module energy_balancer(
    input clk,
    input rst_n,
    input start,
    input [7:0] num_lamps,
    input [7:0] x0, y0,
    input [15:0] e0,
    input [7:0] x1, y1,
    input [15:0] e1,
    input [7:0] x2, y2,
    input [15:0] e2,
    input [7:0] x3, y3,
    input [15:0] e3,
    input [7:0] x4, y4,
    input [15:0] e4,
    input [7:0] x5, y5,
    input [15:0] e5,
    input [7:0] x6, y6,
    input [15:0] e6,
    input [7:0] x7, y7,
    input [15:0] e7,
    input [7:0] x8, y8,
    input [15:0] e8,
    input [7:0] x9, y9,
    input [15:0] e9,
    input [7:0] x10, y10,
    input [15:0] e10,
    input [7:0] x11, y11,
    input [15:0] e11,
    output reg [31:0] result,
    output reg valid,
    output reg impossible
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state, next_state;
    reg [31:0] checksum;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start) begin
                    next_state = COMPUTE;
                end else begin
                    next_state = IDLE;
                end
            end
            COMPUTE: begin
                next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Checksum computation
    always @(*) begin
        checksum = 0;
