    localparam MOD = 1000000007;

    // Helper function for modular exponentiation
    function [63:0] mod_pow;
        input [63:0] base;
        input [63:0] exp;
        reg [63:0] result;
        reg [63:0] b;
        reg [63:0] e;
        integer i;
    begin
        result = 1;
        b = base % MOD;
        e = exp;
        for (i = 0; i < 64; i = i + 1) begin
            if (e == 0) begin
                // break loop early
            end else begin
                if (e[0] == 1)
                    result = (result * b) % MOD;
                b = (b * b) % MOD;
                e = e >> 1;
            end
        end
        mod_pow = result;
    end
