function [63:0] div(input [63:0] a, input [63:0] b);
    reg [127:0] numer;
    reg [63:0] quot;
    integer i;
    begin
        numer = {a, 64'd0}; // Shift left by 64
        quot = 0;
        for (i = 0; i < 64; i = i + 1) begin
            numer = numer << 1;
            if (numer[127:64] >= b) begin
                numer[127:64] = numer[127:64] - b;
                quot[i] = 1;
            end
        end
        div = quot;
    end
endfunction

function [63:0] sqrt(input [63:0] val);
    reg [63:0] guess;
    reg [63:0] prev_guess;
    integer i;
    begin
        guess = val >> 1; // Initial guess
        for (i = 0; i < 16; i = i + 1) begin
            prev_guess = guess;
            guess = (guess + div(val, guess)) >> 1;
            if (guess == prev_guess) begin
                break;
            end
        end
        sqrt = guess;
    end
endfunction

function [63:0] abs_val(input [63:0] val);
    begin
        if (val[63]) begin
            abs_val = -val;
        end else begin
            abs_val = val;
        end
    end
endfunction

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
