                // Search for optimal phi using gradient descent
                if (search_count < MAX_ITER && step_count < MAX_STEPS) begin
                    // Compute spiral position and tangent at phi_current
                    // Simplified: use precomputed values or iterative approximation
                    state <= COMPUTE;
                end else begin
                    state <= FINISH;
                end
            end

            COMPUTE: begin
                // Compute x, y from phi: x = b*phi*cos(phi), y = b*phi*sin(phi)
