    wire [63:0] two_M = M << 1;
    wire [63:0] T_plus_N = T + N_ext;
    wire condition = (two_M <= T_plus_N);
    wire [63:0] part = T - M;
    wire [63:0] two_part = part << 1;
    wire [63:0] else_result = two_part + N_ext;
    wire [63:0] computed_result = condition ? T : else_result;

