    ways_table[4][10] = 80; ways_table[4][11] = 104; ways_table[4][12] = 125;
    ways_table[4][13] = 140; ways_table[4][14] = 146; ways_table[4][15] = 140;
    ways_table[4][16] = 125; ways_table[4][17] = 104; ways_table[4][18] = 80;
    ways_table[4][19] = 56; ways_table[4][20] = 35; ways_table[4][21] = 20;
    ways_table[4][22] = 10; ways_table[4][23] = 4; ways_table[4][24] = 1;
    // R=5: sums 5-30 (only store middle range)
    ways_table[5][15] = 651; ways_table[5][16] = 771; ways_table[5][17] = 901;
    ways_table[5][18] = 1041; ways_table[5][19] = 1191; ways_table[5][20] = 1351;
    // R=6: sums 6-36 (only store middle range)
    ways_table[6][21] = 4332; ways_table[6][22] = 4896; ways_table[6][23] = 5456;
    ways_table[6][24] = 6001; ways_table[6][25] = 6526; ways_table[6][26] = 7021;
    // R=7: sums 7-42 (only store middle range)
    ways_table[7][24] = 14520; ways_table[7][25] = 16275; ways_table[7][26] = 18060;
    ways_table[7][27] = 19835; ways_table[7][28] = 21575; ways_table[7][29] = 23260;
    // R=8: sums 8-48 (only store middle range)
    ways_table[8][27] = 57960; ways_table[8][28] = 63880; ways_table[8][29] = 69760;
    ways_table[8][30] = 75520; ways_table[8][31] = 81080; ways_table[8][32] = 86360;
    // Fill remaining with 0
    for (r = 0; r <= 8; r = r + 1) begin
        for (y = 0; y <= 48; y = y + 1) begin
            if (ways_table[r][y] === 24'bx) ways_table[r][y] = 0;
        end
    end
end

// Internal registers
reg [3:0] state;
reg [3:0] current_K;
reg [7:0] current_T;
reg [23:0] current_dice;
reg [7:0] S;  // Current sum of dice (max 48)
reg [7:0] delta; // T - S
reg [3:0] subset_counter;  // 0 to 2^8 - 1 = 255, but we use 8-bit for 256 states
reg [3:0] best_R;
reg [21:0] best_ways;
reg [21:0] current_ways;
reg [3:0] current_R;
reg [7:0] X;  // Sum of dice in current subset
reg [7:0] Y;  // delta + X
reg [7:0] dice_sum; // Temporary sum for subset
reg [2:0] die_idx;  // Index for dice iteration (0-7)

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        done <= 0;
        result <= 0;
        best_R <= 0;
        best_ways <= 0;
        subset_counter <= 0;
    end else begin
        case (state)
            STATE_IDLE: begin
                done <= 0;
                if (start) begin
                    current_K <= K;
                    current_T <= T;
                    current_dice <= dice_in;
                    state <= STATE_COMPUTE_S;
                    S <= 0;
                    die_idx <= 0;
                end
            end

            STATE_COMPUTE_S: begin
                // Compute sum of all dice
                if (die_idx < current_K) begin
                    // Extract die value (3 bits)
                    S <= S + current_dice[die_idx*3 +: 3];
                    die_idx <= die_idx + 1;
                end else begin
                    delta <= current_T - S;
                    subset_counter <= 0;
                    best_R <= 0;
                    best_ways <= 0;
                    state <= STATE_ITERATE;
                end
            end

            STATE_ITERATE: begin
                // Iterate through all subsets (0 to 2^K - 1)
                if (subset_counter < (1 << current_K)) begin
                    // Reset subset sum and count
                    X <= 0;
                    current_R <= 0;
                    dice_sum <= 0;
                    die_idx <= 0;
                    state <= STATE_UPDATE_BEST;
                end else begin
                    state <= STATE_FIND_RESULT;
                end
            end

            STATE_UPDATE_BEST: begin
                // Compute sum and popcount for current subset
                if (die_idx < current_K) begin
                    if (subset_counter[die_idx]) begin
                        // Include this die in subset
                        X <= X + current_dice[die_idx*3 +: 3];
                        current_R <= current_R + 1;
                    end
                    die_idx <= die_idx + 1;
                end else begin
                    // Done with this subset
                    Y <= delta + X;
                    // Check if Y is valid [current_R, 6*current_R]
                    if (Y >= current_R && Y <= (6 * current_R) && current_R <= current_K) begin
                        current_ways <= ways_table[current_R][Y];
                    end else begin
                        current_ways <= 0;
                    end
                    // Wait one cycle for ROM read
                    state <= STATE_ITERATE;
                    subset_counter <= subset_counter + 1;

                    // Update best (combinational, but we do it in next state)
                    if (current_ways > best_ways || (current_ways == best_ways && current_R < best_R && current_ways != 0)) begin
                        best_ways <= current_ways;
                        best_R <= current_R;
                    end
                end
            end

            STATE_FIND_RESULT: begin
                result <= best_R;
                done <= 1;
                state <= STATE_IDLE;
            end

            default: state <= STATE_IDLE;
        endcase
    end
end

endmodule

