reg [4:0] dp_state, next_dp_state;
reg [4:0] dp_i, dp_j;
reg [7:0] dp_values [15:0];
reg [7:0] temp_val;
reg swap_needed;

// Helper function: compute LIS for array in array_reg[0:array_len-1]
// Uses dp_i and dp_j as indices

// Main FSM next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = START_ORIG_LIS;
        START_ORIG_LIS: next_state = WAIT_ORIG_LIS;
        WAIT_ORIG_LIS: if (dp_done) next_state = LOOP_I;
        LOOP_I: if (i < n) next_state = BUILD_TEMP_INIT; else next_state = SORT_INIT;
        BUILD_TEMP_INIT: next_state = BUILD_TEMP_LOOP;
        BUILD_TEMP_LOOP: if (j >= n) next_state = START_TEMP_LIS; else next_state = BUILD_TEMP_LOOP;
        START_TEMP_LIS: next_state = WAIT_TEMP_LIS;
        WAIT_TEMP_LIS: if (dp_done) next_state = COMPARE_LIS;
        COMPARE_LIS: next_state = INCREMENT_I;
        INCREMENT_I: next_state = LOOP_I;
        SORT_INIT: if (critical_count_reg > 0) next_state = SORT_PASS_LOOP; else next_state = OUTPUT_DONE;
        SORT_PASS_LOOP: if (pass >= critical_count_reg - 1) next_state = OUTPUT_DONE; else next_state = SORT_SWAP_LOOP;
        SORT_SWAP_LOOP: if (idx >= critical_count_reg - 1 - pass) next_state = SORT_NEXT_PASS; else next_state = SORT_SWAP_LOOP;
        SORT_NEXT_PASS: next_state = SORT_PASS_LOOP;
        OUTPUT_DONE: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

// DP FSM next state logic
always @(*) begin
    next_dp_state = dp_state;
    case (dp_state)
        DP_IDLE: if (start_dp) next_dp_state = DP_INIT;
        DP_INIT: next_dp_state = DP_OUTER;
        DP_OUTER: if (dp_i < array_len) next_dp_state = DP_INNER; else next_dp_state = DP_FIND_MAX;
        DP_INNER: if (dp_j < dp_i) next_dp_state = DP_UPDATE; else next_dp_state = DP_NEXT_I;
        DP_UPDATE: next_dp_state = DP_NEXT_J;
        DP_NEXT_J: next_dp_state = DP_INNER;
        DP_NEXT_I: next_dp_state = DP_OUTER;
        DP_FIND_MAX: next_dp_state = DP_DONE;
        DP_DONE: next_dp_state = DP_IDLE;
        default: next_dp_state = DP_IDLE;
    endcase
end

// Sequential logic for main FSM
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        critical_count <= 0;
        start_dp <= 0;
        dp_done <= 0;
        i <= 0;
        j <= 0;
        k <= 0;
        pass <= 0;
        idx <= 0;
        l_orig <= 0;
        l_temp <= 0;
        critical_count_reg <= 0;
    end else begin
        state <= next_state;
        dp_state <= next_dp_state;

        case (state)
            IDLE: begin
                if (start) begin
                    // Copy input array to original_array
                    for (int idx = 0; idx < MAX_N; idx = idx + 1) begin
                        original_array[idx] <= arr[idx];
                    end
                    i <= 0;
                    critical_count_reg <= 0;
                    done <= 0;
                end
            end

            START_ORIG_LIS: begin
                // Set up for original LIS computation
                for (int idx = 0; idx < MAX_N; idx = idx + 1) begin
                    array_reg[idx] <= original_array[idx];
                end
                array_len <= n;
                start_dp <= 1;
            end

            WAIT_ORIG_LIS: begin
                start_dp <= 0;
                if (dp_done) begin
                    l_orig <= lis_result;
                end
            end

            LOOP_I: begin
                // No action, just checking i
            end

            BUILD_TEMP_INIT: begin
                j <= 0;
                k <= 0;
            end

            BUILD_TEMP_LOOP: begin
                if (j < n) begin
                    if (j != i) begin
                        temp_array[k] <= original_array[j];
                        k <= k + 1;
                    end
                    j <= j + 1;
                end
            end

            START_TEMP_LIS: begin
                // Set up for temporary LIS computation
                for (int idx = 0; idx < MAX_N; idx = idx + 1) begin
                    array_reg[idx] <= temp_array[idx];
                end
                array_len <= n - 1;
                start_dp <= 1;
            end

            WAIT_TEMP_LIS: begin
                start_dp <= 0;
                if (dp_done) begin
                    l_temp <= lis_result;
                end
            end

            COMPARE_LIS: begin
                if (l_temp < l_orig) begin
                    critical_array[critical_count_reg] <= original_array[i];
                    critical_count_reg <= critical_count_reg + 1;
                end
            end

            INCREMENT_I: begin
                i <= i + 1;
            end

            SORT_INIT: begin
                critical_count <= critical_count_reg;
                pass <= 0;
            end

            SORT_PASS_LOOP: begin
                if (pass < critical_count_reg - 1) begin
                    idx <= 0;
                end
            end

            SORT_SWAP_LOOP: begin
                if (critical_array[idx] > critical_array[idx + 1]) begin
                    // Swap
                    critical_array[idx] <= critical_array[idx + 1];
                    critical_array[idx + 1] <= critical_array[idx];
                end
                idx <= idx + 1;
            end

            SORT_NEXT_PASS: begin
                pass <= pass + 1;
            end

            OUTPUT_DONE: begin
                done <= 1;
            end
        endcase

        // DP FSM actions
        case (dp_state)
            DP_INIT: begin
                for (int idx = 0; idx < array_len; idx = idx + 1) begin
                    dp_values[idx] <= 1;
                end
                dp_i <= 0;
            end

            DP_OUTER: begin
                if (dp_i < array_len) begin
                    dp_j <= 0;
                end
            end

            DP_INNER: begin
                // No action
            end

            DP_UPDATE: begin
                if (array_reg[dp_j] < array_reg[dp_i]) begin
                    if (dp_values[dp_j] + 1 > dp_values[dp_i]) begin
                        dp_values[dp_i] <= dp_values[dp_j] + 1;
                    end
                end
            end

            DP_NEXT_J: begin
                dp_j <= dp_j + 1;
            end

            DP_NEXT_I: begin
                dp_i <= dp_i + 1;
            end

            DP_FIND_MAX: begin
                // Find maximum in dp_values
                lis_result <= 0;
                for (int idx = 0; idx < array_len; idx = idx + 1) begin
                    if (dp_values[idx] > lis_result) begin
                        lis_result <= dp_values[idx];
                    end
                end
            end

            DP_DONE: begin
                dp_done <= 1;
            end

            DP_IDLE: begin
                dp_done <= 0;
            end
        endcase
    end
end

endmodule

module tree_path #(
    parameter MAX_N = 8,
    parameter DATA_WIDTH = 4,
    parameter PARENT_WIDTH = 3,
    parameter COUNT_WIDTH = 24,
    parameter MOD = 11092019
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    // Labels for nodes 0 to 7
    input wire [DATA_WIDTH-1:0] label_0,
    input wire [DATA_WIDTH-1:0] label_1,
    input wire [DATA_WIDTH-1:0] label_2,
    input wire [DATA_WIDTH-1:0] label_3,
    input wire [DATA_WIDTH-1:0] label_4,
    input wire [DATA_WIDTH-1:0] label_5,
    input wire [DATA_WIDTH-1:0] label_6,
    input wire [DATA_WIDTH-1:0] label_7,
    // Parents for nodes 1 to 7 (parent index < child index)
    input wire [PARENT_WIDTH-1:0] parent_1,
    input wire [PARENT_WIDTH-1:0] parent_2,
    input wire [PARENT_WIDTH-1:0] parent_3,
    input wire [PARENT_WIDTH-1:0] parent_4,
    input wire [PARENT_WIDTH-1:0] parent_5,
    input wire [PARENT_WIDTH-1:0] parent_6,
    input wire [PARENT_WIDTH-1:0] parent_7,
    // Number of valid nodes (1 to 8)
    input wire [3:0] N,
    // Outputs
    output reg [3:0] result_L,
    output reg [COUNT_WIDTH-1:0] result_M,
    output reg done
);

    // State definitions
    localparam IDLE = 0;
    localparam LOAD = 1;
    localparam COMPUTE_ANC = 2;
    localparam COMPUTE_DP_OUTER = 3;
    localparam COMPUTE_DP_INNER = 4;
    localparam COMPUTE_DP_UPDATE = 5;
    localparam FIND_MAX = 6;
    localparam DONE = 7;

    reg [2:0] state, next_state;

    // Internal storage
    reg [DATA_WIDTH-1:0] labels [0:MAX_N-1];
    reg [PARENT_WIDTH-1:0] parents [0:MAX_N-1];
    reg [MAX_N-1:0] anc [0:MAX_N-1]; // ancestry bit masks
    reg [DATA_WIDTH-1:0] dp_len [0:MAX_N-1];
    reg [COUNT_WIDTH-1:0] dp_cnt [0:MAX_N-1];

    // Counters and temporaries
    reg [3:0] i_reg, j_reg;
    reg [DATA_WIDTH-1:0] best_len_temp;
    reg [COUNT_WIDTH-1:0] best_cnt_temp;
    reg [DATA_WIDTH-1:0] global_max_len;
    reg [COUNT_WIDTH-1:0] global_total_cnt;

    // Helper: modulo addition
    function [COUNT_WIDTH-1:0] mod_add;
        input [COUNT_WIDTH-1:0] a, b;
        begin
            mod_add = a + b;
            if (mod_add >= MOD) mod_add = mod_add - MOD;
        end
    endfunction

    // Sequential state transition and outputs
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result_L <= 0;
            result_M <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= LOAD;
                    end
                end

                LOAD: begin
                    // Load labels and parents
                    labels[0] <= label_0;
                    labels[1] <= label_1;
                    labels[2] <= label_2;
                    labels[3] <= label_3;
                    labels[4] <= label_4;
                    labels[5] <= label_5;
                    labels[6] <= label_6;
                    labels[7] <= label_7;
                    parents[0] <= 0; // root has no parent
                    parents[1] <= parent_1;
                    parents[2] <= parent_2;
                    parents[3] <= parent_3;
                    parents[4] <= parent_4;
                    parents[5] <= parent_5;
                    parents[6] <= parent_6;
                    parents[7] <= parent_7;
                    // Initialize counters
                    i_reg <= 0;
                    j_reg <= 0;
                    best_len_temp <= 0;
                    best_cnt_temp <= 0;
                    global_max_len <= 0;
                    global_total_cnt <= 0;
                    // Initialize anc and dp arrays (optional, as we will write them)
                    state <= COMPUTE_ANC;
                end

                COMPUTE_ANC: begin
                    // Compute anc[i] for current i_reg
                    if (i_reg < N) begin
                        if (i_reg == 0) begin
                            anc[i_reg] <= (1 << i_reg);
                        end else begin
                            // anc[i] = anc[parent] | (1<<i)
                            anc[i_reg] <= anc[parents[i_reg]] | (1 << i_reg);
                        end
                        i_reg <= i_reg + 1;
                    end else begin
                        // Done with anc computation
                        i_reg <= 0;
                        state <= COMPUTE_DP_OUTER;
                    end
                end

                COMPUTE_DP_OUTER: begin
                    // Initialize for current node i_reg
                    if (i_reg < N) begin
                        best_len_temp <= 0;
                        best_cnt_temp <= 0;
                        j_reg <= 0;
                        state <= COMPUTE_DP_INNER;
                    end else begin
                        // Done with DP computation, move to find max
                        i_reg <= 0;
                        state <= FIND_MAX;
                    end
                end

                COMPUTE_DP_INNER: begin
                    // Check ancestor j for current i_reg
                    if (j_reg < i_reg) begin
                        // Check if j is ancestor of i and label[j] <= label[i]
                        if (anc[i_reg][j_reg] && (labels[j_reg] <= labels[i_reg])) begin
                            // Compare dp_len[j] with best_len_temp
                            if (dp_len[j_reg] > best_len_temp) begin
                                best_len_temp <= dp_len[j_reg];
                                best_cnt_temp <= dp_cnt[j_reg];
                            end else if (dp_len[j_reg] == best_len_temp) begin
                                best_cnt_temp <= mod_add(best_cnt_temp, dp_cnt[j_reg]);
                            end
                        end
                        j_reg <= j_reg + 1;
                    end else begin
                        // No more j, set dp_len and dp_cnt for i_reg
                        if (best_len_temp == 0) begin
                            dp_len[i_reg] <= 1;
                            dp_cnt[i_reg] <= 1;
                        end else begin
                            dp_len[i_reg] <= best_len_temp + 1;
                            dp_cnt[i_reg] <= best_cnt_temp;
                        end
                        // Move to next i
                        i_reg <= i_reg + 1;
                        state <= COMPUTE_DP_OUTER;
                    end
                end

                FIND_MAX: begin
                    if (i_reg < N) begin
                        if (dp_len[i_reg] > global_max_len) begin
                            global_max_len <= dp_len[i_reg];
                            global_total_cnt <= dp_cnt[i_reg];
                        end else if (dp_len[i_reg] == global_max_len) begin
                            global_total_cnt <= mod_add(global_total_cnt, dp_cnt[i_reg]);
                        end
                        i_reg <= i_reg + 1;
                    end else begin
                        // Done, set outputs
                        result_L <= global_max_len;
                        result_M <= global_total_cnt;
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

Create a Verilog module that implements cake cutting verification.

module cake_divider #(
    parameter N = 8,
    parameter M = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire signed [15:0] x_candles [0:N-1],
    input wire signed [15:0] y_candles [0:N-1],
    input wire signed [31:0] a_lines [0:M-1],
    input wire signed [31:0] b_lines [0:M-1],
    input wire signed [31:0] c_lines [0:M-1],
    input wire [7:0] n,
    input wire [7:0] m,
    input wire signed [15:0] r,
    output reg done,
    output reg result
);

// State definitions
localparam IDLE = 0;
localparam INIT_PAIR = 1;
localparam COMPUTE_DET = 2;
localparam CHECK_DET = 3;
localparam COMPUTE_DXDY = 4;
localparam SQUARE = 5;
localparam COMPARE = 6;
localparam NEXT_PAIR = 7;
localparam CHECK_F = 8;
localparam COMPARE_F = 9;
localparam INIT_SIG = 10;
localparam COMPUTE_SIG = 11;
localparam NEXT_CANDLE = 12;
localparam CHECK_DUP = 13;
localparam DONE = 14;

reg [4:0] state;
reg [3:0] i, j;
reg [3:0] k;
reg [3:0] l;
reg signed [63:0] det;
reg signed [63:0] dx, dy;
reg signed [63:0] lhs, rhs;
reg [3:0] I;
reg [7:0] F;
reg [M-1:0] signatures [0:N-1];
reg [M-1:0] current_sig;
reg duplicate_found;

wire duplicate_found_wire;
assign duplicate_found_wire = 0;

always @(*) begin
    duplicate_found_wire = 0;
    for (integer idx_i = 0; idx_i < N; idx_i = idx_i + 1) begin
        for (integer idx_j = idx_i+1; idx_j < N; idx_j = idx_j + 1) begin
            if (idx_i < n && idx_j < n && signatures[idx_i] == signatures[idx_j]) begin
                duplicate_found_wire = 1;
            end
        end
    end
end

wire signed [63:0] val_current;
assign val_current = $signed(a_lines[l]) * $signed(x_candles[k]) + $signed(b_lines[l]) * $signed(y_candles[k]) + $signed(c_lines[l]);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        I <= 0;
        F <= 0;
        i <= 0;
        j <= 0;
        k <= 0;
        l <= 0;
        duplicate_found <= 0;
        for (integer idx = 0; idx < N; idx = idx + 1) begin
            signatures[idx] <= 0;
        end
        current_sig <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT_PAIR;
                    I <= 0;
                    i <= 0;
                    j <= 1;
                end
            end
            INIT_PAIR: begin
                a_i <= a_lines[i];
                b_i <= b_lines[i];
                c_i <= c_lines[i];
                a_j <= a_lines[j];
                b_j <= b_lines[j];
                c_j <= c_lines[j];
                state <= COMPUTE_DET;
            end
            COMPUTE_DET: begin
                det <= a_i * b_j - a_j * b_i;
                state <= CHECK_DET;
            end
            CHECK_DET: begin
                if (det == 0) begin
                    state <= NEXT_PAIR;
                end else begin
                    state <= COMPUTE_DXDY;
                end
            end
            COMPUTE_DXDY: begin
                dx <= b_i * c_j - b_j * c_i;
                dy <= c_i * a_j - c_j * a_i;
                state <= SQUARE;
            end
            SQUARE: begin
                lhs <= dx * dx + dy * dy;
                rhs <= (r * r) * (det * det);
                state <= COMPARE;
            end
            COMPARE: begin
                if (lhs < rhs) begin
                    I <= I + 1;
                end
                state <= NEXT_PAIR;
            end
            NEXT_PAIR: begin
                if (j < M - 1) begin
                    j <= j + 1;
                    state <= INIT_PAIR;
                end else begin
                    j <= i + 2;
                    if (i < M - 2) begin
                        i <= i + 1;
                        state <= INIT_PAIR;
                    end else begin
                        state <= CHECK_F;
                    end
                end
            end
            CHECK_F: begin
                F <= 1 + m + I;
                state <= COMPARE_F;
            end
            COMPARE_F: begin
                if (F != n) begin
                    result <= 0;
                    state <= DONE;
                end else begin
                    k <= 0;
                    state <= INIT_SIG;
                end
            end
            INIT_SIG: begin
                current_sig <= 0;
                l <= 0;
                state <= COMPUTE_SIG;
            end
            COMPUTE_SIG: begin
                if (val_current > 0) begin
                    current_sig[l] <= 1;
                end else begin
                    current_sig[l] <= 0;
                end
                if (l < m - 1) begin
                    l <= l + 1;
                    state <= COMPUTE_SIG;
                end else begin
                    state <= NEXT_CANDLE;
                end
            end
            NEXT_CANDLE: begin
                signatures[k] <= current_sig;
                k <= k + 1;
                if (k < n - 1) begin
                    state <= INIT_SIG;
                end else begin
                    state <= CHECK_DUP;
                end
            end
            CHECK_DUP: begin
                duplicate_found <= duplicate_found_wire;
                state <= DONE;
            end
            DONE: begin
                done <= 1;
                if (duplicate_found) begin
                    result <= 0;
                end else begin
                    result <= 1;
                end
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

