            eq = 0;
        end else begin
            for (i = 0; i < (MAX_LEN/2); i = i + 1) begin
                if (i < left_len) begin
                    if (left_seg[i] != right_seg[left_len-1-i]) begin
                        eq = 0;
                    end
                end
            end
        end
    end

