    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset
            state <= S_IDLE;
            done <= 0;
            result <= 0;
            // Reset other registers if needed
            left_len <= 0;
            right_len <= 0;
            k <= 0;
            l <= 0;
            r <= 0;
