            state <= next_state;

            case (state)
                S_IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Capture input string and length
                        str_reg <= str;
                        len_reg <= len;
                        // Initialize counters
                        l <= 0;
                        r <= len - 1;
                        left_len <= 0;
                        right_len <= 0;
                        k <= 0;
