                    if (eq) begin
                        k <= k + 2;
                        left_len <= 0;
                        right_len <= 0;
                    end
                    // Note: If not equal, do nothing
                end

                S_NEXT_ITER: begin
                    l <= l + 1;
                    r <= r - 1;
