        for (i = 1; i < 6; i = i + 1) begin
            if (row_addr[i] < min_row) min_row = row_addr[i];
            if (col_addr[i] < min_col) min_col = col_addr[i];
        end
        for (i = 0; i < 6; i = i + 1) begin
