        can_fold = 0;
        if (count != 6) begin // Should never happen per problem statement
            can_fold = 0;
            return;
        end

        for (t = 0; t < 8; t = t + 1) begin
            // Apply transformation t
            for (i = 0; i < 6; i = i + 1) begin
                case (t)
