                    // Initialize
                    valid_len <= (len > 16) ? 16 : len;
                    L <= (len > 16) ? 16 : len;
                    i <= 0;
                    j <= 0;
                    k <= 0;
                    found_repeated <= 0;
                    best_len <= 0;
                    done <= 0;
                    state <= CHECK_L;
                end else if (start && len <= 1) begin
