                    state <= COMPARE;
                end else if (best_len == 0) begin
                    // No repeated substring found (shouldn't happen per problem constraints)
                    // Output single character (first char)
                    for (m = 0; m < 16; m = m + 1) begin
                        result[m] <= (m == 0) ? arr[0] : 8'h00;
                    end
                    out_len <= 1;
                    done <= 1;
                    state <= FINISHED;
                end else begin
                    // Output best substring found
                    for (m = 0; m < 16; m = m + 1) begin
                        result[m] <= (m < best_len) ? best_substring[m] : 8'h00;
                    end
                    out_len <= best_len;
                    done <= 1;
                    state <= FINISHED;
                end
            end

            COMPARE: begin
                // Compare characters at positions i+k and j+k
                if (k < L && i + k < valid_len && j + k < valid_len) begin
                    temp_char1 <= arr[i + k];
                    temp_char2 <= arr[j + k];
                    k <= k + 1;
                    state <= COMPARE; // stay to complete comparison
                end else if (k == L) begin
                    // Complete comparison - check if all matched
                    if (temp_char1 == temp_char2 && found_repeated == 0) begin
                        // Need to compare again for full L characters
                        k <= 0;
                        state <= COMPARE; // restart comparison for full check
                    end else if (temp_char1 == temp_char2 && found_repeated == 1) begin
                        // Already found repetition for this L, update best if needed
                        state <= UPDATE_BEST;
                    end else begin
                        // Mismatch
                        state <= NEXT_J;
                    end
                end else begin
                    // Partial match, continue or finish
                    if (k == L) begin
                        if (found_repeated) begin
                            state <= UPDATE_BEST;
                        end else begin
                            state <= NEXT_J;
                        end
                    end else begin
                        state <= NEXT_J; // partial string, not enough characters
                    end
                end
            end

            NEXT_J: begin
                // Move to next j
                if (j + 1 < valid_len - L + 1 && i + L <= valid_len && j + L <= valid_len) begin
                    j <= j + 1;
                    k <= 0;
                    state <= COMPARE;
                end else begin
                    // Move to next i
                    state <= NEXT_I;
                end
            end

            NEXT_I: begin
                // Move to next i
                if (i + 1 < valid_len - L + 1) begin
                    i <= i + 1;
                    j <= i + 2;
                    k <= 0;
                    state <= COMPARE;
                end else begin
                    // Move to next L
                    L <= L - 1;
                    state <= CHECK_L;
                end
            end

            UPDATE_BEST: begin
                // Check if this substring is better than current best
                if (L > best_len || (L == best_len && substring_smaller(i, L))) begin
                    // Update best substring
                    best_len <= L;
                    for (m = 0; m < 16; m = m + 1) begin
                        if (m < L) begin
                            best_substring[m] <= arr[i + m];
                        end else begin
                            best_substring[m] <= 8'h00;
                        end
                    end
                end
                found_repeated <= 1;
                state <= NEXT_J;
            end

            FINISHED: begin
                // Stay done
                done <= 1;
            end

            default: begin
                state <= IDLE;
            end
        endcase
    end
end

// Helper function to compare current substring with best lexicographically
function automatic integer substring_smaller;
    input [4:0] start_idx;
    input [4:0] length;
    integer idx;
    begin
        substring_smaller = 0;
        for (idx = 0; idx < length; idx = idx + 1) begin
            if (arr[start_idx + idx] < best_substring[idx]) begin
                substring_smaller = 1;
                break;
            end else if (arr[start_idx + idx] > best_substring[idx]) begin
                break;
            end
        end
    end
endfunction

endmodule

// ============================================================================
// BOLT PACK FINDER MODULE
// ============================================================================
//
// Problem: Find smallest advertised pack size that guarantees at least B bolts
//          in a chain of repackaging companies.
//
// Hardware Adaptation:
// - Scaled constraints: B <= 255, companies <= 4, packs per company <= 4
// - Pack sizes <= 255 (8-bit)
// - Sequential implementation with state machine and DP
//
// Algorithm:
// 1. Manufacturer (company 0): real_amount = advertised_amount
// 2. For each subsequent company i > 0:
//    a. For each pack size X in company i:
//       i. Find minimal sum S >= X using packs from company i-1 (unbounded knapsack)
//       ii. Real amount = minimal real sum for sum S (worst case for buyer)
// 3. Find minimal pack size across all companies where real_amount >= B
//
// Interface:
//  Inputs:
//    clk, rst_n, start
//    B [7:0] - required bolts
//    k [3:0] - number of companies
//    pack_sizes [15:0][7:0] - flattened array of pack sizes
//    num_packs [3:0] - valid packs per company
//  Outputs:
//    result [7:0] - minimal pack size
//    done - computation complete
//    impossible - no valid pack found
// ============================================================================

module bolt_pack_finder #(
    parameter MAX_COMPANIES = 4,
    parameter MAX_PACKS = 4,
    parameter MAX_SUM = 1024,
    parameter DATA_WIDTH = 8,
    parameter TIMEOUT_CYCLES = 5000
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] B,
    input wire [3:0] k,
    input wire [DATA_WIDTH-1:0] pack_sizes [0:MAX_COMPANIES*MAX_PACKS-1],
    input wire [3:0] num_packs [0:MAX_COMPANIES-1],
    output reg [DATA_WIDTH-1:0] result,
    output reg done,
    output reg impossible
);

    // State definitions
    localparam IDLE = 4'd0;
    localparam INIT_REAL = 4'd1;
    localparam SETUP_DP = 4'd2;
    localparam DP_INNER_LOOP = 4'd3;
    localparam DP_UPDATE = 4'd4;
    localparam FIND_MIN_SUM = 4'd5;
    localparam STORE_RESULT = 4'd6;
    localparam NEXT_PACK = 4'd7;
    localparam NEXT_COMPANY = 4'd8;
    localparam FIND_BEST = 4'd9;
    localparam FINISHED = 4'd10;

    reg [3:0] state;
    reg [3:0] company_idx;
    reg [3:0] pack_idx;
    reg [DATA_WIDTH-1:0] sum_idx;
    reg [15:0] timeout;

    // DP array: dp[s] = minimal real sum to achieve advertised sum s
    reg [DATA_WIDTH-1:0] dp [0:MAX_SUM-1];

    // Real amounts storage
    reg [DATA_WIDTH-1:0] real_amounts [0:MAX_COMPANIES*MAX_PACKS-1];

    // Previous company's packs for DP
    reg [DATA_WIDTH-1:0] prev_adv [0:MAX_PACKS-1];
    reg [DATA_WIDTH-1:0] prev_real [0:MAX_PACKS-1];
    reg [3:0] prev_num_packs;
    reg [3:0] prev_pack_idx;

    // Current computation
    reg [DATA_WIDTH-1:0] current_real;
    reg [DATA_WIDTH-1:0] min_sum;

    // Result tracking
    reg [DATA_WIDTH-1:0] best_pack;
    reg best_found;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            company_idx <= 0;
            pack_idx <= 0;
            sum_idx <= 0;
            timeout <= 0;
            done <= 0;
            impossible <= 0;
            result <= 0;
            best_pack <= 8'hFF;
            best_found <= 0;
        end else begin
            case (state)
                IDLE: if (start) begin
                    state <= INIT_REAL;
                    company_idx <= 0;
                    pack_idx <= 0;
                end

                INIT_REAL: begin
                    if (pack_idx < num_packs[0]) begin
                        real_amounts[pack_idx] <= pack_sizes[pack_idx];
                        pack_idx <= pack_idx + 1;
                    end else begin
                        pack_idx <= 0;
                        company_idx <= 1;
                        state <= (k > 1) ? SETUP_DP : FIND_BEST;
                    end
                end

                SETUP_DP: begin
                    if (pack_idx < num_packs[company_idx - 1]) begin
                        prev_adv[pack_idx] <= pack_sizes[(company_idx - 1) * MAX_PACKS + pack_idx];
                        prev_real[pack_idx] <= real_amounts[(company_idx - 1) * MAX_PACKS + pack_idx];
                        pack_idx <= pack_idx + 1;
                    end else begin
                        prev_num_packs <= num_packs[company_idx - 1];
                        pack_idx <= 0;
                        prev_pack_idx <= 0;
                        // Initialize DP
                        dp[0] <= 0;
                        for (int i = 1; i < MAX_SUM; i++) dp[i] <= 8'hFF;
                        state <= DP_INNER_LOOP;
                    end
                end

                DP_INNER_LOOP: begin
                    if (prev_pack_idx < prev_num_packs) begin
                        sum_idx <= prev_adv[prev_pack_idx];
                        state <= DP_UPDATE;
                    end else begin
                        prev_pack_idx <= 0;
                        sum_idx <= 0;
                        state <= FIND_MIN_SUM;
                    end
                end

                DP_UPDATE: begin
                    if (sum_idx < MAX_SUM) begin
                        if (dp[sum_idx - prev_adv[prev_pack_idx]] != 8'hFF) begin
                            dp[sum_idx] <= (dp[sum_idx] < dp[sum_idx - prev_adv[prev_pack_idx]] + prev_real[prev_pack_idx]) ? 
                                           dp[sum_idx] : dp[sum_idx - prev_adv[prev_pack_idx]] + prev_real[prev_pack_idx];
                        end
                        sum_idx <= sum_idx + 1;
                    end else begin
                        prev_pack_idx <= prev_pack_idx + 1;
                        state <= DP_INNER_LOOP;
                    end
                end

                FIND_MIN_SUM: begin
                    if (sum_idx < MAX_SUM) begin
                        if (sum_idx >= pack_sizes[company_idx * MAX_PACKS + pack_idx] && dp[sum_idx] != 8'hFF) begin
                            min_sum <= sum_idx;
                            current_real <= dp[sum_idx];
                            state <= STORE_RESULT;
                        end else begin
                            sum_idx <= sum_idx + 1;
                        end
                    end else begin
                        current_real <= 8'hFF;
                        state <= STORE_RESULT;
                    end
                end

                STORE_RESULT: begin
                    real_amounts[company_idx * MAX_PACKS + pack_idx] <= current_real;
                    state <= NEXT_PACK;
                end

                NEXT_PACK: begin
                    pack_idx <= pack_idx + 1;
                    if (pack_idx + 1 < num_packs[company_idx]) state <= SETUP_DP;
                    else begin
                        pack_idx <= 0;
                        state <= NEXT_COMPANY;
                    end
                end

                NEXT_COMPANY: begin
                    company_idx <= company_idx + 1;
                    if (company_idx < k - 1) state <= SETUP_DP;
                    else state <= FIND_BEST;
                end

                FIND_BEST: begin
                    if (company_idx < k) begin
                        if (pack_idx < num_packs[company_idx]) begin
                            if (real_amounts[company_idx * MAX_PACKS + pack_idx] >= B) begin
                                if (!best_found || pack_sizes[company_idx * MAX_PACKS + pack_idx] < best_pack) begin
                                    best_pack <= pack_sizes[company_idx * MAX_PACKS + pack_idx];
                                    best_found <= 1;
                                end
                            end
                            pack_idx <= pack_idx + 1;
                        end else begin
                            pack_idx <= 0;
                            company_idx <= company_idx + 1;
                        end
                    end else begin
                        if (best_found) begin
                            result <= best_pack;
                            impossible <= 0;
                        end else begin
                            result <= 0;
                            impossible <= 1;
                        end
                        done <= 1;
                        state <= FINISHED;
                    end
                end

                FINISHED: if (!start) begin end

                default: state <= IDLE;
            endcase

            // Timeout
            if (state != IDLE && state != FINISHED) begin
                if (timeout >= TIMEOUT_CYCLES) begin
                    impossible <= 1;
                    done <= 1;
                    state <= FINISHED;
                end else timeout <= timeout + 1;
            end else timeout <= 0;
        end
    end
endmodule

module mps_system (
    input clk,
    input rst_n,
    input start,
    input [1:0] num_beacons,
    // Beacon 0
    input signed [7:0] beacon0_x,
    input signed [7:0] beacon0_y,
    input [13:0] beacon0_d,
    // Beacon 1
    input signed [7:0] beacon1_x,
    input signed [7:0] beacon1_y,
    input [13:0] beacon1_d,
    // Beacon 2
    input signed [7:0] beacon2_x,
    input signed [7:0] beacon2_y,
    input [13:0] beacon2_d,
    // Beacon 3
    input signed [7:0] beacon3_x,
    input signed [7:0] beacon3_y,
    input [13:0] beacon3_d,
    output reg [3:0] result_x,
    output reg [3:0] result_y,
    output reg done,
    output reg impossible,
    output reg uncertain
);

// Parameters
parameter GRID_MIN = 0;
parameter GRID_MAX = 7;
parameter MAX_BEACONS = 4;
parameter CLK_TIMEOUT = 1000;

// Internal signals
reg [3:0] candidate_x, candidate_y;
reg [2:0] beacon_idx;
reg [2:0] solution_count;
reg [3:0] first_x, first_y;
reg searching;

// Beacon storage
wire signed [7:0] beacon_x [0:3];
wire signed [7:0] beacon_y [0:3];
wire [13:0] beacon_d [0:3];

assign beacon_x[0] = beacon0_x;
assign beacon_y[0] = beacon0_y;
assign beacon_d[0] = beacon0_d;
assign beacon_x[1] = beacon1_x;
assign beacon_y[1] = beacon1_y;
assign beacon_d[1] = beacon1_d;
assign beacon_x[2] = beacon2_x;
assign beacon_y[2] = beacon2_y;
assign beacon_d[2] = beacon2_d;
assign beacon_x[3] = beacon3_x;
assign beacon_y[3] = beacon3_y;
assign beacon_d[3] = beacon3_d;

// Manhattan distance calculation
wire signed [8:0] dx = candidate_x - beacon_x[beacon_idx];
wire signed [8:0] dy = candidate_y - beacon_y[beacon_idx];
wire signed [8:0] abs_dx = dx[8] ? -dx : dx;
wire signed [8:0] abs_dy = dy[8] ? -dy : dy;
wire [13:0] calc_dist = abs_dx + abs_dy;

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        result_x <= 0;
        result_y <= 0;
        done <= 0;
        impossible <= 0;
        uncertain <= 0;
        candidate_x <= GRID_MIN;
        candidate_y <= GRID_MIN;
        beacon_idx <= 0;
        solution_count <= 0;
        first_x <= 0;
        first_y <= 0;
        searching <= 0;
    end else begin
        if (start && !searching) begin
            // Initialize search
            candidate_x <= GRID_MIN;
            candidate_y <= GRID_MIN;
            beacon_idx <= 0;
            solution_count <= 0;
            first_x <= 0;
            first_y <= 0;
            searching <= 1;
            done <= 0;
            impossible <= 0;
            uncertain <= 0;
        end else if (searching) begin
            if (beacon_idx < num_beacons) begin
                // Check current beacon for current candidate
                if (calc_dist == beacon_d[beacon_idx]) begin
                    // Beacon matches, check next beacon
                    beacon_idx <= beacon_idx + 1;
                end else begin
                    // This candidate doesn't match, move to next candidate
                    beacon_idx <= 0;
                    if (candidate_x == GRID_MAX) begin
                        candidate_x <= GRID_MIN;
                        if (candidate_y == GRID_MAX) begin
                            // Finished all candidates
                            searching <= 0;
                            done <= 1;
                            if (solution_count == 0) begin
                                impossible <= 1;
                            end else if (solution_count > 1) begin
                                uncertain <= 1;
                            end else begin
                                result_x <= first_x;
                                result_y <= first_y;
                            end
                        end else begin
                            candidate_y <= candidate_y + 1;
                        end
                    end else begin
                        candidate_x <= candidate_x + 1;
                    end
                end
            end else begin
                // All beacons matched for this candidate
                solution_count <= solution_count + 1;
                if (solution_count == 0) begin
                    first_x <= candidate_x;
                    first_y <= candidate_y;
                end
                beacon_idx <= 0;
                // Move to next candidate
                if (candidate_x == GRID_MAX) begin
                    candidate_x <= GRID_MIN;
                    if (candidate_y == GRID_MAX) begin
                        // Finished all candidates
                        searching <= 0;
                        done <= 1;
                        if (solution_count == 0) begin
                            // Shouldn't happen (solution_count becomes 1 before this)
                            impossible <= 1;
                        end else if (solution_count >= 1) begin
                            // solution_count was incremented, so >=2 solutions
                            uncertain <= 1;
                        end
                    end else begin
                        candidate_y <= candidate_y + 1;
                    end
                end else begin
                    candidate_x <= candidate_x + 1;
                end
            end
        end
    end
end

endmodule

module rectangle_matcher #(
    parameter N = 8,
    parameter DATA_WIDTH = 16,
    parameter IDX_WIDTH = 4
) (
    input clk, rst_n, start,
    input [DATA_WIDTH-1:0] tl_r [0:N-1],
    input [DATA_WIDTH-1:0] tl_c [0:N-1],
    input [DATA_WIDTH-1:0] br_r [0:N-1],
    input [DATA_WIDTH-1:0] br_c [0:N-1],
    output reg [IDX_WIDTH-1:0] match [0:N-1],
    output reg done,
    output reg error
);

// Define states
localparam IDLE = 0, LOAD = 1, SORT = 2, PROCESS = 3, DONE = 4, ERROR = 5;
reg [2:0] state;

// Define point structure: {r, c, type, idx}
localparam POINT_WIDTH = 2*DATA_WIDTH + 1 + IDX_WIDTH;
reg [POINT_WIDTH-1:0] points [0:2*N-1];

// Stack
reg [IDX_WIDTH-1:0] stack [0:N-1];
reg [IDX_WIDTH-1:0] sp;

// Counters
reg [3:0] load_count;
reg [3:0] i_count;
reg [3:0] j_count;
reg [3:0] idx_proc;

// Helper macros
`define POINT_R(p) p[POINT_WIDTH-1 : POINT_WIDTH-DATA_WIDTH]
`define POINT_C(p) p[POINT_WIDTH-DATA_WIDTH-1 : POINT_WIDTH-2*DATA_WIDTH]
`define POINT_TYPE(p) p[POINT_WIDTH-2*DATA_WIDTH-1]
`define POINT_IDX(p) p[POINT_WIDTH-2*DATA_WIDTH-2 : 0]

// Comparator for bubble sort
wire sort_greater;
assign sort_greater = (`POINT_R(points[j_count]) > `POINT_R(points[j_count+1])) ||
                      (`POINT_R(points[j_count]) == `POINT_R(points[j_count+1]) && `POINT_C(points[j_count]) > `POINT_C(points[j_count+1])) ||
                      (`POINT_R(points[j_count]) == `POINT_R(points[j_count+1]) && `POINT_C(points[j_count]) == `POINT_C(points[j_count+1]) && `POINT_TYPE(points[j_count]) > `POINT_TYPE(points[j_count+1])) ||
                      (`POINT_R(points[j_count]) == `POINT_R(points[j_count+1]) && `POINT_C(points[j_count]) == `POINT_C(points[j_count+1]) && `POINT_TYPE(points[j_count]) == `POINT_TYPE(points[j_count+1]) && `POINT_IDX(points[j_count]) > `POINT_IDX(points[j_count+1]));

// Current point fields
wire [DATA_WIDTH-1:0] current_r = `POINT_R(points[idx_proc]);
wire [DATA_WIDTH-1:0] current_c = `POINT_C(points[idx_proc]);
wire current_type = `POINT_TYPE(points[idx_proc]);
wire [IDX_WIDTH-1:0] current_idx = `POINT_IDX(points[idx_proc]);

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        error <= 0;
        match <= '{default:0};
        points <= '{default:0};
        stack <= '{default:0};
        sp <= 0;
        load_count <= 0;
        i_count <= 0;
        j_count <= 0;
        idx_proc <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= LOAD;
                    load_count <= 0;
                    done <= 0;
                    error <= 0;
                end
            end
            LOAD: begin
                if (load_count < 2*N) begin
                    if (load_count < N) begin
                        points[load_count] <= {tl_r[load_count], tl_c[load_count], 1'b0, load_count[IDX_WIDTH-1:0]};
                    end else begin
                        points[load_count] <= {br_r[load_count-N], br_c[load_count-N], 1'b1, (load_count-N)[IDX_WIDTH-1:0]};
                    end
                    load_count <= load_count + 1;
                end else begin
                    state <= SORT;
                    i_count <= 0;
                    j_count <= 0;
                end
            end
            SORT: begin
                if (i_count < 2*N-1) begin
                    if (j_count < 2*N-1 - i_count) begin
                        if (sort_greater) begin
                            points[j_count] <= points[j_count+1];
                            points[j_count+1] <= points[j_count];
                        end
                        j_count <= j_count + 1;
                    end else begin
                        j_count <= 0;
                        i_count <= i_count + 1;
                    end
                end else begin
                    state <= PROCESS;
                    idx_proc <= 0;
                    sp <= 0;
                end
            end
            PROCESS: begin
                if (idx_proc < 2*N) begin
                    if (current_type == 0) begin
                        stack[sp] <= current_idx;
                        sp <= sp + 1;
                    end else begin
                        if (sp == 0) begin
                            error <= 1;
                            state <= ERROR;
                        end else begin
                            sp <= sp - 1;
                            if (tl_r[stack[sp-1]] >= br_r[current_idx] || tl_c[stack[sp-1]] >= br_c[current_idx]) begin
                                error <= 1;
                                state <= ERROR;
                            end else begin
                                match[stack[sp-1]] <= current_idx + 1;
                            end
                        end
                    end
                    idx_proc <= idx_proc + 1;
                end else begin
                    if (sp != 0) begin
                        error <= 1;
                        state <= ERROR;
                    end else begin
                        state <= DONE;
                        done <= 1;
                    end
                end
            end
            DONE, ERROR: begin
                // stay here
            end
        endcase
    end
end

endmodule

module robot_fixer #(
    parameter H = 4,
    parameter W = 4,
    parameter MAX_CMDS = 8,
    parameter CMD_BITS = 2,
    parameter CHANGES_BITS = 4
)(
    input clk,
    input rst_n,
    input start,

    // Grid: H*W bits, row-major, 1=obstacle
    input [H*W-1:0] grid,

    // Start and goal positions (2 bits each for 4x4 grid)
    input [1:0] start_x,
    input [1:0] start_y,
    input [1:0] goal_x,
    input [1:0] goal_y,

    // Command string: MAX_CMDS * CMD_BITS (L=00, R=01, U=10, D=11)
    input [MAX_CMDS*CMD_BITS-1:0] commands,
    input [3:0] cmd_len,  // 1-MAX_CMDS

    output reg [CHANGES_BITS-1:0] min_changes,
    output reg done,
    output reg valid
);

// State machine definitions
reg [2:0] state;
localparam S_IDLE = 3'b000,
           S_RESET_COST = 3'b001,
           S_INIT = 3'b010,
           S_PROCESS = 3'b011,
           S_EXPLORE = 3'b100,
           S_UPDATE = 3'b101,
           S_DONE = 3'b110;

// Cost table: stores min edits for each state (x,y,cmd_idx)
// 4x4x8 = 256 states, 4 bits each
reg [CHANGES_BITS-1:0] cost_table [0:255];
reg [7:0] reset_idx;  // For initialization

// BFS queue: stores {x,y,cmd_idx} packed as 8 bits
declare reg [7:0] queue [0:31];
reg [5:0] q_head, q_tail;
reg queue_empty;

// Current state being processed
reg [7:0] current_state;
reg [CHANGES_BITS-1:0] current_cost;

// Operation type during exploration
reg [1:0] op_type;  // 0=execute, 1=delete, 2=insert

// Next state and cost calculations
reg [7:0] next_state;
reg [CHANGES_BITS-1:0] next_cost;

// Helper: extract fields from current state
wire [1:0] curr_x = current_state[7:6];
wire [1:0] curr_y = current_state[5:4];
wire [3:0] curr_cmd_idx = current_state[3:0];

// Helper: check if position is valid
wire is_valid_pos = (curr_x < W) && (curr_y < H) && 
                    !grid[curr_y * W + curr_x];

// Helper: check if goal reached
wire is_goal = (curr_x == goal_x) && (curr_y == goal_y);

// Helper: check if more commands available
wire has_more_cmds = (curr_cmd_idx < cmd_len);

// Helper: get current command
wire [1:0] current_cmd = commands[curr_cmd_idx * CMD_BITS +: CMD_BITS];

// Combinational: calculate next position for execute operation
always @(*) begin
    reg [1:0] new_x, new_y;
    new_x = curr_x;
    new_y = curr_y;

    if (has_more_cmds) begin
        case (current_cmd)
            2'b00: if (curr_x > 0) new_x = curr_x - 1;      // L
            2'b01: if (curr_x < W-1) new_x = curr_x + 1;    // R
            2'b10: if (curr_y > 0) new_y = curr_y - 1;      // U
            2'b11: if (curr_y < H-1) new_y = curr_y + 1;    // D
        endcase

        // Check obstacle collision
        if (grid[new_y * W + new_x]) begin
            new_x = curr_x;
            new_y = curr_y;
        end
    end

    next_state = {new_x, new_y, curr_cmd_idx + 1};
    next_cost = current_cost;  // Execute doesn't add cost
end

// State machine and sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        valid <= 0;
        min_changes <= 0;
        reset_idx <= 0;
        q_head <= 0;
        q_tail <= 0;
        queue_empty <= 1;
    end else begin
        case (state)
            S_IDLE: begin
                if (start) begin
                    state <= S_RESET_COST;
                    reset_idx <= 0;
                end
            end

            S_RESET_COST: begin
                // Initialize cost table to max value (15)
                if (reset_idx < 255) begin
                    cost_table[reset_idx] <= CHANGES_BITS'hF;
                    reset_idx <= reset_idx + 1;
                end else begin
                    cost_table[255] <= CHANGES_BITS'hF;
                    state <= S_INIT;
                end
            end

            S_INIT: begin
                // Push start state (cost 0)
                queue[0] <= {start_x, start_y, 4'h0};
                q_tail <= 1;
                q_head <= 0;
                queue_empty <= 0;
                cost_table[{start_x, start_y, 4'h0}] <= 0;
                state <= S_PROCESS;
            end

            S_PROCESS: begin
                if (!queue_empty && q_head != q_tail) begin
                    // Pop current state from queue
                    current_state <= queue[q_head];
                    current_cost <= cost_table[queue[q_head]];
                    q_head <= q_head + 1;

                    // Check if queue becomes empty
                    if (q_head + 1 == q_tail) begin
                        queue_empty <= 1;
                    end

                    op_type <= 0;  // Start with execute
                    state <= S_EXPLORE;
                end else begin
                    // Queue empty - done
                    state <= S_DONE;
                end
            end

            S_EXPLORE: begin
                case (op_type)
                    2'b00: begin  // Execute command
                        if (has_more_cmds) begin
                            // next_state already computed by combinational logic
                            if (next_cost < cost_table[next_state]) begin
                                cost_table[next_state] <= next_cost;

                                // Check if goal reached
                                if (next_state[7:4] == {goal_x, goal_y}) begin
                                    min_changes <= next_cost;
                                    valid <= 1;
                                    state <= S_DONE;
                                end else if (q_tail < 31) begin
                                    // Enqueue new state
                                    queue[q_tail] <= next_state;
                                    q_tail <= q_tail + 1;
                                    queue_empty <= 0;
                                end
                            end
                        end
                        op_type <= 2'b01;  // Next: delete
                    end

                    2'b01: begin  // Delete current command
                        if (has_more_cmds) begin
                            next_state <= {curr_x, curr_y, curr_cmd_idx + 1};
                            next_cost <= current_cost + 1;

                            if (next_cost < cost_table[next_state]) begin
                                cost_table[next_state] <= next_cost;

                                if (next_state[7:4] == {goal_x, goal_y}) begin
                                    min_changes <= next_cost;
                                    valid <= 1;
                                    state <= S_DONE;
                                end else if (q_tail < 31) begin
                                    queue[q_tail] <= next_state;
                                    q_tail <= q_tail + 1;
                                    queue_empty <= 0;
                                end
                            end
                        end
                        op_type <= 2'b10;  // Next: insert
                    end

                    2'b10: begin  // Insert command (simplified)
                        // Insert at current position: stay at same cmd_idx, add cost
                        // This represents inserting a command that moves the robot
                        // For hardware simplicity, we treat insert as:
                        // - Try all 4 directions from current position
                        // - Increase cost by 1
                        // - Keep same cmd_idx

                        // Simplified: just increment cost for insert operation
                        next_state <= {curr_x, curr_y, curr_cmd_idx};
                        next_cost <= current_cost + 1;

                        if (next_cost < cost_table[next_state]) begin
                            cost_table[next_state] <= next_cost;

                            if (next_state[7:4] == {goal_x, goal_y}) begin
                                min_changes <= next_cost;
                                valid <= 1;
                                state <= S_DONE;
                            end else if (q_tail < 31) begin
                                queue[q_tail] <= next_state;
                                q_tail <= q_tail + 1;
                                queue_empty <= 0;
                            end
                        end

                        state <= S_PROCESS;  // Back to queue processing
                    end

                    default: op_type <= 2'b00;
                endcase
            end

            S_DONE: begin
                done <= 1;
                if (!valid) begin
                    // No path found within cost limit
                    min_changes <= CHANGES_BITS'hF;
                end
            end
        endcase
    end
end

endmodule

module lcm_tree_counter #(
    parameter MAX_NODES = 8,
    parameter DATA_WIDTH = 32,
    parameter RESULT_WIDTH = 32,
    parameter MOD = 1000000007
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] n,  // number of nodes, must be odd (1,3,5,7)
    input wire [DATA_WIDTH-1:0] node_vals_0,
    input wire [DATA_WIDTH-1:0] node_vals_1,
    input wire [DATA_WIDTH-1:0] node_vals_2,
    input wire [DATA_WIDTH-1:0] node_vals_3,
    input wire [DATA_WIDTH-1:0] node_vals_4,
    input wire [DATA_WIDTH-1:0] node_vals_5,
    input wire [DATA_WIDTH-1:0] node_vals_6,
    input wire [DATA_WIDTH-1:0] node_vals_7,
    output reg [RESULT_WIDTH-1:0] result,
    output reg done
);

// Internal storage for node values
reg [DATA_WIDTH-1:0] vals [0:MAX_NODES-1];

// DP table: dp[mask][v] = number of ways for subtree with nodes in mask rooted at v
// Total entries: (1 << MAX_NODES) * MAX_NODES = 256 * 8 = 2048
reg [RESULT_WIDTH-1:0] dp [0:(1<<MAX_NODES)-1][0:MAX_NODES-1];

// State machine states
localparam IDLE = 0;
localparam INIT = 1;
localparam PROCESS = 2;
localparam FINAL_SUM = 3;
localparam DONE_STATE = 4;
reg [2:0] state;

// Loop counters
reg [MAX_NODES-1:0] mask;
reg [2:0] v_idx;  // current root index
reg [2:0] a_idx, b_idx;  // for pair iteration
reg [MAX_NODES-1:0] rem_mask;  // remaining nodes after removing v, a, b
reg [MAX_NODES-1:0] submask;  // subset S of rem_mask

// GCD calculator signals
reg gcd_start;
reg [DATA_WIDTH-1:0] gcd_a, gcd_b;
wire gcd_done;
wire [DATA_WIDTH-1:0] gcd_result;

// GCD module instance
gcd_module gcd_inst (
    .clk(clk),
    .rst_n(rst_n),
    .start(gcd_start),
    .a(gcd_a),
    .b(gcd_b),
    .result(gcd_result),
    .done(gcd_done)
);

// Helper function: compute LCM from GCD
reg [DATA_WIDTH*2-1:0] lcm_temp;
reg lcm_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        gcd_start <= 0;
        lcm_valid <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Load node values into array
                    vals[0] <= node_vals_0;
                    vals[1] <= node_vals_1;
                    vals[2] <= node_vals_2;
                    vals[3] <= node_vals_3;
                    vals[4] <= node_vals_4;
                    vals[5] <= node_vals_5;
                    vals[6] <= node_vals_6;
                    vals[7] <= node_vals_7;
                    state <= INIT;
                    // Initialize DP table for masks of size 1
                    // For each mask with exactly one bit set, set dp[mask][v] = 1
                    // This will be handled in INIT state
                end
            end

            INIT: begin
                // Initialize dp for all masks of size 1
                // We can iterate over v from 0 to n-1
                // For each v, mask = 1 << v, set dp[mask][v] = 1
                // After initialization, go to PROCESS
                // Implementation details: use a counter for v
                // For simplicity, we can initialize in PROCESS state
                state <= PROCESS;
                // Initialize loop variables
                mask <= 1;
                v_idx <= 0;
            end

            PROCESS: begin
                // Main DP computation
                // This state will iterate over masks in increasing order of size
                // For each mask, for each v in mask, compute DP[mask][v]
                // using the recurrence relation.
                // Due to complexity, this state machine will have multiple sub-states.
                // We'll use a nested loop approach.
                // This is a high-level specification; details need to be filled.
                // The LLM should generate the complete nested loop logic.
                // After processing, go to FINAL_SUM.
                state <= FINAL_SUM;
            end

            FINAL_SUM: begin
                // Sum dp[full_mask][v] for all v in full_mask
                // full_mask = (1 << n) - 1
                // Accumulate result modulo MOD
                // Then go to DONE_STATE
                state <= DONE_STATE;
            end

            DONE_STATE: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

