module consistency_checker (
    input clk,
    input rst_n,
    input start,
    input statement_valid,
    input last,
    input statement_type,
    input [2:0] word1,
    input [2:0] word2,
    output reg ready,
    output reg done,
    output reg result
);

// Parameters
parameter MAX_WORDS = 8;

// State encoding
localparam IDLE = 3'b000;
localparam FETCH = 3'b001;
localparam FIND_X = 3'b010;
localparam FIND_Y = 3'b011;
localparam CHECK = 3'b100;
localparam UPDATE = 3'b101;
localparam DONE = 3'b110;

// Registers
reg [2:0] state;
reg [2:0] parent [0:MAX_WORDS-1];
reg [MAX_WORDS-1:0] not_matrix [0:MAX_WORDS-1];
reg contradiction_found;
reg [2:0] root_x_reg, root_y_reg;
reg current_type;
reg current_last;
reg [2:0] current_word1, current_word2;

// Helper function for find
function automatic [2:0] find_root;
    input [2:0] x;
    integer i;
    begin
        find_root = x;
        for (i=0; i<MAX_WORDS; i=i+1) begin
            if (parent[find_root] != find_root)
                find_root = parent[find_root];
        end
    end
endfunction

// Combinational logic for roots
wire [2:0] root_x_wire = find_root(current_word1);
wire [2:0] root_y_wire = find_root(current_word2);

// Combinational contradiction check for "is"
wire contradiction_is_wire;
wire [MAX_WORDS-1:0] set_x_mask;
wire [MAX_WORDS-1:0] set_y_mask;
generate
    genvar i, j;
    for (i=0; i<MAX_WORDS; i=i+1) begin : set_x
        assign set_x_mask[i] = (parent[i] == root_x_reg);
    end
    for (j=0; j<MAX_WORDS; j=j+1) begin : set_y
        assign set_y_mask[j] = (parent[j] == root_y_reg);
    end
    wire [MAX_WORDS-1:0] conflict_x;
    for (i=0; i<MAX_WORDS; i=i+1) begin : check_conflicts
        assign conflict_x[i] = set_x_mask[i] & (|(set_y_mask & not_matrix[i]));
    end
    assign contradiction_is_wire = |conflict_x;
endgenerate

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        ready <= 0;
        done <= 0;
        result <= 0;
        contradiction_found <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    for (integer i=0; i<MAX_WORDS; i=i+1) begin
                        parent[i] <= i;
                        not_matrix[i] <= 0;
                    end
                    contradiction_found <= 0;
                    ready <= 1;
                    done <= 0;
                    result <= 0;
                    state <= FETCH;
                end
            end

            FETCH: begin
                if (statement_valid) begin
                    current_type <= statement_type;
                    current_word1 <= word1;
                    current_word2 <= word2;
                    current_last <= last;
                    ready <= 0;
                    state <= FIND_X;
                end
            end

            FIND_X: begin
                root_x_reg <= root_x_wire;
                state <= FIND_Y;
            end

            FIND_Y: begin
                root_y_reg <= root_y_wire;
                state <= CHECK;
            end

            CHECK: begin
                if (current_type == 0) begin
                    if (contradiction_is_wire)
                        contradiction_found <= 1;
                end else begin
                    if (root_x_reg == root_y_reg)
                        contradiction_found <= 1;
                end
                state <= UPDATE;
            end

            UPDATE: begin
                if (contradiction_found == 0) begin
                    if (current_type == 0)
                        parent[root_x_reg] <= root_y_reg;
                    else begin
                        not_matrix[current_word1][current_word2] <= 1;
                        not_matrix[current_word2][current_word1] <= 1;
                    end
                end

                if (current_last) begin
                    state <= DONE;
                end else begin
                    ready <= 1;
                    state <= FETCH;
                end
            end

            DONE: begin
                done <= 1;
                result <= ~contradiction_found;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module kth_sequence (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,      // 2 <= n <= 8
    input wire [13:0] k,     // 1 <= k <= 10000
    output reg [2:0] seq_0, seq_1, seq_2, seq_3, seq_4, seq_5, seq_6, seq_7,
    output reg done
);

// State definitions
localparam IDLE = 3'd0;
localparam FIND_A = 3'd1;
localparam UPDATE = 3'd2;
localparam NEXT = 3'd3;
localparam DONE = 3'd4;

// Registers
reg [2:0] state;
reg [3:0] s;           // current prefix sum modulo n
reg [7:0] used;        // bitmask for used residues (bit i set if residue i used)
reg [3:0] i;           // current position (1 to n-1)
reg [13:0] rem_k;      // remaining k during search
reg [3:0] a;           // current candidate a

// Combinational signals for current candidate
wire [3:0] new_s_temp = s + a;
wire [3:0] new_s = (new_s_temp >= n) ? new_s_temp - n : new_s_temp;
wire valid = (used[new_s] == 0);

// Factorial lookup for count_per = factorial(n - i - 1)
reg [13:0] count_per;
always @(*) begin
    case (n - i - 1)
        0: count_per = 14'd1;
        1: count_per = 14'd1;
        2: count_per = 14'd2;
        3: count_per = 14'd6;
        4: count_per = 14'd24;
        5: count_per = 14'd120;
        6: count_per = 14'd720;
        default: count_per = 14'd0;
    endcase
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        seq_0 <= 0; seq_1 <= 0; seq_2 <= 0; seq_3 <= 0;
        seq_4 <= 0; seq_5 <= 0; seq_6 <= 0; seq_7 <= 0;
        s <= 0;
        used <= 0;
        i <= 0;
        rem_k <= 0;
        a <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    s <= 0;
                    used <= 8'b00000001; // residue 0 used
                    i <= 1;
                    rem_k <= k;
                    a <= 1;
                    state <= FIND_A;
                end
            end

            FIND_A: begin
                if (valid) begin
                    if (rem_k > count_per) begin
                        rem_k <= rem_k - count_per;
                        a <= a + 1;
                        // Assume a <= n-1 always true
                    end else begin
                        state <= UPDATE;
                    end
                end else begin
                    a <= a + 1;
                    // Assume a <= n-1 always true
                end
            end

            UPDATE: begin
                // Assign sequence element based on position
                case (i)
                    1: seq_0 <= a;
                    2: seq_1 <= a;
                    3: seq_2 <= a;
                    4: seq_3 <= a;
                    5: seq_4 <= a;
                    6: seq_5 <= a;
                    7: seq_6 <= a;
                    8: seq_7 <= a;
                endcase
                s <= new_s;
                used <= used | (1 << new_s);
                state <= NEXT;
            end

            NEXT: begin
                i <= i + 1;
                if (i + 1 > n - 1) begin
                    state <= DONE;
                end else begin
                    state <= FIND_A;
                    a <= 1;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module borg_sentry (
  input clk, rst_n, start,
  input [3:0] N,  // number of nodes (2-8)
  input [3:0] L,  // walk length (1-8)
  // Walk sequence (8x4-bit)
  input [3:0] walk0, walk1, walk2, walk3, walk4, walk5, walk6, walk7,
  // Graph structure: degree and neighbors for each node
  input [3:0] degree0, degree1, degree2, degree3, degree4, degree5, degree6, degree7,
  // Neighbors for node 0
  input [3:0] neighbors0_0, neighbors0_1, neighbors0_2, neighbors0_3,
              neighbors0_4, neighbors0_5, neighbors0_6, neighbors0_7,
  // Neighbors for node 1
  input [3:0] neighbors1_0, neighbors1_1, neighbors1_2, neighbors1_3,
              neighbors1_4, neighbors1_5, neighbors1_6, neighbors1_7,
  // Neighbors for node 2
  input [3:0] neighbors2_0, neighbors2_1, neighbors2_2, neighbors2_3,
              neighbors2_4, neighbors2_5, neighbors2_6, neighbors2_7,
  // Neighbors for node 3
  input [3:0] neighbors3_0, neighbors3_1, neighbors3_2, neighbors3_3,
              neighbors3_4, neighbors3_5, neighbors3_6, neighbors3_7,
  // Neighbors for node 4
  input [3:0] neighbors4_0, neighbors4_1, neighbors4_2, neighbors4_3,
              neighbors4_4, neighbors4_5, neighbors4_6, neighbors4_7,
  // Neighbors for node 5
  input [3:0] neighbors5_0, neighbors5_1, neighbors5_2, neighbors5_3,
              neighbors5_4, neighbors5_5, neighbors5_6, neighbors5_7,
  // Neighbors for node 6
  input [3:0] neighbors6_0, neighbors6_1, neighbors6_2, neighbors6_3,
              neighbors6_4, neighbors6_5, neighbors6_6, neighbors6_7,
  // Neighbors for node 7
  input [3:0] neighbors7_0, neighbors7_1, neighbors7_2, neighbors7_3,
              neighbors7_4, neighbors7_5, neighbors7_6, neighbors7_7,
  output reg [31:0] result,  // Fixed-point probability (Q24.8)
  output reg done
);

  // State definitions
  localparam S_IDLE = 4'd0;
  localparam S_LOAD = 4'd1;
  localparam S_INIT = 4'd2;
  localparam S_STEP_RESET = 4'd3;
  localparam S_STEP_LOOP = 4'd4;
  localparam S_FINAL_SUM = 4'd5;
  localparam S_DONE = 4'd6;

  // Fixed-point constants
  localparam FIXED_SHIFT = 24;
  localparam ONE = 24'd1 << FIXED_SHIFT;  // 1.0 in fixed-point

  // Internal registers
  reg [3:0] state;
  reg [3:0] t_count;      // Current step in walk (1 to L-1)
  reg [3:0] u_count;      // Current node index for DP
  reg [3:0] deg_count;    // Current neighbor index for node u
  reg [31:0] dp_prev [0:7];  // Previous DP state
  reg [31:0] dp_curr [0:7];  // Current DP state
  reg [3:0] walk_reg [0:7];  // Registered walk
  reg [3:0] degree_reg [0:7];  // Registered degrees
  reg [3:0] neighbors_reg [0:7][0:7];  // Registered neighbors

  // Function for reciprocal (1/value) in fixed-point
  function [31:0] reciprocal;
    input [3:0] denom;
    begin
      case(denom)
        4'd1: reciprocal = 32'h01000000;  // 1.0
        4'd2: reciprocal = 32'h00800000;  // 0.5
        4'd3: reciprocal = 32'h00555555;  // 1/3
        4'd4: reciprocal = 32'h00400000;  // 0.25
        4'd5: reciprocal = 32'h00333333;  // 0.2
        4'd6: reciprocal = 32'h002AAAAA;  // 1/6
        4'd7: reciprocal = 32'h00249249;  // 1/7
        4'd8: reciprocal = 32'h00200000;  // 0.125
        default: reciprocal = 32'd0;
      endcase
    end
  endfunction

  // Temporary signals for multiplication
  wire [63:0] product;
  wire [63:0] product_rounded_64;
  wire [31:0] product_rounded;

  assign product = dp_prev[u_count] * reciprocal(degree_reg[u_count]);
  assign product_rounded_64 = product + (1 << 23);  // Add 2^23 for rounding
  assign product_rounded = product_rounded_64[55:24];  // Shift right by 24

  // State machine and datapath
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= S_IDLE;
      done <= 0;
      result <= 0;
      t_count <= 0;
      u_count <= 0;
      deg_count <= 0;
    end else begin
      case(state)
        S_IDLE: begin
          if (start) begin
            state <= S_LOAD;
            done <= 0;
          end
        end

        S_LOAD: begin
          // Register all inputs
          walk_reg[0] <= walk0;
          walk_reg[1] <= walk1;
          walk_reg[2] <= walk2;
          walk_reg[3] <= walk3;
          walk_reg[4] <= walk4;
          walk_reg[5] <= walk5;
          walk_reg[6] <= walk6;
          walk_reg[7] <= walk7;

          degree_reg[0] <= degree0;
          degree_reg[1] <= degree1;
          degree_reg[2] <= degree2;
          degree_reg[3] <= degree3;
          degree_reg[4] <= degree4;
          degree_reg[5] <= degree5;
          degree_reg[6] <= degree6;
          degree_reg[7] <= degree7;

          neighbors_reg[0][0] <= neighbors0_0;
          neighbors_reg[0][1] <= neighbors0_1;
          neighbors_reg[0][2] <= neighbors0_2;
          neighbors_reg[0][3] <= neighbors0_3;
          neighbors_reg[0][4] <= neighbors0_4;
          neighbors_reg[0][5] <= neighbors0_5;
          neighbors_reg[0][6] <= neighbors0_6;
          neighbors_reg[0][7] <= neighbors0_7;

          neighbors_reg[1][0] <= neighbors1_0;
          neighbors_reg[1][1] <= neighbors1_1;
          neighbors_reg[1][2] <= neighbors1_2;
          neighbors_reg[1][3] <= neighbors1_3;
          neighbors_reg[1][4] <= neighbors1_4;
          neighbors_reg[1][5] <= neighbors1_5;
          neighbors_reg[1][6] <= neighbors1_6;
          neighbors_reg[1][7] <= neighbors1_7;

          neighbors_reg[2][0] <= neighbors2_0;
          neighbors_reg[2][1] <= neighbors2_1;
          neighbors_reg[2][2] <= neighbors2_2;
          neighbors_reg[2][3] <= neighbors2_3;
          neighbors_reg[2][4] <= neighbors2_4;
          neighbors_reg[2][5] <= neighbors2_5;
          neighbors_reg[2][6] <= neighbors2_6;
          neighbors_reg[2][7] <= neighbors2_7;

          neighbors_reg[3][0] <= neighbors3_0;
          neighbors_reg[3][1] <= neighbors3_1;
          neighbors_reg[3][2] <= neighbors3_2;
          neighbors_reg[3][3] <= neighbors3_3;
          neighbors_reg[3][4] <= neighbors3_4;
          neighbors_reg[3][5] <= neighbors3_5;
          neighbors_reg[3][6] <= neighbors3_6;
          neighbors_reg[3][7] <= neighbors3_7;

          neighbors_reg[4][0] <= neighbors4_0;
          neighbors_reg[4][1] <= neighbors4_1;
          neighbors_reg[4][2] <= neighbors4_2;
          neighbors_reg[4][3] <= neighbors4_3;
          neighbors_reg[4][4] <= neighbors4_4;
          neighbors_reg[4][5] <= neighbors4_5;
          neighbors_reg[4][6] <= neighbors4_6;
          neighbors_reg[4][7] <= neighbors4_7;

          neighbors_reg[5][0] <= neighbors5_0;
          neighbors_reg[5][1] <= neighbors5_1;
          neighbors_reg[5][2] <= neighbors5_2;
          neighbors_reg[5][3] <= neighbors5_3;
          neighbors_reg[5][4] <= neighbors5_4;
          neighbors_reg[5][5] <= neighbors5_5;
          neighbors_reg[5][6] <= neighbors5_6;
          neighbors_reg[5][7] <= neighbors5_7;

          neighbors_reg[6][0] <= neighbors6_0;
          neighbors_reg[6][1] <= neighbors6_1;
          neighbors_reg[6][2] <= neighbors6_2;
          neighbors_reg[6][3] <= neighbors6_3;
          neighbors_reg[6][4] <= neighbors6_4;
          neighbors_reg[6][5] <= neighbors6_5;
          neighbors_reg[6][6] <= neighbors6_6;
          neighbors_reg[6][7] <= neighbors6_7;

          neighbors_reg[7][0] <= neighbors7_0;
          neighbors_reg[7][1] <= neighbors7_1;
          neighbors_reg[7][2] <= neighbors7_2;
          neighbors_reg[7][3] <= neighbors7_3;
          neighbors_reg[7][4] <= neighbors7_4;
          neighbors_reg[7][5] <= neighbors7_5;
          neighbors_reg[7][6] <= neighbors7_6;
          neighbors_reg[7][7] <= neighbors7_7;

          state <= S_INIT;
        end

        S_INIT: begin
          // Initialize DP for t=0
          if (u_count < N) begin
            if (u_count == walk_reg[0]) begin
              dp_prev[u_count] <= 0;
            end else begin
              dp_prev[u_count] <= reciprocal(N);
            end
            u_count <= u_count + 1;
          end else begin
            u_count <= 0;
            t_count <= 1;
            state <= (L > 1) ? S_STEP_RESET : S_FINAL_SUM;
          end
        end

        S_STEP_RESET: begin
          // Reset dp_curr to 0 for all nodes
          if (u_count < N) begin
            dp_curr[u_count] <= 0;
            u_count <= u_count + 1;
          end else begin
            u_count <= 0;
            deg_count <= 0;
            state <= S_STEP_LOOP;
          end
        end

        S_STEP_LOOP: begin
          if (u_count < N) begin
            if (deg_count < degree_reg[u_count]) begin
              // Check conditions
              if (neighbors_reg[u_count][deg_count] != walk_reg[t_count] && 
                  !(u_count == walk_reg[t_count] && neighbors_reg[u_count][deg_count] == walk_reg[t_count-1])) begin
                // Add to dp_curr[v]
                dp_curr[neighbors_reg[u_count][deg_count]] <= dp_curr[neighbors_reg[u_count][deg_count]] + product_rounded;
              end
              deg_count <= deg_count + 1;
            end else begin
              u_count <= u_count + 1;
              deg_count <= 0;
            end
          end else begin
            // Swap dp_prev and dp_curr
            for (integer i = 0; i < 8; i = i + 1) begin
              dp_prev[i] <= dp_curr[i];
            end
            t_count <= t_count + 1;
            if (t_count + 1 < L) begin
              u_count <= 0;
              state <= S_STEP_RESET;
            end else begin
              state <= S_FINAL_SUM;
            end
          end
        end

        S_FINAL_SUM: begin
          // Sum dp_prev[v] for v=0 to N-1
          if (u_count < N) begin
            result <= result + dp_prev[u_count];
            u_count <= u_count + 1;
          end else begin
            state <= S_DONE;
          end
        end

        S_DONE: begin
          done <= 1;
          if (!start) state <= S_IDLE;
        end
      endcase
    end
  end
endmodule

module debt_resolver (
    input clk,
    input rst_n,
    input start,
    input [7:0] debtor_0, debtor_1, debtor_2, debtor_3, debtor_4, debtor_5, debtor_6, debtor_7,
    input [7:0] debt_0, debt_1, debt_2, debt_3, debt_4, debt_5, debt_6, debt_7,
    output reg [15:0] total_money,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam RESOLVE = 3'b001;
localparam CALCULATE = 3'b010;
localparam COMPLETE = 3'b011;

// Internal registers
reg [2:0] state, next_state;
reg [2:0] node_index;
reg [15:0] money_needed [0:7];
reg [15:0] total_sum;
reg [15:0] cycle_min;
reg [2:0] cycle_start;
reg [2:0] cycle_current;
reg cycle_found;
reg [7:0] visited;
reg [2:0] iterations;

// Arrays for easier access
wire [7:0] debtors [0:7];
wire [7:0] debts [0:7];
assign debtors[0] = debtor_0;
assign debtors[1] = debtor_1;
assign debtors[2] = debtor_2;
assign debtors[3] = debtor_3;
assign debtors[4] = debtor_4;
assign debtors[5] = debtor_5;
assign debtors[6] = debtor_6;
assign debtors[7] = debtor_7;

assign debts[0] = debt_0;
assign debts[1] = debt_1;
assign debts[2] = debt_2;
assign debts[3] = debt_3;
assign debts[4] = debt_4;
assign debts[5] = debt_5;
assign debts[6] = debt_6;
assign debts[7] = debt_7;

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        total_money <= 0;
        done <= 0;
        node_index <= 0;
        visited <= 0;
        iterations <= 0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (start) begin
                    total_money <= 0;
                    done <= 0;
                    node_index <= 0;
                    visited <= 0;
                    iterations <= 0;
                    // Initialize money_needed
                    money_needed[0] <= 0;
                    money_needed[1] <= 0;
                    money_needed[2] <= 0;
                    money_needed[3] <= 0;
                    money_needed[4] <= 0;
                    money_needed[5] <= 0;
                    money_needed[6] <= 0;
                    money_needed[7] <= 0;
                end
            end

            RESOLVE: begin
                // Process each node to determine if it needs initial money
                if (node_index < 8 && iterations < 8) begin
                    // Check if this node is part of a cycle
                    if (!visited[node_index]) begin
                        // Start cycle detection from this node
                        cycle_start <= node_index;
                        cycle_current <= node_index;
                        cycle_min <= 16'hFFFF;
                        cycle_found <= 0;
                    end
                    node_index <= node_index + 1;
                end
            end

            CALCULATE: begin
                // Add cycle minimum to total
                if (cycle_found && cycle_min != 16'hFFFF) begin
                    total_money <= total_money + cycle_min;
                end
            end

            COMPLETE: begin
                done <= 1;
            end
        endcase
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: begin
            if (start) next_state = RESOLVE;
        end

        RESOLVE: begin
            if (node_index >= 8 || iterations >= 8) begin
                next_state = CALCULATE;
            end else begin
                next_state = RESOLVE;
            end
        end

        CALCULATE: begin
            next_state = COMPLETE;
        end

        COMPLETE: begin
            next_state = IDLE;
        end

        default: next_state = IDLE;
    endcase
end

// Cycle detection and minimum calculation (combinational logic)
always @(*) begin
    cycle_found = 0;
    cycle_min = 16'hFFFF;

    // Simple cycle detection: check if node points to itself or forms small cycle
    if (state == RESOLVE && node_index < 8) begin
        integer start_idx, current_idx, count;
        start_idx = node_index;
        current_idx = start_idx;
        count = 0;

        // Follow the debt chain for at most 8 steps
        while (count < 8) begin
            integer next_node;
            next_node = debtors[current_idx];

            // Check if valid node
            if (next_node >= 8) break;

            // Found cycle when we revisit a node
            if (next_node == start_idx) begin
                cycle_found = 1;
                // Calculate minimum debt in cycle
                cycle_min = debts[start_idx];
                if (debts[current_idx] < cycle_min) cycle_min = debts[current_idx];
                break;
            end

            // Check for simple self-loop
            if (next_node == current_idx) begin
                cycle_found = 1;
                cycle_min = debts[current_idx];
                break;
            end

            current_idx = next_node;
            count = count + 1;
        end
    end
end

endmodule

module tape_art_solver #(
    parameter MAX_N = 16,
    parameter MAX_COLOR = 16,
    parameter DATA_WIDTH = 4,
    parameter ADDR_WIDTH = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [ADDR_WIDTH-1:0] n,
    input wire [DATA_WIDTH-1:0] colors [0:MAX_N-1],

    output reg done,
    output reg impossible,
    output reg [ADDR_WIDTH-1:0] num_instructions,
    output reg [ADDR_WIDTH-1:0] inst_l [0:MAX_COLOR-1],
    output reg [ADDR_WIDTH-1:0] inst_r [0:MAX_COLOR-1],
    output reg [DATA_WIDTH-1:0] inst_c [0:MAX_COLOR-1],
    output reg inst_valid [0:MAX_COLOR-1]
);
    localparam S_IDLE = 3'b000, S_SCAN = 3'b001, S_CHECK = 3'b010,
               S_SORT = 3'b011, S_OUTPUT = 3'b100, S_DONE = 3'b101,
               S_IMPOSSIBLE = 3'b110;

    reg [2:0] state, next_state;
    reg [ADDR_WIDTH-1:0] L [0:MAX_COLOR-1];
    reg [ADDR_WIDTH-1:0] R [0:MAX_COLOR-1];
    reg present [0:MAX_COLOR-1];
    reg [ADDR_WIDTH-1:0] idx, i, j, sort_i, sort_j, min_idx;
    reg [ADDR_WIDTH-1:0] temp_L, temp_R;
    reg [DATA_WIDTH-1:0] temp_C;
    reg temp_valid;

    always @(posedge clk or negedge rst_n)
        if (!rst_n) state <= S_IDLE; else state <= next_state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0; impossible <= 0; num_instructions <= 0;
            idx <= 0; i <= 0; j <= 0; sort_i <= 0; sort_j <= 0;
            for (integer k = 0; k < MAX_COLOR; k = k + 1) begin
                L[k] <= 0; R[k] <= 0; present[k] <= 0;
                inst_l[k] <= 0; inst_r[k] <= 0; inst_c[k] <= 0; inst_valid[k] <= 0;
            end
            next_state <= S_IDLE;
        end else begin
            case (state)
                S_IDLE: if (start) begin
                    idx <= 0;
                    for (integer k = 0; k < MAX_COLOR; k = k + 1) begin
                        L[k] <= 0; R[k] <= 0; present[k] <= 0;
                    end
                    next_state <= S_SCAN;
                end else next_state <= S_IDLE;

                S_SCAN: if (idx < n) begin
                    if (!present[colors[idx]]) begin
                        present[colors[idx]] <= 1;
                        L[colors[idx]] <= idx;
                        R[colors[idx]] <= idx;
                    end else R[colors[idx]] <= idx;
                    idx <= idx + 1;
                    next_state <= S_SCAN;
                end else begin
                    i <= 0; j <= 1;
                    next_state <= S_CHECK;
                end

                S_CHECK: if (i >= MAX_COLOR) begin
                    sort_i <= 0; sort_j <= 1; min_idx <= 0;
                    next_state <= S_SORT;
                end else if (j >= MAX_COLOR) begin
                    i <= i + 1; j <= i + 2;
                end else if (!present[i] || !present[j]) begin
                    j <= j + 1;
                end else if (R[i] >= L[j] && L[i] <= R[j] &&
                           !(L[i] <= L[j] && R[j] <= R[i]) &&
                           !(L[j] <= L[i] && R[i] <= R[j])) begin
                    impossible <= 1; next_state <= S_IMPOSSIBLE;
                end else j <= j + 1;

                S_SORT: if (sort_i >= MAX_COLOR - 1) begin
                    i <= 0; next_state <= S_OUTPUT;
                end else if (sort_j >= MAX_COLOR) begin
                    if (min_idx != sort_i) begin
                        temp_L <= L[sort_i]; L[sort_i] <= L[min_idx]; L[min_idx] <= temp_L;
                        temp_R <= R[sort_i]; R[sort_i] <= R[min_idx]; R[min_idx] <= temp_R;
                        temp_valid <= present[sort_i]; present[sort_i] <= present[min_idx]; present[min_idx] <= temp_valid;
                    end
                    sort_i <= sort_i + 1; sort_j <= sort_i + 1; min_idx <= sort_i + 1;
                end else if (!present[sort_j]) sort_j <= sort_j + 1;
                else if (sort_j == sort_i) begin
                    min_idx <= sort_j; sort_j <= sort_j + 1;
                end else begin
                    if ((R[sort_j] - L[sort_j]) > (R[min_idx] - L[min_idx])) min_idx <= sort_j;
                    sort_j <= sort_j + 1;
                end

                S_OUTPUT: if (i < MAX_COLOR) begin
                    if (present[i]) begin
                        inst_l[i] <= L[i]; inst_r[i] <= R[i]; inst_c[i] <= i;
                        inst_valid[i] <= 1; num_instructions <= num_instructions + 1;
                    end else inst_valid[i] <= 0;
                    i <= i + 1;
                end else begin done <= 1; next_state <= S_DONE; end

                S_DONE: next_state <= S_DONE;
                S_IMPOSSIBLE: begin done <= 1; next_state <= S_IMPOSSIBLE; end
                default: next_state <= S_IDLE;
            endcase
        end
    end
endmodule

cocotb_testbench:
import cocotb
from cocotb.triggers import Timer, RisingEdge, FallingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Configuration
DATA_WIDTH = 4
ARRAY_SIZE = 16
MAX_COLOR = 16
CLK_PERIOD_NS = 10
MAX_CYCLES = 1000

def is_value_defined(value):
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    try:
        return int(value)
    except ValueError:
        return default

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

def clamp_to_width(value, bits):
    max_val = (1 << bits) - 1
    if value < 0:
        return from_signed(max(-((1 << (bits - 1))), min((1 << (bits - 1)) - 1, value)), bits)
    return min(max_val, max(0, value))

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout: done not asserted after {max_cycles} cycles")

async def start_computation(dut):
    dut.start.value = 1
    await RisingEdge(dut.clk)
    dut.start.value = 0

@cocotb.test(timeout_time=5000, timeout_unit="ms")
async def test_tape_art_solver(dut):
    cocotb.start_soon(Clock(dut.clk, CLK_PERIOD_NS, units='ns').start())
    await reset_dut(dut)

    test_cases = [
        {"n": 6, "colors": [1, 2, 3, 3, 2, 1], "possible": True, 
         "expected": [(1, 6, 1), (2, 5, 2), (3, 4, 3)], "desc": "Nested"},
        {"n": 4, "colors": [1, 2, 1, 2], "possible": False, 
         "expected": [], "desc": "Overlapping non-nested"},
        {"n": 10, "colors": [3, 3, 3, 5, 4, 2, 4, 4, 5, 1], "possible": True,
         "expected": [(4, 9, 5), (5, 8, 4), (10, 10, 1), (6, 6, 2), (1, 3, 3)], "desc": "Complex"},
    ]

    passed = 0
    for test in test_cases:
        dut._log.info(f"Test: {test['desc']}")
        dut.n.value = test['n']
        for i in range(ARRAY_SIZE):
            dut.colors[i].value = clamp_to_width(test['colors'][i], DATA_WIDTH) if i < test['n'] else 0

        await start_computation(dut)
        await wait_for_done(dut)

        if test['possible']:
            if dut.impossible.value:
                raise TestFailure(f"Expected possible but got IMPOSSIBLE")

            num_inst = int(dut.num_instructions.value)
            if num_inst != len(test['expected']):
                raise TestFailure(f"Expected {len(test['expected'])} instructions, got {num_inst}")

            instructions = []
            for i in range(num_inst):
                if not is_value_defined(dut.inst_valid[i].value) or int(dut.inst_valid[i].value) != 1:
                    raise TestFailure(f"Instruction {i} invalid")
                instructions.append((int(dut.inst_l[i].value), int(dut.inst_r[i].value), int(dut.inst_c[i].value)))

            for exp in test['expected']:
                if exp not in instructions:
                    raise TestFailure(f"Expected instruction {exp} not found")

            dut._log.info(f"  PASS: {num_inst} instructions verified")
            passed += 1
        else:
            if not dut.impossible.value:
                raise TestFailure(f"Expected IMPOSSIBLE")
            dut._log.info("  PASS: Correctly IMPOSSIBLE")
            passed += 1

    dut._log.info(f"Results: {passed}/{len(test_cases)} passed")
    if passed != len(test_cases):
        raise TestFailure(f"{len(test_cases) - passed} tests failed")

