module solitaire_merger (
    input clk,
    input rst_n,
    input start,

    // Sequence A (max 4 elements, 8-bit values)
    input [7:0] a0, a1, a2, a3,
    input [2:0] len_a,

    // Sequence B (max 4 elements, 8-bit values)
    input [7:0] b0, b1, b2, b3,
    input [2:0] len_b,

    output reg [7:0] result,
    output reg result_valid,
    output reg done
);

    // Internal state
    reg [2:0] state;
    reg [2:0] ptr_a, ptr_b;

    // State definitions
    localparam IDLE = 3'd0;
    localparam COMPARE = 3'd1;
    localparam OUTPUT_A = 3'd2;
    localparam OUTPUT_B = 3'd3;
    localparam DONE = 3'd4;

    // Combinational comparison result
    wire a_smaller;

    // Comparator: returns 1 if sequence A (from ptr_a) is lexicographically smaller than B
    assign a_smaller = compare_sequences();

    function automatic logic compare_sequences;
        logic [7:0] val_a, val_b;
    begin
        // Default: A is smaller (tie-breaker)
        compare_sequences = 1'b1;

        // Handle empty sequences
        if (ptr_a >= len_a && ptr_b >= len_b) begin
            compare_sequences = 1'b1;
        end
        else if (ptr_a >= len_a) begin
            compare_sequences = 1'b1;  // A empty
        end
        else if (ptr_b >= len_b) begin
            compare_sequences = 1'b0;  // B empty
        end
        else begin
            // Get current values
            case (ptr_a)
                0: val_a = a0;
                1: val_a = a1;
                2: val_a = a2;
                3: val_a = a3;
                default: val_a = 8'hXX;
            endcase

            case (ptr_b)
                0: val_b = b0;
                1: val_b = b1;
                2: val_b = b2;
                3: val_b = b3;
                default: val_b = 8'hXX;
            endcase

            // Compare current element
            if (val_a < val_b) begin
                compare_sequences = 1'b1;
            end
            else if (val_a > val_b) begin
                compare_sequences = 1'b0;
            end
            else begin
                // Look ahead: position 1
                if (ptr_a + 1 < len_a && ptr_b + 1 < len_b) begin
                    logic [7:0] next_a, next_b;
                    case (ptr_a + 1)
                        0: next_a = a0;
                        1: next_a = a1;
                        2: next_a = a2;
                        3: next_a = a3;
                    endcase
                    case (ptr_b + 1)
                        0: next_b = b0;
                        1: next_b = b1;
                        2: next_b = b2;
                        3: next_b = b3;
                    endcase

                    if (next_a < next_b) compare_sequences = 1'b1;
                    else if (next_a > next_b) compare_sequences = 1'b0;
                    else begin
                        // Look ahead: position 2
                        if (ptr_a + 2 < len_a && ptr_b + 2 < len_b) begin
                            logic [7:0] next_a2, next_b2;
                            case (ptr_a + 2)
                                0: next_a2 = a0;
                                1: next_a2 = a1;
                                2: next_a2 = a2;
                                3: next_a2 = a3;
                            endcase
                            case (ptr_b + 2)
                                0: next_b2 = b0;
                                1: next_b2 = b1;
                                2: next_b2 = b2;
                                3: next_b2 = b3;
                            endcase

                            if (next_a2 < next_b2) compare_sequences = 1'b1;
                            else if (next_a2 > next_b2) compare_sequences = 1'b0;
                            else begin
                                // Look ahead: position 3
                                if (ptr_a + 3 < len_a && ptr_b + 3 < len_b) begin
                                    logic [7:0] next_a3, next_b3;
                                    case (ptr_a + 3)
                                        0: next_a3 = a0;
                                        1: next_a3 = a1;
                                        2: next_a3 = a2;
                                        3: next_a3 = a3;
                                    endcase
                                    case (ptr_b + 3)
                                        0: next_b3 = b0;
                                        1: next_b3 = b1;
                                        2: next_b3 = b2;
                                        3: next_b3 = b3;
                                    endcase

                                    if (next_a3 < next_b3) compare_sequences = 1'b1;
                                    else if (next_a3 > next_b3) compare_sequences = 1'b0;
                                    else begin
                                        // All equal, compare remaining lengths
                                        compare_sequences = (len_a - ptr_a) < (len_b - ptr_b);
                                    end
                                end
                                else begin
                                    compare_sequences = (len_a - ptr_a) < (len_b - ptr_b);
                                end
                            end
                        end
                        else begin
                            compare_sequences = (len_a - ptr_a) < (len_b - ptr_b);
                        end
                    end
                end
                else begin
                    compare_sequences = (len_a - ptr_a) < (len_b - ptr_b);
                end
            end
        end
    end
    endfunction

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            ptr_a <= 3'b0;
            ptr_b <= 3'b0;
            result <= 8'b0;
            result_valid <= 1'b0;
            done <= 1'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    result_valid <= 1'b0;
                    done <= 1'b0;
                    if (start) begin
                        ptr_a <= 3'b0;
                        ptr_b <= 3'b0;
                        state <= COMPARE;
                    end
                end

                COMPARE: begin
                    result_valid <= 1'b0;
                    if (ptr_a >= len_a && ptr_b >= len_b) begin
                        state <= DONE;
                    end
                    else if (ptr_a >= len_a) begin
                        state <= OUTPUT_B;
                    end
                    else if (ptr_b >= len_b) begin
                        state <= OUTPUT_A;
                    end
                    else begin
                        if (a_smaller) begin
                            state <= OUTPUT_A;
                        end
                        else begin
                            state <= OUTPUT_B;
                        end
                    end
                end

                OUTPUT_A: begin
                    case (ptr_a)
                        0: result <= a0;
                        1: result <= a1;
                        2: result <= a2;
                        3: result <= a3;
                    endcase
                    result_valid <= 1'b1;
                    ptr_a <= ptr_a + 1;
                    state <= COMPARE;
                end

                OUTPUT_B: begin
                    case (ptr_b)
                        0: result <= b0;
                        1: result <= b1;
                        2: result <= b2;
                        3: result <= b3;
                    endcase
                    result_valid <= 1'b1;
                    ptr_b <= ptr_b + 1;
                    state <= COMPARE;
                end

                DONE: begin
                    result_valid <= 1'b0;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module black_vienna_solver(
    input wire [2:0] n,
    input wire [6:0] inv0,
    input wire [6:0] inv1,
    input wire [6:0] inv2,
    input wire [6:0] inv3,
    input wire [6:0] inv4,
    output reg [2:0] count
);

// Precomputed masks for 4 suspects (A=0, B=1, C=2, D=3) and 8 assignments
reg [3:0] p1_mask [0:7];
reg [3:0] p2_mask [0:7];

initial begin
    // Assignment 0: x=A, p=0 -> P1: A, P2: none
    p1_mask[0] = 4'b0001; p2_mask[0] = 4'b0000;
    // Assignment 1: x=A, p=1 -> P1: none, P2: A
    p1_mask[1] = 4'b0000; p2_mask[1] = 4'b0001;
    // Assignment 2: x=B, p=0 -> P1: B, P2: none
    p1_mask[2] = 4'b0010; p2_mask[2] = 4'b0000;
    // Assignment 3: x=B, p=1 -> P1: none, P2: B
    p1_mask[3] = 4'b0000; p2_mask[3] = 4'b0010;
    // Assignment 4: x=C, p=0 -> P1: C, P2: none
    p1_mask[4] = 4'b0100; p2_mask[4] = 4'b0000;
    // Assignment 5: x=C, p=1 -> P1: none, P2: C
    p1_mask[5] = 4'b0000; p2_mask[5] = 4'b0100;
    // Assignment 6: x=D, p=0 -> P1: D, P2: none
    p1_mask[6] = 4'b1000; p2_mask[6] = 4'b0000;
    // Assignment 7: x=D, p=1 -> P1: none, P2: D
    p1_mask[7] = 4'b0000; p2_mask[7] = 4'b1000;
end

// Decode investigations
wire [1:0] letter1 [0:4];
wire [1:0] letter2 [0:4];
wire player [0:4];
wire [1:0] reply [0:4];

assign letter1[0] = inv0[6:5];
assign letter2[0] = inv0[4:3];
assign player[0] = inv0[2];
assign reply[0] = inv0[1:0];

assign letter1[1] = inv1[6:5];
assign letter2[1] = inv1[4:3];
assign player[1] = inv1[2];
assign reply[1] = inv1[1:0];

assign letter1[2] = inv2[6:5];
assign letter2[2] = inv2[4:3];
assign player[2] = inv2[2];
assign reply[2] = inv2[1:0];

assign letter1[3] = inv3[6:5];
assign letter2[3] = inv3[4:3];
assign player[3] = inv3[2];
assign reply[3] = inv3[1:0];

assign letter1[4] = inv4[6:5];
assign letter2[4] = inv4[4:3];
assign player[4] = inv4[2];
assign reply[4] = inv4[1:0];

// For each assignment, compute valid flag
reg valid [0:7];

integer a, i;
reg [3:0] mask;
reg [1:0] count_val;
reg cond_i;

always @(*) begin
    for (a = 0; a < 8; a = a + 1) begin
        valid[a] = 1'b1;
        for (i = 0; i < 5; i = i + 1) begin
            if (i < n) begin
                // Determine mask based on player
                if (player[i] == 1'b0) begin
                    mask = p1_mask[a];
                end else begin
                    mask = p2_mask[a];
                end
                // Count how many of the two letters are in the mask
                count_val = 0;
                if (mask[letter1[i]]) count_val = count_val + 1;
                if (mask[letter2[i]]) count_val = count_val + 1;
                cond_i = (count_val == reply[i]);
                if (!cond_i) begin
                    valid[a] = 1'b0;
                end
            end
        end
    end
end

// Count the number of valid assignments
always @(*) begin
    count = 0;
    for (a = 0; a < 8; a = a + 1) begin
        if (valid[a]) begin
            count = count + 1;
        end
    end
end

endmodule

module bracket_validator(
    input clk,
    input rst_n,
    input start,
    input [7:0] brackets, // 1 for '(', 0 for ')'
    input [2:0] length,   // number of brackets (1 to 8)
    output reg possible,
    output reg done
);

// Parameters
parameter MAX_LEN = 8;

// Internal registers
reg [7:0] brackets_reg;
reg [2:0] length_reg;
reg [2:0] l, r, i;
reg signed [4:0] cnt;
reg invalid;
reg found;
reg invert_enable;
reg check_orig;

// State encoding
reg [3:0] state;
localparam IDLE = 4'd0;
localparam CHECK_ORIG = 4'd1;
localparam SETUP_SEG = 4'd2;
localparam CHECK_SEG = 4'd3;
localparam LOOP_I = 4'd4;
localparam NEXT_I = 4'd5;
localparam ORIG_DONE = 4'd6;
localparam SEGMENT_DONE = 4'd7;
localparam NEXT_R = 4'd8;
localparam NEXT_L = 4'd9;
localparam DONE = 4'd10;

// Combinational logic for current bracket
wire [2:0] i_val = i;
wire current_bracket_raw = (i_val < length_reg) ? brackets_reg[i_val] : 0;
wire invert_flag = invert_enable && (i_val >= l) && (i_val <= r);
wire current_bracket = invert_flag ? ~current_bracket_raw : current_bracket_raw;

// Next cnt and invalid
wire signed [4:0] next_cnt = current_bracket ? cnt + 1 : cnt - 1;
wire next_invalid = invalid || (next_cnt < 0);

// State machine and datapath
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset
        state <= IDLE;
        possible <= 0;
        done <= 0;
        brackets_reg <= 8'b0;
        length_reg <= 3'b0;
        l <= 3'b0;
        r <= 3'b0;
        i <= 3'b0;
        cnt <= 5'sd0;
        invalid <= 0;
        found <= 0;
        invert_enable <= 0;
        check_orig <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    brackets_reg <= brackets;
                    length_reg <= length;
                    found <= 0;
                    state <= CHECK_ORIG;
                end
            end

            CHECK_ORIG: begin
                invert_enable <= 0;
                check_orig <= 1;
                i <= 3'b0;
                cnt <= 5'sd0;
                invalid <= 0;
                state <= LOOP_I;
            end

            SETUP_SEG: begin
                check_orig <= 0;
                l <= 3'b0;
                r <= 3'b0;
                state <= CHECK_SEG;
            end

            CHECK_SEG: begin
                invert_enable <= 1;
                i <= 3'b0;
                cnt <= 5'sd0;
                invalid <= 0;
                state <= LOOP_I;
            end

            LOOP_I: begin
                // Update cnt and invalid based on current_bracket
                cnt <= next_cnt;
                invalid <= next_invalid;
                state <= NEXT_I;
            end

            NEXT_I: begin
                i <= i + 1;
                if (i + 1 < length_reg) begin
                    state <= LOOP_I;
                end else begin
                    // Finished loop for all indices
                    if (check_orig) begin
                        state <= ORIG_DONE;
                    end else begin
                        state <= SEGMENT_DONE;
                    end
                end
            end

            ORIG_DONE: begin
                if (!invalid && (cnt == 0)) begin
                    found <= 1;
                    state <= DONE;
                end else begin
                    state <= SETUP_SEG;
                end
            end

            SEGMENT_DONE: begin
                if (!invalid && (cnt == 0)) begin
                    found <= 1;
                    state <= DONE;
                end else begin
                    state <= NEXT_R;
                end
            end

            NEXT_R: begin
                if (r + 1 < length_reg) begin
                    r <= r + 1;
                    state <= CHECK_SEG;
                end else begin
                    state <= NEXT_L;
                end
            end

            NEXT_L: begin
                if (l + 1 < length_reg) begin
                    l <= l + 1;
                    r <= l + 1; // set r to new l
                    state <= CHECK_SEG;
                end else begin
                    state <= DONE;
                end
            end

            DONE: begin
                possible <= found;
                done <= 1;
                state <= IDLE; // Return to IDLE for next test
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

