module max_minions_attack (
    input clk,
    input rst_n,
    input start,
    input [1:0] n,
    input [3:0] m,
    input [15:0] R,
    input [15:0] village_x_0, village_y_0, village_r_0,
    input [15:0] village_x_1, village_y_1, village_r_1,
    input [15:0] minion_x_0, minion_y_0,
    input [15:0] minion_x_1, minion_y_1,
    input [15:0] minion_x_2, minion_y_2,
    input [15:0] minion_x_3, minion_y_3,
    input [15:0] minion_x_4, minion_y_4,
    input [15:0] minion_x_5, minion_y_5,
    input [15:0] minion_x_6, minion_y_6,
    input [15:0] minion_x_7, minion_y_7,
    output reg [7:0] max_count,
    output reg done
);

// Parameters
localparam MAX_VILLAGES = 2;
localparam MAX_MINIONS = 8;

// States
localparam IDLE = 3'b000;
localparam CHECK_VILLAGE = 3'b001;
localparam CHECK_VILLAGE_DONE = 3'b010;
localparam COUNT_MINIONS = 3'b011;
localparam UPDATE_MAX = 3'b100;
localparam NEXT_CANDIDATE = 3'b101;
localparam DONE = 3'b110;

// Registers
reg [2:0] state;
reg [3:0] cand_idx;
reg [3:0] village_idx;
reg valid;
reg [7:0] current_count;
reg [31:0] R_sq;
reg [31:0] vr_plus_R_sq;
reg [31:0] dist_sq;
reg [15:0] dx, dy;

// Storage for inputs
reg [15:0] village_x [0:1];
reg [15:0] village_y [0:1];
reg [15:0] village_r [0:1];
reg [15:0] minion_x [0:7];
reg [15:0] minion_y [0:7];

// Combinational: cover count for current candidate
reg [3:0] cover_count;
always @(*) begin
    cover_count = 0;
    for (integer k = 0; k < MAX_MINIONS; k = k + 1) begin
        if (k < m) begin
            // Compute squared distance between cand_idx and k
            reg [15:0] dx_temp, dy_temp;
            reg [31:0] dsq_temp;
            dx_temp = (minion_x[cand_idx] > minion_x[k]) ? (minion_x[cand_idx] - minion_x[k]) : (minion_x[k] - minion_x[cand_idx]);
            dy_temp = (minion_y[cand_idx] > minion_y[k]) ? (minion_y[cand_idx] - minion_y[k]) : (minion_y[k] - minion_y[cand_idx]);
            dsq_temp = dx_temp * dx_temp + dy_temp * dy_temp;
            if (dsq_temp <= R_sq) begin
                cover_count = cover_count + 1;
            end
        end
    end
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        max_count <= 0;
        cand_idx <= 0;
        village_idx <= 0;
        valid <= 0;
        current_count <= 0;
        R_sq <= 0;
        vr_plus_R_sq <= 0;
        // Load inputs into arrays
        village_x[0] <= village_x_0; village_y[0] <= village_y_0; village_r[0] <= village_r_0;
        village_x[1] <= village_x_1; village_y[1] <= village_y_1; village_r[1] <= village_r_1;
        minion_x[0] <= minion_x_0; minion_y[0] <= minion_y_0;
        minion_x[1] <= minion_x_1; minion_y[1] <= minion_y_1;
        minion_x[2] <= minion_x_2; minion_y[2] <= minion_y_2;
        minion_x[3] <= minion_x_3; minion_y[3] <= minion_y_3;
        minion_x[4] <= minion_x_4; minion_y[4] <= minion_y_4;
        minion_x[5] <= minion_x_5; minion_y[5] <= minion_y_5;
        minion_x[6] <= minion_x_6; minion_y[6] <= minion_y_6;
        minion_x[7] <= minion_x_7; minion_y[7] <= minion_y_7;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    R_sq <= R * R;
                    cand_idx <= 0;
                    village_idx <= 0;
                    valid <= 1;
                    current_count <= 0;
                    state <= CHECK_VILLAGE;
                end
            end

            CHECK_VILLAGE: begin
                // Compute dx, dy and (vr+R)^2 for current village
                if (minion_x[cand_idx] >= village_x[village_idx])
                    dx <= minion_x[cand_idx] - village_x[village_idx];
                else
                    dx <= village_x[village_idx] - minion_x[cand_idx];
                if (minion_y[cand_idx] >= village_y[village_idx])
                    dy <= minion_y[cand_idx] - village_y[village_idx];
                else
                    dy <= village_y[village_idx] - minion_y[cand_idx];
                vr_plus_R_sq <= (village_r[village_idx] + R) * (village_r[village_idx] + R);
                state <= CHECK_VILLAGE_DONE;
            end

            CHECK_VILLAGE_DONE: begin
                dist_sq <= dx * dx + dy * dy;
                if (dist_sq < vr_plus_R_sq) begin
                    valid <= 0;
                end
                if (village_idx + 1 < n) begin
                    village_idx <= village_idx + 1;
                    state <= CHECK_VILLAGE;
                end else begin
                    if (valid) begin
                        current_count <= cover_count;
                        state <= UPDATE_MAX;
                    end else begin
                        state <= NEXT_CANDIDATE;
                    end
                end
            end

            UPDATE_MAX: begin
                if (current_count > max_count)
                    max_count <= current_count;
                state <= NEXT_CANDIDATE;
            end

            NEXT_CANDIDATE: begin
                if (cand_idx + 1 < m) begin
                    cand_idx <= cand_idx + 1;
                    village_idx <= 0;
                    valid <= 1;
                    state <= CHECK_VILLAGE;
                end else begin
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module buffet_optimizer (
    input wire clk,
    input wire rst_n,
    input wire start,
    // Discrete dish
    input wire discrete_valid,
    input wire [9:0] discrete_weight,  // 10 bits, 0-1023
    input wire [15:0] discrete_t,      // 16 bits, initial tastiness
    input wire [15:0] discrete_dt,     // 16 bits, decay
    // Continuous dish 1
    input wire cont1_valid,
    input wire [15:0] cont1_t,
    input wire [15:0] cont1_dt,
    // Continuous dish 2
    input wire cont2_valid,
    input wire [15:0] cont2_t,
    input wire [15:0] cont2_dt,
    // Target weight
    input wire [9:0] target_weight,    // 10 bits, 0-1023
    // Outputs
    output reg [63:0] result,          // Q32.32 fixed-point
    output reg done,
    output reg impossible
);

// Parameters
parameter W_WIDTH = 10;
parameter T_WIDTH = 16;
parameter RESULT_WIDTH = 64;
parameter FRAC_BITS = 32;
parameter INT_BITS = 32;

// States
typedef enum logic [2:0] {
    IDLE,
    COMPUTE_DISCRETE,
    COMPUTE_CONTINUOUS,
    UPDATE_MAX,
    DONE
} state_t;

state_t current_state, next_state;

// Internal registers
reg [9:0] max_N;            // Maximum number of discrete items
reg [9:0] N_counter;        // Current N
reg [63:0] max_total;       // Current maximum tastiness
reg [63:0] disc_tastiness;  // Tastiness for current N
reg [63:0] cont_tastiness;  // Continuous tastiness for remaining weight
reg [9:0] remaining_weight; // R = target_weight - N * discrete_weight

// Helper registers for continuous calculation
reg [63:0] lambda;          // λ in Q32.32
reg [63:0] x1, x2;          // Allocations for cont1 and cont2
reg [63:0] temp1, temp2;    // Temporary values

// Division and multiplication functions would be implemented as separate modules
// For this specification, we assume they are available as combinational blocks
// with inputs a, b and output q = a / b in Q32.32.
// In actual implementation, one would instantiate divider modules.

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
        done <= 0;
        impossible <= 0;
        result <= 0;
        N_counter <= 0;
        max_total <= 0;
        disc_tastiness <= 0;
        cont_tastiness <= 0;
        remaining_weight <= 0;
    end else begin
        case (current_state)
            IDLE: begin
                done <= 0;
                impossible <= 0;
                if (start) begin
                    if (!discrete_valid && !cont1_valid && !cont2_valid) begin
                        impossible <= 1;
                        current_state <= DONE;
                    end else begin
                        N_counter <= 0;
                        max_total <= 0;
                        // Compute max_N for discrete dish
                        if (discrete_valid && discrete_weight != 0)
                            max_N <= target_weight / discrete_weight;
                        else
                            max_N <= 0;
                        current_state <= COMPUTE_DISCRETE;
                    end
                end
            end

            COMPUTE_DISCRETE: begin
                if (N_counter <= max_N) begin
                    // Compute discrete tastiness: N*t - dt*N*(N-1)/2
                    // N*(N-1) is even, so division by 2 is exact integer
                    // We compute in fixed-point: disc_tastiness = (N * discrete_t) - (discrete_dt * N * (N-1)) / 2
                    // All values are integers, so we can compute using 64-bit arithmetic
                    // For simplicity, we assume multiplication and division by 2 are combinational
                    disc_tastiness <= (N_counter * discrete_t) - ((discrete_dt * N_counter * (N_counter - 1)) >> 1);
                    remaining_weight <= target_weight - N_counter * discrete_weight;
                    current_state <= COMPUTE_CONTINUOUS;
                end else begin
                    if (max_total == 0 && !discrete_valid && !cont1_valid && !cont2_valid)
                        impossible <= 1;
                    current_state <= DONE;
                end
            end

            COMPUTE_CONTINUOUS: begin
                if (remaining_weight >= 0) begin
                    // Compute continuous tastiness for remaining_weight R
                    // Case 1: No continuous dishes
                    if (!cont1_valid && !cont2_valid) begin
                        if (remaining_weight == 0)
                            cont_tastiness <= 0;
                        else
                            cont_tastiness <= 0; // Will be ignored as impossible
                    end
                    // Case 2: Only one continuous dish
                    else if (cont1_valid && !cont2_valid) begin
                        // cont_tastiness = cont1_t * R - (cont1_dt * R * R) / 2
                        temp1 <= cont1_t * remaining_weight;
                        temp2 <= (cont1_dt * remaining_weight * remaining_weight) >> 1;
                        cont_tastiness <= temp1 - temp2;
                    end
                    else if (!cont1_valid && cont2_valid) begin
                        temp1 <= cont2_t * remaining_weight;
                        temp2 <= (cont2_dt * remaining_weight * remaining_weight) >> 1;
                        cont_tastiness <= temp1 - temp2;
                    end
                    // Case 3: Two continuous dishes
                    else begin
                        // Use closed-form solution
                        // First, compute λ = (t1/dt1 + t2/dt2 - R) / (1/dt1 + 1/dt2)
                        // We need division: t1/dt1, t2/dt2, 1/dt1, 1/dt2.
                        // For simplicity, we assume we have combinational dividers.
                        // In implementation, one would instantiate divider modules.
                        // Here we describe the logic:
                        // Compute t1_over_dt1 = cont1_t / cont1_dt
                        // Compute t2_over_dt2 = cont2_t / cont2_dt
                        // Compute one_over_dt1 = 1 / cont1_dt
                        // Compute one_over_dt2 = 1 / cont2_dt
                        // Then numerator = t1_over_dt1 + t2_over_dt2 - remaining_weight
                        // denominator = one_over_dt1 + one_over_dt2
                        // lambda = numerator / denominator
                        // Check if lambda <= min(cont1_t, cont2_t)
                        // If yes, then x1 = (cont1_t - lambda)/cont1_dt, x2 = (cont2_t - lambda)/cont2_dt
                        // Tastiness = 0.5 * ((cont1_t^2 - lambda^2)/cont1_dt + (cont2_t^2 - lambda^2)/cont2_dt)
                        // If lambda > cont1_t, then x1=0, reduce to one continuous dish case.
                        // We would implement this with a series of states.
                        // For this specification, we assume a combinational block computes
                        // cont_tastiness given remaining_weight and the two continuous dish parameters.
                        // In testbench, we will compute the expected value in Python.
                        cont_tastiness <= 0; // Placeholder
                    end
                    current_state <= UPDATE_MAX;
                end else begin
                    N_counter <= N_counter + 1;
                    current_state <= COMPUTE_DISCRETE;
                end
            end

            UPDATE_MAX: begin
                // Update max_total if total tastiness is larger
                if (disc_tastiness + cont_tastiness > max_total) begin
                    max_total <= disc_tastiness + cont_tastiness;
                end
                N_counter <= N_counter + 1;
                current_state <= COMPUTE_DISCRETE;
            end

            DONE: begin
                done <= 1;
                result <= max_total;
            end
        endcase
    end
end

endmodule

module ski_resort (
    input clk,
    input rst_n,
    input start,
    input [63:0] reach,     // 8x8 reachability matrix: reach[i*8 + j] = 1 if node i can reach node j
    input [2:0] k_in,       // k (1-4)
    input [2:0] a_in,       // number of targets (1-8)
    input [23:0] t_in,      // packed targets: each 3 bits, 0-indexed. First a_in are valid.
    output reg [15:0] result,
    output reg done
);

    // Parameters
    parameter N = 8;         // Number of nodes (fixed)
    parameter MAX_MASK = 256; // 2^8

    // Internal registers
    reg [63:0] reach_reg;
    reg [2:0] k_reg;
    reg [2:0] a_reg;
    reg [23:0] t_reg;
    reg [7:0] mask_counter;  // current mask being tested
    reg [15:0] result_reg;
    reg done_reg;
    reg [3:0] state;
    reg [2:0] target_idx;    // index for iterating targets
    reg [3:0] node_idx;      // index for iterating nodes
    reg [7:0] anc_masks [0:7]; // ancestor masks for each target (up to 8)
    reg [7:0] combined_anc;  // OR of all anc_masks
    reg [7:0] current_mask;  // mask being checked
    reg [3:0] popcnt;        // popcount of current_mask
    reg valid_flag;          // flag for current mask validity
    reg [2:0] inner_idx;     // generic index for inner loops

    // Function to compute popcount of 8-bit value
    function [3:0] popcount8;
        input [7:0] mask;
        begin
            popcount8 = 0;
            for (integer i = 0; i < 8; i = i + 1) begin
                popcount8 = popcount8 + mask[i];
            end
        end
    endfunction

    // State definitions
    localparam S_IDLE = 0;
    localparam S_LOAD = 1;
    localparam S_COMP_ANC = 2;   // Compute ancestor masks
    localparam S_INIT_ENUM = 3;
    localparam S_ENUM_LOOP = 4;  // Check popcount and subset condition
    localparam S_CHECK_TARGETS = 5; // Check each target condition
    localparam S_VALID = 6;
    localparam S_NEXT = 7;
    localparam S_DONE = 8;

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            done_reg <= 0;
            result_reg <= 0;
            mask_counter <= 0;
            reach_reg <= 0;
            k_reg <= 0;
            a_reg <= 0;
            t_reg <= 0;
            current_mask <= 0;
            target_idx <= 0;
            node_idx <= 0;
            inner_idx <= 0;
            valid_flag <= 0;
            combined_anc <= 0;
            // Clear anc_masks
            for (integer i = 0; i < 8; i = i + 1) begin
                anc_masks[i] <= 0;
            end
        end else begin
            case (state)
                S_IDLE: begin
                    done_reg <= 0;
                    if (start) begin
                        state <= S_LOAD;
                    end
                end

                S_LOAD: begin
                    reach_reg <= reach;
                    k_reg <= k_in;
                    a_reg <= a_in;
                    t_reg <= t_in;
                    state <= S_COMP_ANC;
                    // Initialize for ancestor mask computation
                    target_idx <= 0;
                    node_idx <= 0;
                    combined_anc <= 0;
                    for (integer i = 0; i < 8; i = i + 1) begin
                        anc_masks[i] <= 0;
                    end
                end

                S_COMP_ANC: begin
                    if (target_idx < a_reg) begin
                        // Compute ancestor mask for current target
                        if (node_idx < 8) begin
                            // Extract target value (0-indexed)
                            // t_reg[target_idx*3 +: 3] gives the target node number
                            // Check reachability from node_idx to target
                            if (reach_reg[node_idx*8 + t_reg[target_idx*3 +: 3]]) begin
                                anc_masks[target_idx][node_idx] <= 1;
                            end else begin
                                anc_masks[target_idx][node_idx] <= 0;
                            end
                            node_idx <= node_idx + 1;
                        end else begin
                            // Finished this target
                            combined_anc <= combined_anc | anc_masks[target_idx];
                            target_idx <= target_idx + 1;
                            node_idx <= 0;
                        end
                    end else begin
                        // All targets processed
                        state <= S_INIT_ENUM;
                    end
                end

                S_INIT_ENUM: begin
                    mask_counter <= 8'b00000001; // start from mask=1 (skip zero)
                    result_reg <= 0;
                    state <= S_ENUM_LOOP;
                end

                S_ENUM_LOOP: begin
                    if (mask_counter == 8'b00000000) begin // wrapped around after 255
                        state <= S_DONE;
                    end else begin
                        // Check conditions 1 and 2
                        popcnt <= popcount8(mask_counter);
                        // Condition 1: popcount == k_reg
                        // Condition 2: mask is subset of combined_anc (mask & ~combined_anc == 0)
                        if (popcount8(mask_counter) == k_reg && 
                            ((mask_counter & ~combined_anc) == 8'b0)) begin
                            // Conditions passed, now check each target
                            current_mask <= mask_counter;
                            target_idx <= 0;
                            valid_flag <= 1;
                            state <= S_CHECK_TARGETS;
                        end else begin
                            // Skip to next mask
                            state <= S_NEXT;
                        end
                    end
                end

                S_CHECK_TARGETS: begin
                    if (target_idx >= a_reg) begin
                        // All targets checked and passed
                        state <= S_VALID;
                    end else begin
                        // Check popcount of (current_mask & anc_masks[target_idx])
                        if (popcount8(current_mask & anc_masks[target_idx]) != 4'd1) begin
                            valid_flag <= 0;
                            state <= S_NEXT; // skip to next mask
                        end else begin
                            target_idx <= target_idx + 1;
                            state <= S_CHECK_TARGETS;
                        end
                    end
                end

                S_VALID: begin
                    result_reg <= result_reg + 1;
                    state <= S_NEXT;
                end

                S_NEXT: begin
                    if (mask_counter == 8'b11111111) begin
                        state <= S_DONE;
                    end else begin
                        mask_counter <= mask_counter + 1;
                        state <= S_ENUM_LOOP;
                    end
                end

                S_DONE: begin
                    result <= result_reg;
                    done_reg <= 1;
                    state <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

    assign done = done_reg;

endmodule

module clock_setting (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] orig_time_h,  // original hours (00-23)
    input wire [7:0] orig_time_m,  // original minutes (00-59)
    input wire [7:0] target_time_h, // target hours (00-23)
    input wire [7:0] target_time_m, // target minutes (00-59)
    output reg [7:0] current_time_h,
    output reg [7:0] current_time_m,
    output reg valid,
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam CHANGE_MINUTE_ONES = 3'b001;
    localparam CHANGE_MINUTE_TENS = 3'b010;
    localparam CHANGE_HOUR_ONES = 3'b011;
    localparam CHANGE_HOUR_TENS = 3'b100;
    localparam FINISHED = 3'b101;

    reg [2:0] state;
    reg [2:0] next_state;

    // Current values being adjusted
    reg [7:0] current_h;
    reg [7:0] current_m;
    reg [7:0] target_h;
    reg [7:0] target_m;

    // Helper: increment digit with wrap
    function [3:0] inc_digit;
        input [3:0] digit;
        begin
            inc_digit = (digit == 9) ? 0 : digit + 1;
        end
    endfunction

    // Helper: check if time is valid
    function is_valid_time;
        input [7:0] hours;
        input [7:0] minutes;
        begin
            is_valid_time = (hours < 24) && (minutes < 60);
        end
    endfunction

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            current_h <= 8'b0;
            current_m <= 8'b0;
            target_h <= 8'b0;
            target_m <= 8'b0;
            valid <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    if (start) begin
                        current_h <= orig_time_h;
                        current_m <= orig_time_m;
                        target_h <= target_time_h;
                        target_m <= target_time_m;
                        valid <= 1'b1;
                        done <= 1'b0;
                    end else begin
                        valid <= 1'b0;
                    end
                end

                CHANGE_MINUTE_ONES: begin
                    // Increment minute ones digit
                    if (current_m[3:0] != target_m[3:0]) begin
                        current_m[3:0] <= inc_digit(current_m[3:0]);
                        if (is_valid_time(current_h, current_m)) begin
                            valid <= 1'b1;
                        end else begin
                            valid <= 1'b0;
                        end
                    end else begin
                        valid <= 1'b0;
                    end
                end

                CHANGE_MINUTE_TENS: begin
                    // Increment minute tens digit
                    if (current_m[7:4] != target_m[7:4]) begin
                        current_m[7:4] <= inc_digit(current_m[7:4]);
                        if (is_valid_time(current_h, current_m)) begin
                            valid <= 1'b1;
                        end else begin
                            valid <= 1'b0;
                        end
                    end else begin
                        valid <= 1'b0;
                    end
                end

                CHANGE_HOUR_ONES: begin
                    // Increment hour ones digit
                    if (current_h[3:0] != target_h[3:0]) begin
                        current_h[3:0] <= inc_digit(current_h[3:0]);
                        if (is_valid_time(current_h, current_m)) begin
                            valid <= 1'b1;
                        end else begin
                            valid <= 1'b0;
                        end
                    end else begin
                        valid <= 1'b0;
                    end
                end

                CHANGE_HOUR_TENS: begin
                    // Increment hour tens digit
                    if (current_h[7:4] != target_h[7:4]) begin
                        current_h[7:4] <= inc_digit(current_h[7:4]);
                        if (is_valid_time(current_h, current_m)) begin
                            valid <= 1'b1;
                        end else begin
                            valid <= 1'b0;
                        end
                    end else begin
                        valid <= 1'b0;
                    end
                end

                FINISHED: begin
                    done <= 1'b1;
                    valid <= 1'b0;
                end
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) begin
                    // Always output the original time first
                    next_state = CHANGE_MINUTE_ONES;
                end
            end

            CHANGE_MINUTE_ONES: begin
                if (current_m[3:0] == target_m[3:0]) begin
                    next_state = CHANGE_MINUTE_TENS;
                end
            end

            CHANGE_MINUTE_TENS: begin
                if (current_m[7:4] == target_m[7:4]) begin
                    next_state = CHANGE_HOUR_ONES;
                end
            end

            CHANGE_HOUR_ONES: begin
                if (current_h[3:0] == target_h[3:0]) begin
                    next_state = CHANGE_HOUR_TENS;
                end
            end

            CHANGE_HOUR_TENS: begin
                if (current_h[7:4] == target_h[7:4]) begin
                    next_state = FINISHED;
                end
            end

            FINISHED: begin
                next_state = FINISHED;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output assignments
    always @(posedge clk) begin
        current_time_h <= current_h;
        current_time_m <= current_m;
    end

endmodule

module shortest_path_edge_counter (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Graph configuration interface
    input wire [3:0] config_edge_index,  // Edge ID: 0 to 15
    input wire [3:0] config_src,         // Source city: 0 to 7
    input wire [3:0] config_dst,         // Destination city: 0 to 7  
    input wire [15:0] config_weight,     // Edge weight: 0 to 65535
    input wire config_valid,             // Write edge to memory
    input wire [3:0] num_edges,          // Total edges (1 to 8)

    // Computation control
    input wire compute_start,            // Pulse high to start computation

    // Result output
    output reg [3:0] result_edge_index,  // Which edge this result is for
    output reg [31:0] result_count,      // Number of shortest paths containing this edge
    output reg result_valid,             // Result is valid
    output reg done                      // All results computed
);

// Parameters
parameter MAX_CITIES = 8;
parameter MAX_EDGES = 16;
parameter MODULUS = 1000000007;

// Memory for graph data (packed edge format)
reg [23:0] edge_memory [0:15];  // {src[3:0], dst[3:0], weight[15:0]}

// State machine states
typedef enum logic [3:0] {
    IDLE,
    LOAD_EDGES,
    COMPUTE_FLOYD,
    COUNT_PATHS,
    OUTPUT_RESULTS,
    FINISHED
} state_t;

state_t current_state, next_state;

// Floyd-Warshall matrices (using 8x8 arrays)
reg [31:0] dist [0:7][0:7];      // Shortest distances
reg [31:0] paths [0:7][0:7];     // Number of shortest paths

// Iteration counters
reg [2:0] i, j, k;  // For Floyd-Warshall loops
reg [3:0] edge_idx; // For counting and output

// Helper: extract fields from packed edge
wire [3:0] edge_src = edge_memory[edge_idx][23:20];
wire [3:0] edge_dst = edge_memory[edge_idx][19:16];
wire [15:0] edge_w = edge_memory[edge_idx][15:0];

// Modulo addition helper
function automatic [31:0] mod_add;
    input [31:0] a, b;
    begin
        mod_add = (a + b) % MODULUS;
    end
endfunction

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end

// Next state logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        IDLE: begin
            if (compute_start && num_edges > 0)
                next_state = COMPUTE_FLOYD;
            else if (config_valid)
                next_state = LOAD_EDGES;
        end

        LOAD_EDGES: begin
            if (!config_valid && compute_start)
                next_state = COMPUTE_FLOYD;
            else
                next_state = LOAD_EDGES;
        end

        COMPUTE_FLOYD: begin
            if (i == 0 && j == 0 && k == 0)
                next_state = COUNT_PATHS;  // Floyd-Warshall complete
            else
                next_state = COMPUTE_FLOYD;
        end

        COUNT_PATHS: begin
            if (edge_idx >= num_edges)
                next_state = OUTPUT_RESULTS;
            else
                next_state = COUNT_PATHS;
        end

        OUTPUT_RESULTS: begin
            if (edge_idx >= num_edges)
                next_state = FINISHED;
            else
                next_state = OUTPUT_RESULTS;
        end

        FINISHED: begin
            next_state = IDLE;
        end
    endcase
end

// Output logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        result_edge_index <= 0;
        result_count <= 0;
        result_valid <= 0;
        done <= 0;
        i <= 0; j <= 0; k <= 0;
        edge_idx <= 0;
        // Reset distance and path matrices
        for (int x = 0; x < 8; x++) begin
            for (int y = 0; y < 8; y++) begin
                dist[x][y] <= (x == y) ? 0 : 32'hFFFF_FFFF;
                paths[x][y] <= (x == y) ? 1 : 0;
            end
        end
    end else begin
        case (current_state)
            IDLE: begin
                result_valid <= 0;
                done <= 0;
                edge_idx <= 0;
                i <= 0; j <= 0; k <= 0;
                if (config_valid) begin
                    edge_memory[config_edge_index] <= {config_src, config_dst, config_weight};
                end
            end

            LOAD_EDGES: begin
                if (config_valid) begin
                    edge_memory[config_edge_index] <= {config_src, config_dst, config_weight};
                end
            end

            COMPUTE_FLOYD: begin
                // Initialize edges on first iteration
                if (i == 0 && j == 0 && k == 0) begin
                    // Load edges from memory into dist matrix
                    for (int e = 0; e < 16; e++) begin
                        if (e < num_edges) begin
                            automatic reg [3:0] s = edge_memory[e][23:20];
                            automatic reg [3:0] d = edge_memory[e][19:16];
                            automatic reg [15:0] w = edge_memory[e][15:0];
                            if (w < dist[s][d]) begin
                                dist[s][d] <= w;
                                paths[s][d] <= 1;
                            end else if (w == dist[s][d]) begin
                                paths[s][d] <= paths[s][d] + 1;
                            end
                        end
                    end
                    i <= 1; j <= 0; k <= 0;
                end else begin
                    // Floyd-Warshall: dist[k][i] + dist[i][j] < dist[k][j]
                    if (k < 8 && i < 8 && j < 8) begin
                        automatic reg [31:0] new_dist = dist[k][i] + dist[i][j];
                        automatic reg [31:0] cur_dist = dist[k][j];

                        if (dist[k][i] != 32'hFFFF_FFFF && dist[i][j] != 32'hFFFF_FFFF) begin
                            if (new_dist < cur_dist) begin
                                dist[k][j] <= new_dist;
                                paths[k][j] <= paths[k][i];
                            end else if (new_dist == cur_dist) begin
                                paths[k][j] <= mod_add(paths[k][j], paths[k][i]);
                            end
                        end

                        // Increment counters
                        if (j == 7) begin
                            j <= 0;
                            if (i == 7) begin
                                i <= 0;
                                if (k == 7) begin
                                    k <= 0;  // Will trigger transition
                                end else begin
                                    k <= k + 1;
                                end
                            end else begin
                                i <= i + 1;
                            end
                        end else begin
                            j <= j + 1;
                        end
                    end
                end
            end

            COUNT_PATHS: begin
                if (edge_idx < num_edges) begin
                    // For each edge, count shortest paths that use it
                    // Count = sum_{u,v} (paths[u][src] * paths[dst][v]) for shortest paths using this edge
                    automatic reg [3:0] s = edge_memory[edge_idx][23:20];
                    automatic reg [3:0] d = edge_memory[edge_idx][19:16];
                    automatic reg [15:0] w = edge_memory[edge_idx][15:0];

                    // Check if this edge can be part of any shortest path
                    // For all pairs (u,v), if dist[u][s] + w + dist[d][v] == dist[u][v], then add paths[u][s] * paths[d][v]
                    automatic reg [31:0] count = 0;

                    for (int u = 0; u < 8; u++) begin
                        for (int v = 0; v < 8; v++) begin
                            if (u != v && dist[u][s] != 32'hFFFF_FFFF && dist[d][v] != 32'hFFFF_FFFF) begin
                                automatic reg [31:0] total_dist = dist[u][s] + w + dist[d][v];
                                if (total_dist == dist[u][v]) begin
                                    count = mod_add(count, (paths[u][s] * paths[d][v]) % MODULUS);
                                end
                            end
                        end
                    end

                    result_edge_index <= edge_idx;
                    result_count <= count;
                    result_valid <= 1;
