import cocotb
from cocotb.triggers import Timer, RisingEdge, FallingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Configuration
MOD = 10**9 + 7
MAX_DIGITS = 16

# Helper functions
def is_value_defined(value):
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    try:
        return int(value)
    except ValueError:
        return default

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def to_signed(val, bits):
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

def clamp_to_width(value, bits):
    max_val = (1 << bits) - 1
    return min(max_val, max(0, value))

# Convert integer to BCD digits (16 digits)
def int_to_bcd(num, digits=MAX_DIGITS):
    s = str(num).zfill(digits)
    return [int(c) for c in s]

# Check if a number is valid according to rules
def is_number_valid(num):
    s = str(num)
    # No digit 4
    if '4' in s:
        return False
    # Count 6 and 8
    count_68 = sum(1 for c in s if c in '68')
    # Count other digits (excluding 4, and we know 4 isn't present)
    count_other = len(s) - count_68
    return count_68 == count_other

# Count valid numbers in range [1, n]
def count_valid_upto(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, n + 1):
        if is_number_valid(i):
            count += 1
    return count

