    reg [7:0] edge_flow [0:MAX_M*MAX_K-1];   // Current flow
    reg [15:0] edge_count;

    // Producers at N tracking
    reg [MAX_K-1:0] producers_at_n;
    reg [7:0] producer_count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            flow_result <= 0;
            edge_count <= 0;
            producer_count <= 0;
            producers_at_n <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= BUILD_GRAPH;
                        edge_count <= 0;
                        producer_count <= 0;
