def compute_expected(n, m, s, t, a, b, employees, clients, edges):
    INF = 10**12
    dist = [[INF]*n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, d in edges:
        u0 = u-1
        v0 = v-1
        if d < dist[u0][v0]:
            dist[u0][v0] = d
            dist[v0][u0] = d
    for k in range(n):
        for i in range(n):
            if dist[i][k] == INF:
                continue
            for j in range(n):
                if dist[k][j] == INF:
                    continue
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    a0 = a-1
    b0 = b-1
    cost = [[0]*t for _ in range(s)]
    for i in range(s):
        e0 = employees[i]-1
        dA_e = dist[a0][e0]
        dB_e = dist[b0][e0]
        for j in range(t):
            c0 = clients[j]-1
            dA_c = dist[a0][c0]
            dB_c = dist[b0][c0]
            cost[i][j] = min(dA_e + dA_c, dB_e + dB_c)
    dp = [[INF]*(1<<s) for _ in range(t+1)]
    dp[0][0] = 0
    for j in range(t):
        for mask in range(1<<s):
            if dp[j][mask] == INF:
                continue
            for i in range(s):
                if not (mask & (1<<i)):
                    new_mask = mask | (1<<i)
                    new_cost = dp[j][mask] + cost[i][j]
                    if new_cost < dp[j+1][new_mask]:
                        dp[j+1][new_mask] = new_cost
    ans = INF
    for mask in range(1<<s):
        if bin(mask).count('1') == t:
            if dp[t][mask] < ans:
                ans = dp[t][mask]
    return ans

