module matrix_recovery (
    input clk, rst_n, start,
    input [3:0] n, m,  // Matrix dimensions (max 8x8)
    input [7:0] row_parity,  // Row parities (up to 8 bits)
    input [7:0] col_parity,  // Column parities (up to 8 bits)
    output reg [7:0] matrix_out [0:7],  // Output 8x8 matrix (only first n rows and m columns are valid)
    output reg done,
    output reg error
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam CHECK = 3'b001;
    localparam INITIALIZE = 3'b010;
    localparam FIX_PARITY = 3'b011;
    localparam DONE = 3'b100;
    localparam ERROR = 3'b101;

    // Internal registers
    reg [2:0] state, next_state;
    reg [2:0] row_idx, col_idx;  // Current row and column being processed
    reg [7:0] matrix [0:7];      // 8x8 matrix storage
    reg [7:0] row_parity_check;  // Computed row parities
    reg [7:0] col_parity_check;  // Computed column parities
    reg [2:0] flip_count;        // Count of flips needed
    reg [2:0] flip_row, flip_col; // Row and column for flipping

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            error <= 0;
            row_idx <= 0;
            col_idx <= 0;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) next_state = CHECK;
            end

            CHECK: begin
                // Check if XOR condition is satisfied
                if (^row_parity[0+:8] != ^col_parity[0+:8])
                    next_state = ERROR;
                else
                    next_state = INITIALIZE;
            end

            INITIALIZE: begin
                // Initialize matrix with all 1s
                if (row_idx < n) begin
                    next_state = INITIALIZE;
                end else begin
                    next_state = FIX_PARITY;
                end
            end

            FIX_PARITY: begin
                // Fix parity mismatches by flipping bits to 0
                if (row_idx < n && col_idx < m) begin
                    next_state = FIX_PARITY;
                end else if (row_idx >= n && col_idx >= m) begin
                    // Check if all parities are now satisfied
                    if (row_parity_check[0+:n] == row_parity[0+:n] && 
                        col_parity_check[0+:m] == col_parity[0+:m])
                        next_state = DONE;
                    else
                        next_state = ERROR;
                end else begin
                    next_state = FIX_PARITY;
                end
            end

            DONE, ERROR: begin
                next_state = DONE;  // Stay in done/error state
            end

            default: next_state = IDLE;
        endcase
    end

    // Main logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers
            done <= 0;
            error <= 0;
            row_idx <= 0;
            col_idx <= 0;
            flip_count <= 0;
            flip_row <= 0;
            flip_col <= 0;
            // Initialize matrix to 0
            for (integer i = 0; i < 8; i = i + 1) begin
                matrix[i] <= 8'h00;
            end
        end else begin
            case (state)
                CHECK: begin
                    // Initialize row and column parity checks
                    row_parity_check <= 8'h00;
                    col_parity_check <= 8'h00;
                    row_idx <= 0;
                    col_idx <= 0;
                end

                INITIALIZE: begin
                    // Fill matrix with 1s, row by row
                    if (row_idx < n) begin
                        // Set all bits in current row to 1 (for valid columns)
                        if (col_idx < m) begin
                            matrix[row_idx][col_idx] <= 1'b1;
                            col_idx <= col_idx + 1;
                        end else begin
                            col_idx <= 0;
                            row_idx <= row_idx + 1;
                        end
                    end else begin
                        // Reset indices for next phase
                        row_idx <= 0;
                        col_idx <= 0;
                        // Compute initial parities
                        for (integer i = 0; i < n; i = i + 1) begin
                            row_parity_check[i] <= ^matrix[i][0+:m];
                        end
                        for (integer j = 0; j < m; j = j + 1) begin
                            col_parity_check[j] <= ^{matrix[0][j], matrix[1][j], matrix[2][j], matrix[3][j], 
                                                      matrix[4][j], matrix[5][j], matrix[6][j], matrix[7][j]};
                        end
                    end
                end

                FIX_PARITY: begin
                    // Find and fix parity mismatches by flipping bits to 0
                    // Strategy: Start from bottom-right to minimize binary value
                    if (row_idx < n && col_idx < m) begin
                        // Calculate current row and column indices (starting from bottom-right)
                        integer current_row = n - 1 - row_idx;
                        integer current_col = m - 1 - col_idx;

                        // Check if this bit needs to be flipped
                        if (current_row >= 0 && current_col >= 0 && 
                            row_parity_check[current_row] != row_parity[current_row] &&
                            col_parity_check[current_col] != col_parity[current_col]) begin
                            // Flip bit to 0
                            matrix[current_row][current_col] <= 1'b0;
                            // Update parity checks
                            row_parity_check[current_row] <= ~row_parity_check[current_row];
                            col_parity_check[current_col] <= ~col_parity_check[current_col];
                        end

                        // Move to next position
                        if (col_idx < m - 1) begin
                            col_idx <= col_idx + 1;
                        end else begin
                            col_idx <= 0;
                            row_idx <= row_idx + 1;
                        end
                    end else if (row_idx < n) begin
                        // Process remaining rows
                        row_idx <= row_idx + 1;
                    end else if (col_idx < m) begin
                        // Process remaining columns
                        col_idx <= col_idx + 1;
                    end
                end

                DONE: begin
                    done <= 1;
                    error <= 0;
                    // Output the matrix
                    for (integer i = 0; i < 8; i = i + 1) begin
                        matrix_out[i] <= matrix[i];
                    end
                end

                ERROR: begin
                    done <= 1;
                    error <= 1;
                    // Output all zeros in case of error
                    for (integer i = 0; i < 8; i = i + 1) begin
                        matrix_out[i] <= 8'h00;
                    end
                end
            endcase
        end
    end
endmodule

module pharmacy (
    input clk, rst_n, start,
    input load_enable,
    input [31:0] load_drop_time,
    input load_type,           // 1 for S, 0 for R
    input [8:0] load_fill_time,
    input load_done,
    output reg [63:0] sum_S,   // Sum of completion times for in-store
    output reg [63:0] sum_R,   // Sum of completion times for remote
    output reg [31:0] count_S, // Count of in-store prescriptions
    output reg [31:0] count_R, // Count of remote prescriptions
    output reg done
);

// Parameters
parameter N = 16;  // Max prescriptions
parameter T = 4;   // Max technicians

// Internal registers for prescription data
reg [31:0] drop_time [0:N-1];
reg type_reg [0:N-1];           // 1 for S, 0 for R
reg [8:0] fill_time [0:N-1];
reg [4:0] load_count;           // Number of loaded prescriptions

// State machine
localparam IDLE = 3'b000;
localparam LOAD = 3'b001;
localparam SORT = 3'b010;
localparam SCHEDULE = 3'b011;
localparam DONE = 3'b100;
reg [2:0] state, next_state;

// Sorting state
reg [4:0] sort_pass;
reg [4:0] sort_index;
reg sort_swapped;
reg [31:0] temp_drop;
reg temp_type;
reg [8:0] temp_fill;

// Scheduling state
reg [4:0] sched_index;          // Current prescription in sorted list
reg [31:0] tech_free_time [0:T-1]; // When each technician is free
wire [31:0] min_free_time;      // Combinational: minimum free time
wire [1:0] min_tech;            // Combinational: technician with min free time

// Helper signals
integer i;
reg [31:0] completion_time;
reg [31:0] delay;

// Combinational logic to find minimum free time and technician
assign min_free_time = tech_free_time[0];
assign min_tech = 0;
generate
    genvar g;
    for (g = 1; g < T; g = g + 1) begin : find_min
        wire [31:0] candidate_free = tech_free_time[g];
        wire [1:0] candidate_tech = g;
    end
endgenerate

// Sequential logic for finding minimum
always @(*) begin
    min_free_time = tech_free_time[0];
    min_tech = 0;
    for (i = 1; i < T; i = i + 1) begin
        if (tech_free_time[i] < min_free_time) begin
            min_free_time = tech_free_time[i];
            min_tech = i;
        end
    end
end

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else state <= next_state;
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = LOAD;
        LOAD: if (load_done) next_state = SORT;
        SORT: if (sort_pass >= load_count - 1 || !sort_swapped) next_state = SCHEDULE;
        SCHEDULE: if (sched_index >= load_count) next_state = DONE;
        DONE: next_state = DONE;
    endcase
end

// Load logic
always @(posedge clk) begin
    if (state == LOAD && load_enable && load_count < N) begin
        drop_time[load_count] <= load_drop_time;
        type_reg[load_count] <= load_type;
        fill_time[load_count] <= load_fill_time;
        load_count <= load_count + 1;
    end else if (state == IDLE) begin
        load_count <= 0;
    end
end

// Bubble sort
wire sort_done = (sort_pass >= load_count - 1) || !sort_swapped;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sort_pass <= 0;
        sort_index <= 0;
        sort_swapped <= 0;
    end else if (state == SORT) begin
        if (sort_index >= load_count - 1 - sort_pass) begin
            // End of pass
            if (!sort_swapped) sort_pass <= load_count;  // Done if no swaps
            else begin
                sort_pass <= sort_pass + 1;
                sort_index <= 0;
                sort_swapped <= 0;
            end
        end else begin
            // Compare and swap if needed
            if (should_swap(sort_index, sort_index + 1)) begin
                // Swap
                drop_time[sort_index] <= drop_time[sort_index + 1];
                type_reg[sort_index] <= type_reg[sort_index + 1];
                fill_time[sort_index] <= fill_time[sort_index + 1];
                drop_time[sort_index + 1] <= drop_time[sort_index];
                type_reg[sort_index + 1] <= type_reg[sort_index];
                fill_time[sort_index + 1] <= fill_time[sort_index];
                sort_swapped <= 1;
            end
            sort_index <= sort_index + 1;
        end
    end else begin
        sort_pass <= 0;
        sort_index <= 0;
        sort_swapped <= 0;
    end
end

// Compare function for sorting
function should_swap;
    input [4:0] i, j;
    begin
        should_swap = 0;
        // Compare drop_time
        if (drop_time[i] > drop_time[j]) should_swap = 1;
        else if (drop_time[i] == drop_time[j]) begin
            // Compare type (S first, then R)
            if (type_reg[i] < type_reg[j]) should_swap = 1;  // S=1, R=0, so 0<1 means R<S -> swap
            else if (type_reg[i] == type_reg[j]) begin
                // Compare fill_time (shorter first)
                if (fill_time[i] > fill_time[j]) should_swap = 1;
            end
        end
    end
endfunction

// Scheduling logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sched_index <= 0;
        tech_free_time[0] <= 0;
        tech_free_time[1] <= 0;
        tech_free_time[2] <= 0;
        tech_free_time[3] <= 0;
        sum_S <= 0;
        sum_R <= 0;
        count_S <= 0;
        count_R <= 0;
    end else if (state == SCHEDULE) begin
        if (sched_index < load_count) begin
            // Compute completion time
            completion_time <= (drop_time[sched_index] > min_free_time) ? 
                              (drop_time[sched_index] + fill_time[sched_index]) : 
                              (min_free_time + fill_time[sched_index]);
            delay <= (drop_time[sched_index] > min_free_time) ? 
                    fill_time[sched_index] : 
                    (min_free_time - drop_time[sched_index] + fill_time[sched_index]);

            // Update sums and counts in next cycle
            if (type_reg[sched_index] == 1'b1) begin  // S
                sum_S <= sum_S + delay;
                count_S <= count_S + 1;
            end else begin  // R
                sum_R <= sum_R + delay;
                count_R <= count_R + 1;
            end

            // Update technician free time
            tech_free_time[min_tech] <= completion_time;

            sched_index <= sched_index + 1;
        end
    end else if (state != SCHEDULE) begin
        sched_index <= 0;
    end
end

// Done signal
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) done <= 0;
    else if (state == DONE) done <= 1;
    else done <= 0;
end

endmodule

module multiple_counter (
    input clk,
    input rst_n,
    input start,
    input [15:0] X,        // Multiplier (scaled to 16-bit)
    input [15:0] A,        // Lower bound (scaled to 16-bit)
    input [15:0] B,        // Upper bound (scaled to 16-bit)
    input [9:0] allowed_mask, // Bitmask for allowed digits (bit d = 1 if digit d allowed)
    output reg [15:0] count,
    output reg done
);

// State encoding
localparam IDLE = 3'b000;
localparam CHECK = 3'b001;
localparam CHECK_DIGITS = 3'b010;
localparam EXTRACT_DIGIT = 3'b011;
localparam COUNT = 3'b100;
localparam INCREMENT = 3'b101;
localparam DONE = 3'b110;

// Internal registers
reg [2:0] state;
reg [15:0] current;      // Current number being checked
reg [15:0] rem;          // (current mod X)
reg [15:0] temp_count;   // Accumulated count
reg [15:0] temp_num;     // Temporary number for digit extraction
reg valid;               // Flag for valid digit sequence

// Combinational helpers
wire [3:0] next_digit;
wire [15:0] next_temp_num;
wire [15:0] rem_next;

assign next_digit = temp_num % 10;
assign next_temp_num = temp_num / 10;
assign rem_next = (rem + 1 < X) ? rem + 1 : 0;

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        current <= 0;
        rem <= 0;
        temp_count <= 0;
        temp_num <= 0;
        valid <= 0;
        done <= 0;
        count <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    current <= A;
                    rem <= A % X;  // Initial remainder
                    temp_count <= 0;
                    state <= CHECK;
                end
            end

            CHECK: begin
                if (current > B) begin
                    count <= temp_count;
                    state <= DONE;
                end else if (rem == 0) begin
                    // Current is multiple of X
                    state <= CHECK_DIGITS;
                end else begin
                    state <= INCREMENT;
                end
            end

            CHECK_DIGITS: begin
                valid <= 1;
                if (current == 0) begin
                    // Handle zero case
                    if (allowed_mask[0]) state <= COUNT;
                    else state <= INCREMENT;
                end else begin
                    temp_num <= current;
                    state <= EXTRACT_DIGIT;
                end
            end

            EXTRACT_DIGIT: begin
                if (allowed_mask[next_digit] == 0) begin
                    valid <= 0;
                    state <= INCREMENT;  // Skip invalid number
                end else begin
                    temp_num <= next_temp_num;
                    if (next_temp_num == 0) begin
                        if (valid) state <= COUNT;
                        else state <= INCREMENT;
                    end else begin
                        state <= EXTRACT_DIGIT;
                    end
                end
            end

            COUNT: begin
                temp_count <= temp_count + 1;
                state <= INCREMENT;
            end

            INCREMENT: begin
                current <= current + 1;
                rem <= rem_next;
                state <= CHECK;
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module square_difference (
    input wire [31:0] n,
    output reg [31:0] m,
    output reg [31:0] k,
    output reg valid
);
    // Combinational logic
    always @(*) begin
        if (n[0]) begin // odd
            m = (n + 1) >> 1;
            k = (n - 1) >> 1;
            valid = 1;
        end else if (n[1:0] == 2'b00) begin // divisible by 4
            m = (n >> 2) + 1;
            k = (n >> 2) - 1;
            valid = 1;
        end else begin
            m = 0;
            k = 0;
            valid = 0;
        end
    end
endmodule

