            compute_done <= 0;
            cycle_detected <= 0;
        end else begin
            case (state)
                STATE_IDLE: begin
                    done <= 0;
                    inf <= 0;
                    if (graph_write_en) begin
                        // Update adjacency matrix if cnt != 0
                        if (cnt != 4'b0) begin
                            adj[src][dst] <= cnt;
                        end
                        state <= STATE_CONFIG;
                    end else if (start) begin
                        // Start computation
                        state <= STATE_COMPUTE;
                        // Initialize computation registers
                        reachable <= 8'b0;
                        topo_count <= 3'b0;
                        compute_done <= 0;
                        cycle_detected <= 0;
                    end
                end

                STATE_CONFIG: begin
                    // Wait for graph_write_en to de-assert
                    if (!graph_write_en) begin
                        state <= STATE_IDLE;
                    end
                end

                STATE_COMPUTE: begin
                    if (!compute_done) begin
                        // --- Step 1: Compute reachable nodes from start (node 0) ---
