);

// Parameters
parameter MAX_PEOPLE = 8;
localparam BALANCE_WIDTH = 32;
localparam RESULT_WIDTH = 4;
localparam STATE_WIDTH = 5;

// State definitions
localparam S_IDLE = 0,
           S_PROCESS_RECEIPTS = 1,
           S_COUNT_NONZERO = 2,
           S_COMPONENT_START = 3,
           S_COMPONENT_LOOP = 4,
           S_COMPONENT_PROPAGATE_INIT = 5,
           S_COMPONENT_PROPAGATE_LOOP = 6,
           S_COMPONENT_PROPAGATE_J = 7,
           S_COMPONENT_PROPAGATE_K = 8,
           S_COMPONENT_PROPAGATE_J_INC = 9,
           S_COMPONENT_NEXT_I = 10,
           S_COMPUTE_RESULT = 11,
           S_DONE = 12;

// Registers
reg [STATE_WIDTH-1:0] state, next_state;
reg [BALANCE_WIDTH-1:0] balance [0:MAX_PEOPLE-1];
reg [MAX_PEOPLE-1:0] adjacency [0:MAX_PEOPLE-1]; // 8x8 matrix
reg [MAX_PEOPLE-1:0] visited;
reg [RESULT_WIDTH-1:0] non_zero_count;
reg [RESULT_WIDTH-1:0] component_count;
reg [2:0] i, j, k; // counters
reg changed; // for propagation
reg [RESULT_WIDTH-1:0] result_reg;
reg done_reg;

// Integer for loops
integer idx;

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done_reg <= 0;
        result_reg <= 0;
        non_zero_count <= 0;
        component_count <= 0;
        visited <= 0;
        changed <= 0;
        i <= 0;
        j <= 0;
        k <= 0;
        // Reset balance and adjacency
        for (idx = 0; idx < MAX_PEOPLE; idx = idx + 1) begin
            balance[idx] <= 0;
            adjacency[idx] <= 0;
        end
    end else begin
        state <= next_state;
        done_reg <= 0;
        result_reg <= result_reg;

        case (state)
            S_IDLE: begin
                if (start) begin
                    // Already reset, nothing else needed
                end
            end

            S_PROCESS_RECEIPTS: begin
                if (receipt_valid) begin
                    // Update balances: a paid for b
                    balance[receipt_a] <= balance[receipt_a] - receipt_p;
                    balance[receipt_b] <= balance[receipt_b] + receipt_p;
                    // Update adjacency (undirected)
                    adjacency[receipt_a][receipt_b] <= 1;
                    adjacency[receipt_b][receipt_a] <= 1;
                end
            end

            S_COUNT_NONZERO: begin
                // Count non-zero balances
                if (balance[i] != 0) begin
                    non_zero_count <= non_zero_count + 1;
                end
                i <= i + 1;
            end

            S_COMPONENT_START: begin
                visited <= 0;
                component_count <= 0;
                i <= 0;
            end

            S_COMPONENT_LOOP: begin
                if (i < MAX_PEOPLE) begin
                    if (balance[i] != 0 && !visited[i]) begin
                        visited[i] <= 1;
                        component_count <= component_count + 1;
                        changed <= 1;
                    end else begin
                        i <= i + 1;
                    end
                end
            end

            S_COMPONENT_PROPAGATE_INIT: begin
                changed <= 0;
                j <= 0;
            end

            S_COMPONENT_PROPAGATE_LOOP: begin
                if (changed) begin
                    changed <= 0;
                    j <= 0;
                end else begin
                    i <= i + 1; // Move to next i after propagation
                end
            end

            S_COMPONENT_PROPAGATE_J: begin
                if (j < MAX_PEOPLE) begin
                    if (visited[j]) begin
                        k <= 0;
                    end else begin
                        j <= j + 1;
                    end
                end else begin
                    // Finished scanning j for this iteration
                    // Go back to propagate loop to check if changed
                    state <= S_COMPONENT_PROPAGATE_LOOP;
                end
            end

            S_COMPONENT_PROPAGATE_K: begin
                if (k < MAX_PEOPLE) begin
                    if (adjacency[j][k] && balance[k] != 0 && !visited[k]) begin
                        visited[k] <= 1;
                        changed <= 1;
                    end
                    k <= k + 1;
                end else begin
                    j <= j + 1;
                    state <= S_COMPONENT_PROPAGATE_J;
                end
            end

            S_COMPONENT_NEXT_I: begin
                // Already handled by incrementing i in other states
            end

            S_COMPUTE_RESULT: begin
                result_reg <= non_zero_count - component_count;
                done_reg <= 1;
            end

            S_DONE: begin
                done_reg <= 1;
            end
        endcase
    end
end

// Next state logic
always @(*) begin
    case (state)
        S_IDLE: begin
            if (start) next_state = S_PROCESS_RECEIPTS;
            else next_state = S_IDLE;
        end

        S_PROCESS_RECEIPTS: begin
            if (receipt_valid && last) next_state = S_COUNT_NONZERO;
            else if (receipt_valid && !last) next_state = S_PROCESS_RECEIPTS;
            else if (!receipt_valid) next_state = S_PROCESS_RECEIPTS;
            else next_state = S_PROCESS_RECEIPTS;
        end

        S_COUNT_NONZERO: begin
            if (i < MAX_PEOPLE) next_state = S_COUNT_NONZERO;
            else next_state = S_COMPONENT_START;
        end

        S_COMPONENT_START: begin
            next_state = S_COMPONENT_LOOP;
        end

        S_COMPONENT_LOOP: begin
            if (i < MAX_PEOPLE) begin
                if (balance[i] != 0 && !visited[i]) begin
                    next_state = S_COMPONENT_PROPAGATE_INIT;
                end else begin
                    next_state = S_COMPONENT_LOOP; // will increment i
                end
            end else begin
                next_state = S_COMPUTE_RESULT;
            end
        end

        S_COMPONENT_PROPAGATE_INIT: begin
            next_state = S_COMPONENT_PROPAGATE_LOOP;
        end

        S_COMPONENT_PROPAGATE_LOOP: begin
            if (changed) next_state = S_COMPONENT_PROPAGATE_J;
            else next_state = S_COMPONENT_LOOP; // move to next i
        end

        S_COMPONENT_PROPAGATE_J: begin
            if (j < MAX_PEOPLE) begin
                if (visited[j]) next_state = S_COMPONENT_PROPAGATE_K;
                else next_state = S_COMPONENT_PROPAGATE_J; // will increment j
            end else begin
                next_state = S_COMPONENT_PROPAGATE_LOOP;
            end
        end

        S_COMPONENT_PROPAGATE_K: begin
            if (k < MAX_PEOPLE) next_state = S_COMPONENT_PROPAGATE_K;
            else next_state = S_COMPONENT_PROPAGATE_J;
        end

        S_COMPUTE_RESULT: begin
            next_state = S_DONE;
        end

        S_DONE: begin
            next_state = S_DONE;
        end

        default: next_state = S_IDLE;
    endcase
end

// Output assignments
assign result = result_reg;
assign done = done_reg;

endmodule

module min_insertions (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr [0:7],  // Fixed-size array for up to 8 marbles
    input wire [3:0] N,           // Actual number of marbles (1-8)
    input wire [3:0] K,           // Threshold (2-5)
    output reg [7:0] result,
    output reg done
);

// DP array: dp[l][r][k] = min insertions for subarray [l,r] with k extras of color arr[l]
// Dimensions: l,r in [0,7], k in [0,4] (since K≤5)
reg [7:0] dp [0:7][0:7][0:4];

// State machine states
reg [3:0] state;
localparam IDLE = 0;
localparam INIT = 1;
localparam LOOP_LEN = 2;
localparam LOOP_L = 3;
localparam COMPUTE_STATE = 4;
localparam LOOP_I = 5;
localparam NEXT_I = 6;
localparam UPDATE_DP = 7;
localparam NEXT_K = 8;
localparam NEXT_L = 9;
localparam DONE = 10;

// Loop counters
reg [3:0] len, l, k, i;
reg [7:0] cost1, cost2, temp;

// Helper signals
wire [7:0] seg1, seg2;
wire seg1_valid, seg2_valid;

// Compute segment values
assign seg1_valid = (l+1 <= i-1);
assign seg1 = seg1_valid ? dp[l+1][i-1][0] : 8'd0;

assign seg2_valid = (i+1 <= r);
always @(*) begin
    if (k+1 >= K) begin
        seg2 = seg2_valid ? dp[i+1][r][0] : 8'd0;
    end else begin
        seg2 = dp[i][r][k+1];
    end
end

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 8'd0;
        len <= 4'd1;
        l <= 4'd0;
        k <= 4'd0;
        i <= 4'd0;
        cost1 <= 8'd0;
        cost2 <= 8'd0;
        temp <= 8'd0;
        // Reset DP array to 0
        for (integer a = 0; a < 8; a = a + 1) begin
            for (integer b = 0; b < 8; b = b + 1) begin
                for (integer c = 0; c < 5; c = c + 1) begin
                    dp[a][b][c] <= 8'd0;
                end
            end
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT;
                    len <= 4'd1;
                    l <= 4'd0;
                    k <= 4'd0;
                end
            end

            INIT: begin
                // Initialize base cases: length 1
                if (l < N) begin
                    for (k = 0; k < K; k = k + 1) begin
                        if (k + 1 >= K) begin
                            dp[l][l][k] <= 8'd0;
                        end else begin
                            dp[l][l][k] <= K - (k + 1);
                        end
                    end
                    l <= l + 1;
                end else begin
                    l <= 4'd0;
                    k <= 4'd0;
                    len <= 4'd2;  // Start from length 2
                    state <= LOOP_LEN;
                end
            end

            LOOP_LEN: begin
                if (len > N) begin
                    state <= DONE;
                end else begin
                    l <= 4'd0;
                    state <= LOOP_L;
                end
            end

            LOOP_L: begin
                if (l >= N - len + 1) begin
                    len <= len + 1;
                    state <= LOOP_LEN;
                end else begin
                    k <= 4'd0;
                    state <= COMPUTE_STATE;
                end
            end

            COMPUTE_STATE: begin
                // Compute option1
                if (k + 1 >= K) begin
                    cost1 <= dp[l+1][l+len-1][0];
                end else begin
                    cost1 <= (K - (k + 1)) + dp[l+1][l+len-1][0];
                end
                // Initialize option2 computation
                i <= l + 1;
                cost2 <= 8'd255;  // Large number (INF)
                state <= LOOP_I;
            end

            LOOP_I: begin
                if (i > l + len - 1) begin
                    state <= UPDATE_DP;
                end else begin
                    // Check if arr[l] == arr[i]
                    if (arr[l] == arr[i]) begin
                        // Compute temp
                        if (k + 1 >= K) begin
                            temp <= seg1 + seg2;
                        end else begin
                            temp <= seg1 + seg2;
                        end
                        state <= NEXT_I;
                    end else begin
                        state <= NEXT_I;
                    end
                end
            end

            NEXT_I: begin
                if (arr[l] == arr[i] && temp < cost2) begin
                    cost2 <= temp;
                end
                i <= i + 1;
                state <= LOOP_I;
            end

            UPDATE_DP: begin
                dp[l][l+len-1][k] <= (cost1 < cost2) ? cost1 : cost2;
                state <= NEXT_K;
            end

            NEXT_K: begin
                k <= k + 1;
                if (k + 1 < K) begin
                    state <= COMPUTE_STATE;
                end else begin
                    l <= l + 1;
                    state <= NEXT_L;
                end
            end

            NEXT_L: begin
                if (l < N - len + 1) begin
                    k <= 4'd0;
                    state <= COMPUTE_STATE;
                end else begin
                    len <= len + 1;
                    state <= LOOP_LEN;
                end
            end

            DONE: begin
                result <= dp[0][N-1][0];
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

