module TrainPathPlanner (
    input clk,
    input rst_n,
    input start,
    input [5:0] origin,      // 6-bit node ID (0-63)
    input [5:0] destination, // 6-bit node ID (0-63)
    input [3:0] num_edges,   // Number of edges (1-16)
    input [5:0] edge_from [15:0],  // From node IDs
    input [5:0] edge_to [15:0],    // To node IDs  
    input [7:0] edge_dep [15:0],   // Departure time (0-59)
    input [15:0] edge_time [15:0], // Standard time in Q8.8
    input [15:0] edge_p [15:0],    // Probability (0-100) in Q8.8
    input [15:0] edge_d [15:0],    // Max delay in Q8.8
    output reg [15:0] result,       // Expected duration in Q8.8
    output reg done,
    output reg impossible
);

// Parameters
parameter MAX_NODES = 8;
parameter MAX_EDGES = 16;
parameter ITERATIONS = 8;

// Internal state
reg [5:0] node_state [MAX_NODES-1:0]; // 0=unvisited, 1=visiting, 2=done
reg [15:0] expected_time [MAX_NODES-1:0]; // Q8.8
reg [5:0] current_node;
reg [3:0] edge_counter;
reg [2:0] iteration_counter;

// Temporary registers
reg [15:0] new_time;
reg [15:0] wait_time;
reg [15:0] base_time;
reg [15:0] delay_expected;
reg [15:0] prob_factor;
reg [15:0] no_delay_prob;
reg [15:0] delay_prob;
reg [15:0] sum_delay;
reg [4:0] delay_iter;

// State machine states
reg [3:0] state;
localparam IDLE = 0;
localparam INIT = 1;
localparam SELECT_NODE = 2;
localparam PROCESS_EDGES = 3;
localparam UPDATE_NODE = 4;
localparam CHECK_DONE = 5;
localparam FINISHED = 6;
localparam IMPOSSIBLE_STATE = 7;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        impossible <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= INIT;
                    done <= 0;
                    impossible <= 0;
                end
            end

            INIT: begin
                // Initialize node states and expected times
                for (integer i = 0; i < MAX_NODES; i = i + 1) begin
                    node_state[i] <= (i == origin) ? 0 : 0; // All unvisited
                    expected_time[i] <= 16'h7FFF; // Max value
                end
                expected_time[origin] <= 0;
                iteration_counter <= 0;
                state <= SELECT_NODE;
            end

            SELECT_NODE: begin
                // Find unvisited node with minimum expected time
                current_node <= 6'h3F; // Invalid initially
                for (integer i = 0; i < MAX_NODES; i = i + 1) begin
                    if (node_state[i] == 0) begin
                        if (current_node == 6'h3F || expected_time[i] < expected_time[current_node]) begin
                            current_node <= i;
                        end
                    end
                end

                if (current_node == 6'h3F) begin
                    // No more nodes to visit
                    if (expected_time[destination] < 16'h7FFF) begin
                        state <= FINISHED;
                    end else begin
                        state <= IMPOSSIBLE_STATE;
                    end
                end else begin
                    edge_counter <= 0;
                    state <= PROCESS_EDGES;
                end
            end

            PROCESS_EDGES: begin
                if (edge_counter >= num_edges) begin
                    node_state[current_node] <= 2; // Mark as done
                    state <= SELECT_NODE;
                end else if (edge_from[edge_counter] == current_node) begin
                    // Calculate expected time for this edge
                    // wait_time = (departure - current_time) mod 60
                    // But we don't track current time modulo 60 in this simplified version
                    // Instead, we assume immediate departure for simplicity
                    wait_time <= 0;

                    // base_time = standard_time
                    base_time <= edge_time[edge_counter];

                    // delay_expected = (p/100) * (d/2) in Q8.8
                    // p in [0,100], d in [1,120] but scaled to Q8.8
                    delay_expected <= (edge_p[edge_counter] * edge_d[edge_counter]) >> 9; // (p*d/2)/100

                    // no_delay_prob = 1 - p/100
                    no_delay_prob <= 16'h0100 - edge_p[edge_counter]; // 1.0 = 0x0100

                    // delay_prob = p/100
                    delay_prob <= edge_p[edge_counter];

                    // Calculate expected future cost with delays
                    // This is simplified: we assume the next node's expected time
                    // doesn't change significantly with arrival time variations
                    sum_delay <= 0;
                    delay_iter <= 0;
                    state <= UPDATE_NODE;
                end else begin
                    edge_counter <= edge_counter + 1;
                end
            end

            UPDATE_NODE: begin
                // For simplicity, we use a weighted average of no-delay and delay cases
                // In full implementation, we'd need to consider different arrival times
                new_time <= expected_time[current_node] + base_time + delay_expected;

                // Update destination node if better
                if (edge_to[edge_counter] < MAX_NODES && new_time < expected_time[edge_to[edge_counter]]) begin
                    expected_time[edge_to[edge_counter]] <= new_time;
                end

                edge_counter <= edge_counter + 1;
                state <= PROCESS_EDGES;
            end

            FINISHED: begin
                result <= expected_time[destination];
                done <= 1;
                state <= IDLE;
            end

            IMPOSSIBLE_STATE: begin
                impossible <= 1;
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module typo_checker (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] word_count,
    input wire [511:0] words,        // 8 words * 64 bits (8 chars * 8 bits each)
    input wire [31:0] word_lengths,  // 8 words * 4 bits each (0-8)
    output reg pair_valid,
    output reg [3:0] word1_idx,
    output reg [3:0] word2_idx,
    output reg done
);

// Internal storage for words and lengths
reg [63:0] words_reg [0:7];
reg [3:0] word_lengths_reg [0:7];

// State definitions
localparam S_IDLE = 0;
localparam S_LOAD = 1;
localparam S_LOOP_I = 2;
localparam S_LOOP_J = 3;
localparam S_CHECK = 4;
localparam S_OUTPUT = 5;
localparam S_INCREMENT_J = 6;
localparam S_INCREMENT_I = 7;
localparam S_DONE = 8;

reg [3:0] state;
reg [2:0] i, j;          // Current pair indices
reg [2:0] i_reg, j_reg;  // Latched indices for similarity check

// Similarity check output
wire is_similar;

// Instantiate similarity module
similar sim_inst (
    .word1(words_reg[i]),
    .len1(word_lengths_reg[i]),
    .word2(words_reg[j]),
    .len2(word_lengths_reg[j]),
    .is_similar(is_similar)
);

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        pair_valid <= 0;
        done <= 0;
        i <= 0;
        j <= 0;
        i_reg <= 0;
        j_reg <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= S_LOAD;
                end
            end

            S_LOAD: begin
                // Capture input words and lengths
                for (integer w = 0; w < 8; w = w + 1) begin
                    words_reg[w] <= words[w*64 +: 64];
                    word_lengths_reg[w] <= word_lengths[w*4 +: 4];
                end
                i <= 0;
                j <= 0;
                state <= S_LOOP_I;
            end

            S_LOOP_I: begin
                if (word_count <= 3'd1) begin
                    state <= S_DONE;
                end else if (i < word_count - 1) begin
                    j <= i + 1;
                    state <= S_LOOP_J;
                end else begin
                    state <= S_DONE;
                end
            end

            S_LOOP_J: begin
                if (j < word_count) begin
                    state <= S_CHECK;
                end else begin
                    state <= S_INCREMENT_I;
                end
            end

            S_CHECK: begin
                // Similarity result available combinationally
                if (is_similar) begin
                    i_reg <= i;
                    j_reg <= j;
                    state <= S_OUTPUT;
                end else begin
                    state <= S_INCREMENT_J;
                end
            end

            S_OUTPUT: begin
                pair_valid <= 1;
                word1_idx <= i_reg;
                word2_idx <= j_reg;
                state <= S_INCREMENT_J;
            end

            S_INCREMENT_J: begin
                pair_valid <= 0;
                j <= j + 1;
                state <= S_LOOP_J;
            end

            S_INCREMENT_I: begin
                i <= i + 1;
                state <= S_LOOP_I;
            end

            S_DONE: begin
                done <= 1;
                state <= S_IDLE;
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

// Similarity check module
module similar (
    input [63:0] word1,
    input [3:0] len1,
    input [63:0] word2,
    input [3:0] len2,
    output reg is_similar
);

always @(*) begin
    is_similar = 0;

    // Check delete: len1 = len2 + 1
    if (len1 == len2 + 1) begin
        for (integer i = 0; i < 8; i = i + 1) begin
            if (i < len1) begin
                integer k;
                bit match;
                match = 1;
                // Check prefix
                for (k = 0; k < i; k = k + 1) begin
                    if (word1[8*k +:8] != word2[8*k +:8]) match = 0;
                end
                // Check suffix
                for (k = i; k < len2; k = k + 1) begin
                    if (word1[8*(k+1) +:8] != word2[8*k +:8]) match = 0;
                end
                if (match) is_similar = 1;
            end
        end
    end

    // Check insert: len2 = len1 + 1 (symmetric to delete)
    else if (len2 == len1 + 1) begin
        for (integer i = 0; i < 8; i = i + 1) begin
            if (i < len2) begin
                integer k;
                bit match;
                match = 1;
                // Check prefix
                for (k = 0; k < i; k = k + 1) begin
                    if (word2[8*k +:8] != word1[8*k +:8]) match = 0;
                end
                // Check suffix
                for (k = i; k < len1; k = k + 1) begin
                    if (word2[8*(k+1) +:8] != word1[8*k +:8]) match = 0;
                end
                if (match) is_similar = 1;
            end
        end
    end

    // Check replace and transpose: len1 == len2
    else if (len1 == len2) begin
        // Check replace: exactly one character difference
        integer diff_count;
        diff_count = 0;
        for (integer k = 0; k < 8; k = k + 1) begin
            if (k < len1) begin
                if (word1[8*k +:8] != word2[8*k +:8]) diff_count = diff_count + 1;
            end
        end
        if (diff_count == 1) is_similar = 1;

        // Check transpose: one adjacent swap
        for (integer i = 0; i < 8; i = i + 1) begin
            if (i < len1 - 1) begin
                bit match;
                match = 1;
                // Check swapped pair
                if (word1[8*i +:8] != word2[8*(i+1) +:8]) match = 0;
                if (word1[8*(i+1) +:8] != word2[8*i +:8]) match = 0;
                // Check rest
                for (integer k = 0; k < len1; k = k + 1) begin
                    if (k != i && k != i+1) begin
                        if (word1[8*k +:8] != word2[8*k +:8]) match = 0;
                    end
                end
                if (match) is_similar = 1;
            end
        end
    end
end

endmodule

module bridge_controller (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] t0, t1, t2, t3, t4, t5, t6, t7,  // Boat arrival times (scaled to 8 boats)
    input wire [2:0] num_boats,                          // Number of valid boats (1-8)
    output reg [31:0] total_time,
    output reg done
);
    // State machine states
    localparam IDLE = 3'b000;
    localparam READ = 3'b001;
    localparam CHECK_GROUP = 3'b010;
    localparam NEXT_BOAT = 3'b011;
    localparam FINAL_COST = 3'b100;
    localparam DONE_STATE = 3'b101;

    reg [2:0] state;
    reg [2:0] i;                    // Current boat index
    reg [31:0] accum_time;          // Accumulated total time
    reg [15:0] group_start_time;    // First boat time in current group
    reg [2:0] group_size;           // Number of boats in current group
    reg [15:0] current_boat_time;   // Time of current boat

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            total_time <= 0;
            done <= 0;
            i <= 0;
            accum_time <= 0;
            group_start_time <= 0;
            group_size <= 0;
            current_boat_time <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= READ;
                        i <= 0;
                        accum_time <= 0;
                        group_size <= 0;
                    end
                end

                READ: begin
                    // Read current boat time based on index
                    case (i)
                        0: current_boat_time <= t0;
                        1: current_boat_time <= t1;
                        2: current_boat_time <= t2;
                        3: current_boat_time <= t3;
                        4: current_boat_time <= t4;
                        5: current_boat_time <= t5;
                        6: current_boat_time <= t6;
                        7: current_boat_time <= t7;
                    endcase
                    state <= CHECK_GROUP;
                end

                CHECK_GROUP: begin
                    if (group_size == 0) begin
                        // Start first group
                        group_start_time <= current_boat_time;
                        group_size <= 1;
                        state <= NEXT_BOAT;
                    end else if (current_boat_time - group_start_time > 1800) begin
                        // Current boat too far from group start, start new group
                        accum_time <= accum_time + 120 + (20 * group_size);
                        group_start_time <= current_boat_time;
                        group_size <= 1;
                        state <= NEXT_BOAT;
                    end else begin
                        // Continue current group
                        group_size <= group_size + 1;
                        state <= NEXT_BOAT;
                    end
                end

                NEXT_BOAT: begin
                    i <= i + 1;
                    if (i + 1 < num_boats) begin
                        state <= READ;
                    end else begin
                        state <= FINAL_COST;
                    end
                end

                FINAL_COST: begin
                    // Add cost of last group
                    if (group_size > 0) begin
                        total_time <= accum_time + 120 + (20 * group_size);
                    end else begin
                        total_time <= accum_time;
                    end
                    state <= DONE_STATE;
                    done <= 1;
                end

                DONE_STATE: begin
                    if (!start) begin
                        state <= IDLE;
                        done <= 0;
                    end
                end
            endcase
        end
    end
endmodule

module count_representations (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [MAX_BITS-1:0] bin_bits,   // LSB at index 0
    input wire [LOG_MAX_BITS-1:0] length, // number of bits (1 to MAX_BITS)
    output reg [RESULT_WIDTH-1:0] result,
    output reg done
);

    // Parameters
    parameter MAX_BITS = 16;
    parameter LOG_MAX_BITS = 4;
    parameter MOD = 1000000009;
    parameter RESULT_WIDTH = 32;

    // Internal registers for DP
    reg [RESULT_WIDTH-1:0] dp0, dp1;
    reg [LOG_MAX_BITS-1:0] index;
    reg processing;

    // Helper function for modular addition
    function automatic [RESULT_WIDTH-1:0] mod_add;
        input [RESULT_WIDTH-1:0] a, b;
        begin
            mod_add = a + b;
            if (mod_add >= MOD)
                mod_add = mod_add - MOD;
        end
    endfunction

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dp0 <= 0;
            dp1 <= 0;
            result <= 0;
            done <= 0;
            index <= 0;
            processing <= 0;
        end else begin
            if (processing) begin
                // Update DP based on current bit
                if (bin_bits[index] == 1'b0) begin
                    dp0 <= dp0;
                    dp1 <= mod_add(dp0, dp1);
                end else begin
                    dp0 <= mod_add(dp0, dp1);
                    dp1 <= dp1;
                end

                // Check if last bit
                if (index == length - 1) begin
                    processing <= 0;
                    done <= 1;
                    result <= (bin_bits[index] == 1'b0) ? dp0 : mod_add(dp0, dp1);
                end else begin
                    index <= index + 1;
                end
            end else if (start) begin
                // Initialize DP and start processing
                dp0 <= 1;
                dp1 <= 0;
                index <= 0;
                processing <= 1;
                done <= 0;
                result <= 0;
            end else begin
                done <= 0;
            end
        end
    end

endmodule

