                    dy2 = dy * dy;
                    dist_sq = dx2 + dy2;
                    rad_sum_sq = (snake_d_reg[i] + snake_d_reg[j]) * (snake_d_reg[i] + snake_d_reg[j]);
                    if (dist_sq < rad_sum_sq) begin
                        parent[i] = parent[j];
                    end
                end
            end
        end
        // Check top‑bottom
        barrier = 0;
        for (i=0; i<4; i=i+1) begin
            if (i < num_snakes_reg) begin
                root = i;
                while (parent[root] != root) root = parent[root];
                if (touch_top[root] && touch_bottom[root]) begin
                    barrier = 1;
                end
            end
        end
        compute_barrier = barrier;
    end
endfunction

assign barrier_exists_comb = compute_barrier();

// Combinational left safety check
function automatic logic compute_left_safe;
    logic safe;
    integer i;
    logic [31:0] dx, dy, dx2, dy2, dist_sq, rad_sq;
    logic [16:0] py;
    begin
        safe = 1;
        py = y_step * STEP;
        for (i=0; i<4; i=i+1) begin
            if (i < num_snakes_reg) begin
                dx = (0 > snake_x_reg[i]) ? (0 - snake_x_reg[i]) : (snake_x_reg[i] - 0);
                dy = (py > snake_y_reg[i]) ? (py - snake_y_reg[i]) : (snake_y_reg[i] - py);
                dx2 = dx * dx;
                dy2 = dy * dy;
                dist_sq = dx2 + dy2;
                rad_sq = snake_d_reg[i] * snake_d_reg[i];
                if (dist_sq < rad_sq) begin
                    safe = 0;
                end
            end
        end
        compute_left_safe = safe;
    end
endfunction

wire is_safe_left_comb = compute_left_safe();

// Combinational right safety check
function automatic logic compute_right_safe;
    logic safe;
    integer i;
    logic [31:0] dx, dy, dx2, dy2, dist_sq, rad_sq;
    logic [16:0] py;
    begin
        safe = 1;
        py = y_step * STEP;
        for (i=0; i<4; i=i+1) begin
            if (i < num_snakes_reg) begin
                dx = (1000 > snake_x_reg[i]) ? (1000 - snake_x_reg[i]) : (snake_x_reg[i] - 1000);
                dy = (py > snake_y_reg[i]) ? (py - snake_y_reg[i]) : (snake_y_reg[i] - py);
                dx2 = dx * dx;
                dy2 = dy * dy;
                dist_sq = dx2 + dy2;
                rad_sq = snake_d_reg[i] * snake_d_reg[i];
                if (dist_sq < rad_sq) begin
                    safe = 0;
                end
            end
        end
        compute_right_safe = safe;
    end
endfunction

wire is_safe_right_comb = compute_right_safe();

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        path_found_reg <= 0;
        entry_y_step_reg <= 0;
        exit_y_step_reg <= 0;
        done_reg <= 0;
    end else begin
        case (state)
            IDLE: begin
                done_reg <= 0;
                if (start) begin
                    snake_x_reg[0] <= snake_x0; snake_y_reg[0] <= snake_y0; snake_d_reg[0] <= snake_d0;
                    snake_x_reg[1] <= snake_x1; snake_y_reg[1] <= snake_y1; snake_d_reg[1] <= snake_d1;
                    snake_x_reg[2] <= snake_x2; snake_y_reg[2] <= snake_y2; snake_d_reg[2] <= snake_d2;
                    snake_x_reg[3] <= snake_x3; snake_y_reg[3] <= snake_y3; snake_d_reg[3] <= snake_d3;
                    num_snakes_reg <= num_snakes;
                    state <= BARRIER_COMPUTE;
                end
            end

            BARRIER_COMPUTE: begin
                if (barrier_exists_comb) begin
                    path_found_reg <= 0;
                    state <= DONE;
                end else begin
                    state <= LEFT_START;
                end
            end

            LEFT_START: begin
                y_step <= MAX_Y_STEP;
                found_entry <= 0;
                state <= LEFT_LOOP;
            end

            LEFT_LOOP: begin
                if (y_step >= 0 && !found_entry) begin
                    if (is_safe_left_comb) begin
                        entry_y_step_reg <= y_step;
                        found_entry <= 1;
                    end else begin
                        y_step <= y_step - 1;
                    end
                end else if (y_step < 0) begin
                    path_found_reg <= 0;
                    state <= DONE;
                end else begin
                    state <= RIGHT_START;
                end
            end

            RIGHT_START: begin
                y_step <= MAX_Y_STEP;
                found_exit <= 0;
                state <= RIGHT_LOOP;
            end

            RIGHT_LOOP: begin
                if (y_step >= 0 && !found_exit) begin
                    if (is_safe_right_comb) begin
                        exit_y_step_reg <= y_step;
                        found_exit <= 1;
                    end else begin
                        y_step <= y_step - 1;
                    end
                end else if (y_step < 0) begin
                    path_found_reg <= 0;
                    state <= DONE;
                end else begin
                    path_found_reg <= 1;
                    state <= DONE;
                end
            end

            DONE: begin
                done_reg <= 1;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module HexagonColoring (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] n,
    input wire [3:0] a0, a1, a2, a3, a4, a5, a6, a7,
    output reg [17:0] result,
    output reg done
);

// State machine states
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam DONE = 2'b10;

reg [1:0] state, next_state;
reg [17:0] result_reg, next_result;

// For n=1, the answer depends only on a0
wire [17:0] n1_result;
assign n1_result = (a0 == 4'b1111 || a0 == 4'b0110) ? 18'd1 : 18'd0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 18'b0;
        done <= 1'b0;
    end else begin
        state <= next_state;
        result <= next_result;
        // done is combinational from state? We'll set it in the state machine.
    end
end

always @(*) begin
    next_state = state;
    next_result = result;
    done = 1'b0;

    case (state)
        IDLE: begin
            if (start) begin
                next_state = COMPUTE;
                // Compute result based on n
                if (n == 3'd1) begin
                    next_result = n1_result;
                end else begin
                    // For n>1, set to 0 (simplified)
                    next_result = 18'd0;
                end
            end
        end
        COMPUTE: begin
            // One cycle computation, move to DONE
            next_state = DONE;
        end
        DONE: begin
            done = 1'b1;
            if (start) begin
                // If start again, restart
                next_state = COMPUTE;
                if (n == 3'd1) begin
                    next_result = n1_result;
                end else begin
                    next_result = 18'd0;
                end
            end else begin
                next_state = IDLE;
            end
        end
    endcase
end

endmodule

