module candidate_simulation #(
    parameter N = 8,
    parameter VALUE_WIDTH = 8,
    parameter MAX_MINUTES = 16,
    parameter MINUTE_WIDTH = 5, // enough for MAX_MINUTES-1
    parameter LEN_WIDTH = 4     // enough for N
)(
    input clk,
    input rst_n,
    input start,
    input [LEN_WIDTH-1:0] len,
    input [VALUE_WIDTH-1:0] val0, val1, val2, val3, val4, val5, val6, val7,
    output reg done,
    output reg [MINUTE_WIDTH-1:0] M,
    output reg [VALUE_WIDTH-1:0] final0, final1, final2, final3, final4, final5, final6, final7,
    output reg [LEN_WIDTH-1:0] final_len
);

// State definitions
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam REMOVE = 2'b10;
localparam DONE = 2'b11;

// Registers for current state and next state
reg [1:0] state, next_state;

// Current values and length
reg [VALUE_WIDTH-1:0] current_values [0:N-1];
reg [LEN_WIDTH-1:0] current_len_reg;
reg [MINUTE_WIDTH-1:0] minute_count;

// Combinational leaving mask
wire [N-1:0] leaving_mask;

// Combinational logic for new values and new length after removal
reg [VALUE_WIDTH-1:0] new_values [0:N-1];
reg [LEN_WIDTH-1:0] new_len;

// Integer for loops
integer i;

// Combinational block to compute leaving_mask
always @(*) begin
    for (i = 0; i < N; i = i + 1) begin
        if (i < current_len_reg) begin
            leaving_mask[i] = 1'b0;
            // Check left neighbor
            if (i > 0) begin
                if (current_values[i-1] > current_values[i])
                    leaving_mask[i] = 1'b1;
            end
            // Check right neighbor
            if (i < current_len_reg - 1) begin
                if (current_values[i+1] > current_values[i])
                    leaving_mask[i] = 1'b1;
            end
        end else begin
            leaving_mask[i] = 1'b0;
        end
    end
end

// Combinational block to compute new_values and new_len
always @(*) begin
    new_len = 0;
    for (i = 0; i < N; i = i + 1) begin
        if (i < current_len_reg) begin
            if (leaving_mask[i] == 1'b0) begin
                new_values[new_len] = current_values[i];
                new_len = new_len + 1;
            end
        end
    end
end

// State transition and register update
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 1'b0;
        M <= 0;
        current_len_reg <= 0;
        minute_count <= 0;
        // Reset final outputs
        final0 <= 0; final1 <= 0; final2 <= 0; final3 <= 0;
        final4 <= 0; final5 <= 0; final6 <= 0; final7 <= 0;
        final_len <= 0;
        // Reset current_values
        for (i = 0; i < N; i = i + 1) begin
            current_values[i] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Initialize current_values from inputs
                    current_values[0] <= val0;
                    current_values[1] <= val1;
                    current_values[2] <= val2;
                    current_values[3] <= val3;
                    current_values[4] <= val4;
                    current_values[5] <= val5;
                    current_values[6] <= val6;
                    current_values[7] <= val7;
                    current_len_reg <= len;
                    minute_count <= 0;
                    done <= 1'b0;
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                // Check if leaving_mask is zero
                if (leaving_mask == 0) begin
                    // No one leaves, go to DONE
                    state <= DONE;
                    // Set outputs
                    M <= minute_count;
                    // Copy current_values to final outputs
                    final0 <= current_values[0];
                    final1 <= current_values[1];
                    final2 <= current_values[2];
                    final3 <= current_values[3];
                    final4 <= current_values[4];
                    final5 <= current_values[5];
                    final6 <= current_values[6];
                    final7 <= current_values[7];
                    final_len <= current_len_reg;
                    done <= 1'b1;
                end else begin
                    // Some leave, go to REMOVE
                    state <= REMOVE;
                end
            end

            REMOVE: begin
                // Update minute_count
                minute_count <= minute_count + 1;
                // Update current_values and current_len_reg
                for (i = 0; i < N; i = i + 1) begin
                    current_values[i] <= new_values[i];
                end
                current_len_reg <= new_len;
                // Go back to COMPUTE for next minute
                state <= COMPUTE;
            end

            DONE: begin
                // Stay in DONE, done is already set
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module ginger_candies #(
    parameter MAX_N = 8,
    parameter MAX_M = 16,
    parameter C_WIDTH = 16,
    parameter RESULT_WIDTH = 32,
    parameter ALPHA_WIDTH = 5
)(
    input wire clk,                   // Clock
    input wire rst_n,                 // Active-low reset
    input wire start,                 // Start pulse (1 cycle)
    input wire [3:0] M,               // Number of edges (1-16)
    input wire [2:0] u [0:MAX_M-1],   // Source vertex (0-7)
    input wire [2:0] v [0:MAX_M-1],   // Destination vertex
    input wire [C_WIDTH-1:0] c [0:MAX_M-1], // Candy count
    input wire [MAX_M-1:0] valid_edge, // Bitmask: 1 if edge i is valid
    input wire [ALPHA_WIDTH-1:0] alpha, // α constant
    output reg [RESULT_WIDTH-1:0] result, // Minimum energy or 0xFFFFFFFF if none
    output reg done                     // High for 1 cycle when result is ready
);

// Description:
// This module computes the minimum energy for Mr. G's ginger candies problem
// on a small graph (max 8 vertices, 16 edges). The algorithm enumerates all
// subsets of edges (2^M subsets). For each non‑empty subset it checks:
//   1. All vertices have even degree in the subset.
//   2. The subgraph formed by the subset is connected.
//   3. The maximum candy value L and number of edges K are computed.
//   4. Cost = L^2 + α * K is calculated.
// The minimum cost over all valid subsets is stored in result.
// If no valid subset exists, result is set to 0xFFFFFFFF.
//
// Implementation outline:
// - State machine: IDLE, LOAD, ENUM_INIT, ENUM_CHECK, ENUM_NEXT, CONN_CHECK, UPDATE_MIN, DONE.
// - Internal registers:
//   * subset_reg [MAX_M-1:0]: current subset bitmask
//   * min_cost [RESULT_WIDTH-1:0]: current minimum cost
//   * edge_idx [3:0]: index for iterating edges
//   * vertex_deg [MAX_N-1:0][3:0]: degree counters (4 bits enough for max 16 edges)
//   * max_candy [C_WIDTH-1:0]: maximum candy in current subset
//   * edge_count [4:0]: number of edges in subset
//   * visited [MAX_N-1:0]: connectivity visited flags
//   * queue [MAX_N-1:0]: simple FIFO for BFS (width 3 bits, depth 8)
//   * queue_wr, queue_rd pointers
// - On start: latch M, u, v, c, valid_edge, alpha into internal registers.
// - Then iterate subset from 0 to (1<<M)-1. For each subset:
//   * Reset degrees, max_candy, edge_count.
//   * For each edge i (0..M-1): if subset has edge i, update degrees, max_candy, edge_count.
//   * Check edge_count > 0 and all degrees even.
//   * If passes, run BFS from first vertex with degree>0 to check connectivity.
//   * If connected, compute cost = max_candy^2 + alpha * edge_count (use multiplier).
//   * Update min_cost if cost < min_cost.
// - After all subsets, set result = min_cost (or 0xFFFFFFFF if none) and pulse done.
// - Multiplication: max_candy is up to 2^16-1, square fits in 32 bits.
// - The module is fully synchronous; reset clears all registers.
// - The interface uses array ports; assign each element individually in testbench.

endmodule

module shuffle_number #(
    parameter N = 8,
    parameter DATA_WIDTH = 4,
    parameter RESULT_WIDTH = 3
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] perm_0,
    input wire [DATA_WIDTH-1:0] perm_1,
    input wire [DATA_WIDTH-1:0] perm_2,
    input wire [DATA_WIDTH-1:0] perm_3,
    input wire [DATA_WIDTH-1:0] perm_4,
    input wire [DATA_WIDTH-1:0] perm_5,
    input wire [DATA_WIDTH-1:0] perm_6,
    input wire [DATA_WIDTH-1:0] perm_7,
    output reg [RESULT_WIDTH-1:0] result,
    output reg done
);

// Internal arrays
reg [2:0] pos [0:N-1];
reg [0:0] inc [0:N-2];
reg [2:0] f [0:N-1][0:N-1];

// State definitions
localparam IDLE = 0;
localparam INIT_POS_START = 1;
localparam INIT_POS_LOOP = 2;
localparam INIT_INC_START = 3;
localparam INIT_INC_LOOP = 4;
localparam DP_START = 5;
localparam DP_INIT = 6;
localparam DP_LEN_LOOP = 7;
localparam DP_L_LOOP = 8;
localparam DP_M_LOOP = 9;
localparam DP_UPDATE = 10;
localparam DONE = 11;

reg [3:0] state;
reg [2:0] len_cnt;
reg [2:0] l_cnt;
reg [2:0] m_cnt;
reg [2:0] best;
reg [2:0] temp;

// Helper to access perm array
wire [DATA_WIDTH-1:0] perm [0:N-1];
assign perm[0] = perm_0;
assign perm[1] = perm_1;
assign perm[2] = perm_2;
assign perm[3] = perm_3;
assign perm[4] = perm_4;
assign perm[5] = perm_5;
assign perm[6] = perm_6;
assign perm[7] = perm_7;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        len_cnt <= 0;
        l_cnt <= 0;
        m_cnt <= 0;
        best <= 0;
        temp <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT_POS_START;
                end
            end

            INIT_POS_START: begin
                l_cnt <= 0;
                state <= INIT_POS_LOOP;
            end

            INIT_POS_LOOP: begin
                if (l_cnt < N) begin
                    pos[ perm[l_cnt] - 1 ] <= l_cnt;
                    l_cnt <= l_cnt + 1;
                end else begin
                    state <= INIT_INC_START;
                end
            end

            INIT_INC_START: begin
                l_cnt <= 0;
                state <= INIT_INC_LOOP;
            end

            INIT_INC_LOOP: begin
                if (l_cnt < N-1) begin
                    if (pos[l_cnt] < pos[l_cnt+1])
                        inc[l_cnt] <= 1'b1;
                    else
                        inc[l_cnt] <= 1'b0;
                    l_cnt <= l_cnt + 1;
                end else begin
                    state <= DP_START;
                end
            end

            DP_START: begin
                l_cnt <= 0;
                state <= DP_INIT;
            end

            DP_INIT: begin
                if (l_cnt < N) begin
                    f[l_cnt][l_cnt] <= 0;
                    l_cnt <= l_cnt + 1;
                end else begin
                    len_cnt <= 2;
                    state <= DP_LEN_LOOP;
                end
            end

            DP_LEN_LOOP: begin
                if (len_cnt <= N) begin
                    l_cnt <= 0;
                    state <= DP_L_LOOP;
                end else begin
                    result <= f[0][N-1];
                    state <= DONE;
                end
            end

            DP_L_LOOP: begin
                if (l_cnt <= N - len_cnt) begin
                    best <= 7;
                    m_cnt <= l_cnt;
                    state <= DP_M_LOOP;
                end else begin
                    len_cnt <= len_cnt + 1;
                    state <= DP_LEN_LOOP;
                end
            end

            DP_M_LOOP: begin
                if (m_cnt <= l_cnt + len_cnt - 2) begin
                    if (f[l_cnt][m_cnt] > f[m_cnt+1][l_cnt+len_cnt-1])
                        temp <= f[l_cnt][m_cnt];
                    else
                        temp <= f[m_cnt+1][l_cnt+len_cnt-1];
                    state <= DP_UPDATE;
                end else begin
                    f[l_cnt][l_cnt+len_cnt-1] <= best;
                    l_cnt <= l_cnt + 1;
                    state <= DP_L_LOOP;
                end
            end

            DP_UPDATE: begin
                if (temp + 1 < best)
                    best <= temp + 1;
                m_cnt <= m_cnt + 1;
                state <= DP_M_LOOP;
            end

            DONE: begin
                done <= 1;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module ForestBuilder #(
    parameter MAX_V = 8,
    parameter DATA_WIDTH = 8,
    parameter EDGE_WIDTH = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] V,
    input wire [DATA_WIDTH-1:0] degrees [0:MAX_V-1],
    output reg possible,
    output reg done,
    output reg edge_valid,
    output reg [EDGE_WIDTH-1:0] edge_a,
    output reg [EDGE_WIDTH-1:0] edge_b
);

reg [DATA_WIDTH-1:0] deg [0:MAX_V-1];
reg [3:0] comp_id [0:MAX_V-1];
reg [3:0] V_reg;
reg [DATA_WIDTH-1:0] sum_deg, max_deg, m;
reg [3:0] u, v;
reg [3:0] idx;
reg [3:0] best_deg, best_u;
reg found_v;

localparam IDLE = 0;
localparam INIT = 1;
localparam FIND_U = 2;
localparam FIND_V = 3;
localparam ADD_EDGE = 4;
localparam CHECK_DONE = 5;
localparam FINISHED = 6;

reg [2:0] state, next_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        possible <= 0;
        done <= 0;
        edge_valid <= 0;
        edge_a <= 0;
        edge_b <= 0;
        state <= IDLE;
    end else begin
        state <= next_state;
        edge_valid <= 0;
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    V_reg <= V;
                    for (integer i = 0; i < MAX_V; i = i + 1) begin
                        if (i < V) deg[i] <= degrees[i]; else deg[i] <= 0;
                        comp_id[i] <= i;
                    end
                    sum_deg <= 0;
                    max_deg <= 0;
                    m <= 0;
                    idx <= 0;
                    next_state <= INIT;
                end else next_state <= IDLE;
            end
            INIT: begin
                if (idx < V_reg) begin
                    if (deg[idx] > 0) begin
                        sum_deg <= sum_deg + deg[idx];
                        m <= m + 1;
                        if (deg[idx] > max_deg) max_deg <= deg[idx];
                    end
                    idx <= idx + 1;
                    next_state <= INIT;
                end else begin
                    if (sum_deg == 0) begin
                        possible <= 1; done <= 1; next_state <= IDLE;
                    end else if (sum_deg[0] == 1 || (m > 0 && (max_deg > (m-1) || sum_deg > 2*(m-1)))) begin
                        possible <= 0; done <= 1; next_state <= IDLE;
                    end else begin
                        possible <= 1;
                        best_deg <= 0;
                        best_u <= 0;
                        idx <= 0;
                        next_state <= FIND_U;
                    end
                end
            end
            FIND_U: begin
                if (idx < V_reg) begin
                    if (deg[idx] > best_deg) begin
                        best_deg <= deg[idx];
                        best_u <= idx;
                    end
                    idx <= idx + 1;
                    next_state <= FIND_U;
                end else begin
                    if (best_deg == 0) begin
                        done <= 1; next_state <= IDLE;
                    end else begin
                        u <= best_u;
                        best_deg <= 0;
                        idx <= 0;
                        found_v <= 0;
                        next_state <= FIND_V;
                    end
                end
            end
            FIND_V: begin
                if (idx < V_reg) begin
                    if (idx != u && deg[idx] > 0 && comp_id[idx] != comp_id[u]) begin
                        v <= idx;
                        found_v <= 1;
                    end
                    idx <= idx + 1;
                    next_state <= FIND_V;
                end else begin
                    if (found_v) next_state <= ADD_EDGE;
                    else begin
                        possible <= 0; done <= 1; next_state <= IDLE;
                    end
                    idx <= 0;
                end
            end
            ADD_EDGE: begin
                edge_a <= u + 1;
                edge_b <= v + 1;
                edge_valid <= 1;
                deg[u] <= deg[u] - 1;
                deg[v] <= deg[v] - 1;
                for (integer i = 0; i < MAX_V; i = i + 1) begin
                    if (i < V_reg && comp_id[i] == comp_id[v]) comp_id[i] <= comp_id[u];
                end
                next_state <= CHECK_DONE;
            end
            CHECK_DONE: begin
                if (idx < V_reg) begin
                    if (deg[idx] > 0) begin
                        idx <= 0;
                        best_deg <= 0;
                        next_state <= FIND_U;
                    end else begin
                        idx <= idx + 1;
                        next_state <= CHECK_DONE;
                    end
                end else begin
                    done <= 1;
                    next_state <= IDLE;
                end
            end
            default: next_state <= IDLE;
        endcase
    end
end

endmodule

cocotb_testbench:
import cocotb
from cocotb.triggers import Timer, RisingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

def is_value_defined(value):
    try:
        int(value)
        return True
    except ValueError:
        return False

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(value, bits):
    max_val = (1 << bits) - 1
    if value < 0:
        return value + (1 << bits) if value < 0 else value
    return min(max_val, max(0, value))

async def reset_dut(dut, cycles=2):
    if has_signal(dut, 'rst_n'):
        dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        if has_signal(dut, 'clk'):
            await RisingEdge(dut.clk)
    if has_signal(dut, 'rst_n'):
        dut.rst_n.value = 1
    if has_signal(dut, 'clk'):
        await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=1000):
    for _ in range(max_cycles):
        if has_signal(dut, 'clk'):
            await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout: done not asserted after {max_cycles} cycles")

def reference_forest(V, degrees):
    if V == 0:
        return True, []
    sum_deg = sum(degrees)
    if sum_deg % 2 != 0:
        return False, []
    m = sum(1 for d in degrees if d > 0)
    max_deg = max(degrees) if V > 0 else 0
    if m > 0:
        if max_deg > m - 1 or sum_deg > 2 * (m - 1):
            return False, []
    if sum_deg == 0:
        return True, []
    comp_id = list(range(V))
    deg = list(degrees)
    edges = []
    while True:
        u = -1
        best_deg = -1
        for i in range(V):
            if deg[i] > best_deg:
                best_deg = deg[i]
                u = i
        if u == -1:
            break
        v = -1
        for j in range(V):
            if j != u and deg[j] > 0 and comp_id[j] != comp_id[u]:
                v = j
                break
        if v == -1:
            return False, []
        edges.append((u+1, v+1))
        deg[u] -= 1
        deg[v] -= 1
        old_id = comp_id[v]
        new_id = comp_id[u]
        for i in range(V):
            if comp_id[i] == old_id:
                comp_id[i] = new_id
    return True, edges

@cocotb.test(timeout_time=5000, timeout_unit="ms")
async def test_forest_builder(dut):
    MAX_V = 8
    DATA_WIDTH = 8
    CLK_PERIOD_NS = 10
    is_sequential = has_signal(dut, 'clk')
    if is_sequential:
        cocotb.start_soon(Clock(dut.clk, CLK_PERIOD_NS, units='ns').start())
        await reset_dut(dut)
    test_cases = [
        (3, [1,1,2], True, [(1,3),(2,3)]),
        (2, [1,2], False, []),
        (3, [2,2,2], False, []),
        (0, [], True, []),
        (5, [2,2,1,1,0], True, [(1,3),(1,4),(2,5)]),
        (4, [1,1,1,1], True, [(1,2),(3,4)]),
    ]
    for i, (V, degrees, exp_possible, exp_edges) in enumerate(test_cases):
        dut._log.info(f"Test {i+1}: V={V}, degrees={degrees}")
        if has_signal(dut, 'V'):
            dut.V.value = V
        if has_signal(dut, 'degrees'):
            for idx in range(MAX_V):
                if idx < V:
                    getattr(dut, 'degrees')[idx].value = clamp_to_width(degrees[idx], DATA_WIDTH)
                else:
                    getattr(dut, 'degrees')[idx].value = 0
        if is_sequential:
            if has_signal(dut, 'start'):
                dut.start.value = 1
                await RisingEdge(dut.clk)
                dut.start.value = 0
            await wait_for_done(dut)
        else:
            await Timer(100, units='ns')
        if not is_value_defined(dut.possible.value):
            raise TestFailure(f"Test {i+1}: possible undefined")
        actual_possible = int(dut.possible.value) == 1
        if actual_possible != exp_possible:
            raise TestFailure(f"Test {i+1}: expected possible={exp_possible}, got {actual_possible}")
        if exp_possible:
            edges = []
            for _ in range(20):
                if is_sequential:
                    await RisingEdge(dut.clk)
                if is_value_defined(dut.edge_valid.value) and int(dut.edge_valid.value) == 1:
                    a = int(dut.edge_a.value)
                    b = int(dut.edge_b.value)
                    edges.append((a, b))
                if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
                    break
            if set(edges) != set(exp_edges):
                raise TestFailure(f"Test {i+1}: expected edges {exp_edges}, got {edges}")
            dut._log.info(f"Test {i+1}: PASS")
        else:
            dut._log.info(f"Test {i+1}: PASS (IMPOSSIBLE)")
    dut._log.info("All tests passed!")

