module circumsphere (
    input wire signed [7:0] p0_x, p0_y, p0_z,
    input wire signed [7:0] p1_x, p1_y, p1_z,
    input wire signed [7:0] p2_x, p2_y, p2_z,
    input wire signed [7:0] p3_x, p3_y, p3_z,
    output reg signed [31:0] x_c, y_c, z_c
);
    // Convert inputs to real for computation
    real a0, a1, a2;
    real b0, b1, b2;
    real c0, c1, c2;
    real d0, d1, d2;

    always @(*) begin
        a0 = p0_x; a1 = p0_y; a2 = p0_z;
        b0 = p1_x; b1 = p1_y; b2 = p1_z;
        c0 = p2_x; c1 = p2_y; c2 = p2_z;
        d0 = p3_x; d1 = p3_y; d2 = p3_z;
    end

    // Computation of circumsphere center
    real u0, u1, u2;
    real v0, v1, v2;
    real w0, w1, w2;

    real dot_u, dot_v, dot_w;
    real cross_vw0, cross_vw1, cross_vw2;
    real cross_wu0, cross_wu1, cross_wu2;
    real cross_uv0, cross_uv1, cross_uv2;

    real num0, num1, num2;
    real denom;
    real X0, X1, X2;
    real xc, yc, zc;

    always @(*) begin
        // Differences
        u0 = b0 - a0; u1 = b1 - a1; u2 = b2 - a2;
        v0 = c0 - a0; v1 = c1 - a1; v2 = c2 - a2;
        w0 = d0 - a0; w1 = d1 - a1; w2 = d2 - a2;

        // Dot products
        dot_u = u0*u0 + u1*u1 + u2*u2;
        dot_v = v0*v0 + v1*v1 + v2*v2;
        dot_w = w0*w0 + w1*w1 + w2*w2;

        // Cross products
        cross_vw0 = v1*w2 - v2*w1;
        cross_vw1 = v2*w0 - v0*w2;
        cross_vw2 = v0*w1 - v1*w0;

        cross_wu0 = w1*u2 - w2*u1;
        cross_wu1 = w2*u0 - w0*u2;
        cross_wu2 = w0*u1 - w1*u0;

        cross_uv0 = u1*v2 - u2*v1;
        cross_uv1 = u2*v0 - u0*v2;
        cross_uv2 = u0*v1 - u1*v0;

        // Numerator components
        num0 = dot_u*cross_vw0 + dot_v*cross_wu0 + dot_w*cross_uv0;
        num1 = dot_u*cross_vw1 + dot_v*cross_wu1 + dot_w*cross_uv1;
        num2 = dot_u*cross_vw2 + dot_v*cross_wu2 + dot_w*cross_uv2;

        // Denominator: 2 * (u · (v × w))
        denom = 2 * (u0*cross_vw0 + u1*cross_vw1 + u2*cross_vw2);

        // X = numerator / denominator
        X0 = num0 / denom;
        X1 = num1 / denom;
        X2 = num2 / denom;

        // Center = P0 + X
        xc = a0 + X0;
        yc = a1 + X1;
        zc = a2 + X2;
    end

    // Convert to Q16.16 fixed-point (16 fractional bits)
    always @(*) begin
        x_c = $rtoi(xc * 65536.0);
        y_c = $rtoi(yc * 65536.0);
        z_c = $rtoi(zc * 65536.0);
    end

endmodule

module friend_group_checker #(
    parameter MAX_N = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,          // number of nodes (1 to MAX_N)
    input wire [3:0] p,          // max group size
    input wire [3:0] q,          // max cross-edges per group
    input wire [7:0] adj [0:MAX_N-1], // adjacency matrix rows (8 bits each, only first n columns used)
    output reg done,
    output reg valid,
    output reg [2:0] group_id [0:MAX_N-1] // group assignment for each node (0..7)
);

// Behavior:
// - When start is asserted (1 cycle), the module begins computation.
// - The module asserts done when finished (within a few thousand cycles for n≤8).
// - If valid is high, a partition exists and group_id[i] holds the group number for node i.
// - Groups are numbered consecutively from 0.
// - If valid is low, no partition exists; group_id is undefined.
// - Reset: rst_n=0 clears all state, done=0, valid=0, group_id=0.
// - The module uses a DP-over-subsets algorithm:
//     1. Precompute for each subset mask (1..(1<<n)-1) whether it is a valid group:
//        - Size (popcount) ≤ p
//        - Cross-edges ≤ q (sum over nodes in subset of edges to nodes outside)
//     2. DP: dp[mask] = 1 if there exists a submask s of mask such that s is valid and dp[mask\s]=1.
//     3. If dp[(1<<n)-1] = 1, reconstruct partition via stored predecessor submask.
//     4. Output group_id for each node.
// - The module must handle variable n (1..8). Only the lowest n bits of each adj row are considered.
// - The adjacency matrix is symmetric (but not verified).
// - Implementation must be synthesizable; loops can be unrolled for fixed MAX_N.
// - Timing: after start, done will be asserted within a bounded number of cycles (e.g., < 10,000).

// The testbench will provide adj as an array of 8-bit values, one per node, with bits representing friends.
// Example: if node 0 is friends with node 1, then adj[0][1] = 1.

endmodule

module scary_subarrays (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [63:0] packed_arr,
    input wire [3:0] n,
    output reg [5:0] result,
    output reg done
);

// Unpack 8x8-bit array from packed input
wire [7:0] arr [0:7];
assign arr[0] = packed_arr[7:0];
assign arr[1] = packed_arr[15:8];
assign arr[2] = packed_arr[23:16];
assign arr[3] = packed_arr[31:24];
assign arr[4] = packed_arr[39:32];
assign arr[5] = packed_arr[47:40];
assign arr[6] = packed_arr[55:48];
assign arr[7] = packed_arr[63:56];

// State definitions
localparam IDLE = 3'b000;
localparam INIT_L = 3'b001;
localparam CHECK_R = 3'b010;
localparam COMPARE = 3'b011;
localparam CHECK_ODD = 3'b100;
localparam INCREMENT_R = 3'b101;
localparam INCREMENT_L = 3'b110;
localparam DONE = 3'b111;

// Registers
reg [2:0] state;
reg [2:0] l;
reg [2:0] r;
reg [2:0] count_less;
reg [5:0] result_reg;
reg [7:0] temp_arr_l;

// Combinational signals
wire [2:0] diff = r - l;
wire diff_even = ~diff[0];  // 1 if (r-l) even → length odd
wire [2:0] target_count = diff >> 1;  // (r-l)/2

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        l <= 3'b0;
        r <= 3'b0;
        count_less <= 3'b0;
        result_reg <= 6'b0;
        temp_arr_l <= 8'b0;
        done <= 1'b0;
    end else begin
        done <= 1'b0;

        case (state)
            IDLE: begin
                if (start) begin
                    state <= INIT_L;
                    result_reg <= 6'b0;
                end
            end

            INIT_L: begin
                l <= 3'b0;
                temp_arr_l <= arr[0];
                count_less <= 3'b0;
                r <= 3'b0;
                state <= CHECK_R;
            end

            CHECK_R: begin
                if (r < n) begin
                    state <= COMPARE;
                end else begin
                    state <= INCREMENT_L;
                end
            end

            COMPARE: begin
                if (arr[r] < temp_arr_l) begin
                    count_less <= count_less + 1;
                end
                state <= CHECK_ODD;
            end

            CHECK_ODD: begin
                if (diff_even && (count_less == target_count)) begin
                    result_reg <= result_reg + 1;
                end
                state <= INCREMENT_R;
            end

            INCREMENT_R: begin
                r <= r + 1;
                state <= CHECK_R;
            end

            INCREMENT_L: begin
                l <= l + 1;
                if (l + 1 < n) begin
                    temp_arr_l <= arr[l + 1];
                    count_less <= 3'b0;
                    r <= l + 1;
                    state <= CHECK_R;
                end else begin
                    state <= DONE;
                end
            end

            DONE: begin
                result <= result_reg;
                done <= 1'b1;
                state <= IDLE;
            end

            default: begin
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module WorstRank (
    input wire clk,
    input wire rst_n,
    input wire start,                // Assert to reset and start a new computation
    input wire [3:0] n_minus_one,    // Number of scores per contestant (n‑1)
    input wire scores_valid,         // High when scores_in is valid
    input wire [7:0] scores_in,      // Score value for current contestant
    input wire is_your_score,        // High if this score belongs to the first contestant (you)
    input wire end_of_contestants,   // High when this is the last score of the last contestant
    output reg [7:0] worst_rank,     // Result: worst possible rank
    output reg done                  // High when computation is complete
);

// Internal state and registers
reg [7:0] your_scores[0:9];         // Store your scores (max 9)
reg [7:0] other_scores[0:9];        // Store current other contestant's scores
reg [7:0] counter;                 // Count of contestants that can beat you
reg [3:0] score_index;             // Index for reading scores per contestant
reg [3:0] contestants_read;        // Number of other contestants processed
reg processing_you;                // Flag indicating we are reading your scores
reg compute_done;                  // Internal done flag

// Computed values for your aggregate
reg [15:0] your_aggregate;         // Sum of top 4 scores (or all if <4)

// Computed values for other contestant
reg [15:0] other_aggregate;        // Sum of top 4 scores (or all if <4)
reg [7:0] fourth_highest;          // 4th highest score (or 0 if <4)
reg [15:0] needed_score;           // Minimum score needed to beat you

// Helper task to compute top‑4 sum and fourth highest from a score array
function automatic void compute_top4(
    input reg [7:0] scores[0:9],
    input reg [3:0] len,
    output reg [15:0] sum,
    output reg [7:0] fourth
);
    integer i, j;
    reg [7:0] sorted[0:9];
    // Copy and sort descending using bubble sort (len ≤ 9)
    for (i = 0; i < len; i++) sorted[i] = scores[i];
    for (i = 0; i < len-1; i++) begin
        for (j = 0; j < len-i-1; j++) begin
            if (sorted[j] < sorted[j+1]) begin
                sorted[j] = sorted[j] ^ sorted[j+1];
                sorted[j+1] = sorted[j] ^ sorted[j+1];
                sorted[j] = sorted[j] ^ sorted[j+1];
            end
        end
    end
    // Compute sum of top min(4,len) scores
    sum = 0;
    for (i = 0; i < (len < 4 ? len : 4); i++) sum = sum + sorted[i];
    // Fourth highest is the 4th element if len ≥4, else 0
    fourth = (len >= 4) ? sorted[3] : 8'd0;
endfunction

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all registers
        worst_rank <= 8'd0;
        done <= 1'b0;
        counter <= 8'd0;
        score_index <= 4'd0;
        contestants_read <= 4'd0;
        processing_you <= 1'b1;
        compute_done <= 1'b0;
        your_aggregate <= 16'd0;
        needed_score <= 16'd0;
    end else if (start) begin
        // Start a new computation: reset counters and flags
        worst_rank <= 8'd0;
        done <= 1'b0;
        counter <= 8'd0;
        score_index <= 4'd0;
        contestants_read <= 4'd0;
        processing_you <= 1'b1;
        compute_done <= 1'b0;
        your_aggregate <= 16'd0;
        needed_score <= 16'd0;
    end else if (scores_valid && !compute_done) begin
        // Store incoming score
        if (processing_you) begin
            your_scores[score_index] <= scores_in;
        end else begin
            other_scores[score_index] <= scores_in;
        end
        score_index <= score_index + 1;
        // When all scores for current contestant are read
        if (score_index + 1 == n_minus_one) begin
            score_index <= 0;
            if (processing_you) begin
                // Finished reading your scores: compute your aggregate
                compute_top4(your_scores, n_minus_one, your_aggregate, fourth_highest);
                processing_you <= 1'b0;
            end else begin
                // Finished reading other contestant's scores: compute needed score
                // Step 1: compute other_aggregate and fourth_highest
                compute_top4(other_scores, n_minus_one, other_aggregate, fourth_highest);
                // Step 2: calculate needed_score
                if (n_minus_one < 4) begin
                    // If fewer than 4 scores, aggregate = sum + X
                    // Need sum + X > your_aggregate => X > your_aggregate - sum
                    needed_score <= (your_aggregate >= other_aggregate) ? (your_aggregate - other_aggregate + 1) : 16'd0;
                end else begin
                    // If 4 or more scores
                    if (other_aggregate > your_aggregate) begin
                        needed_score <= 16'd0; // Already beats you
                    end else begin
                        // Needed X = max(fourth_highest + 1, your_aggregate - other_aggregate + fourth_highest + 1)
                        // Because X must be > fourth_highest to replace it, and must satisfy other_aggregate - fourth_highest + X > your_aggregate
                        reg [15:0] val1 = fourth_highest + 1;
                        reg [15:0] val2 = your_aggregate - other_aggregate + fourth_highest + 1;
                        needed_score <= (val1 > val2) ? val1 : val2;
                    end
                end
                // Step 3: increment counter if needed_score ≤ 101
                if (needed_score <= 16'd101) counter <= counter + 1;
                // Step 4: prepare for next contestant or finish
                contestants_read <= contestants_read + 1;
            end
        end
        // If end_of_contestants is asserted and we just finished a contestant
        if (end_of_contestants && score_index == n_minus_one - 1) begin
            // Wait for the next clock cycle to finalize the last contestant
        end
    end else if (end_of_contestants && !compute_done && score_index == 4'd0) begin
        // All contestants have been read; finalize result
        worst_rank <= counter + 1;
        done <= 1'b1;
        compute_done <= 1'b1;
    end
end

endmodule

module string_rearrange #(
    parameter N = 8,
    parameter LOG2_N = 3,
    parameter ALPHABET = 26
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [4:0] char_in [0:N-1],
    output reg [4:0] char_out [0:N-1],
    output reg out_valid,
    output reg done,
    output reg impossible
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam COUNT_FREQ = 3'b001;
    localparam FIND_MAX = 3'b010;
    localparam CHECK = 3'b011;
    localparam GEN_OUTPUT = 3'b100;
    localparam DONE = 3'b101;

    // Internal registers
    reg [LOG2_N-1:0] freq [0:ALPHABET-1];
    reg [LOG2_N-1:0] max_freq;
    reg [4:0] threshold;
    reg [5:0] count;
    reg [5:0] idx;
    reg [4:0] current_letter;
    reg [LOG2_N-1:0] output_count;
    reg [2:0] current_state, next_state;

    integer i;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            done <= 0;
            out_valid <= 0;
            impossible <= 0;
            for (i = 0; i < N; i = i + 1) char_out[i] <= 0;
            for (i = 0; i < ALPHABET; i = i + 1) freq[i] <= 0;
            max_freq <= 0;
            threshold <= N >> 1;
            count <= 0;
            idx <= 0;
            current_letter <= 0;
            output_count <= 0;
        end else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    if (start) begin
                        for (i = 0; i < ALPHABET; i = i + 1) freq[i] <= 0;
                        count <= 0;
                        done <= 0;
                        out_valid <= 0;
                        impossible <= 0;
                    end
                end

                COUNT_FREQ: begin
                    if (count < N) begin
                        freq[char_in[count]] <= freq[char_in[count]] + 1;
                        count <= count + 1;
                    end
                end

                FIND_MAX: begin
                    if (count < ALPHABET) begin
                        if (freq[count] > max_freq) begin
                            max_freq <= freq[count];
                        end
                        count <= count + 1;
                    end else begin
                        count <= 0;
                    end
                end

                CHECK: begin
                    if (max_freq > threshold) begin
                        impossible <= 1;
                    end else begin
                        impossible <= 0;
                        current_letter <= 0;
                        output_count <= 0;
                        idx <= 0;
                    end
                end

                GEN_OUTPUT: begin
                    if (idx < N) begin
                        if (output_count < freq[current_letter]) begin
                            char_out[idx] <= current_letter;
                            idx <= idx + 1;
                            output_count <= output_count + 1;
                        end else begin
                            current_letter <= current_letter + 1;
                            output_count <= 0;
                        end
                    end
                end

                DONE: begin
                    done <= 1;
                    out_valid <= 1;
                end
            endcase
        end
    end

    // Combinational next state logic
    always @(*) begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (start) next_state = COUNT_FREQ;
            end

            COUNT_FREQ: begin
                if (count == N) next_state = FIND_MAX;
            end

            FIND_MAX: begin
                if (count == ALPHABET) next_state = CHECK;
            end

            CHECK: begin
                if (max_freq > threshold) begin
                    next_state = DONE;
                end else begin
                    next_state = GEN_OUTPUT;
                end
            end

            GEN_OUTPUT: begin
                if (idx == N) next_state = DONE;
            end

            DONE: begin
                next_state = DONE;
            end
        endcase
    end

endmodule

