import cocotb
from cocotb.triggers import Timer, RisingEdge, FallingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# ============================================================================
# CONFIGURATION
# ============================================================================
N = 8  # Fixed string length
ALPHABET = 26
DATA_WIDTH = 5
CLK_PERIOD_NS = 10
MAX_CYCLES = 1000

# ============================================================================
# MANDATORY HELPER FUNCTIONS
# ============================================================================

def is_value_defined(value):
    """Check if a cocotb value is defined (not X or Z)."""
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    """Safely convert cocotb value to int, returning default if X/Z."""
    try:
        return int(value)
    except ValueError:
        return default

def to_signed(val, bits):
    """Convert unsigned integer to signed (two's complement)."""
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    """Convert signed integer to unsigned for Verilog assignment."""
    if val < 0:
        return val + (1 << bits)
    return val

def has_signal(dut, name):
    """Check if DUT has a signal with given name."""
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(value, bits):
    """Clamp value to fit within specified bit width (unsigned)."""
    max_val = (1 << bits) - 1
    return min(max_val, max(0, value))

# ============================================================================
# ARRAY ACCESS HELPERS
# ============================================================================

async def write_array(dut, array_name, values, element_width):
    """Write values to array, handling different interface styles."""
    try:
        arr = getattr(dut, array_name)
        for i, val in enumerate(values):
            arr[i].value = clamp_to_width(val, element_width)
        return
    except (AttributeError, TypeError):
        pass

    for i, val in enumerate(values):
        port_name = f"{array_name}_{i}"
        if has_signal(dut, port_name):
            getattr(dut, port_name).value = clamp_to_width(val, element_width)
        else:
            raise TestFailure(f"Cannot find array port: {array_name}[{i}] or {port_name}")

async def read_array(dut, array_name, size):
    """Read array values, handling different interface styles."""
    results = []

    try:
        arr = getattr(dut, array_name)
        for i in range(size):
            if is_value_defined(arr[i].value):
                results.append(int(arr[i].value))
            else:
                results.append(None)
        return results
    except (AttributeError, TypeError):
        pass

    for i in range(size):
        port_name = f"{array_name}_{i}"
        if has_signal(dut, port_name):
            val = getattr(dut, port_name).value
            if is_value_defined(val):
                results.append(int(val))
            else:
                results.append(None)
        else:
            results.append(None)

    return results

# ============================================================================
# SEQUENTIAL MODULE HELPERS
# ============================================================================

async def reset_dut(dut, cycles=2):
    """Reset the DUT (active-low reset)."""
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0

    for _ in range(cycles):
        await RisingEdge(dut.clk)

    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    """Wait for done signal with timeout."""
    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout: done not asserted after {max_cycles} cycles")

async def start_computation(dut):
    """Pulse start signal for one cycle."""
    dut.start.value = 1
    await RisingEdge(dut.clk)
    dut.start.value = 0

# ============================================================================
# STRING HELPER FUNCTIONS
# ============================================================================

def char_to_bits(c):
    """Convert character 'a'-'z' to 5-bit value 0-25."""
    return ord(c) - ord('a')

def bits_to_char(bits):
    """Convert 5-bit value 0-25 to character 'a'-'z'."""
    return chr(bits + ord('a'))

def pack_string(s):
    """Pack string into list of 5-bit values."""
    return [char_to_bits(c) for c in s]

def unpack_string(values):
    """Convert list of 5-bit values back to string."""
    return ''.join(bits_to_char(v) for v in values)

# ============================================================================
# MAIN TEST
# ============================================================================

@cocotb.test(timeout_time=5000, timeout_unit="ms")
async def test_string_rearrange(dut):
    """Test string rearrange module with adapted test cases."""

    # Start clock
    cocotb.start_soon(Clock(dut.clk, CLK_PERIOD_NS, units='ns').start())

    # Reset
    await reset_dut(dut)

    # Adapted test cases for N=8
    # Format: (input_string, expected_impossible)
    test_cases = [
        ("tralalal", False),  # Should be possible
        ("zzzzzzzz", True),   # z=8, N/2=4, 8>4 -> impossible
        ("annorlun", False),  # From "annorlunda" shortened
    ]

    passed = 0
    failed = 0

    for i, (input_str, expected_impossible) in enumerate(test_cases):
        cocotb.log.info(f"Test {i+1}: Input '{input_str}' (N={len(input_str)})")

        # Verify input length matches N
        if len(input_str) != N:
            cocotb.log.error(f"Test case error: expected length {N}, got {len(input_str)}")
            failed += 1
            continue

        try:
            # Pack input string
            input_bits = pack_string(input_str)

            # Write input characters to DUT
            for idx in range(N):
                dut.char_in[idx].value = input_bits[idx]

            # Start computation
            await start_computation(dut)
            await wait_for_done(dut)

            # Read impossible flag
            if not is_value_defined(dut.impossible.value):
                raise TestFailure("impossible signal is undefined")

            is_impossible = int(dut.impossible.value) == 1

            # Check if expectation matches
            if is_impossible != expected_impossible:
                raise TestFailure(
                    f"Expected impossible={expected_impossible}, got {is_impossible}"
                )

            if expected_impossible:
                cocotb.log.info(f"  PASS: Correctly identified as impossible")
            else:
                # Read output string
                output_bits = []
                for idx in range(N):
                    if not is_value_defined(dut.char_out[idx].value):
                        raise TestFailure(f"Output char {idx} is undefined")
                    output_bits.append(int(dut.char_out[idx].value))

                output_str = unpack_string(output_bits)

                # Verify it's a permutation of input
                if sorted(output_str) != sorted(input_str):
                    raise TestFailure(
                        f"Output '{output_str}' is not a permutation of input '{input_str}'"
                    )

                # Verify all substrings are different
                half = N // 2
                substrings = [output_str[i:i+half] for i in range(half+1)]
                if len(substrings) != len(set(substrings)):
                    raise TestFailure(
                        f"Output has duplicate substrings: {substrings}"
                    )

                cocotb.log.info(f"  PASS: Output '{output_str}' is valid")

            passed += 1

        except TestFailure as e:
            cocotb.log.error(f"  FAIL: {e}")
            failed += 1

    # Summary
    cocotb.log.info(f"{'='*50}")
    cocotb.log.info(f"Results: {passed}/{passed+failed} tests passed")

    if failed > 0:
        raise TestFailure(f"{failed} tests failed")

verilog_prompt:
module tram_explosion #(
    parameter MAX_R = 4,
    parameter MAX_C = 4,
    parameter MAX_X = 4,
    parameter MAX_L = 4,
    parameter CLK_LIMIT = 100
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [MAX_R*MAX_C*2-1:0] grid,
    output reg [3:0] explosions,
    output reg done
);

// State definitions
localparam IDLE = 4'b0000;
localparam INIT = 4'b0001;
localparam FIND_CLOSEST = 4'b0010;
localparam CHECK_CONFLICTS = 4'b0011;
localparam RESOLVE_EXPLOSIONS = 4'b0100;
localparam RESOLVE_SEATING = 4'b0101;
localparam UPDATE_GRID = 4'b0110;
localparam CHECK_IF_MORE_ROUNDS = 4'b0111;
localparam DONE = 4'b1000;

reg [3:0] state, next_state;
reg [3:0] explosion_cnt, next_explosion_cnt;
reg [7:0] clock_counter, next_clock_counter;
reg [MAX_R*MAX_C*2-1:0] current_grid, next_current_grid;

// X and L positions and counts
reg [3:0] x_pos [0:MAX_X-1];
reg [2:0] x_count, next_x_count;
reg [3:0] l_pos [0:MAX_L-1];
reg [2:0] l_count, next_l_count;

// For current round: for each X, closest L and distance
reg [3:0] x_target_l [0:MAX_X-1];
reg [15:0] x_target_dist [0:MAX_X-1];

// For each L, list of X targeting it (bitmask)
reg [MAX_X-1:0] l_target_mask [0:MAX_L-1];
reg [15:0] l_target_min_dist [0:MAX_L-1];

// Helper function to get cell value
function [1:0] get_cell;
    input [MAX_R*MAX_C*2-1:0] grid_val;
    input [5:0] index;
    begin
        get_cell = grid_val[index*2 +: 2];
    end
endfunction

// Helper function to compute squared distance
function [15:0] compute_dist;
    input [3:0] pos1, pos2;
    integer r1, c1, r2, c2;
    begin
        r1 = pos1 / MAX_C;
        c1 = pos1 % MAX_C;
        r2 = pos2 / MAX_C;
        c2 = pos2 % MAX_C;
        compute_dist = (r1 - r2)*(r1 - r2) + (c1 - c2)*(c1 - c2);
    end
endfunction

integer i, j, k;

// State register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        explosion_cnt <= 0;
        clock_counter <= 0;
        current_grid <= 0;
        x_count <= 0;
        l_count <= 0;
    end else begin
        state <= next_state;
        explosion_cnt <= next_explosion_cnt;
        clock_counter <= next_clock_counter;
        current_grid <= next_current_grid;
        x_count <= next_x_count;
        l_count <= next_l_count;
    end
end

// Next state and datapath
always @(*) begin
    next_state = state;
    next_explosion_cnt = explosion_cnt;
    next_clock_counter = clock_counter + 1;
    next_current_grid = current_grid;
    next_x_count = x_count;
    next_l_count = l_count;

    done = 0;

    case (state)
        IDLE: begin
            next_clock_counter = 0;
            next_explosion_cnt = 0;
            if (start) begin
                next_current_grid = grid;
                next_state = INIT;
            end
        end

        INIT: begin
            // Extract X and L positions from current_grid
            next_x_count = 0;
            next_l_count = 0;
            for (i = 0; i < MAX_R*MAX_C; i = i + 1) begin
                if (get_cell(current_grid, i) == 2'b01 && next_x_count < MAX_X) begin
                    x_pos[next_x_count] = i;
                    next_x_count = next_x_count + 1;
                end else if (get_cell(current_grid, i) == 2'b10 && next_l_count < MAX_L) begin
                    l_pos[next_l_count] = i;
                    next_l_count = next_l_count + 1;
                end
            end
            next_state = FIND_CLOSEST;
        end

        FIND_CLOSEST: begin
            // For each X, find the closest L
            for (i = 0; i < MAX_X; i = i + 1) begin
                if (i < x_count) begin
                    x_target_dist[i] = 16'hFFFF;
                    x_target_l[i] = 0;
                    for (j = 0; j < MAX_L; j = j + 1) begin
                        if (j < l_count) begin
                            if (compute_dist(x_pos[i], l_pos[j]) < x_target_dist[i]) begin
                                x_target_dist[i] = compute_dist(x_pos[i], l_pos[j]);
                                x_target_l[i] = j;
                            end
                        end
                    end
                end
            end
            next_state = CHECK_CONFLICTS;
        end

        CHECK_CONFLICTS: begin
            // Initialize l_target_mask and l_target_min_dist
            for (j = 0; j < MAX_L; j = j + 1) begin
                l_target_mask[j] = 0;
                l_target_min_dist[j] = 16'hFFFF;
            end
            // For each X, add to its target L's mask
            for (i = 0; i < x_count; i = i + 1) begin
                j = x_target_l[i];
                l_target_mask[j] = l_target_mask[j] | (1 << i);
                if (x_target_dist[i] < l_target_min_dist[j]) begin
                    l_target_min_dist[j] = x_target_dist[i];
                end
            end
            next_state = RESOLVE_EXPLOSIONS;
        end

        RESOLVE_EXPLOSIONS: begin
            // Check for explosions
            for (j = 0; j < l_count; j = j + 1) begin
                integer x_count_for_l = 0;
                reg [MAX_X-1:0] mask = l_target_mask[j];
                for (i = 0; i < MAX_X; i = i + 1) begin
                    if (mask[i]) x_count_for_l = x_count_for_l + 1;
                end
                if (x_count_for_l >= 2) begin
                    integer all_equal = 1;
                    for (i = 0; i < MAX_X; i = i + 1) begin
                        if (mask[i] && x_target_dist[i] != l_target_min_dist[j]) begin
                            all_equal = 0;
                        end
                    end
                    if (all_equal) begin
                        next_explosion_cnt = explosion_cnt + 1;
                    end
                end
            end
            next_state = RESOLVE_SEATING;
        end

        RESOLVE_SEATING: begin
            // Resolve seating and update counts
            reg [MAX_X-1:0] removed_x;
            reg [MAX_L-1:0] removed_l;
            removed_x = 0;
            removed_l = 0;

            for (j = 0; j < l_count; j = j + 1) begin
                integer x_count_for_l = 0;
                reg [MAX_X-1:0] mask = l_target_mask[j];
                for (i = 0; i < MAX_X; i = i + 1) begin
                    if (mask[i]) x_count_for_l = x_count_for_l + 1;
                end
                if (x_count_for_l >= 2) begin
                    integer all_equal = 1;
                    for (i = 0; i < MAX_X; i = i + 1) begin
                        if (mask[i] && x_target_dist[i] != l_target_min_dist[j]) begin
                            all_equal = 0;
                        end
                    end
                    if (all_equal) begin
                        // Explosion: remove all X in mask and this L
                        for (i = 0; i < MAX_X; i = i + 1) begin
                            if (mask[i]) removed_x[i] = 1;
                        end
                        removed_l[j] = 1;
                    end else begin
                        // No explosion: find unique closest X
                        integer winner_i = -1;
                        integer winner_count = 0;
                        for (i = 0; i < MAX_X; i = i + 1) begin
                            if (mask[i] && x_target_dist[i] == l_target_min_dist[j]) begin
                                winner_i = i;
                                winner_count = winner_count + 1;
                            end
                        end
                        if (winner_count == 1) begin
                            removed_x[winner_i] = 1;
                            removed_l[j] = 1;
                        end
                    end
                end else if (x_count_for_l == 1) begin
                    for (i = 0; i < MAX_X; i = i + 1) begin
                        if (mask[i]) begin
                            removed_x[i] = 1;
                            removed_l[j] = 1;
                            break;
                        end
                    end
                end
            end

            // Update counts
            next_x_count = 0;
            next_l_count = 0;
            for (i = 0; i < x_count; i = i + 1) begin
                if (!removed_x[i]) begin
                    x_pos[next_x_count] = x_pos[i];
                    next_x_count = next_x_count + 1;
                end
            end
            for (j = 0; j < l_count; j = j + 1) begin
                if (!removed_l[j]) begin
                    l_pos[next_l_count] = l_pos[j];
                    next_l_count = next_l_count + 1;
                end
            end
            next_state = UPDATE_GRID;
        end

        UPDATE_GRID: begin
            // Update grid (simplified: we don't need to track exact grid for counting)
            next_state = CHECK_IF_MORE_ROUNDS;
        end

        CHECK_IF_MORE_ROUNDS: begin
            if (next_x_count > 0 && next_l_count > 0 && clock_counter < CLK_LIMIT - 1) begin
                next_state = FIND_CLOSEST;
            end else begin
                next_state = DONE;
            end
        end

        DONE: begin
            done = 1;
            next_state = IDLE;
        end

        default: next_state = IDLE;
    endcase

    if (clock_counter >= CLK_LIMIT) begin
        next_state = DONE;
    end
end

// Output explosion count
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        explosions <= 0;
    end else begin
        if (state == DONE) begin
            explosions <= explosion_cnt;
        end
    end
end

endmodule

module IOUSettlement #(
    parameter N = 4,                    // Maximum number of friends (nodes)
    parameter M = 8,                    // Maximum number of IOUs (edges)
    parameter WEIGHT_WIDTH = 10,        // Width for debt amounts (max 1000)
    parameter NODE_WIDTH = 3,           // Width for node IDs (2^3=8 >= 4)
    parameter CYCLE_COUNT = 20          // Number of precomputed cycles for N=4
)(
    input clk,                          // Clock, rising edge
    input rst_n,                        // Active-low synchronous reset
    input start,                        // Start pulse (1 cycle)
    input [NODE_WIDTH-1:0] n,          // Actual number of friends (1 to N)
    input [3:0] m,                      // Actual number of IOUs (0 to M)
    input [M*NODE_WIDTH-1:0] a_flat,   // Packed a values (a0,a1,...aM-1)
    input [M*NODE_WIDTH-1:0] b_flat,   // Packed b values (b0,b1,...bM-1)
    input [M*WEIGHT_WIDTH-1:0] c_flat, // Packed c values (c0,c1,...cM-1)
    output reg done,                    // Done signal
    output reg [WEIGHT_WIDTH-1:0] graph [0:N-1][0:N-1] // Output debt matrix
);

// State machine states
localparam STATE_IDLE = 3'b000;
localparam STATE_LOAD = 3'b001;
localparam STATE_CANCEL_PASS = 3'b010;
localparam STATE_CHECK_CYCLE = 3'b011;
localparam STATE_SUBTRACT = 3'b100;
localparam STATE_OUTPUT = 3'b101;

reg [2:0] state, next_state;

// Unpacked input arrays
reg [NODE_WIDTH-1:0] a_reg [0:M-1];
reg [NODE_WIDTH-1:0] b_reg [0:M-1];
reg [WEIGHT_WIDTH-1:0] c_reg [0:M-1];

// Cycle cancellation registers
reg [CYCLE_COUNT-1:0] cycle_idx;          // Current cycle index
reg [1:0] cycle_len;                       // Length of current cycle
reg [NODE_WIDTH-1:0] edge_u [0:3];        // u nodes of edges in cycle
reg [NODE_WIDTH-1:0] edge_v [0:3];        // v nodes of edges in cycle
reg [WEIGHT_WIDTH-1:0] min_weight;        // Minimum weight in cycle
reg [WEIGHT_WIDTH-1:0] temp_weight;       // Temporary weight for comparison
reg cancel_occurred;                       // Flag if any cancellation in pass
reg [9:0] pass_count;                      // Safety counter for max passes

// ROM for precomputed cycles (for N=4)
// Each entry: {len, edge0_u, edge0_v, edge1_u, edge1_v, edge2_u, edge2_v, edge3_u, edge3_v}
// len is 2 bits, each node is 3 bits, so 2 + 8*3 = 26 bits per cycle
reg [25:0] cycle_rom [0:CYCLE_COUNT-1];

// Initialize ROM with all 20 cycles for N=4
initial begin
    // Cycle 0: (0,1) -> (1,0)  length=2
    cycle_rom[0] = 26'b01_000_001_001_000_000_000_000_000;
    // Cycle 1: (0,2) -> (2,0)  length=2
    cycle_rom[1] = 26'b01_000_010_010_000_000_000_000_000;
    // Cycle 2: (0,3) -> (3,0)  length=2
    cycle_rom[2] = 26'b01_000_011_011_000_000_000_000_000;
    // Cycle 3: (1,2) -> (2,1)  length=2
    cycle_rom[3] = 26'b01_001_010_010_001_000_000_000_000;
    // Cycle 4: (1,3) -> (3,1)  length=2
    cycle_rom[4] = 26'b01_001_011_011_001_000_000_000_000;
    // Cycle 5: (2,3) -> (3,2)  length=2
    cycle_rom[5] = 26'b01_010_011_011_010_000_000_000_000;
    // Cycle 6: (0,1)->(1,2)->(2,0)  length=3
    cycle_rom[6] = 26'b10_000_001_001_010_010_000_000_000;
    // Cycle 7: (0,1)->(1,3)->(3,0)  length=3
    cycle_rom[7] = 26'b10_000_001_001_011_011_000_000_000;
    // Cycle 8: (0,2)->(2,1)->(1,0)  length=3
    cycle_rom[8] = 26'b10_000_010_010_001_001_000_000_000;
    // Cycle 9: (0,2)->(2,3)->(3,0)  length=3
    cycle_rom[9] = 26'b10_000_010_010_011_011_000_000_000;
    // Cycle 10: (0,3)->(3,1)->(1,0)  length=3
    cycle_rom[10] = 26'b10_000_011_011_001_001_000_000_000;
    // Cycle 11: (0,3)->(3,2)->(2,0)  length=3
    cycle_rom[11] = 26'b10_000_011_011_010_010_000_000_000;
    // Cycle 12: (1,2)->(2,3)->(3,1)  length=3
    cycle_rom[12] = 26'b10_001_010_010_011_011_001_000_000;
    // Cycle 13: (1,3)->(3,2)->(2,1)  length=3
    cycle_rom[13] = 26'b10_001_011_011_010_010_001_000_000;
    // Cycle 14: (0,1)->(1,2)->(2,3)->(3,0)  length=4
    cycle_rom[14] = 26'b11_000_001_001_010_010_011_011_000;
    // Cycle 15: (0,1)->(1,3)->(3,2)->(2,0)  length=4
    cycle_rom[15] = 26'b11_000_001_001_011_011_010_010_000;
    // Cycle 16: (0,2)->(2,1)->(1,3)->(3,0)  length=4
    cycle_rom[16] = 26'b11_000_010_010_001_001_011_011_000;
    // Cycle 17: (0,2)->(2,3)->(3,1)->(1,0)  length=4
    cycle_rom[17] = 26'b11_000_010_010_011_011_001_001_000;
    // Cycle 18: (0,3)->(3,1)->(1,2)->(2,0)  length=4
    cycle_rom[18] = 26'b11_000_011_011_001_001_010_010_000;
    // Cycle 19: (0,3)->(3,2)->(2,1)->(1,0)  length=4
    cycle_rom[19] = 26'b11_000_011_011_010_010_001_001_000;
end

// Unpack inputs into arrays
integer i;
always @(posedge clk) begin
    if (state == STATE_LOAD) begin
        for (i = 0; i < M; i = i + 1) begin
            a_reg[i] <= a_flat[i*NODE_WIDTH +: NODE_WIDTH];
            b_reg[i] <= b_flat[i*NODE_WIDTH +: NODE_WIDTH];
            c_reg[i] <= c_flat[i*WEIGHT_WIDTH +: WEIGHT_WIDTH];
        end
    end
end

// State transition and output logic
always @(posedge clk) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        done <= 0;
        graph <= '{default: 0};
        cycle_idx <= 0;
        cancel_occurred <= 0;
        pass_count <= 0;
    end else begin
        case (state)
            STATE_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= STATE_LOAD;
                    // Clear graph
                    graph <= '{default: 0};
                    cycle_idx <= 0;
                    cancel_occurred <= 0;
                    pass_count <= 0;
                end
            end

            STATE_LOAD: begin
                // Load IOUs into graph
                for (i = 0; i < M; i = i + 1) begin
                    if (i < m) begin
                        graph[a_reg[i]][b_reg[i]] <= c_reg[i];
                    end
                end
                state <= STATE_CANCEL_PASS;
            end

            STATE_CANCEL_PASS: begin
                // Start a new pass
                cancel_occurred <= 0;
                cycle_idx <= 0;
                state <= STATE_CHECK_CYCLE;
                pass_count <= pass_count + 1;
            end

            STATE_CHECK_CYCLE: begin
                if (cycle_idx >= CYCLE_COUNT) begin
                    // Finished this pass
                    if (cancel_occurred && pass_count < 1000) begin
                        state <= STATE_CANCEL_PASS; // Another pass
                    end else begin
                        state <= STATE_OUTPUT;      // Done
                    end
                end else begin
                    // Read current cycle from ROM
                    {cycle_len, edge_u[0], edge_v[0], edge_u[1], edge_v[1], 
                     edge_u[2], edge_v[2], edge_u[3], edge_v[3]} <= cycle_rom[cycle_idx];
                    state <= STATE_SUBTRACT;
                    min_weight <= {WEIGHT_WIDTH{1'b1}}; // Set to max value
                end
            end

            STATE_SUBTRACT: begin
                // Check if all edges in cycle have positive weight
                if (graph[edge_u[0]][edge_v[0]] > 0 &&
                    (cycle_len < 2 || graph[edge_u[1]][edge_v[1]] > 0) &&
                    (cycle_len < 3 || graph[edge_u[2]][edge_v[2]] > 0) &&
                    (cycle_len < 4 || graph[edge_u[3]][edge_v[3]] > 0)) begin
                    // Find minimum weight
                    min_weight <= graph[edge_u[0]][edge_v[0]];
                    if (cycle_len >= 2 && graph[edge_u[1]][edge_v[1]] < min_weight)
                        min_weight <= graph[edge_u[1]][edge_v[1]];
                    if (cycle_len >= 3 && graph[edge_u[2]][edge_v[2]] < min_weight)
                        min_weight <= graph[edge_u[2]][edge_v[2]];
                    if (cycle_len >= 4 && graph[edge_u[3]][edge_v[3]] < min_weight)
                        min_weight <= graph[edge_u[3]][edge_v[3]];
                    // Subtract min from all edges
                    graph[edge_u[0]][edge_v[0]] <= graph[edge_u[0]][edge_v[0]] - min_weight;
                    if (cycle_len >= 2)
                        graph[edge_u[1]][edge_v[1]] <= graph[edge_u[1]][edge_v[1]] - min_weight;
                    if (cycle_len >= 3)
                        graph[edge_u[2]][edge_v[2]] <= graph[edge_u[2]][edge_v[2]] - min_weight;
                    if (cycle_len >= 4)
                        graph[edge_u[3]][edge_v[3]] <= graph[edge_u[3]][edge_v[3]] - min_weight;
                    cancel_occurred <= 1;
                end
                cycle_idx <= cycle_idx + 1;
                state <= STATE_CHECK_CYCLE;
            end

            STATE_OUTPUT: begin
                done <= 1;
                // Hold graph values for reading
                state <= STATE_IDLE;
            end

            default: state <= STATE_IDLE;
        endcase
    end
end

endmodule

module packing_solver (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] N,
    output reg [15:0] result,
    output reg done
);

// State definitions
localparam IDLE = 3'd0;
localparam INIT = 3'd1;
localparam COMPUTE_W = 3'd2;
localparam CHECK_RATIO = 3'd3;
localparam UPDATE_MIN = 3'd4;
localparam INCREMENT_H = 3'd5;
localparam DONE = 3'd6;

reg [2:0] state, next_state;

// Internal registers
reg [15:0] H;           // Current H (1 to 256)
reg [15:0] W;           // Computed W
reg [15:0] min_empty;   // Minimum empty squares
reg [31:0] area;        // W * H
reg [15:0] div_a;       // Numerator for division
reg [15:0] div_b;       // Denominator for division
reg [15:0] div_quotient; // Division result
reg div_done;
reg div_start;

// Division unit (repeated subtraction)
reg [15:0] div_rem;
reg [7:0] div_cycles;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        H <= 0;
        min_empty <= 16'hFFFF;
        div_done <= 1;
    end else begin
        state <= next_state;

        case (state)
            INIT: begin
                H <= 1;
                min_empty <= 16'hFFFF;
            end

            COMPUTE_W: begin
                // W = ceil(N/H) = (N + H - 1) / H
                div_a <= N + H - 1;
                div_b <= H;
                div_start <= 1;
                div_done <= 0;
                div_quotient <= 0;
                div_rem <= N + H - 1;
                div_cycles <= 0;
            end

            CHECK_RATIO: begin
                if (!div_done) begin
                    // Continue division (max 16 cycles)
                    if (div_cycles < 16) begin
                        if (div_rem >= div_b) begin
                            div_rem <= div_rem - div_b;
                            div_quotient <= div_quotient + 1;
                        end
                        div_cycles <= div_cycles + 1;
                    end else begin
                        // Check remainder for ceil
                        if (div_rem > 0) div_quotient <= div_quotient + 1;
                        div_done <= 1;
                    end
                end else begin
                    W <= div_quotient;
                    // Check ratio: H/2 <= W <= 2H
                    // Use integer check: 2*W >= H and W <= 2*H
                    if (({1'b0, W} * 2 >= H) && (W <= ({1'b0, H} * 2))) begin
                        area <= W * H;
                    end else begin
                        area <= 32'hFFFF;  // Mark invalid
                    end
                end
            end

            UPDATE_MIN: begin
                if (area < 32'hFFFF && area >= N) begin
                    if (area - N < min_empty) begin
                        min_empty <= area - N;
                    end
                end
            end

            INCREMENT_H: begin
                H <= H + 1;
            end

            DONE: begin
                result <= min_empty;
                done <= 1;
            end
        endcase
    end
end

// State transitions
always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = INIT;
        INIT: next_state = COMPUTE_W;
        COMPUTE_W: next_state = CHECK_RATIO;
        CHECK_RATIO: if (div_done) next_state = UPDATE_MIN;
        UPDATE_MIN: next_state = INCREMENT_H;
        INCREMENT_H: begin
            if (H > 16'd256) next_state = DONE;  // Max iterations
            else next_state = COMPUTE_W;
        end
        DONE: next_state = IDLE;
    endcase
end

endmodule

module gold_leaf_fold (
    input clk,
    input rst_n,
    input start,
    input [3:0] n, m,  // max 8x8
    input [63:0] grid, // 8x8 packed: row-major, each cell 1 bit
    output reg [3:0] r1, c1, r2, c2,
    output reg done
);

// Internal state machine
reg [2:0] state;
reg [2:0] fold_type; // 0:horizontal, 1:vertical, 2:diag1(45), 3:diag2(135)
reg [3:0] fold_param; // i for horizontal, j for vertical, k for diagonal
reg [3:0] check_r, check_c;
reg [3:0] best_r1, best_c1, best_r2, best_c2;
reg valid_found;

// State definitions
localparam IDLE = 0;
localparam CHECK_FOLD = 1;
localparam NEXT_FOLD = 2;
localparam DONE = 3;

// Helper function to get grid cell (0-indexed)
function get_cell;
    input [3:0] r, c;
    get_cell = grid[r * 8 + c];
endfunction

// Mirror calculation functions
function [7:0] mirror_horizontal; // returns {r2, c2}
    input [3:0] r, c, i;
    begin
        mirror_horizontal = {2*i + 1 - r, c};
    end
endfunction

function [7:0] mirror_vertical;
    input [3:0] r, c, j;
    begin
        mirror_vertical = {r, 2*j + 1 - c};
    end
endfunction

function [7:0] mirror_diag1; // slope 1: r-c = k
    input [3:0] r, c, k;
    begin
        mirror_diag1 = {k + c, r - k};
    end
endfunction

function [7:0] mirror_diag2; // slope -1: r+c = k
    input [3:0] r, c, k;
    begin
        mirror_diag2 = {k - c, k - r};
    end
endfunction

// Check if fold is valid for current candidate
reg check_valid;

always @(*) begin
    check_valid = 1;
    case (fold_type)
        0: begin // horizontal
            for (check_r = 0; check_r < n; check_r = check_r + 1) begin
                for (check_c = 0; check_c < m; check_c = check_c + 1) begin
                    if (check_r < fold_param) begin
                        // Check mirror
                        if (mirror_horizontal(check_r, check_c, fold_param) < {n, m}) begin
                            if (get_cell(check_r, check_c) && get_cell(mirror_horizontal(check_r, check_c, fold_param))) begin
                                check_valid = 0;
                            end
                        end
                    end
                end
            end
        end
        1: begin // vertical
            for (check_r = 0; check_r < n; check_r = check_r + 1) begin
                for (check_c = 0; check_c < m; check_c = check_c + 1) begin
                    if (check_c < fold_param) begin
                        if (mirror_vertical(check_r, check_c, fold_param) < {n, m}) begin
                            if (get_cell(check_r, check_c) && get_cell(mirror_vertical(check_r, check_c, fold_param))) begin
                                check_valid = 0;
                            end
                        end
                    end
                end
            end
        end
        2: begin // diag1 - check fold line cells are '#'
            // Check fold line cells
            for (check_r = 0; check_r < n; check_r = check_r + 1) begin
                for (check_c = 0; check_c < m; check_c = check_c + 1) begin
                    if (check_r - check_c == fold_param) begin
                        if (!get_cell(check_r, check_c)) begin
                            check_valid = 0;
                        end
                    end
                end
            end
            // Check pairs
            if (check_valid) begin
                for (check_r = 0; check_r < n; check_r = check_r + 1) begin
                    for (check_c = 0; check_c < m; check_c = check_c + 1) begin
                        if (check_r - check_c != fold_param) begin
                            if (mirror_diag1(check_r, check_c, fold_param) < {n, m}) begin
                                if (get_cell(check_r, check_c) && get_cell(mirror_diag1(check_r, check_c, fold_param))) begin
                                    check_valid = 0;
                                end
                            end
                        end
                    end
                end
            end
        end
        3: begin // diag2 - check fold line cells are '#'
            // Check fold line cells
            for (check_r = 0; check_r < n; check_r = check_r + 1) begin
                for (check_c = 0; check_c < m; check_c = check_c + 1) begin
                    if (check_r + check_c == fold_param) begin
                        if (!get_cell(check_r, check_c)) begin
                            check_valid = 0;
                        end
                    end
                end
            end
            // Check pairs
            if (check_valid) begin
                for (check_r = 0; check_r < n; check_r = check_r + 1) begin
                    for (check_c = 0; check_c < m; check_c = check_c + 1) begin
                        if (check_r + check_c != fold_param) begin
                            if (mirror_diag2(check_r, check_c, fold_param) < {n, m}) begin
                                if (get_cell(check_r, check_c) && get_cell(mirror_diag2(check_r, check_c, fold_param))) begin
                                    check_valid = 0;
                                end
                            end
                        end
                    end
                end
            end
        end
    endcase
end

// Update best fold
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        valid_found <= 0;
        best_r1 <= 4'd15;
        best_c1 <= 4'd15;
        best_r2 <= 4'd15;
        best_c2 <= 4'd15;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= CHECK_FOLD;
                    fold_type <= 0;
                    fold_param <= 1; // Start with i=1 for horizontal (between row 1-2)
                    done <= 0;
                end
            end
            CHECK_FOLD: begin
                if (check_valid) begin
                    // Compute output coordinates
                    case (fold_type)
                        0: begin // horizontal: (i,1,i,m)
                            r1 <= fold_param;
                            c1 <= 1;
                            r2 <= fold_param;
                            c2 <= m;
                        end
                        1: begin // vertical: (1,j,n,j)
                            r1 <= 1;
                            c1 <= fold_param;
                            r2 <= n;
                            c2 <= fold_param;
                        end
                        2: begin // diag1: find endpoints
                            // Simplified: output (1,1,n,m) for now
                            r1 <= 1; c1 <= 1; r2 <= n; c2 <= m;
                        end
                        3: begin // diag2: output (n,1,1,m)
                            r1 <= n; c1 <= 1; r2 <= 1; c2 <= m;
                        end
                    endcase
                    state <= NEXT_FOLD;
                end else begin
                    state <= NEXT_FOLD;
                end
            end
            NEXT_FOLD: begin
                // Move to next candidate
                if (fold_type == 0 && fold_param < n-1) begin
                    fold_param <= fold_param + 1;
                    state <= CHECK_FOLD;
                end else if (fold_type == 0) begin
                    fold_type <= 1;
                    fold_param <= 1;
                    state <= CHECK_FOLD;
                end else if (fold_type == 1 && fold_param < m-1) begin
                    fold_param <= fold_param + 1;
                    state <= CHECK_FOLD;
                end else if (fold_type == 1) begin
                    fold_type <= 2;
                    fold_param <= 0;
                    state <= CHECK_FOLD;
                end else if (fold_type == 2 && fold_param < 8) begin // Simplified range
                    fold_param <= fold_param + 1;
                    state <= CHECK_FOLD;
                end else if (fold_type == 2) begin
                    fold_type <= 3;
                    fold_param <= 2;
                    state <= CHECK_FOLD;
                end else if (fold_type == 3 && fold_param < 8) begin
                    fold_param <= fold_param + 1;
                    state <= CHECK_FOLD;
                end else begin
                    state <= DONE;
                    done <= 1;
                end
            end
            DONE: begin
                state <= IDLE;
                done <= 0;
            end
        endcase
    end
end

endmodule

module min_cost_solver #(
    parameter MAX_FACTORS = 4,
    parameter MAX_EXP = 3,
    parameter DATA_WIDTH = 8,
    parameter RESULT_WIDTH = 64,
    parameter MOD = 1000000007
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] factor_count,
    input wire [DATA_WIDTH-1:0] prime_0,
    input wire [DATA_WIDTH-1:0] prime_1,
    input wire [DATA_WIDTH-1:0] prime_2,
    input wire [DATA_WIDTH-1:0] prime_3,
    input wire [DATA_WIDTH-1:0] exp_0,
    input wire [DATA_WIDTH-1:0] exp_1,
    input wire [DATA_WIDTH-1:0] exp_2,
    input wire [DATA_WIDTH-1:0] exp_3,
    output reg [RESULT_WIDTH-1:0] result,
    output reg done
);

// Internal state machine states
localparam S_IDLE = 0;
localparam S_LOAD = 1;
localparam S_COMPUTE_POWERS = 2;
localparam S_ENUMERATE = 3;
localparam S_COMPUTE_M = 4;
localparam S_COMPUTE_N = 5;
localparam S_COMPUTE_COST = 6;
localparam S_UPDATE_MIN = 7;
localparam S_DONE = 8;

// Registers for input storage
reg [DATA_WIDTH-1:0] primes [0:MAX_FACTORS-1];
reg [DATA_WIDTH-1:0] exps [0:MAX_FACTORS-1];
reg [1:0] valid_factors;

// Power storage
reg [15:0] powers [0:MAX_FACTORS-1][0:MAX_EXP];
reg [1:0] power_prime_idx;
reg [1:0] power_exp_idx;

// Enumeration registers
reg [1:0] a [0:MAX_FACTORS-1];
reg [1:0] mult_idx;
reg [RESULT_WIDTH-1:0] M;
reg [RESULT_WIDTH-1:0] N;
reg [RESULT_WIDTH-1:0] cost;
reg [RESULT_WIDTH-1:0] min_cost;

// State register
reg [3:0] state, next_state;

// Next state logic
always @(*) begin
    case (state)
        S_IDLE: next_state = start ? S_LOAD : S_IDLE;
        S_LOAD: next_state = S_COMPUTE_POWERS;
        S_COMPUTE_POWERS: begin
            if (power_prime_idx < valid_factors) begin
                if (power_exp_idx <= exps[power_prime_idx])
                    next_state = S_COMPUTE_POWERS;
                else
                    next_state = (power_prime_idx == valid_factors-1) ? S_ENUMERATE : S_COMPUTE_POWERS;
            end else
                next_state = S_ENUMERATE;
        end
        S_ENUMERATE: next_state = S_COMPUTE_M;
        S_COMPUTE_M: begin
            if (mult_idx < valid_factors)
                next_state = S_COMPUTE_M;
            else
                next_state = S_COMPUTE_N;
        end
        S_COMPUTE_N: begin
            if (mult_idx < valid_factors)
                next_state = S_COMPUTE_N;
            else
                next_state = S_COMPUTE_COST;
        end
        S_COMPUTE_COST: next_state = S_UPDATE_MIN;
        S_UPDATE_MIN: begin
            if (enumeration_done)
                next_state = S_DONE;
            else
                next_state = S_ENUMERATE;
        end
        S_DONE: next_state = S_IDLE;
        default: next_state = S_IDLE;
    endcase
end

// State update
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= S_IDLE;
    else
        state <= next_state;
end

// Load inputs
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        primes[0] <= 0; primes[1] <= 0; primes[2] <= 0; primes[3] <= 0;
        exps[0] <= 0; exps[1] <= 0; exps[2] <= 0; exps[3] <= 0;
        valid_factors <= 0;
    end else if (state == S_LOAD) begin
        primes[0] <= prime_0; primes[1] <= prime_1; primes[2] <= prime_2; primes[3] <= prime_3;
        exps[0] <= exp_0; exps[1] <= exp_1; exps[2] <= exp_2; exps[3] <= exp_3;
        valid_factors <= factor_count;
    end
end

// Compute powers
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        power_prime_idx <= 0;
        power_exp_idx <= 0;
    end else if (state == S_COMPUTE_POWERS) begin
        if (power_prime_idx < valid_factors) begin
            if (power_exp_idx <= exps[power_prime_idx]) begin
                // Compute power: primes[power_prime_idx] ^ power_exp_idx
                if (power_exp_idx == 0)
                    powers[power_prime_idx][power_exp_idx] <= 16'd1;
                else
                    powers[power_prime_idx][power_exp_idx] <= powers[power_prime_idx][power_exp_idx-1] * primes[power_prime_idx];
                power_exp_idx <= power_exp_idx + 1;
            end else begin
                // Move to next prime
                power_exp_idx <= 0;
                power_prime_idx <= power_prime_idx + 1;
            end
        end
    end
end

// Enumeration and multiplication
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a[0] <= 0; a[1] <= 0; a[2] <= 0; a[3] <= 0;
        mult_idx <= 0;
        M <= 0;
        N <= 0;
        cost <= 0;
        min_cost <= {RESULT_WIDTH{1'b1}};
        done <= 0;
        result <= 0;
    end else begin
        case (state)
            S_ENUMERATE: begin
                // Initialize multiplication
                mult_idx <= 0;
                M <= 1;
                N <= 1;
            end
            S_COMPUTE_M: begin
                if (mult_idx < valid_factors) begin
                    M <= M * powers[mult_idx][a[mult_idx]];
                    mult_idx <= mult_idx + 1;
                end
            end
            S_COMPUTE_N: begin
                if (mult_idx < valid_factors) begin
                    N <= N * powers[mult_idx][exps[mult_idx] - a[mult_idx]];
                    mult_idx <= mult_idx + 1;
                end
            end
            S_COMPUTE_COST: begin
                cost <= M + N;
            end
            S_UPDATE_MIN: begin
                if (cost < min_cost)
                    min_cost <= cost;
                // Increment exponent indices (odometer)
                // Simplified for MAX_FACTORS=4 and MAX_EXP=3
                if (a[0] < exps[0]) begin
                    a[0] <= a[0] + 1;
                end else begin
                    a[0] <= 0;
                    if (valid_factors > 1) begin
                        if (a[1] < exps[1]) begin
                            a[1] <= a[1] + 1;
                        end else begin
                            a[1] <= 0;
                            if (valid_factors > 2) begin
                                if (a[2] < exps[2]) begin
                                    a[2] <= a[2] + 1;
                                end else begin
                                    a[2] <= 0;
                                    if (valid_factors > 3) begin
                                        if (a[3] < exps[3]) begin
                                            a[3] <= a[3] + 1;
                                        end else begin
                                            a[3] <= 0;
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            S_DONE: begin
                result <= min_cost % MOD;
                done <= 1;
            end
            default: begin
                done <= 0;
            end
        endcase
    end
end

// Signal to detect when all combinations have been processed
reg enumeration_done;
always @(*) begin
    enumeration_done = 1;
    if (valid_factors > 0 && a[0] < exps[0]) enumeration_done = 0;
    if (valid_factors > 1 && a[1] < exps[1]) enumeration_done = 0;
    if (valid_factors > 2 && a[2] < exps[2]) enumeration_done = 0;
    if (valid_factors > 3 && a[3] < exps[3]) enumeration_done = 0;
end

endmodule

module ham_distribution (
    input [7:0] A0, A1, A2,
    input [7:0] B0, B1, B2,
    output real result
);

real S;
real lower_bound;
real upper_bound;
real deltaA, deltaB;
real bound;

always @(*) begin
    S = B0 + B1 + B2;
    lower_bound = 0.0;
    upper_bound = 1e7; // 10 million

    // Pair (0,1)
    deltaA = A0 - A1;
    deltaB = B0 - B1;
    if (deltaB == 0.0) begin
        if (deltaA < 0.0) begin
            lower_bound = 1e8;
            upper_bound = -1e8;
        end
    end else begin
        bound = (-S * deltaA) / deltaB;
        if (deltaB > 0.0) begin
            if (bound > lower_bound) lower_bound = bound;
        end else begin
            if (bound < upper_bound) upper_bound = bound;
        end
    end

    // Pair (1,2)
    deltaA = A1 - A2;
    deltaB = B1 - B2;
    if (deltaB == 0.0) begin
        if (deltaA < 0.0) begin
            lower_bound = 1e8;
            upper_bound = -1e8;
        end
    end else begin
        bound = (-S * deltaA) / deltaB;
        if (deltaB > 0.0) begin
            if (bound > lower_bound) lower_bound = bound;
        end else begin
            if (bound < upper_bound) upper_bound = bound;
        end
    end

    // Finalize
    if (lower_bound < 0.0) lower_bound = 0.0;
    if (lower_bound > upper_bound || lower_bound > 1e7 || upper_bound < 0.0) begin
        result = -1.0;
    end else begin
        result = lower_bound; // any value in [lower, upper] works
    end
end

endmodule

