module find_polly #(
    parameter N = 8,                      // Number of boxes (fixed at 8)
    parameter WIDTH_ENERGY = 10,          // Bits for energy (0-1023)
    parameter WIDTH_PROB = 16,            // Bits for probability (Q8.8 format)
    parameter WIDTH_RESULT = 13           // Bits for result (0-8191)
)(
    input wire clk,
    input wire rst_n,
    input wire start,

    // Energy and probability inputs for each box
    // Q8.8 format: value = integer + fractional/256
    input wire [WIDTH_ENERGY-1:0] energy [0:N-1],
    input wire [WIDTH_PROB-1:0] prob [0:N-1],

    // Target probability in Q8.8 format
    input wire [WIDTH_PROB-1:0] P_target,

    // Outputs
    output reg [WIDTH_RESULT-1:0] min_energy,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam INIT = 3'b001;
localparam COMPUTE_SUBSET = 3'b010;
localparam CHECK_BIT = 3'b011;
localparam UPDATE_RESULT = 3'b100;
localparam INCREMENT = 3'b101;
localparam DONE = 3'b110;

// Registers
reg [2:0] state;
reg [7:0] subset_reg;        // Subset counter (0 to 255)
reg [2:0] bit_index;         // Bit position (0 to N-1)
reg [WIDTH_PROB-1:0] temp_prob_sum;
reg [WIDTH_RESULT-1:0] temp_energy_sum;
reg [WIDTH_RESULT-1:0] min_energy_reg;
reg [WIDTH_PROB-1:0] P_target_reg;

// Combinational signals
wire [WIDTH_PROB-1:0] prob_to_add;
wire [WIDTH_RESULT-1:0] energy_to_add;
wire subset_bit_set;
wire [7:0] max_subset;

assign max_subset = (1 << N) - 1; // 2^N - 1 (255 for N=8)
assign subset_bit_set = subset_reg[bit_index];
assign prob_to_add = prob[bit_index];
assign energy_to_add = energy[bit_index];

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        subset_reg <= 8'b0;
        bit_index <= 3'b0;
        temp_prob_sum <= 0;
        temp_energy_sum <= 0;
        min_energy_reg <= 0;
        P_target_reg <= 0;
        min_energy <= 0;
        done <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    state <= INIT;
                end
            end

            INIT: begin
                // Initialize min_energy to maximum value
                min_energy_reg <= {WIDTH_RESULT{1'b1}};
                subset_reg <= 8'b0;
                P_target_reg <= P_target;
                state <= COMPUTE_SUBSET;
            end

            COMPUTE_SUBSET: begin
                // Reset accumulators and start bit checking from bit 0
                temp_prob_sum <= 0;
                temp_energy_sum <= 0;
                bit_index <= 3'b0;
                state <= CHECK_BIT;
            end

            CHECK_BIT: begin
                // If current bit is set, add corresponding values
                if (subset_bit_set) begin
                    temp_prob_sum <= temp_prob_sum + prob_to_add;
                    temp_energy_sum <= temp_energy_sum + energy_to_add;
                end

                // Move to next bit
                bit_index <= bit_index + 1;

                // If we just checked the last bit (bit_index == N-1), go to UPDATE_RESULT
                if (bit_index == N - 1) begin
                    state <= UPDATE_RESULT;
                end else begin
                    state <= CHECK_BIT;
                end
            end

            UPDATE_RESULT: begin
                // Check if current subset meets probability requirement
                if (temp_prob_sum >= P_target_reg && temp_energy_sum < min_energy_reg) begin
                    min_energy_reg <= temp_energy_sum;
                end
                state <= INCREMENT;
            end

            INCREMENT: begin
                // Move to next subset
                subset_reg <= subset_reg + 1;

                // If we haven't processed the last subset yet, continue
                if (subset_reg < max_subset) begin
                    state <= COMPUTE_SUBSET;
                end else begin
                    state <= DONE;
                    min_energy <= min_energy_reg;
                end
            end

            DONE: begin
                done <= 1'b1;
                // Wait for reset or new start
                if (start) begin
                    state <= INIT;
                    done <= 1'b0;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module pokemon_go_cost (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] N,
    input wire [9:0] P_scaled, // P * 1000, integer from 0 to 1000
    output reg [63:0] cost,
    output reg done
);

    // Constants
    localparam NUM_STATES = 101;
    localparam STATE_BITS = 7;
    localparam FIXED_BITS = 32;

    // Internal variables (using real for simulation)
    real prob [0:NUM_STATES-1];
    real total_cost;
    real q;
    real q_power [0:NUM_STATES-1]; // q^i
    real P_real;
    real C [0:NUM_STATES-1];
    real T [0:NUM_STATES-1][0:NUM_STATES-1];

    integer i, j, k, step;
    reg computing;

    // Convert scaled P to real P and compute q
    always @(P_scaled) begin
        P_real = P_scaled / 1000.0;
        q = 1.0 - P_real;
        // Precompute q_power
        q_power[0] = 1.0;
        for (i = 1; i < NUM_STATES; i = i + 1) begin
            q_power[i] = q_power[i-1] * q;
        end
        // Precompute C
        for (i = 0; i < NUM_STATES; i = i + 1) begin
            if (i == 0) begin
                C[i] = 5.0;
            end else begin
                C[i] = 5.0 * q_power[i];
            end
        end
        // Precompute T
        for (i = 0; i < NUM_STATES; i = i + 1) begin
            for (j = 0; j < NUM_STATES; j = j + 1) begin
                T[i][j] = 0.0;
            end
            if (i == 0) begin
                T[0][100] = 1.0;
            end else begin
                // transitions to states i-1 down to 1
                for (k = 1; k < i; k = k + 1) begin
                    T[i][i - k] = P_real * q_power[k-1];
                end
                // catch on last ball
                T[i][0] = P_real * q_power[i-1];
                // fail after i balls
                T[i][100] = q_power[i];
            end
        end
    end

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
            cost <= 0;
            computing <= 0;
        end else if (start && !computing) begin
            // Initialize distribution
            for (i = 0; i < NUM_STATES; i = i + 1) begin
                prob[i] = 0.0;
            end
            prob[100] = 1.0;
            total_cost = 0.0;
            step = 0;
            computing <= 1;
            done <= 0;
        end else if (computing) begin
            if (step < N) begin
                // Compute immediate cost
                real cost_step = 0.0;
                for (i = 0; i < NUM_STATES; i = i + 1) begin
                    cost_step = cost_step + prob[i] * C[i];
                end
                total_cost = total_cost + cost_step;

                // Compute next distribution
                real prob_next [0:NUM_STATES-1];
                for (j = 0; j < NUM_STATES; j = j + 1) begin
                    prob_next[j] = 0.0;
                    for (i = 0; i < NUM_STATES; i = i + 1) begin
                        prob_next[j] = prob_next[j] + prob[i] * T[i][j];
                    end
                end

                // Update prob
                for (i = 0; i < NUM_STATES; i = i + 1) begin
                    prob[i] = prob_next[i];
                end

                step = step + 1;
            end else begin
                // Done
                cost <= total_cost * (1 << FIXED_BITS);
                done <= 1;
                computing <= 0;
            end
        end
    end

endmodule

module reconstruct (
    input clk,
    input rst_n,
    input start,
    input [7:0] B0, B1, B2, B3,
    output reg [15:0] A0, A1, A2, A3,
    output reg done
);

    // For N=4 only
    wire [15:0] A0_temp;
    wire [15:0] A1_temp;
    wire [15:0] A2_temp;
    wire [15:0] A3_temp;

    // Compute A0 = (B0 + B1 + B3 - 2*B2) / 3
    assign A0_temp = (B0 + B1 + B3 - (B2 << 1)) / 3;
    // Compute A1 = (B0 + B1 - B2) - 2*A0
    assign A1_temp = (B0 + B1 - B2) - (A0_temp << 1);
    // Compute A2 = B1 - A0 - A1
    assign A2_temp = B1 - A0_temp - A1_temp;
    // Compute A3 = B2 - A1 - A2 (equivalent to B2 - B1 + A0)
    assign A3_temp = B2 - A1_temp - A2_temp;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            A0 <= 16'd0;
            A1 <= 16'd0;
            A2 <= 16'd0;
            A3 <= 16'd0;
            done <= 1'b0;
        end else begin
            if (start) begin
                A0 <= A0_temp;
                A1 <= A1_temp;
                A2 <= A2_temp;
                A3 <= A3_temp;
                done <= 1'b1;
            end else begin
                done <= 1'b0;
            end
        end
    end
endmodule

module envelope_optimizer #(
    parameter N = 8,  // Max number of card types
    parameter K = 4,  // Max envelope types
    parameter DATA_W = 16,  // Data width for w,h,q
    parameter RESULT_W = 32  // Result width
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_W-1:0] card_width [N-1:0],
    input wire [DATA_W-1:0] card_height [N-1:0],
    input wire [DATA_W-1:0] card_qty [N-1:0],
    input wire [3:0] num_env_types,  // k (1-4)
    output reg [RESULT_W-1:0] result,
    output reg done
);

// States
localparam IDLE = 3'd0;
localparam COMPUTE_SUBSET = 3'd1;
localparam DP_INIT = 3'd2;
localparam DP_COMPUTE = 3'd3;
localparam FINISH = 3'd4;

reg [2:0] state;
reg [2:0] next_state;

// Memory for subset waste calculation (2^N = 256 entries)
reg [RESULT_W-1:0] subset_waste [0:255];
reg [7:0] subset_idx;  // Current subset being computed

// DP arrays: dp[mask][t]
reg [RESULT_W-1:0] dp [0:255];  // Current dp layer (t-1)
reg [RESULT_W-1:0] next_dp [0:255];  // Next dp layer (t)

// Helper variables
reg [7:0] mask;
reg [7:0] submask;
reg [DATA_W-1:0] max_w, max_h;
reg [DATA_W*2-1:0] env_area;
reg [RESULT_W-1:0] sum_qty;
reg [RESULT_W-1:0] sum_area;
reg [3:0] t;  // Current envelope type count
reg [7:0] i, j;
reg [RESULT_W-1:0] candidate;

// Combinational logic for subset computation
always @(*) begin
    // Calculate max width and height for current subset
    max_w = 0;
    max_h = 0;
    sum_qty = 0;
    sum_area = 0;

    for (i = 0; i < N; i = i + 1) begin
        if (subset_idx[i]) begin
            if (card_width[i] > max_w) max_w = card_width[i];
            if (card_height[i] > max_h) max_h = card_height[i];
            sum_qty = sum_qty + card_qty[i];
            sum_area = sum_area + (card_qty[i] * (card_width[i] * card_height[i]));
        end
    end

    env_area = max_w * max_h;
end

// Sequential state transitions
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        subset_idx <= 0;
        t <= 0;
        done <= 0;
        result <= 0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                if (start) begin
                    subset_idx <= 1;  // Start from subset {0} (but we'll process from 0)
                    t <= 1;
                    done <= 0;
                end
            end

            COMPUTE_SUBSET: begin
                // Calculate waste for current subset
                if (sum_qty > 0) begin
                    subset_waste[subset_idx] <= (env_area * sum_qty) - sum_area;
                end else begin
                    subset_waste[subset_idx] <= 0;
                end

                if (subset_idx == 255) begin
                    subset_idx <= 0;
                end else begin
                    subset_idx <= subset_idx + 1;
                end
            end

            DP_INIT: begin
                // Initialize dp[0][*] = 0, dp[mask][0] = INF for mask != 0
                if (subset_idx == 0) begin
                    dp[0] <= 0;
                    subset_idx <= 1;
                end else if (subset_idx < 255) begin
                    dp[subset_idx] <= 32'h7FFFFFFF;  // INF
                    subset_idx <= subset_idx + 1;
                end else begin
                    dp[255] <= 32'h7FFFFFFF;
                    subset_idx <= 0;
                    t <= 1;
                end
            end

            DP_COMPUTE: begin
                if (t <= num_env_types) begin
                    // For each mask, compute min over submask
                    if (mask == 0) begin
                        mask <= 1;
                        next_dp[0] <= dp[0];  // dp[0][t] = dp[0][t-1] = 0
                    end else if (mask < 255) begin
                        // Compute for current mask
                        if (submask == 0) begin
                            // Initialize with large value
                            next_dp[mask] <= 32'h7FFFFFFF;
                            submask <= mask;
                        end else if (submask > 0) begin
                            // submask is subset of mask
                            if (subset_waste[submask] < 32'h7FFFFFFF && dp[mask ^ submask] < 32'h7FFFFFFF) begin
                                candidate <= subset_waste[submask] + dp[mask ^ submask];
                            end else begin
                                candidate <= 32'h7FFFFFFF;
                            end

                            if (submask == mask) begin
                                submask <= 0;
                                mask <= mask + 1;
                            end else begin
                                // Find next submask using trick: (submask - 1) & mask
                                submask <= (submask - 1) & mask;
                            end
                        end else begin
                            // Done with this mask
                            if (next_dp[mask] > candidate) begin
                                next_dp[mask] <= candidate;
                            end
                        end
                    end else begin
                        // All masks computed for current t
                        // Copy next_dp to dp
                        if (subset_idx < 255) begin
                            dp[subset_idx] <= next_dp[subset_idx];
                            subset_idx <= subset_idx + 1;
                        end else begin
                            dp[255] <= next_dp[255];
                            subset_idx <= 0;
                            mask <= 0;
                            submask <= 0;
                            t <= t + 1;
                        end
                    end
                end else begin
                    // Finished all DP iterations
                    result <= dp[255];
                    done <= 1;
                end
            end

            FINISH: begin
                done <= 0;
            end
        endcase
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: begin
            if (start) next_state = COMPUTE_SUBSET;
        end

        COMPUTE_SUBSET: begin
            if (subset_idx == 255) next_state = DP_INIT;
        end

        DP_INIT: begin
            if (subset_idx == 255 && t == 1) next_state = DP_COMPUTE;
        end

        DP_COMPUTE: begin
            if (t > num_env_types) next_state = FINISH;
        end

        FINISH: begin
            if (!done) next_state = IDLE;
        end

        default: next_state = IDLE;
    endcase
end

endmodule

module hopper_exploration (
    input clk,
    input rst_n,
    input start,
    input [2:0] n,       // Number of valid elements (1-8)
    input [2:0] D,       // Maximum jump distance (1-7)
    input [7:0] M,       // Maximum value difference (0-255, signed)
    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7, // Array elements (8-bit signed)
    output reg [3:0] length, // Longest sequence length (1-8)
    output reg done           // Computation complete
);

// Parameters
parameter MAX_N = 8;
parameter STATE_IDLE = 2'b00;
parameter STATE_INIT = 2'b01;
parameter STATE_COMPUTE = 2'b10;
parameter STATE_DONE = 2'b11;

// Registers and wires
reg [1:0] state, next_state;
reg [2:0] i, j;              // Loop counters
reg [7:0] dp [0:255];        // DP table: 256 states, max length 8 (stored as 8-bit)
reg [7:0] max_len_reg;
reg [7:0] arr_reg [0:7];     // Local storage for array
reg [2:0] n_reg, D_reg;      // Local storage for parameters
reg [7:0] M_reg;

// Combinational signals
wire signed [7:0] arr_val_i;
wire signed [7:0] arr_val_j;
wire signed [7:0] diff;
wire [7:0] mask_bit;
wire [7:0] new_mask;
wire valid_jump;

// Assign array values
assign arr_val_i = arr_reg[i];
assign arr_val_j = arr_reg[j];
assign diff = arr_val_i - arr_val_j;
assign mask_bit = (1 << j);
assign new_mask = (1 << i) | (1 << j);
assign valid_jump = (j < n_reg) && (j != i) && (|diff[7] ? -diff : diff <= M_reg) && ($signed(i) - $signed(j) >= -$signed(D_reg)) && ($signed(i) - $signed(j) <= $signed(D_reg));

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        done <= 0;
        length <= 0;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    next_state = state;
    case (state)
        STATE_IDLE: if (start) next_state = STATE_INIT;
        STATE_INIT: next_state = STATE_COMPUTE;
        STATE_COMPUTE: if (i >= n_reg) next_state = STATE_DONE;
        STATE_DONE: next_state = STATE_IDLE;
    endcase
end

// Main computation logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all registers
        i <= 0;
        j <= 0;
        max_len_reg <= 0;
        done <= 0;
        length <= 0;
        // Clear dp table
        for (integer k = 0; k < 256; k = k + 1) dp[k] <= 0;
        // Clear arr_reg
        for (integer k = 0; k < 8; k = k + 1) arr_reg[k] <= 0;
        n_reg <= 0;
        D_reg <= 0;
        M_reg <= 0;
    end else begin
        case (state)
            STATE_INIT: begin
                // Load inputs into local registers
                arr_reg[0] <= arr_0;
                arr_reg[1] <= arr_1;
                arr_reg[2] <= arr_2;
                arr_reg[3] <= arr_3;
                arr_reg[4] <= arr_4;
                arr_reg[5] <= arr_5;
                arr_reg[6] <= arr_6;
                arr_reg[7] <= arr_7;
                n_reg <= n;
                D_reg <= D;
                M_reg <= M;
                // Initialize DP table for single-element sequences
                for (integer k = 0; k < 8; k = k + 1) begin
                    if (k < n) dp[1 << k] <= 1;
                    else dp[1 << k] <= 0;
                end
                i <= 0;
                j <= 0;
                max_len_reg <= 1; // Minimum length is 1
            end

            STATE_COMPUTE: begin
                if (i < n_reg) begin
                    if (j < n_reg) begin
                        // Check if j is reachable from i
                        if (valid_jump) begin
                            // Update DP state
                            // dp[new_mask][j] = max(dp[new_mask][j], dp[1<<i][i] + 1)
                            // We use flattened index: mask = (1<<i) | (1<<j)
                            if (dp[(1<<i) | (1<<j)] < dp[1<<i] + 1) begin
                                dp[(1<<i) | (1<<j)] <= dp[1<<i] + 1;
                                if (dp[1<<i] + 1 > max_len_reg) max_len_reg <= dp[1<<i] + 1;
                            end
                        end
                        j <= j + 1;
                    end else begin
                        j <= 0;
                        i <= i + 1;
                    end
                end
            end

            STATE_DONE: begin
                done <= 1;
                length <= max_len_reg[3:0]; // Truncate to 4 bits
            end

            STATE_IDLE: begin
                done <= 0;
                i <= 0;
                j <= 0;
            end
        endcase
    end
end

endmodule

