module decipher (
  input wire clk,
  input wire rst_n,
  input wire start,
  input wire [255:0] string_in,     // 32 chars * 8 bits
  input wire [511:0] dict_words,    // 8 words * 8 chars * 8 bits
  input wire [31:0] dict_lengths,   // 8 words * 4 bits (lengths 1-8)
  output reg done,
  output reg [1:0] result_status,   // 00=valid, 01=impossible, 10=ambiguous
  output reg [255:0] result_sentence // 32 chars for output
);

// States for the main FSM
localparam IDLE = 3'b000;
localparam PRECOMPUTE = 3'b001;
localparam SEARCH = 3'b010;
localparam RESULT = 3'b011;

reg [2:0] state, next_state;

// Word signature storage
reg [2:0] word_length [0:7];      // Length for each word (0-8)
reg [7:0] first_char [0:7];       // First character of each word
reg [7:0] last_char [0:7];        // Last character of each word
reg [127:0] internal_multiset [0:7]; // 26 letters * 5 bits (counts 0-20)

// Search variables
reg [4:0] string_pos;             // Current position in string (0-31)
reg [2:0] word_idx;               // Current word being checked
reg [2:0] match_count;            // Number of valid segmentations found
reg [2:0] segmentation_count;     // Count of ways to segment
reg [255:0] stored_sentence;      // First valid segmentation
reg [2:0] stored_word_count;      // Number of words in stored segmentation

// Helper: compute multiset of internal letters
function [127:0] compute_multiset(input [7:0] length, input [63:0] word);
  integer i;
  reg [7:0] char;
  begin
    compute_multiset = 128'b0;
    for (i = 1; i < length-1; i = i + 1) begin
      char = word[8*i +: 8]; // Extract character
      if (char >= 8'h61 && char <= 8'h7a) begin // 'a' to 'z'
        compute_multiset[char*5 +: 5] = compute_multiset[char*5 +: 5] + 1;
      end
    end
  end
endfunction

// Helper: check if substring matches word
function matches(input [4:0] str_pos, input [2:0] w_idx);
  reg [7:0] len;
  reg [7:0] s_first, s_last;
  reg [63:0] substring;
  reg [127:0] sub_multiset;
  begin
    len = word_length[w_idx];
    // Check if we have enough characters
    if (str_pos + len > 32) begin
      matches = 0;
    end else begin
      // Extract first and last characters from string
      s_first = string_in[8*str_pos +: 8];
      s_last = string_in[8*(str_pos+len-1) +: 8];
      // Extract substring (for multiset calculation)
      substring = string_in[8*str_pos +: 8*len];
      // Check length, first char, last char
      if (len == 0 || s_first != first_char[w_idx] || s_last != last_char[w_idx]) begin
        matches = 0;
      end else if (len <= 2) begin
        // For 1-2 char words, only first/last matters
        matches = 1;
      end else begin
        // Check internal letters multiset
        sub_multiset = compute_multiset(len, substring);
        matches = (sub_multiset == internal_multiset[w_idx]);
      end
    end
  end
endfunction

// State machine
always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state <= IDLE;
    done <= 0;
    result_status <= 2'b00;
    result_sentence <= 256'b0;
    string_pos <= 5'b0;
    word_idx <= 3'b0;
    match_count <= 3'b0;
    segmentation_count <= 3'b0;
  end else begin
    state <= next_state;

    case (state)
      PRECOMPUTE: begin
        // Precompute word signatures
        if (word_idx < 8) begin
          word_length[word_idx] = dict_lengths[word_idx*4 +: 4];
          first_char[word_idx] = dict_words[word_idx*64 +: 8];
          last_char[word_idx] = dict_words[word_idx*64 + 8*(dict_lengths[word_idx*4 +: 4]-1) +: 8];
          internal_multiset[word_idx] = compute_multiset(dict_lengths[word_idx*4 +: 4], dict_words[word_idx*64 +: 64]);
          word_idx <= word_idx + 1;
        end
      end

      SEARCH: begin
        if (string_pos < 32 && word_idx < 8) begin
          // Try to match current word at current position
          if (matches(string_pos, word_idx)) begin
            // Found a match - recursively continue from next position
            if (string_pos + word_length[word_idx] == 32) begin
              // Complete segmentation found
              segmentation_count <= segmentation_count + 1;
              if (segmentation_count == 0) begin
                // Store first valid segmentation
                stored_sentence <= result_sentence; // Will be built during reconstruction
                stored_word_count <= match_count + 1;
              end
            end else begin
              // Continue searching from next position
              // For simplicity, we only count complete segmentations in this implementation
              // A full implementation would use recursion or stack
            end
          end
          word_idx <= word_idx + 1;
        end else if (string_pos < 32 && word_idx == 8) begin
          string_pos <= string_pos + 1;
          word_idx <= 3'b0;
        end
      end

      RESULT: begin
        done <= 1;
        if (segmentation_count == 0) begin
          result_status <= 2'b01; // impossible
          result_sentence <= "impossible";
        end else if (segmentation_count == 1) begin
          result_status <= 2'b00; // valid
          // For this implementation, we output a placeholder
          // A full implementation would reconstruct the stored sentence
          result_sentence <= "valid";
        end else begin
          result_status <= 2'b10; // ambiguous
          result_sentence <= "ambiguous";
        end
      end
    endcase
  end
end

// Next state logic
always @(*) begin
  next_state = state;
  case (state)
    IDLE: if (start) next_state = PRECOMPUTE;
    PRECOMPUTE: if (word_idx == 8) next_state = SEARCH;
    SEARCH: if (string_pos >= 32) next_state = RESULT;
    RESULT: next_state = IDLE;
  endcase
end

endmodule

module election #(
    parameter MAX_S = 8,
    parameter DATA_WIDTH = 32,
    parameter DELEGATE_WIDTH = 12
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] S,
    input wire [DELEGATE_WIDTH-1:0] D [MAX_S-1:0],
    input wire [DATA_WIDTH-1:0] C [MAX_S-1:0],
    input wire [DATA_WIDTH-1:0] F [MAX_S-1:0],
    input wire [DATA_WIDTH-1:0] U [MAX_S-1:0],
    output reg [DATA_WIDTH-1:0] result,
    output reg done
);
localparam INF = 32'h7FFFFFFF;
wire [DATA_WIDTH-1:0] cost_wire [MAX_S-1:0];
generate
for (genvar i=0;i<MAX_S;i=i+1) begin : gen_cost
assign cost_wire[i] = calc_cost(C[i],F[i],U[i]);
end
endgenerate
function automatic [DATA_WIDTH-1:0] calc_cost;
input [DATA_WIDTH-1:0] C_val,F_val,U_val;
reg [DATA_WIDTH:0] diff;
begin
if (C_val > F_val + U_val) calc_cost = 0;
else if (C_val + U_val <= F_val) calc_cost = INF;
else begin diff = F_val + U_val - C_val; calc_cost = (diff>>1)+1; end
end
endfunction
wire [DELEGATE_WIDTH-1:0] total_delegates_comb;
wire [DELEGATE_WIDTH-1:0] required_comb;
wire [7:0] max_mask_comb;
assign total_delegates_comb = ( (S>0?D[0]:0)+(S>1?D[1]:0)+(S>2?D[2]:0)+(S>3?D[3]:0)+(S>4?D[4]:0)+(S>5?D[5]:0)+(S>6?D[6]:0)+(S>7?D[7]:0) );
assign required_comb = (total_delegates_comb>>1)+1;
assign max_mask_comb = (8'b00000001<<S)-1;
reg [7:0] mask;
reg [2:0] i;
reg [DELEGATE_WIDTH-1:0] sum_delegates;
reg [DATA_WIDTH-1:0] sum_cost;
reg [DATA_WIDTH-1:0] min_cost;
reg [DELEGATE_WIDTH-1:0] total_delegates_latched;
reg [DELEGATE_WIDTH-1:0] required_latched;
reg [7:0] max_mask_latched;
reg [3:0] S_latched;
reg [DELEGATE_WIDTH-1:0] D_latched [MAX_S-1:0];
reg [DATA_WIDTH-1:0] cost_latched [MAX_S-1:0];
localparam S_IDLE=0,S_INIT=1,S_START_MASK=2,S_ADD_STATE=3,S_CHECK=4,S_DONE=5;
reg [2:0] state;
always @(posedge clk or negedge rst_n) begin
if (!rst_n) begin
state<=S_IDLE; done<=0; result<=0; mask<=0; i<=0; sum_delegates<=0; sum_cost<=0; min_cost<=INF;
total_delegates_latched<=0; required_latched<=0; max_mask_latched<=0; S_latched<=0;
end else begin
case (state)
S_IDLE: begin
done<=0;
if (start) begin
S_latched<=S;
total_delegates_latched<=total_delegates_comb;
required_latched<=required_comb;
max_mask_latched<=max_mask_comb;
if (S>0) begin D_latched[0]<=D[0]; cost_latched[0]<=cost_wire[0]; end else begin D_latched[0]<=0; cost_latched[0]<=INF; end
if (S>1) begin D_latched[1]<=D[1]; cost_latched[1]<=cost_wire[1]; end else begin D_latched[1]<=0; cost_latched[1]<=INF; end
if (S>2) begin D_latched[2]<=D[2]; cost_latched[2]<=cost_wire[2]; end else begin D_latched[2]<=0; cost_latched[2]<=INF; end
if (S>3) begin D_latched[3]<=D[3]; cost_latched[3]<=cost_wire[3]; end else begin D_latched[3]<=0; cost_latched[3]<=INF; end
if (S>4) begin D_latched[4]<=D[4]; cost_latched[4]<=cost_wire[4]; end else begin D_latched[4]<=0; cost_latched[4]<=INF; end
if (S>5) begin D_latched[5]<=D[5]; cost_latched[5]<=cost_wire[5]; end else begin D_latched[5]<=0; cost_latched[5]<=INF; end
if (S>6) begin D_latched[6]<=D[6]; cost_latched[6]<=cost_wire[6]; end else begin D_latched[6]<=0; cost_latched[6]<=INF; end
if (S>7) begin D_latched[7]<=D[7]; cost_latched[7]<=cost_wire[7]; end else begin D_latched[7]<=0; cost_latched[7]<=INF; end
mask<=0; min_cost<=INF; state<=S_START_MASK; end
end
S_START_MASK: begin i<=0; sum_delegates<=0; sum_cost<=0; state<=S_ADD_STATE; end
S_ADD_STATE: begin
if (i < S_latched) begin
if (mask[i]) begin sum_delegates <= sum_delegates + D_latched[i]; sum_cost <= sum_cost + cost_latched[i]; end
i <= i + 1; state <= S_ADD_STATE; end
else state <= S_CHECK; end
S_CHECK: begin
if (sum_delegates >= required_latched) begin if (sum_cost < min_cost) min_cost <= sum_cost; end
if (mask < max_mask_latched) begin mask <= mask + 1; state <= S_START_MASK; end
else state <= S_DONE; end
S_DONE: begin result <= min_cost; done <= 1; state <= S_IDLE; end
default: state <= S_IDLE;
endcase
end
end
endmodule

module aladin_device (
    input clk,
    input rst_n,
    input start,
    input [1:0] cmd_type,   // 1: update, 2: query
    input [15:0] L, R,      // 16-bit, but we only use 1..16
    input [19:0] A, B,      // 20-bit
    output reg [31:0] result,
    output reg done
);

parameter BOXES = 16;

// Box storage: 1-indexed, boxes 1 to 16
reg [31:0] box [1:BOXES];

// State machine
reg [1:0] state;
localparam IDLE = 2'd0, UPDATE = 2'd1, QUERY = 2'd2;

reg [15:0] current_index, step;
reg [31:0] sum;
integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all boxes to 0
        for (i = 1; i <= BOXES; i = i + 1) begin
            box[i] <= 0;
        end
        state <= IDLE;
        result <= 0;
        done <= 0;
        current_index <= 0;
        step <= 0;
        sum <= 0;
    end else begin
        done <= 0; // default

        case (state)
            IDLE: begin
                if (start) begin
                    if (cmd_type == 1) begin
                        // Update command
                        current_index <= L;
                        step <= 1;
                        state <= UPDATE;
                    end else if (cmd_type == 2) begin
                        // Query command
                        current_index <= L;
                        sum <= 0;
                        state <= QUERY;
                    end
                end
            end

            UPDATE: begin
                if (current_index <= R && current_index <= BOXES) begin
                    // Compute value for current box
                    box[current_index] <= (step * A) % B;
                    current_index <= current_index + 1;
                    step <= step + 1;
                end else begin
                    // Finished update
                    state <= IDLE;
                    done <= 1;
                end
            end

            QUERY: begin
                if (current_index <= R && current_index <= BOXES) begin
                    sum <= sum + box[current_index];
                    current_index <= current_index + 1;
                end else begin
                    state <= IDLE;
                    result <= sum;
                    done <= 1;
                end
            end
        endcase
    end
end

endmodule

module bird_berry_assigner #(
    parameter MAX_NODES = 8,
    parameter MAX_LABEL_BITS = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,

    // Tree structure: node 0 is root
    input wire [2:0] parent [0:MAX_NODES-1],      // Parent index (0-7)
    input wire [2:0] node_type [0:MAX_NODES-1],   // 0:big branch, 1:small branch, 2:giant bird, 3:tiny bird, 4:berry
    input wire [MAX_LABEL_BITS-1:0] label [0:MAX_NODES-1], // ASCII char label

    output reg valid,              // 1 if labeling is valid after tiny->giant conversion
    output reg [2:0] conflict_count, // number of same-label birds with same controlled area
    output reg [2:0] first_conflict_node, // node ID of first conflict
    output reg done                // computation finished
);

// State definitions
localparam S_IDLE = 3'b000;
localparam S_COMPUTE_AREAS = 3'b001;
localparam S_CHECK_CONFLICTS = 3'b010;
localparam S_CHECK_BERRIES = 3'b011;
localparam S_DONE = 3'b100;

reg [2:0] state;
reg [2:0] node_idx;
reg [2:0] area [0:MAX_NODES-1];  // Controlled area root for each bird
reg [MAX_LABEL_BITS-1:0] bird_labels [0:MAX_NODES-1]; // Labels of birds only
reg [2:0] bird_count;
reg [2:0] berry_count;

// Helper: Find closest big branch ancestor
function automatic [2:0] find_big_ancestor;
    input [2:0] start_node;
    reg [2:0] current;
    begin
        current = start_node;
        while (current != 0) begin
            if (node_type[current] == 0) begin // big branch
                find_big_ancestor = current;
                return;
            end
            current = parent[current];
        end
        find_big_ancestor = 0; // root is always big
    end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        valid <= 0;
        conflict_count <= 0;
        first_conflict_node <= 0;
        node_idx <= 0;
        bird_count <= 0;
        berry_count <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                if (start) begin
                    state <= S_COMPUTE_AREAS;
                    node_idx <= 0;
                    bird_count <= 0;
                    berry_count <= 0;
                    done <= 0;
                end
            end

            S_COMPUTE_AREAS: begin
                // Compute controlled areas for all birds
                if (node_idx < MAX_NODES) begin
                    if (node_type[node_idx] >= 2 && node_type[node_idx] <= 3) begin
                        // It's a bird (giant or tiny)
                        if (node_type[node_idx] == 2) begin // giant bird
                            area[node_idx] <= find_big_ancestor(node_idx);
                        end else begin // tiny bird -> convert to giant
                            area[node_idx] <= find_big_ancestor(parent[node_idx]);
                        end
                        bird_labels[bird_count] <= label[node_idx];
                        bird_count <= bird_count + 1;
                    end else if (node_type[node_idx] == 4) begin
                        berry_count <= berry_count + 1;
                    end
                    node_idx <= node_idx + 1;
                end else begin
                    node_idx <= 0;
                    state <= S_CHECK_CONFLICTS;
                end
            end

            S_CHECK_CONFLICTS: begin
                // Check for same-label birds with same controlled area
                if (node_idx < MAX_NODES - 1) begin
                    if (node_type[node_idx] >= 2 && node_type[node_idx] <= 3) begin
                        reg [2:0] i;
                        for (i = node_idx + 1; i < MAX_NODES; i = i + 1) begin
                            if (node_type[i] >= 2 && node_type[i] <= 3) begin
                                if (label[node_idx] == label[i] && area[node_idx] == area[i]) begin
                                    conflict_count <= conflict_count + 1;
                                    if (first_conflict_node == 0)
                                        first_conflict_node <= node_idx;
                                end
                            end
                        end
                    end
                    node_idx <= node_idx + 1;
                end else begin
                    if (conflict_count == 0 && berry_count > 0)
                        state <= S_CHECK_BERRIES;
                    else
                        state <= S_DONE;
                end
            end

            S_CHECK_BERRIES: begin
                // Verify each berry is in some bird's controlled area with same label
                // Simplified: check if there exists at least one bird per label that covers
                // Since constraints guarantee uniqueness, we just need to ensure valid
                valid <= (conflict_count == 0);
                state <= S_DONE;
            end

            S_DONE: begin
                done <= 1;
                if (conflict_count == 0 && berry_count > 0)
                    valid <= 1;
                else
                    valid <= 0;
                state <= S_IDLE;
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

module mirko_slavko #(
    parameter MOD = 1000000000,
    parameter MAX_N = 8,
    parameter CUTS = 7,
    parameter STATES = 1 << CUTS, // 128
    parameter MAX_PAIRS = 21
)(
    input clk,
    input rst_n,
    input start,
    input [3:0] N,        // 1..8
    output reg done,
    output reg [29:0] result
);

// Precomputed coprime pairs for 1..8
// Each entry: i, j, mask (bits for cuts 2..8)
reg [2:0] pair_i [0:20];
reg [2:0] pair_j [0:20];
reg [6:0] pair_mask [0:20];

initial begin
    // Pair 0: (1,2) mask=0000001
    pair_i[0] = 1; pair_j[0] = 2; pair_mask[0] = 7'b0000001;
    // Pair 1: (1,3) mask=0000011
    pair_i[1] = 1; pair_j[1] = 3; pair_mask[1] = 7'b0000011;
    // Pair 2: (1,4) mask=0000111
    pair_i[2] = 1; pair_j[2] = 4; pair_mask[2] = 7'b0000111;
    // Pair 3: (1,5) mask=0001111
    pair_i[3] = 1; pair_j[3] = 5; pair_mask[3] = 7'b0001111;
    // Pair 4: (1,6) mask=0011111
    pair_i[4] = 1; pair_j[4] = 6; pair_mask[4] = 7'b0011111;
    // Pair 5: (1,7) mask=0111111
    pair_i[5] = 1; pair_j[5] = 7; pair_mask[5] = 7'b0111111;
    // Pair 6: (1,8) mask=1111111
    pair_i[6] = 1; pair_j[6] = 8; pair_mask[6] = 7'b1111111;
    // Pair 7: (2,3) mask=0000010
    pair_i[7] = 2; pair_j[7] = 3; pair_mask[7] = 7'b0000010;
    // Pair 8: (2,5) mask=0001110
    pair_i[8] = 2; pair_j[8] = 5; pair_mask[8] = 7'b0001110;
    // Pair 9: (2,7) mask=0111110
    pair_i[9] = 2; pair_j[9] = 7; pair_mask[9] = 7'b0111110;
    // Pair 10: (3,4) mask=0000100
    pair_i[10] = 3; pair_j[10] = 4; pair_mask[10] = 7'b0000100;
    // Pair 11: (3,5) mask=0001100
    pair_i[11] = 3; pair_j[11] = 5; pair_mask[11] = 7'b0001100;
    // Pair 12: (3,7) mask=0111100
    pair_i[12] = 3; pair_j[12] = 7; pair_mask[12] = 7'b0111100;
    // Pair 13: (3,8) mask=1111100
    pair_i[13] = 3; pair_j[13] = 8; pair_mask[13] = 7'b1111100;
    // Pair 14: (4,5) mask=0001000
    pair_i[14] = 4; pair_j[14] = 5; pair_mask[14] = 7'b0001000;
    // Pair 15: (4,7) mask=0111000
    pair_i[15] = 4; pair_j[15] = 7; pair_mask[15] = 7'b0111000;
    // Pair 16: (5,6) mask=0010000
    pair_i[16] = 5; pair_j[16] = 6; pair_mask[16] = 7'b0010000;
    // Pair 17: (5,7) mask=0110000
    pair_i[17] = 5; pair_j[17] = 7; pair_mask[17] = 7'b0110000;
    // Pair 18: (5,8) mask=1110000
    pair_i[18] = 5; pair_j[18] = 8; pair_mask[18] = 7'b1110000;
    // Pair 19: (6,7) mask=0100000
    pair_i[19] = 6; pair_j[19] = 7; pair_mask[19] = 7'b0100000;
    // Pair 20: (7,8) mask=1000000
    pair_i[20] = 7; pair_j[20] = 8; pair_mask[20] = 7'b1000000;
end

// Full mask for given N
reg [6:0] full_mask;
always_comb begin
    case(N)
        1: full_mask = 7'b0000000;
        2: full_mask = 7'b0000001;
        3: full_mask = 7'b0000011;
        4: full_mask = 7'b0000111;
        5: full_mask = 7'b0001111;
        6: full_mask = 7'b0011111;
        7: full_mask = 7'b0111111;
        8: full_mask = 7'b1111111;
        default: full_mask = 7'b0000000;
    endcase
end

// State machine
localparam IDLE = 3'b000;
localparam LOAD_PAIR = 3'b001;
localparam COPY_DP = 3'b010;
localparam PROCESS_MASK = 3'b011;
localparam UPDATE = 3'b100;
localparam NEXT_PAIR = 3'b101;
localparam DONE = 3'b110;

reg [2:0] state, next_state;
reg [4:0] pair_index, next_pair_index; // 0..20
reg [6:0] mask_index, next_mask_index; // 0..127

// DP arrays
reg [29:0] dp [0:STATES-1];      // current dp
reg [29:0] next_dp [0:STATES-1]; // next dp (during pair processing)

// Addition helper
wire [29:0] add_a;
wire [29:0] add_b;
wire [29:0] add_sum;
wire [29:0] add_mod;

assign add_a = dp[mask_index];
assign add_b = next_dp[mask_index | pair_mask[pair_index]];
assign add_sum = add_a + add_b;
assign add_mod = (add_sum >= MOD) ? (add_sum - MOD) : add_sum;

// Combinational next state logic
always_comb begin
    next_state = state;
    next_pair_index = pair_index;
    next_mask_index = mask_index;
    done = 0;

    case(state)
        IDLE: begin
            if (start) begin
                next_state = LOAD_PAIR;
                next_pair_index = 0;
            end
        end

        LOAD_PAIR: begin
            if (pair_index >= MAX_PAIRS) begin
                next_state = DONE;
            end else if (pair_i[pair_index] > N || pair_j[pair_index] > N) begin
                next_pair_index = pair_index + 1;
                next_state = LOAD_PAIR;
            end else begin
                // valid pair, start copying dp to next_dp
                next_mask_index = 0;
                next_state = COPY_DP;
            end
        end

        COPY_DP: begin
            // copy dp[mask_index] to next_dp[mask_index]
            // next_dp[mask_index] will be assigned in sequential block
            if (mask_index == STATES-1) begin
                next_mask_index = 0;
                next_state = PROCESS_MASK;
            end else begin
                next_mask_index = mask_index + 1;
            end
        end

        PROCESS_MASK: begin
            // For current mask_index, if dp[mask_index] != 0, add to next_dp[new_mask]
            // We'll update next_dp in sequential block based on add_mod
            if (mask_index == STATES-1) begin
                next_state = UPDATE;
            end else begin
                next_mask_index = mask_index + 1;
            end
        end

        UPDATE: begin
            // dp will be updated from next_dp in sequential block
            next_pair_index = pair_index + 1;
            next_state = LOAD_PAIR;
        end

        NEXT_PAIR: begin
            // Not used, we go directly from UPDATE to LOAD_PAIR
        end

        DONE: begin
            done = 1;
        end
    endcase
end

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        pair_index <= 0;
        mask_index <= 0;
        // Reset dp
        for (int i = 0; i < STATES; i++) begin
            dp[i] <= 0;
            next_dp[i] <= 0;
        end
        result <= 0;
    end else begin
        state <= next_state;
        pair_index <= next_pair_index;
        mask_index <= next_mask_index;

        case(state)
            IDLE: begin
                if (start) begin
                    // Initialize dp: dp[0]=1, others 0
                    for (int i = 0; i < STATES; i++) begin
                        dp[i] <= 0;
                        next_dp[i] <= 0;
                    end
                    dp[0] <= 1;
                end
            end

            COPY_DP: begin
                next_dp[mask_index] <= dp[mask_index];
            end

            PROCESS_MASK: begin
                // Only update if dp[mask_index] != 0
                if (add_a != 0) begin
                    next_dp[mask_index | pair_mask[pair_index]] <= add_mod;
                end
            end

            UPDATE: begin
                // Copy next_dp to dp
                for (int i = 0; i < STATES; i++) begin
                    dp[i] <= next_dp[i];
                end
            end

            DONE: begin
                // Compute result = dp[full_mask]; if full_mask==0, subtract 1 (exclude empty set)
                if (full_mask == 0) begin
                    // dp[0] is 1 (empty set), so subtract 1
                    if (dp[0] >= 1)
                        result <= dp[0] - 1;
                    else
                        result <= dp[0] + MOD - 1; // should not happen
                end else begin
                    result <= dp[full_mask];
                end
            end
        endcase
    end
end

endmodule

module max_flow_solver #(
    parameter MAX_NODES = 8,
    parameter DATA_WIDTH = 32,
    parameter NODE_WIDTH = 3,
    parameter RESULT_WIDTH = 32,
    parameter MAX_AUGMENTATIONS = 16,
    parameter MAX_CYCLES = 10000
)(
    input clk,
    input rst_n,
    input start,

    // Configuration interface
    input [NODE_WIDTH-1:0] src_node,
    input [NODE_WIDTH-1:0] dst_node,
    input [NODE_WIDTH-1:0] edge_u,
    input [NODE_WIDTH-1:0] edge_v,
    input [DATA_WIDTH-1:0] edge_cap,
    input load_edge,

    // Results
    output reg done,
    output reg [RESULT_WIDTH-1:0] max_flow,

    // Edge flow output interface (activated after done)
    output reg [NODE_WIDTH-1:0] flow_src,
    output reg [NODE_WIDTH-1:0] flow_dst,
    output reg [DATA_WIDTH-1:0] flow_amount,
    output reg flow_valid,
    output reg flow_done
);

// Internal memory for capacity and flow matrices
reg [DATA_WIDTH-1:0] capacity [0:MAX_NODES-1][0:MAX_NODES-1];
reg [DATA_WIDTH-1:0] flow [0:MAX_NODES-1][0:MAX_NODES-1];

// BFS state registers
reg [NODE_WIDTH-1:0] queue [0:MAX_NODES-1];
reg [NODE_WIDTH-1:0] parent [0:MAX_NODES-1];
reg [MAX_NODES-1:0] visited;
reg [NODE_WIDTH-1:0] bfs_head, bfs_tail;
reg [NODE_WIDTH-1:0] path_nodes [0:MAX_NODES-1];  // For path reconstruction

// FSM state definitions
localparam IDLE = 4'd0;
localparam LOAD = 4'd1;
localparam BFS_INIT = 4'd2;
localparam BFS_LOOP = 4'd3;
localparam AUGMENT = 4'd4;
localparam CHECK = 4'd5;
localparam OUTPUT_INIT = 4'd6;
localparam OUTPUT_LOOP = 4'd7;
localparam COMPLETE = 4'd8;

reg [3:0] state;
reg [3:0] next_state;

// Computation counters
reg [NODE_WIDTH-1:0] current_node;
reg [NODE_WIDTH-1:0] neighbor;
reg [RESULT_WIDTH-1:0] augment_count;
reg [DATA_WIDTH-1:0] bottleneck;
reg [DATA_WIDTH-1:0] residual;

// Output state machine
reg [NODE_WIDTH-1:0] out_i, out_j;
reg [NODE_WIDTH-1:0] next_i, next_j;

// Internal control signals
reg bfs_done;
reg path_found;
reg [NODE_WIDTH-1:0] path_length;
reg [NODE_WIDTH-1:0] path_idx;

// Flow output control
reg output_active;
reg [NODE_WIDTH-1:0] scan_i, scan_j;

// ============================================================================
// STATE MACHINE LOGIC
// ============================================================================

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        // Reset matrices
        for (int i = 0; i < MAX_NODES; i = i + 1) begin
            for (int j = 0; j < MAX_NODES; j = j + 1) begin
                capacity[i][j] <= 0;
                flow[i][j] <= 0;
            end
        end
        // Reset output signals
        done <= 0;
        max_flow <= 0;
        flow_valid <= 0;
        flow_done <= 0;
        flow_src <= 0;
        flow_dst <= 0;
        flow_amount <= 0;
        augment_count <= 0;
        output_active <= 0;
    end else begin
        state <= next_state;

        case (state)
            LOAD: begin
                if (load_edge) begin
                    capacity[edge_u][edge_v] <= edge_cap;
                end
            end

            BFS_INIT: begin
                // Initialize BFS
                visited <= 0;
                visited[src_node] <= 1'b1;
                parent <= 0;
                parent[src_node] <= src_node;
                queue[0] <= src_node;
                bfs_head <= 0;
                bfs_tail <= 1;
                path_found <= 0;
            end

            BFS_LOOP: begin
                if (bfs_head < bfs_tail && !path_found) begin
                    current_node <= queue[bfs_head];
                    bfs_head <= bfs_head + 1;
                end
            end

            AUGMENT: begin
                if (path_found) begin
                    // Update flows along path
                    for (int i = 0; i < path_length - 1; i = i + 1) begin
                        flow[path_nodes[i]][path_nodes[i+1]] <= 
                            flow[path_nodes[i]][path_nodes[i+1]] + bottleneck;
                    end
                    max_flow <= max_flow + bottleneck;
                    augment_count <= augment_count + 1;
                end
            end

            OUTPUT_INIT: begin
                output_active <= 1'b1;
                scan_i <= 0;
                scan_j <= 0;
                flow_valid <= 0;
                flow_done <= 0;
            end

            OUTPUT_LOOP: begin
                if (scan_i < MAX_NODES) begin
                    if (scan_j < MAX_NODES) begin
                        // Output flow if non-zero
                        if (flow[scan_i][scan_j] > 0) begin
                            flow_src <= scan_i;
                            flow_dst <= scan_j;
                            flow_amount <= flow[scan_i][scan_j];
                            flow_valid <= 1'b1;
                        end else begin
                            flow_valid <= 1'b0;
                        end
                        // Increment to next column
                        if (scan_j == MAX_NODES - 1) begin
                            scan_j <= 0;
                            scan_i <= scan_i + 1;
                        end else begin
                            scan_j <= scan_j + 1;
                        end
                    end
                end else begin
                    // Done scanning all edges
                    flow_done <= 1'b1;
                    output_active <= 1'b0;
                end
            end

            COMPLETE: begin
                done <= 1'b1;
                flow_valid <= 1'b0;
            end
        endcase
    end
end

// ============================================================================
// NEXT STATE LOGIC
// ============================================================================

always @(*) begin
    next_state = state;

    case (state)
        IDLE: begin
            if (load_edge) begin
                next_state = LOAD;
            end else if (start) begin
                next_state = BFS_INIT;
            end
        end

        LOAD: begin
            if (!load_edge) begin
                next_state = IDLE;
            end
        end

        BFS_INIT: begin
            next_state = BFS_LOOP;
        end

        BFS_LOOP: begin
            if (bfs_head >= bfs_tail) begin
                // Queue empty, no path found
                next_state = OUTPUT_INIT;
            end else if (current_node == dst_node) begin
                // Path found
                path_found = 1'b1;
                next_state = AUGMENT;
            end else begin
                // Process neighbors
                // (Neighborhood expansion logic would go here)
                // For simplicity, we assume neighbor processing happens in same cycle
                // In real implementation, this would need more states
                next_state = BFS_LOOP;
            end
        end

        AUGMENT: begin
            next_state = CHECK;
        end

        CHECK: begin
            if (augment_count >= MAX_AUGMENTATIONS) begin
                next_state = OUTPUT_INIT;
            end else begin
                // Check if more augmenting paths exist
                // For now, assume we continue
                next_state = BFS_INIT;
            end
        end

        OUTPUT_INIT: begin
            next_state = OUTPUT_LOOP;
        end

        OUTPUT_LOOP: begin
            if (scan_i >= MAX_NODES && scan_j == 0) begin
                next_state = COMPLETE;
            end else begin
                next_state = OUTPUT_LOOP;
            end
        end

        COMPLETE: begin
            // Stay in COMPLETE until reset
            next_state = COMPLETE;
        end
    endcase
end

// ============================================================================
// BFS NEIGHBOR PROCESSING (Combinational)
// ============================================================================

integer k;
always @(*) begin
    // Check all neighbors of current_node
    for (k = 0; k < MAX_NODES; k = k + 1) begin
        if (!visited[k] && capacity[current_node][k] > flow[current_node][k]) begin
            // Found reachable neighbor in residual graph
            visited[k] = 1'b1;
            parent[k] = current_node;
            queue[bfs_tail] = k;
            bfs_tail = bfs_tail + 1;
        end
    end
end

// ============================================================================
// PATH RECONSTRUCTION AND BOTTLENECK CALCULATION (Combinational)
// ============================================================================

integer p;
always @(*) begin
    if (path_found) begin
        // Reconstruct path from dst to src
        path_nodes[0] = dst_node;
        path_length = 1;
        path_idx = dst_node;

        while (path_idx != src_node && path_length < MAX_NODES) begin
            path_idx = parent[path_idx];
            path_nodes[path_length] = path_idx;
            path_length = path_length + 1;
        end

        // Reverse path to be src->dst
        for (p = 0; p < path_length/2; p = p + 1) begin
            path_nodes[p] = path_nodes[path_length-1-p];
            path_nodes[path_length-1-p] = path_nodes[p];
        end

        // Calculate bottleneck
        bottleneck = capacity[path_nodes[0]][path_nodes[1]] - flow[path_nodes[0]][path_nodes[1]];
        for (p = 1; p < path_length - 1; p = p + 1) begin
            residual = capacity[path_nodes[p]][path_nodes[p+1]] - flow[path_nodes[p]][path_nodes[p+1]];
            if (residual < bottleneck) bottleneck = residual;
        end
    end else begin
        bottleneck = 0;
        path_length = 0;
    end
end

endmodule

module distance_calculator (
    input [3:0] a0, a1, a2, a3,   // Digits of number A (most significant first)
    input [3:0] b0, b1, b2, b3,   // Digits of number B (most significant first)
    output [7:0] dist              // Sum of absolute digit differences
);

    // Compute absolute differences for each digit position
    wire [3:0] diff0 = (a0 >= b0) ? (a0 - b0) : (b0 - a0);
    wire [3:0] diff1 = (a1 >= b1) ? (a1 - b1) : (b1 - a1);
    wire [3:0] diff2 = (a2 >= b2) ? (a2 - b2) : (b2 - a2);
    wire [3:0] diff3 = (a3 >= b3) ? (a3 - b3) : (b3 - a3);

    // Sum of all differences (max 36, fits in 8 bits)
    assign dist = diff0 + diff1 + diff2 + diff3;

endmodule

// Interface specification:
// - Inputs: 8 signals of 4 bits each, representing the two numbers as 4-digit decimals (0-9 per digit).
//   a0/a1/a2/a3 are the digits of A (e.g., 0123 -> a0=0, a1=1, a2=2, a3=3).
// - Output: 8-bit distance value.
// - Function: Combinational; computes |a0-b0| + |a1-b1| + |a2-b2| + |a3-b3|.
// - Leading zeros are inherent in the 4-digit representation.
// - The module assumes inputs are decimal digits (0-9) encoded in 4-bit binary.

module art_reproduction (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] grid [0:7][0:7],  // 2-bit per cell: 00=W, 01=R, 02=G, 03=B
    output reg done,
    output reg result  // 1=YES, 0=NO
);

// Parameters
parameter MAX_ITER = 64;
parameter GRID_SIZE = 8;
parameter COLOR_W = 2'b00;
parameter COLOR_R = 2'b01;
parameter COLOR_G = 2'b10;
parameter COLOR_B = 2'b11;

// Internal state
reg [1:0] board [0:7][0:7];  // Current board state
reg [5:0] iter_count;         // Iteration counter (0-63)
reg [2:0] scan_x, scan_y;     // 3x3 block top-left position
reg scanning;                 // Scanning state flag
reg found_block;              // Found monochromatic block
reg [1:0] block_color;        // Color of found block
reg all_white;                // Check if board is all white

// State machine states
localparam S_IDLE = 3'b000;
localparam S_SCAN = 3'b001;
localparam S_REMOVE = 3'b010;
localparam S_CHECK = 3'b011;
localparam S_DONE = 3'b100;
reg [2:0] state;

integer i, j;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset state
        done <= 1'b0;
        result <= 1'b0;
        state <= S_IDLE;
        iter_count <= 6'b0;
        scan_x <= 3'b0;
        scan_y <= 3'b0;
        scanning <= 1'b0;
        found_block <= 1'b0;
        all_white <= 1'b1;
        // Clear board
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 8; j = j + 1) begin
                board[i][j] <= COLOR_W;
            end
        end
    end else begin
        case (state)
            S_IDLE: begin
                done <= 1'b0;
                if (start) begin
                    // Copy input grid to internal buffer
                    for (i = 0; i < 8; i = i + 1) begin
                        for (j = 0; j < 8; j = j + 1) begin
                            board[i][j] <= grid[i][j];
                        end
                    end
                    iter_count <= 6'b0;
                    state <= S_SCAN;
                    scan_x <= 3'b0;
                    scan_y <= 3'b0;
                    found_block <= 1'b0;
                end
            end

            S_SCAN: begin
                // Scan for monochromatic 3x3 block
                if (scan_x <= 5 && scan_y <= 5) begin
                    // Check current 3x3 block
                    block_color <= board[scan_x][scan_y];
                    if (board[scan_x][scan_y] != COLOR_W &&
                        board[scan_x][scan_y] == board[scan_x][scan_y+1] &&
                        board[scan_x][scan_y] == board[scan_x][scan_y+2] &&
                        board[scan_x][scan_y] == board[scan_x+1][scan_y] &&
                        board[scan_x][scan_y] == board[scan_x+1][scan_y+1] &&
                        board[scan_x][scan_y] == board[scan_x+1][scan_y+2] &&
                        board[scan_x][scan_y] == board[scan_x+2][scan_y] &&
                        board[scan_x][scan_y] == board[scan_x+2][scan_y+1] &&
                        board[scan_x][scan_y] == board[scan_x+2][scan_y+2]) begin
                        found_block <= 1'b1;
                        state <= S_REMOVE;
                    end else begin
                        // Move to next position
                        if (scan_x == 5) begin
                            scan_x <= 3'b0;
                            if (scan_y == 5) begin
                                // Finished scanning all positions
                                scan_y <= 3'b0;
                                state <= S_CHECK;
                            end else begin
                                scan_y <= scan_y + 1;
                            end
                        end else begin
                            scan_x <= scan_x + 1;
                        end
                    end
                end else begin
                    // Should not reach here
                    state <= S_CHECK;
                end
            end

            S_REMOVE: begin
                // Remove the monochromatic block by setting to white
                board[scan_x][scan_y] <= COLOR_W;
                board[scan_x][scan_y+1] <= COLOR_W;
                board[scan_x][scan_y+2] <= COLOR_W;
                board[scan_x+1][scan_y] <= COLOR_W;
                board[scan_x+1][scan_y+1] <= COLOR_W;
                board[scan_x+1][scan_y+2] <= COLOR_W;
                board[scan_x+2][scan_y] <= COLOR_W;
                board[scan_x+2][scan_y+1] <= COLOR_W;
                board[scan_x+2][scan_y+2] <= COLOR_W;

                found_block <= 1'b0;
                iter_count <= iter_count + 1;

                // Move to next scan position
                if (scan_x == 5) begin
                    scan_x <= 3'b0;
                    if (scan_y == 5) begin
                        scan_y <= 3'b0;
                        state <= S_CHECK;
                    end else begin
                        scan_y <= scan_y + 1;
                        state <= S_SCAN;
                    end
                end else begin
                    scan_x <= scan_x + 1;
                    state <= S_SCAN;
                end
            end

            S_CHECK: begin
                // Check if all cells are white
                all_white <= 1'b1;
                for (i = 0; i < 8; i = i + 1) begin
                    for (j = 0; j < 8; j = j + 1) begin
                        if (board[i][j] != COLOR_W) begin
                            all_white <= 1'b0;
                        end
                    end
                end

                // Check if we should continue or finish
                if (all_white) begin
                    result <= 1'b1;
                    state <= S_DONE;
                end else if (iter_count >= MAX_ITER) begin
                    result <= 1'b0;
                    state <= S_DONE;
                end else begin
                    // Continue scanning from beginning
                    scan_x <= 3'b0;
                    scan_y <= 3'b0;
                    state <= S_SCAN;
                end
            end

            S_DONE: begin
                done <= 1'b1;
                if (!start) begin
                    state <= S_IDLE;
                end
            end

            default: begin
                state <= S_IDLE;
            end
        endcase
    end
end

endmodule

