            INCREMENT: path_index <= path_index + 1;
            OUTPUT: begin
                if (min_angle == 32'h7FFFFFFF) result <= 32'hFFFFFFFF;
                else result <= min_angle;
                done <= 1;
            end
            IDLE: done <= 0;
        endcase
    end
