wire [1:0] sum11 = V0_1 + V1_1 + H1_0 + H1_1;
wire [1:0] sum21 = V0_2 + V1_2 + H1_1;
wire [1:0] sum02 = V1_0 + H2_0;
wire [1:0] sum12 = V1_1 + H2_0 + H2_1;
wire [1:0] sum22 = V1_2 + H2_1;

wire touch_valid;
assign touch_valid = 
    (sum00 <= 1) &&
    (sum10 <= 1) &&
    (sum20 <= 1) &&
    (sum01 <= 1) &&
    (sum11 <= 1) &&
    (sum21 <= 1) &&
    (sum02 <= 1) &&
    (sum12 <= 1) &&
    (sum22 <= 1);

// Overall valid candidate
wire valid_candidate;
assign valid_candidate = row0_check && row1_check && col0_check && col1_check && touch_valid;

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        candidate <= 12'b0;
        done <= 0;
        row0_vbars <= 3'b0;
        row1_vbars <= 3'b0;
        col0_hbars <= 3'b0;
        col1_hbars <= 3'b0;
    end else begin
        case (state)
            IDLE: if (start) begin
                state <= SEARCH;
                candidate <= 12'b0;
                done <= 0;
            end

            SEARCH: begin
                if (valid_candidate) begin
                    // Latch the solution
                    row0_vbars <= candidate[2:0];
                    row1_vbars <= candidate[5:3];
                    col0_hbars <= {candidate[8], candidate[7], candidate[6]}; // H0_vec
                    col1_hbars <= {candidate[11], candidate[10], candidate[9]}; // H1_vec
                    done <= 1;
                    state <= DONE;
                end else begin
                    if (candidate == 12'hFFF) begin
                        // Exhausted all candidates, no solution found (should not happen)
                        done <= 1;
                        state <= DONE;
                    end else begin
                        candidate <= candidate + 1;
                    end
                end
            end

            DONE: begin
                // Stay here until reset
            end
        endcase
    end
end

endmodule

module dessert_finder (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] P,

    output reg [15:0] count,
    output reg [15:0] beverage,
    output reg [15:0] main_dish,
    output reg pair_valid,
    output reg done
);

// State encoding
localparam IDLE = 2'b00;
localparam INIT = 2'b01;
localparam CHECK = 2'b10;
localparam DONE = 2'b11;

// Registers
reg [1:0] state, next_state;
reg [15:0] b, next_b;
reg [15:0] count_reg, next_count;
reg [15:0] beverage_reg, next_beverage;
reg [15:0] main_dish_reg, next_main_dish;
reg pair_valid_reg, next_pair_valid;
reg done_reg, next_done;

// Combinational logic
wire [15:0] m;
wire [9:0] mask_b, mask_m, mask_P;
wire disjoint;

assign m = P - b;

// Digit mask computation function
function [9:0] compute_mask;
    input [15:0] num;
    reg [3:0] digit;
    begin
        compute_mask = 10'b0;
        digit = num % 10;
        compute_mask[digit] = 1'b1;
        if (num >= 10) begin
            digit = (num / 10) % 10;
            compute_mask[digit] = 1'b1;
        end
        if (num >= 100) begin
            digit = (num / 100) % 10;
            compute_mask[digit] = 1'b1;
        end
        if (num >= 1000) begin
            digit = (num / 1000) % 10;
            compute_mask[digit] = 1'b1;
        end
        if (num >= 10000) begin
            digit = (num / 10000) % 10;
            compute_mask[digit] = 1'b1;
        end
    end
endfunction

assign mask_b = compute_mask(b);
assign mask_m = compute_mask(m);
assign mask_P = compute_mask(P);

assign disjoint = ((mask_b & mask_m) == 10'b0) && 
                  ((mask_b & mask_P) == 10'b0) && 
                  ((mask_m & mask_P) == 10'b0);

// State machine
always @(*) begin
    next_state = state;
    next_b = b;
    next_count = count_reg;
    next_beverage = beverage_reg;
    next_main_dish = main_dish_reg;
    next_pair_valid = 1'b0;
    next_done = 1'b0;

    case (state)
        IDLE: begin
            if (start) begin
                next_state = INIT;
            end
        end

        INIT: begin
            next_b = 16'd1;
            next_count = 16'd0;
            next_state = CHECK;
        end

        CHECK: begin
            if (b < (P - b)) begin
                if (disjoint) begin
                    next_beverage = b;
                    next_main_dish = m;
                    next_count = count_reg + 1;
                    next_pair_valid = 1'b1;
                end
                if (b < P - 16'd1) begin
                    next_b = b + 1;
                    next_state = CHECK;
                end else begin
                    next_state = DONE;
                end
            end else begin
                next_state = DONE;
            end
        end

        DONE: begin
            next_done = 1'b1;
            if (~start) begin
                next_state = IDLE;
            end
        end

        default: next_state = IDLE;
    endcase
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        b <= 16'd0;
        count_reg <= 16'd0;
        beverage_reg <= 16'd0;
        main_dish_reg <= 16'd0;
        pair_valid_reg <= 1'b0;
        done_reg <= 1'b0;
    end else begin
        state <= next_state;
        b <= next_b;
        count_reg <= next_count;
        beverage_reg <= next_beverage;
        main_dish_reg <= next_main_dish;
        pair_valid_reg <= next_pair_valid;
        done_reg <= next_done;
    end
end

// Output assignments
always @(*) begin
    count = count_reg;
    beverage = beverage_reg;
    main_dish = main_dish_reg;
    pair_valid = pair_valid_reg;
    done = done_reg;
end

endmodule

module coprime_counter (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] a, b, c, d,
    output wire [15:0] result,
    output wire done
);

// Internal registers
reg [3:0] x_reg, y_reg;
reg [15:0] count_reg;
reg done_reg;
reg [2:0] state;

// State definitions
localparam IDLE = 3'b000;
localparam COMPUTE_GCD = 3'b001;
localparam CHECK_GCD = 3'b010;
localparam INCR_Y = 3'b011;
localparam INCR_X = 3'b100;
localparam DONE = 3'b101;

// GCD function (fixed-step Euclidean algorithm for numbers <= 16, up to 6 steps)
function automatic [3:0] gcd;
    input [3:0] a;
    input [3:0] b;
    reg [3:0] x, y, temp;
    begin
        x = a;
        y = b;
        // Step 1
        if (y != 0) begin
            temp = y;
            y = x % y;
            x = temp;
        end
        // Step 2
        if (y != 0) begin
            temp = y;
            y = x % y;
            x = temp;
        end
        // Step 3
        if (y != 0) begin
            temp = y;
            y = x % y;
            x = temp;
        end
        // Step 4
        if (y != 0) begin
            temp = y;
            y = x % y;
            x = temp;
        end
        // Step 5
        if (y != 0) begin
            temp = y;
            y = x % y;
            x = temp;
        end
        // Step 6
        if (y != 0) begin
            temp = y;
            y = x % y;
            x = temp;
        end
        gcd = x;
    end
endfunction

// Combinational gcd value for current x_reg and y_reg
wire [3:0] current_gcd;
assign current_gcd = gcd(x_reg, y_reg);

// State machine and sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        x_reg <= 4'b0;
        y_reg <= 4'b0;
        count_reg <= 16'b0;
        done_reg <= 1'b0;
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                done_reg <= 1'b0;
                if (start) begin
                    x_reg <= a;
                    y_reg <= c;
                    count_reg <= 16'b0;
                    state <= COMPUTE_GCD;
                end
            end

            COMPUTE_GCD: begin
                // GCD is computed combinationally, move to check
                state <= CHECK_GCD;
            end

            CHECK_GCD: begin
                if (current_gcd == 4'b1) begin
                    count_reg <= count_reg + 1;
                end
                state <= INCR_Y;
            end

            INCR_Y: begin
                if (y_reg < d) begin
                    y_reg <= y_reg + 4'b1;
                    state <= COMPUTE_GCD;
                end else begin
                    y_reg <= c;  // reset to c for next x
                    state <= INCR_X;
                end
            end

            INCR_X: begin
                if (x_reg < b) begin
                    x_reg <= x_reg + 4'b1;
                    state <= COMPUTE_GCD;
                end else begin
                    state <= DONE;
                end
            end

            DONE: begin
                done_reg <= 1'b1;
                // Wait for start to go low, then return to IDLE for next computation
                if (!start) begin
                    state <= IDLE;
                    done_reg <= 1'b0;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

assign result = count_reg;
assign done = done_reg;

endmodule

module cluster_min #(
    parameter MAX_N = 16,
    parameter DATA_WIDTH = 8,
    parameter STATE_WIDTH = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] a [0:MAX_N-1],
    input wire [DATA_WIDTH-1:0] b [0:MAX_N-1],
    input wire [MAX_N-1:0] c,
    input wire [3:0] n,
    output reg [DATA_WIDTH*2:0] result,
    output reg done
);

// State definitions
localparam S_IDLE = 0;
localparam S_INIT = 1;
localparam S_PREPARE_PAIRS = 2;
localparam S_COMPUTE_PAIR = 3;
localparam S_LOOP_NON_VOTERS = 4;
localparam S_UPDATE_MIN = 5;
localparam S_DONE = 6;

reg [STATE_WIDTH-1:0] state, next_state;

// Registers for data
reg [DATA_WIDTH-1:0] a_reg [0:MAX_N-1];
reg [DATA_WIDTH-1:0] b_reg [0:MAX_N-1];
reg [MAX_N-1:0] c_reg;
reg [3:0] n_reg;

// Registers for computation
reg [3:0] k;
reg [3:0] m;
reg [3:0] voter_idx [0:MAX_N-1];
reg [3:0] non_voter_idx [0:MAX_N-1];
reg [3:0] i, j;
reg [3:0] p;
reg signed [DATA_WIDTH*2-1:0] dx, dy;
reg [DATA_WIDTH*2-1:0] dot_uw;
reg signed [DATA_WIDTH*2-1:0] dot_pu;
reg [DATA_WIDTH*2-1:0] count;
reg [DATA_WIDTH*2-1:0] cluster_size;
reg [DATA_WIDTH*2-1:0] min_cluster;

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= S_IDLE;
    else state <= next_state;
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        S_IDLE: if (start) next_state = S_INIT;
        S_INIT: next_state = S_PREPARE_PAIRS;
        S_PREPARE_PAIRS: next_state = S_COMPUTE_PAIR;
        S_COMPUTE_PAIR: next_state = S_LOOP_NON_VOTERS;
        S_LOOP_NON_VOTERS: begin
            if (p < m-1) next_state = S_LOOP_NON_VOTERS;
            else next_state = S_UPDATE_MIN;
        end
        S_UPDATE_MIN: begin
            if (j < k-1) next_state = S_COMPUTE_PAIR;
            else if (i < k-1) next_state = S_COMPUTE_PAIR;
            else next_state = S_DONE;
        end
        S_DONE: next_state = S_IDLE;
        default: next_state = S_IDLE;
    endcase
end

// Datapath
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 0;
        result <= 0;
        k <= 0;
        m <= 0;
        i <= 0;
        j <= 0;
        p <= 0;
        min_cluster <= 0;
        count <= 0;
        cluster_size <= 0;
        integer idx;
        for (idx = 0; idx < MAX_N; idx = idx + 1) begin
            voter_idx[idx] <= 0;
            non_voter_idx[idx] <= 0;
            a_reg[idx] <= 0;
            b_reg[idx] <= 0;
        end
        c_reg <= 0;
        n_reg <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    a_reg <= a;
                    b_reg <= b;
                    c_reg <= c;
                    n_reg <= n;
                end
            end

            S_INIT: begin
                k <= 0;
                m <= 0;
                for (integer idx = 0; idx < n_reg; idx = idx + 1) begin
                    if (c_reg[idx]) begin
                        voter_idx[k] <= idx;
                        k <= k + 1;
                    end else begin
                        non_voter_idx[m] <= idx;
                        m <= m + 1;
                    end
                end
                min_cluster <= k;
            end

            S_PREPARE_PAIRS: begin
                i <= 0;
                j <= 0;
            end

            S_COMPUTE_PAIR: begin
                ax <= a_reg[voter_idx[i]];
                ay <= b_reg[voter_idx[i]];
                bx <= a_reg[voter_idx[j]];
                by <= b_reg[voter_idx[j]];
                dx <= bx - ax;
                dy <= by - ay;
                dot_uw <= (bx - ax)*(bx - ax) + (by - ay)*(by - ay);
                count <= 0;
                p <= 0;
            end

            S_LOOP_NON_VOTERS: begin
                if (p < m) begin
                    dot_pu <= (a_reg[non_voter_idx[p]] - ax)*dx + (b_reg[non_voter_idx[p]] - ay)*dy;
                    if (dot_pu > 0 && dot_pu < dot_uw) count <= count + 1;
                    p <= p + 1;
                end
            end

            S_UPDATE_MIN: begin
                cluster_size <= k + count;
                if (k + count < min_cluster) min_cluster <= k + count;
                if (j < k-1) j <= j + 1;
                else begin
                    j <= 0;
                    if (i < k-1) i <= i + 1;
                end
            end

            S_DONE: begin
                result <= min_cluster;
                done <= 1;
            end
        endcase
    end
end

endmodule

