module CheetahMinPack #(
    parameter WIDTH = 8,
    parameter STEPS = 257,
    parameter SCALE = 256
)(
    input clk,
    input rst_n,
    input start,
    input [WIDTH-1:0] t0, t1, t2,
    input [WIDTH-1:0] v0, v1, v2,
    output reg [15:0] result,
    output reg done
);

    // Combinational max_t
    wire [WIDTH-1:0] max_t_comb = (t0 > t1) ? ((t0 > t2) ? t0 : t2) : ((t1 > t2) ? t1 : t2);

    // Scaled times
    wire [31:0] t0_scaled = {t0, 8'b0};
    wire [31:0] t1_scaled = {t1, 8'b0};
    wire [31:0] t2_scaled = {t2, 8'b0};

    // Combinational signals for current T
    wire [31:0] D0 = T_reg - t0_scaled;
    wire [31:0] D1 = T_reg - t1_scaled;
    wire [31:0] D2 = T_reg - t2_scaled;

    wire [31:0] P0 = v0 * D0;
    wire [31:0] P1 = v1 * D1;
    wire [31:0] P2 = v2 * D2;

    // Max and min of P0, P1, P2
    wire [31:0] max_P = (P0 > P1) ? ((P0 > P2) ? P0 : P2) : ((P1 > P2) ? P1 : P2);
    wire [31:0] min_P = (P0 < P1) ? ((P0 < P2) ? P0 : P2) : ((P1 < P2) ? P1 : P2);

    wire [31:0] diff = max_P - min_P;

    // State machine
    localparam IDLE = 2'b00;
    localparam INIT = 2'b01;
    localparam LOOP = 2'b10;
    localparam DONE = 2'b11;

    reg [1:0] state;
    reg [31:0] T_reg;
    reg [31:0] min_pack_reg;
    reg [8:0] counter;  // 9 bits for up to 511 (STEPS=257 needs 9 bits)

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            T_reg <= 0;
            min_pack_reg <= 32'hFFFF_FFFF;
            counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= INIT;
                    end
                end

                INIT: begin
                    // Initialize T_reg to max_t * SCALE
                    T_reg <= {max_t_comb, 8'b0};
                    min_pack_reg <= 32'hFFFF_FFFF;
                    counter <= 0;
                    state <= LOOP;
                end

                LOOP: begin
                    // Update min_pack_reg if current diff is smaller
                    if (diff < min_pack_reg) begin
                        min_pack_reg <= diff;
                    end

                    // Increment T and counter
                    T_reg <= T_reg + 1;
                    counter <= counter + 1;

                    // Check if we have processed all STEPS points
                    // When counter reaches STEPS, we are done (counter counts from 0 to STEPS-1)
                    if (counter == STEPS - 1) begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1;
                    result <= min_pack_reg[15:0];
                    // Remain in DONE until reset
                end

                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module magic_checkerboard (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] board_0, board_1, board_2, board_3,
    input wire [7:0] board_4, board_5, board_6, board_7,
    input wire [7:0] board_8, board_9, board_10, board_11,
    input wire [7:0] board_12, board_13, board_14, board_15,
    output reg [15:0] result,
    output reg done
);
    localparam NUM_CELLS = 16;
    localparam MAX_SUM = 16'hFFFF;

    // States
    localparam IDLE = 3'b000;
    localparam SETUP_COMBO = 3'b001;
    localparam PROCESS_CELL = 3'b010;
    localparam CHECK_COMBO = 3'b011;
    localparam NEXT_COMBO = 3'b100;
    localparam DONE = 3'b101;

    // Registers
    reg [2:0] state;
    reg [7:0] board_in [0:15];
    reg [7:0] filled_board [0:15];
    reg [3:0] cell_idx;
    reg [1:0] combo_idx;
    reg [15:0] min_sum;
    reg [15:0] sum;
    reg combo_error;

    // Combinational helpers
    wire [3:0] i = cell_idx[3:2];   // row (0..3)
    wire [3:0] j = cell_idx[1:0];   // column (0..3)

    wire [7:0] left_val = (j > 0) ? filled_board[cell_idx - 1] : 8'd0;
    wire [7:0] top_val  = (i > 0) ? filled_board[cell_idx - 4] : 8'd0;

    wire [7:0] lower_bound = (j > 0 && i > 0) ? ((left_val + 1) > (top_val + 1) ? left_val + 1 : top_val + 1) :
                              (j > 0) ? (left_val + 1) :
                              (i > 0) ? (top_val + 1) : 8'd1;

    // Parity assignment bits for current combo
    wire even_parity = combo_idx[0];   // 0: color0 even, 1: color0 odd
    wire odd_parity  = combo_idx[1];   // same for odd component

    wire component = (i + j) % 2;      // 0: even i+j, 1: odd i+j
    wire row_parity = i % 2;           // 0 or 1

    wire required_parity = (component == 0) ?
                           (row_parity == 0 ? even_parity : ~even_parity) :
                           (row_parity == 0 ? odd_parity  : ~odd_parity);

    wire [7:0] new_val = (required_parity == lower_bound[0]) ? lower_bound : lower_bound + 1;
    wire val_ok = (new_val <= 8'hFF);

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            cell_idx <= 0;
            combo_idx <= 0;
            min_sum <= MAX_SUM;
            sum <= 0;
            combo_error <= 0;
            // Clear arrays
            for (integer idx = 0; idx < 16; idx = idx + 1) begin
                board_in[idx] <= 8'd0;
                filled_board[idx] <= 8'd0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load input board
                        board_in[0] <= board_0;  board_in[1] <= board_1;  board_in[2] <= board_2;  board_in[3] <= board_3;
                        board_in[4] <= board_4;  board_in[5] <= board_5;  board_in[6] <= board_6;  board_in[7] <= board_7;
                        board_in[8] <= board_8;  board_in[9] <= board_9;  board_in[10] <= board_10; board_in[11] <= board_11;
                        board_in[12] <= board_12; board_in[13] <= board_13; board_in[14] <= board_14; board_in[15] <= board_15;
                        combo_idx <= 2'b00;
                        min_sum <= MAX_SUM;
                        state <= SETUP_COMBO;
                    end
                end

                SETUP_COMBO: begin
                    combo_error <= 0;
                    sum <= 0;
                    cell_idx <= 0;
                    filled_board <= board_in;   // copy input
                    state <= PROCESS_CELL;
                end

                PROCESS_CELL: begin
                    if (!combo_error) begin
                        if (board_in[cell_idx] != 8'd0) begin
                            // Given cell: verify constraints
                            if (board_in[cell_idx] < lower_bound) combo_error <= 1;
                            else if (board_in[cell_idx][0] != required_parity) combo_error <= 1;
                            else sum <= sum + board_in[cell_idx];
                        end else begin
                            // Fill zero cell
                            if (!val_ok) combo_error <= 1;
                            else begin
                                filled_board[cell_idx] <= new_val;
                                sum <= sum + new_val;
                            end
                        end
                    end
                    if (cell_idx < 15) cell_idx <= cell_idx + 1;
                    else state <= CHECK_COMBO;
                end

                CHECK_COMBO: begin
                    if (!combo_error && sum < min_sum) min_sum <= sum;
                    state <= NEXT_COMBO;
                end

                NEXT_COMBO: begin
                    combo_idx <= combo_idx + 1;
                    if (combo_idx < 3) state <= SETUP_COMBO;
                    else state <= DONE;
                end

                DONE: begin
                    done <= 1;
                    result <= (min_sum == MAX_SUM) ? 16'hFFFF : min_sum;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

