module phone_network(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] valid_detectors,  // Number of valid detectors (1-8)

    // Position inputs (8 detectors, 8-bit each)
    input wire [7:0] pos_0, pos_1, pos_2, pos_3,
    input wire [7:0] pos_4, pos_5, pos_6, pos_7,

    // Count inputs (8 detectors, 32-bit each)
    input wire [31:0] count_0, count_1, count_2, count_3,
    input wire [31:0] count_4, count_5, count_6, count_7,

    output reg [31:0] result,
    output reg done
);

    // Internal state
    reg [7:0] sorted_pos [0:7];
    reg [31:0] sorted_count [0:7];
    reg [2:0] n_detectors;
    reg [2:0] sort_idx, sort_limit;
    reg [31:0] temp_result;
    reg [2:0] calc_idx;

    // State machine states
    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam SORT = 2'b01;
    localparam CALC = 2'b10;
    localparam DONE = 2'b11;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 1'b0;
            result <= 32'd0;
            n_detectors <= 3'd0;
            sort_idx <= 3'd0;
            sort_limit <= 3'd0;
            calc_idx <= 3'd0;
            temp_result <= 32'd0;
            // Clear arrays
            for (i = 0; i < 8; i = i + 1) begin
                sorted_pos[i] <= 8'd0;
                sorted_count[i] <= 32'd0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // Load input data into internal arrays
                        sorted_pos[0] <= pos_0; sorted_count[0] <= count_0;
                        sorted_pos[1] <= pos_1; sorted_count[1] <= count_1;
                        sorted_pos[2] <= pos_2; sorted_count[2] <= count_2;
                        sorted_pos[3] <= pos_3; sorted_count[3] <= count_3;
                        sorted_pos[4] <= pos_4; sorted_count[4] <= count_4;
                        sorted_pos[5] <= pos_5; sorted_count[5] <= count_5;
                        sorted_pos[6] <= pos_6; sorted_count[6] <= count_6;
                        sorted_pos[7] <= pos_7; sorted_count[7] <= count_7;
                        n_detectors <= valid_detectors;
                        sort_idx <= 3'd0;
                        sort_limit <= valid_detectors - 3'd1;
                        state <= SORT;
                    end
                end

                SORT: begin
                    // Bubble sort by position (simplified for small N)
                    if (sort_idx < sort_limit) begin
                        if (sorted_pos[sort_idx] > sorted_pos[sort_idx + 1]) begin
                            // Swap positions and counts
                            sorted_pos[sort_idx] <= sorted_pos[sort_idx + 1];
                            sorted_pos[sort_idx + 1] <= sorted_pos[sort_idx];
                            sorted_count[sort_idx] <= sorted_count[sort_idx + 1];
                            sorted_count[sort_idx + 1] <= sorted_count[sort_idx];
                        end
                        sort_idx <= sort_idx + 3'd1;
                    end else begin
                        // Check if another pass needed
                        if (sort_limit > 3'd0) begin
                            sort_limit <= sort_limit - 3'd1;
                            sort_idx <= 3'd0;
                        end else begin
                            // Sorting complete, initialize calculation
                            temp_result <= sorted_count[0];
                            calc_idx <= 3'd1;
                            state <= CALC;
                        end
                    end
                end

                CALC: begin
                    if (calc_idx < n_detectors) begin
                        if (sorted_count[calc_idx] > sorted_count[calc_idx - 1]) begin
                            temp_result <= temp_result + 
                                (sorted_count[calc_idx] - sorted_count[calc_idx - 1]);
                        end
                        calc_idx <= calc_idx + 3'd1;
                    end else begin
                        result <= temp_result;
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module kernel_area (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] n,
    input wire signed [31:0] x [0:7],
    input wire signed [31:0] y [0:7],
    output reg [63:0] area,
    output reg done
);
    // Combinational calculation of sum of cross products
    reg signed [63:0] sum_comb;
    integer i;
    always @(*) begin
        sum_comb = 0;
        for (i = 0; i < 8; i = i + 1) begin
            if (i < n) begin
                if (i < n-1) begin
                    sum_comb = sum_comb + (x[i] * y[i+1] - x[i+1] * y[i]);
                end else begin
                    sum_comb = sum_comb + (x[i] * y[0] - x[0] * y[i]);
                end
            end
        end
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            area <= 0;
            done <= 0;
        end else begin
            if (start) begin
                // Compute absolute value and divide by 2
                if (sum_comb < 0)
                    area <= (-sum_comb) >> 1;
                else
                    area <= sum_comb >> 1;
                done <= 1;
            end else begin
                done <= 0;
            end
        end
    end
endmodule

