module pebble_counter #(
    parameter N = 6,
    parameter MAX_K = 2
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [N-1:0] target,
    input wire [2:0] K,
    output reg [N-1:0] result,
    output reg done
);

// State definitions
localparam STATE_IDLE = 3'b000;
localparam STATE_SETUP = 3'b001;
localparam STATE_TRANSFORM = 3'b010;
localparam STATE_CHECK = 3'b011;
localparam STATE_ROTATE = 3'b100;
localparam STATE_NEXT = 3'b101;
localparam STATE_DONE = 3'b110;

// Registers
reg [2:0] state;
reg [N-1:0] candidate;      // Current candidate configuration
reg [N-1:0] transformed;    // Result after K transformations
reg [N-1:0] temp;           // Temporary for transformation
reg [2:0] k_count;          // Counter for K transformations
reg [N-1:0] rotation_ref;   // Reference for rotation comparison
reg [2:0] rot_idx;          // Rotation index
reg [5:0] config_counter;   // 0 to 63 for N=6
reg [N-1:0] min_rot;        // Minimum rotation of candidate
reg is_min;                 // Flag if candidate is minimal rotation
reg [N-1:0] temp_rot;       // Temp rotation

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        result <= 0;
        done <= 0;
        config_counter <= 0;
        candidate <= 0;
        k_count <= 0;
    end else begin
        case (state)
            STATE_IDLE: begin
                done <= 0;
                if (start) begin
                    result <= 0;
                    config_counter <= 0;
                    state <= STATE_SETUP;
                end
            end

            STATE_SETUP: begin
                // Load current candidate from counter
                candidate <= config_counter;
                transformed <= config_counter;
                k_count <= 0;
                state <= STATE_TRANSFORM;
            end

            STATE_TRANSFORM: begin
                if (k_count < K) begin
                    // One transformation step: new[i] = old[i] XOR old[(i+1)%N]
                    temp <= transformed;
                    k_count <= k_count + 1;
                    state <= STATE_TRANSFORM;
                    // Perform XOR transformation in next cycle
                end else begin
                    state <= STATE_CHECK;
                end
            end

            STATE_CHECK: begin
                // Check if transformed matches target
                if (transformed == target) begin
                    // Check if this candidate is minimal rotation
                    min_rot <= candidate;
                    rot_idx <= 1;
                    state <= STATE_ROTATE;
                end else begin
                    state <= STATE_NEXT;
                end
            end

            STATE_ROTATE: begin
                // Generate rotation
                if (rot_idx < N) begin
                    temp_rot <= {candidate[0], candidate[N-1:1]}; // Right rotate
                    if (temp_rot < min_rot) min_rot <= temp_rot;
                    rot_idx <= rot_idx + 1;
                    candidate <= temp_rot;
                end else begin
                    // Check if original candidate equals min_rot
                    if (candidate == min_rot) begin
                        result <= result + 1;
                    end
                    state <= STATE_NEXT;
                end
            end

            STATE_NEXT: begin
                if (config_counter < (1 << N) - 1) begin
                    config_counter <= config_counter + 1;
                    state <= STATE_SETUP;
                end else begin
                    state <= STATE_DONE;
                end
            end

            STATE_DONE: begin
                done <= 1;
                if (!start) state <= STATE_IDLE;
            end

            default: state <= STATE_IDLE;
        endcase
    end
end

// Combinational logic for transformation step
always @(*) begin
    if (state == STATE_TRANSFORM && k_count < K) begin
        // Perform XOR transformation
        transformed = temp;
        transformed[0] = temp[0] ^ temp[1];
        transformed[N-1] = temp[N-1] ^ temp[0];
        for (integer i = 1; i < N-1; i = i + 1) begin
            transformed[i] = temp[i] ^ temp[i+1];
        end
    end
end

endmodule

// Interface specification:
// - Clock (clk) and active-low reset (rst_n)
// - start: Assert high for 1 clock cycle to begin computation
// - target: N-bit input representing the final configuration (B=0, W=1)
// - K: Number of transformations (1 to MAX_K)
// - result: N-bit output count of distinct starting circles
// - done: Asserted high when computation complete
// Timing: After start, done will go high within ~64*K cycles
// Reset: Assert rst_n low for minimum 2 cycles to clear state

module max_satisfied_people #(
    parameter NUM_PEOPLE = 8,
    parameter DATA_WIDTH = 16,
    parameter MAX_SUM = 10000
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] a0, a1, a2, a3, a4, a5, a6, a7,
    input wire [DATA_WIDTH-1:0] b0, b1, b2, b3, b4, b5, b6, b7,
    input wire [DATA_WIDTH-1:0] c0, c1, c2, c3, c4, c5, c6, c7,
    output wire [3:0] result,
    output wire done
);
    localparam IDLE = 3'd0;
    localparam INIT = 3'd1;
    localparam LOOP = 3'd2;
    localparam SCAN = 3'd3;
    localparam CHECK = 3'd4;
    localparam POPCOUNT = 3'd5;
    localparam UPDATE = 3'd6;
    reg [2:0] state, next_state;
    reg [7:0] mask;
    reg [3:0] best_count;
    reg [DATA_WIDTH-1:0] max_a, max_b, max_c;
    reg [DATA_WIDTH:0] sum;
    reg [3:0] popcount;
    reg done_reg;
    reg [2:0] scan_idx;
    reg [DATA_WIDTH-1:0] reg_a [0:NUM_PEOPLE-1];
    reg [DATA_WIDTH-1:0] reg_b [0:NUM_PEOPLE-1];
    reg [DATA_WIDTH-1:0] reg_c [0:NUM_PEOPLE-1];
    reg [3:0] popcount_rom [0:255];
    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) begin
            popcount_rom[i] = 0;
            if (i[0]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[1]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[2]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[3]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[4]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[5]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[6]) popcount_rom[i] = popcount_rom[i] + 1;
            if (i[7]) popcount_rom[i] = popcount_rom[i] + 1;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            mask <= 8'b0;
            best_count <= 4'b0;
            max_a <= 0; max_b <= 0; max_c <= 0;
            sum <= 0; popcount <= 0; done_reg <= 0;
            scan_idx <= 0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    if (start) begin
                        reg_a[0] <= a0; reg_a[1] <= a1; reg_a[2] <= a2; reg_a[3] <= a3;
                        reg_a[4] <= a4; reg_a[5] <= a5; reg_a[6] <= a6; reg_a[7] <= a7;
                        reg_b[0] <= b0; reg_b[1] <= b1; reg_b[2] <= b2; reg_b[3] <= b3;
                        reg_b[4] <= b4; reg_b[5] <= b5; reg_b[6] <= b6; reg_b[7] <= b7;
                        reg_c[0] <= c0; reg_c[1] <= c1; reg_c[2] <= c2; reg_c[3] <= c3;
                        reg_c[4] <= c4; reg_c[5] <= c5; reg_c[6] <= c6; reg_c[7] <= c7;
                        best_count <= 0; done_reg <= 0;
                    end
                end
                INIT: begin
                    mask <= 8'b0; scan_idx <= 0;
                    max_a <= 0; max_b <= 0; max_c <= 0;
                end
                LOOP: begin
                    if (mask == 8'd256) done_reg <= 1;
                    else begin
                        scan_idx <= 0;
                        max_a <= 0; max_b <= 0; max_c <= 0;
                    end
                end
                SCAN: begin
                    if (mask[scan_idx]) begin
                        if (reg_a[scan_idx] > max_a) max_a <= reg_a[scan_idx];
                        if (reg_b[scan_idx] > max_b) max_b <= reg_b[scan_idx];
                        if (reg_c[scan_idx] > max_c) max_c <= reg_c[scan_idx];
                    end
                    scan_idx <= scan_idx + 1;
                end
                CHECK: sum <= max_a + max_b + max_c;
                POPCOUNT: popcount <= popcount_rom[mask];
                UPDATE: begin
                    if (sum <= MAX_SUM && popcount > best_count) best_count <= popcount;
                    mask <= mask + 1;
                end
            endcase
        end
    end
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = INIT; else next_state = IDLE;
            INIT: next_state = LOOP;
            LOOP: if (mask == 8'd256) next_state = IDLE; else next_state = SCAN;
            SCAN: if (scan_idx == NUM_PEOPLE-1) next_state = CHECK; else next_state = SCAN;
            CHECK: next_state = POPCOUNT;
            POPCOUNT: next_state = UPDATE;
            UPDATE: next_state = LOOP;
        endcase
    end
    assign result = best_count;
    assign done = done_reg;
endmodule

