// 2. Check if edge crosses y = h_mid
// 3. Compute intersection if needed (requires division)
// 4. Build clip_x and clip_y arrays
// 5. Compute area using shoelace: area = 1/2 * sum(x_i*y_{i+1} - x_{i+1}*y_i)
// 6. Store result in area_mid

endmodule

module tree_avg_dist (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,                    // Number of ports (2-8)
    input wire [63:0] dist_matrix,         // Packed 8x8 distance matrix, each 8-bit element
    output reg [15:0] result,              // Q8.8 fixed-point average distance
    output reg done
);

// Internal state definitions
reg [2:0] state;                           // State machine
reg [3:0] i, j;                            // Loop counters
reg [7:0] dist_sum;                       // Sum of distances (8-bit max for n=8)
reg [7:0] divisor;                         // n*(n-1)/2
reg [15:0] temp_result;                   // For division

// State definitions
localparam IDLE = 3'd0;
localparam CALC_SUM = 3'd1;
localparam DIVIDE = 3'd2;
localparam CONVERT = 3'd3;
localparam DONE = 3'd4;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 16'd0;
        done <= 1'b0;
        dist_sum <= 8'd0;
        divisor <= 8'd0;
        i <= 4'd0;
        j <= 4'd0;
        temp_result <= 16'd0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    state <= CALC_SUM;
                    dist_sum <= 8'd0;
                    i <= 4'd0;
                    j <= 4'd0;
                end
            end

            CALC_SUM: begin
                // Extract distance from packed matrix
                // Each row has 8 elements of 8 bits
                // dist_matrix[i*64 + j*8 +: 8]
                if (i < n && j < n) begin
                    if (i != j) begin
                        dist_sum <= dist_sum + dist_matrix[i*64 + j*8 +: 8];
                    end
                    // Increment counters
                    if (j == n - 1) begin
                        j <= 4'd0;
                        i <= i + 1'b1;
                    end else begin
                        j <= j + 1'b1;
                    end
                end else begin
                    state <= DIVIDE;
                    // Calculate divisor = n*(n-1)/2
                    divisor <= (n * (n - 1)) >> 1;
                    i <= 4'd0;
                end
            end

            DIVIDE: begin
                // Perform division: dist_sum / divisor
                // For Q8.8: result = (dist_sum << 8) / divisor
                if (divisor != 8'd0) begin
                    temp_result <= (dist_sum << 8) / divisor;
                end else begin
                    temp_result <= 16'd0; // Avoid division by zero
                end
                state <= CONVERT;
            end

            CONVERT: begin
                // Result already in Q8.8 format
                result <= temp_result;
                state <= DONE;
            end

            DONE: begin
                done <= 1'b1;
                if (!start) begin
                    state <= IDLE;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module potato_optimizer (
    input clk,
    input rst_n,
    input start,
    input [3:0] N,          // Number of farmers (2-8)
    input [3:0] L,          // Required bags in one store (1-7)
    input [7:0] a [0:7],    // Potatoes per bag (1-100)
    input [19:0] c [0:7],   // Cost per bag (1-1000000)
    output reg [31:0] result, // Fixed-point 16.16 product P1*P2
    output reg done
);

// Parameters
parameter MAX_BAGS = 8;
parameter MAX_POTATOES = 500;
parameter DATA_WIDTH = 8;
parameter COST_WIDTH = 20;
parameter RESULT_WIDTH = 32;

// States
localparam IDLE = 3'b000;
localparam COMPUTE = 3'b001;
localparam CALCULATE = 3'b010;
localparam DONE = 3'b011;

reg [2:0] state;

// Internal signals
reg [7:0] total_potatoes;
reg [19:0] total_cost;
reg [3:0] bag_count;

// DP arrays: [number_of_bags][total_potatoes]
// We only need to store current and previous states
reg [19:0] dp_cost [0:MAX_BAGS][0:MAX_POTATOES];  // Minimum cost for given bags and potatoes
reg dp_valid [0:MAX_BAGS][0:MAX_POTATOES];        // Valid state flag

// Computation registers
reg [3:0] current_bag;
reg [7:0] current_potatoes;
reg [19:0] current_cost;

// Result calculation
reg [31:0] best_product;  // 16.16 format
reg [3:0] check_k;        // Current k being checked
reg [7:0] check_t;        // Current t being checked

integer i, j;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset state
        state <= IDLE;
        done <= 0;
        result <= 0;
        total_potatoes <= 0;
        total_cost <= 0;
        bag_count <= 0;
        current_bag <= 0;
        current_potatoes <= 0;
        current_cost <= 0;
        best_product <= 32'h7FFFFFFF;  // Initialize to max value
        check_k <= 0;
        check_t <= 0;

        // Clear DP arrays
        for (i = 0; i <= MAX_BAGS; i = i + 1) begin
            for (j = 0; j <= MAX_POTATOES; j = j + 1) begin
                dp_cost[i][j] <= 0;
                dp_valid[i][j] <= 0;
            end
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Compute totals
                    total_potatoes <= 0;
                    total_cost <= 0;
                    bag_count <= N;
                    for (i = 0; i < N; i = i + 1) begin
                        total_potatoes <= total_potatoes + a[i];
                        total_cost <= total_cost + c[i];
                    end

                    // Initialize DP
                    // dp[0][0] = 0 (cost 0 for 0 bags, 0 potatoes)
                    for (i = 0; i <= MAX_BAGS; i = i + 1) begin
                        for (j = 0; j <= MAX_POTATOES; j = j + 1) begin
                            dp_valid[i][j] <= 0;
                        end
                    end
                    dp_cost[0][0] <= 0;
                    dp_valid[0][0] <= 1;

                    current_bag <= 0;
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                if (current_bag < N) begin
                    // Process bag current_bag
                    // Update DP table for this bag
                    for (i = MAX_BAGS; i >= 1; i = i - 1) begin
                        for (j = MAX_POTATOES; j >= a[current_bag]; j = j - 1) begin
                            if (dp_valid[i-1][j - a[current_bag]]) begin
                                if (!dp_valid[i][j] || (dp_cost[i-1][j - a[current_bag]] + c[current_bag] < dp_cost[i][j])) begin
                                    dp_cost[i][j] <= dp_cost[i-1][j - a[current_bag]] + c[current_bag];
                                    dp_valid[i][j] <= 1;
                                end
                            end
                        end
                    end
                    current_bag <= current_bag + 1;
                end else begin
                    // Done processing all bags
                    check_k <= 0;
                    check_t <= 0;
                    best_product <= 32'h7FFFFFFF;
                    state <= CALCULATE;
                end
            end

            CALCULATE: begin
                // Check all possible divisions where one store has exactly L bags
                if (check_k <= N) begin
                    // Case 1: Store 1 has L bags
                    if (check_k == L) begin
                        for (j = 0; j <= MAX_POTATOES; j = j + 1) begin
                            if (dp_valid[check_k][j] && dp_valid[N - check_k][total_potatoes - j]) begin
                                if (j > 0 && (total_potatoes - j) > 0) begin
                                    // Calculate P1 * P2 = (cost1/potatoes1) * (cost2/potatoes2)
                                    // = (cost1 * cost2) / (potatoes1 * potatoes2)
                                    // Using fixed-point: multiply by 2^16 for 16.16 format

                                    // Calculate cost1 and cost2
                                    // cost1 = dp_cost[check_k][j]
                                    // cost2 = total_cost - dp_cost[check_k][j]

                                    // We'll do integer division with scaling
                                    // To avoid overflow, we'll do: (cost1 * cost2 * 2^16) / (j * (total_potatoes - j))

                                    // Use intermediate registers to avoid timing issues
                                    reg [39:0] numerator;
                                    reg [39:0] denominator;
                                    reg [31:0] product;

                                    numerator = dp_cost[check_k][j] * (total_cost - dp_cost[check_k][j]);
                                    numerator = numerator << 16;  // Scale by 2^16
                                    denominator = j * (total_potatoes - j);

                                    if (denominator != 0) begin
                                        product = numerator / denominator;
                                        if (product < best_product) begin
                                            best_product <= product;
                                        end
                                    end
                                end
                            end
                        end
                    end

                    // Case 2: Store 2 has L bags (store 1 has N-L bags)
                    if (check_k == N - L && L != N - L) begin  // Avoid duplicate if L = N-L
                        for (j = 0; j <= MAX_POTATOES; j = j + 1) begin
                            if (dp_valid[check_k][j] && dp_valid[N - check_k][total_potatoes - j]) begin
                                if (j > 0 && (total_potatoes - j) > 0) begin
                                    // Similar calculation as above
                                    reg [39:0] numerator;
                                    reg [39:0] denominator;
                                    reg [31:0] product;

                                    numerator = dp_cost[check_k][j] * (total_cost - dp_cost[check_k][j]);
                                    numerator = numerator << 16;
                                    denominator = j * (total_potatoes - j);

                                    if (denominator != 0) begin
                                        product = numerator / denominator;
                                        if (product < best_product) begin
                                            best_product <= product;
                                        end
                                    end
                                end
                            end
                        end
                    end

                    check_k <= check_k + 1;
                end else begin
                    // All combinations checked
                    result <= best_product;
                    done <= 1;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 0;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module fox_hiding_distance (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] roost_x,    // Q12.20 fixed-point
    input wire [31:0] roost_y,
    input wire [31:0] spot_x [0:7],
    input wire [31:0] spot_y [0:7],
    input wire [3:0] N,            // number of spots (1..8)
    output reg done,
    output reg [31:0] result       // Q12.20 fixed-point
);

parameter MAX_N = 8;
parameter FRAC_BITS = 20;
parameter SCALE = 1 << FRAC_BITS; // 1048576

// State definitions
localparam IDLE = 0;
localparam COMPUTE_DIST_ROOST = 1;
localparam COMPUTE_DIST_SPOT = 2;
localparam DP_INIT = 3;
localparam DP_OUTER = 4;
localparam DP_INNER_I = 5;
localparam DP_INNER_J = 6;
localparam DP_UPDATE = 7;
localparam DONE_STATE = 8;

reg [3:0] state;
reg [3:0] next_state;

// Loop counters
reg [3:0] i_cnt, j_cnt;          // indices for spots
reg [7:0] mask;                  // current subset mask
reg [7:0] prev_mask;             // mask without i/j
reg [7:0] dp_addr;               // address for dp memory
reg [31:0] dp_data;              // data for dp memory
reg dp_wr_en;                    // write enable for dp memory

// Distance storage
dist_roost [0:7]: reg [31:0];    // distances from roost to each spot
dist_spot [0:7][0:7]: reg [31:0]; // distances between spots

// DP memory: 256 entries of 32-bit
reg [31:0] dp [0:255];

// Temporary registers for distance computation
reg [31:0] x1, y1, x2, y2;
real dx, dy, dist_real;

// Task to compute Euclidean distance (simulation only)
task compute_distance;
    input [31:0] x1_in, y1_in, x2_in, y2_in;
    output [31:0] dist_out;
    real x1_real, y1_real, x2_real, y2_real;
    begin
        x1_real = $itor(x1_in) / SCALE;
        y1_real = $itor(y1_in) / SCALE;
        x2_real = $itor(x2_in) / SCALE;
        y2_real = $itor(y2_in) / SCALE;
        dx = x1_real - x2_real;
        dy = y1_real - y2_real;
        dist_real = $sqrt(dx*dx + dy*dy);
        dist_out = $rtoi(dist_real * SCALE);
    end
endtask

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = COMPUTE_DIST_ROOST;
        COMPUTE_DIST_ROOST: if (i_cnt >= N) next_state = COMPUTE_DIST_SPOT;
        COMPUTE_DIST_SPOT: if (i_cnt >= N) next_state = DP_INIT;
        DP_INIT: next_state = DP_OUTER;
        DP_OUTER: if (mask > (1 << N) - 1) next_state = DONE_STATE;
                  else next_state = DP_INNER_I;
        DP_INNER_I: if (i_cnt >= N) next_state = DP_OUTER;
                    else if (mask[i_cnt]) next_state = DP_INNER_J;
                    else next_state = DP_INNER_I;
        DP_INNER_J: if (j_cnt >= N) next_state = DP_INNER_I;
                    else if (j_cnt > i_cnt && mask[j_cnt]) next_state = DP_UPDATE;
                    else next_state = DP_INNER_J;
        DP_UPDATE: next_state = DP_INNER_J;
        DONE_STATE: if (!start) next_state = IDLE;
    endcase
end

// Control signals and counters
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i_cnt <= 0;
        j_cnt <= 0;
        mask <= 1;
        dp_wr_en <= 0;
        done <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                i_cnt <= 0;
                j_cnt <= 0;
                mask <= 1;
                done <= 0;
            end
            COMPUTE_DIST_ROOST: begin
                // Compute distance from roost to spot i_cnt
                x1 <= roost_x;
                y1 <= roost_y;
                x2 <= spot_x[i_cnt];
                y2 <= spot_y[i_cnt];
                compute_distance(x1, y1, x2, y2, dist_roost[i_cnt]);
                i_cnt <= i_cnt + 1;
            end
            COMPUTE_DIST_SPOT: begin
                // Compute distance between spot i_cnt and spot j_cnt
                if (i_cnt < N && j_cnt < N && i_cnt != j_cnt) begin
                    x1 <= spot_x[i_cnt];
                    y1 <= spot_y[i_cnt];
                    x2 <= spot_x[j_cnt];
                    y2 <= spot_y[j_cnt];
                    compute_distance(x1, y1, x2, y2, dist_spot[i_cnt][j_cnt]);
                end
                // Increment j_cnt, then i_cnt when j_cnt reaches N
                if (j_cnt + 1 >= N) begin
                    j_cnt <= 0;
                    i_cnt <= i_cnt + 1;
                end else begin
                    j_cnt <= j_cnt + 1;
                end
            end
            DP_INIT: begin
                dp[0] <= 0;
                mask <= 1;
                i_cnt <= 0;
                j_cnt <= 0;
            end
            DP_OUTER: begin
                if (mask > (1 << N) - 1) begin
                    // Done, result is dp[(1<<N)-1]
                    result <= dp[(1 << N) - 1];
                    done <= 1;
                end else begin
                    // Initialize dp[mask] to a large value (e.g., 32'h7FFFFFFF)
                    dp[mask] <= 32'h7FFFFFFF;
                    i_cnt <= 0;
                    j_cnt <= 0;
                end
            end
            DP_INNER_I: begin
                if (i_cnt < N) begin
                    if (mask[i_cnt]) begin
                        // Consider trip with single spot i_cnt
                        prev_mask <= mask & ~(1 << i_cnt);
                        // Compute cost = 2 * dist_roost[i_cnt]
                        // Addition is cheaper than multiplication by 2
                        dp_data <= dp[prev_mask] + dist_roost[i_cnt] + dist_roost[i_cnt];
                        dp_addr <= mask;
                        dp_wr_en <= 1;
                        // After update, move to next i
                        i_cnt <= i_cnt + 1;
                    end else begin
                        i_cnt <= i_cnt + 1;
                    end
                end
            end
            DP_INNER_J: begin
                dp_wr_en <= 0; // disable write from previous state
                if (j_cnt < N) begin
                    if (j_cnt > i_cnt && mask[j_cnt]) begin
                        // Consider trip with two spots i_cnt and j_cnt
                        prev_mask <= mask & ~(1 << i_cnt) & ~(1 << j_cnt);
                        // Compute cost = dist_roost[i_cnt] + dist_spot[i_cnt][j_cnt] + dist_roost[j_cnt]
                        dp_data <= dp[prev_mask] + dist_roost[i_cnt] + dist_spot[i_cnt][j_cnt] + dist_roost[j_cnt];
                        dp_addr <= mask;
                        dp_wr_en <= 1;
                    end
                    j_cnt <= j_cnt + 1;
                end else begin
                    // Done with j loop, move to next i
                    j_cnt <= 0;
                    i_cnt <= i_cnt + 1;
                end
            end
            DP_UPDATE: begin
                // Update dp[mask] with min(dp[mask], dp_data)
                if (dp_wr_en) begin
                    if (dp_data < dp[mask]) begin
                        dp[mask] <= dp_data;
                    end
                    dp_wr_en <= 0;
                end
            end
            DONE_STATE: begin
                // Wait for start to go low
                done <= 1;
            end
        endcase
    end
end

endmodule

module stack_operations #(
    parameter MAX_OPS = 16,          // Maximum operations (scaled from 300k to 16)
    parameter MAX_STACK_SIZE = 8,    // Maximum stack depth
    parameter DATA_WIDTH = 8,        // Number width (fits 1-16)
    parameter ADDR_WIDTH = 4         // Stack address width (16 stacks)
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] op_type,       // 00=push, 01=pop, 10=count
    input wire [ADDR_WIDTH-1:0] v,  // First stack operand
    input wire [ADDR_WIDTH-1:0] w,  // Second stack operand (type 10 only)
    output reg [15:0] result,       // Result for pop and count operations
    output reg done                 // Operation complete pulse
);

// Internal memory for all stacks
reg [DATA_WIDTH-1:0] stacks [0:MAX_OPS-1][0:MAX_STACK_SIZE-1];
reg [2:0] stack_len [0:MAX_OPS-1];

// Operation tracking
reg [ADDR_WIDTH-1:0] op_counter;   // Current operation number (1..MAX_OPS)
reg [ADDR_WIDTH-1:0] current_idx;  // Next stack index to allocate

// FSM states
localparam IDLE = 3'd0;
localparam EXECUTE = 3'd1;
localparam TYPE_C_CALC = 3'd2;
localparam DONE = 3'd3;
reg [2:0] state;

// Type C calculation registers
reg [2:0] c_i;                      // Element index in stack v
reg [3:0] c_count;                  // Accumulated intersection count
reg c_match_found;                  // Match flag for current element

// Combinational logic for type C: check if value exists in stack w
wire exists_in_w;
assign exists_in_w = (
    (c_i < stack_len[v]) && (
        (stack_len[w] > 0 && stacks[v][c_i] == stacks[w][0]) ||
        (stack_len[w] > 1 && stacks[v][c_i] == stacks[w][1]) ||
        (stack_len[w] > 2 && stacks[v][c_i] == stacks[w][2]) ||
        (stack_len[w] > 3 && stacks[v][c_i] == stacks[w][3]) ||
        (stack_len[w] > 4 && stacks[v][c_i] == stacks[w][4]) ||
        (stack_len[w] > 5 && stacks[v][c_i] == stacks[w][5]) ||
        (stack_len[w] > 6 && stacks[v][c_i] == stacks[w][6]) ||
        (stack_len[w] > 7 && stacks[v][c_i] == stacks[w][7])
    )
);

// Reset and state transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all state
        state <= IDLE;
        op_counter <= 1;
        current_idx <= 1;
        done <= 0;
        result <= 0;
        c_i <= 0;
        c_count <= 0;
        c_match_found <= 0;
        // Clear stack lengths
        for (integer i = 0; i < MAX_OPS; i = i + 1) begin
            stack_len[i] <= 0;
        end
    end else begin
        done <= 0;  // Pulse done only for 1 cycle

        case (state)
            IDLE: begin
                if (start) begin
                    state <= EXECUTE;
                end
            end

            EXECUTE: begin
                case (op_type)
                    2'b00: begin // Type A: Push
                        // Copy stack v to new stack
                        if (current_idx < MAX_OPS) begin
                            stack_len[current_idx] <= stack_len[v] + 1;
                            for (integer i = 0; i < MAX_STACK_SIZE; i = i + 1) begin
                                if (i < stack_len[v]) begin
                                    stacks[current_idx][i] <= stacks[v][i];
                                end
                            end
                            // Push operation number on top
                            if (stack_len[v] < MAX_STACK_SIZE) begin
                                stacks[current_idx][stack_len[v]] <= op_counter;
                            end
                            op_counter <= op_counter + 1;
                            current_idx <= current_idx + 1;
                        end
                        state <= DONE;
                    end

                    2'b01: begin // Type B: Pop
                        if (current_idx < MAX_OPS && stack_len[v] > 0) begin
                            // Copy stack v (without top element)
                            stack_len[current_idx] <= stack_len[v] - 1;
                            for (integer i = 0; i < MAX_STACK_SIZE; i = i + 1) begin
                                if (i < stack_len[v] - 1) begin
                                    stacks[current_idx][i] <= stacks[v][i];
                                end
                            end
                            // Output popped value
                            result <= stacks[v][stack_len[v] - 1];
                            op_counter <= op_counter + 1;
                            current_idx <= current_idx + 1;
                        end
                        state <= DONE;
                    end

                    2'b10: begin // Type C: Count common elements
                        // Initialize type C calculation
                        c_i <= 0;
                        c_count <= 0;
                        c_match_found <= 0;
                        state <= TYPE_C_CALC;
                    end

                    default: begin
                        state <= DONE;
                    end
                endcase
            end

            TYPE_C_CALC: begin
                // Process each element of stack v
                if (c_i < stack_len[v]) begin
                    // Check if current element exists in stack w
                    if (exists_in_w && !c_match_found) begin
                        c_count <= c_count + 1;
                        c_match_found <= 1; // Prevent double-counting for this element
                    end
                    c_i <= c_i + 1;
                    // Reset match flag for next element (in next cycle)
                    if (c_i + 1 < stack_len[v]) begin
                        c_match_found <= 0;
                    end
                end else begin
                    // Type C complete
                    result <= c_count;
                    op_counter <= op_counter + 1;
                    current_idx <= current_idx + 1;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module stream_scheduler (
    input clk,
    input rst_n,
    input start,
    // 4 streams: each with start (8-bit), duration (8-bit), priority (8-bit)
    input [7:0] s0, d0, p0,
    input [7:0] s1, d1, p1,
    input [7:0] s2, d2, p2,
    input [7:0] s3, d3, p3,
    output reg [15:0] result,
    output reg done
);

// Behavior:
// When start is asserted, load inputs and compute max priority.
// Enumerate all 16 subsets of 4 streams.
// For each subset:
//   - Sum priorities of included streams.
//   - Check feasibility: No crossing intervals.
//     Two intervals i and j cross if:
//       (s_i < s_j < e_i < e_j) or (s_j < s_i < e_j < e_i)
//     where e_i = s_i + d_i, e_j = s_j + d_j.
//   - If feasible, update maximum.
// After computation, assert done and output max priority.
// Completes within 100 cycles.

// Reset behavior:
// On rst_n = 0: done = 0, result = 0, state machine reset to IDLE.
// Minimum 2 clock cycles of reset required.

// Interface details:
// - Clock: rising edge triggered.
// - Start: pulse high for one cycle when inputs are valid.
// - Done: high for one cycle when result is valid.
// - Result: 16-bit maximum total priority.

// Implementation notes:
// - Use a state machine with states: IDLE, LOAD, COMPUTE, UPDATE, DONE.
// - Compute end times as s_i + d_i (use 16-bit to avoid overflow).
// - For each subset, iterate over all 6 unordered pairs.
// - Use combinational comparisons for crossing checks.
// - Update result when a feasible subset has higher total priority.

endmodule

module max_excursion (
    input clk,              // Clock signal
    input rst_n,            // Active-low reset
    input start,            // Start pulse (1 cycle)
    input [7:0] valid,      // Valid mask for pupils (1=valid)
    input [31:0] arr_0,     // Pupil 0 data: {sport[7:0], music[7:0], height[11:0], sex[0], unused[2:0]}
    input [31:0] arr_1,     // Pupil 1 data
    input [31:0] arr_2,     // Pupil 2 data
    input [31:0] arr_3,     // Pupil 3 data
    input [31:0] arr_4,     // Pupil 4 data
    input [31:0] arr_5,     // Pupil 5 data
    input [31:0] arr_6,     // Pupil 6 data
    input [31:0] arr_7,     // Pupil 7 data
    output reg [7:0] max_size, // Maximum eligible pupils
    output reg done           // Computation done (1 cycle)
);

// State definitions
localparam S_IDLE = 4'd0;
localparam S_DECODE = 4'd1;
localparam S_ENUM_START = 4'd2;
localparam S_ENUM_CHECK = 4'd3;
localparam S_ENUM_POPCOUNT = 4'd4;

// Internal registers
reg [3:0] state;
reg [7:0] mask_reg;        // Current subset mask
reg [7:0] max_size_reg;    // Internal max size
reg [2:0] i_idx, j_idx;    // Pair indices for checking
reg checking_valid;        // Flag for current mask validity

// Registered attributes for each pupil
reg [11:0] height_0, height_1, height_2, height_3, height_4, height_5, height_6, height_7;
reg sex_0, sex_1, sex_2, sex_3, sex_4, sex_5, sex_6, sex_7;
reg [7:0] music_0, music_1, music_2, music_3, music_4, music_5, music_6, music_7;
reg [7:0] sport_0, sport_1, sport_2, sport_3, sport_4, sport_5, sport_6, sport_7;

// Combinational signals for compatibility check
reg [11:0] h_i, h_j;
reg sex_i, sex_j;
reg [7:0] music_i, music_j, sport_i, sport_j;
wire comp_ij;
wire cond1, cond2, cond3, cond4;
wire [7:0] popcount_result;

// Compatibility computation
always @* begin
    // Select attributes based on i_idx and j_idx
    case(i_idx)
        3'd0: begin h_i = height_0; sex_i = sex_0; music_i = music_0; sport_i = sport_0; end
        3'd1: begin h_i = height_1; sex_i = sex_1; music_i = music_1; sport_i = sport_1; end
        3'd2: begin h_i = height_2; sex_i = sex_2; music_i = music_2; sport_i = sport_2; end
        3'd3: begin h_i = height_3; sex_i = sex_3; music_i = music_3; sport_i = sport_3; end
        3'd4: begin h_i = height_4; sex_i = sex_4; music_i = music_4; sport_i = sport_4; end
        3'd5: begin h_i = height_5; sex_i = sex_5; music_i = music_5; sport_i = sport_5; end
        3'd6: begin h_i = height_6; sex_i = sex_6; music_i = music_6; sport_i = sport_6; end
        3'd7: begin h_i = height_7; sex_i = sex_7; music_i = music_7; sport_i = sport_7; end
    endcase
    case(j_idx)
        3'd0: begin h_j = height_0; sex_j = sex_0; music_j = music_0; sport_j = sport_0; end
        3'd1: begin h_j = height_1; sex_j = sex_1; music_j = music_1; sport_j = sport_1; end
        3'd2: begin h_j = height_2; sex_j = sex_2; music_j = music_2; sport_j = sport_2; end
        3'd3: begin h_j = height_3; sex_j = sex_3; music_j = music_3; sport_j = sport_3; end
        3'd4: begin h_j = height_4; sex_j = sex_4; music_j = music_4; sport_j = sport_4; end
        3'd5: begin h_j = height_5; sex_j = sex_5; music_j = music_5; sport_j = sport_5; end
        3'd6: begin h_j = height_6; sex_j = sex_6; music_j = music_6; sport_j = sport_6; end
        3'd7: begin h_j = height_7; sex_j = sex_7; music_j = music_7; sport_j = sport_7; end
    endcase
    // Conditions
    cond1 = (h_i > h_j + 12'd40) || (h_j > h_i + 12'd40); // Height diff > 40
    cond2 = (sex_i == sex_j);                               // Same sex
    cond3 = (music_i != music_j);                           // Different music
    cond4 = (sport_i == sport_j);                           // Same sport
    comp_ij = cond1 || cond2 || cond3 || cond4;
end

// Popcount computation (8-bit)
assign popcount_result = mask_reg[0] + mask_reg[1] + mask_reg[2] + mask_reg[3] + 
                        mask_reg[4] + mask_reg[5] + mask_reg[6] + mask_reg[7];

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        max_size <= 0;
        mask_reg <= 0;
        max_size_reg <= 0;
        checking_valid <= 0;
        i_idx <= 0;
        j_idx <= 0;
        // Reset attributes to zero
        height_0 <= 0; height_1 <= 0; height_2 <= 0; height_3 <= 0;
        height_4 <= 0; height_5 <= 0; height_6 <= 0; height_7 <= 0;
        sex_0 <= 0; sex_1 <= 0; sex_2 <= 0; sex_3 <= 0;
        sex_4 <= 0; sex_5 <= 0; sex_6 <= 0; sex_7 <= 0;
        music_0 <= 0; music_1 <= 0; music_2 <= 0; music_3 <= 0;
        music_4 <= 0; music_5 <= 0; music_6 <= 0; music_7 <= 0;
        sport_0 <= 0; sport_1 <= 0; sport_2 <= 0; sport_3 <= 0;
        sport_4 <= 0; sport_5 <= 0; sport_6 <= 0; sport_7 <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= S_DECODE;
                end
            end

            S_DECODE: begin
                // Decode and register pupil data
                height_0 <= arr_0[15:4]; sex_0 <= arr_0[3]; music_0 <= arr_0[23:16]; sport_0 <= arr_0[31:24];
                height_1 <= arr_1[15:4]; sex_1 <= arr_1[3]; music_1 <= arr_1[23:16]; sport_1 <= arr_1[31:24];
                height_2 <= arr_2[15:4]; sex_2 <= arr_2[3]; music_2 <= arr_2[23:16]; sport_2 <= arr_2[31:24];
                height_3 <= arr_3[15:4]; sex_3 <= arr_3[3]; music_3 <= arr_3[23:16]; sport_3 <= arr_3[31:24];
                height_4 <= arr_4[15:4]; sex_4 <= arr_4[3]; music_4 <= arr_4[23:16]; sport_4 <= arr_4[31:24];
                height_5 <= arr_5[15:4]; sex_5 <= arr_5[3]; music_5 <= arr_5[23:16]; sport_5 <= arr_5[31:24];
                height_6 <= arr_6[15:4]; sex_6 <= arr_6[3]; music_6 <= arr_6[23:16]; sport_6 <= arr_6[31:24];
                height_7 <= arr_7[15:4]; sex_7 <= arr_7[3]; music_7 <= arr_7[23:16]; sport_7 <= arr_7[31:24];
                // Initialize enumeration
                mask_reg <= 0;
                max_size_reg <= 0;
                state <= S_ENUM_START;
            end

            S_ENUM_START: begin
                if (mask_reg > 8'hFF) begin
                    // Finished all masks
                    max_size <= max_size_reg;
                    done <= 1;
                    state <= S_IDLE;
                end else begin
                    // Check if mask is subset of valid set
                    if ((mask_reg & ~valid) == 8'd0) begin
                        // Initialize pair checking
                        i_idx <= 0;
                        j_idx <= 1;
                        checking_valid <= 1;
                        state <= S_ENUM_CHECK;
                    end else begin
                        // Skip invalid mask
                        mask_reg <= mask_reg + 1;
                        state <= S_ENUM_START;
                    end
                end
            end

            S_ENUM_CHECK: begin
                if (i_idx >= 3'd7 && j_idx >= 3'd7) begin
                    // Finished all pairs for this mask
                    if (checking_valid) begin
                        state <= S_ENUM_POPCOUNT;
                    end else begin
                        mask_reg <= mask_reg + 1;
                        state <= S_ENUM_START;
                    end
                end else if (j_idx >= 3'd7) begin
                    // Move to next i
                    i_idx <= i_idx + 1;
                    j_idx <= i_idx + 2;
                end else begin
                    // Check if both pupils are in the mask
                    if (mask_reg[i_idx] && mask_reg[j_idx]) begin
                        // Compute compatibility
                        if (!comp_ij) begin
                            checking_valid <= 0;
                        end
                    end
                    j_idx <= j_idx + 1;
                end
            end

            S_ENUM_POPCOUNT: begin
                // Update max size if current mask is larger
                if (popcount_result > max_size_reg) begin
                    max_size_reg <= popcount_result;
                end
                mask_reg <= mask_reg + 1;
                state <= S_ENUM_START;
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

module evenland (
    input wire clk,
    input wire rst_n,
    input wire start,           // start the process (reset and prepare for input)
    input wire edge_valid,      // indicates edge data is valid
    input wire [3:0] N,         // number of vertices (1-8)
    input wire [4:0] M,         // total number of edges (1-16)
    input wire [2:0] edge_a,    // vertex a (1 to N)
    input wire [2:0] edge_b,    // vertex b (1 to N)
    output reg [31:0] result,   // number of ways modulo 1000000009
    output reg done             // asserted when result is valid
);

    // Maximum sizes (for synthesis)
    localparam MAX_N = 8;
    localparam MAX_M = 16;

    // State definitions
    localparam IDLE          = 0;
    localparam COLLECT       = 1;
    localparam FIND          = 2;
    localparam PROCESS_RESULT= 3;
    localparam UNION         = 4;
    localparam CHECK_DONE    = 5;
    localparam COMPUTE_INIT  = 6;
    localparam COMPUTE_LOOP  = 7;
    localparam COMPUTE_RESULT= 8;
    localparam DONE          = 9;

    // Registers
    reg [3:0] state;
    reg [3:0] next_state;
    reg [3:0] parent [0:MAX_N-1];   // parent[i] stores parent of vertex i (0-indexed)
    reg [4:0] edge_count;           // number of edges processed
    reg [4:0] M_reg;                // copy of M
    reg [3:0] N_reg;                // copy of N
    reg [2:0] temp_a, temp_b;       // temporary storage for edge vertices (0-indexed)
    reg [2:0] find_target;          // vertex whose root we are searching
    reg [2:0] root_a, root_b;       // roots for edge vertices
    reg [2:0] root_temp;            // temporary root storage
    reg [1:0] phase;                // 0: idle, 1: find_a, 2: find_b, 3: component
    reg [2:0] find_iter;            // iteration counter for find loop
    reg [3:0] i;                    // loop index for component counting
    reg [3:0] component_count;      // number of connected components
    reg [7:0] seen_roots;           // bitmask of seen roots
    reg [4:0] shift_amount;         // exponent for result
    reg [31:0] result_reg;          // internal result register
    reg done_reg;                   // internal done flag

    // Combinational next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = COLLECT;
            COLLECT: begin
                if (edge_count < M_reg && edge_valid) next_state = FIND;
                else if (edge_count == M_reg) next_state = COMPUTE_INIT;
            end
            FIND: begin
                if (parent[find_target] == find_target) next_state = PROCESS_RESULT;
                else if (find_iter >= 7) next_state = PROCESS_RESULT; // safety
                else next_state = FIND;
            end
            PROCESS_RESULT: begin
                if (phase == 1) next_state = FIND; // find b
                else if (phase == 2) next_state = UNION;
                else if (phase == 3) next_state = COMPUTE_LOOP;
            end
            UNION: next_state = CHECK_DONE;
            CHECK_DONE: begin
                if (edge_count == M_reg) next_state = COMPUTE_INIT;
                else next_state = COLLECT;
            end
            COMPUTE_INIT: next_state = COMPUTE_LOOP;
            COMPUTE_LOOP: begin
                if (i >= N_reg) next_state = COMPUTE_RESULT;
                else next_state = FIND;
            end
            COMPUTE_RESULT: next_state = DONE;
            DONE: next_state = DONE;
            default: next_state = IDLE;
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            edge_count <= 0;
            done_reg <= 0;
            result <= 0;
            done <= 0;
        end else begin
            state <= next_state;
            case (state)
                IDLE: begin
                    if (start) begin
                        // Initialize parent array: each vertex is its own parent
                        parent[0] <= 4'd0;
                        parent[1] <= 4'd1;
                        parent[2] <= 4'd2;
                        parent[3] <= 4'd3;
                        parent[4] <= 4'd4;
                        parent[5] <= 4'd5;
                        parent[6] <= 4'd6;
                        parent[7] <= 4'd7;
                        edge_count <= 0;
                        M_reg <= M;
                        N_reg <= N;
                        done_reg <= 0;
                        result <= 0;
                        done <= 0;
                    end
                end
                COLLECT: begin
                    if (edge_count < M_reg && edge_valid) begin
                        temp_a <= edge_a - 1; // convert to 0-index
                        temp_b <= edge_b - 1;
                        edge_count <= edge_count + 1;
                        phase <= 2'd1;          // find a next
                        find_target <= edge_a - 1;
                        find_iter <= 0;
                    end
                end
                FIND: begin
                    if (parent[find_target] == find_target) begin
                        root_temp <= find_target;
                    end else if (find_iter >= 7) begin
                        root_temp <= find_target; // forced root
                    end else begin
                        find_target <= parent[find_target];
                        find_iter <= find_iter + 1;
                    end
                end
                PROCESS_RESULT: begin
                    if (phase == 2'd1) begin
                        root_a <= root_temp;
                        phase <= 2'd2;          // find b next
                        find_target <= temp_b;
                        find_iter <= 0;
                    end else if (phase == 2'd2) begin
                        root_b <= root_temp;
                    end else if (phase == 2'd3) begin
                        // Component counting: mark seen root
                        if (!seen_roots[root_temp]) begin
                            seen_roots[root_temp] <= 1;
                            component_count <= component_count + 1;
                        end
                        i <= i + 1;              // next vertex
                    end
                end
                UNION: begin
                    if (root_a != root_b) begin
                        parent[root_a] <= root_b;
                    end
                end
                CHECK_DONE: begin
                    // no action
                end
                COMPUTE_INIT: begin
                    i <= 0;
                    component_count <= 0;
                    seen_roots <= 0;
                end
                COMPUTE_LOOP: begin
                    if (i < N_reg) begin
                        phase <= 2'd3;          // component counting
                        find_target <= i;
                        find_iter <= 0;
                    end
                end
                COMPUTE_RESULT: begin
                    shift_amount <= (M_reg + component_count) - N_reg;
                    result <= (32'h1 << ((M_reg + component_count) - N_reg));
                    done_reg <= 1;
                    done <= 1;
                end
                DONE: begin
                    // Keep outputs stable
                end
            endcase
        end
    end

endmodule

module profit_maximizer #(
    parameter NUM_PRODUCERS = 4,
    parameter NUM_CONSUMERS = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,

    input wire [7:0] producer_price [0:NUM_PRODUCERS-1],
    input wire [7:0] producer_date [0:NUM_PRODUCERS-1],

    input wire [7:0] consumer_price [0:NUM_CONSUMERS-1],
    input wire [7:0] consumer_date [0:NUM_CONSUMERS-1],

    output reg [15:0] result,
    output reg done
);

// State machine states
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam DONE = 2'b10;

reg [1:0] state;
reg [3:0] i;  // Producer index (supports up to 16 producers)
reg [3:0] j;  // Consumer index (supports up to 16 consumers)
reg [15:0] max_profit;

// Combinational profit calculation
wire [15:0] profit;
wire valid_pair;

// Valid if consumer date > producer date AND consumer price > producer price
assign valid_pair = (consumer_date[j] > producer_date[j]) && 
                    (consumer_price[j] > producer_price[i]);

// Calculate profit: (q - p) * (e - d)
assign profit = valid_pair ? 
                (consumer_price[j] - producer_price[i]) * 
                (consumer_date[j] - producer_date[i]) : 16'd0;

// State register and next state logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 16'd0;
        done <= 1'b0;
        i <= 4'd0;
        j <= 4'd0;
        max_profit <= 16'd0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    state <= COMPUTE;
                    i <= 4'd0;
                    j <= 4'd0;
                    max_profit <= 16'd0;
                end
            end

            COMPUTE: begin
                // Update max profit if current pair is valid and profitable
                if (valid_pair && (profit > max_profit)) begin
                    max_profit <= profit;
                end

                // Next pair
                if (j < NUM_CONSUMERS - 1) begin
                    j <= j + 1;
                end else begin
                    j <= 0;
                    if (i < NUM_PRODUCERS - 1) begin
                        i <= i + 1;
                    end else begin
                        state <= DONE;
                        result <= max_profit;
                    end
                end
            end

            DONE: begin
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module TrafficOptimizer (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] t,          // Segment pass time (4-180)
    input wire [3:0] n,          // Number of cars (1-8)
    input wire [7:0] car_direction, // 1-bit per car: 1=W, 0=E
    input wire [135:0] car_arrival, // 17-bit per car (8 cars)
    input wire [95:0] car_irritation, // 12-bit per car (8 cars)
    output reg [3:0] result,
    output reg done
);

// State encoding
localparam IDLE = 4'd0;
localparam PREPARE = 4'd1;
localparam DP_LOOP = 4'd2;
localparam UPDATE_STATE = 4'd3;
localparam FIND_MIN = 4'd4;
localparam FINISHED = 4'd5;

// DP memory: 9x9x3 = 243 entries
// Each entry: {valid, irritation[3:0], time[15:0]}
reg [20:0] dp [0:242];

// Working registers
reg [3:0] state;
reg [3:0] i, j;           // Processed car counts
reg [1:0] d;              // Last direction: 0=W, 1=E, 2=none
reg [3:0] west_count, east_count;
reg [15:0] west_arrival [0:7];
reg [11:0] west_irritation [0:7];
reg [15:0] east_arrival [0:7];
reg [11:0] east_irritation [0:7];
reg [15:0] current_time;
reg [3:0] current_irr;
reg [15:0] best_time;
reg [3:0] best_irr;
reg [3:0] temp_irr;
reg [15:0] temp_time;
reg [15:0] car_arrival_temp;
reg [11:0] car_irritation_temp;
reg [15:0] release_time;
reg [15:0] waiting;
reg irritation_flag;
reg [2:0] loop_d;

// Helper: index calculation
function [8:0] state_index;
    input [3:0] i_val;
    input [3:0] j_val;
    input [1:0] d_val;
    state_index = {i_val, j_val, d_val};
endfunction

integer idx;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        // Reset DP memory
        for (idx = 0; idx < 243; idx = idx + 1)
            dp[idx] <= 21'b0; // All invalid
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= PREPARE;
                    i <= 0;
                    j <= 0;
                    d <= 0;
                    west_count <= 0;
                    east_count <= 0;
                end
            end

            PREPARE: begin
                // Separate cars into west and east lists
                if (i < n) begin
                    if (car_direction[i]) begin
                        west_arrival[west_count] <= car_arrival[17*i +: 17];
                        west_irritation[west_count] <= car_irritation[12*i +: 12];
                        west_count <= west_count + 1;
                    end else begin
                        east_arrival[east_count] <= car_arrival[17*i +: 17];
                        east_irritation[east_count] <= car_irritation[12*i +: 12];
                        east_count <= east_count + 1;
                    end
                    i <= i + 1;
                end else begin
                    // Initialize DP memory
                    for (idx = 0; idx < 243; idx = idx + 1)
                        dp[idx] <= 21'b0;
                    // Set initial state (0,0,2) to valid with time=0, irr=0
                    dp[state_index(0,0,2)] <= 21'b1_0000_000000000000;
                    i <= 0;
                    j <= 0;
                    d <= 0;
                    state <= DP_LOOP;
                end
            end

            DP_LOOP: begin
                if (i <= west_count && j <= east_count && d < 3) begin
                    // Read current state
                    {current_irr, current_time} <= dp[state_index(i,j,d)][19:0];
                    if (dp[state_index(i,j,d)][20]) begin // Valid
                        state <= UPDATE_STATE;
                        loop_d <= 0; // 0=west, 1=east
                    end else begin
                        // Invalid, go to next d
                        d <= d + 1;
                        if (d == 2) begin
                            if (j == east_count) begin
                                if (i == west_count) state <= FIND_MIN;
                                else begin i <= i + 1; j <= 0; d <= 0; end
                            end else begin
                                j <= j + 1;
                                d <= 0;
                            end
                        end
                    end
                end else if (i > west_count || j > east_count) begin
                    state <= FIND_MIN;
                end else begin
                    state <= FIND_MIN;
                end
            end

            UPDATE_STATE: begin
                case (loop_d)
                    0: begin // Try west car
                        if (i < west_count) begin
                            car_arrival_temp <= west_arrival[i];
                            car_irritation_temp <= west_irritation[i];
                            // Calculate gap
                            if (d == 0) temp_time <= current_time + 16'd3;
                            else if (d == 1) temp_time <= current_time + t;
                            else temp_time <= current_time;
                            // Wait one cycle for multiplication? No, just use max
                            release_time <= (current_time + ((d == 0) ? 16'd3 : (d == 1) ? t : 16'd0)) > west_arrival[i] ? 
                                           (current_time + ((d == 0) ? 16'd3 : (d == 1) ? t : 16'd0)) : west_arrival[i];
                            waiting <= ((current_time + ((d == 0) ? 16'd3 : (d == 1) ? t : 16'd0)) > west_arrival[i] ? 
                                       (current_time + ((d == 0) ? 16'd3 : (d == 1) ? t : 16'd0)) : west_arrival[i]) - west_arrival[i];
                            loop_d <= 1;
                        end else begin
                            loop_d <= 1;
                        end
                    end
                    1: begin // Process west result and try east
                        if (i < west_count) begin
                            irritation_flag <= (waiting > car_irritation_temp);
                            temp_irr <= current_irr + ((waiting > car_irritation_temp) ? 1 : 0);
                            // Update state (i+1, j, 0)
                            // We'll write this in next cycle
                        end
                        if (j < east_count) begin
                            car_arrival_temp <= east_arrival[j];
                            car_irritation_temp <= east_irritation[j];
                            release_time <= (current_time + ((d == 1) ? 16'd3 : (d == 0) ? t : 16'd0)) > east_arrival[j] ? 
                                           (current_time + ((d == 1) ? 16'd3 : (d == 0) ? t : 16'd0)) : east_arrival[j];
                            waiting <= ((current_time + ((d == 1) ? 16'd3 : (d == 0) ? t : 16'd0)) > east_arrival[j] ? 
                                       (current_time + ((d == 1) ? 16'd3 : (d == 0) ? t : 16'd0)) : east_arrival[j]) - east_arrival[j];
                            loop_d <= 2;
                        end else begin
                            loop_d <= 3;
                        end
                    end
                    2: begin // Process east result
                        irritation_flag <= (waiting > car_irritation_temp);
                        // Write both updates (west and east) if valid
                        if (i < west_count) begin
                            // Write west update: state (i+1, j, 0)
                            dp[state_index(i+1, j, 0)] <= 21'b1_0000_000000000000; // Placeholder, will be updated in next cycle
                        end
                        if (j < east_count) begin
                            // Write east update: state (i, j+1, 1)
                            dp[state_index(i, j+1, 1)] <= 21'b1_0000_000000000000; // Placeholder
                        end
                        loop_d <= 3;
                    end
                    3: begin // Move to next state
                        d <= d + 1;
                        if (d == 2) begin
                            if (j == east_count) begin
                                if (i == west_count) state <= FIND_MIN;
                                else begin i <= i + 1; j <= 0; d <= 0; end
                            end else begin
                                j <= j + 1;
                                d <= 0;
                            end
                        end else begin
                            state <= DP_LOOP;
                        end
                    end
                endcase
            end

            FIND_MIN: begin
                // Find minimum irritation among final states
                best_irr <= 8; // Initialize to max
                i <= west_count;
                j <= east_count;
                d <= 0;
                state <= FINISHED;
            end

            FINISHED: begin
                // For d=0,1,2, check dp[i][j][d] and take minimum
                if (d < 3) begin
                    if (dp[state_index(i,j,d)][20]) begin
                        if (dp[state_index(i,j,d)][19:16] < best_irr) begin
                            best_irr <= dp[state_index(i,j,d)][19:16];
                        end
                    end
                    d <= d + 1;
                end else begin
                    result <= best_irr;
                    done <= 1;
                    state <= IDLE;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module gold_scheduler (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] t0, h0, t1, h1, t2, h2, t3, h3,
    input wire [7:0] t4, h4, t5, h5, t6, h6, t7, h7,
    output wire [3:0] result,
    output wire done
);

// This module computes the maximum number of gold stores that can be visited.
// It processes 8 stores, but stores with t=255 and h=0 are considered invalid and never selected.
// Algorithm:
// 1. On start, load the 8 pairs into internal arrays.
// 2. Sort the pairs by h (altitude) in ascending order using bubble sort.
// 3. Iterate over sorted pairs:
//    - Maintain an array selected_t (size 8) of selected t values.
//    - Maintain count of selected stores (0-8).
//    - Maintain total_time (sum of selected t).
//    - For each pair (t, h):
//        * If total_time + t <= h, then add this store:
//            selected_t[count] = t;
//            total_time = total_time + t;
//            count = count + 1;
//        * Else, if count > 0, find the maximum t in selected_t.
//          If max_t > t, then replace that store with this one:
//            total_time = total_time - max_t + t;
//            replace the max_t entry with t.
// 4. After processing all 8 pairs, result = count, and done is asserted.
//
// Timing:
// - Start pulse: assert start for one clock cycle.
// - Sorting takes up to 28 cycles (bubble sort for 8 elements).
// - Selection takes 8 cycles (one per sorted pair).
// - Total cycles <= 40.
// - Done is asserted when computation is complete, and result is valid.
//
// Reset:
// - On rst_n=0, all registers are cleared, done=0, result=0.
//
// Implementation details:
// - Use internal registers t_reg[0:7], h_reg[0:7] to store inputs.
// - Use i and j for bubble sort.
// - Use selected_t[0:7], count, total_time.
// - For max calculation, use combinational logic to find max_t and its index.
//
// Note: The module expects exactly 8 pairs. For fewer valid stores, set unused
//       stores to t=255, h=0 (invalid). These will be sorted first but never selected.
endmodule

