module palindrome_search (
    input clk,
    input rst_n,
    input start,
    input [7:0] char_0, char_1, char_2, char_3, char_4, char_5, char_6, char_7,
    input [7:0] char_8, char_9, char_10, char_11, char_12, char_13, char_14, char_15,
    input [7:0] char_16, char_17, char_18, char_19, char_20, char_21, char_22, char_23,
    input [7:0] char_24, char_25, char_26, char_27, char_28, char_29, char_30, char_31,
    input [7:0] char_32, char_33, char_34, char_35, char_36, char_37, char_38, char_39,
    input [7:0] char_40, char_41, char_42, char_43, char_44, char_45, char_46, char_47,
    input [7:0] char_48, char_49,
    input [5:0] length,
    output reg [5:0] result_start,
    output reg [5:0] result_len,
    output reg done
);

    // State definitions
    localparam IDLE = 3'd0;
    localparam LOAD = 3'd1;
    localparam SEARCH = 3'd2;
    localparam UPDATE = 3'd3;
    localparam FINISH = 3'd4;

    // Internal registers
    reg [2:0] state;
    reg [5:0] i, j, k;
    reg [5:0] best_start_reg, best_len_reg;
    reg [7:0] str_reg [0:49];
    reg [5:0] len_reg;

    // Helper to check if character is 'a' or 'b'
    function is_valid;
        input [7:0] c;
        begin
            is_valid = (c == 8'h61) || (c == 8'h62); // 'a' or 'b'
        end
    endfunction

    // Helper to check if substring [i,j] is a valid palindrome
    function is_palindrome;
        input [5:0] start_idx, end_idx;
        integer l, r;
        reg valid;
        begin
            valid = 1;
            l = start_idx;
            r = end_idx;
            while (l < r && valid) begin
                if (!is_valid(str_reg[l]) || !is_valid(str_reg[r]) || str_reg[l] != str_reg[r]) begin
                    valid = 0;
                end
                l = l + 1;
                r = r - 1;
            end
            is_palindrome = valid;
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result_start <= 0;
            result_len <= 0;
            i <= 0;
            j <= 0;
            k <= 0;
            best_start_reg <= 0;
            best_len_reg <= 0;
            len_reg <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= LOAD;
                        i <= 0;
                    end
                end

                LOAD: begin
                    if (i < 50) begin
                        // Load characters into internal register
                        case (i)
                            0: str_reg[0] <= char_0;
                            1: str_reg[1] <= char_1;
                            2: str_reg[2] <= char_2;
                            3: str_reg[3] <= char_3;
                            4: str_reg[4] <= char_4;
                            5: str_reg[5] <= char_5;
                            6: str_reg[6] <= char_6;
                            7: str_reg[7] <= char_7;
                            8: str_reg[8] <= char_8;
                            9: str_reg[9] <= char_9;
                            10: str_reg[10] <= char_10;
                            11: str_reg[11] <= char_11;
                            12: str_reg[12] <= char_12;
                            13: str_reg[13] <= char_13;
                            14: str_reg[14] <= char_14;
                            15: str_reg[15] <= char_15;
                            16: str_reg[16] <= char_16;
                            17: str_reg[17] <= char_17;
                            18: str_reg[18] <= char_18;
                            19: str_reg[19] <= char_19;
                            20: str_reg[20] <= char_20;
                            21: str_reg[21] <= char_21;
                            22: str_reg[22] <= char_22;
                            23: str_reg[23] <= char_23;
                            24: str_reg[24] <= char_24;
                            25: str_reg[25] <= char_25;
                            26: str_reg[26] <= char_26;
                            27: str_reg[27] <= char_27;
                            28: str_reg[28] <= char_28;
                            29: str_reg[29] <= char_29;
                            30: str_reg[30] <= char_30;
                            31: str_reg[31] <= char_31;
                            32: str_reg[32] <= char_32;
                            33: str_reg[33] <= char_33;
                            34: str_reg[34] <= char_34;
                            35: str_reg[35] <= char_35;
                            36: str_reg[36] <= char_36;
                            37: str_reg[37] <= char_37;
                            38: str_reg[38] <= char_38;
                            39: str_reg[39] <= char_39;
                            40: str_reg[40] <= char_40;
                            41: str_reg[41] <= char_41;
                            42: str_reg[42] <= char_42;
                            43: str_reg[43] <= char_43;
                            44: str_reg[44] <= char_44;
                            45: str_reg[45] <= char_45;
                            46: str_reg[46] <= char_46;
                            47: str_reg[47] <= char_47;
                            48: str_reg[48] <= char_48;
                            49: str_reg[49] <= char_49;
                        endcase
                        i <= i + 1;
                    end else begin
                        len_reg <= length;
                        i <= 0;
                        j <= 0;
                        best_start_reg <= 0;
                        best_len_reg <= 0;
                        state <= SEARCH;
                    end
                end

                SEARCH: begin
                    if (i < len_reg) begin
                        if (j < len_reg) begin
                            // Check if substring [i,j] is valid palindrome
                            if (is_palindrome(i, j)) begin
                                if ((j - i + 1) > best_len_reg) begin
                                    best_start_reg <= i;
                                    best_len_reg <= j - i + 1;
                                end
                            end
                            j <= j + 1;
                        end else begin
                            j <= i;
                            i <= i + 1;
                        end
                    end else begin
                        state <= UPDATE;
                    end
                end

                UPDATE: begin
                    result_start <= best_start_reg;
                    result_len <= best_len_reg;
                    done <= 1;
                    state <= FINISH;
                end

                FINISH: begin
                    done <= 0;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module shortest_path (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] s,
    input wire [2:0] t,
    input wire [7:0] adj_0,
    input wire [7:0] adj_1,
    input wire [7:0] adj_2,
    input wire [7:0] adj_3,
    input wire [7:0] adj_4,
    input wire [7:0] adj_5,
    input wire [7:0] adj_6,
    input wire [7:0] adj_7,
    output reg [3:0] result,
    output reg done,
    output reg impossible
);
    // Parameters
    parameter N_NODES = 8;
    parameter MAX_CYCLES = 1000;

    // State encoding
    localparam IDLE = 2'b00;
    localparam INIT = 2'b01;
    localparam LOOP = 2'b10;
    localparam FINISH = 2'b11;

    // Registers
    reg [1:0] state;
    reg [1:0] next_state;
    reg [3:0] dist_reg;
    reg [3:0] next_dist;
    reg [7:0] visited;
    reg [7:0] next_visited;
    reg [2:0] queue [0:7]; // FIFO for BFS
    reg [2:0] queue_head;
    reg [2:0] queue_tail;
    reg [2:0] next_queue_head;
    reg [2:0] next_queue_tail;
    reg [3:0] cycle_count;
    reg [3:0] next_cycle_count;

    // Wires for adjacency matrix
    wire [7:0] adj [0:7];
    assign adj[0] = adj_0;
    assign adj[1] = adj_1;
    assign adj[2] = adj_2;
    assign adj[3] = adj_3;
    assign adj[4] = adj_4;
    assign adj[5] = adj_5;
    assign adj[6] = adj_6;
    assign adj[7] = adj_7;

    // Current node in queue
    wire [2:0] current_node = queue[queue_head];

    // Next state logic
    always @(*) begin
        next_state = state;
        next_dist = dist_reg;
        next_visited = visited;
        next_queue_head = queue_head;
        next_queue_tail = queue_tail;
        next_cycle_count = cycle_count + 1;

        case (state)
            IDLE: begin
                if (start) begin
                    next_state = INIT;
                    next_cycle_count = 0;
                end
            end

            INIT: begin
                // Initialize queue with start node
                queue[0] = s;
                next_queue_head = 0;
                next_queue_tail = 1;
                next_visited = (1'b1 << s);
                next_dist = 0;

                if (s == t) begin
                    next_state = FINISH;
                end else begin
                    next_state = LOOP;
                end
            end

            LOOP: begin
                if (queue_head == queue_tail || cycle_count >= MAX_CYCLES) begin
                    // Queue empty or timeout - no path
                    next_state = FINISH;
                end else begin
                    // Process current node
                    if (current_node == t) begin
                        next_state = FINISH;
                    end else begin
                        // Add unvisited neighbors to queue
                        if (queue_head < 7) begin
                            next_queue_head = queue_head + 1;
                        end

                        // Check all possible neighbors
                        // This is combinational but will be registered
                        for (integer i = 0; i < 8; i = i + 1) begin
                            if (adj[current_node][i] && !visited[i]) begin
                                if (next_queue_tail < 8) begin
                                    queue[next_queue_tail] = i;
                                    next_queue_tail = next_queue_tail + 1;
                                    next_visited[i] = 1'b1;
                                end
                            end
                        end

                        next_dist = dist_reg + 1;
                    end
                end
            end

            FINISH: begin
                // Hold state
                next_state = FINISH;
            end
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            dist_reg <= 0;
            visited <= 0;
            queue_head <= 0;
            queue_tail <= 0;
            cycle_count <= 0;
            result <= 0;
            done <= 0;
            impossible <= 0;
        end else begin
            state <= next_state;
            dist_reg <= next_dist;
            visited <= next_visited;
            queue_head <= next_queue_head;
            queue_tail <= next_queue_tail;
            cycle_count <= next_cycle_count;

            if (state == FINISH) begin
                done <= 1'b1;
                if (queue_head == queue_tail) begin
                    impossible <= 1'b1;
                    result <= 0;
                end else begin
                    impossible <= 1'b0;
                    result <= dist_reg;
                end
            end else begin
                done <= 1'b0;
                impossible <= 1'b0;
            end
        end
    end
endmodule

module stan_eater (
    input clk,
    input rst_n,
    input start,
    input [7:0] course_0, course_1, course_2, course_3,
                 course_4, course_5, course_6, course_7,
    input [7:0] m,
    output reg [15:0] result,
    output reg done
);

// State machine definitions
localparam IDLE = 4'd0;
localparam INIT_DP = 4'd1;
localparam INIT_COPY = 4'd2;
localparam COMPUTE_R = 4'd3;
localparam COMPUTE_S = 4'd4;
localparam NEXT_S = 4'd5;
localparam NEXT_R = 4'd6;
localparam NEXT_I_1 = 4'd7;
localparam COPY = 4'd8;
localparam NEXT_I_2 = 4'd9;
localparam DONE = 4'd10;

reg [3:0] state;
reg [3:0] i;          // Current course index (7 down to 0)
reg [7:0] r;          // Current rate
reg [1:0] s;          // Skip count (0,1,2)
reg [8:0] copy_index; // 0 to 386 for 129*3 array

// DP arrays - double bufferingeg [15:0] dp_next [0:128][0:2];   // Next state values
reg [15:0] dp_current [0:128][0:2]; // Current state values

// Course storage
reg [7:0] course_reg [0:7];

// Computation registers
reg [7:0] current_rate;
reg [15:0] calories;
reg [7:0] next_r;
reg [1:0] next_s;
reg [15:0] value1, value2;
reg [15:0] max_value;

// Helper variables
reg [8:0] r_copy, s_copy;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        r <= 0;
        s <= 0;
        copy_index <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Load courses into registers
                    course_reg[0] <= course_0;
                    course_reg[1] <= course_1;
                    course_reg[2] <= course_2;
                    course_reg[3] <= course_3;
                    course_reg[4] <= course_4;
                    course_reg[5] <= course_5;
                    course_reg[6] <= course_6;
                    course_reg[7] <= course_7;
                    state <= INIT_DP;
                end
            end

            INIT_DP: begin
                i <= 7;  // Start from last course
                copy_index <= 0;
                state <= INIT_COPY;
            end

            INIT_COPY: begin
                // Initialize dp_next to zero
                r_copy <= copy_index / 3;
                s_copy <= copy_index % 3;
                dp_next[copy_index / 3][copy_index % 3] <= 0;
                if (copy_index < 9'd386) begin
                    copy_index <= copy_index + 1;
                end else begin
                    state <= COMPUTE_R;
                end
            end

            COMPUTE_R: begin
                if (r > 8'd128) begin
                    state <= NEXT_I_1;
                end else begin
                    s <= 0;
                    state <= COMPUTE_S;
                end
            end

            COMPUTE_S: begin
                if (s > 2) begin
                    state <= NEXT_R;
                end else if (s == 2 && r != m) begin
                    dp_current[r][s] <= 0;
                    state <= NEXT_S;
                end else begin
                    // Determine current rate
                    current_rate = (s == 2) ? m : r;

                    // Eat option
                    if (current_rate < course_reg[i])
                        calories = current_rate;
                    else
                        calories = course_reg[i];
                    next_r = (current_rate * 2) / 3;
                    next_s = 0;
                    value1 = calories + dp_next[next_r][next_s];

                    // Skip option
                    if (s < 2) begin
                        next_s = s + 1;
                        next_r = current_rate;
                    end else begin
                        next_s = 2;
                        next_r = m;
                    end
                    value2 = dp_next[next_r][next_s];

                    // Max of eat vs skip
                    if (value1 > value2)
                        max_value = value1;
                    else
                        max_value = value2;

                    dp_current[r][s] <= max_value;
                    state <= NEXT_S;
                end
            end

            NEXT_S: begin
                s <= s + 1;
                state <= COMPUTE_S;
            end

            NEXT_R: begin
                r <= r + 1;
                state <= COMPUTE_R;
            end

            NEXT_I_1: begin
                copy_index <= 0;
                state <= COPY;
            end

            COPY: begin
                r_copy <= copy_index / 3;
                s_copy <= copy_index % 3;
                dp_next[copy_index / 3][copy_index % 3] <= dp_current[copy_index / 3][copy_index % 3];
                if (copy_index < 9'd386) begin
                    copy_index <= copy_index + 1;
                end else begin
                    state <= NEXT_I_2;
                end
            end

            NEXT_I_2: begin
                i <= i - 1;
                if (i == 0) begin  // i was 1, now becomes 0, then next will be -1
                    state <= DONE;
                end else begin
                    r <= 0;
                    s <= 0;
                    state <= COMPUTE_S;
                end
            end

            DONE: begin
                result <= dp_next[m][0];
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module UW_Distance_Optimizer (
    input clk,
    input rst_n,
    input start,
    input [7:0] gravity_in [0:7],
    input [7:0] connections_in [0:7],
    input human_mask [0:7],
    input alien_mask [0:7],
    output reg [15:0] min_distance,
    output reg done
);

// Parameters
parameter MAX_NODES = 8;
parameter MAX_EDGES = 16;

// State definitions
parameter IDLE = 4'b0000;
parameter READ_GRAPH = 4'b0001;
parameter FIND_PATHS = 4'b0010;
parameter CALCULATE_DISTANCE = 4'b0011;
parameter APPLY_DEVICE = 4'b0100;
parameter UPDATE_MIN = 4'b0101;
parameter COMPLETE = 4'b0110;

// Internal registers
reg [3:0] current_state, next_state;
reg [3:0] node_count;
reg [3:0] current_node, next_node;
reg [3:0] path_nodes [0:7]; // Store path nodes
reg [3:0] path_length;
reg [2:0] device_node; // Node where device is placed (0-7)
reg [15:0] current_distance;
reg [15:0] best_distance;
reg [2:0] search_depth;

// Adjacency matrix (8x8, stored as 64-bit for efficiency)
reg [63:0] adjacency;

// UW Distance Calculation Registers
reg signed [15:0] gravity_seq [0:7];
reg signed [15:0] cap_seq [0:6];
reg signed [15:0] pot_seq [0:6];
reg signed [15:0] ind_seq [0:6];
reg signed [31:0] intermediate [0:6];
reg signed [31:0] total_sum;
reg [3:0] calc_step;

// Device effect registers
reg signed [15:0] modified_gravity [0:7];
reg [2:0] affected_nodes [0:7];
reg [2:0] affected_count;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= IDLE;
        min_distance <= 16'hFFFF;
        done <= 0;
    end else begin
        current_state <= next_state;
        case (current_state)
            IDLE: begin
                if (start) begin
                    node_count <= 0;
                    best_distance <= 16'hFFFF;
                    device_node <= 0;
                    done <= 0;
                end
            end

            READ_GRAPH: begin
                // Read gravity values and build adjacency matrix
                if (node_count < MAX_NODES) begin
                    // Store gravity values (simplified)
                    modified_gravity[node_count] <= {8'd0, gravity_in[node_count]};
                    node_count <= node_count + 1;
                end
            end

            FIND_PATHS: begin
                // Simplified: find all human-alien pairs
                // In hardware, this would use BFS/DFS state machine
                if (current_node < MAX_NODES) begin
                    if (human_mask[current_node]) begin
                        // Start search for alien nodes
                        search_depth <= 0;
                        path_nodes[0] <= current_node;
                        path_length <= 1;
                    end
                    current_node <= current_node + 1;
                end
            end

            CALCULATE_DISTANCE: begin
                // Calculate UW distance for current path
                case (calc_step)
                    0: begin
                        // Calculate sequences
                        for (integer i = 0; i < path_length - 1; i = i + 1) begin
                            cap_seq[i] <= modified_gravity[path_nodes[i+1]] + modified_gravity[path_nodes[i]];
                            pot_seq[i] <= modified_gravity[path_nodes[i+1]] - modified_gravity[path_nodes[i]];
                            ind_seq[i] <= modified_gravity[path_nodes[i+1]] * modified_gravity[path_nodes[i]];
                        end
                        calc_step <= 1;
                    end
                    1: begin
                        // Calculate pot * (cap^2 - ind)
                        for (integer i = 0; i < path_length - 1; i = i + 1) begin
                            intermediate[i] <= pot_seq[i] * ((cap_seq[i] * cap_seq[i]) - ind_seq[i]);
                        end
                        calc_step <= 2;
                    end
                    2: begin
                        // Sum intermediate values
                        total_sum <= 0;
                        for (integer i = 0; i < path_length - 1; i = i + 1) begin
                            total_sum <= total_sum + intermediate[i];
                        end
                        calc_step <= 3;
                    end
                    3: begin
                        // Take absolute value
                        current_distance <= (total_sum[31]) ? -total_sum[15:0] : total_sum[15:0];
                        calc_step <= 0;
                    end
                endcase
            end

            APPLY_DEVICE: begin
                // Apply gravity dispersal device effects
                // Device at device_node: -1 to that node, +1 to all neighbors
                modified_gravity[device_node] <= modified_gravity[device_node] - 1;
                // Apply to neighbors (simplified)
                if (device_node > 0) modified_gravity[device_node-1] <= modified_gravity[device_node-1] + 1;
                if (device_node < 7) modified_gravity[device_node+1] <= modified_gravity[device_node+1] + 1;
            end

            UPDATE_MIN: begin
                if (current_distance < best_distance) begin
                    best_distance <= current_distance;
                end
                // Try next device position
                if (device_node < 7) begin
                    device_node <= device_node + 1;
                    // Reset modified_gravity to original values
                    for (integer i = 0; i < MAX_NODES; i = i + 1) begin
                        modified_gravity[i] <= {8'd0, gravity_in[i]};
                    end
                end
            end

            COMPLETE: begin
                min_distance <= best_distance;
                done <= 1;
            end
        endcase
    end
end

// State transition logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        IDLE: if (start) next_state = READ_GRAPH;
        READ_GRAPH: if (node_count >= MAX_NODES) next_state = FIND_PATHS;
        FIND_PATHS: if (current_node >= MAX_NODES) next_state = APPLY_DEVICE;
        APPLY_DEVICE: next_state = CALCULATE_DISTANCE;
        CALCULATE_DISTANCE: if (calc_step == 3) next_state = UPDATE_MIN;
        UPDATE_MIN: begin
            if (device_node < 7) next_state = APPLY_DEVICE;
            else next_state = COMPLETE;
        end
        COMPLETE: next_state = IDLE;
    endcase
end

endmodule

module EagletonTallest (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] N,
    input wire signed [31:0] k,
    input wire signed [31:0] h0,
    input wire signed [31:0] h1,
    input wire signed [31:0] h2,
    input wire signed [31:0] h3,
    output reg signed [31:0] result,
    output reg done
);

// Fixed-point Q16.16
// Arithmetic shift right by 1 for division by 2
function signed [31:0] div2;
    input signed [31:0] x;
    begin
        div2 = {x[31], x[31:1]};
    end
endfunction

// State encoding
localparam IDLE = 0;
localparam START_SCAN = 1;
localparam CHECK_HOUSE = 2;
localparam UPDATE_HOUSE = 3;
localparam NEXT_HOUSE = 4;
localparam SCAN_DONE = 5;
localparam MAX_COMPUTE = 6;
localparam OUTPUT = 7;

reg [3:0] state;
reg [3:0] i;                     // 0-indexed house counter
reg signed [31:0] heights [0:3]; // Current heights
reg changed;                     // Update flag
reg [9:0] iteration_counter;     // Max 1000 scans
reg signed [31:0] left, right, target;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        changed <= 0;
        iteration_counter <= 0;
        heights[0] <= 0;
        heights[1] <= 0;
        heights[2] <= 0;
        heights[3] <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Load initial heights
                    if (N >= 1) heights[0] <= h0;
                    if (N >= 2) heights[1] <= h1;
                    if (N >= 3) heights[2] <= h2;
                    if (N >= 4) heights[3] <= h3;
                    i <= 0;
                    changed <= 0;
                    iteration_counter <= 0;
                    state <= START_SCAN;
                end
            end

            START_SCAN: begin
                i <= 0;
                changed <= 0;
                state <= CHECK_HOUSE;
            end

            CHECK_HOUSE: begin
                // Determine left and right neighbors
                left = (i == 0) ? 32'sd0 : heights[i-1];
                right = (i == N-1) ? 32'sd0 : heights[i+1];
                target <= div2(left + right) + k;
                state <= UPDATE_HOUSE;
            end

            UPDATE_HOUSE: begin
                if (heights[i] < target) begin
                    heights[i] <= target;
                    changed <= 1;
                end
                state <= NEXT_HOUSE;
            end

            NEXT_HOUSE: begin
                if (i < N-1) begin
                    i <= i + 1;
                    state <= CHECK_HOUSE;
                end else begin
                    state <= SCAN_DONE;
                end
            end

            SCAN_DONE: begin
                if (changed) begin
                    iteration_counter <= iteration_counter + 1;
                    if (iteration_counter < 1000) begin
                        state <= START_SCAN;
                    end else begin
                        state <= MAX_COMPUTE; // Timeout
                    end
                end else begin
                    state <= MAX_COMPUTE; // Converged
                end
            end

            MAX_COMPUTE: begin
                // Find maximum height
                result <= heights[0];
                if (N > 1 && heights[1] > result) result <= heights[1];
                if (N > 2 && heights[2] > result) result <= heights[2];
                if (N > 3 && heights[3] > result) result <= heights[3];
                state <= OUTPUT;
            end

            OUTPUT: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

