module BalancedParentheses #(
    parameter N = 4,               // Number of pieces (max 4)
    parameter MAX_BALANCE = 16,    // Maximum balance (sum of positive gains)
    parameter DATA_WIDTH = 8,      // Width for result and length
    parameter TOTAL_WIDTH = 4,     // Width for total balance (signed)
    parameter MIN_WIDTH = 4,       // Width for min_prefix (signed)
    parameter LEN_WIDTH = 3        // Width for piece length
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] num_pieces,   // Number of valid pieces (1-4)

    // Piece properties (sorted optimally: first positive pieces by need ascending,
    // then negative pieces by (need - gain) ascending)
    input wire [TOTAL_WIDTH-1:0] piece_total_0,
    input wire [TOTAL_WIDTH-1:0] piece_total_1,
    input wire [TOTAL_WIDTH-1:0] piece_total_2,
    input wire [TOTAL_WIDTH-1:0] piece_total_3,

    input wire [MIN_WIDTH-1:0] piece_min_prefix_0,
    input wire [MIN_WIDTH-1:0] piece_min_prefix_1,
    input wire [MIN_WIDTH-1:0] piece_min_prefix_2,
    input wire [MIN_WIDTH-1:0] piece_min_prefix_3,

    input wire [LEN_WIDTH-1:0] piece_length_0,
    input wire [LEN_WIDTH-1:0] piece_length_1,
    input wire [LEN_WIDTH-1:0] piece_length_2,
    input wire [LEN_WIDTH-1:0] piece_length_3,

    output reg [DATA_WIDTH-1:0] result,
    output reg done
);

// State definitions
localparam S_IDLE = 3'b000;
localparam S_INIT = 3'b001;
localparam S_SET_PIECE = 3'b010;
localparam S_DECIDE_ORDER = 3'b011;
localparam S_UPDATE_LOOP = 3'b100;
localparam S_NEXT_PIECE = 3'b101;
localparam S_FINISH = 3'b110;

reg [2:0] state, next_state;
reg [DATA_WIDTH-1:0] dp [0:MAX_BALANCE]; // DP table, index = balance
reg [DATA_WIDTH-1:0] dp_next [0:MAX_BALANCE];
reg [2:0] piece_idx; // current piece index (0 to 3)
reg [TOTAL_WIDTH-1:0] cur_total;
reg [MIN_WIDTH-1:0] cur_min_prefix;
reg [LEN_WIDTH-1:0] cur_length;
reg signed [TOTAL_WIDTH:0] need; // need = -min_prefix, positive
reg signed [TOTAL_WIDTH:0] gain; // gain = total
reg [MAX_BALANCE:0] bal; // current balance during loop
reg loop_dir; // 0: decrement, 1: increment
reg [MAX_BALANCE:0] loop_start, loop_end;
wire [MAX_BALANCE:0] new_bal;

// Helper: compute need and gain
always @(*) begin
    need = -cur_min_prefix; // cur_min_prefix is signed, so - is positive
    gain = cur_total;
end

// New balance calculation
assign new_bal = bal + gain;

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        S_IDLE: if (start) next_state = S_INIT;
        S_INIT: next_state = S_SET_PIECE;
        S_SET_PIECE: next_state = S_DECIDE_ORDER;
        S_DECIDE_ORDER: next_state = S_UPDATE_LOOP;
        S_UPDATE_LOOP: begin
            // If loop finished, go to NEXT_PIECE
            if (loop_dir) begin
                if (bal >= loop_end) next_state = S_NEXT_PIECE;
                else next_state = S_UPDATE_LOOP;
            end else begin
                if (bal <= loop_end) next_state = S_NEXT_PIECE;
                else next_state = S_UPDATE_LOOP;
            end
        end
        S_NEXT_PIECE: begin
            if (piece_idx + 1 < num_pieces) next_state = S_SET_PIECE;
            else next_state = S_FINISH;
        end
        S_FINISH: next_state = S_IDLE;
        default: next_state = S_IDLE;
    endcase
end

// DP update logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset DP table
        for (integer i = 0; i <= MAX_BALANCE; i = i + 1) begin
            dp[i] <= {DATA_WIDTH{1'b1}}; // invalid value
        end
        dp[0] <= 0; // balance 0, length 0
        result <= 0;
        done <= 0;
        piece_idx <= 0;
        cur_total <= 0;
        cur_min_prefix <= 0;
        cur_length <= 0;
        bal <= 0;
        loop_start <= 0;
        loop_end <= 0;
        loop_dir <= 0;
    end else begin
        case (state)
            S_INIT: begin
                // Reset DP table
                for (integer i = 0; i <= MAX_BALANCE; i = i + 1) begin
                    dp[i] <= {DATA_WIDTH{1'b1}};
                end
                dp[0] <= 0;
                piece_idx <= 0;
                done <= 0;
            end

            S_SET_PIECE: begin
                // Load current piece properties
                case (piece_idx)
                    0: begin
                        cur_total <= piece_total_0;
                        cur_min_prefix <= piece_min_prefix_0;
                        cur_length <= piece_length_0;
                    end
                    1: begin
                        cur_total <= piece_total_1;
                        cur_min_prefix <= piece_min_prefix_1;
                        cur_length <= piece_length_1;
                    end
                    2: begin
                        cur_total <= piece_total_2;
                        cur_min_prefix <= piece_min_prefix_2;
                        cur_length <= piece_length_2;
                    end
                    3: begin
                        cur_total <= piece_total_3;
                        cur_min_prefix <= piece_min_prefix_3;
                        cur_length <= piece_length_3;
                    end
                endcase
            end

            S_DECIDE_ORDER: begin
                // Determine loop direction based on gain sign
                if (gain >= 0) begin
                    loop_dir <= 0; // decrement
                    loop_start <= MAX_BALANCE;
                    loop_end <= need;
                end else begin
                    loop_dir <= 1; // increment
                    loop_start <= need;
                    loop_end <= MAX_BALANCE;
                end
                bal <= loop_start;
            end

            S_UPDATE_LOOP: begin
                // For current balance bal, if dp[bal] is valid and bal >= need, update dp[new_bal]
                if (dp[bal] != {DATA_WIDTH{1'b1}} && bal >= need) begin
                    if (new_bal >= 0 && new_bal <= MAX_BALANCE) begin
                        if (dp[bal] + cur_length > dp[new_bal]) begin
                            dp[new_bal] <= dp[bal] + cur_length;
                        end
                    end
                end
                // Update bal for next iteration
                if (loop_dir) begin
                    bal <= bal + 1;
                end else begin
                    bal <= bal - 1;
                end
            end

            S_NEXT_PIECE: begin
                piece_idx <= piece_idx + 1;
            end

            S_FINISH: begin
                result <= dp[0];
                done <= 1;
            end
        endcase
    end
end

endmodule

module triple_correlation #(
    parameter P_MAX = 20,
    parameter N_MAX = 3,
    parameter M_MAX = 3
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] p,
    input wire [3:0] seq [0:P_MAX-1],
    output reg found,
    output reg [3:0] a_out,
    output reg [3:0] b_out,
    output reg [3:0] c_out,
    output reg [7:0] n_out,
    output reg [7:0] m_out,
    output reg done
);

    // Internal registers
    reg [3:0] seq_reg [0:P_MAX-1];
    reg [7:0] p_reg;
    reg [7:0] T;
    reg [7:0] n_reg, m_reg;
    reg [3:0] a_reg, b_reg, c_reg;
    reg [7:0] i;
    reg [7:0] triple_count;
    reg [7:0] first_i;
    reg candidate_valid;
    reg [3:0] best_a, best_b, best_c;
    reg [7:0] best_n, best_m, best_first_i;

    // State definition
    localparam IDLE = 0;
    localparam LOAD = 1;
    localparam SEARCH = 2;
    localparam SCANNING = 3;
    localparam EVALUATE = 4;
    localparam NEXT_C = 5;
    localparam NEXT_B = 6;
    localparam NEXT_A = 7;
    localparam NEXT_M = 8;
    localparam NEXT_N = 9;
    localparam DONE = 10;
    reg [3:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            found <= 0;
            // Other registers reset if needed
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    // Load sequence from inputs
                    for (integer idx = 0; idx < P_MAX; idx = idx + 1) begin
                        seq_reg[idx] <= seq[idx];
                    end
                    p_reg <= p;
                    T <= (p + 39) / 40 + 1;  // ceil(p/40)+1
                    best_first_i <= P_MAX + 1;
                    found <= 0;
                    state <= SEARCH;
                end
                SEARCH: begin
                    n_reg <= 1;
                    m_reg <= 1;
                    a_reg <= 0;
                    b_reg <= 0;
                    c_reg <= 0;
                    state <= SCANNING;
                    i <= 0;
                    triple_count <= 0;
                    first_i <= P_MAX + 1;
                    candidate_valid <= 1;
                end
                SCANNING: begin
                    if (i < p_reg) begin
                        // Check correlation conditions and triple occurrence
                        if ( (
                             (seq_reg[i] == a_reg && i + n_reg < p_reg && seq_reg[i + n_reg] == b_reg && i + n_reg + m_reg < p_reg && seq_reg[i + n_reg + m_reg] != c_reg) ||
                             (seq_reg[i] == b_reg && i + m_reg < p_reg && seq_reg[i + m_reg] == c_reg && i >= n_reg && seq_reg[i - n_reg] != a_reg) ||
                             (seq_reg[i] == a_reg && i + n_reg + m_reg < p_reg && seq_reg[i + n_reg + m_reg] == c_reg && i + n_reg < p_reg && seq_reg[i + n_reg] != b_reg)
                           ) ) begin
                            candidate_valid <= 0;
                            state <= NEXT_C;
                        end else begin
                            // Count triple occurrences
                            if (i + n_reg < p_reg && i + n_reg + m_reg < p_reg &&
                                seq_reg[i] == a_reg && seq_reg[i + n_reg] == b_reg && seq_reg[i + n_reg + m_reg] == c_reg) begin
                                triple_count <= triple_count + 1;
                                if (first_i > P_MAX) first_i <= i;
                            end
                            i <= i + 1;
                            if (i + 1 < p_reg) begin
                                state <= SCANNING;
                            end else begin
                                state <= EVALUATE;
                            end
                        end
                    end else begin
                        state <= EVALUATE;
                    end
                end
                EVALUATE: begin
                    if (candidate_valid && triple_count >= T) begin
                        if (first_i < best_first_i ||
                            (first_i == best_first_i && n_reg < best_n) ||
                            (first_i == best_first_i && n_reg == best_n && m_reg < best_m)) begin
                            best_a <= a_reg;
                            best_b <= b_reg;
                            best_c <= c_reg;
                            best_n <= n_reg;
                            best_m <= m_reg;
                            best_first_i <= first_i;
                        end
                    end
                    state <= NEXT_C;
                end
                NEXT_C: begin
                    if (c_reg == 9) begin
                        state <= NEXT_B;
                    end else begin
                        c_reg <= c_reg + 1;
                        state <= SCANNING;
                        i <= 0;
                        triple_count <= 0;
                        first_i <= P_MAX + 1;
                        candidate_valid <= 1;
                    end
                end
                NEXT_B: begin
                    if (b_reg == 9) begin
                        state <= NEXT_A;
                    end else begin
                        b_reg <= b_reg + 1;
                        c_reg <= 0;
                        state <= SCANNING;
                        i <= 0;
                        triple_count <= 0;
                        first_i <= P_MAX + 1;
                        candidate_valid <= 1;
                    end
                end
                NEXT_A: begin
                    if (a_reg == 9) begin
                        state <= NEXT_M;
                    end else begin
                        a_reg <= a_reg + 1;
                        b_reg <= 0;
                        c_reg <= 0;
                        state <= SCANNING;
                        i <= 0;
                        triple_count <= 0;
                        first_i <= P_MAX + 1;
                        candidate_valid <= 1;
                    end
                end
                NEXT_M: begin
                    if (m_reg == M_MAX) begin
                        state <= NEXT_N;
                    end else begin
                        m_reg <= m_reg + 1;
                        a_reg <= 0;
                        b_reg <= 0;
                        c_reg <= 0;
                        state <= SCANNING;
                        i <= 0;
                        triple_count <= 0;
                        first_i <= P_MAX + 1;
                        candidate_valid <= 1;
                    end
                end
                NEXT_N: begin
                    if (n_reg == N_MAX) begin
                        state <= DONE;
                    end else begin
                        n_reg <= n_reg + 1;
                        m_reg <= 1;
                        a_reg <= 0;
                        b_reg <= 0;
                        c_reg <= 0;
                        state <= SCANNING;
                        i <= 0;
                        triple_count <= 0;
                        first_i <= P_MAX + 1;
                        candidate_valid <= 1;
                    end
                end
                DONE: begin
                    done <= 1;
                    if (best_first_i <= P_MAX) begin
                        found <= 1;
                        a_out <= best_a;
                        b_out <= best_b;
                        c_out <= best_c;
                        n_out <= best_n;
                        m_out <= best_m;
                    end else begin
                        found <= 0;
                    end
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

module nudgemon_go (
    input clk,
    input rst_n,
    input start,
    // Family definitions: 4 families max, each with up to 4 kinds
    input [3:0] family_sizes,  // 4 bits per family: s_i
    input [31:0] evolution_costs,  // 4 families * 8-bit costs packed
    input [31:0] catch_times,  // 4 catches * 8-bit times
    input [15:0] catch_names,  // 4 catches * 4-bit family+type indices
    output reg [15:0] max_xp,
    output reg done
);
    // Internal parameters
    parameter NUM_FAMILIES = 4;
    parameter MAX_KINDS_PER_FAMILY = 4;
    parameter MAX_CATCHES = 16;
    parameter WINDOW_DURATION = 16;

    // State machine states
    localparam IDLE = 0;
    localparam PARSE_FAMILIES = 1;
    localparam PARSE_CATCHES = 2;
    localparam COMPUTE_EVOLUTIONS = 3;
    localparam FIND_OPTIMAL_WINDOW = 4;
    localparam OUTPUT_RESULT = 5;

    reg [2:0] state;
    reg [7:0] timer;
    reg [7:0] best_start_time;
    reg [15:0] best_xp;

    // Memory for family data
    reg [7:0] family_kinds [0:3];  // Number of kinds per family
    reg [7:0] costs [0:15];  // Evolution costs for all families
    reg [7:0] catch_time_list [0:15];  // Catch times
    reg [3:0] catch_family [0:15];  // Which family for each catch
    reg [3:0] catch_type [0:15];  // Type within family

    // Candy counters and Nudgémon counts
    reg [7:0] candy [0:3];  // Candy per family
    reg [7:0] mon_counts [0:15];  // Count of each Nudgémon kind

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            max_xp <= 0;
            timer <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= PARSE_FAMILIES;
                        timer <= 0;
                    end
                end

                PARSE_FAMILIES: begin
                    // Extract family sizes and costs from inputs
