module bandwidth_allocator (
  input clk, rst_n, start,
  input [31:0] a0, a1, a2, a3,
  input [31:0] b0, b1, b2, b3,
  input [31:0] d0, d1, d2, d3,
  input [31:0] t,
  output reg [31:0] x0, x1, x2, x3,
  output reg done
);

// State encoding
localparam IDLE = 0;
localparam COMPUTE_TOTAL_D = 1;
localparam COMPUTE_Y = 2;
localparam INIT_X = 3;
localparam CHECK_ITERATION = 4;
localparam COMPUTE_RESIDUAL = 5;
localparam COMPUTE_TOTAL_Y_FREE = 6;
localparam UPDATE_X = 7;
localparam DONE = 8;

reg [3:0] state;
reg [1:0] index; // 0 to 3
reg [31:0] total_d;
reg [31:0] y [0:3];
reg [31:0] x [0:3];
reg [3:0] fixed; // one bit per species
reg [31:0] residual;
reg [31:0] total_y_free;
reg changed;

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state <= IDLE;
    done <= 0;
    fixed <= 0;
    changed <= 0;
    index <= 0;
    total_d <= 0;
    residual <= 0;
    total_y_free <= 0;
    x0 <= 0; x1 <= 0; x2 <= 0; x3 <= 0;
  end else begin
    case (state)
      IDLE: 
        if (start) begin
          state <= COMPUTE_TOTAL_D;
          index <= 0;
          total_d <= 0;
        end

      COMPUTE_TOTAL_D:
        begin
          case (index)
            0: total_d <= total_d + d0;
            1: total_d <= total_d + d1;
            2: total_d <= total_d + d2;
            3: total_d <= total_d + d3;
          endcase
          index <= index + 1;
          if (index == 3) begin
            state <= COMPUTE_Y;
            index <= 0;
          end
        end

      COMPUTE_Y:
        begin
          case (index)
            0: y[0] <= (t * d0) / total_d;
            1: y[1] <= (t * d1) / total_d;
            2: y[2] <= (t * d2) / total_d;
            3: y[3] <= (t * d3) / total_d;
          endcase
          index <= index + 1;
          if (index == 3) begin
            state <= INIT_X;
            index <= 0;
          end
        end

      INIT_X:
        begin
          case (index)
            0: begin
                 x[0] <= y[0];
                 if (y[0] < a0) begin
                   x[0] <= a0;
                   fixed[0] <= 1;
                 end else if (y[0] > b0) begin
                   x[0] <= b0;
                   fixed[0] <= 1;
                 end
               end
            1: begin
                 x[1] <= y[1];
                 if (y[1] < a1) begin
                   x[1] <= a1;
                   fixed[1] <= 1;
                 end else if (y[1] > b1) begin
                   x[1] <= b1;
                   fixed[1] <= 1;
                 end
               end
            2: begin
                 x[2] <= y[2];
                 if (y[2] < a2) begin
                   x[2] <= a2;
                   fixed[2] <= 1;
                 end else if (y[2] > b2) begin
                   x[2] <= b2;
                   fixed[2] <= 1;
                 end
               end
            3: begin
                 x[3] <= y[3];
                 if (y[3] < a3) begin
                   x[3] <= a3;
                   fixed[3] <= 1;
                 end else if (y[3] > b3) begin
                   x[3] <= b3;
                   fixed[3] <= 1;
                 end
               end
          endcase
          index <= index + 1;
          if (index == 3) begin
            state <= CHECK_ITERATION;
            index <= 0;
            changed <= 0;
          end
        end

      CHECK_ITERATION:
        begin
          if (fixed == 4'b1111) begin
            state <= DONE;
          end else begin
            state <= COMPUTE_RESIDUAL;
            index <= 0;
            residual <= t;
          end
        end

      COMPUTE_RESIDUAL:
        begin
          case (index)
            0: if (fixed[0]) residual <= residual - x[0];
            1: if (fixed[1]) residual <= residual - x[1];
            2: if (fixed[2]) residual <= residual - x[2];
            3: if (fixed[3]) residual <= residual - x[3];
          endcase
          index <= index + 1;
          if (index == 3) begin
            state <= COMPUTE_TOTAL_Y_FREE;
            index <= 0;
            total_y_free <= 0;
          end
        end

      COMPUTE_TOTAL_Y_FREE:
        begin
          case (index)
            0: if (!fixed[0]) total_y_free <= total_y_free + y[0];
            1: if (!fixed[1]) total_y_free <= total_y_free + y[1];
            2: if (!fixed[2]) total_y_free <= total_y_free + y[2];
            3: if (!fixed[3]) total_y_free <= total_y_free + y[3];
          endcase
          index <= index + 1;
          if (index == 3) begin
            state <= UPDATE_X;
            index <= 0;
          end
        end

      UPDATE_X:
        begin
          case (index)
            0: if (!fixed[0]) begin
                 x[0] <= (residual * y[0]) / total_y_free;
                 if (x[0] < a0) begin
                   x[0] <= a0;
                   fixed[0] <= 1;
                   changed <= 1;
                 end else if (x[0] > b0) begin
                   x[0] <= b0;
                   fixed[0] <= 1;
                   changed <= 1;
                 end
               end
            1: if (!fixed[1]) begin
                 x[1] <= (residual * y[1]) / total_y_free;
                 if (x[1] < a1) begin
                   x[1] <= a1;
                   fixed[1] <= 1;
                   changed <= 1;
                 end else if (x[1] > b1) begin
                   x[1] <= b1;
                   fixed[1] <= 1;
                   changed <= 1;
                 end
               end
            2: if (!fixed[2]) begin
                 x[2] <= (residual * y[2]) / total_y_free;
                 if (x[2] < a2) begin
                   x[2] <= a2;
                   fixed[2] <= 1;
                   changed <= 1;
                 end else if (x[2] > b2) begin
                   x[2] <= b2;
                   fixed[2] <= 1;
                   changed <= 1;
                 end
               end
            3: if (!fixed[3]) begin
                 x[3] <= (residual * y[3]) / total_y_free;
                 if (x[3] < a3) begin
                   x[3] <= a3;
                   fixed[3] <= 1;
                   changed <= 1;
                 end else if (x[3] > b3) begin
                   x[3] <= b3;
                   fixed[3] <= 1;
                   changed <= 1;
                 end
               end
          endcase
          index <= index + 1;
          if (index == 3) begin
            if (changed) begin
              state <= COMPUTE_RESIDUAL;
              index <= 0;
              residual <= t;
            end else begin
              state <= DONE;
            end
          end
        end

      DONE:
        begin
          done <= 1;
          x0 <= x[0];
          x1 <= x[1];
          x2 <= x[2];
          x3 <= x[3];
        end

    endcase
  end
end

endmodule

`timescale 1ns/1ps

module HouseZone #(
    parameter N = 4,
    parameter ADDR_WIDTH = 2,
    parameter DATA_WIDTH = 16
)(
    input wire [ADDR_WIDTH-1:0] query_a,
    input wire [ADDR_WIDTH-1:0] query_b,
    input wire signed [DATA_WIDTH-1:0] house_x [0:N-1],
    input wire signed [DATA_WIDTH-1:0] house_y [0:N-1],
    output reg signed [DATA_WIDTH-1:0] result
);

    integer i, j;
    reg signed [DATA_WIDTH-1:0] min_x, max_x, min_y, max_y;
    reg [ADDR_WIDTH-1:0] idx_min_x, idx_max_x, idx_min_y, idx_max_y;
    reg signed [DATA_WIDTH-1:0] L0;
    reg signed [DATA_WIDTH-1:0] L_c;
    reg signed [DATA_WIDTH-1:0] min_x_c, max_x_c, min_y_c, max_y_c;
    reg first;
    reg [ADDR_WIDTH-1:0] c0, c1, c2, c3;
    reg signed [DATA_WIDTH-1:0] diff_x, diff_y;

    always_comb begin
        // Initialize with the first house in the range
        min_x = house_x[query_a];
        max_x = house_x[query_a];
        min_y = house_y[query_a];
        max_y = house_y[query_a];
        idx_min_x = query_a;
        idx_max_x = query_a;
        idx_min_y = query_a;
        idx_max_y = query_a;

        // Find extremes and their indices
        for (i = query_a + 1; i <= query_b; i = i + 1) begin
            if (house_x[i] < min_x) begin
                min_x = house_x[i];
                idx_min_x = i;
            end
            if (house_x[i] > max_x) begin
                max_x = house_x[i];
                idx_max_x = i;
            end
            if (house_y[i] < min_y) begin
                min_y = house_y[i];
                idx_min_y = i;
            end
            if (house_y[i] > max_y) begin
                max_y = house_y[i];
                idx_max_y = i;
            end
        end

        // Compute L0
        diff_x = max_x - min_x;
        diff_y = max_y - min_y;
        L0 = (diff_x > diff_y) ? diff_x : diff_y;
        result = L0;

        // Candidate indices
        c0 = idx_min_x;
        c1 = idx_max_x;
        c2 = idx_min_y;
        c3 = idx_max_y;

        // Candidate 0: remove idx_min_x
        first = 1;
        for (j = query_a; j <= query_b; j = j + 1) begin
            if (j != c0) begin
                if (first) begin
                    min_x_c = house_x[j];
                    max_x_c = house_x[j];
                    min_y_c = house_y[j];
                    max_y_c = house_y[j];
                    first = 0;
                end else begin
                    if (house_x[j] < min_x_c) min_x_c = house_x[j];
                    if (house_x[j] > max_x_c) max_x_c = house_x[j];
                    if (house_y[j] < min_y_c) min_y_c = house_y[j];
                    if (house_y[j] > max_y_c) max_y_c = house_y[j];
                end
            end
        end
        if (!first) begin
            diff_x = max_x_c - min_x_c;
            diff_y = max_y_c - min_y_c;
            L_c = (diff_x > diff_y) ? diff_x : diff_y;
            if (L_c < result) result = L_c;
        end

        // Candidate 1: remove idx_max_x, if different from c0
        if (c1 != c0) begin
            first = 1;
            for (j = query_a; j <= query_b; j = j + 1) begin
                if (j != c1) begin
                    if (first) begin
                        min_x_c = house_x[j];
                        max_x_c = house_x[j];
                        min_y_c = house_y[j];
                        max_y_c = house_y[j];
                        first = 0;
                    end else begin
                        if (house_x[j] < min_x_c) min_x_c = house_x[j];
                        if (house_x[j] > max_x_c) max_x_c = house_x[j];
                        if (house_y[j] < min_y_c) min_y_c = house_y[j];
                        if (house_y[j] > max_y_c) max_y_c = house_y[j];
                    end
                end
            end
            if (!first) begin
                diff_x = max_x_c - min_x_c;
                diff_y = max_y_c - min_y_c;
                L_c = (diff_x > diff_y) ? diff_x : diff_y;
                if (L_c < result) result = L_c;
            end
        end

        // Candidate 2: remove idx_min_y, if not already considered
        if (c2 != c0 && c2 != c1) begin
            first = 1;
            for (j = query_a; j <= query_b; j = j + 1) begin
                if (j != c2) begin
                    if (first) begin
                        min_x_c = house_x[j];
                        max_x_c = house_x[j];
                        min_y_c = house_y[j];
                        max_y_c = house_y[j];
                        first = 0;
                    end else begin
                        if (house_x[j] < min_x_c) min_x_c = house_x[j];
                        if (house_x[j] > max_x_c) max_x_c = house_x[j];
                        if (house_y[j] < min_y_c) min_y_c = house_y[j];
                        if (house_y[j] > max_y_c) max_y_c = house_y[j];
                    end
                end
            end
            if (!first) begin
                diff_x = max_x_c - min_x_c;
                diff_y = max_y_c - min_y_c;
                L_c = (diff_x > diff_y) ? diff_x : diff_y;
                if (L_c < result) result = L_c;
            end
        end

        // Candidate 3: remove idx_max_y, if not already considered
        if (c3 != c0 && c3 != c1 && c3 != c2) begin
            first = 1;
            for (j = query_a; j <= query_b; j = j + 1) begin
                if (j != c3) begin
                    if (first) begin
                        min_x_c = house_x[j];
                        max_x_c = house_x[j];
                        min_y_c = house_y[j];
                        max_y_c = house_y[j];
                        first = 0;
                    end else begin
                        if (house_x[j] < min_x_c) min_x_c = house_x[j];
                        if (house_x[j] > max_x_c) max_x_c = house_x[j];
                        if (house_y[j] < min_y_c) min_y_c = house_y[j];
                        if (house_y[j] > max_y_c) max_y_c = house_y[j];
                    end
                end
            end
            if (!first) begin
                diff_x = max_x_c - min_x_c;
                diff_y = max_y_c - min_y_c;
                L_c = (diff_x > diff_y) ? diff_x : diff_y;
                if (L_c < result) result = L_c;
            end
        end
    end

endmodule

