import cocotb
from cocotb.triggers import Timer
from cocotb.result import TestFailure

# ============================================================================
# MANDATORY HELPER FUNCTIONS
# ============================================================================

def is_value_defined(value):
    """Check if a cocotb value is defined (not X or Z)."""
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    """Safely convert cocotb value to int, returning default if X/Z."""
    try:
        return int(value)
    except ValueError:
        return default

def to_signed(val, bits):
    """Convert unsigned integer to signed (two's complement)."""
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    """Convert signed integer to unsigned for Verilog assignment."""
    if val < 0:
        return val + (1 << bits)
    return val

def has_signal(dut, name):
    """Check if DUT has a signal with given name."""
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(value, bits):
    """Clamp value to fit within specified bit width."""
    max_val = (1 << bits) - 1
    if value < 0:
        return from_signed(max(-((1 << (bits-1))), min((1 << (bits-1)) - 1, value)), bits)
    return min(max_val, max(0, value))

# ============================================================================
# CONFIGURATION
# ============================================================================

DATA_WIDTH = 16
N = 4
ADDR_WIDTH = 2

def compute_answer(houses_x, houses_y, a, b):
    """Compute minimal side length for a range [a,b] inclusive."""
    # Find extremes
    min_x = houses_x[a]
    max_x = houses_x[a]
    min_y = houses_y[a]
    max_y = houses_y[a]
    idx_min_x = a
    idx_max_x = a
    idx_min_y = a
    idx_max_y = a

    for i in range(a+1, b+1):
        if houses_x[i] < min_x:
            min_x = houses_x[i]
            idx_min_x = i
        if houses_x[i] > max_x:
            max_x = houses_x[i]
            idx_max_x = i
        if houses_y[i] < min_y:
            min_y = houses_y[i]
            idx_min_y = i
        if houses_y[i] > max_y:
            max_y = houses_y[i]
            idx_max_y = i

    L0 = max(max_x - min_x, max_y - min_y)
    result = L0

    # Candidates
    candidates = {idx_min_x, idx_max_x, idx_min_y, idx_max_y}

    for c in candidates:
        first = True
        for i in range(a, b+1):
            if i == c:
                continue
            if first:
                min_x_c = houses_x[i]
                max_x_c = houses_x[i]
                min_y_c = houses_y[i]
                max_y_c = houses_y[i]
                first = False
            else:
                if houses_x[i] < min_x_c:
                    min_x_c = houses_x[i]
                if houses_x[i] > max_x_c:
                    max_x_c = houses_x[i]
                if houses_y[i] < min_y_c:
                    min_y_c = houses_y[i]
                if houses_y[i] > max_y_c:
                    max_y_c = houses_y[i]
        if not first:
            L_c = max(max_x_c - min_x_c, max_y_c - min_y_c)
            if L_c < result:
                result = L_c

    return result

@cocotb.test(timeout_time=1000, timeout_unit="ms")
async def test_house_zone(dut):
    """Test HouseZone module with fixed data."""

    # Define test houses (addresses 0..3)
    houses_x = [1, 0, 1000, 5]
    houses_y = [0, 1, 1, 5]

    # Define queries: (a, b) inclusive indices
    queries = [
        (0, 2),  # houses 0,1,2 -> should give 1
        (1, 3),  # houses 1,2,3 -> compute expected
    ]

    # Write houses to DUT (signed assignment)
    for i in range(N):
        dut.house_x[i].value = from_signed(houses_x[i], DATA_WIDTH)
        dut.house_y[i].value = from_signed(houses_y[i], DATA_WIDTH)

    # Wait a bit for signals to settle
    await Timer(10, units='ns')

    # Process each query
    for idx, (a, b) in enumerate(queries):
        # Set query inputs (unsigned)
        dut.query_a.value = a
        dut.query_b.value = b

        # Wait for combinational propagation
        await Timer(10, units='ns')

        # Read result
        if not is_value_defined(dut.result.value):
            raise TestFailure(f"Query {idx}: result is undefined (X/Z)")

        raw_result = int(dut.result.value)
        actual = to_signed(raw_result, DATA_WIDTH)

        # Compute expected
        expected = compute_answer(houses_x, houses_y, a, b)

        if actual != expected:
            raise TestFailure(f"Query {idx}: expected {expected}, got {actual}")

        dut._log.info(f"Query {idx} [{a},{b}] = {actual} (OK)")

    dut._log.info("All tests passed.")

verilog_prompt:
module resource_claim (
    input clk,
    input rst_n,
    input start,

    // Graph topology - 16 nodes, each with up to 4 neighbors
    input [3:0] node_count,           // Number of nodes (1-16)
    input [3:0] iron_count,           // Number of iron ore nodes (1-4)
    input [3:0] coal_count,           // Number of coal nodes (1-4)

    // Resource locations
    input [3:0] iron_nodes [0:3],     // IDs of iron ore cells
    input [3:0] coal_nodes [0:3],     // IDs of coal cells

    // Graph connectivity - adjacency matrix representation
    input [15:0] adjacency [0:15],    // Each row: bit i=1 means edge to node i

    output reg [7:0] result,          // Minimal settlers needed
    output reg done,                  // Computation complete
    output reg impossible             // No solution possible
);

// State machine
localparam IDLE = 3'b000;
localparam BFS_IRON = 3'b001;
localparam BFS_COAL = 3'b010;
localparam COMPUTE = 3'b011;
localparam DONE = 3'b100;

reg [2:0] state;
reg [3:0] queue [0:15];  // BFS queue
reg [4:0] q_head, q_tail;
reg [7:0] dist_iron [0:15];  // Distance from node 1 to each node (for iron BFS)
reg [7:0] dist_coal [0:15];  // Distance from node 1 to each node (for coal BFS)
reg [3:0] visited;
reg [3:0] current_node;
reg [3:0] target_idx;
reg [7:0] min_settlers;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        impossible <= 0;
        result <= 0;
        q_head <= 0;
        q_tail <= 0;
        visited <= 0;
        min_settlers <= 8'hFF;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Initialize BFS for iron
                    for (i = 0; i < 16; i = i + 1) begin
                        dist_iron[i] <= 8'hFF;
                        dist_coal[i] <= 8'hFF;
                    end
                    dist_iron[0] <= 0;  // Node 1 is index 0
                    dist_coal[0] <= 0;
                    visited <= 0;
                    q_head <= 0;
                    q_tail <= 0;
                    target_idx <= 0;
                    state <= BFS_IRON;
                    impossible <= 0;
                end
            end

            BFS_IRON: begin
                // Run BFS to find distances to all iron nodes
                if (q_head < q_tail) begin
                    current_node <= queue[q_head];
                    q_head <= q_head + 1;
                end else if (q_head == q_tail && q_head == 0) begin
                    // First node - add node 0 to queue
                    queue[0] <= 0;
                    q_tail <= 1;
                end else if (dist_iron[target_idx] != 8'hFF && target_idx < iron_count) begin
                    // Found current iron node, move to next
                    target_idx <= target_idx + 1;
                end else if (target_idx < iron_count) begin
                    // Check if current iron node reached
                    if (dist_iron[iron_nodes[target_idx]] != 8'hFF) begin
                        target_idx <= target_idx + 1;
                    end else begin
                        // Add neighbors to queue
                        for (i = 0; i < 16; i = i + 1) begin
                            if (adjacency[current_node][i] && !visited[i] && dist_iron[i] == 8'hFF) begin
                                queue[q_tail] <= i;
                                q_tail <= q_tail + 1;
                                dist_iron[i] <= dist_iron[current_node] + 1;
                                visited[i] <= 1;
                            end
                        end
                    end
                end else if (target_idx >= iron_count) begin
                    // Iron BFS complete, start coal BFS
                    q_head <= 0;
                    q_tail <= 0;
                    visited <= 0;
                    target_idx <= 0;
                    state <= BFS_COAL;
                end
            end

            BFS_COAL: begin
                // Run BFS for coal nodes
                if (q_head < q_tail) begin
                    current_node <= queue[q_head];
                    q_head <= q_head + 1;
                end else if (q_head == q_tail && q_head == 0) begin
                    queue[0] <= 0;
                    q_tail <= 1;
                end else if (target_idx < coal_count) begin
                    if (dist_coal[coal_nodes[target_idx]] != 8'hFF) begin
                        target_idx <= target_idx + 1;
                    end else begin
                        for (i = 0; i < 16; i = i + 1) begin
                            if (adjacency[current_node][i] && !visited[i] && dist_coal[i] == 8'hFF) begin
                                queue[q_tail] <= i;
                                q_tail <= q_tail + 1;
                                dist_coal[i] <= dist_coal[current_node] + 1;
                                visited[i] <= 1;
                            end
                        end
                    end
                end else begin
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                // Find minimal settlers by combining paths
                min_settlers <= 8'hFF;

                // Check all combinations of iron and coal
                for (i = 0; i < 4; i = i + 1) begin
                    if (i < iron_count && dist_iron[iron_nodes[i]] != 8'hFF) begin
                        integer j;
                        for (j = 0; j < 4; j = j + 1) begin
                            if (j < coal_count && dist_coal[coal_nodes[j]] != 8'hFF) begin
                                // Total settlers = iron_dist + coal_dist - 1 (shared starting point)
                                integer total;
                                total = dist_iron[iron_nodes[i]] + dist_coal[coal_nodes[j]] - 1;
                                if (total < min_settlers) begin
                                    min_settlers <= total;
                                end
                            end
                        end
                    end
                end

                if (min_settlers == 8'hFF) begin
                    impossible <= 1;
                end else begin
                    result <= min_settlers;
                end
                state <= DONE;
            end

            DONE: begin
                done <= 1;
            end
        endcase
    end
end

endmodule

module betting_guarantee (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] julia_score,
    input wire [31:0] other_scores_0,
    input wire [31:0] other_scores_1,
    input wire [31:0] other_scores_2,
    input wire [31:0] other_scores_3,
    input wire [31:0] other_scores_4,
    input wire [31:0] other_scores_5,
    input wire [31:0] other_scores_6,
    input wire [31:0] other_scores_7,
    input wire [2:0] valid_count,
    output reg [31:0] guarantee_matches,
    output reg done
);

// Parameters
parameter MAX_OTHERS = 8;

// Internal registers
reg [31:0] max_score;
reg [31:0] second_max_score;
reg [31:0] count_max;
reg [31:0] temp_result;
reg [2:0] stage;
reg processing;

// Sorting logic - simple comparator network for 8 elements
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        max_score <= 32'd0;
        second_max_score <= 32'd0;
        count_max <= 32'd0;
        guarantee_matches <= 32'd0;
        done <= 1'b0;
        stage <= 3'd0;
        processing <= 1'b0;
    end else if (start && !processing) begin
        // Initialize
        stage <= 3'd0;
        processing <= 1'b1;
        done <= 1'b0;
        max_score <= 32'd0;
        second_max_score <= 32'd0;
        count_max <= 32'd0;
    end else if (processing) begin
        case (stage)
            3'd0: begin
                // Find max and second max
                // Stage 0: Initialize with first valid score
                if (valid_count > 0) begin
                    max_score <= other_scores_0;
                    second_max_score <= 32'd0;
                    count_max <= 32'd1;
                end else begin
                    max_score <= 32'd0;
                    second_max_score <= 32'd0;
                    count_max <= 32'd0;
                end
                stage <= 3'd1;
            end

            3'd1: begin
                // Process remaining scores
                if (valid_count > 1 && other_scores_1 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_1;
                    count_max <= 32'd1;
                end else if (valid_count > 1 && other_scores_1 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 1 && other_scores_1 > second_max_score && other_scores_1 < max_score) begin
                    second_max_score <= other_scores_1;
                end
                stage <= 3'd2;
            end

            3'd2: begin
                if (valid_count > 2 && other_scores_2 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_2;
                    count_max <= 32'd1;
                end else if (valid_count > 2 && other_scores_2 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 2 && other_scores_2 > second_max_score && other_scores_2 < max_score) begin
                    second_max_score <= other_scores_2;
                end
                stage <= 3'd3;
            end

            3'd3: begin
                if (valid_count > 3 && other_scores_3 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_3;
                    count_max <= 32'd1;
                end else if (valid_count > 3 && other_scores_3 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 3 && other_scores_3 > second_max_score && other_scores_3 < max_score) begin
                    second_max_score <= other_scores_3;
                end
                stage <= 3'd4;
            end

            3'd4: begin
                if (valid_count > 4 && other_scores_4 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_4;
                    count_max <= 32'd1;
                end else if (valid_count > 4 && other_scores_4 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 4 && other_scores_4 > second_max_score && other_scores_4 < max_score) begin
                    second_max_score <= other_scores_4;
                end
                stage <= 3'd5;
            end

            3'd5: begin
                if (valid_count > 5 && other_scores_5 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_5;
                    count_max <= 32'd1;
                end else if (valid_count > 5 && other_scores_5 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 5 && other_scores_5 > second_max_score && other_scores_5 < max_score) begin
                    second_max_score <= other_scores_5;
                end
                stage <= 3'd6;
            end

            3'd6: begin
                if (valid_count > 6 && other_scores_6 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_6;
                    count_max <= 32'd1;
                end else if (valid_count > 6 && other_scores_6 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 6 && other_scores_6 > second_max_score && other_scores_6 < max_score) begin
                    second_max_score <= other_scores_6;
                end
                stage <= 3'd7;
            end

            3'd7: begin
                if (valid_count > 7 && other_scores_7 > max_score) begin
                    second_max_score <= max_score;
                    max_score <= other_scores_7;
                    count_max <= 32'd1;
                end else if (valid_count > 7 && other_scores_7 == max_score) begin
                    count_max <= count_max + 1;
                end else if (valid_count > 7 && other_scores_7 > second_max_score && other_scores_7 < max_score) begin
                    second_max_score <= other_scores_7;
                end
                // Compute result in next stage
                stage <= 3'd0; // Will move to next logic
                // Actually need separate stage for calculation
                processing <= 1'b0; // Temporarily stop, but we need calculation
            end

            default: begin
                stage <= 3'd0;
                processing <= 1'b0;
            end
        endcase
    end
end

// Separate calculation logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        guarantee_matches <= 32'd0;
        done <= 1'b0;
    end else if (start && !processing && stage == 3'd0) begin
        done <= 1'b0;
    end else if (!processing && stage == 3'd7 && !done) begin
        // Calculation stage
        if (max_score == julia_score) begin
            if (second_max_score > 0 && julia_score >= second_max_score)
                guarantee_matches <= (julia_score - second_max_score) + count_max - 1;
            else
                guarantee_matches <= count_max - 1;
        end else begin
            if (second_max_score > 0 && julia_score >= second_max_score)
                guarantee_matches <= (julia_score - max_score) + (julia_score - second_max_score) + count_max - 2;
            else if (julia_score > max_score)
                guarantee_matches <= julia_score - max_score;
            else
                guarantee_matches <= 32'd0;
        end
        done <= 1'b1;
        stage <= 3'd0;
    end else if (done) begin
        done <= 1'b0;
    end
end

endmodule

module pizza_delivery_optimizer (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,
    input [3:0] m,
    input [3:0] k,
    input [3:0] edge_u [0:15],
    input [3:0] edge_v [0:15],
    input [31:0] edge_d [0:15],
    input [31:0] order_s [0:7],
    input [3:0] order_u [0:7],
    input [31:0] order_t [0:7],
    output reg [31:0] result,
    output reg done
);

// Internal state machine
reg [2:0] state;
reg [3:0] i_cnt, j_cnt, k_cnt;
reg [31:0] dist [0:7][0:7];
reg [31:0] D_prev, D_curr, T_min;
reg [3:0] order_idx;

// State definitions
localparam IDLE = 0;
localparam INIT_DIST = 1;
localparam FLOYD_UPDATE = 2;
localparam COMPUTE_DELIVERY = 3;
localparam DONE = 4;

// Constants
localparam INF = 32'h7FFFFFFF;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i_cnt <= 0;
        j_cnt <= 0;
        k_cnt <= 0;
        order_idx <= 0;
        D_prev <= 0;
        D_curr <= 0;
        T_min <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= INIT_DIST;
                    i_cnt <= 0;
                    j_cnt <= 0;
                end
            end

            INIT_DIST: begin
                // Initialize distance matrix
                if (i_cnt < n) begin
                    if (j_cnt < n) begin
                        if (i_cnt == j_cnt)
                            dist[i_cnt][j_cnt] <= 0;
                        else
                            dist[i_cnt][j_cnt] <= INF;
                        j_cnt <= j_cnt + 1;
                    end else begin
                        j_cnt <= 0;
                        i_cnt <= i_cnt + 1;
                    end
                end else begin
                    // Set edges
                    i_cnt <= 0;
                    state <= FLOYD_UPDATE;
                end
            end

            FLOYD_UPDATE: begin
                // Floyd-Warshall algorithm
                if (k_cnt < n) begin
                    if (i_cnt < n) begin
                        if (j_cnt < n) begin
                            // dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
                            if (dist[i_cnt][k_cnt] != INF && dist[k_cnt][j_cnt] != INF) begin
                                if (dist[i_cnt][k_cnt] + dist[k_cnt][j_cnt] < dist[i_cnt][j_cnt]) begin
                                    dist[i_cnt][j_cnt] <= dist[i_cnt][k_cnt] + dist[k_cnt][j_cnt];
                                end
                            end
                            j_cnt <= j_cnt + 1;
                        end else begin
                            j_cnt <= 0;
                            i_cnt <= i_cnt + 1;
                        end
                    end else begin
                        i_cnt <= 0;
                        k_cnt <= k_cnt + 1;
                    end
                end else begin
                    // Set actual edge distances (after Floyd-Warshall initialization)
                    if (i_cnt < m) begin
                        if (edge_u[i_cnt] < n && edge_v[i_cnt] < n) begin
                            // Convert to 0-based index
                            dist[edge_u[i_cnt]-1][edge_v[i_cnt]-1] <= edge_d[i_cnt];
                            dist[edge_v[i_cnt]-1][edge_u[i_cnt]-1] <= edge_d[i_cnt];
                        end
                        i_cnt <= i_cnt + 1;
                    end else begin
                        i_cnt <= 0;
                        k_cnt <= 0;
                        j_cnt <= 0;
                        state <= COMPUTE_DELIVERY;
                        order_idx <= 0;
                        T_min <= 0;
                    end
                end
            end

            COMPUTE_DELIVERY: begin
                if (order_idx < k) begin
                    if (order_idx == 0) begin
                        // First order: D0 = max(t0, dist[1][u0])
                        if (order_u[0] > 0 && order_u[0] <= n) begin
                            if (dist[0][order_u[0]-1] > order_t[0]) begin
                                D_prev <= dist[0][order_u[0]-1];
                                T_min <= dist[0][order_u[0]-1] - order_s[0];
                            end else begin
                                D_prev <= order_t[0];
                                T_min <= order_t[0] - order_s[0];
                            end
                        end
                        order_idx <= order_idx + 1;
                    end else begin
                        // Subsequent orders
                        if (order_u[order_idx-1] > 0 && order_u[order_idx-1] <= n &&
                            order_u[order_idx] > 0 && order_u[order_idx] <= n) begin

                            reg [31:0] travel_time = dist[order_u[order_idx-1]-1][order_u[order_idx]-1];
                            reg [31:0] arrival_time = D_prev + travel_time;
                            reg [31:0] new_T;

                            if (arrival_time > order_t[order_idx]) begin
                                D_curr <= arrival_time;
                                new_T = arrival_time - order_s[order_idx];
                            end else begin
                                D_curr <= order_t[order_idx];
                                new_T = order_t[order_idx] - order_s[order_idx];
                            end

                            if (new_T > T_min) begin
                                T_min <= new_T;
                            end

                            D_prev <= (arrival_time > order_t[order_idx]) ? arrival_time : order_t[order_idx];
                        end
                        order_idx <= order_idx + 1;
                    end
                end else begin
                    result <= T_min;
                    state <= DONE;
                    done <= 1;
                end
            end

            DONE: begin
                done <= 0;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module WatchLaterMinClicks (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] video_types [0:15],  // ASCII characters, 16 videos max
    input wire [4:0] length,              // Number of videos (1-16)
    output reg [7:0] result,
    output reg done
);

// Parameters
parameter MAX_VIDEOS = 16;
parameter MAX_TYPES = 8;
parameter STATE_IDLE = 3'b000;
parameter STATE_COUNT_SEGMENTS = 3'b001;
parameter STATE_FIND_MIN = 3'b010;
parameter STATE_REMOVE_TYPE = 3'b011;
parameter STATE_UPDATE_RESULT = 3'b100;
parameter STATE_DONE = 3'b101;

// Registers
reg [2:0] state;
reg [7:0] current_videos [0:15];  // Current remaining videos
reg [4:0] remaining_length;
reg [7:0] segment_counts [0:7];    // Segment counts for each type (0-7, mapped from ASCII)
reg [7:0] min_segments;
reg [7:0] selected_type;
reg [3:0] type_index;              // Iterating through types
reg [4:0] video_index;             // Iterating through videos
reg [7:0] temp_result;
reg [7:0] last_type;
reg counting_done;

// Helper: Map ASCII to type index (0-7)
function automatic [2:0] char_to_type(input [7:0] c);
    begin
        // Map 'a'..'h' to 0..7 (simple mapping for small k)
        char_to_type = c[2:0];  // Use lower 3 bits for type index
    end
endfunction

// Helper: Check if two types are same
function automatic is_same_type(input [7:0] a, input [7:0] b);
    begin
        is_same_type = (a == b);
    end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        result <= 8'b0;
        done <= 1'b0;
        remaining_length <= 5'b0;
        temp_result <= 8'b0;
        type_index <= 4'b0;
        video_index <= 5'b0;
        min_segments <= 8'hFF;
        selected_type <= 8'b0;
        last_type <= 8'b0;
        counting_done <= 1'b0;
    end else begin
        case (state)
            STATE_IDLE: begin
                done <= 1'b0;
                if (start && length > 0) begin
                    // Initialize current_videos from input
                    for (integer i = 0; i < MAX_VIDEOS; i = i + 1) begin
                        if (i < length)
                            current_videos[i] <= video_types[i];
                        else
                            current_videos[i] <= 8'hFF;  // Invalid marker
                    end
                    remaining_length <= length;
                    temp_result <= 8'b0;
                    state <= STATE_COUNT_SEGMENTS;
                    type_index <= 4'b0;
                    video_index <= 5'b0;
                    counting_done <= 1'b0;
                end
            end

            STATE_COUNT_SEGMENTS: begin
                // Count segments for current type_index
                if (type_index < MAX_TYPES) begin
                    if (!counting_done) begin
                        // Reset segment count for this type
                        segment_counts[type_index] <= 8'b0;
                        video_index <= 5'b0;
                        last_type <= 8'hFF;
                        counting_done <= 1'b1;
                    end else if (video_index < remaining_length) begin
                        if (current_videos[video_index] != 8'hFF) begin
                            if (char_to_type(current_videos[video_index]) == type_index[2:0]) begin
                                // This video is of current type
                                if (video_index == 0 || 
                                    last_type == 8'hFF || 
                                    !is_same_type(current_videos[video_index-1], current_videos[video_index])) begin
                                    // Start of new segment
                                    segment_counts[type_index] <= segment_counts[type_index] + 1;
                                end
                                last_type <= current_videos[video_index];
                            end
                        end
                        video_index <= video_index + 1;
                    end else begin
                        counting_done <= 1'b0;
                        type_index <= type_index + 1;
                    end
                end else begin
                    // Done counting all types
                    type_index <= 4'b0;
                    state <= STATE_FIND_MIN;
                    min_segments <= 8'hFF;
                    selected_type <= 8'hFF;
                end
            end

            STATE_FIND_MIN: begin
                // Find type with minimum segments (but > 0)
                if (type_index < MAX_TYPES) begin
                    if (segment_counts[type_index] > 0 && segment_counts[type_index] < min_segments) begin
                        min_segments <= segment_counts[type_index];
                        selected_type <= type_index[2:0];
                    end
                    type_index <= type_index + 1;
                end else begin
                    if (min_segments != 8'hFF && remaining_length > 0) begin
                        // Remove videos of selected_type
                        video_index <= 5'b0;
                        state <= STATE_REMOVE_TYPE;
                    end else begin
                        // No videos left or all removed
                        state <= STATE_DONE;
                    end
                end
            end

            STATE_REMOVE_TYPE: begin
                // Remove all videos of selected_type from current_videos
                if (video_index < remaining_length) begin
                    if (current_videos[video_index] != 8'hFF && 
                        char_to_type(current_videos[video_index]) == selected_type[2:0]) begin
                        // Remove this video by shifting remaining videos left
                        for (integer i = video_index; i < remaining_length - 1; i = i + 1) begin
                            current_videos[i] <= current_videos[i + 1];
                        end
                        current_videos[remaining_length - 1] <= 8'hFF;
                        remaining_length <= remaining_length - 1;
                        // Stay at same index after shift
                    end else begin
                        video_index <= video_index + 1;
                    end
                end else begin
                    state <= STATE_UPDATE_RESULT;
                end
            end

            STATE_UPDATE_RESULT: begin
                temp_result <= temp_result + min_segments;
                state <= STATE_COUNT_SEGMENTS;
                type_index <= 4'b0;
                video_index <= 5'b0;
                counting_done <= 1'b0;
            end

            STATE_DONE: begin
                result <= temp_result;
                done <= 1'b1;
                state <= STATE_IDLE;
            end

            default: state <= STATE_IDLE;
        endcase
    end
end

endmodule

// Testbench Requirements:
// - Test with provided examples: "abba" -> 2, "rtrt" -> 3
// - Additional tests for edge cases
// - Verify state transitions and result correctness
// - Use 8-bit ASCII characters for video types
// - Map types to indices 0-7 using lower 3 bits
// - Maximum 16 videos, length input 1-16
// - Result expected in range 1-16 clicks

module gridnavia_solver #(
  parameter ROWS = 8,
  parameter COLS = 8,
  parameter DATA_WIDTH = 2,   // 1 or 2
  parameter LANG_WIDTH = 1     // 0 or 1 for presence
)(
  input wire clk,
  input wire rst_n,
  input wire start,
  input wire [ROWS-1:0][COLS-1:0][DATA_WIDTH-1:0] grid,
  output reg [ROWS-1:0][COLS-1:0][LANG_WIDTH-1:0] grid_A,
  output reg [ROWS-1:0][COLS-1:0][LANG_WIDTH-1:0] grid_B,
  output reg [ROWS-1:0][COLS-1:0][LANG_WIDTH-1:0] grid_C,
  output reg done,
  output reg impossible
);

  // State definitions
  localparam STATE_IDLE = 3'b000;
  localparam STATE_CHECK = 3'b001;
  localparam STATE_COMPUTE_A = 3'b010;
  localparam STATE_COMPUTE_B = 3'b011;
  localparam STATE_COMPUTE_C = 3'b100;
  localparam STATE_VERIFY = 3'b101;
  localparam STATE_DONE = 3'b110;
  localparam STATE_IMPOSSIBLE = 3'b111;

  reg [2:0] current_state, next_state;
  reg [3:0] row_ptr, col_ptr; // 8x8 max, so 4 bits
  reg [1:0] cell_type; // 1 or 2 from grid
  reg [1:0] lang_count; // Count of languages assigned

  // Connectivity tracking for each language
  reg [ROWS*COLS-1:0] visited_A, visited_B, visited_C;
  reg [ROWS*COLS-1:0] assigned_A, assigned_B, assigned_C;

  // Helper to compute index
  function automatic integer idx(input [3:0] r, input [3:0] c);
    idx = r * COLS + c;
  endfunction

  // Check if all three languages are connected
  task check_connectivity;
    // Simplified: just check that each language has at least one cell
    // In real implementation, would do BFS to check connectivity
    integer i;
    reg has_A, has_B, has_C;
    begin
      has_A = 0; has_B = 0; has_C = 0;
      for (i = 0; i < ROWS*COLS; i = i + 1) begin
        if (assigned_A[i]) has_A = 1;
        if (assigned_B[i]) has_B = 1;
        if (assigned_C[i]) has_C = 1;
      end
      if (!has_A || !has_B || !has_C) begin
        impossible = 1;
      end
    end
  endtask

  // Main state machine
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      current_state <= STATE_IDLE;
      done <= 0;
      impossible <= 0;
      grid_A <= '0;
      grid_B <= '0;
      grid_C <= '0;
      assigned_A <= '0;
      assigned_B <= '0;
      assigned_C <= '0;
      row_ptr <= 0;
      col_ptr <= 0;
    end else begin
      case (current_state)
        STATE_IDLE: begin
          done <= 0;
          impossible <= 0;
          if (start) begin
            // Special case: 1x1 grid
            if (ROWS == 1 && COLS == 1) begin
              if (grid[0][0] == 2'd1) begin
                current_state <= STATE_IMPOSSIBLE;
              end else begin
                // Assign all three languages
                grid_A[0][0] <= 1'b1;
                grid_B[0][0] <= 1'b1;
                grid_C[0][0] <= 1'b1;
                current_state <= STATE_DONE;
              end
            end else begin
              current_state <= STATE_CHECK;
              row_ptr <= 0;
              col_ptr <= 0;
            end
          end
        end

        STATE_CHECK: begin
          // Check if we processed all cells
          if (row_ptr >= ROWS) begin
            current_state <= STATE_COMPUTE_A;
            row_ptr <= 0;
            col_ptr <= 0;
          end else if (col_ptr >= COLS) begin
            row_ptr <= row_ptr + 1;
            col_ptr <= 0;
          end else begin
            cell_type <= grid[row_ptr][col_ptr];
            // For cells with '1', they'll be assigned one language
            // For cells with '2', they'll be assigned two languages
            current_state <= STATE_COMPUTE_A;
          end
        end

        STATE_COMPUTE_A: begin
          // Assign language A based on position pattern
          if (row_ptr == 0 || col_ptr == 0) begin
            assigned_A[idx(row_ptr, col_ptr)] <= 1'b1;
            grid_A[row_ptr][col_ptr] <= 1'b1;
          end
          current_state <= STATE_COMPUTE_B;
        end

        STATE_COMPUTE_B: begin
          // Assign language B based on position pattern
          if (row_ptr == ROWS-1 || col_ptr == COLS-1) begin
            assigned_B[idx(row_ptr, col_ptr)] <= 1'b1;
            grid_B[row_ptr][col_ptr] <= 1'b1;
          end
          current_state <= STATE_COMPUTE_C;
        end

        STATE_COMPUTE_C: begin
          // Assign language C to middle cells
          if (row_ptr > 0 && row_ptr < ROWS-1 && 
              col_ptr > 0 && col_ptr < COLS-1) begin
            assigned_C[idx(row_ptr, col_ptr)] <= 1'b1;
            grid_C[row_ptr][col_ptr] <= 1'b1;
          end
          // Also assign C to any cell that needs more languages
          lang_count <= (grid_A[row_ptr][col_ptr] ? 1'b1 : 1'b0) +
                       (grid_B[row_ptr][col_ptr] ? 1'b1 : 1'b0) +
                       (grid_C[row_ptr][col_ptr] ? 1'b1 : 1'b0);
          current_state <= STATE_VERIFY;
        end

        STATE_VERIFY: begin
          // Verify constraints for current cell
          if (cell_type == 2'd1 && lang_count != 1) begin
            current_state <= STATE_IMPOSSIBLE;
          end else if (cell_type == 2'd2 && lang_count < 2) begin
            // Add language C if needed
            if (!grid_C[row_ptr][col_ptr]) begin
              grid_C[row_ptr][col_ptr] <= 1'b1;
              assigned_C[idx(row_ptr, col_ptr)] <= 1'b1;
              lang_count <= lang_count + 1;
              // Stay in VERIFY to recheck
            end else begin
              current_state <= STATE_IMPOSSIBLE;
            end
          end else begin
            // Cell constraints satisfied, move to next
            col_ptr <= col_ptr + 1;
            current_state <= STATE_CHECK;
          end
        end

        STATE_DONE: begin
          // Final connectivity check
          check_connectivity;
          if (!impossible) begin
            done <= 1'b1;
          end else begin
            current_state <= STATE_IMPOSSIBLE;
          end
        end

        STATE_IMPOSSIBLE: begin
          impossible <= 1'b1;
          done <= 1'b1;
        end
      endcase
    end
  end

endmodule

// Testbench will verify with specific test cases including the 3x4 example

module dog_feeding_2dogs (
    input clk,
    input rst_n,
    input start,
    input [7:0] t0_0, t0_1, t0_2, t0_3,
    input [7:0] t1_0, t1_1, t1_2, t1_3,
    output reg [7:0] min_T,
    output reg done
);

    // State encoding
    localparam IDLE = 3'b000;
    localparam INIT = 3'b001;
    localparam LOOP0 = 3'b010;
    localparam LOOP1 = 3'b011;
    localparam UPDATE = 3'b100;
    localparam NEXT = 3'b101;
    localparam DONE = 3'b110;

    reg [2:0] state;
    reg [1:0] bowl0_idx, bowl1_idx;
    reg [7:0] min_T_reg;
    reg [7:0] t0_reg, t1_reg;

    // Combinational logic
    wire [7:0] t0_current, t1_current;
    wire [7:0] diff;

    assign t0_current = (bowl0_idx == 2'd0) ? t0_0 :
                       (bowl0_idx == 2'd1) ? t0_1 :
                       (bowl0_idx == 2'd2) ? t0_2 : t0_3;

    assign t1_current = (bowl1_idx == 2'd0) ? t1_0 :
                       (bowl1_idx == 2'd1) ? t1_1 :
                       (bowl1_idx == 2'd2) ? t1_2 : t1_3;

    assign diff = (t0_reg > t1_reg) ? (t0_reg - t1_reg) : (t1_reg - t0_reg);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            min_T <= 8'd0;
            done <= 1'b0;
            bowl0_idx <= 2'd0;
            bowl1_idx <= 2'd0;
            min_T_reg <= 8'd0;
            t0_reg <= 8'd0;
            t1_reg <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) state <= INIT;
                end

                INIT: begin
                    min_T_reg <= 8'd255;
                    bowl0_idx <= 2'd0;
                    bowl1_idx <= 2'd0;
                    state <= LOOP0;
                end

                LOOP0: begin
                    if (bowl0_idx == 2'd4) begin
                        state <= DONE;
                    end else begin
                        bowl1_idx <= 2'd0;
                        state <= LOOP1;
                    end
                end

                LOOP1: begin
                    if (bowl1_idx == 2'd4) begin
                        bowl0_idx <= bowl0_idx + 1'b1;
                        state <= LOOP0;
                    end else if (bowl0_idx != bowl1_idx) begin
                        t0_reg <= t0_current;
                        t1_reg <= t1_current;
                        state <= UPDATE;
                    end else begin
                        state <= NEXT;
                    end
                end

                UPDATE: begin
                    if (diff < min_T_reg) begin
                        min_T_reg <= diff;
                    end
                    state <= NEXT;
                end

                NEXT: begin
                    bowl1_idx <= bowl1_idx + 1'b1;
                    state <= LOOP1;
                end

                DONE: begin
                    min_T <= min_T_reg;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module file_deletion (
    input clk,
    input rst_n,
    input start,
    input [13:0] nr, nc,  // Screen dimensions
    input [2:0] N,         // Number of points (≤8)
    input [231:0] points_packed,  // 8 points × 29 bits each (1-bit type + 14-bit x + 14-bit y)
    output reg [3:0] moves,
    output reg done
);
    // State definitions
    localparam IDLE = 3'd0;
    localparam LOAD = 3'd1;
    localparam SORT = 3'd2;
    localparam ITERATE = 3'd3;
    localparam COMPUTE = 3'd4;
    localparam FINISH = 3'd5;

    // Internal registers
    reg [2:0] state, next_state;
    reg [2:0] count;        // For sorting/iteration
    reg [3:0] max_f;        // Maximum F = (#delete in rect) - (#keep in rect)
    reg [3:0] current_f;
    reg [3:0] n_delete;     // Total number of delete points

    // Unpacked points storage (8 points)
    reg [13:0] x_coords [0:7];
    reg [13:0] y_coords [0:7];
    reg types [0:7];         // 1=delete, 0=keep

    // Compressed coordinates
    reg [13:0] xs [0:9];     // Unique x + 0, nr (max 10: 8 points + 2 boundaries)
    reg [13:0] ys [0:9];     // Unique y + 0, nc
    reg [3:0] xs_count;      // Number of unique x
    reg [3:0] ys_count;      // Number of unique y

    // Rectangle boundaries indices
    reg [3:0] x_left_idx, x_right_idx;
    reg [3:0] y_low_idx, y_high_idx;

    // Loop counters
    reg [3:0] i, j;

    // Helper: extract bit from packed points
    wire [28:0] point_wire [0:7];
    generate
        genvar k;
        for (k = 0; k < 8; k = k + 1) begin : unpack
            assign point_wire[k] = points_packed[29*k +: 29];
        end
    endgenerate

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) state <= IDLE;
        else state <= next_state;
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = LOAD;
            LOAD: next_state = SORT;
            SORT: if (count >= 4'd9) next_state = ITERATE;
            ITERATE: next_state = COMPUTE;
            COMPUTE: if (i >= N) next_state = FINISH;
            FINISH: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Main processing
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all
            moves <= 4'd0;
            done <= 0;
            max_f <= 4'd0;
            count <= 3'd0;
            xs_count <= 4'd0;
            ys_count <= 4'd0;
            n_delete <= 4'd0;
            x_left_idx <= 4'd0;
            x_right_idx <= 4'd0;
            y_low_idx <= 4'd0;
            y_high_idx <= 4'd0;
            i <= 4'd0;
            j <= 4'd0;
            current_f <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        max_f <= 4'd0;
                        count <= 3'd0;
                        i <= 4'd0;
                        n_delete <= 4'd0;
                    end
                end

                LOAD: begin
                    // Unpack points and count deletes
                    for (integer idx = 0; idx < 8; idx = idx + 1) begin
                        if (idx < N) begin
                            types[idx] <= point_wire[idx][28];
                            x_coords[idx] <= point_wire[idx][27:14];
                            y_coords[idx] <= point_wire[idx][13:0];
                            if (point_wire[idx][28]) n_delete <= n_delete + 1;
                        end
                    end
                    // Add screen boundaries
                    xs[0] <= 14'd0;
                    xs[1] <= nr;
                    ys[0] <= 14'd0;
                    ys[1] <= nc;
                    xs_count <= 4'd2;
                    ys_count <= 4'd2;
                end

                SORT: begin
                    // Simple insertion sort for points (simplified for small N)
                    if (count < N) begin
                        // Add point to xs/ys if not already present
                        if (x_coords[count] != 14'd0 && x_coords[count] != nr) begin
                            xs[xs_count] <= x_coords[count];
                            xs_count <= xs_count + 1;
                        end
                        if (y_coords[count] != 14'd0 && y_coords[count] != nc) begin
                            ys[ys_count] <= y_coords[count];
                            ys_count <= ys_count + 1;
                        end
                        count <= count + 1;
                    end else begin
                        // Sort xs and ys (bubble sort - simplified)
                        // In practice, this would need more states for sorting
                        // For this design, we assume input order is manageable
                        count <= 4'd0;
                    end
                end

                ITERATE: begin
                    // Iterate over rectangle boundaries
                    if (x_left_idx < xs_count - 1) begin
                        if (x_right_idx < xs_count) begin
                            if (y_low_idx < ys_count - 1) begin
                                if (y_high_idx < ys_count) begin
                                    current_f <= 0;
                                    i <= 0;  // Reset point counter
                                    next_state = COMPUTE;
                                end else begin
                                    y_high_idx <= y_low_idx + 1;
                                    y_low_idx <= y_low_idx + 1;
                                end
                            end else begin
                                y_low_idx <= 0;
                                y_high_idx <= 1;
                                x_right_idx <= x_right_idx + 1;
                            end
                        end else begin
                            x_right_idx <= x_left_idx + 1;
                            x_left_idx <= x_left_idx + 1;
                        end
                    end else begin
                        next_state = FINISH;
                    end
                end

                COMPUTE: begin
                    // Check if point is inside current rectangle
                    if (i < N) begin
                        if (x_coords[i] >= xs[x_left_idx] && x_coords[i] <= xs[x_right_idx] &&
                            y_coords[i] >= ys[y_low_idx] && y_coords[i] <= ys[y_high_idx]) begin
                            if (types[i]) current_f <= current_f + 1;  // Delete point
                            else current_f <= current_f - 1;           // Keep point
                        end
                        i <= i + 1;
                    end else begin
                        if (current_f > max_f) max_f <= current_f;
                        next_state = ITERATE;
                    end
                end

                FINISH: begin
                    moves <= n_delete - max_f;
                    done <= 1;
                end
            endcase
        end
    end
endmodule

// Password Recovery Module
// Finds characters in f^K(S) where f expands each character via substitution strings T[a-z]
// Scaled constraints: |S|<=16, |T_i|<=8, K<=256, M<=8 queries
module password_recovery (
    input clk,
    input rst_n,
    input start,

    // Configuration
    input [7:0] K,          // Iterations (1-256)
    input [3:0] M,          // Queries (1-8)

    // Data loading interface
    input load_en,
    input [4:0] load_addr,  // 0-15=S, 16-41=T[0-25]
    input [7:0] load_data,
    input [3:0] load_len,   // Length for current entity

    // Query loading
    input query_load_en,
    input [2:0] query_addr,
    input [31:0] query_pos,

    // Results
    output reg [7:0] result_char,
    output reg [2:0] result_addr,
    output reg result_valid,
    output reg done,
    output reg error
);

// Memory arrays
reg [7:0] S [0:15];
reg [3:0] S_len;
reg [7:0] T [0:25][0:7];
reg [3:0] T_len [0:25];
reg [31:0] query_pos_arr [0:7];
reg [7:0] results [0:7];

// Length table: length_table[c][k] = length of expanding char c k times
reg [31:0] length_table [0:25][0:256];

// State machine
reg [3:0] state;
localparam IDLE = 0, PRECOMP = 1, PRECOMP_LOOP = 2, PRECOMP_SUM = 3;
localparam COMPUTE = 4, FIND_CHAR = 5, UPDATE = 6, OUTPUT = 7, DONE = 8;

// Processing registers
reg [7:0] cur_q, cur_level, cur_char;
reg [31:0] cur_pos, cumulative;
reg [3:0] cur_len, idx;
reg [7:0] cur_str [0:7];
reg [7:0] pc, pl, pi;  // Precompute counters
reg [31:0] temp_sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE; done <= 0; error <= 0; result_valid <= 0; result_addr <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (load_en) begin
                    if (load_addr < 16) begin
                        S[load_addr] <= load_data;
                        if (load_addr == 15) S_len <= load_len;
                    end else if (load_addr >= 16 && load_addr < 42) begin
                        // Simplified: assume sequential loading of T chars
                        integer char_idx = load_addr - 16;
                        integer char_pos = load_len[2:0]; // Use load_len low bits as position
                        T[char_idx][char_pos] <= load_data;
                        T_len[char_idx] <= load_len[7:4]; // High bits for length
                    end
                end
                if (query_load_en) query_pos_arr[query_addr] <= query_pos;
                if (start && load_addr == 41) begin // All data loaded
                    if (S_len == 0 || K == 0 || K > 256 || M == 0 || M > 8) begin
                        error <= 1; state <= DONE;
                    end else begin
                        cur_q <= 0; pc <= 0; pl <= 0; state <= PRECOMP;
                    end
                end
            end

            PRECOMP: begin
                if (pc < 26) begin
                    length_table[pc][0] <= 1; pc <= pc + 1;
                end else begin
                    pc <= 0; pl <= 1; state <= (K > 0) ? PRECOMP_LOOP : COMPUTE;
                end
            end

            PRECOMP_LOOP: begin
                if (pl <= K) begin
                    if (pc < 26) begin
                        temp_sum <= 0; pi <= 0; state <= PRECOMP_SUM;
                    end else begin
                        pc <= 0; pl <= pl + 1;
                    end
                end else state <= COMPUTE;
            end

            PRECOMP_SUM: begin
                if (pi < T_len[pc]) begin
                    temp_sum <= temp_sum + length_table[T[pc][pi]][pl-1]; pi <= pi + 1;
                end else begin
                    length_table[pc][pl] <= temp_sum; pc <= pc + 1; state <= PRECOMP_LOOP;
                end
            end

            COMPUTE: begin
                if (cur_q < M) begin
                    cur_level <= K; cur_len <= S_len; cur_pos <= query_pos_arr[cur_q];
                    for (integer i = 0; i < 8; i = i + 1) cur_str[i] <= (i < S_len) ? S[i] : 0;
                    state <= FIND_CHAR;
                end else state <= OUTPUT;
            end

            FIND_CHAR: begin
                if (cur_level == 0) begin
                    if (cur_pos > 0 && cur_pos <= cur_len) begin
                        results[cur_q] <= cur_str[cur_pos-1]; cur_q <= cur_q + 1; state <= COMPUTE;
                    end else begin error <= 1; state <= DONE; end
                end else begin
                    cumulative <= 0; idx <= 0; state <= UPDATE;
                end
            end

            UPDATE: begin
                if (idx < cur_len) begin
                    cur_char <= cur_str[idx];
                    if (cur_pos <= cumulative + length_table[cur_str[idx]][cur_level]) begin
                        cur_pos <= cur_pos - cumulative; cur_len <= T_len[cur_str[idx]];
                        for (integer i = 0; i < 8; i = i + 1) cur_str[i] <= (i < T_len[cur_str[idx]]) ? T[cur_str[idx]][i] : 0;
                        cur_level <= cur_level - 1; state <= FIND_CHAR;
                    end else begin
                        cumulative <= cumulative + length_table[cur_str[idx]][cur_level]; idx <= idx + 1;
                    end
                end else begin error <= 1; state <= DONE; end
            end

            OUTPUT: begin
                if (result_addr < M) begin
                    result_char <= results[result_addr]; result_addr <= result_addr + 1; result_valid <= 1;
                end else begin result_valid <= 0; done <= 1; state <= DONE; end
            end

            DONE: begin
                if (!start) begin state <= IDLE; done <= 0; result_addr <= 0; end
            end
        endcase
    end
end

endmodule

module castle_danger (
    input wire clk,
    input wire rst_n,
