localparam CHECK = 2'd1;
localparam DONE = 2'd2;

// Internal registers
reg [1:0] state;
reg [1:0] edge_idx;      // 0-3 for four edges
reg [15:0] cross;        // Cross product result
reg is_inside;           // Inside flag
reg first_sign;          // Sign of first edge's cross product
reg degenerate;          // Degeneracy flag

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        danger <= 1'b0;
        done <= 1'b0;
        is_inside <= 1'b0;
        degenerate <= 1'b0;
        edge_idx <= 2'd0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                danger <= 1'b0;
                if (start) begin
                    state <= CHECK;
                    edge_idx <= 2'd0;
                    is_inside <= 1'b1;
                    degenerate <= 1'b0;
                end
            end

            CHECK: begin
                // Compute cross product for current edge and castle
                case (edge_idx)
                    2'd0: cross <= ( (p1_x - p0_x) * (castle_y - p0_y) ) - ( (p1_y - p0_y) * (castle_x - p0_x) );
                    2'd1: cross <= ( (p2_x - p1_x) * (castle_y - p1_y) ) - ( (p2_y - p1_y) * (castle_x - p1_x) );
                    2'd2: cross <= ( (p3_x - p2_x) * (castle_y - p2_y) ) - ( (p3_y - p2_y) * (castle_x - p2_x) );
                    2'd3: cross <= ( (p0_x - p3_x) * (castle_y - p3_y) ) - ( (p0_y - p3_y) * (castle_x - p3_x) );
                endcase
                state <= CHECK + 1;
            end

            CHECK + 1: begin
                // Check degeneracy on first iteration
                if (edge_idx == 2'd0) begin
                    if (((p1_x - p0_x) * (p2_y - p0_y) - (p1_y - p0_y) * (p2_x - p0_x) == 16'd0) ||
                        ((p2_x - p1_x) * (p3_y - p1_y) - (p2_y - p1_y) * (p3_x - p1_x) == 16'd0) ||
                        ((p3_x - p2_x) * (p0_y - p2_y) - (p3_y - p2_y) * (p0_x - p2_x) == 16'd0) ||
                        ((p0_x - p3_x) * (p1_y - p3_y) - (p0_y - p3_y) * (p1_x - p3_x) == 16'd0)) begin
                        degenerate <= 1'b1;
                    end
                    if (cross != 16'd0) first_sign <= cross[15];
                end else begin
                    // Subsequent edges: sign must match first (or be zero)
                    if (cross != 16'd0 && cross[15] != first_sign) begin
                        is_inside <= 1'b0;
                    end
                end

                // Check if castle is exactly on edge
                if (cross == 16'd0) begin
                    // Still counts as inside
                end

                if (edge_idx < 2'd3) begin
                    edge_idx <= edge_idx + 1;
                    state <= CHECK;
                end else begin
                    // Final result
                    if (degenerate) begin
                        danger <= 1'b0;
                    end else begin
                        danger <= is_inside;
                    end
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1'b1;
                if (!start) state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module word_search (
  input clk,
  input rst_n,
  input start,
  input [63:0] query_word,  // 8 characters, 8 bits each
  output reg [15:0] result,
  output reg done
);

  // Database storage (8 words, each 8 bytes)
  reg [63:0] database [0:7];

  // State definitions
  localparam IDLE = 2'b00;
  localparam COMPARE = 2'b01;
  localparam NEXT = 2'b10;
  localparam DONE = 2'b11;

  // Internal registers
  reg [2:0] index;        // 3-bit index for 8 words
  reg [15:0] count;       // number of words compared
  reg [15:0] lcp_sum;     // sum of LCP lengths
  reg [1:0] state, next_state;

  // Current database word being compared
  wire [63:0] current_word;
  assign current_word = database[index];

  // LCP computation - unrolled for 8 characters
  reg [3:0] lcp_temp;
  always @(*) begin
    lcp_temp = 0;
    // Compare each character pair
    if (query_word[7:0] == current_word[7:0]) begin
      lcp_temp = 1;
      if (query_word[15:8] == current_word[15:8]) begin
        lcp_temp = 2;
        if (query_word[23:16] == current_word[23:16]) begin
          lcp_temp = 3;
          if (query_word[31:24] == current_word[31:24]) begin
            lcp_temp = 4;
            if (query_word[39:32] == current_word[39:32]) begin
              lcp_temp = 5;
              if (query_word[47:40] == current_word[47:40]) begin
                lcp_temp = 6;
                if (query_word[55:48] == current_word[55:48]) begin
                  lcp_temp = 7;
                  if (query_word[63:56] == current_word[63:56]) begin
                    lcp_temp = 8;
                  end
                end
              end
            end
          end
        end
      end
    end
  end

  // State machine
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      count <= 0;
      lcp_sum <= 0;
      index <= 0;
      result <= 0;
      done <= 0;
    end else begin
      state <= next_state;
      case (state)
        IDLE: if (start) begin
          count <= 0;
          lcp_sum <= 0;
          index <= 0;
          done <= 0;
        end
        COMPARE: begin
          count <= count + 1;
          lcp_sum <= lcp_sum + lcp_temp;
        end
        NEXT: begin
          if (index < 7) index <= index + 1;
        end
        DONE: begin
          result <= count + lcp_sum;
          done <= 1;
        end
      endcase
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: if (start) next_state = COMPARE;
      COMPARE: begin
        if (lcp_temp == 8)  // Full match found
          next_state = DONE;
        else
          next_state = NEXT;
      end
      NEXT: begin
        if (index < 7)      // More words to compare
          next_state = COMPARE;
        else
          next_state = DONE;
      end
      DONE: next_state = DONE;  // Wait for reset
    endcase
  end

endmodule

