module license_renewal (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,
    input wire [7:0] s1,
    input wire [7:0] s2,
    input wire [7:0] t0,
    input wire [7:0] t1,
    input wire [7:0] t2,
    input wire [7:0] t3,
    input wire [7:0] t4,
    input wire [7:0] t5,
    input wire [7:0] t6,
    input wire [7:0] t7,
    output reg [3:0] max_count,
    output reg done
);
    // State definitions
    localparam IDLE = 3'b000;
    localparam INIT = 3'b001;
    localparam SETUP_SIM = 3'b010;
    localparam CHECK_CUSTOMER = 3'b011;
    localparam NEXT_ASSIGNMENT = 3'b100;
    localparam DONE = 3'b101;

    reg [2:0] state;
    reg [8:0] assignment_counter; // 9-bit to avoid overflow
    reg [8:0] max_assignment;
    reg [3:0] n_reg;
    reg [7:0] s1_reg, s2_reg;
    reg [7:0] t_reg [0:7];
    reg [3:0] customer_index;
    reg [7:0] rem1, rem2;
    reg [3:0] current_count;
    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            assignment_counter <= 0;
            max_assignment <= 0;
            n_reg <= 0;
            s1_reg <= 0;
            s2_reg <= 0;
            for (i = 0; i < 8; i = i + 1) begin
                t_reg[i] <= 0;
            end
            customer_index <= 0;
            rem1 <= 0;
            rem2 <= 0;
            current_count <= 0;
            max_count <= 0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= INIT;
                    end
                end

                INIT: begin
                    // Capture inputs
                    n_reg <= n;
                    s1_reg <= s1;
                    s2_reg <= s2;
                    t_reg[0] <= t0;
                    t_reg[1] <= t1;
                    t_reg[2] <= t2;
                    t_reg[3] <= t3;
                    t_reg[4] <= t4;
                    t_reg[5] <= t5;
                    t_reg[6] <= t6;
                    t_reg[7] <= t7;
                    // Compute max_assignment = (1 << n) - 1
                    max_assignment <= (9'd1 << n) - 9'd1;
                    assignment_counter <= 0;
                    max_count <= 0;
                    state <= SETUP_SIM;
                end

                SETUP_SIM: begin
                    customer_index <= 0;
                    rem1 <= s1_reg;
                    rem2 <= s2_reg;
                    current_count <= 0;
                    state <= CHECK_CUSTOMER;
                end

                CHECK_CUSTOMER: begin
                    if (customer_index >= n_reg) begin
                        // All customers processed for this assignment
                        if (current_count > max_count) begin
                            max_count <= current_count;
                        end
                        state <= NEXT_ASSIGNMENT;
                    end else begin
                        // Get assignment bit
                        if (assignment_counter[customer_index] == 1'b0) begin
                            // Assign to counter1
                            if (t_reg[customer_index] <= rem1) begin
                                rem1 <= rem1 - t_reg[customer_index];
                                current_count <= current_count + 1;
                                customer_index <= customer_index + 1;
                            end else begin
                                // Cannot serve
                                if (current_count > max_count) begin
                                    max_count <= current_count;
                                end
                                state <= NEXT_ASSIGNMENT;
                            end
                        end else begin
                            // Assign to counter2
                            if (t_reg[customer_index] <= rem2) begin
                                rem2 <= rem2 - t_reg[customer_index];
                                current_count <= current_count + 1;
                                customer_index <= customer_index + 1;
                            end else begin
                                // Cannot serve
                                if (current_count > max_count) begin
                                    max_count <= current_count;
                                end
                                state <= NEXT_ASSIGNMENT;
                            end
                        end
                    end
                end

                NEXT_ASSIGNMENT: begin
                    if (assignment_counter + 1 <= max_assignment) begin
                        assignment_counter <= assignment_counter + 1;
                        state <= SETUP_SIM;
                    end else begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module mst_mht_weight (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] N,
    input wire [7:0] x0, x1, x2, x3, x4, x5, x6, x7,
    input wire [7:0] y0, y1, y2, y3, y4, y5, y6, y7,
    output reg [11:0] result,
    output reg done
);

// Module computes Minimum Spanning Tree weight using Manhattan distance
// for a set of up to 8 points with 8-bit coordinates.
//
// Algorithm: Prim's algorithm
// - Supports N = 1 to 8 points (N=0 is invalid)
// - Unused points beyond N are ignored (should be set to 0)
// - Handles duplicate points (distance = 0)
//
// Timing:
// - Assert start for 1 clock cycle to initiate computation
// - done pulses high for 1 cycle when computation completes
// - Computation requires at most 100 clock cycles
// - result holds the MST weight (sum of edge weights)
//
// Reset behavior:
// - On rst_n=0: all internal state cleared, result=0, done=0
// - Minimum 2 clock cycles of reset recommended
//
// Implementation hints:
// - Use state machine with states: IDLE, INIT, FIND_MIN, ADD_VERTEX, UPDATE_DIST, DONE
// - Register visited[7:0] to track vertices in MST
// - Register min_dist[0:7][11:0] for minimum distance to MST
// - Register current result[11:0] accumulates MST weight
// - Manhattan distance: |x1-x2| + |y1-y2| (use absolute value subtraction)
// - State machine loops at most 7 times (N-1 iterations)
// - Each iteration: 1 cycle to find min, 1 cycle to add, up to 8 cycles to update
// - Total cycles ≤ 7*(1+1+8) = 70 cycles

// End of module specification
endmodule

module max_queens_4x4 (
    input clk,
    input rst_n,
    input start,
    input [15:0] broken,  // 1=broken cell, 0=usable
    output reg [3:0] max_queens,
    output reg [15:0] num_ways,
    output reg done
);
    // Parameters
    parameter BOARD_SIZE = 16;
    parameter MAX_TRIANGLES = 560; // Number of triangles in 4x4 board

    // State definitions
    localparam IDLE = 3'b000;
    localparam INIT = 3'b001;
    localparam CHECK_BROKEN = 3'b010;
    localparam POPCOUNT = 3'b011;
    localparam CHECK_TRIANGLE = 3'b100;
    localparam UPDATE_MAX = 3'b101;
    localparam NEXT_SUBSET = 3'b110;
    localparam DONE = 3'b111;

    // Registers
    reg [2:0] state;
    reg [15:0] subset;
    reg [3:0] max_q;
    reg [15:0] ways;
    reg [3:0] popcnt;
    reg [9:0] tri_idx; // 0 to 559
    reg triangle_found;
    reg [15:0] current_mask;
    reg [3:0] bit_idx; // for popcount loop
    reg [15:0] temp_mask; // for triangle check

    // Triangle table: precomputed for 4x4 board
    // Each entry is a 16-bit mask of three cells that form a triangle
    reg [15:0] triangle_mask [0:MAX_TRIANGLES-1];

    // Initialize triangle table (generated by Python script)
    initial begin
        // Example entries (replace with actual generated values)
        triangle_mask[0] = 16'h0000; // placeholder
        triangle_mask[1] = 16'h0000;
        // ... up to triangle_mask[559]
    end

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            subset <= 16'b0;
            max_q <= 4'b0;
            ways <= 16'b0;
            popcnt <= 4'b0;
            tri_idx <= 10'b0;
            triangle_found <= 1'b0;
            done <= 1'b0;
            bit_idx <= 4'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= INIT;
                        done <= 1'b0;
                    end
                end

                INIT: begin
                    subset <= 16'b0;
                    max_q <= 4'b0;
                    ways <= 16'b0;
                    state <= CHECK_BROKEN;
                end

                CHECK_BROKEN: begin
                    // Check if current subset intersects broken cells
                    if (|(subset & broken)) begin
                        // Skip this subset
                        state <= NEXT_SUBSET;
                    end else begin
                        // Initialize popcount variables
                        popcnt <= 4'b0;
                        bit_idx <= 4'b0;
                        state <= POPCOUNT;
                    end
                end

                POPCOUNT: begin
                    if (bit_idx < 4'd16) begin
                        if (subset[bit_idx]) begin
                            popcnt <= popcnt + 1'b1;
                        end
                        bit_idx <= bit_idx + 1'b1;
                    end else begin
                        // Popcount done, initialize triangle check
                        tri_idx <= 10'b0;
                        triangle_found <= 1'b0;
                        state <= CHECK_TRIANGLE;
                    end
                end

                CHECK_TRIANGLE: begin
                    if (tri_idx < MAX_TRIANGLES) begin
                        current_mask <= triangle_mask[tri_idx];
                        // Check if triangle_mask[tri_idx] is subset of subset
                        if ((subset & current_mask) == current_mask) begin
                            triangle_found <= 1'b1;
                            // No need to check further
                            state <= NEXT_SUBSET;
                        end else begin
                            tri_idx <= tri_idx + 1'b1;
                        end
                    end else begin
                        // No triangle found, update max and ways
                        if (triangle_found == 1'b0) begin
                            state <= UPDATE_MAX;
                        end else begin
                            state <= NEXT_SUBSET;
                        end
                    end
                end

                UPDATE_MAX: begin
                    if (popcnt > max_q) begin
                        max_q <= popcnt;
                        ways <= 16'd1;
                    end else if (popcnt == max_q) begin
                        ways <= ways + 1'b1;
                    end
                    state <= NEXT_SUBSET;
                end

                NEXT_SUBSET: begin
                    if (subset < 16'hFFFF) begin
                        subset <= subset + 1'b1;
                        state <= CHECK_BROKEN;
                    end else begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    max_queens <= max_q;
                    num_ways <= ways;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module find_base (
    input clk,
    input rst_n,
    input start,
    input [15:0] y,        // Scaled age (16-bit)
    input [15:0] l,        // Scaled lower bound (16-bit)
    output reg [15:0] b,   // Largest valid base
    output reg done,       // Computation complete
    output reg valid       // 1 if valid base found
);

// Parameters
parameter MAX_B = 16'd256;      // Maximum base to search
parameter DATA_WIDTH = 16;
parameter CLK_DELAY = 4'd10;    // Timeout for division

// State definitions
localparam IDLE = 3'b000;
localparam START_SEARCH = 3'b001;
localparam COMPUTE_REP = 3'b010;
localparam CHECK_DIGITS = 3'b011;
localparam CHECK_VALUE = 3'b100;
localparam UPDATE_B = 3'b101;
localparam DONE = 3'b110;

// Internal registers
reg [2:0] state;
reg [15:0] current_b;
reg [31:0] temp_y;        // 32-bit for division
reg [31:0] temp_b;
reg [15:0] digits[0:15];  // Store up to 16 digits
reg [3:0] digit_count;
reg [15:0] base10_value;
reg [15:0] best_b;
reg found_valid;
reg [3:0] loop_counter;   // For division timeout

// Computation registers
reg [31:0] quotient;
reg [31:0] remainder;
reg [31:0] divisor;
reg div_done;
reg [3:0] digit_idx;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        b <= 16'd0;
        done <= 1'b0;
        valid <= 1'b0;
        current_b <= 16'd0;
        best_b <= 16'd0;
        found_valid <= 1'b0;
        digit_count <= 4'd0;
        base10_value <= 16'd0;
        temp_y <= 32'd0;
        temp_b <= 32'd0;
        loop_counter <= 4'd0;
        div_done <= 1'b0;
        digit_idx <= 4'd0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                valid <= 1'b0;
                if (start) begin
                    state <= START_SEARCH;
                    found_valid <= 1'b0;
                    best_b <= 16'd0;
                    // Start with min(y, MAX_B)
                    current_b <= (y < MAX_B) ? y : MAX_B;
                end
            end

            START_SEARCH: begin
                if (current_b < 16'd2) begin
                    // No valid base found
                    state <= DONE;
                end else begin
                    // Initialize for digit computation
                    temp_y <= {16'd0, y};  // Extend to 32-bit
                    temp_b <= {16'd0, current_b};
                    digit_count <= 4'd0;
                    state <= COMPUTE_REP;
                    loop_counter <= 4'd0;
                    div_done <= 1'b0;
                end
            end

            COMPUTE_REP: begin
                // Compute representation by repeated division
                // This is a simplified division loop
                if (temp_y == 32'd0 || loop_counter >= 4'd15) begin
                    // Done computing representation
                    state <= CHECK_DIGITS;
                    digit_idx <= 4'd0;
                end else if (!div_done) begin
                    // Perform one division step
                    if (temp_y >= temp_b) begin
                        quotient <= temp_y / temp_b;
                        remainder <= temp_y % temp_b;
                        temp_y <= temp_y / temp_b;
                        digits[digit_count] <= temp_y % temp_b;
                        digit_count <= digit_count + 1'b1;
                    end else begin
                        // Last digit
                        digits[digit_count] <= temp_y[15:0];
                        digit_count <= digit_count + 1'b1;
                        temp_y <= 32'd0;
                    end
                    loop_counter <= loop_counter + 1'b1;
                end
            end

            CHECK_DIGITS: begin
                // Check if all digits are ≤ 9
                if (digit_idx >= digit_count) begin
                    // All digits checked, valid
                    state <= CHECK_VALUE;
                    digit_idx <= 4'd0;
                    base10_value <= 16'd0;
                end else if (digits[digit_idx] > 9) begin
                    // Invalid digit, try next b
                    state <= UPDATE_B;
                end else begin
                    digit_idx <= digit_idx + 1'b1;
                end
            end

            CHECK_VALUE: begin
                // Compute base-10 value of digits
                if (digit_idx >= digit_count) begin
                    // Value computed, compare with l
                    if (base10_value >= l) begin
                        // Valid base found
                        found_valid <= 1'b1;
                        best_b <= current_b;
                        // Since we search descending, this is largest
                        state <= DONE;
                    end else begin
                        state <= UPDATE_B;
                    end
                end else begin
                    // base10_value = base10_value * 10 + digits[digit_idx]
                    base10_value <= base10_value * 10 + digits[digit_idx];
                    digit_idx <= digit_idx + 1'b1;
                end
            end

            UPDATE_B: begin
                // Decrement b and continue search
                current_b <= current_b - 16'd1;
                state <= START_SEARCH;
            end

            DONE: begin
                done <= 1'b1;
                if (found_valid) begin
                    b <= best_b;
                    valid <= 1'b1;
                end else begin
                    b <= 16'd0;
                    valid <= 1'b0;
                end
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

Module: min_transmission_cost

// Interface
module min_transmission_cost (
    input  [2:0] N,          // Number of nodes in tree A (1..8)
    input  [2:0] M,          // Number of nodes in tree B (1..8)
    input  [7:0] adj_A_0, adj_A_1, adj_A_2, adj_A_3,
                adj_A_4, adj_A_5, adj_A_6, adj_A_7,  // Adjacency matrix rows for A (bit j = 1 if edge between i and j)
    input  [7:0] adj_B_0, adj_B_1, adj_B_2, adj_B_3,
                adj_B_4, adj_B_5, adj_B_6, adj_B_7,  // Adjacency matrix rows for B
    output reg [31:0] min_cost   // Minimal transmission cost of network C
);

// Fixed maximum sizes
localparam MAX_N = 8;
localparam MAX_M = 8;

// Internal arrays for adjacency and distances
reg [7:0] adj_A [MAX_N-1:0];
reg [7:0] adj_B [MAX_M-1:0];
reg [3:0] dist_A [MAX_N-1:0][MAX_N-1:0]; // 4 bits enough for distances up to 7
reg [3:0] dist_B [MAX_M-1:0][MAX_M-1:0];

// Helper sums
reg [15:0] cost_A, cost_B; // Sum of squared distances within each tree
reg [15:0] S_A [MAX_N-1:0]; // Sum of distances from node u to all nodes in A
reg [15:0] S_A2 [MAX_N-1:0]; // Sum of squared distances from u to all nodes in A
reg [15:0] S_B [MAX_M-1:0];
reg [15:0] S_B2 [MAX_M-1:0];

// Temporary variables
integer i, j, k;
reg [15:0] cross_cost;
reg [31:0] total_cost;
reg [31:0] best_total;

// Assign input rows to internal array
always @(*) begin
    adj_A[0] = adj_A_0; adj_A[1] = adj_A_1; adj_A[2] = adj_A_2; adj_A[3] = adj_A_3;
    adj_A[4] = adj_A_4; adj_A[5] = adj_A_5; adj_A[6] = adj_A_6; adj_A[7] = adj_A_7;
    adj_B[0] = adj_B_0; adj_B[1] = adj_B_1; adj_B[2] = adj_B_2; adj_B[3] = adj_B_3;
    adj_B[4] = adj_B_4; adj_B[5] = adj_B_5; adj_B[6] = adj_B_6; adj_B[7] = adj_B_7;
end

// Main combinational logic
always @(*) begin
    // 1. Compute distance matrix for A using Floyd-Warshall
    for (i = 0; i < MAX_N; i = i + 1) begin
        for (j = 0; j < MAX_N; j = j + 1) begin
            if (i == j) dist_A[i][j] = 0;
            else if (i < N && j < N && adj_A[i][j]) dist_A[i][j] = 1;
            else dist_A[i][j] = 4'hF; // INF (15)
        end
    end
    for (k = 0; k < MAX_N; k = k + 1) begin
        for (i = 0; i < MAX_N; i = i + 1) begin
            for (j = 0; j < MAX_N; j = j + 1) begin
                if (i < N && j < N && k < N) begin
                    if (dist_A[i][k] + dist_A[k][j] < dist_A[i][j])
                        dist_A[i][j] = dist_A[i][k] + dist_A[k][j];
                end
            end
        end
    end

    // 2. Compute distance matrix for B (same process)
    for (i = 0; i < MAX_M; i = i + 1) begin
        for (j = 0; j < MAX_M; j = j + 1) begin
            if (i == j) dist_B[i][j] = 0;
            else if (i < M && j < M && adj_B[i][j]) dist_B[i][j] = 1;
            else dist_B[i][j] = 4'hF;
        end
    end
    for (k = 0; k < MAX_M; k = k + 1) begin
        for (i = 0; i < MAX_M; i = i + 1) begin
            for (j = 0; j < MAX_M; j = j + 1) begin
                if (i < M && j < M && k < M) begin
                    if (dist_B[i][k] + dist_B[k][j] < dist_B[i][j])
                        dist_B[i][j] = dist_B[i][k] + dist_B[k][j];
                end
            end
        end
    end

    // 3. Compute cost_A and cost_B (sum of squared distances for all unordered pairs)
    cost_A = 0;
    for (i = 0; i < MAX_N; i = i + 1) begin
        for (j = i+1; j < MAX_N; j = j + 1) begin
            if (i < N && j < N) begin
                cost_A = cost_A + (dist_A[i][j] * dist_A[i][j]);
            end
        end
    end
    cost_B = 0;
    for (i = 0; i < MAX_M; i = i + 1) begin
        for (j = i+1; j < MAX_M; j = j + 1) begin
            if (i < M && j < M) begin
                cost_B = cost_B + (dist_B[i][j] * dist_B[i][j]);
            end
        end
    end

    // 4. Compute S_A, S_A2 for each node u in A
    for (u = 0; u < MAX_N; u = u + 1) begin
        S_A[u] = 0;
        S_A2[u] = 0;
        if (u < N) begin
            for (a = 0; a < MAX_N; a = a + 1) begin
                if (a < N) begin
                    S_A[u] = S_A[u] + dist_A[a][u];
                    S_A2[u] = S_A2[u] + (dist_A[a][u] * dist_A[a][u]);
                end
            end
        end
    end

    // 5. Compute S_B, S_B2 for each node v in B
    for (v = 0; v < MAX_M; v = v + 1) begin
        S_B[v] = 0;
        S_B2[v] = 0;
        if (v < M) begin
            for (b = 0; b < MAX_M; b = b + 1) begin
                if (b < M) begin
                    S_B[v] = S_B[v] + dist_B[b][v];
                    S_B2[v] = S_B2[v] + (dist_B[b][v] * dist_B[b][v]);
                end
            end
        end
    end

    // 6. Find minimal total cost by trying all pairs (u,v)
    best_total = 32'hFFFFFFFF; // Start with large number
    for (u = 0; u < MAX_N; u = u + 1) begin
        if (u < N) begin
            for (v = 0; v < MAX_M; v = v + 1) begin
                if (v < M) begin
                    // Cross cost formula
                    cross_cost = M * S_A2[u] + N * S_B2[v] + N * M + 2 * S_A[u] * S_B[v] + 2 * M * S_A[u] + 2 * N * S_B[v];
                    total_cost = cost_A + cost_B + cross_cost;
                    if (total_cost < best_total)
                        best_total = total_cost;
                end
            end
        end
    end

    // 7. Assign output
    min_cost = best_total;
end

endmodule

