module secure_door (
    input clk,
    input rst_n,
    input start,
    input [3:0] N,        // number of rooms (1..8)
    input [3:0] M,        // number of doors (0..16)
    input [127:0] edges,  // packed edges: 16 edges, each 8 bits: {u[3:0], v[3:0]}, outside is 8
    output reg [3:0] result,
    output reg done
);

    // State definitions
    localparam S_IDLE = 0;
    localparam S_INIT = 1;
    localparam S_FOR_EDGE = 2;
    localparam S_BFS_INIT = 3;
    localparam S_BFS_LOOP = 4;
    localparam S_BFS_EDGE_LOOP = 5;
    localparam S_BFS_UPDATE = 6;
    localparam S_COUNT = 7;
    localparam S_UPDATE_MAX = 8;
    localparam S_NEXT_EDGE = 9;
    localparam S_DONE = 10;

    // Registers
    reg [4:0] state;
    reg [3:0] edge_idx;      // current edge being processed
    reg [8:0] visited_reg;   // visited nodes (bit i for node i, node 8 is outside)
    reg [3:0] max_protected; // maximum protected rooms found
    reg [3:0] count_curr;    // count for current edge
    reg [3:0] i;             // counter for room iteration
    reg [3:0] j;             // counter for edge iteration
    reg [3:0] iteration_count; // BFS iteration counter
    reg changed;             // flag for BFS progress
    reg [8:0] visited_temp;  // temporary visited for BFS iteration
    reg changed_temp;        // temporary changed for BFS iteration

    // Combinational helpers for edge extraction
    wire [7:0] current_edge = edges[edge_idx*8 +: 8];
    wire [3:0] current_u = current_edge[7:4];
    wire [3:0] current_v = current_edge[3:0];

    wire [7:0] edge_j = edges[j*8 +: 8];
    wire [3:0] u_j = edge_j[7:4];
    wire [3:0] v_j = edge_j[3:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            done <= 0;
            result <= 0;
            edge_idx <= 0;
            visited_reg <= 0;
            max_protected <= 0;
            count_curr <= 0;
            i <= 0;
            j <= 0;
            iteration_count <= 0;
            changed <= 0;
            visited_temp <= 0;
            changed_temp <= 0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (start) state <= S_INIT;
                end

                S_INIT: begin
                    max_protected <= 0;
                    edge_idx <= 0;
                    visited_reg <= 0;
                    state <= S_FOR_EDGE;
                end

                S_FOR_EDGE: begin
                    if (edge_idx >= M) begin
                        state <= S_DONE;
                    end else begin
                        state <= S_BFS_INIT;
                    end
                end

                S_BFS_INIT: begin
                    visited_reg <= 9'b0_0000_1000; // Set outside (node 8) as visited
                    iteration_count <= 0;
                    state <= S_BFS_LOOP;
                end

                S_BFS_LOOP: begin
                    visited_temp <= visited_reg;
                    changed_temp <= 0;
                    j <= 0;
                    state <= S_BFS_EDGE_LOOP;
                end

                S_BFS_EDGE_LOOP: begin
                    if (j < M) begin
                        if (j != edge_idx) begin
                            // Check if edge connects visited to unvisited
                            if (visited_reg[u_j] && !visited_reg[v_j]) begin
                                visited_temp[v_j] <= 1;
                                changed_temp <= 1;
                            end
                            if (visited_reg[v_j] && !visited_reg[u_j]) begin
                                visited_temp[u_j] <= 1;
                                changed_temp <= 1;
                            end
                        end
                        j <= j + 1;
                        if (j + 1 < M) begin
                            state <= S_BFS_EDGE_LOOP;
                        end else begin
                            state <= S_BFS_UPDATE;
                        end
                    end else begin
                        state <= S_BFS_UPDATE;
                    end
                end

                S_BFS_UPDATE: begin
                    visited_reg <= visited_temp;
                    changed <= changed_temp;
                    iteration_count <= iteration_count + 1;
                    if (changed_temp && (iteration_count < 8)) begin
                        state <= S_BFS_LOOP;
                    end else begin
                        state <= S_COUNT;
                        count_curr <= 0;
                        i <= 0;
                    end
                end

                S_COUNT: begin
                    if (i < N) begin
                        if (!visited_reg[i]) begin
                            count_curr <= count_curr + 1;
                        end
                        i <= i + 1;
                        state <= S_COUNT;
                    end else begin
                        state <= S_UPDATE_MAX;
                    end
                end

                S_UPDATE_MAX: begin
                    if (count_curr > max_protected) begin
                        max_protected <= count_curr;
                    end
                    state <= S_NEXT_EDGE;
                end

                S_NEXT_EDGE: begin
                    edge_idx <= edge_idx + 1;
                    state <= S_FOR_EDGE;
                end

                S_DONE: begin
                    done <= 1;
                    result <= max_protected;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module min_max_sum (
    input clk,
    input rst_n,
    input start,
    input [7:0] A0, A1, A2, A3, A4, A5, A6, A7,
    input [7:0] B0, B1, B2, B3, B4, B5, B6, B7,
    output reg [7:0] result,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam SORT_A = 3'b001;
localparam SORT_B = 3'b010;
localparam COMPUTE = 3'b011;
localparam DONE = 3'b100;

// Internal registers
reg [7:0] A [0:7];
reg [7:0] B [0:7];
reg [2:0] state;
reg [2:0] i, j; // counters for bubble sort
reg [3:0] k;    // counter for compute max
reg [7:0] max_sum;

// Load inputs on start
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset arrays
        A[0] <= 8'd0; A[1] <= 8'd0; A[2] <= 8'd0; A[3] <= 8'd0;
        A[4] <= 8'd0; A[5] <= 8'd0; A[6] <= 8'd0; A[7] <= 8'd0;
        B[0] <= 8'd0; B[1] <= 8'd0; B[2] <= 8'd0; B[3] <= 8'd0;
        B[4] <= 8'd0; B[5] <= 8'd0; B[6] <= 8'd0; B[7] <= 8'd0;
    end else if (start && state == IDLE) begin
        // Load input arrays
        A[0] <= A0; A[1] <= A1; A[2] <= A2; A[3] <= A3;
        A[4] <= A4; A[5] <= A5; A[6] <= A6; A[7] <= A7;
        B[0] <= B0; B[1] <= B1; B[2] <= B2; B[3] <= B3;
        B[4] <= B4; B[5] <= B5; B[6] <= B6; B[7] <= B7;
    end
end

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        i <= 3'd0;
        j <= 3'd0;
        k <= 4'd0;
        max_sum <= 8'd0;
        result <= 8'd0;
        done <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    state <= SORT_A;
                    i <= 3'd0;
                    j <= 3'd0;
                end
            end

            SORT_A: begin
                if (i < 3'd7) begin
                    if (j < 3'd7 - i) begin
                        // Compare and swap
                        if (A[j] > A[j+1]) begin
                            A[j] <= A[j+1];
                            A[j+1] <= A[j];
                        end
                        j <= j + 1;
                    end else begin
                        j <= 3'd0;
                        i <= i + 1;
                    end
                end else begin
                    // Done sorting A
                    i <= 3'd0;
                    j <= 3'd0;
                    state <= SORT_B;
                end
            end

            SORT_B: begin
                if (i < 3'd7) begin
                    if (j < 3'd7 - i) begin
                        // Compare and swap for descending order
                        if (B[j] < B[j+1]) begin
                            B[j] <= B[j+1];
                            B[j+1] <= B[j];
                        end
                        j <= j + 1;
                    end else begin
                        j <= 3'd0;
                        i <= i + 1;
                    end
                end else begin
                    // Done sorting B
                    i <= 3'd0;
                    j <= 3'd0;
                    k <= 4'd0;
                    max_sum <= 8'd0;
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                if (k < 4'd8) begin
                    if (A[k] + B[k] > max_sum) begin
                        max_sum <= A[k] + B[k];
                    end
                    k <= k + 1;
                end else begin
                    result <= max_sum;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module SpyIDCounter #(
    parameter MAX_N = 8,
    parameter MAX_M = 6
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,              // ID length (1 to MAX_N)
    input wire [3:0] pattern_len,    // Pattern length (1 to MAX_M)
    input wire [MAX_M-1:0] pattern_mask, // 1= fixed 1, 0= wildcard
    output reg [15:0] result,
    output reg done
);

// Internal state for DP
reg [7:0] dp_vector [0:(2*2**(MAX_M-1)-1)]; // 64 counters, 8 bits each
reg [3:0] current_pos;
reg computing;
reg [15:0] result_reg;
reg start_delayed;

// Helper signals
wire [MAX_M-1:0] mask_eff;
assign mask_eff = pattern_mask & ((1 << pattern_len) - 1);

// State encoding: {has_match, suffix}
// suffix width = pattern_len - 1 bits (stored in MAX_M-1 bits)

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset
        result <= 16'd0;
        done <= 1'b0;
        computing <= 1'b0;
        current_pos <= 4'd0;
        start_delayed <= 1'b0;
        // Clear dp_vector
        for (integer i = 0; i < (2*2**(MAX_M-1)); i = i + 1) begin
            dp_vector[i] <= 8'd0;
        end
    end else begin
        done <= 1'b0;
        start_delayed <= start;

        if (start && !start_delayed) begin
            // Start pulse detected
            current_pos <= 4'd0;

            if (pattern_len > n) begin
                // Case 1: pattern longer than ID
                result <= 16'd0;
                done <= 1'b1;
                computing <= 1'b0;
            end else if (pattern_len == n) begin
                // Case 2: pattern length equals ID length
                // Count wildcards = n - popcount(pattern_mask[0:n-1])
                // Result = 2^wildcards
                integer wildcards = n - popcount(mask_eff);
                result <= (wildcards >= 0 && wildcards <= 16) ? (16'd1 << wildcards) : 16'd0;
                done <= 1'b1;
                computing <= 1'b0;
            end else begin
                // Case 3: pattern length < ID length
                // Initialize DP vector
                for (integer i = 0; i < (2*2**(MAX_M-1)); i = i + 1) begin
                    dp_vector[i] <= 8'd0;
                end
                // Initial state: has_match=0, suffix=0, count=1
                dp_vector[0] <= 8'd1; // State index 0 = {0, 0}
                computing <= 1'b1;
            end
        end else if (computing) begin
            if (current_pos < n) begin
                // Perform DP transition for this position
                // Compute next_dp_vector from current dp_vector
                // This is combinational logic, but we implement it sequentially here for clarity

                // For each state in dp_vector
                for (integer state_idx = 0; state_idx < (2*2**(MAX_M-1)); state_idx = state_idx + 1) begin
                    if (dp_vector[state_idx] != 8'd0) begin
                        // Extract has_match and suffix from state_idx
                        // state_idx = {has_match, suffix} where suffix is pattern_len-1 bits
                        wire has_match = state_idx[MAX_M-1];
                        wire [MAX_M-2:0] suffix = state_idx[MAX_M-2:0];

                        // For bit = 0 and 1
                        for (integer bit_val = 0; bit_val < 2; bit_val = bit_val + 1) begin
                            // Compute new suffix
                            wire [MAX_M-2:0] new_suffix = ((suffix << 1) | bit_val) & ((1 << (pattern_len-1)) - 1);

                            // Check for match
                            wire match;
                            if (current_pos >= pattern_len - 1) begin
                                // We have enough bits to check a full substring
                                wire [MAX_M-1:0] full_substring = (suffix << 1) | bit_val;
                                match = ((full_substring & mask_eff) == mask_eff);
                            end else begin
                                match = 1'b0;
                            end

                            wire new_has_match = has_match | match;

                            // Compute new state index
                            wire [MAX_M-1:0] new_state_idx = {new_has_match, new_suffix};

                            // Add count to next_dp_vector[new_state_idx]
                            // This needs to be done in a separate always block or using temporary storage
                            // For simplicity, we'll use a separate combinational block
                        end
                    end
                end

                current_pos <= current_pos + 1'b1;
            end else begin
                // Finished DP: compute result
                // Sum all states where has_match = 1
                result_reg <= 16'd0;
                for (integer state_idx = 0; state_idx < (2*2**(MAX_M-1)); state_idx = state_idx + 1) begin
                    if (state_idx[MAX_M-1] == 1'b1) begin // has_match bit
                        result_reg <= result_reg + dp_vector[state_idx];
                    end
                end
                result <= result_reg;
                done <= 1'b1;
                computing <= 1'b0;
            end
        end
    end
end

// Helper function to count set bits (popcount)
function integer popcount(input [MAX_M-1:0] val);
    integer i;
    popcount = 0;
    for (i = 0; i < MAX_M; i = i + 1) begin
        if (val[i]) popcount = popcount + 1;
    end
endfunction

endmodule

module maze_escape (
    input clk,
    input rst_n,
    input start,
    input [127:0] grid_data,  // 8x8 grid, 2 bits per cell: 00=wall, 01=passable, 10=Joe, 11=Fire
    output reg [5:0] result,   // 0-63 for exit time, 6'b111111 for IMPOSSIBLE
    output reg done
);

// Internal state machine states
localparam IDLE = 0;
localparam FIRE_BFS_INIT = 1;
localparam FIRE_BFS_PROCESS = 2;
localparam FIRE_BFS_CHECK = 3;
localparam JOE_BFS_INIT = 4;
localparam JOE_BFS_PROCESS = 5;
localparam JOE_BFS_CHECK = 6;
localparam DONE = 7;

reg [2:0] state;

// Grid storage (8x8, 2 bits per cell)
reg [1:0] grid [0:7][0:7];
// Fire arrival times (0-63, 127=inf)
reg [6:0] fire_time [0:7][0:7];
// Joe visited flags
reg visited [0:7][0:7];

// Fire queue: {row[2:0], col[2:0]}
reg [5:0] fire_queue [0:63];
reg [5:0] fire_q_wr, fire_q_rd;
wire fire_q_empty = (fire_q_wr == fire_q_rd);
wire fire_q_full = (fire_q_wr == fire_q_rd + 1);

// Joe queue: {row[2:0], col[2:0], time[5:0]}
reg [11:0] joe_queue [0:63];
reg [5:0] joe_q_wr, joe_q_rd;
wire joe_q_empty = (joe_q_wr == joe_q_rd);
wire joe_q_full = (joe_q_wr == joe_q_rd + 1);

// Current processing registers
reg [2:0] cur_r, cur_c;
reg [6:0] cur_time;
reg [1:0] dir;  // 0:up, 1:down, 2:left, 3:right

// Neighbor calculation
wire [2:0] nr = (dir == 0) ? cur_r - 1 : (dir == 1) ? cur_r + 1 : cur_r;
wire [2:0] nc = (dir == 2) ? cur_c - 1 : (dir == 3) ? cur_c + 1 : cur_c;
wire in_bounds = (nr < 8) && (nc < 8);
wire [1:0] cell = grid[nr][nc];

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        fire_q_wr <= 0; fire_q_rd <= 0;
        joe_q_wr <= 0; joe_q_rd <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Load grid from input
                    for (integer i=0; i<8; i=i+1) begin
                        for (integer j=0; j<8; j=j+1) begin
                            grid[i][j] <= grid_data[(i*16) + (j*2) +: 2];
                        end
                    end
                    state <= FIRE_BFS_INIT;
                end
            end

            FIRE_BFS_INIT: begin
                // Reset fire times
                for (integer i=0; i<8; i=i+1)
                    for (integer j=0; j<8; j=j+1)
                        fire_time[i][j] <= 7'b1111111;
                // Enqueue all fire cells
                for (integer i=0; i<8; i=i+1) begin
                    for (integer j=0; j<8; j=j+1) begin
                        if (grid[i][j] == 2'b11 && !fire_q_full) begin
                            fire_queue[fire_q_wr] <= {i[2:0], j[2:0]};
                            fire_q_wr <= fire_q_wr + 1;
                            fire_time[i][j] <= 0;
                        end
                    end
                end
                state <= FIRE_BFS_PROCESS;
            end

            FIRE_BFS_PROCESS: begin
                if (!fire_q_empty) begin
                    {cur_r, cur_c} <= fire_queue[fire_q_rd];
                    fire_q_rd <= fire_q_rd + 1;
                    cur_time <= fire_time[cur_r][cur_c];
                    dir <= 0;
                    state <= FIRE_BFS_CHECK;
                end else begin
                    state <= JOE_BFS_INIT;
                end
            end

            FIRE_BFS_CHECK: begin
                if (in_bounds && cell != 2'b00 && fire_time[nr][nc] == 7'b1111111) begin
                    fire_time[nr][nc] <= cur_time + 1;
                    if (!fire_q_full) begin
                        fire_queue[fire_q_wr] <= {nr, nc};
                        fire_q_wr <= fire_q_wr + 1;
                    end
                end
                if (dir < 3) begin
                    dir <= dir + 1;
                end else begin
                    state <= FIRE_BFS_PROCESS;
                end
            end

            JOE_BFS_INIT: begin
                // Reset visited
                for (integer i=0; i<8; i=i+1)
                    for (integer j=0; j<8; j=j+1)
                        visited[i][j] <= 0;
                // Find and enqueue Joe
                for (integer i=0; i<8; i=i+1) begin
                    for (integer j=0; j<8; j=j+1) begin
                        if (grid[i][j] == 2'b10 && !joe_q_full) begin
                            joe_queue[joe_q_wr] <= {i[2:0], j[2:0], 6'b000000};
                            joe_q_wr <= joe_q_wr + 1;
                            visited[i][j] <= 1;
                        end
                    end
                end
                state <= JOE_BFS_PROCESS;
            end

            JOE_BFS_PROCESS: begin
                if (!joe_q_empty) begin
                    {cur_r, cur_c, cur_time[5:0]} <= joe_queue[joe_q_rd];
                    joe_q_rd <= joe_q_rd + 1;
                    dir <= 0;
                    state <= JOE_BFS_CHECK;
                end else begin
                    result <= 6'b111111;
                    done <= 1;
                    state <= DONE;
                end
            end

            JOE_BFS_CHECK: begin
                // Check boundary exit
                if (cur_r == 0 || cur_r == 7 || cur_c == 0 || cur_c == 7) begin
                    result <= cur_time[5:0];
                    done <= 1;
                    state <= DONE;
                end else if (dir < 3) begin
                    // Check neighbor for movement
                    if (in_bounds && cell != 2'b00 && !visited[nr][nc] && (fire_time[nr][nc] > cur_time + 1)) begin
                        if (!joe_q_full) begin
                            joe_queue[joe_q_wr] <= {nr, nc, cur_time[5:0] + 1};
                            joe_q_wr <= joe_q_wr + 1;
                            visited[nr][nc] <= 1;
                        end
                    end
                    dir <= dir + 1;
                end else begin
                    state <= JOE_BFS_PROCESS;
                end
            end

            DONE: begin
                // Wait for reset
            end
        endcase
    end
end

endmodule

module score_calculator (
    input [3:0] N,
    input [63:0] x [0:7],
    input [63:0] y [0:7],
    output reg [63:0] result
);

    always @(*) begin
        result = 0;
        if (N >= 3) begin
            for (integer i = 0; i < N; i = i + 1) begin
                for (integer j = i+1; j < N; j = j + 1) begin
                    for (integer k = j+1; k < N; k = k + 1) begin
                        // Compute twice the area of triangle (i,j,k)
                        result = (result + twice_area(i,j,k)) % 1000003;
                    end
                end
            end
        end
    end

    function automatic [63:0] twice_area;
        input [2:0] i, j, k;
        reg signed [63:0] x1, y1, x2, y2, x3, y3;
        reg signed [63:0] area;
        reg [63:0] abs_area;
    begin
        x1 = x[i]; y1 = y[i];
        x2 = x[j]; y2 = y[j];
        x3 = x[k]; y3 = y[k];
        area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
        if (area < 0)
          abs_area = -area;
        else
          abs_area = area;
        twice_area = abs_area;
    end
    endfunction

endmodule

