        # Reset
        await reset_dut(dut)

    # Test cases: (N, x_list, y_list, expected_result, description)
    test_cases = [
        (
            6,
            [1, 4, 1, 10, 10, 7, 0, 0],
            [1, 1, 5, 10, 8, 10, 0, 0],
            7,
            "Example 1: 6 customers"
        ),
        (
            7,
            [0, 100, 0, 100, 50, 0, 100, 0],
            [0, 100, 100, 0, 50, 50, 50, 0],
            100,
            "Example 2: 7 customers"
        ),
    ]

    passed = 0
    failed = 0

    for i, (N, x_vals, y_vals, expected, description) in enumerate(test_cases):
        cocotb.log.info(f"Test {i+1}: {description}")
        cocotb.log.info(f"  N={N}, expected={expected}")

        try:
