module latest_departure #(
    parameter MAX_N = 8,
    parameter MAX_M = 16,
    parameter DATA_WIDTH = 8,   // time values up to 255
    parameter IDX_WIDTH = 3     // index width for up to 8 nodes
)(
    // Clock and reset
    input wire clk,
    input wire rst_n,           // active-low synchronous reset
    input wire start,           // pulse high to start computation

    // Problem dimensions
    input wire [IDX_WIDTH-1:0] n,      // number of nodes (2..8)
    input wire [IDX_WIDTH-1:0] m,      // number of edges (1..16)
    input wire [DATA_WIDTH-1:0] s,     // meeting time (0..255)

    // Edge definitions (array of ports)
    input wire [IDX_WIDTH-1:0] u_arr [0:MAX_M-1],   // from node
    input wire [IDX_WIDTH-1:0] v_arr [0:MAX_M-1],   // to node
    input wire [DATA_WIDTH-1:0] t0_arr [0:MAX_M-1], // first departure
    input wire [DATA_WIDTH-1:0] p_arr [0:MAX_M-1],  // period
    input wire [DATA_WIDTH-1:0] d_arr [0:MAX_M-1],  // travel time

    // Outputs
    output reg [DATA_WIDTH-1:0] result,  // latest departure from stop 0
    output reg done,                    // asserted for 1 cycle when finished
    output reg impossible               // high if no solution
);

// State definitions
localparam S_IDLE        = 3'd0;
localparam S_INIT        = 3'd1;
localparam S_ITER_LOOP   = 3'd2;
localparam S_EDGE_PROCESS = 3'd3;
localparam S_DONE        = 3'd4;

// Internal registers
reg [2:0] state;
reg [DATA_WIDTH-1:0] L [0:MAX_N-1];    // latest departure times per node
reg [IDX_WIDTH-1:0] iteration_count;
reg [IDX_WIDTH-1:0] edge_index;
reg changed;                           // flag to detect convergence

// Edge data registers
reg [IDX_WIDTH-1:0] u_reg, v_reg;
reg [DATA_WIDTH-1:0] t0_reg, p_reg, d_reg;

// Combinational logic for departure time calculation
wire [DATA_WIDTH:0] diff = (L[v_reg] >= d_reg + t0_reg) ? (L[v_reg] - d_reg - t0_reg) : 0;
wire [DATA_WIDTH-1:0] k = (L[v_reg] >= d_reg + t0_reg) ? (diff / p_reg) : 0;
wire [DATA_WIDTH-1:0] t_dep = (L[v_reg] >= d_reg + t0_reg) ? (t0_reg + k * p_reg) : 0;

// State machine and datapath
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        impossible <= 0;
        result <= 0;
        changed <= 0;
        iteration_count <= 0;
        edge_index <= 0;
        // Invalidate all L
        for (integer i = 0; i < MAX_N; i = i + 1) L[i] <= 8'hFF;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                impossible <= 0;
                if (start) begin
                    state <= S_INIT;
                end
            end

            S_INIT: begin
                // Invalidate all nodes
                for (integer i = 0; i < MAX_N; i = i + 1) L[i] <= 8'hFF;
                // Set destination departure time = meeting time
                L[n-1] <= s;
                iteration_count <= 0;
                changed <= 0;
                state <= S_ITER_LOOP;
            end

            S_ITER_LOOP: begin
                // If we have done n iterations without change, finish
                if (iteration_count >= n) begin
                    if (changed) begin
                        // More iterations needed
                        iteration_count <= 0;
                        changed <= 0;
                        edge_index <= 0;
                        state <= S_EDGE_PROCESS;
                    end else begin
                        // No changes in last iteration -> convergence
                        state <= S_DONE;
                    end
                end else begin
                    // Start processing edges for this iteration
                    edge_index <= 0;
                    state <= S_EDGE_PROCESS;
                end
            end

            S_EDGE_PROCESS: begin
                if (edge_index >= m) begin
                    // Finished this iteration
                    iteration_count <= iteration_count + 1;
                    state <= S_ITER_LOOP;
                end else begin
                    // Load edge data
                    u_reg <= u_arr[edge_index];
                    v_reg <= v_arr[edge_index];
                    t0_reg <= t0_arr[edge_index];
                    p_reg <= p_arr[edge_index];
                    d_reg <= d_arr[edge_index];

                    // Check if v has a valid departure time
                    if (L[v_reg] != 8'hFF && L[v_reg] >= d_reg + t0_reg) begin
                        // Combinational computation ready in same cycle
                        if (t_dep > L[u_reg] || L[u_reg] == 8'hFF) begin
                            L[u_reg] <= t_dep;
                            changed <= 1;
                        end
                    end
                    edge_index <= edge_index + 1;
                end
            end

            S_DONE: begin
                done <= 1;
                if (L[0] != 8'hFF) begin
                    result <= L[0];
                    impossible <= 0;
                end else begin
                    result <= 0;
                    impossible <= 1;
                end
                state <= S_IDLE;
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

module laser_tag #(
    parameter WIDTH = 32,
    parameter FRAC_BITS = 16
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [WIDTH-1:0] x1, y1, x2, y2, x3, y3,
    output reg [WIDTH-1:0] low_y,
    output reg [WIDTH-1:0] high_y,
    output reg low_inf,
    output reg high_inf,
    output reg can_hit,
    output reg done
);
    // State definitions
    localparam IDLE = 0;
    localparam COMPUTE_A_B = 1;
    localparam COMPUTE_C = 2;
    localparam COMPUTE_D = 3;
    localparam COMPUTE_DENOM = 4;
    localparam COMPUTE_S_PRIME = 5;
    localparam CHECK_CAN_HIT = 6;
    localparam COMPUTE_ENDPOINT1 = 7;
    localparam COMPUTE_ENDPOINT2 = 8;
    localparam DETERMINE_RESULT = 9;
    localparam DONE = 10;

    reg [4:0] state;
    reg [WIDTH-1:0] A, B, C, D, denom;
    reg [WIDTH-1:0] Sx, Sy;  // Virtual shooter coordinates
    reg [WIDTH-1:0] x_min, x_max;
    reg [WIDTH-1:0] dx, dy, t, y_wall;
    reg [1:0] endpoint_count;
    reg [WIDTH-1:0] y_values[0:1];
    reg inf_flags[0:1];  // 0=finite, 1=infinite
    reg signed_flag[0:1]; // For infinity direction: 0=negative, 1=positive

    // Helper: Fixed-point multiplication
    function [WIDTH-1:0] mult;
        input [WIDTH-1:0] a, b;
        begin
            mult = (a * b) >>> FRAC_BITS;
        end
    endfunction

    // Helper: Fixed-point division (simplified - assumes denominator is power of 2)
    // Real implementation would need sequential divider
    function [WIDTH-1:0] divide;
        input [WIDTH-1:0] num, denom;
        begin
            // For simulation, use integer division
            divide = num / denom;
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            low_inf <= 0;
            high_inf <= 0;
            can_hit <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Latch inputs
                        state <= COMPUTE_A_B;
                        x_min <= (x1 < x2) ? x1 : x2;
                        x_max <= (x1 > x2) ? x1 : x2;
                        endpoint_count <= 0;
                    end
                end

                COMPUTE_A_B: begin
                    // A = y2 - y1, B = x1 - x2
                    A <= y2 - y1;
                    B <= x1 - x2;
                    state <= COMPUTE_C;
                end

                COMPUTE_C: begin
                    // C = -(A*x1 + B*y1)
                    C <= -(mult(A, x1) + mult(B, y1));
                    state <= COMPUTE_D;
                end

                COMPUTE_D: begin
                    // D = A*x3 + B*y3 + C
                    D <= mult(A, x3) + mult(B, y3) + C;
                    state <= COMPUTE_DENOM;
                end

                COMPUTE_DENOM: begin
                    // denom = A*A + B*B
                    denom <= mult(A, A) + mult(B, B);
                    state <= COMPUTE_S_PRIME;
                end

                COMPUTE_S_PRIME: begin
                    // Sx = x3 - (2*A*D)/denom
                    // Sy = y3 - (2*B*D)/denom
                    if (denom != 0) begin
                        Sx <= x3 - (2 * mult(A, D)) / denom;
                        Sy <= y3 - (2 * mult(B, D)) / denom;
                    end else begin
                        Sx <= 0;
                        Sy <= 0;
                    end
                    state <= CHECK_CAN_HIT;
                end

                CHECK_CAN_HIT: begin
                    // Check if mirror intersects interval between 0 and Sx
                    if ((Sx > 0 && x_min >= Sx) || (Sx < 0 && x_max <= Sx) || (Sx == 0)) begin
                        can_hit <= 0;
                        state <= DONE;
                    end else begin
                        can_hit <= 1;
                        state <= COMPUTE_ENDPOINT1;
                    end
                end

                COMPUTE_ENDPOINT1, COMPUTE_ENDPOINT2: begin
                    if (can_hit) begin
                        // Get current endpoint
                        if (state == COMPUTE_ENDPOINT1) begin
                            dx <= x1 - Sx;
                            dy <= y1 - Sy;
                        end else begin
                            dx <= x2 - Sx;
                            dy <= y2 - Sy;
                        end
                        // Check for infinite case (dx == 0)
                        if (dx == 0) begin
                            inf_flags[endpoint_count] <= 1;
                            // Determine infinity direction
                            if (dy > 0) begin
                                signed_flag[endpoint_count] <= 1; // positive infinity
                            end else begin
                                signed_flag[endpoint_count] <= 0; // negative infinity
                            end
                        end else begin
                            inf_flags[endpoint_count] <= 0;
                            // Compute t = -Sx / dx
                            t <= (-Sx) / dx;  // Integer division, need proper handling
                            // Compute y = Sy + t * dy
                            y_values[endpoint_count] <= Sy + mult(t, dy);
                        end
                        endpoint_count <= endpoint_count + 1;
                        if (endpoint_count == 0) begin
                            state <= COMPUTE_ENDPOINT2;
                        end else begin
                            state <= DETERMINE_RESULT;
                        end
                    end
                end

                DETERMINE_RESULT: begin
                    // Determine low and high from y_values and inf_flags
                    if (inf_flags[0] && inf_flags[1]) begin
                        low_inf <= signed_flag[0] ? 0 : 1;
                        high_inf <= signed_flag[1] ? 1 : 0;
                        low_y <= 0;
                        high_y <= 0;
                    end else if (inf_flags[0]) begin
                        low_inf <= 1;
                        high_inf <= 0;
                        low_y <= 0;
                        high_y <= y_values[1];
                    end else if (inf_flags[1]) begin
                        low_inf <= 0;
                        high_inf <= 1;
                        low_y <= y_values[0];
                        high_y <= 0;
                    end else begin
                        low_inf <= 0;
                        high_inf <= 0;
                        low_y <= (y_values[0] < y_values[1]) ? y_values[0] : y_values[1];
                        high_y <= (y_values[0] > y_values[1]) ? y_values[0] : y_values[1];
                    end
                    state <= DONE;
                end

                DONE: begin
                    done <= 1;
                    if (!start) begin
                        state <= IDLE;
                        done <= 0;
                    end
                end
            endcase
        end
    end
endmodule

module xray_sim #(
    parameter N = 8,           // Max energy bins (scaled from 200)
    parameter M = 2,           // Max simulation energies (scaled from n)
    parameter K_WIDTH = 8,     // Photon count width (scaled from 10^6)
    parameter COST_WIDTH = 32, // Q16.16 fixed-point result
    parameter IDX_WIDTH = 3,   // Index width (log2(N))
    parameter E_WIDTH = 8      // Energy index width (1-8)
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [IDX_WIDTH-1:0] n,      // Actual bins (1-8)
    input wire [1:0] m,                // Actual sim energies (1-2)
    input wire [(K_WIDTH*N)-1:0] k_packed,  // Packed: k[0] in LSB
    output reg [COST_WIDTH-1:0] result,
    output reg done
);

// Unpack k_packed into array for easy access
wire [K_WIDTH-1:0] k [0:N-1];
generate
    for (genvar i = 0; i < N; i = i + 1) begin : unpack_k
        assign k[i] = k_packed[(i+1)*K_WIDTH-1 : i*K_WIDTH];
    end
endgenerate

// State machine encoding
localparam IDLE = 3'b000;
localparam SETUP = 3'b001;
localparam SEARCH = 3'b010;
localparam CALC_COST = 3'b011;
localparam UPDATE_MIN = 3'b100;
localparam FINISH = 3'b101;

reg [2:0] state;
reg [E_WIDTH-1:0] e1, e2;          // Current test energies (indices 1-8)
reg [E_WIDTH-1:0] best_e1, best_e2; // Best energies found
reg [COST_WIDTH-1:0] min_cost;      // Minimum cost
reg [COST_WIDTH-1:0] current_cost;  // Cost for current energies
reg [3:0] point_idx;               // Current point being evaluated
reg [1:0] m_reg;                   // Registered m
reg [IDX_WIDTH-1:0] n_reg;         // Registered n

// Temporary calculations
wire signed [COST_WIDTH*2-1:0] dist1, dist2;
wire [COST_WIDTH-1:0] min_dist_sq;
wire [COST_WIDTH*2-1:0] weighted_dist;

// Signed distance calculations (allow negative)
assign dist1 = signed'({{COST_WIDTH{1'b0}}, point_idx + 1}) - signed'({{COST_WIDTH{1'b0}}, e1});
assign dist2 = signed'({{COST_WIDTH{1'b0}}, point_idx + 1}) - signed'({{COST_WIDTH{1'b0}}, e2});

// Find minimum squared distance (simplified for m=2)
assign min_dist_sq = (dist1 < 0 ? -dist1 : dist1) < (dist2 < 0 ? -dist2 : dist2) ? 
                     (dist1 * dist1) : (dist2 * dist2);

// Weighted distance (k[point_idx] * min_dist_sq)
assign weighted_dist = k[point_idx] * min_dist_sq;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        min_cost <= {COST_WIDTH{1'b1}}; // Initialize to max
        current_cost <= 0;
        e1 <= 1;
        e2 <= 1;
        point_idx <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    n_reg <= n;
                    m_reg <= m;
                    state <= SETUP;
                    e1 <= 1;
                    e2 <= 1;
                    min_cost <= {COST_WIDTH{1'b1}};
                end
            end

            SETUP: begin
                // Initialize search bounds
                if (m_reg == 1) begin
                    // For m=1, only e1 matters, e2 unused
                    state <= SEARCH;
                    e1 <= 1;
                    e2 <= 1;
                end else begin
                    state <= SEARCH;
                    e1 <= 1;
                    e2 <= 1;
                end
            end

            SEARCH: begin
                // Check if search complete
                if (e1 > n_reg) begin
                    state <= FINISH;
                end else if (m_reg == 1) begin
                    // For m=1, only e1 is valid
                    if (e1 > n_reg) begin
                        state <= FINISH;
                    end else begin
                        state <= CALC_COST;
                        current_cost <= 0;
                        point_idx <= 0;
                    end
                end else begin
                    // For m=2, need to check e2
                    if (e2 > n_reg) begin
                        e1 <= e1 + 1;
                        e2 <= 1;
                    end else begin
                        state <= CALC_COST;
                        current_cost <= 0;
                        point_idx <= 0;
                    end
                end
            end

            CALC_COST: begin
                // Accumulate cost for all points
                if (point_idx < n_reg) begin
                    current_cost <= current_cost + weighted_dist[COST_WIDTH-1:0];
                    point_idx <= point_idx + 1;
                end else begin
                    state <= UPDATE_MIN;
                end
            end

            UPDATE_MIN: begin
                if (current_cost < min_cost) begin
                    min_cost <= current_cost;
                    best_e1 <= e1;
                    best_e2 <= e2;
                end
                // Next combination
                if (m_reg == 1) begin
                    e1 <= e1 + 1;
                    state <= SEARCH;
                end else begin
                    e2 <= e2 + 1;
                    state <= SEARCH;
                end
            end

            FINISH: begin
                // Convert cost to Q16.16 (already in fixed units of k*energy^2)
                // For true Q16.16, we need to scale by 1/65536, but since we're
                // computing integer sum of squares, we return the raw value
                // and let testbench interpret as fixed-point
                result <= min_cost;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module ContestScheduler (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] Z,          // Number of years (1 or 2)
    input wire [2:0] dow_oct1_0, // Day of week of Oct 1, year 2019 (0=Sun, 1=Mon, ..., 6=Sat)
    input wire [2:0] dow_oct1_1, // Day of week of Oct 1, year 2020
    input wire [30:0] forbidden_mask_0, // 31-bit mask, bit i-1 = 1 if day i is forbidden
    input wire [30:0] forbidden_mask_1,
    output reg [4:0] day0,       // Chosen day for year 2019 (1-31)
    output reg [4:0] day1,       // Chosen day for year 2020 (1-31, 0 if not used)
    output reg [16:0] total_penalty,
    output reg done
);

    // Parameters
    parameter MAX_ALLOWED = 5; // Max allowed days per year

    // Function to compute Friday before Thanksgiving (second Monday in October)
    function [4:0] compute_tsg_friday;
        input [2:0] dow; // day of week of Oct 1
        integer offset, first_monday, second_monday;
        begin
            offset = (1 - dow + 7) % 7;          // days to first Monday
            first_monday = 1 + offset;
            second_monday = first_monday + 7;
            compute_tsg_friday = second_monday - 2;
        end
    endfunction

    // Internal signals for allowed days
    reg [4:0] allowed_days_0 [0:MAX_ALLOWED-1];
    reg [2:0] allowed_count_0;
    reg [4:0] allowed_days_1 [0:MAX_ALLOWED-1];
    reg [2:0] allowed_count_1;
    reg [4:0] tsg_friday_0, tsg_friday_1;

    // Combinational logic to compute allowed days for year 0
    integer d;
    reg is_friday, is_forbidden, is_tsg;
    always @(*) begin
        tsg_friday_0 = compute_tsg_friday(dow_oct1_0);
        allowed_count_0 = 0;
        for (d = 1; d <= 31; d = d + 1) begin
            is_friday = ((dow_oct1_0 + d - 1) % 7 == 5);
            is_forbidden = forbidden_mask_0[d-1];
            is_tsg = (d == tsg_friday_0);
            if (is_friday && !is_forbidden && !is_tsg) begin
                if (allowed_count_0 < MAX_ALLOWED) begin
                    allowed_days_0[allowed_count_0] = d;
                    allowed_count_0 = allowed_count_0 + 1;
                end
            end
        end
    end

    // Combinational logic to compute allowed days for year 1
    always @(*) begin
        tsg_friday_1 = compute_tsg_friday(dow_oct1_1);
        allowed_count_1 = 0;
        for (d = 1; d <= 31; d = d + 1) begin
            is_friday = ((dow_oct1_1 + d - 1) % 7 == 5);
            is_forbidden = forbidden_mask_1[d-1];
            is_tsg = (d == tsg_friday_1);
            if (is_friday && !is_forbidden && !is_tsg) begin
                if (allowed_count_1 < MAX_ALLOWED) begin
                    allowed_days_1[allowed_count_1] = d;
                    allowed_count_1 = allowed_count_1 + 1;
                end
            end
        end
    end

    // DP combinational logic (for Z=1 or Z=2)
    integer i0, i1;
    reg [16:0] best_penalty;
    reg [4:0] best_day0, best_day1;
    reg [16:0] penalty, penalty0, penalty1, total_pen;
    reg [4:0] day0_val, day1_val;

    always @(*) begin
        best_penalty = 17'h1FFFF; // Large value
        best_day0 = 0;
        best_day1 = 0;
        if (Z >= 1) begin
            if (Z == 1) begin
                // Only year 0
                for (i0 = 0; i0 < allowed_count_0; i0 = i0 + 1) begin
                    day0_val = allowed_days_0[i0];
                    penalty = (day0_val - 12) * (day0_val - 12);
                    if (penalty < best_penalty) begin
                        best_penalty = penalty;
                        best_day0 = day0_val;
                        best_day1 = 0;
                    end
                end
            end else begin // Z == 2
                // Years 0 and 1
                for (i0 = 0; i0 < allowed_count_0; i0 = i0 + 1) begin
                    day0_val = allowed_days_0[i0];
                    penalty0 = (day0_val - 12) * (day0_val - 12);
                    for (i1 = 0; i1 < allowed_count_1; i1 = i1 + 1) begin
                        day1_val = allowed_days_1[i1];
                        penalty1 = (day1_val - day0_val) * (day1_val - day0_val);
                        total_pen = penalty0 + penalty1;
                        if (total_pen < best_penalty) begin
                            best_penalty = total_pen;
                            best_day0 = day0_val;
                            best_day1 = day1_val;
                        end
                    end
                end
            end
        end
    end

    // Sequential output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
            day0 <= 0;
            day1 <= 0;
            total_penalty <= 0;
        end else if (start) begin
            day0 <= best_day0;
            day1 <= best_day1;
            total_penalty <= best_penalty;
            done <= 1;
        end
    end

endmodule

