// Verilog module for scaled-down xorbonacci problem
// Parameters: K=4, W=8 (value width), L=16 (index width)
// The sequence prefix XOR has period M=K+1=5.
// Interface:
//   clk, rst_n: clock and active-low reset
//   start: pulse to load initial values (a0..a3)
//   query: pulse to start query computation (l,r must be stable)
//   a0,a1,a2,a3: 8-bit initial values
//   l, r: 16-bit query indices
//   result: 8-bit XOR of x_l ... x_r
//   done: high for one cycle when result is valid
// Operation:
//   After reset, assert start to load a0..a3 and compute prefix table P[0..4].
//   Then assert query to compute answer for current l,r.
//   done goes high after a few cycles.
//   The module stays ready for subsequent queries.

module xorbonacci (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire query,
    input wire [7:0] a0, a1, a2, a3,
    input wire [15:0] l, r,
    output reg [7:0] result,
    output reg done
);

    // State encoding
    localparam IDLE = 0;
    localparam LOADING = 1;
    localparam READY = 2;
    localparam COMPUTING = 3;
    localparam RESULT = 4;
    localparam DONE = 5;

    reg [2:0] state;
    reg [7:0] P [0:4];          // Prefix XOR table, index 0..4
    reg [15:0] l_reg, r_reg;    // Stored query indices
    reg [2:0] rem_l, rem_r;     // Remainders modulo 5

    // Helper function: compute 16-bit value modulo 5
    function [2:0] mod5;
        input [15:0] val;
        reg [4:0] sum_low, sum_high;
        reg [4:0] rlow, rhigh;
        begin
            // Low byte: split into two 4-bit parts
            sum_low = val[7:4] + val[3:0];
            // Compute remainder by subtracting multiples of 5
            if (sum_low >= 25) rlow = sum_low - 25;
            else if (sum_low >= 20) rlow = sum_low - 20;
            else if (sum_low >= 15) rlow = sum_low - 15;
            else if (sum_low >= 10) rlow = sum_low - 10;
            else if (sum_low >= 5)  rlow = sum_low - 5;
            else rlow = sum_low;
            // High byte: split into two 4-bit parts
            sum_high = val[15:12] + val[11:8];
            if (sum_high >= 25) rhigh = sum_high - 25;
            else if (sum_high >= 20) rhigh = sum_high - 20;
            else if (sum_high >= 15) rhigh = sum_high - 15;
            else if (sum_high >= 10) rhigh = sum_high - 10;
            else if (sum_high >= 5)  rhigh = sum_high - 5;
            else rhigh = sum_high;
            // Combine
            mod5 = rhigh + rlow;
            if (mod5 >= 5) mod5 = mod5 - 5;
        end
    endfunction

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        // Compute prefix XOR table P[0..4]
                        P[0] <= 0;
                        P[1] <= a0;
                        P[2] <= a0 ^ a1;
                        P[3] <= a0 ^ a1 ^ a2;
                        P[4] <= a0 ^ a1 ^ a2 ^ a3;
                        state <= LOADING;
                    end
                end

                LOADING: begin
                    // One cycle to let P settle
                    state <= READY;
                end

                READY: begin
                    if (query) begin
                        l_reg <= l;
                        r_reg <= r;
                        state <= COMPUTING;
                    end
                end

                COMPUTING: begin
                    // Compute remainders using the function
                    rem_l <= mod5(l_reg);
                    rem_r <= mod5(r_reg);
                    state <= RESULT;
                end

                RESULT: begin
                    // XOR the two prefix values
                    result <= P[rem_r] ^ P[rem_l];
                    done <= 1;
                    state <= DONE;
                end

                DONE: begin
                    done <= 0;
                    state <= READY;  // Ready for next query
                end
            endcase
        end
    end

endmodule

module graph_partition_4(
  input wire adj13,
  input wire adj14,
  input wire adj23,
  input wire adj24,
  input wire adj34,
  output wire possible,
  output wire [3:0] aryas_set,
  output wire [3:0] sansas_set
);

wire A1_3, A1_4, A2_3, A2_4, A0_3, A0_4;
wire clique_A0, clique_A1, clique_A2;

assign A1_3 = adj13;
assign A1_4 = adj14;
assign A2_3 = adj23 && !adj13;
assign A2_4 = adj24 && !adj14;
assign A0_3 = !adj13 && !adj23;
assign A0_4 = !adj14 && !adj24;

assign clique_A0 = !(A0_3 && A0_4) || adj34;
assign clique_A1 = !(A1_3 && A1_4) || adj34;
assign clique_A2 = !(A2_3 && A2_4) || adj34;

assign possible = clique_A0 && clique_A1 && clique_A2;

assign aryas_set = {A1_4, A1_3, 1'b0, 1'b1};
assign sansas_set = {A2_4, A2_3, 1'b1, 1'b0};

endmodule

module Figurine4Pack #(
    parameter N = 8,
    parameter WEIGHT_WIDTH = 8,
    parameter RESULT_WIDTH = 16,
    parameter FP_FRAC_BITS = 16
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [WEIGHT_WIDTH-1:0] weights [0:N-1],

    output reg [RESULT_WIDTH-1:0] max_weight,
    output reg [RESULT_WIDTH-1:0] min_weight,
    output reg [RESULT_WIDTH-1:0] num_distinct,
    output reg [31:0] expected_weight,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam LOAD = 3'b001;
localparam COMPUTE = 3'b010;
localparam COUNT_DISTINCT = 3'b011;
localparam DONE = 3'b100;

reg [2:0] state, next_state;

// Data storage
reg [WEIGHT_WIDTH-1:0] w [0:N-1];
reg [RESULT_WIDTH-1:0] sum_all;
reg [WEIGHT_WIDTH:0] min_val;
reg [WEIGHT_WIDTH:0] max_val;
reg [10:0] combo_idx;
reg [10:0] distinct_count;
reg [1020:0] seen_sums;

// Combinational signals
wire [2:0] i0 = combo_idx % N;
wire [2:0] i1 = (combo_idx / N) % N;
wire [2:0] i2 = (combo_idx / (N*N)) % N;
wire [2:0] i3 = (combo_idx / (N*N*N)) % N;
wire [WEIGHT_WIDTH:0] current_sum = w[i0] + w[i1] + w[i2] + w[i3];
wire [10:0] total_combos = N * N * N * N;

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else state <= next_state;
end

always @(*) begin
    case (state)
        IDLE: next_state = start ? LOAD : IDLE;
        LOAD: next_state = COMPUTE;
        COMPUTE: next_state = COUNT_DISTINCT;
        COUNT_DISTINCT: next_state = (combo_idx >= total_combos) ? DONE : COUNT_DISTINCT;
        DONE: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

// Datapath
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        max_weight <= 0;
        min_weight <= 0;
        num_distinct <= 0;
        expected_weight <= 0;
        done <= 0;
        sum_all <= 0;
        min_val <= {11{1'b1}};
        max_val <= 0;
        combo_idx <= 0;
        distinct_count <= 0;
        seen_sums <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    combo_idx <= 0;
                    distinct_count <= 0;
                    seen_sums <= 0;
                    min_val <= {11{1'b1}};
                    max_val <= 0;
                    sum_all <= 0;
                end
            end

            LOAD: begin
                for (integer i = 0; i < N; i = i + 1) begin
                    w[i] <= weights[i];
                end
            end

            COMPUTE: begin
                for (integer i = 0; i < N; i = i + 1) begin
                    sum_all <= sum_all + w[i];
                    if (w[i] < min_val) min_val <= w[i];
                    if (w[i] > max_val) max_val <= w[i];
                end
            end

            COUNT_DISTINCT: begin
                if (!seen_sums[current_sum]) begin
                    seen_sums[current_sum] <= 1'b1;
                    distinct_count <= distinct_count + 1;
                end
                combo_idx <= combo_idx + 1;
            end

            DONE: begin
                max_weight <= max_val * 4;
                min_weight <= min_val * 4;
                num_distinct <= distinct_count;
                expected_weight <= (sum_all * 4 * (1 << FP_FRAC_BITS)) / N;
                done <= 1;
            end
        endcase
    end
end

endmodule

