module max_flow_network (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Network configuration
    input wire [3:0] num_suppliers,      // 1-8
    input wire [3:0] num_factories,      // 1-8  
    input wire [3:0] num_companies,      // 1-8

    // Supplier states: supplier_states[i] = state index (0-15)
    input wire [3:0] supplier_states [0:7],

    // Factory states: factory_states[i] = state index (0-15)
    input wire [3:0] factory_states [0:7],

    // Company states: company_states[i][j] = state index for company i, state j
    // Valid states are 0-15, 15 = invalid/unused
    input wire [3:0] company_states [0:7][0:7],

    // Output
    output reg [7:0] max_flow,           // Result: number of matched factories
    output reg done                      // Computation complete
);

// Internal parameters
localparam NODE_SOURCE = 0;
localparam NODE_SINK = 1;
localparam NODE_SUPPLIERS_START = 2;
localparam NODE_FACTORIES_START = 10;  // After suppliers (max 8)
localparam NODE_COMPANIES_START = 18;  // After factories (max 8)
localparam MAX_NODES = 26;              // Total nodes: 1+1+8+8+8
localparam INVALID_NODE = 63;

// Flow network adjacency matrix (capacity)
reg [7:0] capacity [0:MAX_NODES-1][0:MAX_NODES-1];
// Flow matrix
reg [7:0] flow [0:MAX_NODES-1][0:MAX_NODES-1];

// BFS and state machine variables
reg [5:0] parent [0:MAX_NODES-1];      // For path reconstruction
reg [5:0] queue [0:MAX_NODES-1];       // BFS queue
reg [5:0] queue_head, queue_tail;
reg visited [0:MAX_NODES-1];

// Algorithm state
reg [3:0] state;
localparam S_IDLE = 0;
localparam S_BUILD_NETWORK = 1;
localparam S_BFS_INIT = 2;
localparam S_BFS_PROCESS = 3;
localparam S_UPDATE_FLOW = 4;
localparam S_CHECK_DONE = 5;
localparam S_FINISH = 6;

// Loop counters
reg [3:0] i, j, k;
reg [5:0] u, v;
reg [7:0] path_flow;
reg [7:0] max_flow_reg;

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        max_flow <= 0;
        // Reset matrices
        for (i = 0; i < MAX_NODES; i = i + 1) begin
            for (j = 0; j < MAX_NODES; j = j + 1) begin
                capacity[i][j] <= 0;
                flow[i][j] <= 0;
            end
        end
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= S_BUILD_NETWORK;
                    max_flow_reg <= 0;
                end
            end

            S_BUILD_NETWORK: begin
                // Build flow network
                // Edges from source to suppliers
                for (i = 0; i < 8; i = i + 1) begin
                    if (i < num_suppliers) begin
                        capacity[NODE_SOURCE][NODE_SUPPLIERS_START + i] <= 1;
                    end else begin
                        capacity[NODE_SOURCE][NODE_SUPPLIERS_START + i] <= 0;
                    end
                end

                // Edges from factories to sink
                for (i = 0; i < 8; i = i + 1) begin
                    if (i < num_factories) begin
                        capacity[NODE_FACTORIES_START + i][NODE_SINK] <= 1;
                    end else begin
                        capacity[NODE_FACTORIES_START + i][NODE_SINK] <= 0;
                    end
                end

                // Edges from suppliers to companies (if company operates in supplier state)
                for (i = 0; i < 8; i = i + 1) begin  // suppliers
                    if (i < num_suppliers) begin
                        for (j = 0; j < 8; j = j + 1) begin  // companies
                            if (j < num_companies) begin
                                // Check if company j can operate in supplier i's state
                                for (k = 0; k < 8; k = k + 1) begin
                                    if (company_states[j][k] == supplier_states[i] && company_states[j][k] != 4'hF) begin
                                        capacity[NODE_SUPPLIERS_START + i][NODE_COMPANIES_START + j] <= 1;
                                    end
                                end
                            end
                        end
                    end
                end

                // Edges from companies to factories (if company operates in factory state)
                for (i = 0; i < 8; i = i + 1) begin  // companies
                    if (i < num_companies) begin
                        for (j = 0; j < 8; j = j + 1) begin  // factories
                            if (j < num_factories) begin
                                // Check if company i can operate in factory j's state
                                for (k = 0; k < 8; k = k + 1) begin
                                    if (company_states[i][k] == factory_states[j] && company_states[i][k] != 4'hF) begin
                                        capacity[NODE_COMPANIES_START + i][NODE_FACTORIES_START + j] <= 1;
                                    end
                                end
                            end
                        end
                    end
                end

                // Edges between companies (if they share any state)
                for (i = 0; i < 8; i = i + 1) begin  // companies i
                    if (i < num_companies) begin
                        for (j = 0; j < 8; j = j + 1) begin  // companies j
                            if (j < num_companies && i != j) begin
                                // Check for common state
                                for (k = 0; k < 8; k = k + 1) begin
                                    if (company_states[i][k] != 4'hF) begin
                                        for (int m = 0; m < 8; m = m + 1) begin
                                            if (company_states[j][m] == company_states[i][k] && company_states[j][m] != 4'hF) begin
                                                capacity[NODE_COMPANIES_START + i][NODE_COMPANIES_START + j] <= 1;
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                state <= S_BFS_INIT;
            end

            S_BFS_INIT: begin
                // Initialize BFS for augmenting path search
                for (i = 0; i < MAX_NODES; i = i + 1) begin
                    parent[i] <= INVALID_NODE;
                    visited[i] <= 0;
                end
                queue_head <= 0;
                queue_tail <= 0;
                queue[0] <= NODE_SOURCE;
                visited[NODE_SOURCE] <= 1;
                state <= S_BFS_PROCESS;
            end

            S_BFS_PROCESS: begin
                if (queue_head < queue_tail || (queue_head == 0 && queue_tail == 0 && visited[NODE_SOURCE])) begin
                    u <= queue[queue_head];
                    queue_head <= queue_head + 1;
                    state <= 3'd3;  // Process neighbors
                end else begin
                    // BFS complete, check if sink was reached
                    if (parent[NODE_SINK] != INVALID_NODE) begin
                        state <= S_UPDATE_FLOW;
                    end else begin
                        state <= S_CHECK_DONE;
                    end
                end
            end

            3'd3: begin  // Process neighbors of u
                if (j < MAX_NODES) begin
                    // Check capacity and residual flow
                    if (capacity[u][j] > flow[u][j] && !visited[j]) begin
                        queue[queue_tail] <= j;
                        queue_tail <= queue_tail + 1;
                        parent[j] <= u;
                        visited[j] <= 1;
                    end
                    j <= j + 1;
                end else begin
                    j <= 0;
                    state <= S_BFS_PROCESS;
                end
            end

            S_UPDATE_FLOW: begin
                // Find minimum residual capacity along path
                path_flow <= 255;  // Initialize to large value
                v <= NODE_SINK;
                state <= 4'd4;  // Find min capacity
            end

            4'd4: begin  // Find min capacity
                if (parent[v] != INVALID_NODE && parent[v] != NODE_SOURCE) begin
                    u <= parent[v];
                    if (capacity[parent[v]][v] - flow[parent[v]][v] < path_flow) begin
                        path_flow <= capacity[parent[v]][v] - flow[parent[v]][v];
                    end
                    v <= parent[v];
                end else if (parent[v] != INVALID_NODE) begin
                    // Reached source, update flow
                    v <= NODE_SINK;
                    state <= 4'd5;  // Update flow along path
                end else begin
                    state <= S_BFS_INIT;  // Shouldn't happen
                end
            end

            4'd5: begin  // Update flow along path
                if (parent[v] != INVALID_NODE) begin
                    // Forward edge
                    flow[parent[v]][v] <= flow[parent[v]][v] + path_flow;
                    // Backward edge (residual)
                    flow[v][parent[v]] <= flow[v][parent[v]] - path_flow;
                    v <= parent[v];
                end else begin
                    max_flow_reg <= max_flow_reg + path_flow;
                    state <= S_BFS_INIT;  // Look for more augmenting paths
                end
            end

            S_CHECK_DONE: begin
                // No more augmenting paths
                max_flow <= max_flow_reg;
                state <= S_FINISH;
            end

            S_FINISH: begin
                done <= 1;
                state <= S_IDLE;
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

module robotic_arm #(
    parameter N = 8,           // Max 8 segments (scaled down from 20)
    parameter DATA_WIDTH = 32, // Q16.16 fixed-point format
    parameter FRACT_WIDTH = 16,
    parameter MAX_CYCLES = 256 // Timeout for state machine
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire signed [DATA_WIDTH-1:0] target_x,
    input wire signed [DATA_WIDTH-1:0] target_y,
    input wire [DATA_WIDTH-1:0] segment_lengths [0:N-1],

    output reg signed [DATA_WIDTH-1:0] x_coords [0:N-1],
    output reg signed [DATA_WIDTH-1:0] y_coords [0:N-1],
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam CALC_SUM = 3'b001;
localparam CALC_DIST = 3'b010;
localparam CALC_DIR = 3'b011;
localparam COMPUTE_POS = 3'b100;
localparam FINISHED = 3'b101;

// Registers and wires
reg [2:0] state, next_state;
reg [7:0] idx, next_idx;          // Segment counter
reg signed [DATA_WIDTH-1:0] sum_lengths, next_sum_lengths;
reg signed [DATA_WIDTH-1:0] target_dist, next_target_dist;
reg signed [DATA_WIDTH-1:0] angle_sin, next_angle_sin;
reg signed [DATA_WIDTH-1:0] angle_cos, next_angle_cos;
reg signed [DATA_WIDTH-1:0] acc_x, next_acc_x;  // Accumulated x position
reg signed [DATA_WIDTH-1:0] acc_y, next_acc_y;  // Accumulated y position
reg signed [DATA_WIDTH-1:0] scale_factor, next_scale_factor;
reg [7:0] cycle_count, next_cycle_count;

// Combinational logic for state transition
always @(*) begin
    next_state = state;
    next_idx = idx;
    next_sum_lengths = sum_lengths;
    next_target_dist = target_dist;
    next_angle_sin = angle_sin;
    next_angle_cos = angle_cos;
    next_acc_x = acc_x;
    next_acc_y = acc_y;
    next_scale_factor = scale_factor;
    next_cycle_count = cycle_count;
    done = 0;

    case (state)
        IDLE: begin
            if (start) begin
                next_state = CALC_SUM;
                next_idx = 0;
                next_sum_lengths = 0;
                next_cycle_count = 0;
            end
        end

        CALC_SUM: begin
            if (idx < N) begin
                next_sum_lengths = sum_lengths + segment_lengths[idx];
                next_idx = idx + 1;
            end else begin
                next_state = CALC_DIST;
                next_idx = 0;
            end
        end

        CALC_DIST: begin
            // Calculate target distance = sqrt(x² + y²)
            // Simplified: use Manhattan distance for hardware
            // For Q16.16: dist = (abs(x) + abs(y)) / 2
            if (cycle_count == 0) begin
                next_target_dist = ((target_x > 0 ? target_x : -target_x) + 
                                   (target_y > 0 ? target_y : -target_y)) >>> 1;
                next_cycle_count = cycle_count + 1;
            end else if (cycle_count == 1) begin
                // Check if reachable
                if (target_dist <= sum_lengths) begin
                    next_scale_factor = target_dist; // Will divide by sum later
                    next_state = CALC_DIR;
                end else begin
                    // Unreachable - point straight to target
                    next_angle_cos = target_x;
                    next_angle_sin = target_y;
                    next_state = COMPUTE_POS;
                end
                next_cycle_count = 0;
                next_idx = 0;
            end
        end

        CALC_DIR: begin
            // Calculate direction vector (cos, sin) normalized
            // For Q16.16, we use x/dist and y/dist
            if (cycle_count == 0) begin
                // Scale factor = target_dist / sum_lengths
                // For simplicity, approximate: scale = target_dist / (sum_lengths / 2)
                next_scale_factor = target_dist * 2;
                next_scale_factor = next_scale_factor / (sum_lengths >> 8); // Divide by sum (scaled)
                next_angle_cos = target_x;
                next_angle_sin = target_y;
                next_cycle_count = cycle_count + 1;
            end else if (cycle_count == 1) begin
                // Normalize direction
                next_angle_cos = target_x * 2; // Approximation
                next_angle_cos = next_angle_cos / (target_dist + 1); // Avoid divide by zero
                next_angle_sin = target_y * 2;
                next_angle_sin = next_angle_sin / (target_dist + 1);
                next_cycle_count = 0;
                next_state = COMPUTE_POS;
            end
        end

        COMPUTE_POS: begin
            if (idx < N) begin
                // Calculate segment length (scaled or original)
                reg signed [DATA_WIDTH-1:0] seg_len;
                if (target_dist <= sum_lengths) begin
                    // Reachable: scale segment length
                    seg_len = (segment_lengths[idx] * scale_factor) >> FRACT_WIDTH;
                end else begin
                    // Unreachable: full length
                    seg_len = segment_lengths[idx];
                end

                // Calculate delta = length * direction
                next_acc_x = acc_x + ((seg_len * angle_cos) >>> FRACT_WIDTH);
                next_acc_y = acc_y + ((seg_len * angle_sin) >>> FRACT_WIDTH);

                // Store coordinates
                x_coords[idx] = next_acc_x;
                y_coords[idx] = next_acc_y;

                next_idx = idx + 1;
            end else begin
                next_state = FINISHED;
            end
        end

        FINISHED: begin
            done = 1;
            if (!start) begin
                next_state = IDLE;
            end
        end

        default: next_state = IDLE;
    endcase
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        idx <= 0;
        sum_lengths <= 0;
        target_dist <= 0;
        angle_sin <= 0;
        angle_cos <= 0;
        acc_x <= 0;
        acc_y <= 0;
        scale_factor <= 0;
        cycle_count <= 0;
        // Clear output arrays
        for (integer i = 0; i < N; i = i + 1) begin
            x_coords[i] <= 0;
            y_coords[i] <= 0;
        end
    end else begin
        state <= next_state;
        idx <= next_idx;
        sum_lengths <= next_sum_lengths;
        target_dist <= next_target_dist;
        angle_sin <= next_angle_sin;
        angle_cos <= next_angle_cos;
        acc_x <= next_acc_x;
        acc_y <= next_acc_y;
        scale_factor <= next_scale_factor;
        cycle_count <= next_cycle_count;
    end
end

endmodule

module apple_distance #(
    parameter GRID_R = 8,
    parameter GRID_S = 8,
    parameter MAX_TREES = 24,
    parameter COORD_BITS = 4,  // Coordinates 1-8
    parameter DIST_BITS = 7,   // Max squared distance 98
    parameter TREE_IDX_BITS = 5
)(
    input wire clk,
    input wire rst_n,
    input wire load_en,        // Load initial tree (pulse high)
    input wire process,        // Process query (pulse high)
    input wire [COORD_BITS-1:0] r,
    input wire [COORD_BITS-1:0] s,
    output reg [DIST_BITS-1:0] distance,
    output reg done,
    output reg full
);

// Tree storage: parallel arrays for row and column
reg [COORD_BITS-1:0] tree_r [0:MAX_TREES-1];
reg [COORD_BITS-1:0] tree_s [0:MAX_TREES-1];
reg [TREE_IDX_BITS-1:0] num_trees;

// FSM states
reg [1:0] state;
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam UPDATE = 2'b10;

// Computation registers
reg [TREE_IDX_BITS-1:0] tree_index;
reg [DIST_BITS-1:0] current_min;
reg [COORD_BITS-1:0] query_r, query_s;

// Combinational distance calculation for current tree
wire [COORD_BITS-1:0] current_tree_r = tree_r[tree_index];
wire [COORD_BITS-1:0] current_tree_s = tree_s[tree_index];
wire [COORD_BITS-1:0] diff_r = (query_r >= current_tree_r) ? 
                                (query_r - current_tree_r) : 
                                (current_tree_r - query_r);
wire [COORD_BITS-1:0] diff_s = (query_s >= current_tree_s) ? 
                                (query_s - current_tree_s) : 
                                (current_tree_s - query_s);
wire [6:0] current_dist = (diff_r * diff_r) + (diff_s * diff_s);

// State machine and tree management
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        num_trees <= 0;
        done <= 0;
        full <= 0;
        distance <= 0;
        tree_index <= 0;
        current_min <= {DIST_BITS{1'b1}};
    end else begin
        done <= 0;
        full <= (num_trees >= MAX_TREES);

        case (state)
            IDLE: begin
                if (load_en && !full) begin
                    // Load initial tree
                    tree_r[num_trees] <= r;
                    tree_s[num_trees] <= s;
                    num_trees <= num_trees + 1;
                end else if (process && !full && num_trees > 0) begin
                    // Start query processing
                    query_r <= r;
                    query_s <= s;
                    tree_index <= 0;
                    current_min <= {DIST_BITS{1'b1}};
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                if (tree_index < num_trees) begin
                    // Update minimum distance
                    if (current_dist < current_min) begin
                        current_min <= current_dist;
                    end
                    tree_index <= tree_index + 1;
                end else begin
                    // All trees processed
                    state <= UPDATE;
                end
            end

            UPDATE: begin
                // Add query position as new tree
                if (!full) begin
                    tree_r[num_trees] <= query_r;
                    tree_s[num_trees] <= query_s;
                    num_trees <= num_trees + 1;
                end
                // Output result
                distance <= current_min;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module stop_counting (
    input clk,
    input rst_n,
    input start,
    input [31:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    output done,
    output reg [63:0] result_sum,
    output reg [31:0] result_count
);

    // Parameters
    parameter N = 8;
    parameter SUM_WIDTH = 35; // 32-bit inputs + log2(8) = 35 bits
    localparam COUNT_WIDTH = 5; // count up to 8

    // States
    localparam IDLE = 3'd0;
    localparam COMPUTE_PREFIX = 3'd1;
    localparam COMPUTE_SUFFIX = 3'd2;
    localparam SEARCH = 3'd3;
    localparam DONE = 3'd4;

    // Registers
    reg [2:0] state;
    reg [3:0] i_ptr; // 0..N
    reg [3:0] j_ptr; // 1..N+1
    reg [3:0] i;     // current prefix length in search
    reg [3:0] j;     // current suffix start index in search
    reg signed [SUM_WIDTH-1:0] arr_reg [0:N-1];
    reg signed [SUM_WIDTH-1:0] pref [0:N]; // pref[0] = 0, pref[i] = sum of first i cards
    reg signed [SUM_WIDTH-1:0] suff [1:N+1]; // suff[N+1] = 0, suff[j] = sum from j to N
    reg signed [SUM_WIDTH-1:0] best_sum;
    reg [COUNT_WIDTH-1:0] best_count;
    wire signed [SUM_WIDTH-1:0] sum_wire;
    wire [COUNT_WIDTH-1:0] count_wire;
    wire signed [63:0] left;
    wire signed [63:0] right;

    // Combination logic for sum and count
    assign sum_wire = pref[i] + suff[j];
    assign count_wire = i + (N - j + 1); // N=8 => i + (9-j)

    // Multiplication for comparison (signed)
    wire signed [SUM_WIDTH:0] best_count_signed = $signed({1'b0, best_count});
    wire signed [SUM_WIDTH:0] count_wire_signed = $signed({1'b0, count_wire});
    assign left = $signed(sum_wire) * best_count_signed;
    assign right = $signed(best_sum) * count_wire_signed;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result_sum <= 0;
            result_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Capture input array
                        arr_reg[0] <= arr_0;
                        arr_reg[1] <= arr_1;
                        arr_reg[2] <= arr_2;
                        arr_reg[3] <= arr_3;
                        arr_reg[4] <= arr_4;
                        arr_reg[5] <= arr_5;
                        arr_reg[6] <= arr_6;
                        arr_reg[7] <= arr_7;
                        i_ptr <= 0;
                        state <= COMPUTE_PREFIX;
                    end
                end

                COMPUTE_PREFIX: begin
                    if (i_ptr == 0) begin
                        pref[0] <= 0;
                        i_ptr <= 1;
                    end else if (i_ptr <= N) begin
                        pref[i_ptr] <= pref[i_ptr-1] + arr_reg[i_ptr-1];
                        i_ptr <= i_ptr + 1;
                    end else begin
                        i_ptr <= 0;
                        j_ptr <= N+1;
                        state <= COMPUTE_SUFFIX;
                    end
                end

                COMPUTE_SUFFIX: begin
                    if (j_ptr == N+1) begin
                        suff[N+1] <= 0;
                        j_ptr <= N;
                    end else if (j_ptr >= 1) begin
                        suff[j_ptr] <= suff[j_ptr+1] + arr_reg[j_ptr-1];
                        j_ptr <= j_ptr - 1;
                    end else begin
                        i <= 0;
                        j <= 1; // first pair: i=0, j=1
                        best_sum <= 0;
                        best_count <= 1; // represents average 0
                        state <= SEARCH;
                    end
                end

                SEARCH: begin
                    // Compare current pair with best if count > 0
                    if (count_wire > 0 && left > right) begin
                        best_sum <= sum_wire;
                        best_count <= count_wire;
                    end
                    // Move to next pair
                    if (j == N+1) begin
                        // Finished current i
                        if (i == N) begin
                            state <= DONE;
                        end else begin
                            i <= i + 1;
                            j <= i + 2; // next j = (i+1)+1, using old i
                        end
                    end else begin
                        j <= j + 1;
                    end
                end

                DONE: begin
                    done <= 1;
                    result_sum <= {{(64-SUM_WIDTH){1'b0}}, best_sum}; // zero-extend to 64 bits
                    result_count <= {{(32-COUNT_WIDTH){1'b0}}, best_count}; // zero-extend to 32 bits
                    // Stay in DONE until reset
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module BingoTwoCardChecker (
    input [11:0] card1 [0:4][0:4],
    input [11:0] card2 [0:4][0:4],
    output reg tie_found,
    output reg [2:0] tie_row1,
    output reg [2:0] tie_row2
);
    // Parameters
    localparam ROWS = 5;
    localparam COLS = 5;
    localparam DATA_WIDTH = 12;
    localparam MAX_UNION_SIZE = 10;
    localparam MAX_INTERSECTION_SIZE = 5;

    // Internal helper function: check if a number is in an array
    function automatic int is_in_array(
        input [DATA_WIDTH-1:0] num,
        input [DATA_WIDTH-1:0] arr [0:MAX_UNION_SIZE-1],
        input int size
    );
        int i;
        is_in_array = 0;
        for (i = 0; i < size; i++) begin
            if (arr[i] == num) begin
                is_in_array = 1;
                return 1;
            end
        end
        return 0;
    endfunction

    // Main combinational logic
    always_comb begin
        // Initialize outputs
        tie_found = 0;
        tie_row1 = 0;
        tie_row2 = 0;

        // Iterate over each row in card1
        for (int i = 0; i < ROWS; i++) begin
            // Iterate over each row in card2
            for (int j = 0; j < ROWS; j++) begin
                // Compute intersection of row i and row j
                reg [DATA_WIDTH-1:0] inter [0:MAX_INTERSECTION_SIZE-1];
                int inter_size = 0;
                for (int k = 0; k < COLS; k++) begin
                    for (int l = 0; l < COLS; l++) begin
                        if (card1[i][k] == card2[j][l]) begin
                            // Check if already in intersection
                            int found = 0;
                            for (int m = 0; m < inter_size; m++) begin
                                if (inter[m] == card1[i][k]) found = 1;
                            end
                            if (!found && inter_size < MAX_INTERSECTION_SIZE) begin
                                inter[inter_size] = card1[i][k];
                                inter_size++;
                            end
                        end
                    end
                end

                // Compute union of row i and row j
                reg [DATA_WIDTH-1:0] uni [0:MAX_UNION_SIZE-1];
                int uni_size = 0;
                // Add all from row i
                for (int k = 0; k < COLS; k++) begin
                    if (!is_in_array(card1[i][k], uni, uni_size) && uni_size < MAX_UNION_SIZE) begin
                        uni[uni_size] = card1[i][k];
                        uni_size++;
                    end
                end
                // Add all from row j
                for (int k = 0; k < COLS; k++) begin
                    if (!is_in_array(card2[j][k], uni, uni_size) && uni_size < MAX_UNION_SIZE) begin
                        uni[uni_size] = card2[j][k];
                        uni_size++;
                    end
                end

                // For each element in intersection, check if it can be the last number
                for (int x_idx = 0; x_idx < inter_size; x_idx++) begin
                    reg [DATA_WIDTH-1:0] x = inter[x_idx];
                    int valid = 1;

                    // Check all rows in card1
                    for (int r = 0; r < ROWS; r++) begin
                        // Check if this row is subset of union
                        int is_subset = 1;
                        for (int c = 0; c < COLS; c++) begin
                            if (!is_in_array(card1[r][c], uni, uni_size)) begin
                                is_subset = 0;
                                break;
                            end
                        end
                        if (is_subset) begin
                            // If subset, must contain x
                            int contains_x = 0;
                            for (int c = 0; c < COLS; c++) begin
                                if (card1[r][c] == x) contains_x = 1;
                            end
                            if (!contains_x) valid = 0;
                        end
                    end

                    // Check all rows in card2
                    for (int r = 0; r < ROWS; r++) begin
                        int is_subset = 1;
                        for (int c = 0; c < COLS; c++) begin
                            if (!is_in_array(card2[r][c], uni, uni_size)) begin
                                is_subset = 0;
                                break;
                            end
                        end
                        if (is_subset) begin
                            int contains_x = 0;
                            for (int c = 0; c < COLS; c++) begin
                                if (card2[r][c] == x) contains_x = 1;
                            end
                            if (!contains_x) valid = 0;
                        end
                    end

                    if (valid) begin
                        tie_found = 1;
                        tie_row1 = i;
                        tie_row2 = j;
                        // Break out of loops by checking tie_found in outer loops
                        // This will stop further iterations once a tie is found
                        if (tie_found) break;
                    end
                end
                if (tie_found) break;
            end
            if (tie_found) break;
        end
    end
endmodule

