module camel_race #(
    parameter MAX_CAMELS = 8,
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] jaap_bet [0:MAX_CAMELS-1],
    input wire [DATA_WIDTH-1:0] jan_bet [0:MAX_CAMELS-1],
    input wire [DATA_WIDTH-1:0] thijs_bet [0:MAX_CAMELS-1],
    input wire [ADDR_WIDTH-1:0] num_camels,
    output reg [DATA_WIDTH*2-1:0] result,
    output reg done
);

    // Internal state definitions
    localparam IDLE = 3'b000;
    localparam COMPUTE_POS = 3'b001;
    localparam COUNT_PAIRS = 3'b010;
    localparam FINISHED = 3'b011;

    // State register
    reg [2:0] state, next_state;

    // Position arrays - flattened for hardware
    reg [DATA_WIDTH-1:0] pos1 [0:MAX_CAMELS-1];
    reg [DATA_WIDTH-1:0] pos2 [0:MAX_CAMELS-1];
    reg [DATA_WIDTH-1:0] pos3 [0:MAX_CAMELS-1];

    // Point array for CDQ algorithm (x, y, z)
    reg [DATA_WIDTH-1:0] points_x [0:MAX_CAMELS-1];
    reg [DATA_WIDTH-1:0] points_y [0:MAX_CAMELS-1];
    reg [DATA_WIDTH-1:0] points_z [0:MAX_CAMELS-1];

    // Counters and indices
    reg [ADDR_WIDTH-1:0] i, j, k;
    reg [ADDR_WIDTH-1:0] merge_left, merge_right;
    reg [DATA_WIDTH*2-1:0] pair_count;

    // Temporary storage for merge sort
    reg [DATA_WIDTH-1:0] temp_x [0:MAX_CAMELS-1];
    reg [DATA_WIDTH-1:0] temp_y [0:MAX_CAMELS-1];
    reg [DATA_WIDTH-1:0] temp_z [0:MAX_CAMELS-1];

    // Control signals
    reg compute_positions_done;
    reg pairs_counting_done;
    reg clear_fenwick;
    reg update_fenwick;
    reg query_fenwick;

    // Fenwick Tree for z-coordinate (simplified for small MAX_CAMELS)
    reg [DATA_WIDTH*2-1:0] fenwick_tree [0:MAX_CAMELS-1];
    reg [ADDR_WIDTH-1:0] fenwick_index;

    // Helper task to update Fenwick tree
    task update_fenwick_tree;
        input [ADDR_WIDTH-1:0] idx;
        input [DATA_WIDTH-1:0] val;
        integer ptr;
        begin
            ptr = idx + 1;
            while (ptr <= num_camels) begin
                fenwick_tree[ptr-1] = fenwick_tree[ptr-1] + val;
                ptr = ptr + (ptr & -ptr);
            end
        end
    endtask

    // Helper task to query Fenwick tree
    task query_fenwick_tree;
        input [ADDR_WIDTH-1:0] idx;
        output [DATA_WIDTH*2-1:0] sum;
        integer ptr;
        begin
            sum = 0;
            ptr = idx + 1;
            while (ptr > 0) begin
                sum = sum + fenwick_tree[ptr-1];
                ptr = ptr - (ptr & -ptr);
            end
        end
    endtask

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start) next_state = COMPUTE_POS;
                else next_state = IDLE;
            end
            COMPUTE_POS: begin
                if (compute_positions_done) next_state = COUNT_PAIRS;
                else next_state = COMPUTE_POS;
            end
            COUNT_PAIRS: begin
                if (pairs_counting_done) next_state = FINISHED;
                else next_state = COUNT_PAIRS;
            end
            FINISHED: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Main computation logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers
            done <= 0;
            result <= 0;
            i <= 0;
            j <= 0;
            k <= 0;
            merge_left <= 0;
            merge_right <= 0;
            pair_count <= 0;
            compute_positions_done <= 0;
            pairs_counting_done <= 0;
            clear_fenwick <= 0;
            update_fenwick <= 0;
            query_fenwick <= 0;
            // Reset Fenwick tree
            for (integer idx = 0; idx < MAX_CAMELS; idx = idx + 1) begin
                fenwick_tree[idx] <= 0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        i <= 0;
                        j <= 0;
                        k <= 0;
                        pair_count <= 0;
                        compute_positions_done <= 0;
                        pairs_counting_done <= 0;
                    end
                end

                COMPUTE_POS: begin
                    // Convert bets to position arrays
                    if (i < num_camels) begin
                        // Position for Jaap's bet
                        for (integer idx = 0; idx < MAX_CAMELS; idx = idx + 1) begin
                            if (jaap_bet[idx] < num_camels && jaap_bet[idx] < MAX_CAMELS) begin
                                pos1[jaap_bet[idx]] <= i;
                            end
                        end
                        // Position for Jan's bet
                        for (integer idx = 0; idx < MAX_CAMELS; idx = idx + 1) begin
                            if (jan_bet[idx] < num_camels && jan_bet[idx] < MAX_CAMELS) begin
                                pos2[jan_bet[idx]] <= i;
                            end
                        end
                        // Position for Thijs' bet
                        for (integer idx = 0; idx < MAX_CAMELS; idx = idx + 1) begin
                            if (thijs_bet[idx] < num_camels && thijs_bet[idx] < MAX_CAMELS) begin
                                pos3[thijs_bet[idx]] <= i;
                            end
                        end
                        i <= i + 1;
                    end else begin
                        // Build points array sorted by x (pos1)
                        for (integer idx = 0; idx < MAX_CAMELS; idx = idx + 1) begin
                            if (idx < num_camels) begin
                                points_x[idx] <= pos1[idx];
                                points_y[idx] <= pos2[idx];
                                points_z[idx] <= pos3[idx];
                            end
                        end
                        compute_positions_done <= 1;
                        i <= 0;
                        j <= 0;
                        k <= 0;
                    end
                end

                COUNT_PAIRS: begin
                    // Simplified CDQ algorithm for fixed small N
                    // We implement a basic 3D dominance counter for up to MAX_CAMELS

                    if (i < num_camels) begin
                        for (j = i + 1; j < num_camels; j = j + 1) begin
                            // Check if points[i] dominates points[j]
                            if ((points_x[i] < points_x[j]) && 
                                (points_y[i] < points_y[j]) && 
                                (points_z[i] < points_z[j])) begin
                                pair_count <= pair_count + 1;
                            end
                            // Also check the reverse (points[j] dominates points[i])
                            if ((points_x[j] < points_x[i]) && 
                                (points_y[j] < points_y[i]) && 
                                (points_z[j] < points_z[i])) begin
                                pair_count <= pair_count + 1;
                            end
                        end
                        i <= i + 1;
                    end else begin
                        pairs_counting_done <= 1;
                    end
                end

                FINISHED: begin
                    result <= pair_count;
                    done <= 1;
                end
            endcase
        end
    end

endmodule

// Module: palindrome_count
// Description: Counts the number of palindromic strings of length 2N over alphabet {A,B} that contain the given string S as a subsequence.
// Parameters:
//   N: length of S (and half-length of palindrome), max 8 for synthesis, but design supports up to 8.
// Inputs:
//   clk: clock, rising edge
//   rst_n: active-low reset
//   start: start signal, pulse high for one cycle to begin computation
//   S: packed vector of N bits, where S[i] is the i-th character of S (0 for A, 1 for B)
// Outputs:
//   result: 32-bit count modulo 1000000007
//   done: asserted high for one cycle when result is ready
//
// Behavior:
//   - When start is asserted, the module computes the count by enumerating all possible first halves (2^N possibilities).
//   - For each first half, it constructs the palindrome of length 2N and checks if S is a subsequence.
//   - The check is done by scanning the palindrome and greedily matching S.
//   - After processing all first halves, the count modulo 1000000007 is output and done is asserted.
//
// Implementation notes:
//   - The module uses a state machine with states: IDLE, SETUP, SCAN, UPDATE_COUNT, FINISH.
//   - The first half is stored in a register 'first_half' of width N bits, ranging from 0 to 2^N-1.
//   - For each first half, 'pos' scans from 0 to 2N-1, and 'matched' tracks how many characters of S have been matched.
//   - The current character of the palindrome is determined by 'pos': if pos < N, it is first_half[pos]; else it is first_half[2*N-1-pos].
//   - If the current character equals S[matched] (and matched < N), then matched is incremented.
//   - After scanning all 2N positions, if matched == N, the count is incremented.
//   - The count is kept modulo 1000000007.
//
// Timing:
//   - The computation takes (2^N) * (2N) clock cycles plus some overhead.
//   - For N=8, this is 256*16=4096 cycles.
//
// Reset:
//   - On reset, all registers are cleared, state returns to IDLE, done=0, result=0.

module palindrome_count #(parameter N=4) (
    input clk,
    input rst_n,
    input start,
    input [N-1:0] S,
    output reg [31:0] result,
    output reg done
);

// Constants
localparam MOD = 1000000007;
localparam MAX_FIRST_HALF = (1 << N) - 1;

// States
localparam IDLE = 0;
localparam SETUP = 1;
localparam SCAN = 2;
localparam UPDATE_COUNT = 3;
localparam FINISH = 4;

reg [2:0] state;
reg [N-1:0] first_half;
reg [4:0] pos;          // position in palindrome (0..2N-1)
reg [N-1:0] matched;
reg [31:0] count;

wire char;
assign char = (pos < N) ? first_half[pos] : first_half[2*N-1-pos];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 0;
        done <= 0;
        count <= 0;
        first_half <= 0;
        pos <= 0;
        matched <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= SETUP;
                    count <= 0;
                    first_half <= 0;
                end
            end

            SETUP: begin
                pos <= 0;
                matched <= 0;
                state <= SCAN;
            end

            SCAN: begin
                if (matched < N && char == S[matched]) begin
                    matched <= matched + 1;
                end
                pos <= pos + 1;
                if (pos == 2*N - 1) begin
                    state <= UPDATE_COUNT;
                end
            end

            UPDATE_COUNT: begin
                if (matched == N) begin
                    count <= count + 1;
                end
                if (first_half == MAX_FIRST_HALF) begin
                    state <= FINISH;
                end else begin
                    first_half <= first_half + 1;
                    state <= SETUP;
                end
            end

            FINISH: begin
                result <= count % MOD;
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module maximum_disjoint_matchings (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] adj_flat,
    output reg [2:0] k,
    output reg [47:0] assignments_packed,
    output reg done
);

// State machine
localparam IDLE = 3'b000;
localparam RESET = 3'b001;
localparam FIND_MATCHING = 3'b010;
localparam FOUND = 3'b011;
localparam UPDATE = 3'b100;
localparam DONE = 3'b101;

reg [2:0] state, next_state;

// Internal registers
reg [15:0] available_edges;
reg [2:0] k_reg;
reg [47:0] assignments_packed_reg;

// Permutation ROM (24 permutations of 4 buttons)
reg [11:0] permutations [0:23];

// Permutation checking
reg [4:0] perm_index;  // 0-23
reg [1:0] check_index; // 0-3 for button checking
reg valid_perm;
reg [11:0] current_perm;

// Initialize permutations (all possible perfect matchings for n=4)
initial begin
    // Identity and cyclic permutations
    permutations[0] = 12'b000_001_010_011; // [0,1,2,3]
    permutations[1] = 12'b000_001_011_010; // [0,1,3,2]
    permutations[2] = 12'b000_010_001_011; // [0,2,1,3]
    permutations[3] = 12'b000_010_011_001; // [0,2,3,1]
    permutations[4] = 12'b000_011_001_010; // [0,3,1,2]
    permutations[5] = 12'b000_011_010_001; // [0,3,2,1]
    permutations[6] = 12'b001_000_010_011; // [1,0,2,3]
    permutations[7] = 12'b001_000_011_010; // [1,0,3,2]
    permutations[8] = 12'b001_010_000_011; // [1,2,0,3]
    permutations[9] = 12'b001_010_011_000; // [1,2,3,0]
    permutations[10] = 12'b001_011_000_010; // [1,3,0,2]
    permutations[11] = 12'b001_011_010_000; // [1,3,2,0]
    permutations[12] = 12'b010_000_001_011; // [2,0,1,3]
    permutations[13] = 12'b010_000_011_001; // [2,0,3,1]
    permutations[14] = 12'b010_001_000_011; // [2,1,0,3]
    permutations[15] = 12'b010_001_011_000; // [2,1,3,0]
    permutations[16] = 12'b010_011_000_001; // [2,3,0,1]
    permutations[17] = 12'b010_011_001_000; // [2,3,1,0]
    permutations[18] = 12'b011_000_001_010; // [3,0,1,2]
    permutations[19] = 12'b011_000_010_001; // [3,0,2,1]
    permutations[20] = 12'b011_001_000_010; // [3,1,0,2]
    permutations[21] = 12'b011_001_010_000; // [3,1,2,0]
    permutations[22] = 12'b011_010_000_001; // [3,2,0,1]
    permutations[23] = 12'b011_010_001_000; // [3,2,1,0]
end

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    case (state)
        IDLE: begin
            if (start) next_state = RESET;
            else next_state = IDLE;
        end
        RESET: next_state = FIND_MATCHING;
        FIND_MATCHING: begin
            if (valid_perm) next_state = FOUND;
            else if (perm_index == 23) next_state = DONE;
            else next_state = FIND_MATCHING;
        end
        FOUND: next_state = UPDATE;
        UPDATE: begin
            if (available_edges == 16'b0) next_state = DONE;
            else next_state = FIND_MATCHING;
        end
        DONE: next_state = DONE;
        default: next_state = IDLE;
    endcase
end

// Output logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        k <= 3'b0;
        assignments_packed <= 48'b0;
        done <= 1'b0;
        available_edges <= 16'b0;
        k_reg <= 3'b0;
        assignments_packed_reg <= 48'b0;
        perm_index <= 5'b0;
        check_index <= 2'b0;
        valid_perm <= 1'b0;
    end else begin
        case (state)
            RESET: begin
                available_edges <= adj_flat;
                k_reg <= 3'b0;
                assignments_packed_reg <= 48'b0;
                perm_index <= 5'b0;
                check_index <= 2'b0;
                valid_perm <= 1'b0;
                done <= 1'b0;
            end
            FIND_MATCHING: begin
                if (perm_index < 24) begin
                    current_perm <= permutations[perm_index];
                    // Check if current permutation is valid
                    if (check_index == 3) begin
                        // All 4 buttons checked, if valid_perm still high, then valid
                        if (valid_perm) begin
                            valid_perm <= 1'b1;
                        end else begin
                            valid_perm <= 1'b0;
                        end
                        perm_index <= perm_index + 1;
                        check_index <= 2'b0;
                    end else begin
                        // Check one button
                        case (check_index)
                            0: begin // button 0
                                valid_perm <= (available_edges[(current_perm[2:0]*4 + 0)] && 
                                             (current_perm[2:0] != current_perm[5:3]) && 
                                             (current_perm[2:0] != current_perm[8:6]) && 
                                             (current_perm[2:0] != current_perm[11:9]));
                            end
                            1: begin // button 1
                                valid_perm <= valid_perm && (available_edges[(current_perm[5:3]*4 + 1)] && 
                                             (current_perm[5:3] != current_perm[8:6]) && 
                                             (current_perm[5:3] != current_perm[11:9]));
                            end
                            2: begin // button 2
                                valid_perm <= valid_perm && (available_edges[(current_perm[8:6]*4 + 2)] && 
                                             (current_perm[8:6] != current_perm[11:9]));
                            end
                            3: begin // button 3
                                valid_perm <= valid_perm && (available_edges[(current_perm[11:9]*4 + 3)]);
                            end
                        endcase
                        check_index <= check_index + 1;
                    end
                end
            end
            FOUND: begin
                // Record the matching
                if (k_reg < 4) begin
                    // Pack the permutation into assignments_packed_reg
                    // Each matching: 12 bits, 4 matchings -> 48 bits
                    case (k_reg)
                        0: assignments_packed_reg[11:0] <= current_perm;
                        1: assignments_packed_reg[23:12] <= current_perm;
                        2: assignments_packed_reg[35:24] <= current_perm;
                        3: assignments_packed_reg[47:36] <= current_perm;
                    endcase
                    k_reg <= k_reg + 1;
                end
            end
            UPDATE: begin
                // Remove the edges used in the current matching
                // For each button, clear the edge from the assigned person
                available_edges[(current_perm[2:0]*4 + 0)] <= 1'b0;
                available_edges[(current_perm[5:3]*4 + 1)] <= 1'b0;
                available_edges[(current_perm[8:6]*4 + 2)] <= 1'b0;
                available_edges[(current_perm[11:9]*4 + 3)] <= 1'b0;
                // Reset for next search
                perm_index <= 5'b0;
                check_index <= 2'b0;
                valid_perm <= 1'b0;
            end
            DONE: begin
                k <= k_reg;
                assignments_packed <= assignments_packed_reg;
                done <= 1'b1;
            end
        endcase
    end
end

endmodule

module hall_students (
    input clk,
    input rst_n,
    input start,
    input [7:0] num0, num1, num2, num3,
    output reg [7:0] result,
    output reg done
);

    // Function to compute gcd of two 8-bit numbers (for simulation)
    function automatic [7:0] gcd;
        input [7:0] a, b;
        reg [7:0] x, y;
        begin
            x = a; y = b;
            while (x != 0 && y != 0) begin
                if (x > y) x = x - y;
                else y = y - x;
            end
            gcd = x | y;
        end
    endfunction

    // Function to compute the count of valid trees
    function automatic [7:0] compute_count;
        input [7:0] n0, n1, n2, n3;
        reg [7:0] g01, g02, g03, g12, g13, g23;
        reg a01, a02, a03, a12, a13, a23;
        reg [5:0] allowed;
        reg [7:0] cnt;
        begin
            g01 = gcd(n0, n1);
            g02 = gcd(n0, n2);
            g03 = gcd(n0, n3);
            g12 = gcd(n1, n2);
            g13 = gcd(n1, n3);
            g23 = gcd(n2, n3);
            a01 = (g01 > 1);
            a02 = (g02 > 1);
            a03 = (g03 > 1);
            a12 = (g12 > 1);
            a13 = (g13 > 1);
            a23 = (g23 > 1);
            allowed = {a23, a13, a12, a03, a02, a01};
            cnt = 0;
            // Check each of the 12 non-crossing tree masks
            if ((allowed & 6'b000111) == 6'b000111) cnt = cnt + 1;
            if ((allowed & 6'b100011) == 6'b100011) cnt = cnt + 1;
            if ((allowed & 6'b001101) == 6'b001101) cnt = cnt + 1;
            if ((allowed & 6'b100101) == 6'b100101) cnt = cnt + 1;
            if ((allowed & 6'b011001) == 6'b011001) cnt = cnt + 1;
            if ((allowed & 6'b101001) == 6'b101001) cnt = cnt + 1;
            if ((allowed & 6'b110001) == 6'b110001) cnt = cnt + 1;
            if ((allowed & 6'b001110) == 6'b001110) cnt = cnt + 1;
            if ((allowed & 6'b101010) == 6'b101010) cnt = cnt + 1;
            if ((allowed & 6'b011100) == 6'b011100) cnt = cnt + 1;
            if ((allowed & 6'b101100) == 6'b101100) cnt = cnt + 1;
            if ((allowed & 6'b110100) == 6'b110100) cnt = cnt + 1;
            compute_count = cnt;
        end
    endfunction

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 8'd0;
            done <= 1'b0;
        end else begin
            if (start) begin
                result <= compute_count(num0, num1, num2, num3);
                done <= 1'b1;
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

