// Registers
reg [2:0] state;
reg [1:0] sim_state;
reg [K_WIDTH-1:0] current_k;
reg [RESULT_WIDTH-1:0] current_correct;
reg signed [DATA_WIDTH-1:0] prev_played;
reg [3:0] sim_idx;

// Wires
wire signed [DATA_WIDTH-1:0] diff;
wire signed [DATA_WIDTH-1:0] next_played;
wire is_correct;

assign diff = arr[sim_idx] - arr[sim_idx-1];
assign next_played = (diff > 0) ? (prev_played + $signed({1'b0, current_k})) :
                     (diff < 0) ? (prev_played - $signed({1'b0, current_k})) :
                     prev_played;
assign is_correct = (next_played == arr[sim_idx]);

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        max_correct <= 0;
        best_K <= 0;
        current_k <= 0;
        current_correct <= 0;
        prev_played <= 0;
        sim_idx <= 0;
        sim_state <= SIM_SETUP;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT_SIM;
                    current_k <= 0;
                    max_correct <= 0;
                    best_K <= 0;
                end
            end

            INIT_SIM: begin
                // Initialize simulation for current K
                sim_state <= SIM_SETUP;
                state <= RUN_SIM;
            end

            RUN_SIM: begin
                case (sim_state)
                    SIM_SETUP: begin
                        // Position 0 is always correct
                        current_correct <= 1;
                        prev_played <= arr[0];
                        sim_idx <= 1;
                        sim_state <= SIM_LOOP;
                    end

                    SIM_LOOP: begin
                        if (sim_idx < N) begin
                            // Update played key and check correctness
                            prev_played <= next_played;
                            if (is_correct)
                                current_correct <= current_correct + 1;
                            sim_idx <= sim_idx + 1;
                        end else begin
                            sim_state <= SIM_FINISH;
                        end
                    end

                    SIM_FINISH: begin
                        state <= UPDATE_BEST;
                    end

                    default: sim_state <= SIM_SETUP;
                endcase
            end

            UPDATE_BEST: begin
                if (current_correct > max_correct) begin
                    max_correct <= current_correct;
                    best_K <= current_k;
                end
                state <= NEXT_K;
            end

            NEXT_K: begin
                if (current_k < K_MAX) begin
                    current_k <= current_k + 1;
                    state <= INIT_SIM;
                end else begin
                    state <= DONE_STATE;
                end
            end

            DONE_STATE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module badge_access_counter (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] S, D,
    input wire [3:0] lock_count,
    input wire [7:0] badge_max,
    input wire [31:0] lock0, lock1, lock2, lock3,
    input wire [31:0] lock4, lock5, lock6, lock7,
    input wire [31:0] lock8, lock9, lock10, lock11,
    input wire [31:0] lock12, lock13, lock14, lock15,
    output reg [7:0] result,
    output reg done
);

parameter MAX_LOCKS = 16;
parameter MAX_ROOMS = 8;

localparam S_IDLE = 4'd0;
localparam S_PREPARE_BADGE = 4'd1;
localparam S_BFS_INIT = 4'd2;
localparam S_BFS_DEQUEUE = 4'd3;
localparam S_BFS_CHECK_LOCK = 4'd4;
localparam S_BFS_DONE = 4'd6;
localparam S_INCREMENT_BADGE = 4'd7;
localparam S_FINISH = 4'd8;

reg [3:0] state;
reg [7:0] badge_id;
reg [7:0] count;
reg [15:0] active_mask_reg;
reg [7:0] visited;
reg [2:0] queue [0:7];
reg [2:0] head;
reg [2:0] tail;
reg [2:0] current_u;
reg [3:0] lock_idx;
reg path_found;
reg [2:0] v;

wire [7:0] lock_a [0:15];
wire [7:0] lock_b [0:15];
wire [7:0] lock_x [0:15];
wire [7:0] lock_y [0:15];

genvar i;
generate
    for (i = 0; i < 16; i = i + 1) begin : lock_assign
        assign lock_a[i] = (i == 0) ? lock0[31:24] :
                           (i == 1) ? lock1[31:24] :
                           (i == 2) ? lock2[31:24] :
                           (i == 3) ? lock3[31:24] :
                           (i == 4) ? lock4[31:24] :
                           (i == 5) ? lock5[31:24] :
                           (i == 6) ? lock6[31:24] :
                           (i == 7) ? lock7[31:24] :
                           (i == 8) ? lock8[31:24] :
                           (i == 9) ? lock9[31:24] :
                           (i == 10) ? lock10[31:24] :
                           (i == 11) ? lock11[31:24] :
                           (i == 12) ? lock12[31:24] :
                           (i == 13) ? lock13[31:24] :
                           (i == 14) ? lock14[31:24] :
                                       lock15[31:24];
        assign lock_b[i] = (i == 0) ? lock0[23:16] :
                           (i == 1) ? lock1[23:16] :
                           (i == 2) ? lock2[23:16] :
                           (i == 3) ? lock3[23:16] :
                           (i == 4) ? lock4[23:16] :
                           (i == 5) ? lock5[23:16] :
                           (i == 6) ? lock6[23:16] :
                           (i == 7) ? lock7[23:16] :
                           (i == 8) ? lock8[23:16] :
                           (i == 9) ? lock9[23:16] :
                           (i == 10) ? lock10[23:16] :
                           (i == 11) ? lock11[23:16] :
                           (i == 12) ? lock12[23:16] :
                           (i == 13) ? lock13[23:16] :
                           (i == 14) ? lock14[23:16] :
                                       lock15[23:16];
        assign lock_x[i] = (i == 0) ? lock0[15:8] :
                           (i == 1) ? lock1[15:8] :
                           (i == 2) ? lock2[15:8] :
                           (i == 3) ? lock3[15:8] :
                           (i == 4) ? lock4[15:8] :
                           (i == 5) ? lock5[15:8] :
                           (i == 6) ? lock6[15:8] :
                           (i == 7) ? lock7[15:8] :
                           (i == 8) ? lock8[15:8] :
                           (i == 9) ? lock9[15:8] :
                           (i == 10) ? lock10[15:8] :
                           (i == 11) ? lock11[15:8] :
                           (i == 12) ? lock12[15:8] :
                           (i == 13) ? lock13[15:8] :
                           (i == 14) ? lock14[15:8] :
                                       lock15[15:8];
        assign lock_y[i] = (i == 0) ? lock0[7:0] :
                           (i == 1) ? lock1[7:0] :
                           (i == 2) ? lock2[7:0] :
                           (i == 3) ? lock3[7:0] :
                           (i == 4) ? lock4[7:0] :
                           (i == 5) ? lock5[7:0] :
                           (i == 6) ? lock6[7:0] :
                           (i == 7) ? lock7[7:0] :
                           (i == 8) ? lock8[7:0] :
                           (i == 9) ? lock9[7:0] :
                           (i == 10) ? lock10[7:0] :
                           (i == 11) ? lock11[7:0] :
                           (i == 12) ? lock12[7:0] :
                           (i == 13) ? lock13[7:0] :
                           (i == 14) ? lock14[7:0] :
                                       lock15[7:0];
    end
endgenerate

reg [15:0] active_mask_comb;
always @(*) begin
    integer j;
    active_mask_comb = 16'd0;
    for (j = 0; j < MAX_LOCKS; j = j + 1) begin
        if (j < lock_count) begin
            if ((lock_x[j] <= (badge_id + 1)) && ((badge_id + 1) <= lock_y[j])) begin
                active_mask_comb[j] = 1'b1;
            end
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        result <= 0;
        badge_id <= 0;
        count <= 0;
        active_mask_reg <= 0;
        visited <= 0;
        head <= 0;
        tail <= 0;
        current_u <= 0;
        lock_idx <= 0;
        path_found <= 0;
        v <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                if (start) begin
                    badge_id <= 0;
                    count <= 0;
                    state <= S_PREPARE_BADGE;
                    done <= 0;
                end
            end
            S_PREPARE_BADGE: begin
                active_mask_reg <= active_mask_comb;
                state <= S_BFS_INIT;
            end
            S_BFS_INIT: begin
                visited <= 0;
                head <= 0;
                tail <= 0;
                queue[0] <= S;
                tail <= 1;
                visited[S] <= 1;
                path_found <= 0;
                lock_idx <= 0;
                state <= S_BFS_DEQUEUE;
            end
            S_BFS_DEQUEUE: begin
                if (head != tail) begin
                    current_u <= queue[head];
                    head <= head + 1;
                    lock_idx <= 0;
                    state <= S_BFS_CHECK_LOCK;
                end else begin
                    state <= S_BFS_DONE;
                end
            end
            S_BFS_CHECK_LOCK: begin
                if (current_u == D) begin
                    path_found <= 1;
                    state <= S_BFS_DONE;
                end else if (lock_idx < lock_count) begin
                    if (active_mask_reg[lock_idx] && (lock_a[lock_idx] == current_u)) begin
                        v <= lock_b[lock_idx];
                        if (!visited[lock_b[lock_idx]]) begin
                            queue[tail] <= lock_b[lock_idx];
                            tail <= tail + 1;
                            visited[lock_b[lock_idx]] <= 1;
                        end
                    end
                    lock_idx <= lock_idx + 1;
                    state <= S_BFS_CHECK_LOCK;
                end else begin
                    state <= S_BFS_DEQUEUE;
                end
            end
            S_BFS_DONE: begin
                if (path_found) begin
                    count <= count + 1;
                end
                state <= S_INCREMENT_BADGE;
            end
            S_INCREMENT_BADGE: begin
                if (badge_id + 1 < badge_max) begin
                    badge_id <= badge_id + 1;
                    state <= S_PREPARE_BADGE;
                end else begin
                    state <= S_FINISH;
                end
            end
            S_FINISH: begin
                result <= count;
                done <= 1;
                if (!start) begin
                    state <= S_IDLE;
                    done <= 0;
                end
            end
            default: state <= S_IDLE;
        endcase
    end
end
endmodule

