module HintCounter (
    // Clock and control
    input wire clk,
    input wire rst_n,
    input wire start,

    // Problem size (1-8 problems, 1-4 hints)
    input wire [7:0] n,  // Number of problems
    input wire [7:0] m,  // Number of hints

    // Hints (4 hints max, packed into individual ports)
    // Each hint: l (left bound, 1-indexed), r (right bound, 1-indexed), type (0=same, 1=different)
    input wire [7:0] l_0, l_1, l_2, l_3,
    input wire [7:0] r_0, r_1, r_2, r_3,
    input wire type_0, type_1, type_2, type_3,

    // Output: count of valid sequences modulo 10^9+7
    output reg [31:0] result,
    output reg done
);

// State definitions
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam DONE = 2'b10;

// Registers for iteration
reg [1:0] state;
reg [7:0] seq;          // Current sequence (0 to 2^n-1)
reg [2:0] hint_idx;     // Current hint index (0 to m-1)
reg [31:0] count;       // Valid sequence counter
reg [7:0] max_seq;      // Maximum sequence value (2^n - 1)

// Helper: Current hint data
wire [7:0] current_l;
wire [7:0] current_r;
wire current_type;

assign current_l = (hint_idx == 0) ? l_0 :
                   (hint_idx == 1) ? l_1 :
                   (hint_idx == 2) ? l_2 : l_3;
assign current_r = (hint_idx == 0) ? r_0 :
                   (hint_idx == 1) ? r_1 :
                   (hint_idx == 2) ? r_2 : r_3;
assign current_type = (hint_idx == 0) ? type_0 :
                      (hint_idx == 1) ? type_1 :
                      (hint_idx == 2) ? type_2 : type_3;

// Mask generation: creates bit mask for range [l-1:r-1]
// Example: l=2, r=4 => mask = 2^4 - 2^1 = 14 (binary: 00001110)
wire [8:0] full_mask = (9'd1 << current_r) - (9'd1 << (current_l - 1));
wire [7:0] mask = full_mask[7:0] & ((1 << n) - 1);  // Mask to n bits

// Extract bits from current sequence
wire [7:0] masked_bits = seq & mask;
wire bits_all_0 = (masked_bits == 8'b0);
wire bits_all_1 = (masked_bits == mask);

// Hint validation logic
wire hint_pass = current_type ? 
                 ~(bits_all_0 | bits_all_1) :  // different: not all same
                 (bits_all_0 | bits_all_1);    // same: all same

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        seq <= 8'd0;
        hint_idx <= 3'd0;
        count <= 32'd0;
        result <= 32'd0;
        done <= 1'b0;
        max_seq <= 8'd0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= COMPUTE;
                    seq <= 8'd0;
                    hint_idx <= 3'd0;
                    count <= 32'd0;
                    done <= 1'b0;
                    // Compute 2^n - 1 using bit shift
                    // For n=8: (1<<8)-1 = 0-1 = 255 (correct)
                    // For n=5: (1<<5)-1 = 32-1 = 31 (correct)
                    max_seq <= (1 << n) - 1;
                end
            end

            COMPUTE: begin
                if (seq > max_seq) begin
                    // All sequences processed
                    state <= DONE;
                    result <= count % 32'd1000000007;
                    done <= 1'b1;
                end else if (hint_idx >= m) begin
                    // All hints passed for current sequence
                    count <= count + 1'b1;
                    seq <= seq + 1'b1;
                    hint_idx <= 3'd0;
                end else if (hint_pass) begin
                    // Current hint passed, check next
                    hint_idx <= hint_idx + 1'b1;
                end else begin
                    // Current hint failed, skip to next sequence
                    seq <= seq + 1'b1;
                    hint_idx <= 3'd0;
                end
            end

            DONE: begin
                // Wait for reset
            end
        endcase
    end
end

endmodule

module coin_optimizer (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] P,
    input wire [7:0] N1,
    input wire [7:0] N5,
    input wire [7:0] N10,
    input wire [7:0] N25,
    output reg [7:0] result,
    output reg valid,
    output reg done
);
    // State encoding
    localparam IDLE = 4'b0000;
    localparam START_LOOP = 4'b0001;
    localparam CHECK_X25 = 4'b0010;
    localparam SET_X10 = 4'b0011;
    localparam CHECK_X10 = 4'b0100;
    localparam SET_X5 = 4'b0101;
    localparam CHECK_X5 = 4'b0110;
    localparam PROCESS = 4'b0111;
    localparam INCR_X5 = 4'b1000;
    localparam INCR_X10 = 4'b1001;
    localparam INCR_X25 = 4'b1010;
    localparam DONE = 4'b1011;

    reg [3:0] state, next_state;
    reg [3:0] x25;
    reg [4:0] x10;
    reg [5:0] x5;
    reg [7:0] max_coins;
    reg found;

    wire [15:0] val25 = x25 * 8'd25;
    wire [15:0] val10 = x10 * 8'd10;
    wire [15:0] val5  = x5 * 8'd5;
    wire [15:0] total = val25 + val10 + val5;
    wire [7:0] x1 = P - total[7:0];
    wire total_le_P = (total <= P);
    wire x1_le_N1 = (x1 <= N1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 8'b0;
            valid <= 1'b0;
            done <= 1'b0;
            x25 <= 4'b0;
            x10 <= 5'b0;
            x5 <= 6'b0;
            max_coins <= 8'b0;
            found <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        x25 <= 4'b0;
                        x10 <= 5'b0;
                        x5 <= 6'b0;
                        max_coins <= 8'b0;
                        found <= 1'b0;
                        state <= CHECK_X25;
                    end
                end

                CHECK_X25: begin
                    if (x25 <= N25 && val25 <= P) begin
                        x10 <= 5'b0;
                        state <= CHECK_X10;
                    end else begin
                        state <= DONE;
                    end
                end

                CHECK_X10: begin
                    if (x10 <= N10 && (val25 + val10) <= P) begin
                        x5 <= 6'b0;
                        state <= CHECK_X5;
                    end else begin
                        if (x10 < N10) begin
                            x10 <= x10 + 1;
                            state <= CHECK_X10;
                        end else begin
                            x25 <= x25 + 1;
                            state <= CHECK_X25;
                        end
                    end
                end

                CHECK_X5: begin
                    if (x5 <= N5 && total <= P) begin
                        if (x1_le_N1) begin
                            if (x1 + x5 + x10 + x25 > max_coins) begin
                                max_coins <= x1 + x5 + x10 + x25;
                                found <= 1'b1;
                            end
                        end
                        if (x5 < N5) begin
                            x5 <= x5 + 1;
                            state <= CHECK_X5;
                        end else begin
                            if (x10 < N10) begin
                                x10 <= x10 + 1;
                                state <= CHECK_X10;
                            end else begin
                                x25 <= x25 + 1;
                                state <= CHECK_X25;
                            end
                        end
                    end else begin
                        if (x10 < N10) begin
                            x10 <= x10 + 1;
                            state <= CHECK_X10;
                        end else begin
                            x25 <= x25 + 1;
                            state <= CHECK_X25;
                        end
                    end
                end

                DONE: begin
                    result <= max_coins;
                    valid <= found;
                    done <= 1'b1;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module HeapProbability (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] n,          // Number of nodes (1..8)
    input wire [31:0] b0, b1, b2, b3, b4, b5, b6, b7,  // b values
    input wire [7:0] p0, p1, p2, p3, p4, p5, p6, p7,   // parent indices (0..6, 255 = no parent)
    output reg [31:0] result,
    output reg done
);

    // Parameters
    parameter MAX_N = 8;
    parameter MOD = 1000000007;

    // Internal state
    reg [7:0] node_counter;      // Current node being processed
    reg [7:0] child_counter;      // Child index during multiplication
    reg [7:0] degree_counter;     // Degree index for polynomial ops
    reg [31:0] poly_a [0:MAX_N];  // Polynomial A coefficients
    reg [31:0] poly_b [0:MAX_N];  // Polynomial B coefficients
    reg [31:0] poly_res [0:MAX_N]; // Result polynomial
    reg [31:0] b_values [0:MAX_N]; // Local copy of b_i
    reg [7:0] parent_idx [0:MAX_N]; // Parent indices
    reg [7:0] children [0:MAX_N][0:MAX_N-1]; // Children lists
    reg [7:0] child_count [0:MAX_N]; // Number of children per node
    reg [31:0] powers [0:MAX_N];   // Temporary powers of b
    reg [31:0] inv_int [0:MAX_N]; // Precomputed inverses of 1..MAX_N
    reg processing_done;

    // State machine states
    localparam S_IDLE = 0;
    localparam S_BUILD = 1;
    localparam S_PROCESS = 2;
    localparam S_COMPUTE_RESULT = 3;
    localparam S_DONE = 4;
    reg [2:0] state;

    // Helper: Modular inverse (using Fermat's little theorem, but for small numbers we precompute)
    // We'll precompute inverses for 1..MAX_N (up to 8) and store in inv_int
