);

// Unpack dictionary and input words into 2D arrays for easier access
wire [7:0] dict_words [0:NUM_DICT_WORDS-1][0:MAX_WORD_LEN-1];
wire [7:0] input_word [0:MAX_WORD_LEN-1];

genvar i, j;
generate
    for (i = 0; i < NUM_DICT_WORDS; i = i + 1) begin : unpack_dict
        for (j = 0; j < MAX_WORD_LEN; j = j + 1) begin : unpack_dict_char
            assign dict_words[i][j] = dict_words_packed[i][j*8 +: 8];
        end
    end
    for (j = 0; j < MAX_WORD_LEN; j = j + 1) begin : unpack_input
        assign input_word[j] = input_word_packed[j*8 +: 8];
    end
generate

// State machine states
localparam IDLE = 4'd0;
localparam INIT = 4'd1;
localparam SETUP_PREFIX = 4'd2;
localparam SETUP_DICT = 4'd3;
localparam CHECK_PREFIX = 4'd4;
localparam CALC_COMMON = 4'd5;
localparam CALC_COST = 4'd6;
localparam UPDATE_MIN = 4'd7;
localparam NEXT_DICT = 4'd8;
localparam NEXT_PREFIX = 4'd9;
localparam DONE_STATE = 4'd10;

// Internal registers
reg [3:0] state;
reg [4:0] prefix_len;           // Current prefix length being tried
reg [2:0] dict_idx;             // Current dictionary word index
reg [7:0] min_keystrokes;       // Running minimum keystrokes
reg [7:0] cost;                 // Current cost calculation
reg [4:0] common_len;           // Common prefix length between dict and input

// Helper registers for string comparison
reg [4:0] cmp_idx;              // Character index for comparison
reg prefix_match;               // Flag: current dict word matches prefix
reg [7:0] char_input, char_dict; // Characters being compared

// Combinational logic: check if current dict word starts with current prefix
always @(*) begin
    prefix_match = 1;
    if (prefix_len > input_len || prefix_len > dict_lens[dict_idx]) begin
        prefix_match = 0;
    end else begin
        for (cmp_idx = 0; cmp_idx < prefix_len; cmp_idx = cmp_idx + 1) begin
            if (input_word[cmp_idx] != dict_words[dict_idx][cmp_idx]) begin
                prefix_match = 0;
            end
        end
    end
end

// Combinational logic: calculate common prefix length
always @(*) begin
    common_len = 0;
    for (cmp_idx = 0; cmp_idx < MAX_WORD_LEN; cmp_idx = cmp_idx + 1) begin
        if (cmp_idx < input_len && cmp_idx < dict_lens[dict_idx] && 
            input_word[cmp_idx] == dict_words[dict_idx][cmp_idx]) begin
            common_len = cmp_idx + 1;
        end
    end
end

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        prefix_len <= 0;
        dict_idx <= 0;
        min_keystrokes <= 0;
        cost <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT;
                end
            end

            INIT: begin
                // Initialize with direct typing cost
                min_keystrokes <= input_len;
                prefix_len <= 5'd1;
                dict_idx <= 0;
                state <= (input_len > 0 && input_len <= MAX_WORD_LEN) ? SETUP_PREFIX : DONE_STATE;
            end

            SETUP_PREFIX: begin
                if (prefix_len > input_len) begin
                    state <= DONE_STATE;
                end else begin
                    dict_idx <= 0;
                    state <= SETUP_DICT;
                end
            end

            SETUP_DICT: begin
                if (dict_idx >= NUM_DICT_WORDS) begin
                    state <= NEXT_PREFIX;
                end else begin
                    state <= CHECK_PREFIX;
                end
            end

            CHECK_PREFIX: begin
                // Check if prefix matches (combinational signal prefix_match)
                if (prefix_match && dict_lens[dict_idx] > 0) begin
                    state <= CALC_COMMON;
                end else begin
                    state <= NEXT_DICT;
                end
            end

            CALC_COMMON: begin
                // common_len is already calculated combinational
                state <= CALC_COST;
            end

            CALC_COST: begin
                // cost = prefix_len + 1 + dict_len + input_len - 2*common_len
                cost <= prefix_len + 1 + dict_lens[dict_idx] + input_len - (common_len << 1);
                state <= UPDATE_MIN;
            end

            UPDATE_MIN: begin
                if (cost < min_keystrokes) begin
                    min_keystrokes <= cost;
                end
                state <= NEXT_DICT;
            end

            NEXT_DICT: begin
                dict_idx <= dict_idx + 1;
                state <= SETUP_DICT;
            end

            NEXT_PREFIX: begin
                prefix_len <= prefix_len + 1;
                state <= SETUP_PREFIX;
            end

            DONE_STATE: begin
                result <= min_keystrokes;
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

