                    end
                    idx <= idx + 1;
                end else if (idx == N) begin
                    if (cnt[0]) begin
                        exponent <= total_edges - 1;
                        power <= 1;
                        idx <= idx + 1;
                    end else begin
                        result <= 0;
                        done <= 1;
                        computing <= 0;
                    end
                end else if (idx > N) begin
                    if (exponent > 0) begin
                        power <= (power * 2) % MOD;
                        exponent <= exponent - 1;
                    end else begin
                        result <= power;
                        done <= 1;
                        computing <= 0;
                    end
                end
            end else begin
                done <= 0;
            end
        end
    end
endmodule

