module island_courier (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] n,            // number of islands: 0->1, 1->2, 2->3, 3->4
    input wire [15:0] adj,         // packed adjacency matrix: bit [i*4 + j] = edge i->j for i,j in 0..3. Self-loops must be 1.
    input wire [63:0] L,           // packed tunnel lengths: each 16 bits, L[i][j] at bits 16*(i*4+j)+:16
    output reg [15:0] result,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam CHECK_ORIG = 3'b001;
localparam ITER_START = 3'b010;
localparam ITER_BODY = 3'b011;
localparam EVALUATE = 3'b100;
localparam UPDATE = 3'b101;
localparam DONE = 3'b110;

reg [2:0] state, next_state;
reg [1:0] i_idx, j_idx;
reg [15:0] orig_adj_reg;
reg [15:0] new_adj;
reg [15:0] min_result;
reg [15:0] candidate;
reg strong_flag;

// Function: is_strongly_connected
function automatic is_strongly_connected;
    input [15:0] adj_mat;
    input [1:0] num_nodes;
    integer i, j, k;
    reg [15:0] reach;
    begin
        reach = adj_mat;
        for (k = 0; k < 4; k = k + 1) begin
            if (k < num_nodes) begin
                for (i = 0; i < 4; i = i + 1) begin
                    if (i < num_nodes) begin
                        for (j = 0; j < 4; j = j + 1) begin
                            if (j < num_nodes) begin
                                reach[i*4 + j] = reach[i*4 + j] | (reach[i*4 + k] & reach[k*4 + j]);
                            end
                        end
                    end
                end
            end
        end
        is_strongly_connected = 1'b1;
        for (i = 0; i < 4; i = i + 1) begin
            if (i < num_nodes) begin
                for (j = 0; j < 4; j = j + 1) begin
                    if (j < num_nodes) begin
                        if (reach[i*4 + j] != 1'b1) begin
                            is_strongly_connected = 1'b0;
                        end
                    end
                end
            end
        end
    end
endfunction

// Combinational logic for new_adj and strong_flag
always @(*) begin
    new_adj = orig_adj_reg;
    if (state == ITER_BODY || state == EVALUATE) begin
        if (i_idx < n && j_idx < n) begin
            new_adj[i_idx*4 + j_idx] = 1'b1;
            new_adj[j_idx*4 + i_idx] = 1'b1;
        end
    end
    strong_flag = is_strongly_connected(new_adj, n);
end

// Helper to extract L[i][j]
function automatic [15:0] get_L;
    input [63:0] L_mat;
    input [1:0] i, j;
    begin
        get_L = L_mat[16*(i*4 + j) +: 16];
    end
endfunction

// State transition and output
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 16'h0;
        done <= 1'b0;
        min_result <= 16'hFFFF;
        i_idx <= 2'b00;
        j_idx <= 2'b00;
        orig_adj_reg <= 16'h0;
        candidate <= 16'h0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    orig_adj_reg <= adj;
                    state <= CHECK_ORIG;
                    min_result <= 16'hFFFF;
                end
            end

            CHECK_ORIG: begin
                if (strong_flag) begin
                    result <= 16'h0;
                    done <= 1'b1;
                    state <= DONE;
                end else begin
                    state <= ITER_START;
                end
            end

            ITER_START: begin
                i_idx <= 2'b00;
                j_idx <= 2'b01;
                state <= ITER_BODY;
            end

            ITER_BODY: begin
                if (i_idx < n && j_idx < n) begin
                    state <= EVALUATE;
                end else begin
                    if (j_idx < n - 1) begin
                        j_idx <= j_idx + 1;
                    end else begin
                        j_idx <= 2'b00;
                        if (i_idx < n - 1) begin
                            i_idx <= i_idx + 1;
                        end else begin
                            state <= DONE;
                        end
                    end
                end
            end

            EVALUATE: begin
                if (strong_flag) begin
                    candidate <= get_L(L, i_idx, j_idx);
                    state <= UPDATE;
                end else begin
                    state <= ITER_BODY;
                    if (j_idx < n - 1) begin
                        j_idx <= j_idx + 1;
                    end else begin
                        j_idx <= 2'b00;
                        if (i_idx < n - 1) begin
                            i_idx <= i_idx + 1;
                        end else begin
                            state <= DONE;
                        end
                    end
                end
            end

            UPDATE: begin
                if (candidate < min_result) begin
                    min_result <= candidate;
                end
                state <= ITER_BODY;
                if (j_idx < n - 1) begin
                    j_idx <= j_idx + 1;
                end else begin
                    j_idx <= 2'b00;
                    if (i_idx < n - 1) begin
                        i_idx <= i_idx + 1;
                    end else begin
                        state <= DONE;
                    end
                end
            end

            DONE: begin
                if (min_result != 16'hFFFF) begin
                    result <= min_result;
                end else begin
                    result <= 16'hFFFF;
                end
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module spot #(
    parameter NUM_TOYS = 2,
    parameter NUM_TREES = 1,
    parameter signed [15:0] TOY_X [0:NUM_TOYS-1] = '{10, 10},
    parameter signed [15:0] TOY_Y [0:NUM_TOYS-1] = '{0, 10},
    parameter signed [15:0] TREE_X [0:NUM_TREES-1] = '{9},
    parameter signed [15:0] TREE_Y [0:NUM_TREES-1] = '{1}
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    output reg [31:0] result,   // Q16.16 fixed-point
    output reg done
);
    // State machine states
    localparam IDLE = 3'd0;
    localparam SORT_TREES = 3'd1;
    localparam COMPUTE = 3'd2;
    localparam UPDATE_MAX = 3'd3;
    localparam FINISHED = 3'd4;

    reg [2:0] state, next_state;

    // Internal registers
    reg [31:0] max_leash;           // Current maximum leash length (Q16.16)
    reg [31:0] current_leash;       // Leash length for current toy
    reg [7:0] toy_idx;              // Current toy index
    reg [7:0] tree_idx;             // Current tree index for sorting/computation
    reg [7:0] wrap_count;           // Number of wrapped trees for current toy

    // Tree sorting: we need to order trees by angle relative to origin.
    // Since NUM_TREES <= 4, we can do a bubble sort.
    // We'll store sorted tree indices.
    reg [7:0] sorted_tree_idx [0:3];
    reg [7:0] sort_pass;

    // Fixed-point arithmetic helpers
    // We assume coordinates are integers, and we'll compute distances as Q16.16.
    // Square root approximation: use iterative method.
    // For simplicity, we'll use a combinational sqrt module defined elsewhere.
    // Here we declare a function that computes sqrt of a 32-bit integer (input is squared value, scaled by 2^16).
    // In practice, we would instantiate a sqrt unit.
    // For this specification, we assume a function sqrt32 that returns Q16.16.

    function automatic [31:0] sqrt32(input [31:0] val);
        // Placeholder for square root; in real implementation use a non-restoring algorithm.
        // For simulation, we can use $realtobits($sqrt($bitstoreal(val)));
        // But we avoid system functions for synthesizable code.
        // We'll just return 0 as placeholder; the LLM should replace with proper implementation.
        sqrt32 = 32'd0;
    endfunction

    // Function to compute distance between two points (x1,y1) and (x2,y2) in Q16.16
    function automatic [31:0] distance(input signed [15:0] x1, input signed [15:0] y1,
                                       input signed [15:0] x2, input signed [15:0] y2);
        reg signed [31:0] dx, dy;
        reg [31:0] sq;
        dx = (x2 - x1);
        dy = (y2 - y1);
        // Square and accumulate; note sign extension for negative values.
        sq = (dx * dx) + (dy * dy);  // This yields 32-bit result; but dx*dx may need 32 bits.
        // Convert to Q16.16? Actually, the squared distance is in units of (coord^2). We need sqrt.
        // We'll compute sqrt of sq, and then scale by 2^8? Wait, we need to produce Q16.16.
        // For simplicity, we assume that the sqrt function returns Q16.16 directly.
        // In a real implementation, we would scale appropriately.
        distance = sqrt32(sq << 16);  // Shift left 16 to scale for sqrt Q16.16
    endfunction

    // Function to compare angles: returns 1 if tree angle < toy angle (tree wrapped)
    function automatic angle_less(input signed [15:0] tx, input signed [15:0] ty,
                                  input signed [15:0] ox, input signed [15:0] oy);
        // cross = tx*oy - ty*ox; if cross < 0 then tree angle < toy angle
        reg signed [31:0] cross;
        cross = tx * oy - ty * ox;
        angle_less = (cross < 0);
    endfunction

    // Function to swap two tree indices in sorted array
    task swap_trees(input integer i, input integer j);
        reg [7:0] tmp;
        tmp = sorted_tree_idx[i];
        sorted_tree_idx[i] = sorted_tree_idx[j];
        sorted_tree_idx[j] = tmp;
    endtask

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 32'd0;
            done <= 1'b0;
            max_leash <= 32'd0;
            current_leash <= 32'd0;
            toy_idx <= 8'd0;
            tree_idx <= 8'd0;
            wrap_count <= 8'd0;
            sort_pass <= 8'd0;
            // Initialize sorted_tree_idx
            sorted_tree_idx[0] <= 8'd0;
            sorted_tree_idx[1] <= 8'd1;
            sorted_tree_idx[2] <= 8'd2;
            sorted_tree_idx[3] <= 8'd3;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= (NUM_TREES > 1) ? SORT_TREES : COMPUTE;
                        toy_idx <= 8'd0;
                        max_leash <= 32'd0;
                        done <= 1'b0;
                    end
                end

                SORT_TREES: begin
                    // Bubble sort trees by angle (only if more than one tree)
                    if (NUM_TREES > 1 && sort_pass < NUM_TREES - 1) begin
                        if (tree_idx < NUM_TREES - 1 - sort_pass) begin
                            // Compare angles of tree[sorted_tree_idx[tree_idx]] and tree[sorted_tree_idx[tree_idx+1]]
                            if (!angle_less(TREE_X[sorted_tree_idx[tree_idx]], TREE_Y[sorted_tree_idx[tree_idx]],
                                           TREE_X[sorted_tree_idx[tree_idx+1]], TREE_Y[sorted_tree_idx[tree_idx+1]])) begin
                                // If tree[tree_idx] angle >= tree[tree_idx+1] angle, swap
                                swap_trees(tree_idx, tree_idx + 1);
                            end
                            tree_idx <= tree_idx + 1;
                        end else begin
                            sort_pass <= sort_pass + 1;
                            tree_idx <= 8'd0;
                        end
                    end else begin
                        // Sorting done
                        state <= COMPUTE;
                        tree_idx <= 8'd0;
                    end
                end

                COMPUTE: begin
                    // Compute leash length for current toy (toy_idx)
                    // Determine wrapped trees: those with angle less than toy angle.
                    // Since trees are sorted by angle, wrapped trees are a prefix.
                    // We'll compute step by step.
                    // Reset current_leash
                    current_leash <= 32'd0;
                    wrap_count <= 8'd0;
                    tree_idx <= 8'd0;
                    state <= UPDATE_MAX; // We'll compute in UPDATE_MAX state
                end

                UPDATE_MAX: begin
                    // Accumulate leash length
                    if (tree_idx < NUM_TREES) begin
                        // Check if this tree is wrapped (angle less than toy angle)
                        if (angle_less(TREE_X[sorted_tree_idx[tree_idx]], TREE_Y[sorted_tree_idx[tree_idx]],
                                      TOY_X[toy_idx], TOY_Y[toy_idx])) begin
                            // This tree is wrapped
                            if (wrap_count == 0) begin
                                // First wrapped tree: add distance from origin to this tree
                                current_leash <= current_leash + distance(16'sd0, 16'sd0,
                                    TREE_X[sorted_tree_idx[tree_idx]], TREE_Y[sorted_tree_idx[tree_idx]]);
                            end else begin
                                // Add distance from previous wrapped tree to this tree
                                current_leash <= current_leash + distance(
                                    TREE_X[sorted_tree_idx[tree_idx-1]], TREE_Y[sorted_tree_idx[tree_idx-1]],
                                    TREE_X[sorted_tree_idx[tree_idx]], TREE_Y[sorted_tree_idx[tree_idx]]);
                            end
                            wrap_count <= wrap_count + 1;
                        end
                        tree_idx <= tree_idx + 1;
                    end else begin
                        // All trees processed, now add distance from last wrapped tree to toy
                        if (wrap_count > 0) begin
                            current_leash <= current_leash + distance(
                                TREE_X[sorted_tree_idx[wrap_count-1]], TREE_Y[sorted_tree_idx[wrap_count-1]],
                                TOY_X[toy_idx], TOY_Y[toy_idx]);
                        end else begin
                            // No trees wrapped: leash is straight distance to toy
                            current_leash <= distance(16'sd0, 16'sd0, TOY_X[toy_idx], TOY_Y[toy_idx]);
                        end
                        // Compare with max
                        if (current_leash > max_leash) begin
                            max_leash <= current_leash;
                        end
                        // Next toy
                        if (toy_idx < NUM_TOYS - 1) begin
                            toy_idx <= toy_idx + 1;
                            state <= COMPUTE;
                        end else begin
                            state <= FINISHED;
                        end
                    end
                end

                FINISHED: begin
                    result <= max_leash;
                    done <= 1'b1;
                    if (!start) begin
                        state <= IDLE;
                        done <= 1'b0;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module text_viewport #(
    parameter W = 8,              // Viewport width (3-200, scaled)
    parameter H = 6,              // Viewport height (3-200, scaled)
    parameter MAX_WORDS = 8,      // Maximum number of words
    parameter MAX_WORD_LEN = 8    // Maximum characters per word
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [5:0] F,           // First line index (0-31)

    // Word memory interface (testbench writes words via these signals)
    input wire [$clog2(MAX_WORDS)-1:0] word_addr,  // Word index (0 to MAX_WORDS-1)
    input wire [2:0] char_idx,                     // Character index within word (0 to MAX_WORD_LEN-1)
    input wire [7:0] word_char,                    // ASCII character to store
    input wire word_write,                         // Write enable

    // Output interface
    output reg [7:0] char_out,      // Output character
    output reg char_valid,          // Valid when outputting
    output reg done                 // Done signal
);

// Internal memory for words
reg [7:0] word_memory [0:MAX_WORDS-1][0:MAX_WORD_LEN-1];
reg [3:0] word_len [0:MAX_WORDS-1];  // Actual length of each word
reg [$clog2(MAX_WORDS):0] num_words; // Number of valid words

// Adjusted lines buffer
reg [7:0] adjusted_lines [0:15][0:W-1];  // Up to 16 lines
reg [3:0] line_count;                    // Total number of adjusted lines

// State machine
reg [2:0] state;  // 0=IDLE, 1=READ, 2=BUILD, 3=CALC, 4=RENDER, 5=DONE

// Building state registers
reg [$clog2(MAX_WORDS):0] build_word_idx;  // Current word being processed
reg [3:0] build_line_idx;                  // Current line being built
reg [3:0] build_col;                       // Current column in line

// Rendering state
reg [3:0] render_line;  // Line being rendered (0 to H+1)
reg [3:0] render_col;   // Column in render line (0 to W+3)
reg [7:0] thumb_pos;    // Calculated thumb position (0 to H-3)

// Word write handling
always @(posedge clk) begin
    if (word_write) begin
        word_memory[word_addr][char_idx] <= word_char;
    end
end

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        done <= 0;
        char_valid <= 0;
        num_words <= 0;
        line_count <= 0;
    end else begin
        case (state)
            0: begin  // IDLE
                if (start) begin
                    // Count valid words (non-zero length)
                    num_words <= 0;
                    for (int i = 0; i < MAX_WORDS; i++) begin
                        if (word_memory[i][0] != 8'h00) num_words <= num_words + 1;
                    end
                    state <= 1;
                end
            end

            1: begin  // READ - Compute word lengths
                for (int i = 0; i < MAX_WORDS; i++) begin
                    word_len[i] <= 0;
                    for (int j = 0; j < MAX_WORD_LEN; j++) begin
                        if (word_memory[i][j] != 8'h00) word_len[i] <= word_len[i] + 1;
                    end
                end
                state <= 2;
                build_word_idx <= 0;
                build_line_idx <= 0;
                build_col <= 0;
            end

            2: begin  // BUILD - Line breaking
                if (build_word_idx < num_words) begin
                    // Try to fit current word
                    if (build_col == 0) begin  // First word on line
                        if (word_len[build_word_idx] <= W) begin
                            // Fit entire word
                            for (int i = 0; i < word_len[build_word_idx]; i++) begin
                                adjusted_lines[build_line_idx][build_col + i] <= word_memory[build_word_idx][i];
                            end
                            build_col <= build_col + word_len[build_word_idx];
                        end else begin
                            // Truncate
                            for (int i = 0; i < W; i++) begin
                                adjusted_lines[build_line_idx][i] <= word_memory[build_word_idx][i];
                            end
                            build_col <= W;
                        end
                        build_word_idx <= build_word_idx + 1;
                    end else begin  // Not first word
                        if (build_col + 1 + word_len[build_word_idx] <= W) begin
                            // Fit with space
                            adjusted_lines[build_line_idx][build_col] <= 8'h20;  // space
                            for (int i = 0; i < word_len[build_word_idx]; i++) begin
                                adjusted_lines[build_line_idx][build_col + 1 + i] <= word_memory[build_word_idx][i];
                            end
                            build_col <= build_col + 1 + word_len[build_word_idx];
                            build_word_idx <= build_word_idx + 1;
                        end else begin
                            // Start new line
                            build_line_idx <= build_line_idx + 1;
                            build_col <= 0;
                        end
                    end
                end else begin
                    // All words processed
                    line_count <= build_line_idx + (build_col > 0 ? 1 : 0);
                    state <= 3;
                end
            end

            3: begin  // CALC - Thumb position
                if (line_count > H) begin
                    // T = floor((H-3) * F / (line_count - H))
                    thumb_pos <= ((H - 3) * F) / (line_count - H);
                end else begin
                    thumb_pos <= 0;
                end
                state <= 4;
                render_line <= 0;
                render_col <= 0;
            end

            4: begin  // RENDER
                if (render_col < W + 4) begin
                    // Determine character based on position
                    if (render_line == 0 || render_line == H + 1) begin
                        // Top/bottom border
                        if (render_col == 0 || render_col == W + 3)
                            char_out <= "+";
                        else
                            char_out <= "-";
                    end else begin
                        // Content lines
                        if (render_col == 0)
                            char_out <= "|";
                        else if (render_col == W + 1)
                            char_out <= " ";
                        else if (render_col == W + 2) begin
                            // Scrollbar
                            if (render_line == 1)
                                char_out <= "^";  // Top arrow
                            else if (render_line == H)
                                char_out <= "v";  // Bottom arrow
                            else if (render_line - 1 == thumb_pos + 1)
                                char_out <= "X";  // Thumb
                            else
                                char_out <= " ";  // Empty space
                        end else if (render_col == W + 3)
                            char_out <= "|";
                        else begin
                            // Text area (columns 1 to W)
                            if (render_line - 1 + F < line_count) begin
                                char_out <= adjusted_lines[render_line - 1 + F][render_col - 1];
                                // If character is zero (unused), show space
                                if (char_out == 8'h00) char_out <= " ";
                            end else begin
                                char_out <= " ";
                            end
                        end
                    end
                    char_valid <= 1;
                    render_col <= render_col + 1;
                end else begin
                    // End of line
                    char_valid <= 0;
                    render_col <= 0;
                    render_line <= render_line + 1;
                    if (render_line == H + 1) begin
                        state <= 5;  // DONE
                    end
                end
            end

            5: begin  // DONE
                done <= 1;
                if (!start) state <= 0;  // Reset when start goes low
            end
        endcase
    end
end

endmodule

module max_hit_calculator #(parameter N=8) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] start_angles [0:N-1],
    input wire [31:0] end_angles   [0:N-1],
    input wire [N-1:0] valid,
    output reg [7:0] max_overlap,
    output reg done
);

// Constants
localparam TWO_PI = 32'd6283185; // 2 * pi * 1e6 (micro-radians)

// State definitions
localparam IDLE = 3'b000;
localparam SPLIT = 3'b001;
localparam GEN_EVENTS = 3'b010;
localparam SORT = 3'b011;
localparam SWEEP = 3'b100;
localparam DONE = 3'b101;

// Internal registers
reg [2:0] state;
reg [7:0] idx;          // general index
reg [7:0] idx2;         // second index for sorting
reg [7:0] interval_cnt; // number of intervals after splitting
reg [7:0] event_cnt;    // number of events

// Interval buffers: up to 2*N intervals
reg [31:0] starts [0:2*N-1];
reg [31:0] ends   [0:2*N-1];

// Event buffers: each event is 33 bits: [32:1] angle, [0] type (1=start, 0=end)
reg [32:0] events [0:4*N-1];

// Current count and max count
reg [7:0] count;
reg [7:0] max_count;

// Helper task to reset internal state
task reset_internal;
begin
    interval_cnt <= 0;
    event_cnt <= 0;
    count <= 0;
    max_count <= 0;
    idx <= 0;
    idx2 <= 0;
end
endtask

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        max_overlap <= 0;
        reset_internal;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= SPLIT;
                    reset_internal;
                end
            end

            SPLIT: begin
                if (idx < N) begin
                    if (valid[idx]) begin
                        // Check if wrap-around
                        if (start_angles[idx] <= end_angles[idx]) begin
                            // No wrap
                            starts[interval_cnt] <= start_angles[idx];
                            ends[interval_cnt] <= end_angles[idx];
                            interval_cnt <= interval_cnt + 1;
                        end else begin
                            // Wrap: split into two intervals
                            // First: start to TWO_PI
                            starts[interval_cnt] <= start_angles[idx];
                            ends[interval_cnt] <= TWO_PI;
                            interval_cnt <= interval_cnt + 1;
                            // Second: 0 to end
                            starts[interval_cnt] <= 0;
                            ends[interval_cnt] <= end_angles[idx];
                            interval_cnt <= interval_cnt + 1;
                        end
                    end
                    idx <= idx + 1;
                end else begin
                    idx <= 0;
                    state <= GEN_EVENTS;
                end
            end

            GEN_EVENTS: begin
                if (idx < interval_cnt) begin
                    // Create start event
                    events[event_cnt] <= {starts[idx], 1'b1};
                    event_cnt <= event_cnt + 1;
                    // Create end event
                    events[event_cnt] <= {ends[idx], 1'b0};
                    event_cnt <= event_cnt + 1;
                    idx <= idx + 1;
                end else begin
                    // If no events, go directly to DONE
                    if (event_cnt == 0) begin
                        state <= DONE;
                    end else begin
                        state <= SORT;
                        idx <= 0;
                        idx2 <= 0;
                    end
                end
            end

            SORT: begin
                // Bubble sort: one swap per clock cycle
                if (idx < event_cnt - 1) begin
                    if (idx2 < event_cnt - idx - 1) begin
                        // Compare events[idx2] and events[idx2+1]
                        if (events[idx2][32:1] > events[idx2+1][32:1] || 
                            (events[idx2][32:1] == events[idx2+1][32:1] && events[idx2][0] > events[idx2+1][0])) begin
                            // Swap
                            events[idx2] <= events[idx2+1];
                            events[idx2+1] <= events[idx2];
                        end
                        idx2 <= idx2 + 1;
                    end else begin
                        // Next pass
                        idx <= idx + 1;
                        idx2 <= 0;
                    end
                end else begin
                    // Sorting done
                    state <= SWEEP;
                    idx <= 0;
                    count <= 0;
                    max_count <= 0;
                end
            end

            SWEEP: begin
                if (idx < event_cnt) begin
                    // Update count
                    if (events[idx][0] == 1'b1) begin // start event
                        count <= count + 1;
                        if (count + 1 > max_count) begin
                            max_count <= count + 1;
                        end
                    end else begin // end event
                        count <= count - 1;
                    end
                    idx <= idx + 1;
                end else begin
                    state <= DONE;
                end
            end

            DONE: begin
                max_overlap <= max_count;
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module movie_theme (
    input clk,
    input rst_n,
    input in_start,
    input in_valid,
    input [31:0] in_data,
    output reg out_done,
    output reg out_possible
);

    // State definitions
    localparam IDLE = 0;
    localparam READ_F = 1;
    localparam READ_T = 2;
    localparam READ_N = 3;
    localparam READ_START = 4;
    localparam READ_END = 5;
    localparam COMPUTE = 6;
    localparam DP_LOOP = 7;
    localparam CHECK_RESULT = 8;
    localparam NEXT_FREQ = 9;
    localparam DONE = 10;

    // Maximum constants
    localparam MAX_FREQ = 10;
    localparam MAX_INTERVAL = 100;

    // Registers for state and data
    reg [4:0] state;
    reg [31:0] f;
    reg [31:0] freq_count;
    reg [31:0] current_t;
    reg [31:0] current_n;
    reg [31:0] interval_count;
    reg [31:0] L_array [0:MAX_INTERVAL-1];
    reg [31:0] H_array [0:MAX_INTERVAL-1];
    reg [31:0] gap_array [0:MAX_INTERVAL-1];
    reg [31:0] prev_end;
    reg [31:0] temp_start;
    reg overall_possible;
    reg skip_dp;
    reg dp_plus;
    reg dp_minus;
    reg [31:0] i;

    // State transition and data processing
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            out_done <= 0;
            out_possible <= 0;
            f <= 0;
            freq_count <= 0;
            current_t <= 0;
            current_n <= 0;
            interval_count <= 0;
            prev_end <= 0;
            temp_start <= 0;
            overall_possible <= 1;
            skip_dp <= 0;
            dp_plus <= 0;
            dp_minus <= 0;
            i <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (in_start) begin
                        state <= READ_F;
                        overall_possible <= 1;
                        freq_count <= 0;
                    end
                end

                READ_F: begin
                    if (in_valid) begin
                        f <= in_data;
                        state <= READ_T;
                    end
                end

                READ_T: begin
                    if (in_valid) begin
                        current_t <= in_data;
                        state <= READ_N;
                    end
                end

                READ_N: begin
                    if (in_valid) begin
                        current_n <= in_data;
                        interval_count <= 0;
                        skip_dp <= 0;
                        state <= READ_START;
                    end
                end

                READ_START: begin
                    if (in_valid) begin
                        temp_start <= in_data;
                        state <= READ_END;
                    end
                end

                READ_END: begin
                    if (in_valid) begin
                        // Compute L and H
                        L_array[interval_count] <= in_data - temp_start;
                        H_array[interval_count] <= current_t - (in_data - temp_start);
                        // Check if L exceeds current_t
                        if (in_data - temp_start > current_t) begin
                            skip_dp <= 1;
                            overall_possible <= 0;
                        end
                        // Compute gap if not first interval
                        if (interval_count > 0) begin
                            gap_array[interval_count-1] <= temp_start - prev_end;
                        end
                        prev_end <= in_data;
                        interval_count <= interval_count + 1;
                        if (interval_count + 1 < current_n) begin
                            state <= READ_START;
                        end else begin
                            state <= COMPUTE;
                        end
                    end
                end

                COMPUTE: begin
                    if (skip_dp) begin
                        state <= NEXT_FREQ;
                    end else if (current_n == 1) begin
                        // Single interval, always possible if L <= current_t
                        state <= NEXT_FREQ;
                    end else begin
                        // Initialize DP
                        dp_plus <= 1;
                        dp_minus <= 1;
                        i <= 0;
                        state <= DP_LOOP;
                    end
                end

                DP_LOOP: begin
                    if (i < current_n - 1) begin
                        // Compute compatibility conditions
                        reg comp_pp, comp_mm;
                        comp_pp = (L_array[i] <= H_array[i+1]);
                        comp_mm = (L_array[i+1] <= H_array[i]);
                        // Update DP states
                        dp_plus <= (dp_plus && comp_pp) || (dp_minus && (gap_array[i] >= 1));
                        dp_minus <= (dp_plus && (gap_array[i] >= 1)) || (dp_minus && comp_mm);
                        i <= i + 1;
                    end else begin
                        state <= CHECK_RESULT;
                    end
                end

                CHECK_RESULT: begin
                    if (!(dp_plus || dp_minus)) begin
                        overall_possible <= 0;
                    end
                    state <= NEXT_FREQ;
                end

                NEXT_FREQ: begin
                    freq_count <= freq_count + 1;
                    if (freq_count + 1 < f) begin
                        state <= READ_T;
                    end else begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    out_done <= 1;
                    out_possible <= overall_possible;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module indoorienteering (
    input clk,
    input rst_n,
    input start,
    input [2:0] n,
    input [7:0] L,
    input [7:0] dist_00, dist_01, dist_02, dist_03,
    input [7:0] dist_10, dist_11, dist_12, dist_13,
    input [7:0] dist_20, dist_21, dist_22, dist_23,
    input [7:0] dist_30, dist_31, dist_32, dist_33,
    output reg possible,
    output reg done
);

// State definitions
localparam IDLE = 2'b00;
localparam COMPARE = 2'b01;
localparam DONE = 2'b10;

reg [1:0] state;
reg [2:0] perm_index;
reg found;
wire [2:0] max_perm;
wire [15:0] L_ext = {8'd0, L};

// Distance matrix array
wire [7:0] dist [0:3][0:3];
assign dist[0][0] = dist_00; assign dist[0][1] = dist_01; assign dist[0][2] = dist_02; assign dist[0][3] = dist_03;
assign dist[1][0] = dist_10; assign dist[1][1] = dist_11; assign dist[1][2] = dist_12; assign dist[1][3] = dist_13;
assign dist[2][0] = dist_20; assign dist[2][1] = dist_21; assign dist[2][2] = dist_22; assign dist[2][3] = dist_23;
assign dist[3][0] = dist_30; assign dist[3][1] = dist_31; assign dist[3][2] = dist_32; assign dist[3][3] = dist_33;

// Combinational logic to compute total distance for current permutation
reg [15:0] total_sum;
always @(*) begin
    total_sum = 0;
    case (n)
        3'd2: begin
            total_sum = dist[0][1] + dist[1][0];
        end
        3'd3: begin
            case (perm_index)
                3'd0: total_sum = dist[0][1] + dist[1][2] + dist[2][0];
                3'd1: total_sum = dist[0][2] + dist[2][1] + dist[1][0];
                default: total_sum = 0;
            endcase
        end
        3'd4: begin
            case (perm_index)
                3'd0: total_sum = dist[0][1] + dist[1][2] + dist[2][3] + dist[3][0];
                3'd1: total_sum = dist[0][1] + dist[1][3] + dist[3][2] + dist[2][0];
                3'd2: total_sum = dist[0][2] + dist[2][1] + dist[1][3] + dist[3][0];
                3'd3: total_sum = dist[0][2] + dist[2][3] + dist[3][1] + dist[1][0];
                3'd4: total_sum = dist[0][3] + dist[3][1] + dist[1][2] + dist[2][0];
                3'd5: total_sum = dist[0][3] + dist[3][2] + dist[2][1] + dist[1][0];
                default: total_sum = 0;
            endcase
        end
        default: total_sum = 0;
    endcase
end

// Determine max permutations based on n
assign max_perm = (n == 2) ? 1 : (n == 3) ? 2 : 6;

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        perm_index <= 0;
        found <= 0;
        done <= 0;
        possible <= 0;
    end else begin
        done <= 0;
        case (state)
            IDLE: begin
                if (start) begin
                    state <= COMPARE;
                    perm_index <= 0;
                    found <= 0;
                end
            end
            COMPARE: begin
                // Check current permutation
                if (total_sum == L_ext) found <= 1;
                // Move to next permutation or finish
                if (perm_index < max_perm - 1) begin
                    perm_index <= perm_index + 1;
                end else begin
                    state <= DONE;
                end
            end
            DONE: begin
                done <= 1;
                possible <= found;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

cocotb_testbench:
import cocotb
from cocotb.triggers import Timer, RisingEdge, FallingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# Configuration
DATA_WIDTH = 8
L_WIDTH = 8
N_MAX = 4
CLK_PERIOD_NS = 10
MAX_CYCLES = 1000

# Helper functions (Section A)
def is_value_defined(value):
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    try:
        return int(value)
    except ValueError:
        return default

def to_signed(val, bits):
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(value, bits):
    max_val = (1 << bits) - 1
    if value < 0:
        return from_signed(max(-((1 << (bits-1))), min((1 << (bits-1)) - 1, value)), bits)
    return min(max_val, max(0, value))

# Sequential module helpers
async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout: done not asserted after {max_cycles} cycles")

async def start_computation(dut):
    dut.start.value = 1
    await RisingEdge(dut.clk)
    dut.start.value = 0

# Helper to set distance matrix
def set_dist_matrix(dut, dist_matrix, n):
    for i in range(4):
        for j in range(4):
            port_name = f'dist_{i}{j}'
            if has_signal(dut, port_name):
                if i < n and j < n:
                    val = dist_matrix[i][j]
                else:
                    val = 0
                getattr(dut, port_name).value = clamp_to_width(val, DATA_WIDTH)
            else:
                raise TestFailure(f"Port {port_name} not found")

# Brute-force expected result (for reference, not used in test)
def brute_force_expected(n, L, dist_matrix):
    import itertools
    nodes = list(range(n))
    perms = list(itertools.permutations(nodes[1:]))
    for perm in perms:
        total = 0
        prev = 0
        for node in perm:
            total += dist_matrix[prev][node]
            prev = node
        total += dist_matrix[prev][0]
        if total == L:
            return 1
    return 0

# Main test
@cocotb.test(timeout_time=5000, timeout_unit="ms")
async def test_indoorienteering(dut):
    # Start clock
    cocotb.start_soon(Clock(dut.clk, CLK_PERIOD_NS, units='ns').start())

    # Reset
    await reset_dut(dut)

    # Test cases: (n, L, dist_matrix, expected_possible)
    dist1 = [
        [0, 3, 2, 1],
        [3, 0, 1, 3],
        [2, 1, 0, 2],
        [1, 3, 2, 0]
    ]
    dist2 = [
        [0, 1, 2],
        [1, 0, 3],
        [2, 3, 0]
    ]
    dist3 = [
        [0, 5],
        [5, 0]
    ]
    dist4 = [
        [0, 1, 2, 3],
        [1, 0, 4, 5],
        [2, 4, 0, 6],
        [3, 5, 6, 0]
    ]

    test_cases = [
        (4, 10, dist1, 1),
        (3, 5, dist2, 0),
        (2, 10, dist3, 1),
        (4, 30, dist4, 0),
    ]

    passed = 0
    failed = 0

    for i, (n, L, dist_matrix, expected) in enumerate(test_cases):
        cocotb.log.info(f"Test {i+1}: n={n}, L={L}")

        # Set inputs
        dut.n.value = n
        dut.L.value = L
        set_dist_matrix(dut, dist_matrix, n)

        # Start computation
        await start_computation(dut)

        # Wait for done
        await wait_for_done(dut)

        # Read result
        if not is_value_defined(dut.possible.value):
            raise TestFailure("Result is undefined (X/Z)")

        result = int(dut.possible.value)

        if result != expected:
            cocotb.log.error(f"  FAIL: expected {expected}, got {result}")
            failed += 1
        else:
            cocotb.log.info(f"  PASS: result = {result}")
            passed += 1

    cocotb.log.info(f"{'='*50}")
    cocotb.log.info(f"Results: {passed}/{passed+failed} tests passed")

    if failed > 0:
        raise TestFailure(f"{failed} tests failed")

