module photo_validator (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] length,
    input wire [127:0] packed_arr,  // Packed array of 16 8-bit values: arr[0] in bits 7:0, arr[1] in 15:8, ..., arr[15] in 127:120
    output reg result,
    output reg done
);

// State encoding
localparam IDLE = 3'b000;
localparam INIT_I = 3'b001;
localparam CHECK_LEFT = 3'b010;
localparam CHECK_RIGHT = 3'b011;
localparam FOUND_VALID = 3'b100;
localparam DONE = 3'b101;

reg [2:0] state;
reg [3:0] i, j, k;          // counters up to 16
reg [3:0] captured_len;      // captured length (4-bit)
reg [127:0] captured_arr;    // captured array
reg left_found;
reg [7:0] left_min_above;
reg right_found;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 0;
        done <= 0;
        i <= 0;
        j <= 0;
        k <= 0;
        left_found <= 0;
        left_min_above <= 8'hFF;
        right_found <= 0;
        captured_len <= 0;
        captured_arr <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                result <= 0;
                if (start) begin
                    captured_arr <= packed_arr;
                    captured_len <= length;
                    i <= 0;
                    state <= INIT_I;
                end
            end

            INIT_I: begin
                if (i >= captured_len) begin
                    // No valid position found
                    result <= 0;
                    done <= 1;
                    state <= DONE;
                end else begin
                    left_found <= 0;
                    left_min_above <= 8'hFF;
                    j <= 0;
                    state <= CHECK_LEFT;
                end
            end

            CHECK_LEFT: begin
                if (j < i) begin
                    // Compare arr[j] and arr[i]
                    if (captured_arr[8*j +: 8] > captured_arr[8*i +: 8]) begin
                        left_found <= 1;
                        if (captured_arr[8*j +: 8] < left_min_above)
                            left_min_above <= captured_arr[8*j +: 8];
                    end
                    j <= j + 1;
                end else begin
                    // Finished scanning left
                    if (left_found) begin
                        k <= i + 1;
                        right_found <= 0;
                        state <= CHECK_RIGHT;
                    end else begin
                        // No left taller person, move to next i
                        i <= i + 1;
                        state <= INIT_I;
                    end
                end
            end

            CHECK_RIGHT: begin
                if (k < captured_len) begin
                    if (captured_arr[8*k +: 8] > captured_arr[8*i +: 8] && captured_arr[8*k +: 8] > left_min_above) begin
                        right_found <= 1;
                        state <= FOUND_VALID;
                    end else begin
                        k <= k + 1;
                    end
                end else begin
                    // No right person found for this i
                    i <= i + 1;
                    state <= INIT_I;
                end
            end

            FOUND_VALID: begin
                result <= 1;
                done <= 1;
                state <= DONE;
            end

            DONE: begin
                // Stay here until reset
                if (!rst_n) begin
                    state <= IDLE;
                    result <= 0;
                    done <= 0;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module digit_product_counter (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [9:0] L,
    input wire [9:0] R,
    output reg [31:0] count_1,
    output reg [31:0] count_2,
    output reg [31:0] count_3,
    output reg [31:0] count_4,
    output reg [31:0] count_5,
    output reg [31:0] count_6,
    output reg [31:0] count_7,
    output reg [31:0] count_8,
    output reg [31:0] count_9,
    output reg done
);

// State encoding
localparam IDLE = 3'b000;
localparam COMPUTE = 3'b001;
localparam INCREMENT = 3'b010;
localparam DONE = 3'b011;

// Sub-state for compute
localparam COMPUTE_INIT = 3'b000;
localparam COMPUTE_GET_DIGIT = 3'b001;
localparam COMPUTE_MULTIPLY = 3'b010;
localparam COMPUTE_UPDATE = 3'b011;
localparam COMPUTE_CHECK = 3'b100;

reg [9:0] current_number;
reg [15:0] product;
reg [9:0] temp;
reg [3:0] digit;
reg [2:0] state;
reg [2:0] compute_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset
        state <= IDLE;
        done <= 0;
        count_1 <= 0;
        count_2 <= 0;
        count_3 <= 0;
        count_4 <= 0;
        count_5 <= 0;
        count_6 <= 0;
        count_7 <= 0;
        count_8 <= 0;
        count_9 <= 0;
        current_number <= 0;
        product <= 0;
        temp <= 0;
        digit <= 0;
        compute_state <= COMPUTE_INIT;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Initialize counts to 0
                    count_1 <= 0;
                    count_2 <= 0;
                    count_3 <= 0;
                    count_4 <= 0;
                    count_5 <= 0;
                    count_6 <= 0;
                    count_7 <= 0;
                    count_8 <= 0;
                    count_9 <= 0;
                    current_number <= L;
                    state <= COMPUTE;
                    compute_state <= COMPUTE_INIT;
                end
            end

            COMPUTE: begin
                case (compute_state)
                    COMPUTE_INIT: begin
                        temp <= current_number;
                        product <= 1;
                        compute_state <= COMPUTE_GET_DIGIT;
                    end

                    COMPUTE_GET_DIGIT: begin
                        if (temp == 0) begin
                            compute_state <= COMPUTE_CHECK;
                        end else begin
                            // Get the last digit
                            digit <= temp % 10;
                            temp <= temp / 10;
                            compute_state <= COMPUTE_MULTIPLY;
                        end
                    end

                    COMPUTE_MULTIPLY: begin
                        if (digit != 0) begin
                            product <= product * digit;
                        end
                        compute_state <= COMPUTE_GET_DIGIT;
                    end

                    COMPUTE_CHECK: begin
                        if (product < 10) begin
                            // We have the final digit
                            // Increment the count for this digit
                            state <= INCREMENT;
                        end else begin
                            // Need to reduce further
                            temp <= product;
                            product <= 1;
                            compute_state <= COMPUTE_INIT;
                        end
                    end
                endcase
            end

            INCREMENT: begin
                case (product)
                    1: count_1 <= count_1 + 1;
                    2: count_2 <= count_2 + 1;
                    3: count_3 <= count_3 + 1;
                    4: count_4 <= count_4 + 1;
                    5: count_5 <= count_5 + 1;
                    6: count_6 <= count_6 + 1;
                    7: count_7 <= count_7 + 1;
                    8: count_8 <= count_8 + 1;
                    9: count_9 <= count_9 + 1;
                    default: ; // Should not happen
                endcase

                // Increment current_number
                current_number <= current_number + 1;
                // Check if we are done
                if (current_number + 1 > R) begin
                    state <= DONE;
                end else begin
                    state <= COMPUTE;
                    compute_state <= COMPUTE_INIT;
                end
            end

            DONE: begin
                done <= 1;
                if (!start) begin
                    state <= IDLE;
                end
            end
        endcase
    end
end

endmodule

module profit_calculator (
    input clk,
    input rst_n,
    input start,
    input [31:0] profit_cents,      // Total profit in cents
    input [15:0] pita_profit_cents, // Profit per pita in cents
    input [15:0] pizza_profit_cents, // Profit per pizza in cents
    output reg [15:0] pitas,
    output reg [15:0] pizzas,
    output reg valid,
    output reg done
);

// Parameters for maximum values
parameter MAX_ITERATIONS = 1000;
parameter MAX_SOLUTIONS = 16;

// State machine states
parameter IDLE = 3'b000;
parameter COMPUTE = 3'b001;
parameter CHECK = 3'b010;
parameter OUTPUT = 3'b011;
parameter INCREMENT = 3'b100;
parameter FINISHED = 3'b101;

// Internal registers
reg [2:0] state;
reg [15:0] x;           // Current pita count
reg [15:0] y;           // Current pizza count  
reg [31:0] remainder;   // Remaining profit after x*pita
reg [7:0] solution_count;
reg [31:0] product;     // x * pita_profit

// Combinational calculations
wire [31:0] product_wire = x * pita_profit_cents;
wire [31:0] remainder_wire = profit_cents - product_wire;
wire [31:0] y_calc = remainder_wire / pizza_profit_cents;
wire [31:0] check = y_calc * pizza_profit_cents;
wire valid_solution = (product_wire <= profit_cents) && 
                      (remainder_wire >= 0) && 
                      (check == remainder_wire) &&
                      (y_calc <= 16'hFFFF);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        pitas <= 0;
        pizzas <= 0;
        valid <= 0;
        done <= 0;
        x <= 0;
        y <= 0;
        solution_count <= 0;
    end else begin
        case (state)
            IDLE: begin
                valid <= 0;
                done <= 0;
                if (start) begin
                    x <= 0;
                    y <= 0;
                    solution_count <= 0;
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                product <= product_wire;
                state <= CHECK;
            end

            CHECK: begin
                if (x > MAX_ITERATIONS || solution_count >= MAX_SOLUTIONS) begin
                    state <= FINISHED;
                end else if (valid_solution) begin
                    pitas <= x;
                    pizzas <= y_calc;
                    state <= OUTPUT;
                end else begin
                    state <= INCREMENT;
                end
            end

            OUTPUT: begin
                valid <= 1;
                solution_count <= solution_count + 1;
                state <= INCREMENT;
            end

            INCREMENT: begin
                valid <= 0;
                x <= x + 1;
                state <= COMPUTE;
            end

            FINISHED: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

