// Verilog module: finds cheapest price by rearranging magnets with optional flipping.
// Scaled: N=4 magnets, each up to 3 digits (4‑bit per digit), length 1‑3.
// Interface: sequential with start/done, uses state machine to enumerate all flip combinations.
// Result is output as a variable‑length digit array (up to 12 digits).

module cheapest_price (
    input wire clk,
    input wire rst_n,          // active‑low reset
    input wire start,          // pulse high to start computation
    // Magnet inputs: 4 magnets, each as 12‑bit vector (3 digits * 4 bits) + 2‑bit length
    input wire [11:0] mag_data [3:0],    // packed digits: each 4‑bit digit, LSB = first digit
    input wire [1:0]  mag_len  [3:0],    // number of digits (1‑3, 0 means unused)
    // Output: result digits, length, and valid flag
    output reg [3:0]  result_digits [11:0], // 12 digits, each 4‑bit (0‑9)
    output reg [3:0]  result_len,           // number of valid digits (0‑12)
    output reg        result_valid           // high when result is ready
);

// Parameters
localparam MAX_MAGNETS = 4;
localparam MAX_DIGITS_PER_MAG = 3;
localparam MAX_TOTAL_DIGITS = MAX_MAGNETS * MAX_DIGITS_PER_MAG;
localparam DIGIT_WIDTH = 4;

// State machine states
localparam S_IDLE = 0;
localparam S_LOAD = 1;
localparam S_COMB_START = 2;
localparam S_COMB_SELECT = 3;
localparam S_SORT = 4;
localparam S_CONCAT = 5;
localparam S_COMPARE = 6;
localparam S_UPDATE = 7;
localparam S_NEXT_COMB = 8;
localparam S_DONE = 9;

reg [3:0] state, next_state;

// Storage for original magnets
reg [11:0] orig_data [3:0];
reg [1:0]  orig_len  [3:0];

// Flipped versions (only valid if all digits flippable)
reg [11:0] flip_data [3:0];
reg [1:0]  flip_len  [3:0];
reg        flip_valid [3:0];  // 1 if flipping is allowed

// Current combination index (bitmask for flip selection)
reg [3:0] comb;  // 4 bits, each bit = 1 means use flipped version

// Selected strings for current combination
reg [11:0] sel_data [3:0];
reg [1:0]  sel_len  [3:0];

// Sorted strings (after sorting network)
reg [11:0] sorted_data [3:0];
reg [1:0]  sorted_len  [3:0];

// Candidate concatenation (up to 12 digits)
reg [3:0] cand_digits [11:0];
reg [3:0] cand_len;

// Current best concatenation
reg [3:0] best_digits [11:0];
reg [3:0] best_len;
reg       best_valid;

// Helper: check if a digit is flippable (0,1,6,8,9)
function automatic is_flippable_digit(input [3:0] d);
begin
    is_flippable_digit = (d == 4'd0 || d == 4'd1 || d == 4'd6 || d == 4'd8 || d == 4'd9);
end
endfunction

// Helper: flip a single digit
function automatic [3:0] flip_digit(input [3:0] d);
begin
    case (d)
        4'd0: flip_digit = 4'd0;
        4'd1: flip_digit = 4'd1;
        4'd6: flip_digit = 4'd9;
        4'd8: flip_digit = 4'd8;
        4'd9: flip_digit = 4'd6;
        default: flip_digit = 4'd15; // invalid marker
    endcase
end
endfunction

// Helper: compute flipped magnet if all digits flippable
task automatic compute_flip(input [11:0] data_in, input [1:0] len_in,
                            output [11:0] data_out, output [1:0] len_out, output valid);
    integer i;
    reg [3:0] d;
begin
    valid = 1;
    len_out = len_in;
    // Reverse order and flip each digit
    for (i = 0; i < MAX_DIGITS_PER_MAG; i = i + 1) begin
        if (i < len_in) begin
            d = data_in[ (i*DIGIT_WIDTH) +: DIGIT_WIDTH ]; // get digit
            if (!is_flippable_digit(d)) begin
                valid = 0;
                data_out = 12'd0;
                len_out = 2'd0;
                return;
            end
            data_out[ ((len_in-1-i)*DIGIT_WIDTH) +: DIGIT_WIDTH ] = flip_digit(d);
        end else begin
            // pad with zeros (not used)
            data_out[ (i*DIGIT_WIDTH) +: DIGIT_WIDTH ] = 4'd0;
        end
    end
end
endtask

// Helper: extract digit from a packed magnet data at position idx (0‑based, 0 = first digit)
function automatic [3:0] get_digit(input [11:0] data, input [1:0] len, input integer idx);
begin
    if (idx < len)
        get_digit = data[ (idx*DIGIT_WIDTH) +: DIGIT_WIDTH ];
    else
        get_digit = 4'd0; // padding
end
endfunction

// Helper: compare two strings A and B (as packed data+len) for sorting.
// Returns 1 if A should come before B (i.e., A+B <= B+A lexicographically).
function automatic compare_strings(input [11:0] dataA, input [1:0] lenA,
                                   input [11:0] dataB, input [1:0] lenB);
    integer i;
    reg [3:0] digitA, digitB;
    reg [3:0] concatA [5:0]; // max length A+B = 6 digits
    reg [3:0] concatB [5:0];
    integer totalA, totalB;
begin
    totalA = lenA + lenB;
    totalB = lenB + lenA; // same
    // Build concatenated A+B
    for (i = 0; i < 6; i = i + 1) begin
        if (i < lenA) begin
            concatA[i] = get_digit(dataA, lenA, i);
        end else if (i < totalA) begin
            concatA[i] = get_digit(dataB, lenB, i - lenA);
        end else begin
            concatA[i] = 4'd0;
        end
    end
    // Build concatenated B+A
    for (i = 0; i < 6; i = i + 1) begin
        if (i < lenB) begin
            concatB[i] = get_digit(dataB, lenB, i);
        end else if (i < totalB) begin
            concatB[i] = get_digit(dataA, lenA, i - lenB);
        end else begin
            concatB[i] = 4'd0;
        end
    end
    // Lexicographic comparison
    for (i = 0; i < 6; i = i + 1) begin
        if (concatA[i] < concatB[i]) begin
            compare_strings = 1; // A < B
            return;
        end else if (concatA[i] > concatB[i]) begin
            compare_strings = 0; // A > B
            return;
        end
    end
    // equal
    compare_strings = 1; // consider equal as A before B (doesn't matter)
end
endfunction

// Helper: swap two strings in the sorting network
task automatic swap_strings(inout [11:0] data1, inout [1:0] len1,
                            inout [11:0] data2, inout [1:0] len2);
    reg [11:0] tmp_data;
    reg [1:0] tmp_len;
begin
    tmp_data = data1; tmp_len = len1;
    data1 = data2; len1 = len2;
    data2 = tmp_data; len2 = tmp_len;
end
endtask

// Helper: concatenate sorted strings into candidate digits
task automatic concatenate_sorted;
    integer i, pos;
begin
    pos = 0;
    for (i = 0; i < MAX_MAGNETS; i = i + 1) begin
        if (sorted_len[i] > 0) begin
            for (integer j = 0; j < sorted_len[i]; j = j + 1) begin
                cand_digits[pos] = get_digit(sorted_data[i], sorted_len[i], j);
                pos = pos + 1;
            end
        end
    end
    cand_len = pos;
end
endtask

// Helper: compare candidate with best (lexicographic)
function automatic candidate_better;
    integer i;
begin
    if (!best_valid) begin
        candidate_better = 1; // any candidate is better than none
        return;
    end
    if (cand_len < best_len) begin // shorter string is smaller if prefix equal
        candidate_better = 1;
        return;
    end else if (cand_len > best_len) begin
        candidate_better = 0;
        return;
    end
    // same length, compare digit by digit
    for (i = 0; i < cand_len; i = i + 1) begin
        if (cand_digits[i] < best_digits[i]) begin
            candidate_better = 1;
            return;
        end else if (cand_digits[i] > best_digits[i]) begin
            candidate_better = 0;
            return;
        end
    end
    candidate_better = 0; // equal
end
endfunction

// State transition and output logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        result_valid <= 0;
        best_valid <= 0;
        comb <= 4'd0;
    end else begin
        case (state)
            S_IDLE: begin
                if (start) begin
                    state <= S_LOAD;
                    result_valid <= 0;
                    best_valid <= 0;
                    comb <= 4'd0;
                end
            end
            S_LOAD: begin
                // Store original magnets and compute flipped versions
                for (integer i = 0; i < MAX_MAGNETS; i = i + 1) begin
                    orig_data[i] <= mag_data[i];
                    orig_len[i]  <= mag_len[i];
                    compute_flip(mag_data[i], mag_len[i], flip_data[i], flip_len[i], flip_valid[i]);
                end
                state <= S_COMB_START;
            end
            S_COMB_START: begin
                // Prepare to iterate over combinations
                comb <= 4'd0;
                state <= S_COMB_SELECT;
            end
            S_COMB_SELECT: begin
                // Select strings based on current combination
                for (integer i = 0; i < MAX_MAGNETS; i = i + 1) begin
                    if (comb[i] && flip_valid[i]) begin
                        sel_data[i] <= flip_data[i];
                        sel_len[i]  <= flip_len[i];
                    end else begin
                        sel_data[i] <= orig_data[i];
                        sel_len[i]  <= orig_len[i];
                    end
                end
                state <= S_SORT;
            end
            S_SORT: begin
                // Sorting network for 4 strings using bubble sort (2 passes)
                // Pass 1
                if (compare_strings(sel_data[0], sel_len[0], sel_data[1], sel_len[1])) begin
                    // keep order
                end else begin
                    swap_strings(sel_data[0], sel_len[0], sel_data[1], sel_len[1]);
                end
                if (compare_strings(sel_data[1], sel_len[1], sel_data[2], sel_len[2])) begin
                end else begin
                    swap_strings(sel_data[1], sel_len[1], sel_data[2], sel_len[2]);
                end
                if (compare_strings(sel_data[2], sel_len[2], sel_data[3], sel_len[3])) begin
                end else begin
                    swap_strings(sel_data[2], sel_len[2], sel_data[3], sel_len[3]);
                end
                // Pass 2
                if (compare_strings(sel_data[0], sel_len[0], sel_data[1], sel_len[1])) begin
                end else begin
                    swap_strings(sel_data[0], sel_len[0], sel_data[1], sel_len[1]);
                end
                if (compare_strings(sel_data[1], sel_len[1], sel_data[2], sel_len[2])) begin
                end else begin
                    swap_strings(sel_data[1], sel_len[1], sel_data[2], sel_len[2]);
                end
                // After sorting, copy to sorted arrays
                for (integer i = 0; i < MAX_MAGNETS; i = i + 1) begin
                    sorted_data[i] <= sel_data[i];
                    sorted_len[i]  <= sel_len[i];
                end
                state <= S_CONCAT;
            end
            S_CONCAT: begin
                concatenate_sorted;
                state <= S_COMPARE;
            end
            S_COMPARE: begin
                if (candidate_better) begin
                    state <= S_UPDATE;
                end else begin
                    state <= S_NEXT_COMB;
                end
            end
            S_UPDATE: begin
                // Update best with candidate
                for (integer i = 0; i < MAX_TOTAL_DIGITS; i = i + 1) begin
                    best_digits[i] <= cand_digits[i];
                end
                best_len <= cand_len;
                best_valid <= 1;
                state <= S_NEXT_COMB;
            end
            S_NEXT_COMB: begin
                // Increment combination index
                if (comb == 4'b1111) begin
                    state <= S_DONE;
                end else begin
                    comb <= comb + 1;
                    state <= S_COMB_SELECT;
                end
            end
            S_DONE: begin
                // Output the best result
                for (integer i = 0; i < MAX_TOTAL_DIGITS; i = i + 1) begin
                    result_digits[i] <= best_digits[i];
                end
                result_len <= best_len;
                result_valid <= 1;
                state <= S_IDLE;
            end
            default: state <= S_IDLE;
        endcase
    end
end

endmodule

module domino_cover (
    input [7:0] cell_0_0, cell_0_1, cell_0_2,
    input [7:0] cell_1_0, cell_1_1, cell_1_2,
    input [1:0] K,
    output reg [15:0] result
);
// This module computes the maximal sum of exactly K dominoes on a 2x3 board.
// Dominoes are 2x1 tiles, can be placed horizontally or vertically.
// There are 7 possible placements, each covering two cells.
// The algorithm enumerates all non‑overlapping subsets of placements of size K.
// K can be 0,1,2,3. For K=0, result=0. For K>3, result is undefined.

// Weights and masks for each placement (weight = sum of two cells, mask = covered cells).
wire signed [15:0] weight[0:6];
wire [5:0] mask[0:6];

assign weight[0] = $signed(cell_0_0) + $signed(cell_0_1);
assign mask[0] = 6'b000011;
assign weight[1] = $signed(cell_0_1) + $signed(cell_0_2);
assign mask[1] = 6'b000110;
assign weight[2] = $signed(cell_1_0) + $signed(cell_1_1);
assign mask[2] = 6'b001100;
assign weight[3] = $signed(cell_1_1) + $signed(cell_1_2);
assign mask[3] = 6'b011000;
assign weight[4] = $signed(cell_0_0) + $signed(cell_1_0);
assign mask[4] = 6'b001001;
assign weight[5] = $signed(cell_0_1) + $signed(cell_1_1);
assign mask[5] = 6'b010010;
assign weight[6] = $signed(cell_0_2) + $signed(cell_1_2);
assign mask[6] = 6'b100100;

always @(*) begin
    case (K)
        2'b00: result = 16'sd0;
        2'b01: begin
            result = weight[0];
            if (weight[1] > result) result = weight[1];
            if (weight[2] > result) result = weight[2];
            if (weight[3] > result) result = weight[3];
            if (weight[4] > result) result = weight[4];
            if (weight[5] > result) result = weight[5];
            if (weight[6] > result) result = weight[6];
        end
        2'b10: begin
            result = -16'sd32768;
            if ((mask[0] & mask[1]) == 6'b0 && weight[0] + weight[1] > result) result = weight[0] + weight[1];
            if ((mask[0] & mask[2]) == 6'b0 && weight[0] + weight[2] > result) result = weight[0] + weight[2];
            if ((mask[0] & mask[3]) == 6'b0 && weight[0] + weight[3] > result) result = weight[0] + weight[3];
            if ((mask[0] & mask[4]) == 6'b0 && weight[0] + weight[4] > result) result = weight[0] + weight[4];
            if ((mask[0] & mask[5]) == 6'b0 && weight[0] + weight[5] > result) result = weight[0] + weight[5];
            if ((mask[0] & mask[6]) == 6'b0 && weight[0] + weight[6] > result) result = weight[0] + weight[6];
            if ((mask[1] & mask[2]) == 6'b0 && weight[1] + weight[2] > result) result = weight[1] + weight[2];
            if ((mask[1] & mask[3]) == 6'b0 && weight[1] + weight[3] > result) result = weight[1] + weight[3];
            if ((mask[1] & mask[4]) == 6'b0 && weight[1] + weight[4] > result) result = weight[1] + weight[4];
            if ((mask[1] & mask[5]) == 6'b0 && weight[1] + weight[5] > result) result = weight[1] + weight[5];
            if ((mask[1] & mask[6]) == 6'b0 && weight[1] + weight[6] > result) result = weight[1] + weight[6];
            if ((mask[2] & mask[3]) == 6'b0 && weight[2] + weight[3] > result) result = weight[2] + weight[3];
            if ((mask[2] & mask[4]) == 6'b0 && weight[2] + weight[4] > result) result = weight[2] + weight[4];
            if ((mask[2] & mask[5]) == 6'b0 && weight[2] + weight[5] > result) result = weight[2] + weight[5];
            if ((mask[2] & mask[6]) == 6'b0 && weight[2] + weight[6] > result) result = weight[2] + weight[6];
            if ((mask[3] & mask[4]) == 6'b0 && weight[3] + weight[4] > result) result = weight[3] + weight[4];
            if ((mask[3] & mask[5]) == 6'b0 && weight[3] + weight[5] > result) result = weight[3] + weight[5];
            if ((mask[3] & mask[6]) == 6'b0 && weight[3] + weight[6] > result) result = weight[3] + weight[6];
            if ((mask[4] & mask[5]) == 6'b0 && weight[4] + weight[5] > result) result = weight[4] + weight[5];
            if ((mask[4] & mask[6]) == 6'b0 && weight[4] + weight[6] > result) result = weight[4] + weight[6];
            if ((mask[5] & mask[6]) == 6'b0 && weight[5] + weight[6] > result) result = weight[5] + weight[6];
        end
        2'b11: begin
            result = -16'sd32768;
            if ((mask[0] & mask[1]) == 6'b0 && (mask[0] & mask[2]) == 6'b0 && (mask[1] & mask[2]) == 6'b0 && weight[0] + weight[1] + weight[2] > result) result = weight[0] + weight[1] + weight[2];
            if ((mask[0] & mask[1]) == 6'b0 && (mask[0] & mask[3]) == 6'b0 && (mask[1] & mask[3]) == 6'b0 && weight[0] + weight[1] + weight[3] > result) result = weight[0] + weight[1] + weight[3];
            if ((mask[0] & mask[1]) == 6'b0 && (mask[0] & mask[4]) == 6'b0 && (mask[1] & mask[4]) == 6'b0 && weight[0] + weight[1] + weight[4] > result) result = weight[0] + weight[1] + weight[4];
            if ((mask[0] & mask[1]) == 6'b0 && (mask[0] & mask[5]) == 6'b0 && (mask[1] & mask[5]) == 6'b0 && weight[0] + weight[1] + weight[5] > result) result = weight[0] + weight[1] + weight[5];
            if ((mask[0] & mask[1]) == 6'b0 && (mask[0] & mask[6]) == 6'b0 && (mask[1] & mask[6]) == 6'b0 && weight[0] + weight[1] + weight[6] > result) result = weight[0] + weight[1] + weight[6];
            if ((mask[0] & mask[2]) == 6'b0 && (mask[0] & mask[3]) == 6'b0 && (mask[2] & mask[3]) == 6'b0 && weight[0] + weight[2] + weight[3] > result) result = weight[0] + weight[2] + weight[3];
            if ((mask[0] & mask[2]) == 6'b0 && (mask[0] & mask[4]) == 6'b0 && (mask[2] & mask[4]) == 6'b0 && weight[0] + weight[2] + weight[4] > result) result = weight[0] + weight[2] + weight[4];
            if ((mask[0] & mask[2]) == 6'b0 && (mask[0] & mask[5]) == 6'b0 && (mask[2] & mask[5]) == 6'b0 && weight[0] + weight[2] + weight[5] > result) result = weight[0] + weight[2] + weight[5];
            if ((mask[0] & mask[2]) == 6'b0 && (mask[0] & mask[6]) == 6'b0 && (mask[2] & mask[6]) == 6'b0 && weight[0] + weight[2] + weight[6] > result) result = weight[0] + weight[2] + weight[6];
            if ((mask[0] & mask[3]) == 6'b0 && (mask[0] & mask[4]) == 6'b0 && (mask[3] & mask[4]) == 6'b0 && weight[0] + weight[3] + weight[4] > result) result = weight[0] + weight[3] + weight[4];
            if ((mask[0] & mask[3]) == 6'b0 && (mask[0] & mask[5]) == 6'b0 && (mask[3] & mask[5]) == 6'b0 && weight[0] + weight[3] + weight[5] > result) result = weight[0] + weight[3] + weight[5];
            if ((mask[0] & mask[3]) == 6'b0 && (mask[0] & mask[6]) == 6'b0 && (mask[3] & mask[6]) == 6'b0 && weight[0] + weight[3] + weight[6] > result) result = weight[0] + weight[3] + weight[6];
            if ((mask[0] & mask[4]) == 6'b0 && (mask[0] & mask[5]) == 6'b0 && (mask[4] & mask[5]) == 6'b0 && weight[0] + weight[4] + weight[5] > result) result = weight[0] + weight[4] + weight[5];
            if ((mask[0] & mask[4]) == 6'b0 && (mask[0] & mask[6]) == 6'b0 && (mask[4] & mask[6]) == 6'b0 && weight[0] + weight[4] + weight[6] > result) result = weight[0] + weight[4] + weight[6];
            if ((mask[0] & mask[5]) == 6'b0 && (mask[0] & mask[6]) == 6'b0 && (mask[5] & mask[6]) == 6'b0 && weight[0] + weight[5] + weight[6] > result) result = weight[0] + weight[5] + weight[6];
            if ((mask[1] & mask[2]) == 6'b0 && (mask[1] & mask[3]) == 6'b0 && (mask[2] & mask[3]) == 6'b0 && weight[1] + weight[2] + weight[3] > result) result = weight[1] + weight[2] + weight[3];
            if ((mask[1] & mask[2]) == 6'b0 && (mask[1] & mask[4]) == 6'b0 && (mask[2] & mask[4]) == 6'b0 && weight[1] + weight[2] + weight[4] > result) result = weight[1] + weight[2] + weight[4];
            if ((mask[1] & mask[2]) == 6'b0 && (mask[1] & mask[5]) == 6'b0 && (mask[2] & mask[5]) == 6'b0 && weight[1] + weight[2] + weight[5] > result) result = weight[1] + weight[2] + weight[5];
            if ((mask[1] & mask[2]) == 6'b0 && (mask[1] & mask[6]) == 6'b0 && (mask[2] & mask[6]) == 6'b0 && weight[1] + weight[2] + weight[6] > result) result = weight[1] + weight[2] + weight[6];
            if ((mask[1] & mask[3]) == 6'b0 && (mask[1] & mask[4]) == 6'b0 && (mask[3] & mask[4]) == 6'b0 && weight[1] + weight[3] + weight[4] > result) result = weight[1] + weight[3] + weight[4];
            if ((mask[1] & mask[3]) == 6'b0 && (mask[1] & mask[5]) == 6'b0 && (mask[3] & mask[5]) == 6'b0 && weight[1] + weight[3] + weight[5] > result) result = weight[1] + weight[3] + weight[5];
            if ((mask[1] & mask[3]) == 6'b0 && (mask[1] & mask[6]) == 6'b0 && (mask[3] & mask[6]) == 6'b0 && weight[1] + weight[3] + weight[6] > result) result = weight[1] + weight[3] + weight[6];
            if ((mask[1] & mask[4]) == 6'b0 && (mask[1] & mask[5]) == 6'b0 && (mask[4] & mask[5]) == 6'b0 && weight[1] + weight[4] + weight[5] > result) result = weight[1] + weight[4] + weight[5];
            if ((mask[1] & mask[4]) == 6'b0 && (mask[1] & mask[6]) == 6'b0 && (mask[4] & mask[6]) == 6'b0 && weight[1] + weight[4] + weight[6] > result) result = weight[1] + weight[4] + weight[6];
            if ((mask[1] & mask[5]) == 6'b0 && (mask[1] & mask[6]) == 6'b0 && (mask[5] & mask[6]) == 6'b0 && weight[1] + weight[5] + weight[6] > result) result = weight[1] + weight[5] + weight[6];
            if ((mask[2] & mask[3]) == 6'b0 && (mask[2] & mask[4]) == 6'b0 && (mask[3] & mask[4]) == 6'b0 && weight[2] + weight[3] + weight[4] > result) result = weight[2] + weight[3] + weight[4];
            if ((mask[2] & mask[3]) == 6'b0 && (mask[2] & mask[5]) == 6'b0 && (mask[3] & mask[5]) == 6'b0 && weight[2] + weight[3] + weight[5] > result) result = weight[2] + weight[3] + weight[5];
            if ((mask[2] & mask[3]) == 6'b0 && (mask[2] & mask[6]) == 6'b0 && (mask[3] & mask[6]) == 6'b0 && weight[2] + weight[3] + weight[6] > result) result = weight[2] + weight[3] + weight[6];
            if ((mask[2] & mask[4]) == 6'b0 && (mask[2] & mask[5]) == 6'b0 && (mask[4] & mask[5]) == 6'b0 && weight[2] + weight[4] + weight[5] > result) result = weight[2] + weight[4] + weight[5];
            if ((mask[2] & mask[4]) == 6'b0 && (mask[2] & mask[6]) == 6'b0 && (mask[4] & mask[6]) == 6'b0 && weight[2] + weight[4] + weight[6] > result) result = weight[2] + weight[4] + weight[6];
            if ((mask[2] & mask[5]) == 6'b0 && (mask[2] & mask[6]) == 6'b0 && (mask[5] & mask[6]) == 6'b0 && weight[2] + weight[5] + weight[6] > result) result = weight[2] + weight[5] + weight[6];
            if ((mask[3] & mask[4]) == 6'b0 && (mask[3] & mask[5]) == 6'b0 && (mask[4] & mask[5]) == 6'b0 && weight[3] + weight[4] + weight[5] > result) result = weight[3] + weight[4] + weight[5];
            if ((mask[3] & mask[4]) == 6'b0 && (mask[3] & mask[6]) == 6'b0 && (mask[4] & mask[6]) == 6'b0 && weight[3] + weight[4] + weight[6] > result) result = weight[3] + weight[4] + weight[6];
            if ((mask[3] & mask[5]) == 6'b0 && (mask[3] & mask[6]) == 6'b0 && (mask[5] & mask[6]) == 6'b0 && weight[3] + weight[5] + weight[6] > result) result = weight[3] + weight[5] + weight[6];
            if ((mask[4] & mask[5]) == 6'b0 && (mask[4] & mask[6]) == 6'b0 && (mask[5] & mask[6]) == 6'b0 && weight[4] + weight[5] + weight[6] > result) result = weight[4] + weight[5] + weight[6];
        end
        default: result = 16'sd0;
    endcase
end
endmodule

