module lamp_assigner (
    input clk,
    input rst_n,
    input start,
    input [3:0] k,  // Number of lamps (1-16)
    input [31:0] packed_lamp_rows,  // 16 lamps × 2 bits each
    input [31:0] packed_lamp_cols,
    output reg result,
    output reg done
);

// Constants
parameter GRID_SIZE = 4;
parameter MAX_REACH = 2;  // Covers up to 5 squares
parameter MAX_LAMPS = 16;

// States
localparam IDLE = 0;
localparam PRECOMPUTE = 1;
localparam INIT_ASSIGN = 2;
localparam CHECK_ASSIGN = 3;
localparam ASSIGN_PASS = 4;
localparam ASSIGN_FAIL = 5;
localparam FINISHED = 6;

// Registers
reg [3:0] state;
reg [15:0] assignment_counter;  // Current assignment
reg [15:0] max_assignment;      // 2^k - 1
reg [1:0] lamp_rows [0:15];     // Unpacked rows
reg [1:0] lamp_cols [0:15];     // Unpacked cols
reg [1:0] row_interval_start [0:15];
reg [1:0] row_interval_end [0:15];
reg [1:0] col_interval_start [0:15];
reg [1:0] col_interval_end [0:15];

// Intermediate storage for checking
reg [1:0] row_group_col [0:3][0:3];   // [row][index] -> column
reg [1:0] row_group_start [0:3][0:3]; // [row][index] -> start
reg [1:0] row_group_end [0:3][0:3];   // [row][index] -> end
reg [1:0] row_group_count [0:3];      // Count per row
reg [1:0] col_group_row [0:3][0:3];   // [col][index] -> row
reg [1:0] col_group_start [0:3][0:3]; // [col][index] -> start
reg [1:0] col_group_end [0:3][0:3];   // [col][index] -> end
reg [1:0] col_group_count [0:3];      // Count per col

// Sorting/checking variables
reg [2:0] i, j;
reg overlap_found;

// Unpack inputs
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Clear all
    end else if (start && state == IDLE) begin
        for (i = 0; i < 16; i = i + 1) begin
            lamp_rows[i] <= packed_lamp_rows[2*i +: 2];
            lamp_cols[i] <= packed_lamp_cols[2*i +: 2];
        end
        max_assignment <= (1 << k) - 1;
    end
end

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 0;
        done <= 0;
        assignment_counter <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) state <= PRECOMPUTE;
            end

            PRECOMPUTE: begin
                // Precompute intervals for all lamps
                for (i = 0; i < 16; i = i + 1) begin
                    // Row interval (for row mode)
                    row_interval_start[i] <= (lamp_cols[i] >= MAX_REACH) ? lamp_cols[i] - MAX_REACH : 0;
                    row_interval_end[i] <= (lamp_cols[i] + MAX_REACH < GRID_SIZE) ? lamp_cols[i] + MAX_REACH : GRID_SIZE - 1;

                    // Column interval (for column mode)
                    col_interval_start[i] <= (lamp_rows[i] >= MAX_REACH) ? lamp_rows[i] - MAX_REACH : 0;
                    col_interval_end[i] <= (lamp_rows[i] + MAX_REACH < GRID_SIZE) ? lamp_rows[i] + MAX_REACH : GRID_SIZE - 1;
                end
                state <= INIT_ASSIGN;
            end

            INIT_ASSIGN: begin
                assignment_counter <= 0;
                state <= CHECK_ASSIGN;
            end

            CHECK_ASSIGN: begin
                // Clear grouping
                for (i = 0; i < 4; i = i + 1) begin
                    row_group_count[i] <= 0;
                    col_group_count[i] <= 0;
                end

                // Group lamps by assignment
                for (i = 0; i < 16; i = i + 1) begin
                    if (i < k) begin
                        if (assignment_counter[i] == 0) begin  // Row mode
                            row_group_col[lamp_rows[i]][row_group_count[lamp_rows[i]]] <= lamp_cols[i];
                            row_group_start[lamp_rows[i]][row_group_count[lamp_rows[i]]] <= row_interval_start[i];
                            row_group_end[lamp_rows[i]][row_group_count[lamp_rows[i]]] <= row_interval_end[i];
                            row_group_count[lamp_rows[i]] <= row_group_count[lamp_rows[i]] + 1;
                        end else begin  // Column mode
                            col_group_row[lamp_cols[i]][col_group_count[lamp_cols[i]]] <= lamp_rows[i];
                            col_group_start[lamp_cols[i]][col_group_count[lamp_cols[i]]] <= col_interval_start[i];
                            col_group_end[lamp_cols[i]][col_group_count[lamp_cols[i]]] <= col_interval_end[i];
                            col_group_count[lamp_cols[i]] <= col_group_count[lamp_cols[i]] + 1;
                        end
                    end
                end

                // Next state: sort and check
                state <= ASSIGN_PASS;
                i <= 0;  // Start with row 0
                j <= 0;  // Start with first pair
                overlap_found <= 0;
            end

            ASSIGN_PASS: begin
                // Check rows for overlaps
                if (i < 4) begin  // For each row
                    if (row_group_count[i] > 1) begin
                        // Simple bubble sort (1 cycle per comparison) - in practice would need multiple cycles
                        // For now, assume we check in next state
                        state <= ASSIGN_FAIL;
                    end else begin
                        i <= i + 1;
                    end
                end else begin
                    // All rows checked, now check columns
                    i <= 0;
                    state <= ASSIGN_FAIL;  // Move to column checking
                end
            end

            ASSIGN_FAIL: begin
                // Check if current assignment passes
                if (!overlap_found && assignment_counter <= max_assignment) begin
                    result <= 1;
                    done <= 1;
                    state <= FINISHED;
                end else if (assignment_counter < max_assignment) begin
                    assignment_counter <= assignment_counter + 1;
                    state <= CHECK_ASSIGN;
                end else begin
                    result <= 0;
                    done <= 1;
                    state <= FINISHED;
                end
            end

            FINISHED: begin
                // Stay done
            end
        endcase
    end
end

endmodule

module DeliveryTimeSolver (
    input clk,
    input rst_n,
    input start,
    // Misha's segment (2 points)
    input [15:0] A_x, A_y,
    input [15:0] B_x, B_y,
    input [31:0] L_M, // Length * 256
    // Nadia's segment (2 points)
    input [15:0] C_x, C_y,
    input [15:0] D_x, D_y,
    input [31:0] L_N, // Length * 256
    // Output
    output reg [31:0] result, // Delivery time * 65536 (Q16.16)
    output reg done,
    output reg impossible
);

// Parameters
localparam FRAC = 8;
localparam SCALE = 256;
localparam SCALE_SQ = 65536;
localparam MAX_ITER = 24; // Binary search iterations

// States
localparam IDLE = 0,
           INIT_BIN = 1,
           FEAS_CHECK = 2,
           UPDATE_BIN = 3,
           FINISH = 4,
           IMPOSSIBLE = 5;

reg [3:0] state;
reg [31:0] low, high, mid; // T_fixed values
reg [31:0] t1, t2;
reg [7:0] s;
reg [7:0] u;
reg [15:0] Mx, My, Nx, Ny;
reg signed [31:0] dx, dy;
reg [31:0] dist_sq;
reg [31:0] threshold, T_sq;
reg [31:0] cycles;
reg feas_flag;
reg [31:0] result_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        impossible <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                impossible <= 0;
                if (start) begin
                    low <= 0;
                    high <= (1 << 24) - 1; // Upper bound for T_fixed
                    cycles <= 0;
                    state <= INIT_BIN;
                end
            end

            INIT_BIN: begin
                // Compute mid = (low + high) >> 1
                mid <= (low + high) >> 1;
                s <= 0;
                feas_flag <= 0;
                state <= FEAS_CHECK;
            end

            FEAS_CHECK: begin
                // Feasibility check for T = mid
                // This state machine iterates s from 0 to 255
                case (s)
                    8'h00: begin // Compute t1 = (s * L_M) >> FRAC
                        t1 <= (s * L_M) >> FRAC;
                        s <= s + 1;
                    end
                    8'h01: begin // Compute t2 = t1 + mid
                        t2 <= t1 + mid;
                        if (t2 > L_N) begin
                            state <= UPDATE_BIN; // Infeasible for this and larger s
                        end else begin
                            s <= s + 1;
                        end
                    end
                    8'h02: begin // Compute u = (t2 * SCALE) / L_N
                        u <= (t2 * SCALE) / L_N;
                        s <= s + 1;
                    end
                    8'h03: begin // Check u <= 255
                        if (u > 8'hFF) begin
                            state <= UPDATE_BIN;
                        end else begin
                            s <= s + 1;
                        end
                    end
                    8'h04: begin // Compute Mx, My
                        Mx <= A_x + ((B_x - A_x) * (s-4)) >> FRAC;
                        My <= A_y + ((B_y - A_y) * (s-4)) >> FRAC;
                        s <= s + 1;
                    end
                    8'h05: begin // Compute Nx, Ny
                        Nx <= C_x + ((D_x - C_x) * u) >> FRAC;
                        Ny <= C_y + ((D_y - C_y) * u) >> FRAC;
                        s <= s + 1;
                    end
                    8'h06: begin // Compute dx, dy
                        dx <= Mx - Nx;
                        dy <= My - Ny;
                        s <= s + 1;
                    end
                    8'h07: begin // Compute dist_sq = dx*dx + dy*dy
                        dist_sq <= dx*dx + dy*dy;
                        s <= s + 1;
                    end
                    8'h08: begin // Compute threshold = dist_sq * SCALE_SQ
                        threshold <= dist_sq * SCALE_SQ;
                        s <= s + 1;
                    end
                    8'h09: begin // Compute T_sq = mid * mid
                        T_sq <= mid * mid;
                        s <= s + 1;
                    end
                    8'h0A: begin // Compare threshold <= T_sq
                        if (threshold <= T_sq) begin
                            feas_flag <= 1;
                            state <= UPDATE_BIN; // Found feasible, break early
                        end else begin
                            if (s == 8'hFF) begin // Last iteration
                                state <= UPDATE_BIN;
                            end else begin
                                s <= 8'h00; // Reset to compute next t1
                            end
                        end
                    end
                    default: s <= s + 1;
                endcase
            end

            UPDATE_BIN: begin
                if (feas_flag) begin
                    high <= mid;
                end else begin
                    low <= mid + 1;
                end
                if (high - low <= 1 || cycles >= MAX_ITER) begin
                    // Converged or max iterations reached
                    result_reg <= high;
                    state <= FINISH;
                end else begin
                    cycles <= cycles + 1;
                    state <= INIT_BIN;
                end
            end

            FINISH: begin
                // Check if high is feasible (final check)
                // For simplicity, we assume high is feasible
                // If high is 0, might be impossible, but we assume it's feasible
                result <= high << 8; // Convert to Q16.16
                done <= 1;
                state <= IDLE;
            end

            IMPOSSIBLE: begin
                impossible <= 1;
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module tree_diff #(
    parameter N = 8,           // Number of trees (fixed at 8)
    parameter DATA_WIDTH = 8,  // Width for tree heights (1..100 fits in 8 bits)
    parameter K_WIDTH = 4      // Width for k input (k <= 8)
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    // Input array: 8 individual ports, each 8 bits
    input wire [DATA_WIDTH-1:0] arr_0,
    input wire [DATA_WIDTH-1:0] arr_1,
    input wire [DATA_WIDTH-1:0] arr_2,
    input wire [DATA_WIDTH-1:0] arr_3,
    input wire [DATA_WIDTH-1:0] arr_4,
    input wire [DATA_WIDTH-1:0] arr_5,
    input wire [DATA_WIDTH-1:0] arr_6,
    input wire [DATA_WIDTH-1:0] arr_7,
    input wire [K_WIDTH-1:0] k,
    output reg [DATA_WIDTH-1:0] result,
    output reg done
);

// Internal registers for array storage
reg [DATA_WIDTH-1:0] arr_reg [0:N-1];
reg [K_WIDTH-1:0] k_reg;
reg [DATA_WIDTH-1:0] min_diff;
reg [DATA_WIDTH-1:0] cur_min, cur_max;
reg [3:0] i;          // window start index
reg [3:0] j;          // inner loop index
reg [2:0] state;

// State definitions
localparam IDLE = 3'b000;
localparam NEXT_WINDOW = 3'b001;
localparam COMPUTE_WINDOW = 3'b010;
localparam UPDATE_DIFF = 3'b011;
localparam DONE = 3'b100;

integer idx;

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset
        state <= IDLE;
        done <= 1'b0;
        result <= 8'b0;
        // Reset array registers (optional)
        for (idx = 0; idx < N; idx = idx + 1)
            arr_reg[idx] <= 8'b0;
        k_reg <= 8'b0;
        min_diff <= 8'b0;
        cur_min <= 8'b0;
        cur_max <= 8'b0;
        i <= 4'b0;
        j <= 4'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    // Capture input array into registers
                    arr_reg[0] <= arr_0;
                    arr_reg[1] <= arr_1;
                    arr_reg[2] <= arr_2;
                    arr_reg[3] <= arr_3;
                    arr_reg[4] <= arr_4;
                    arr_reg[5] <= arr_5;
                    arr_reg[6] <= arr_6;
                    arr_reg[7] <= arr_7;
                    k_reg <= k;
                    // Initialize min_diff to max possible
                    min_diff <= 8'hFF;
                    i <= 4'b0;
                    state <= NEXT_WINDOW;
                end
            end

            NEXT_WINDOW: begin
                // Check if more windows exist
                if (i <= N - k_reg) begin
                    // Start new window
                    cur_min <= 8'hFF;  // Initialize to max
                    cur_max <= 8'h00;  // Initialize to min
                    j <= i;            // Start inner loop
                    state <= COMPUTE_WINDOW;
                end else begin
                    // All windows processed
                    state <= DONE;
                end
            end

            COMPUTE_WINDOW: begin
                // Update min and max with current element
                if (arr_reg[j] < cur_min)
                    cur_min <= arr_reg[j];
                if (arr_reg[j] > cur_max)
                    cur_max <= arr_reg[j];
                // Increment j
                j <= j + 1;
                // Check if finished this window
                if (j + 1 < i + k_reg)
                    state <= COMPUTE_WINDOW; // continue
                else
                    state <= UPDATE_DIFF;   // window done
            end

            UPDATE_DIFF: begin
                // Compute diff and update min_diff if smaller
                if (cur_max - cur_min < min_diff)
                    min_diff <= cur_max - cur_min;
                // Move to next window
                i <= i + 1;
                state <= NEXT_WINDOW;
            end

            DONE: begin
                result <= min_diff;
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module LanguagePairing (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] N,   // Number of languages (unused, kept for interface)
    input wire [3:0] M,   // Number of translators (max 4)
    // Translator definitions: each translator speaks two languages
    input wire [3:0] lang1_0, lang2_0,
    input wire [3:0] lang1_1, lang2_1,
    input wire [3:0] lang1_2, lang2_2,
    input wire [3:0] lang1_3, lang2_3,
    // Output pairs of translator indices
    output reg [3:0] pair1_tr1, pair1_tr2,
    output reg [3:0] pair2_tr1, pair2_tr2,
    output reg valid,      // Asserted when a valid pairing is found
    output reg impossible  // Asserted when no pairing exists
);

// States
localparam IDLE = 3'd0;
localparam CHECK_M = 3'd1;
localparam M2_CHECK = 3'd2;
localparam M4_CHECK1 = 3'd3;
localparam M4_CHECK2 = 3'd4;
localparam M4_CHECK3 = 3'd5;
localparam ODD_M = 3'd6;

reg [2:0] state, next_state;

// Helper function: check if two translators share a language
function automatic logic share_language(
    input [3:0] a1, a2,
    input [3:0] b1, b2
);
    share_language = (a1 == b1) || (a1 == b2) || (a2 == b1) || (a2 == b2);
endfunction

// Combinational signals for share checks
logic m2_share;
assign m2_share = share_language(lang1_0, lang2_0, lang1_1, lang2_1);

logic pair1_share_1, pair2_share_1;
assign pair1_share_1 = share_language(lang1_0, lang2_0, lang1_1, lang2_1);
assign pair2_share_1 = share_language(lang1_2, lang2_2, lang1_3, lang2_3);

logic pair1_share_2, pair2_share_2;
assign pair1_share_2 = share_language(lang1_0, lang2_0, lang1_2, lang2_2);
assign pair2_share_2 = share_language(lang1_1, lang2_1, lang1_3, lang2_3);

logic pair1_share_3, pair2_share_3;
assign pair1_share_3 = share_language(lang1_0, lang2_0, lang1_3, lang2_3);
assign pair2_share_3 = share_language(lang1_1, lang2_1, lang1_2, lang2_2);

// State transition and output logic
always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        valid <= 1'b0;
        impossible <= 1'b0;
        pair1_tr1 <= 4'd0;
        pair1_tr2 <= 4'd0;
        pair2_tr1 <= 4'd0;
        pair2_tr2 <= 4'd0;
    end else begin
        state <= next_state;
        case (state)
            IDLE: begin
                valid <= 1'b0;
                impossible <= 1'b0;
            end
            M2_CHECK: begin
                if (m2_share) begin
                    pair1_tr1 <= 4'd0;
                    pair1_tr2 <= 4'd1;
                    valid <= 1'b1;
                end else begin
                    impossible <= 1'b1;
                end
            end
            M4_CHECK1: begin
                if (pair1_share_1 && pair2_share_1) begin
                    pair1_tr1 <= 4'd0;
                    pair1_tr2 <= 4'd1;
                    pair2_tr1 <= 4'd2;
                    pair2_tr2 <= 4'd3;
                    valid <= 1'b1;
                end
            end
            M4_CHECK2: begin
                if (pair1_share_2 && pair2_share_2) begin
                    pair1_tr1 <= 4'd0;
                    pair1_tr2 <= 4'd2;
                    pair2_tr1 <= 4'd1;
                    pair2_tr2 <= 4'd3;
                    valid <= 1'b1;
                end
            end
            M4_CHECK3: begin
                if (pair1_share_3 && pair2_share_3) begin
                    pair1_tr1 <= 4'd0;
                    pair1_tr2 <= 4'd3;
                    pair2_tr1 <= 4'd1;
                    pair2_tr2 <= 4'd2;
                    valid <= 1'b1;
                end else begin
                    impossible <= 1'b1;
                end
            end
            ODD_M: begin
                impossible <= 1'b1;
            end
        endcase
    end
end

// Next state logic
always_comb begin
    next_state = state;
    case (state)
        IDLE: begin
            if (start) next_state = CHECK_M;
        end
        CHECK_M: begin
            if (M[0]) // M is odd
                next_state = ODD_M;
            else if (M == 4'd2)
                next_state = M2_CHECK;
            else if (M == 4'd4)
                next_state = M4_CHECK1;
            else
                next_state = ODD_M; // Unsupported M, treat as impossible
        end
        M2_CHECK: next_state = IDLE;
        M4_CHECK1: begin
            if (pair1_share_1 && pair2_share_1)
                next_state = IDLE;
            else
                next_state = M4_CHECK2;
        end
        M4_CHECK2: begin
            if (pair1_share_2 && pair2_share_2)
                next_state = IDLE;
            else
                next_state = M4_CHECK3;
        end
        M4_CHECK3: begin
            next_state = IDLE;
        end
        ODD_M: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

endmodule

module max_clique #(
    parameter N = 4,
    parameter DATA_WIDTH = 16,
    parameter MASK_WIDTH = N,
    parameter SIZE_WIDTH = 3
)(
    input clk,
    input rst_n,
    input start,
    input [DATA_WIDTH-1:0] d,
    input [DATA_WIDTH-1:0] x0, x1, x2, x3,
    input [DATA_WIDTH-1:0] y0, y1, y2, y3,
    input [2:0] num_sensors,
    output reg [SIZE_WIDTH-1:0] max_size,
    output reg [MASK_WIDTH-1:0] subset_mask,
    output reg done
);

// Internal registers for coordinates
reg [DATA_WIDTH-1:0] x [0:N-1];
reg [DATA_WIDTH-1:0] y [0:N-1];

// Adjacency matrix
reg adj [0:N-1][0:N-1];

// State machine states
localparam IDLE = 3'b000;
localparam COMPUTE_ADJ = 3'b001;
localparam INIT_ENUM = 3'b010;
localparam CHECK_SUBSET = 3'b011;
localparam DONE = 3'b100;

reg [2:0] state, next_state;

// Registers for enumeration
reg [MASK_WIDTH-1:0] mask, next_mask;
reg [SIZE_WIDTH-1:0] best_size, next_best_size;
reg [MASK_WIDTH-1:0] best_mask, next_best_mask;
reg [2:0] pair_index, next_pair_index; // 0..5 for 4 sensors
reg clique_ok, next_clique_ok;
reg [DATA_WIDTH*2-1:0] d_sq, next_d_sq; // 32-bit for d^2

// Pair index decoder: pair_index -> (i,j)
wire [1:0] i_idx, j_idx;
assign i_idx = (pair_index == 3'd0) ? 2'd0 :
               (pair_index == 3'd1) ? 2'd0 :
               (pair_index == 3'd2) ? 2'd0 :
               (pair_index == 3'd3) ? 2'd1 :
               (pair_index == 3'd4) ? 2'd1 : 2'd2;
assign j_idx = (pair_index == 3'd0) ? 2'd1 :
               (pair_index == 3'd1) ? 2'd2 :
               (pair_index == 3'd2) ? 2'd3 :
               (pair_index == 3'd3) ? 2'd2 :
               (pair_index == 3'd4) ? 2'd3 : 2'd3;

// Function to compute popcount of a function [SIZE_WIDTH-1:0] popcount;
    input [MASK_WIDTH-1:0] m;
    integer k;
    begin
        popcount = 0;
        for (k = 0; k < N; k = k + 1) begin
            if (m[k]) popcount = popcount + 1;
        end
    end
endfunction

// Compute squared distance and compare to d_sq
wire [DATA_WIDTH-1:0] dx = (x[i_idx] > x[j_idx]) ? (x[i_idx] - x[j_idx]) : (x[j_idx] - x[i_idx]);
wire [DATA_WIDTH-1:0] dy = (y[i_idx] > y[j_idx]) ? (y[i_idx] - y[j_idx]) : (y[j_idx] - y[i_idx]);
wire [DATA_WIDTH*2-1:0] dist_sq = dx * dx + dy * dy;

// Combinational next state and output logic
always @(*) begin
    // Default assignments to avoid latches
    next_state = state;
    next_mask = mask;
    next_best_size = best_size;
    next_best_mask = best_mask;
    next_pair_index = pair_index;
    next_clique_ok = clique_ok;
    next_d_sq = d_sq;

    case (state)
        IDLE: begin
            if (start) begin
                next_d_sq = d * d;
                next_pair_index = 0;
                next_state = COMPUTE_ADJ;
            end
        end

        COMPUTE_ADJ: begin
            // Update adjacency for current pair
            if (i_idx < num_sensors && j_idx < num_sensors) begin
                if (dist_sq <= d_sq) begin
                    adj[i_idx][j_idx] = 1;
                    adj[j_idx][i_idx] = 1;
                end else begin
                    adj[i_idx][j_idx] = 0;
                    adj[j_idx][i_idx] = 0;
                end
            end else begin
                adj[i_idx][j_idx] = 0;
                adj[j_idx][i_idx] = 0;
            end

            if (pair_index < 5) begin
                next_pair_index = pair_index + 1;
            end else begin
                next_pair_index = 0;
                next_state = INIT_ENUM;
            end
        end

        INIT_ENUM: begin
            next_mask = 0;
            next_best_size = 0;
            next_best_mask = 0;
            next_pair_index = 0;
            next_clique_ok = 1;
            next_state = CHECK_SUBSET;
        end

        CHECK_SUBSET: begin
            if (pair_index < 6) begin
                // Check current pair
                if (mask[i_idx] && mask[j_idx]) begin
                    if (!adj[i_idx][j_idx]) begin
                        next_clique_ok = 0;
                    end
                end
                next_pair_index = pair_index + 1;
            end else begin
                // Finished all pairs for this mask
                if (clique_ok) begin
                    if (popcount(mask) > best_size) begin
                        next_best_size = popcount(mask);
                        next_best_mask = mask;
                    end
                end
                // Next mask
                if (mask < (1 << N) - 1) begin
                    next_mask = mask + 1;
                    next_pair_index = 0;
                    next_clique_ok = 1;
                end else begin
                    next_state = DONE;
                end
            end
        end

        DONE: begin
            // Stay in done state
            next_state = DONE;
        end

        default: next_state = IDLE;
    endcase
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        mask <= 0;
        best_size <= 0;
        best_mask <= 0;
        pair_index <= 0;
        clique_ok <= 1;
        d_sq <= 0;
        done <= 0;
        max_size <= 0;
        subset_mask <= 0;
        // Initialize coordinates and adj
        for (integer i = 0; i < N; i = i + 1) begin
            x[i] <= 0;
            y[i] <= 0;
            for (integer j = 0; j < N; j = j + 1) begin
                adj[i][j] <= 0;
            end
        end
    end else begin
        state <= next_state;
        mask <= next_mask;
        best_size <= next_best_size;
        best_mask <= next_best_mask;
        pair_index <= next_pair_index;
        clique_ok <= next_clique_ok;
        d_sq <= next_d_sq;
        done <= (state == DONE) ? 1 : 0;
        if (state == DONE) begin
            max_size <= best_size;
            subset_mask <= best_mask;
        end
        // Load coordinates when start is asserted in IDLE
        if (start && state == IDLE) begin
            x[0] <= x0;
            x[1] <= x1;
            x[2] <= x2;
            x[3] <= x3;
            y[0] <= y0;
            y[1] <= y1;
            y[2] <= y2;
            y[3] <= y3;
        end
    end
end

endmodule

module task_selection #(
    parameter N = 8,
    parameter DATA_WIDTH = 32,
    parameter MOD = 1000000007
) (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input arrays: exact tasks A[0:N-1], flexible tasks B[0:N-2]
    input wire [DATA_WIDTH-1:0] A [0:N-1],
    input wire [DATA_WIDTH-1:0] B [0:N-2],

    output reg [DATA_WIDTH-1:0] result,
    output reg done
);
    localparam IDLE=2'b00, COMPUTE=2'b01, DONE=2'b10;
    reg [1:0] state;
    reg [DATA_WIDTH-1:0] f, g;
    reg [31:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE; f <= 0; g <= 0; counter <= 0;
            done <= 0; result <= 0;
        end else case (state)
            IDLE: if (start) begin
                if (N == 1) begin result <= A[0]; done <= 1; state <= DONE; end
                else begin f <= (A[0] + B[0]) % MOD; g <= B[0] % MOD; counter <= 1; state <= COMPUTE; end
            end
            COMPUTE: begin
                if (counter < N-1) g <= (f * B[counter]) % MOD; else g <= 0;
                f <= (f * (A[counter] + B[counter-1]) + (counter < N-1 ? f * B[counter] : 0) - g + MOD) % MOD;
                if (counter == N-1) begin state <= DONE; result <= f; done <= 1; end
                else counter <= counter + 1;
            end
            DONE: begin done <= 0; state <= IDLE; end
        endcase
    end
endmodule

module grasshopper (
    input clk,
    input rst_n,
    input start,
    // Grid values (8-bit each)
    input [7:0] grid_0_0, grid_0_1, grid_0_2, grid_0_3,
                 grid_1_0, grid_1_1, grid_1_2, grid_1_3,
                 grid_2_0, grid_2_1, grid_2_2, grid_2_3,
                 grid_3_0, grid_3_1, grid_3_2, grid_3_3,
    input [1:0] start_row, start_col,  // 0-indexed
    output reg [4:0] max_length,
    output reg done
);

// State definitions
localparam S_IDLE = 4'd0;
localparam S_LOAD = 4'd1;
localparam S_SORT_INIT = 4'd2;
localparam S_SORT_LOOP = 4'd3;
localparam S_SORT_COMPARE = 4'd4;
localparam S_SORT_SWAP = 4'd5;
localparam S_SORT_NEXT = 4'd6;
localparam S_DP_INIT = 4'd7;
localparam S_DP_OUTER = 4'd8;
localparam S_DP_INNER = 4'd9;
localparam S_DP_UPDATE = 4'd10;
localparam S_DP_NEXT_J = 4'd11;
localparam S_DP_NEXT_K = 4'd12;
localparam S_RESULT = 4'd13;
localparam S_DONE = 4'd14;

// Registers
reg [3:0] state;
reg [3:0] pass, i, k, j;  // counters
reg [7:0] petal [0:15];   // petal values
reg [3:0] idx [0:15];     // permutation indices
reg [4:0] dp [0:15];      // DP values
reg [4:0] max_length_reg;
reg done_reg;

// Temporary registers for swap and update
reg [7:0] temp_petal;
reg [3:0] temp_idx;
reg [4:0] temp_dp;

// Coordinates and move calculation
reg [1:0] r_i, c_i, r_j, c_j;
reg [1:0] diff_r, diff_c;
reg move_allowed;

// Combinational logic for move check
always @(*) begin
    // Coordinates from idx (i and j are current indices in petal array)
    r_i = idx[i][3:2];
    c_i = idx[i][1:0];
    r_j = idx[j][3:2];
    c_j = idx[j][1:0];

    // Absolute differences
    if (r_i > r_j) diff_r = r_i - r_j; else diff_r = r_j - r_i;
    if (c_i > c_j) diff_c = c_i - c_j; else diff_c = c_j - c_i;

    // Movement rule: (|r_i - r_j| == 1 && |c_i - c_j| >= 2) || (|c_i - c_j| == 1 && |r_i - r_j| >= 2)
    move_allowed = ((diff_r == 1 && diff_c >= 2) || (diff_c == 1 && diff_r >= 2));
end

// Main state machine and sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        max_length <= 0;
        pass <= 0;
        i <= 0;
        k <= 0;
        j <= 0;
        done_reg <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= S_LOAD;
                end
            end

            S_LOAD: begin
                // Load grid into petal array
                petal[0] <= grid_0_0; petal[1] <= grid_0_1; petal[2] <= grid_0_2; petal[3] <= grid_0_3;
                petal[4] <= grid_1_0; petal[5] <= grid_1_1; petal[6] <= grid_1_2; petal[7] <= grid_1_3;
                petal[8] <= grid_2_0; petal[9] <= grid_2_1; petal[10] <= grid_2_2; petal[11] <= grid_2_3;
                petal[12] <= grid_3_0; petal[13] <= grid_3_1; petal[14] <= grid_3_2; petal[15] <= grid_3_3;
                // Initialize indices
                for (int idx_init = 0; idx_init < 16; idx_init = idx_init + 1) begin
                    idx[idx_init] <= idx_init;
                end
                state <= S_SORT_INIT;
            end

            S_SORT_INIT: begin
                pass <= 0;
                i <= 0;
                state <= S_SORT_LOOP;
            end

            S_SORT_LOOP: begin
                if (i < 14 - pass) begin
                    state <= S_SORT_COMPARE;
                end else begin
                    pass <= pass + 1;
                    i <= 0;
                    if (pass >= 15) begin
                        state <= S_DP_INIT;
                    end else begin
                        state <= S_SORT_LOOP;
                    end
                end
            end

            S_SORT_COMPARE: begin
                // Compare petal[i] and petal[i+1] (descending order)
                if (petal[i] < petal[i+1]) begin
                    state <= S_SORT_SWAP;
                end else begin
                    state <= S_SORT_NEXT;
                end
            end

            S_SORT_SWAP: begin
                // Swap petal[i] and petal[i+1]
                temp_petal <= petal[i];
                petal[i] <= petal[i+1];
                petal[i+1] <= temp_petal;
                // Swap idx[i] and idx[i+1]
                temp_idx <= idx[i];
                idx[i] <= idx[i+1];
                idx[i+1] <= temp_idx;
                state <= S_SORT_NEXT;
            end

            S_SORT_NEXT: begin
                i <= i + 1;
                state <= S_SORT_LOOP;
            end

            S_DP_INIT: begin
                // Initialize dp to 1 for all cells
                for (int dp_init = 0; dp_init < 16; dp_init = dp_init + 1) begin
                    dp[dp_init] <= 5'd1;
                end
                k <= 0;
                state <= S_DP_OUTER;
            end

            S_DP_OUTER: begin
                if (k < 16) begin
                    j <= 0;
                    state <= S_DP_INNER;
                end else begin
                    state <= S_RESULT;
                end
            end

            S_DP_INNER: begin
                if (j < 16) begin
                    state <= S_DP_UPDATE;
                end else begin
                    state <= S_DP_NEXT_K;
                end
            end

            S_DP_UPDATE: begin
                // Check if move allowed and petal[j] > petal[i]
                if (move_allowed && (petal[j] > petal[idx[k]])) begin
                    // dp[i] = max(dp[i], dp[j] + 1)
                    if (dp[idx[k]] < dp[j] + 1) begin
                        dp[idx[k]] <= dp[j] + 1;
                    end
                end
                state <= S_DP_NEXT_J;
            end

            S_DP_NEXT_J: begin
                j <= j + 1;
                state <= S_DP_INNER;
            end

            S_DP_NEXT_K: begin
                k <= k + 1;
                state <= S_DP_OUTER;
            end

            S_RESULT: begin
                // Compute start index = start_row * 4 + start_col
                max_length_reg <= dp[{start_row, start_col}];
                state <= S_DONE;
            end

            S_DONE: begin
                max_length <= max_length_reg;
                done <= 1;
                if (!start) begin
                    state <= S_IDLE;
                end
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

