    for i in range(N):
        for j in range(N):
            if i == j:
                color_matrix[i][j] = 0
            else:
                pi = pos[i]
                pj = pos[j]
                if pi < pj:
                    color_matrix[i][j] = c[pi]
                else:
                    color_matrix[i][j] = c[pj]
    if has_signal(dut, 'color'):
        for i in range(N):
            for j in range(N):
                dut.color[i][j].value = clamp_to_width(color_matrix[i][j], COLOR_WIDTH)
