        if len(clique) <= 1:
            return True
        first = None
        for idx1 in range(len(clique)):
            for idx2 in range(idx1+1, len(clique)):
                col = mat[clique[idx1]][clique[idx2]]
                if first is None:
                    first = col
                elif col != first:
                    return False
        return True
    def f(S, mat):
        if not S:
            return 0
        max_sz = 1
        S_list = list(S)
        nS = len(S_list)
        for mask in range(1, 1<<nS):
            clique = [S_list[i] for i in range(nS) if (mask>>i)&1]
            if is_monochromatic(clique, mat):
                sz = len(clique)
                if sz > max_sz:
                    max_sz = sz
        return max_sz
    def compute_sum(mat):
        total = 0
        for mask in range(1, 1<<N):
            S = [i for i in range(N) if (mask>>i)&1]
            total += f(S, mat)
        return total % MOD
