localparam S_COMPUTE_PREFIX = 1;
localparam S_SET_BEST0 = 2;
localparam S_INIT_I = 3;
localparam S_LOOP_J_START = 4;
localparam S_COMPUTE_S = 5;
localparam S_COMPARE = 6;
localparam S_UPDATE = 7;
localparam S_NEXT_J = 8;
localparam S_NEXT_I = 9;
localparam S_DONE = 10;

reg [4:0] state, next_state;

// Arrays
reg [SUM_WIDTH-1:0] prefix [0:8];
reg [RESULT_WIDTH-1:0] best [0:7];
reg [SUM_WIDTH-1:0] sum [0:7];

// Temporary registers
