module pattern_sorter #(
    parameter NUM_PATTERNS = 4,
    parameter PATTERN_LENGTH = 8,
    parameter DATA_WIDTH = 2,  // 2 bits: 00=R, 01=P, 10=S
    parameter SCORE_WIDTH = 8,  // Max score = 1+2+...+7 = 28
    parameter N_WIDTH = 20
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [N_WIDTH-1:0] n,  // Number of rounds (unused in border score)
    input wire [DATA_WIDTH*PATTERN_LENGTH-1:0] patterns_in [0:NUM_PATTERNS-1],
    output wire done,
    output wire [DATA_WIDTH*PATTERN_LENGTH-1:0] patterns_out [0:NUM_PATTERNS-1]
);

// Functionality:
// 1. On start=1, compute border score for each pattern
// 2. Score = sum of lengths of all proper borders (prefix = suffix)
// 3. Sort patterns by score ascending (stable for ties)
// 4. Assert done when complete
// 5. Computation takes NUM_PATTERNS * PATTERN_LENGTH cycles

// Implementation: Sequential state machine
// - State 0: Idle
// - State 1: Compute KMP prefix function for current pattern
// - State 2: Sum border lengths
// - State 3: Compare scores and sort
// - State 4: Done

endmodule

module SecureNetwork (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,          // number of buildings (1-8)
    input [3:0] p,          // number of insecure buildings (0-8)
    input [31:0] insecure_list, // packed insecure IDs (8 x 4 bits, LSB first)
    input [63:0] edge_u,    // edge start nodes (16 x 4 bits)
    input [63:0] edge_v,    // edge end nodes (16 x 4 bits)
    input [255:0] edge_cost, // edge costs (16 x 16 bits)
    input [15:0] edge_valid, // mask for valid edges
    output reg [15:0] result, // total cost if possible
    output reg done,          // pulse when computation finishes
    output reg impossible     // 1 if no valid network exists
);

// Behavioral description:
// - Sequential FSM with states: IDLE, CHECK_SPECIAL, FIND_MIN, BUILD_MST, COMPUTE, DONE
// - On start pulse, processes input graph according to security constraint.
// - Handles three cases:
//   1) p == n: if n==1 -> result=0; if n==2 -> find edge between the two; else impossible.
//   2) p == 0 -> standard MST (Kruskal) on all nodes.
//   3) 0 < p < n -> find min edge from each insecure node to any secure node;
//      then MST on secure subgraph; sum costs; if any insecure has no edge or secure subgraph disconnected -> impossible.
// - Union-find used for MST (max 8 secure nodes).
// - Edge sorting via repeated min selection (max 16 edges).
// - Guaranteed to finish within 1000 cycles.
// - On reset (rst_n=0): all outputs 0.
// - Timing: Assert start for 1 cycle; after computation, done pulses high for 1 cycle.

endmodule

module meow_factor (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [4:0] char_0, char_1, char_2, char_3, char_4, char_5, char_6, char_7,
    input wire [2:0] len,
    output reg [3:0] result,
    output reg done
);

// MEOW character codes (0-indexed from 'a')
localparam CHAR_M = 5'd12;  // 'm' - 'a'
localparam CHAR_E = 5'd4;   // 'e' - 'a'
localparam CHAR_O = 5'd14;  // 'o' - 'a'
localparam CHAR_W = 5'd22;  // 'w' - 'a'

// States
localparam IDLE = 2'd0;
localparam INIT = 2'd1;
localparam COMPUTE = 2'd2;
localparam FINISH = 2'd3;

reg [1:0] state;
reg [2:0] char_idx;      // Current character index (0-7)
reg [1:0] meow_idx;      // Current 'meow' position (0-3)
reg [3:0] dp_prev [0:4]; // Previous DP row
reg [3:0] dp_curr [0:4]; // Current DP row
reg [3:0] min_result;    // Minimum dp[i][4] seen
reg [4:0] current_char;  // Current character value

// Character selection
always @(*) begin
    case(char_idx)
        3'd0: current_char = char_0;
        3'd1: current_char = char_1;
        3'd2: current_char = char_2;
        3'd3: current_char = char_3;
        3'd4: current_char = char_4;
        3'd5: current_char = char_5;
        3'd6: current_char = char_6;
        3'd7: current_char = char_7;
        default: current_char = 5'd0;
    endcase
end

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        char_idx <= 0;
        meow_idx <= 0;
        min_result <= 4'd15;
    end else begin
        case(state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Initialize DP for empty string (i=0)
                    dp_prev[0] <= 4'd0;
                    dp_prev[1] <= 4'd1;
                    dp_prev[2] <= 4'd2;
                    dp_prev[3] <= 4'd3;
                    dp_prev[4] <= 4'd4;
                    min_result <= 4'd4;  // dp[0][4] = 4
                    char_idx <= 0;
                    meow_idx <= 0;
                    if (len == 3'd0) begin
                        result <= 4'd4;
                        done <= 1;
                    end else begin
                        state <= INIT;
                    end
                end
            end
            INIT: begin
                state <= COMPUTE;
            end
            COMPUTE: begin
                if (char_idx < len && char_idx < 3'd8) begin
                    case(meow_idx)
                        2'd0: begin
                            dp_curr[0] <= char_idx + 1;
                            meow_idx <= 2'd1;
                        end
                        2'd1: begin
                            dp_curr[1] <= min3(
                                dp_prev[0] + ((current_char == CHAR_M) ? 4'd0 : 4'd1),
                                dp_prev[1] + 4'd1,
                                dp_curr[0] + 4'd1
                            );
                            meow_idx <= 2'd2;
                        end
                        2'd2: begin
                            dp_curr[2] <= min3(
                                dp_prev[1] + ((current_char == CHAR_E) ? 4'd0 : 4'd1),
                                dp_prev[2] + 4'd1,
                                dp_curr[1] + 4'd1
                            );
                            meow_idx <= 2'd3;
                        end
                        2'd3: begin
                            dp_curr[3] <= min3(
                                dp_prev[2] + ((current_char == CHAR_O) ? 4'd0 : 4'd1),
                                dp_prev[3] + 4'd1,
                                dp_curr[2] + 4'd1
                            );
                            dp_curr[4] <= min3(
                                dp_prev[3] + ((current_char == CHAR_W) ? 4'd0 : 4'd1),
                                dp_prev[4] + 4'd1,
                                dp_curr[3] + 4'd1
                            );
                            if (dp_curr[4] < min_result) min_result <= dp_curr[4];
                            dp_prev[0] <= dp_curr[0];
                            dp_prev[1] <= dp_curr[1];
                            dp_prev[2] <= dp_curr[2];
                            dp_prev[3] <= dp_curr[3];
                            dp_prev[4] <= dp_curr[4];
                            char_idx <= char_idx + 1;
                            meow_idx <= 2'd0;
                        end
                    endcase
                end else begin
                    state <= FINISH;
                end
            end
            FINISH: begin
                result <= min_result;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

function [3:0] min3;
    input [3:0] a, b, c;
    reg [3:0] temp;
    begin
        temp = (a < b) ? a : b;
        min3 = (temp < c) ? temp : c;
    end
endfunction

endmodule

module hr_optimization (
    input clk,
    input rst_n,
    input start,
    input [3:0] day_index,  // Current day (0-15)
    input [3:0] f_i,         // Workers to fire (0-8)
    input [3:0] h_i,         // Workers to hire (0-8)
    output reg [3:0] hr_id,  // Assigned HR ID for this day
    output reg done,         // Computation complete
    output reg [3:0] min_hr  // Minimum HR count needed
);

// Scaled parameters
parameter MAX_DAYS = 16;
parameter MAX_WORKERS = 8;
parameter MAX_HR = 16;

// Internal state
reg [3:0] stack [0:MAX_WORKERS-1];  // Stack storing HR IDs of hired workers
reg [3:0] sp;  // Stack pointer
reg [3:0] used_hr_mask;  // Bitmask of used HR IDs for current day
reg [3:0] max_hr_used;
reg processing;
reg [3:0] day_counter;

integer i;

// Find smallest available HR ID
function [3:0] find_min_hr(input [15:0] used_mask);
    integer j;
    begin
        find_min_hr = 1;
        for (j = 1; j < MAX_HR; j = j + 1) begin
            if (!used_mask[j] && find_min_hr == 1) begin
                find_min_hr = j;
            end
        end
    end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sp <= 0;
        max_hr_used <= 0;
        done <= 0;
        processing <= 0;
        day_counter <= 0;
        hr_id <= 0;
        min_hr <= 0;
        for (i = 0; i < MAX_WORKERS; i = i + 1)
            stack[i] <= 0;
    end else begin
        if (start && !processing) begin
            processing <= 1;
            day_counter <= 0;
            done <= 0;
            sp <= 0;
            max_hr_used <= 0;
            for (i = 0; i < MAX_WORKERS; i = i + 1)
                stack[i] <= 0;
        end else if (processing) begin
            if (day_counter < MAX_DAYS) begin
                // Process current day
                used_hr_mask = 0;

                // Mark HR IDs of workers being fired
                for (i = 0; i < MAX_WORKERS; i = i + 1) begin
                    if (i < f_i && sp > 0 && sp - 1 - i >= 0) begin
                        used_hr_mask[stack[sp - 1 - i]] = 1;
                    end
                end

                // Find available HR ID
                hr_id <= find_min_hr(used_hr_mask);

                // Update max HR used
                if (find_min_hr(used_hr_mask) > max_hr_used)
                    max_hr_used <= find_min_hr(used_hr_mask);

                // Fire workers (LIFO)
                if (sp >= f_i)
                    sp <= sp - f_i;
                else
                    sp <= 0;

                // Hire new workers
                for (i = 0; i < MAX_WORKERS; i = i + 1) begin
                    if (i < h_i && sp + i < MAX_WORKERS) begin
                        stack[sp + i] <= find_min_hr(used_hr_mask);
                    end
                end
                if (sp + h_i <= MAX_WORKERS)
                    sp <= sp + h_i;
                else
                    sp <= MAX_WORKERS;

                day_counter <= day_counter + 1;
            end else begin
                processing <= 0;
                done <= 1;
                min_hr <= max_hr_used;
            end
        end else begin
            done <= 0;
        end
    end
end

endmodule

module frog_jumps #(
    parameter N = 8,
    parameter SPOT_WIDTH = 8,
    parameter IDX_WIDTH = 4
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [N*SPOT_WIDTH-1:0] spots_flat,
    output reg [IDX_WIDTH-1:0] max_index,
    output reg done
);
    // Unpack spots into an array for easy indexing
    wire [SPOT_WIDTH-1:0] spots [0:N-1];
    generate
        genvar g;
        for (g=0; g<N; g=g+1) begin
            assign spots[g] = spots_flat[g*SPOT_WIDTH +: SPOT_WIDTH];
        end
    endgenerate

    // Reachable flags
    reg [N-1:0] reachable;

    // State machine states
    localparam IDLE = 2'b00;
    localparam LOOP = 2'b01;
    localparam DONE = 2'b10;
    reg [1:0] state;

    // Index counters
    reg [IDX_WIDTH-1:0] i, j;

    // Condition computation
    wire [SPOT_WIDTH:0] sum = spots[i] + spots[j];
    wire [IDX_WIDTH:0] diff = j - i;          // unsigned, width = IDX_WIDTH+1
    wire condition_met = reachable[i] && (sum == diff);

    // Main sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            reachable <= 0;
            max_index <= 0;
            i <= 0;
            j <= 0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        // Initialize: only pebble 0 is reachable
                        reachable <= 0;
                        reachable[0] <= 1;
                        max_index <= 0;
                        i <= 0;
                        j <= 1;              // start with pair (0,1)
                        state <= LOOP;
                        done <= 0;
                    end
                end

                LOOP: begin
                    if (i >= N-1) begin
                        // No more pairs to check
                        state <= DONE;
                        done <= 1;
                    end else if (j >= N) begin
                        // Move to next i, reset j to i+1
                        i <= i + 1;
                        j <= i + 2;          // new i will be i+1, so j = (i+1)+1 = i+2
                    end else begin
                        // Check jump condition for current (i,j)
                        if (condition_met) begin
                            if (!reachable[j]) begin
                                reachable[j] <= 1;
                                if (j > max_index) max_index <= j;
                            end
                        end
                        j <= j + 1;
                    end
                end

                DONE: begin
                    // Stay in DONE until reset
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module min_magic_path #(
    parameter MAX_N = 8,
    parameter DATA_WIDTH = 16,   // magic value width
    parameter RESULT_WIDTH = 64  // result width
)(
    input  wire                    clk,
    input  wire                    rst_n,
    input  wire                    start,
    input  wire [3:0]              N,               // number of nodes (1..8)
    input  wire [MAX_N*MAX_N-1:0]  adj_flat,        // flattened adjacency matrix
    input  wire [MAX_N*DATA_WIDTH-1:0] magic_flat,   // flattened magic values
    output reg  [RESULT_WIDTH-1:0] result_numer,
    output reg  [RESULT_WIDTH-1:0] result_denom,
    output reg                     done
);

    // State definitions
    localparam IDLE              = 0;
    localparam BUILD_INIT        = 1;
    localparam BUILD_LOOP        = 2;
    localparam BUILD_FOR_V       = 3;
    localparam INIT_STATE        = 4;
    localparam LOOP_I            = 5;
    localparam LOOP_J            = 6;
    localparam COMPUTE_PATH_START = 7;
    localparam COMPUTE_PATH_LOOP1 = 8;
    localparam COMPUTE_PATH_LOOP2 = 9;
    localparam COMPUTE_PATH_LOOP3 = 10;
    localparam COMPUTE_PATH_FINAL = 11;
    localparam COMPARE           = 12;
    localparam REDUCE            = 13;
    localparam REDUCE_LOOP       = 14;
    localparam DONE              = 15;

    // Internal registers
    reg [4:0] state;
    reg [4:0] next_state;

    // BFS registers
    reg [MAX_N-1:0] visited;
    reg [3:0] parent [MAX_N-1:0];
    reg [3:0] depth [MAX_N-1:0];
    reg [3:0] queue [MAX_N-1:0];
    reg [3:0] queue_head;
    reg [3:0] queue_tail;
    reg [3:0] current_u;
    reg [3:0] v_counter;

    // Loop counters
    reg [3:0] i_counter;
    reg [3:0] j_counter;

    // Path computation registers
    reg [3:0] u_reg, v_reg;
    reg [RESULT_WIDTH-1:0] prod;
    reg [RESULT_WIDTH-1:0] len;

    // Best registers
    reg [RESULT_WIDTH-1:0] best_product;
    reg [RESULT_WIDTH-1:0] best_len;

    // Reduce registers
    reg [RESULT_WIDTH-1:0] a_reg;
    reg [RESULT_WIDTH-1:0] b_reg;
    reg [RESULT_WIDTH-1:0] temp_reg;

    // Combinational arrays from flat inputs
    wire [DATA_WIDTH-1:0] magic [MAX_N-1:0];
    wire [MAX_N-1:0] adj [MAX_N-1:0];

    genvar i_gen, j_gen;
    generate
        for (i_gen = 0; i_gen < MAX_N; i_gen = i_gen + 1) begin : gen_magic
            assign magic[i_gen] = magic_flat[i_gen*DATA_WIDTH +: DATA_WIDTH];
        end
        for (i_gen = 0; i_gen < MAX_N; i_gen = i_gen + 1) begin : gen_adj_row
            for (j_gen = 0; j_gen < MAX_N; j_gen = j_gen + 1) begin : gen_adj_col
                assign adj[i_gen][j_gen] = adj_flat[i_gen*MAX_N + j_gen];
            end
        end
    endgenerate

    // State transition logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE:               if (start) next_state = BUILD_INIT;
            BUILD_INIT:         next_state = BUILD_LOOP;
            BUILD_LOOP:         next_state = (queue_head != queue_tail) ? BUILD_FOR_V : INIT_STATE;
            BUILD_FOR_V:        next_state = (v_counter < N) ? BUILD_FOR_V : BUILD_LOOP;
            INIT_STATE:         next_state = LOOP_I;
            LOOP_I:             next_state = (i_counter < N) ? LOOP_J : REDUCE;
            LOOP_J:             next_state = (j_counter < N) ? COMPUTE_PATH_START : LOOP_I;
            COMPUTE_PATH_START: next_state = COMPUTE_PATH_LOOP1;
            COMPUTE_PATH_LOOP1: next_state = (depth[u_reg] > depth[v_reg]) ? COMPUTE_PATH_LOOP1 : COMPUTE_PATH_LOOP2;
            COMPUTE_PATH_LOOP2: next_state = (depth[v_reg] > depth[u_reg]) ? COMPUTE_PATH_LOOP2 : COMPUTE_PATH_LOOP3;
            COMPUTE_PATH_LOOP3: next_state = (u_reg != v_reg) ? COMPUTE_PATH_LOOP3 : COMPUTE_PATH_FINAL;
            COMPUTE_PATH_FINAL: next_state = COMPARE;
            COMPARE:            next_state = LOOP_J; // will increment j_counter in sequential block
            REDUCE:             next_state = (b_reg != 0) ? REDUCE_LOOP : DONE;
            REDUCE_LOOP:        next_state = (b_reg != 0) ? REDUCE_LOOP : DONE;
            DONE:               next_state = DONE;
            default:            next_state = IDLE;
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result_numer <= 0;
            result_denom <= 0;
            visited <= 0;
            queue_head <= 0;
            queue_tail <= 0;
            current_u <= 0;
            v_counter <= 0;
            i_counter <= 0;
            j_counter <= 0;
            u_reg <= 0;
            v_reg <= 0;
            prod <= 0;
            len <= 0;
            best_product <= 0;
            best_len <= 0;
            a_reg <= 0;
            b_reg <= 0;
            temp_reg <= 0;
            // Reset parent and depth arrays
            for (integer k = 0; k < MAX_N; k = k + 1) begin
                parent[k] <= 0;
                depth[k] <= 0;
                queue[k] <= 0;
            end
        end else begin
            state <= next_state;
            case (state)
                BUILD_INIT: begin
                    visited <= 1 << 0;
                    parent[0] <= 0;
                    depth[0] <= 0;
                    queue[0] <= 0;
                    queue_head <= 0;
                    queue_tail <= 1;
                    current_u <= 0;
                    v_counter <= 0;
                end
                BUILD_LOOP: begin
                    if (queue_head != queue_tail) begin
                        current_u <= queue[queue_head];
                        queue_head <= queue_head + 1;
                        v_counter <= 0;
                    end
                end
                BUILD_FOR_V: begin
                    if (v_counter < N) begin
                        if (adj[current_u][v_counter] && !visited[v_counter]) begin
                            visited[v_counter] <= 1'b1;
                            parent[v_counter] <= current_u;
                            depth[v_counter] <= depth[current_u] + 1;
                            queue[queue_tail] <= v_counter;
                            queue_tail <= queue_tail + 1;
                        end
                        v_counter <= v_counter + 1;
                    end
                end
                INIT_STATE: begin
                    best_product <= magic[0];
                    best_len <= 1;
                    i_counter <= 0;
                    j_counter <= 0;
                end
                LOOP_I: begin
                    if (i_counter < N) begin
                        j_counter <= i_counter;
                    end
                end
                LOOP_J: begin
                    // No action here; handled in next_state logic
                end
                COMPUTE_PATH_START: begin
                    u_reg <= i_counter;
                    v_reg <= j_counter;
                    prod <= 1;
                    len <= 0;
                end
                COMPUTE_PATH_LOOP1: begin
                    if (depth[u_reg] > depth[v_reg]) begin
                        prod <= prod * magic[u_reg];
                        len <= len + 1;
                        u_reg <= parent[u_reg];
                    end
                end
                COMPUTE_PATH_LOOP2: begin
                    if (depth[v_reg] > depth[u_reg]) begin
                        prod <= prod * magic[v_reg];
                        len <= len + 1;
                        v_reg <= parent[v_reg];
                    end
                end
                COMPUTE_PATH_LOOP3: begin
                    if (u_reg != v_reg) begin
                        prod <= prod * magic[u_reg] * magic[v_reg];
                        len <= len + 2;
                        u_reg <= parent[u_reg];
                        v_reg <= parent[v_reg];
                    end
                end
                COMPUTE_PATH_FINAL: begin
                    prod <= prod * magic[u_reg];
                    len <= len + 1;
                end
                COMPARE: begin
                    if (prod * best_len < best_product * len) begin
                        best_product <= prod;
                        best_len <= len;
                    end
                    j_counter <= j_counter + 1;
                end
                REDUCE: begin
                    a_reg <= best_product;
                    b_reg <= best_len;
                end
                REDUCE_LOOP: begin
                    if (b_reg != 0) begin
                        temp_reg <= b_reg;
                        b_reg <= a_reg % b_reg;
                        a_reg <= temp_reg;
                    end
                end
                DONE: begin
                    result_numer <= best_product / a_reg;
                    result_denom <= best_len / a_reg;
                    done <= 1;
                end
            endcase
        end
    end
endmodule

module sliding_blocks_solver #(
    parameter GRID_ROWS = 4,
    parameter GRID_COLS = 4,
    parameter MAX_BLOCKS = 8,
    parameter DATA_WIDTH = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] init_r,
    input wire [DATA_WIDTH-1:0] init_c,
    input wire [DATA_WIDTH-1:0] target_r [0:MAX_BLOCKS-1],
    input wire [DATA_WIDTH-1:0] target_c [0:MAX_BLOCKS-1],
    input wire [3:0] num_blocks,
    output reg move_valid,
    output reg [1:0] move_dir,
    output reg [DATA_WIDTH-1:0] move_k,
    output reg done,
    output reg possible
);

// State machine
localparam S_IDLE=3'd0, S_CHECK=3'd1, S_SEARCH=3'd2, S_OUTPUT=3'd3, S_UPDATE=3'd4, S_COMPLETE=3'd5, S_FAIL=3'd6;

reg [2:0] state;
reg [GRID_ROWS*GRID_COLS-1:0] grid;
reg [3:0] idx;
reg [DATA_WIDTH-1:0] cur_r, cur_c, k_reg;
reg [1:0] dir_reg;

function bit is_occ(input [DATA_WIDTH-1:0] r, c);
begin
    is_occ = (r>=1 && r<=GRID_ROWS && c>=1 && c<=GRID_COLS) ? grid[(r-1)*GRID_COLS + (c-1)] : 0;
end
endfunction

function automatic [9:0] find_move(input [DATA_WIDTH-1:0] r, c);
    integer i; bit v_up, v_down, v_left, v_right;
begin
    v_up = is_occ(r-1,c) && !is_occ(r+1,c);
    for (i=r+1; i<=GRID_ROWS; i=i+1) if (is_occ(i,c)) v_up = 0;

    v_down = is_occ(r+1,c) && !is_occ(r-1,c);
    for (i=r-1; i>=1; i=i-1) if (is_occ(i,c)) v_down = 0;

    v_left = is_occ(r,c-1) && !is_occ(r,c+1);
    for (i=c+1; i<=GRID_COLS; i=i+1) if (is_occ(r,i)) v_left = 0;

    v_right = is_occ(r,c+1) && !is_occ(r,c-1);
    for (i=c-1; i>=1; i=i-1) if (is_occ(r,i)) v_right = 0;

    if (v_up) find_move = {1'b1, 2'b11, r};
    else if (v_down) find_move = {1'b1, 2'b10, r};
    else if (v_left) find_move = {1'b1, 2'b00, c};
    else if (v_right) find_move = {1'b1, 2'b01, c};
    else find_move = 10'b0;
end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE; grid <= 0; idx <= 0;
        move_valid <= 0; done <= 0; possible <= 0;
    end else begin
        case (state)
            S_IDLE: if (start) begin
                move_valid <= 0; done <= 0; possible <= 0; idx <= 0;
                grid <= 0;
                if (init_r>=1 && init_r<=GRID_ROWS && init_c>=1 && init_c<=GRID_COLS)
                    grid[(init_r-1)*GRID_COLS + (init_c-1)] <= 1'b1;
                state <= S_CHECK;
            end
            S_CHECK: if (idx >= num_blocks) begin
                possible <= 1; state <= S_COMPLETE;
            end else begin
                cur_r <= target_r[idx]; cur_c <= target_c[idx]; state <= S_SEARCH;
            end
            S_SEARCH: begin
                {dir_reg, k_reg} <= find_move(cur_r, cur_c);
                if (find_move(cur_r, cur_c)[9]) state <= S_OUTPUT;
                else state <= S_FAIL;
            end
            S_OUTPUT: begin
                move_valid <= 1; move_dir <= dir_reg; move_k <= k_reg; state <= S_UPDATE;
            end
            S_UPDATE: begin
                move_valid <= 0;
                if (cur_r>=1 && cur_r<=GRID_ROWS && cur_c>=1 && cur_c<=GRID_COLS)
                    grid[(cur_r-1)*GRID_COLS + (cur_c-1)] <= 1'b1;
                idx <= idx + 1; state <= S_CHECK;
            end
            S_COMPLETE: begin done <= 1; state <= S_IDLE; end
            S_FAIL: begin possible <= 0; done <= 1; state <= S_IDLE; end
            default: state <= S_IDLE;
        endcase
    end
end
endmodule

