module min_deletions #(
    parameter N = 8,
    parameter DATA_WIDTH = 4,
    parameter ADDR_WIDTH = 3
)(
    input clk,
    input rst_n,
    input start,
    input [DATA_WIDTH-1:0] row1 [0:N-1],
    input [DATA_WIDTH-1:0] row2 [0:N-1],
    input [DATA_WIDTH-1:0] row3 [0:N-1],
    output reg [DATA_WIDTH-1:0] deletions,
    output reg done
);
    // State encoding
    localparam IDLE = 2'b00;
    localparam COMPUTE_POS = 2'b01;
    localparam ITERATE_MASKS = 2'b10;
    localparam CHECK_SUBSET = 2'b11;

    reg [1:0] state;
    reg [DATA_WIDTH-1:0] pos [0:N-1];  // pos[value-1] = column index
    reg [N-1:0] mask;                  // current subset mask
    reg [DATA_WIDTH-1:0] i;            // loop variable
    reg [DATA_WIDTH-1:0] max_size;
    reg [DATA_WIDTH-1:0] current_size;
    reg valid;
    reg [1:0] check_stage;
    reg seen2 [0:N-1];                 // seen values in row2 (indexed by value-1)
    reg seen3 [0:N-1];                 // seen values in row3
    reg [DATA_WIDTH-1:0] val2, val3;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            deletions <= 0;
            max_size <= 0;
            mask <= 0;
            i <= 0;
            check_stage <= 0;
            valid <= 1;
            current_size <= 0;
            for (int k = 0; k < N; k = k + 1) begin
                seen2[k] <= 0;
                seen3[k] <= 0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= COMPUTE_POS;
                        i <= 0;
                    end
                end

                COMPUTE_POS: begin
                    // Compute inverse mapping: for each column i, set pos[row1[i]-1] = i
                    pos[row1[i]-1] <= i;
                    if (i < N-1) begin
                        i <= i + 1;
                    end else begin
                        i <= 0;
                        mask <= 0;
                        max_size <= 0;
                        state <= ITERATE_MASKS;
                    end
                end

                ITERATE_MASKS: begin
                    if (mask < (1 << N)) begin
                        // Initialize for checking this mask
                        i <= 0;
                        valid <= 1;
                        current_size <= 0;
                        for (int k = 0; k < N; k = k + 1) begin
                            seen2[k] <= 0;
                            seen3[k] <= 0;
                        end
                        check_stage <= 0;
                        state <= CHECK_SUBSET;
                    end else begin
                        deletions <= N - max_size;
                        done <= 1;
                        state <= IDLE;
                    end
                end

                CHECK_SUBSET: begin
                    case (check_stage)
                        0: begin
                            if (i < N) begin
                                if (mask[i]) begin
                                    current_size <= current_size + 1;
                                    val2 <= row2[i];
                                    val3 <= row3[i];
                                    check_stage <= 1;
                                end else begin
                                    i <= i + 1;
                                end
                            end else begin
                                if (valid) begin
                                    if (current_size > max_size)
                                        max_size <= current_size;
                                end
                                mask <= mask + 1;
                                state <= ITERATE_MASKS;
                            end
                        end

                        1: begin
                            // Check closure: pos[val2-1] and pos[val3-1] must be in mask
                            if (!mask[pos[val2-1]] || !mask[pos[val3-1]])
                                valid <= 0;
                            // Check distinctness in row2
                            if (seen2[val2-1])
                                valid <= 0;
                            else
                                seen2[val2-1] <= 1;
                            // Check distinctness in row3
                            if (seen3[val3-1])
                                valid <= 0;
                            else
                                seen3[val3-1] <= 1;
                            i <= i + 1;
                            check_stage <= 0;
                        end
                    endcase
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module IceMazeSolver #(
    parameter ROWS = 4,
    parameter COLS = 4,
    parameter CELL_COUNT = ROWS * COLS,
    parameter DATA_WIDTH = 2,
    parameter DIST_WIDTH = 5,
    parameter DIR_COUNT = 4,
    parameter MAX_CYCLES = 256
)(
    input clk,
    input rst_n,
    input start,
    input [CELL_COUNT*DATA_WIDTH-1:0] grid_data,
    output reg [CELL_COUNT*DIST_WIDTH-1:0] distances_data,
    output reg done
);
    // State encoding
    localparam IDLE = 0, SETUP = 1, CHECK_CELL = 2, CALC_SLIDE = 3,
               UPDATE = 4, NEXT_DIR = 5, NEXT_CELL = 6, FINISHED = 7;
    reg [2:0] state, next_state;

    // Grid and distance storage
    reg [DATA_WIDTH-1:0] grid [0:CELL_COUNT-1];
    reg [DIST_WIDTH-1:0] dist [0:CELL_COUNT-1];
    reg [DIST_WIDTH-1:0] next_dist [0:CELL_COUNT-1];

    // Current cell and direction
    reg [5:0] curr_cell;
    reg [1:0] curr_dir;
    reg [5:0] cycle_count;

    // Slide computation
    reg [3:0] slide_r, slide_c;
    reg [3:0] next_r, next_c;
    reg [5:0] target_idx;
    reg slide_active;
    reg slide_done;

    // Unpack grid_data into array
    genvar g;
    generate
        for (g = 0; g < CELL_COUNT; g = g + 1) begin
            assign grid[g] = grid_data[g*DATA_WIDTH +: DATA_WIDTH];
        end
    endgenerate

    // Helper: convert linear index to coordinates
    function automatic [5:0] idx_to_coord;
        input [5:0] idx;
        begin
            idx_to_coord = idx / COLS;
        end
    endfunction

    function automatic [5:0] idx_to_col;
        input [5:0] idx;
        begin
            idx_to_col = idx % COLS;
        end
    endfunction

    // Helper: convert coordinates to linear index
    function automatic [5:0] coord_to_idx;
        input [3:0] r, c;
        begin
            coord_to_idx = r * COLS + c;
        end
    endfunction

    // Slide computation combinational logic
    always @(*) begin
        slide_done = 0;
        next_r = slide_r;
        next_c = slide_c;
        target_idx = coord_to_idx(slide_r, slide_c);

        if (slide_active) begin
            // Calculate next position based on direction
            case (curr_dir)
                2'b00: next_r = slide_r - 1; // up
                2'b01: next_r = slide_r + 1; // down
                2'b10: next_c = slide_c - 1; // left
                2'b11: next_c = slide_c + 1; // right
            endcase

            // Check boundaries
            if (next_r >= ROWS || next_c >= COLS) begin
                slide_done = 1;
            end else begin
                // Check cell type
                case (grid[coord_to_idx(next_r, next_c)])
                    2'b00: slide_done = 1; // obstacle
                    2'b01, 2'b11: begin // gravel or goal
                        target_idx = coord_to_idx(next_r, next_c);
                        slide_done = 1;
                    end
                    2'b10: begin // ice - continue sliding
                        // Update for next iteration
                        slide_r = next_r;
                        slide_c = next_c;
                    end
                    default: slide_done = 1;
                endcase
            end
        end
    end

    // State machine and distance updates
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            cycle_count <= 0;
            slide_active <= 0;
            // Reset distances to INF (31)
            for (integer i = 0; i < CELL_COUNT; i = i + 1) begin
                dist[i] <= {DIST_WIDTH{1'b1}};
                next_dist[i] <= {DIST_WIDTH{1'b1}};
            end
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= SETUP;
                        done <= 0;
                    end
                end
                SETUP: begin
                    // Find goal and set distance to 0
                    for (integer i = 0; i < CELL_COUNT; i = i + 1) begin
                        if (grid[i] == 2'b11) begin
                            dist[i] <= 0;
                            next_dist[i] <= 0;
                        end else begin
                            dist[i] <= {DIST_WIDTH{1'b1}};
                            next_dist[i] <= {DIST_WIDTH{1'b1}};
                        end
                    end
                    curr_cell <= 0;
                    curr_dir <= 0;
                    cycle_count <= 0;
                    state <= CHECK_CELL;
                end
                CHECK_CELL: begin
                    if (curr_cell < CELL_COUNT && cycle_count < MAX_CYCLES) begin
                        if (dist[curr_cell] != {DIST_WIDTH{1'b1}}) begin
                            // Calculate starting position for slide
                            slide_r <= idx_to_coord(curr_cell);
                            slide_c <= idx_to_col(curr_cell);
                            slide_active <= 1;
                            state <= CALC_SLIDE;
                        end else begin
                            state <= NEXT_CELL;
                        end
                    end else begin
                        state <= FINISHED;
                    end
                end
                CALC_SLIDE: begin
                    if (slide_done) begin
                        slide_active <= 0;
                        state <= UPDATE;
                    end
                end
                UPDATE: begin
                    if (target_idx != curr_cell && target_idx < CELL_COUNT) begin
                        // Update distance using reverse edge: dist[target] = min(dist[target], dist[curr] + 1)
                        if (next_dist[target_idx] > dist[curr_cell] + 1) begin
                            next_dist[target_idx] <= dist[curr_cell] + 1;
                        end
                    end
                    state <= NEXT_DIR;
                end
                NEXT_DIR: begin
                    if (curr_dir < DIR_COUNT - 1) begin
                        curr_dir <= curr_dir + 1;
                        state <= CHECK_CELL;
                    end else begin
                        state <= NEXT_CELL;
                    end
                end
                NEXT_CELL: begin
                    curr_cell <= curr_cell + 1;
                    curr_dir <= 0;
                    cycle_count <= cycle_count + 1;
                    // Update all distances at end of iteration
                    for (integer i = 0; i < CELL_COUNT; i = i + 1) begin
                        dist[i] <= next_dist[i];
                    end
                    state <= CHECK_CELL;
                end
                FINISHED: begin
                    // Pack distances into output
                    for (integer i = 0; i < CELL_COUNT; i = i + 1) begin
                        distances_data[i*DIST_WIDTH +: DIST_WIDTH] <= dist[i];
                    end
                    done <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

module guess_circle (
    // Number of papers (max 16)
    input wire [7:0] n,
