    case (F_curr)
        16'd121, 16'd143, 16'd1147, 16'd1457: is_wonderful = 1'b1;
        default: is_wonderful = 1'b0;
    endcase
end

// Main FSM
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 8'd0;
        count <= 8'd0;
        F_prev_prev <= 16'd0;
        F_prev <= 16'd0;
        F_curr <= 16'd0;
        done <= 1'b0;
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    i <= 8'd1;
                    count <= 8'd0;
                    F_prev_prev <= 16'd0;
                    F_prev <= 16'd0;
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                if (i == 8'd1) begin
                    F_curr <= 16'd42;
                end else if (i == 8'd2) begin
                    F_curr <= (11 * k) + 77;
                end else begin
                    F_curr <= (F_prev << 1) - F_prev_prev + (10 * k);
                end
                state <= CHECK;
            end

            CHECK: begin
                if (is_wonderful) begin
                    count <= count + 1;
                end
                state <= INCREMENT;
            end

            INCREMENT: begin
                F_prev_prev <= F_prev;
                F_prev <= F_curr;
                i <= i + 1;
                if (i + 1 > n) begin
                    state <= DONE;
                end else begin
                    state <= COMPUTE;
                end
            end

            DONE: begin
                result <= count;
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

