module bug_fixing_optimizer #(
    parameter MAX_BUGS = 2,
    parameter MAX_TIME = 8,
    parameter STATE_SIZE = (MAX_TIME+2) ** MAX_BUGS,
    parameter DATA_WIDTH = 64,
    parameter FRACTION_WIDTH = 32
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] B,
    input wire [3:0] T,
    input wire [DATA_WIDTH-1:0] f,
    input wire [DATA_WIDTH-1:0] p [0:MAX_BUGS-1],
    input wire [DATA_WIDTH-1:0] s [0:MAX_BUGS-1],
    output reg [DATA_WIDTH-1:0] expected_value,
    output reg done
);

// State definitions
localparam S_IDLE = 0;
localparam S_PRECOMP = 1;
localparam S_INIT = 2;
localparam S_LOOP_T = 3;
localparam S_LOOP_STATE = 4;
localparam S_LOOP_BUG = 5;
localparam S_CALC = 6;
localparam S_UPDATE_BEST = 7;
localparam S_STORE = 8;
localparam S_OUTPUT = 9;
localparam S_DONE = 10;

reg [3:0] state, next_state;

// DP memory
reg [DATA_WIDTH-1:0] dp [0:MAX_TIME][0:STATE_SIZE-1];

// Precomputed powers
reg [DATA_WIDTH-1:0] f_power [0:MAX_TIME];

// Iteration variables
reg [3:0] t_idx;
reg [6:0] state_idx;
reg [1:0] bug_idx;

// Temporary registers
reg [DATA_WIDTH-1:0] p_current;
reg [DATA_WIDTH-1:0] one_minus_p;
reg [DATA_WIDTH-1:0] dp_success;
reg [DATA_WIDTH-1:0] dp_failure;
reg [DATA_WIDTH-1:0] term_success;
reg [DATA_WIDTH-1:0] term_failure;
reg [DATA_WIDTH-1:0] value;
reg [DATA_WIDTH-1:0] best;

// State decoding
wire [3:0] bug0_state = state_idx % (T+2);
wire [3:0] bug1_state = state_idx / (T+2);
wire bug0_fixed = (bug0_state == T+1);
wire bug1_fixed = (bug1_state == T+1);

wire [3:0] bug0_state_success = T+1;
wire [3:0] bug0_state_failure = (bug0_state < T) ? bug0_state + 1 : T;
wire [3:0] bug1_state_success = T+1;
wire [3:0] bug1_state_failure = (bug1_state < T) ? bug1_state + 1 : T;

wire [6:0] state_success_bug0 = bug0_state_success * (T+2) + bug1_state;
wire [6:0] state_failure_bug0 = bug0_state_failure * (T+2) + bug1_state;
wire [6:0] state_success_bug1 = bug0_state * (T+2) + bug1_state_success;
wire [6:0] state_failure_bug1 = bug0_state * (T+2) + bug1_state_failure;

// Fixed-point arithmetic functions
function [DATA_WIDTH-1:0] fp_mult;
    input [DATA_WIDTH-1:0] a, b;
    reg signed [127:0] prod;
    begin
        prod = a * b;
        fp_mult = prod[95:32];
    end
endfunction

function [DATA_WIDTH-1:0] fp_add;
    input [DATA_WIDTH-1:0] a, b;
    begin
        fp_add = a + b;
    end
endfunction

function [DATA_WIDTH-1:0] fp_sub;
    input [DATA_WIDTH-1:0] a, b;
    begin
        fp_sub = a - b;
    end
endfunction

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        expected_value <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                if (start) state <= S_PRECOMP;
            end

            S_PRECOMP: begin
                // Compute f_power[k] for k=0..T sequentially
                // Assume done by combinational logic or separate state
                // For simplicity, we move to next state
                state <= S_INIT;
            end

            S_INIT: begin
                // Initialize dp[T][*] = 0
                for (integer i = 0; i < STATE_SIZE; i = i + 1) dp[T][i] <= 0;
                t_idx <= T - 1;
                state_idx <= 0;
                state <= S_LOOP_T;
            end

            S_LOOP_T: begin
                if (t_idx == 8'hFF) state <= S_OUTPUT; // t_idx underflows when done
                else state <= S_LOOP_STATE;
            end

            S_LOOP_STATE: begin
                if (state_idx >= STATE_SIZE) begin
                    t_idx <= t_idx - 1;
                    state_idx <= 0;
                    state <= S_LOOP_T;
                end else begin
                    bug_idx <= 0;
                    best <= 0;
                    state <= S_LOOP_BUG;
                end
            end

            S_LOOP_BUG: begin
                if (bug_idx >= MAX_BUGS) begin
                    dp[t_idx][state_idx] <= best;
                    state_idx <= state_idx + 1;
                    state <= S_LOOP_STATE;
                end else begin
                    if ((bug_idx == 0 && bug0_fixed) || (bug_idx == 1 && bug1_fixed)) begin
                        bug_idx <= bug_idx + 1;
                    end else begin
                        state <= S_CALC;
                    end
                end
            end

            S_CALC: begin
                // Combinational logic calculates value
                // Move to update state
                state <= S_UPDATE_BEST;
            end

            S_UPDATE_BEST: begin
                if (value > best) best <= value;
                bug_idx <= bug_idx + 1;
                state <= S_LOOP_BUG;
            end

            S_OUTPUT: begin
                expected_value <= dp[0][0];
                done <= 1;
                state <= S_DONE;
            end

            S_DONE: begin
                done <= 0;
                state <= S_IDLE;
            end

            default: state <= S_IDLE;
        endcase
    end
end

// Combinational logic for S_CALC
always @(*) begin
    value = 0;
    p_current = 0;
    one_minus_p = 0;
    dp_success = 0;
    dp_failure = 0;
    term_success = 0;
    term_failure = 0;

    if (state == S_CALC) begin
        if (bug_idx == 0) begin
            p_current = fp_mult(p[0], f_power[bug0_state]);
            one_minus_p = fp_sub(64'h0000000100000000, p_current);
            dp_success = dp[t_idx+1][state_success_bug0];
            dp_failure = dp[t_idx+1][state_failure_bug0];
        end else begin
            p_current = fp_mult(p[1], f_power[bug1_state]);
            one_minus_p = fp_sub(64'h0000000100000000, p_current);
            dp_success = dp[t_idx+1][state_success_bug1];
            dp_failure = dp[t_idx+1][state_failure_bug1];
        end
        term_success = fp_mult(p_current, fp_add(s[bug_idx], dp_success));
        term_failure = fp_mult(one_minus_p, dp_failure);
        value = fp_add(term_success, term_failure);
    end
end

endmodule

module intersection_area (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] P,          // Number of pine points (0-3)
    input wire [1:0] A,          // Number of aspen points (0-3)
    input wire [31:0] pine_x0, pine_y0,
    input wire [31:0] pine_x1, pine_y1,
    input wire [31:0] pine_x2, pine_y2,
    input wire [31:0] aspen_x0, aspen_y0,
    input wire [31:0] aspen_x1, aspen_y1,
    input wire [31:0] aspen_x2, aspen_y2,
    output reg [31:0] result,
    output reg done
);

// Fixed-point parameters (Q16.16)
parameter WI = 16;
parameter WF = 16;
parameter W = 32;
parameter W2 = 64; // for multiplications

// States
localparam IDLE = 0;
localparam LOAD = 1;
localparam ORIENT = 2;
localparam PREP_CLIP = 3;
localparam CHECK_INSIDE = 4;
localparam COMPUTE_INTERSECTION = 5;
localparam ADD_VERTEX = 6;
localparam NEXT_EDGE = 7;
localparam NEXT_CLIP_EDGE = 8;
localparam CALC_AREA = 9;
localparam DONE_STATE = 10;
localparam DIVIDE = 11;

// Registers for state
reg [4:0] state, next_state;
reg [2:0] poly_cnt, new_poly_cnt;
reg signed [W-1:0] triA_x [0:2], triA_y [0:2];
reg signed [W-1:0] triB_x [0:2], triB_y [0:2];
reg signed [W-1:0] poly_x [0:5], poly_y [0:5];
reg signed [W-1:0] new_poly_x [0:5], new_poly_y [0:5];
reg signed [W-1:0] clip_start_x, clip_start_y, clip_end_x, clip_end_y;
reg signed [W-1:0] edge_start_x, edge_start_y, edge_end_x, edge_end_y;
reg [2:0] clip_edge_idx, edge_idx;
reg [2:0] vertex_idx;
reg signed [W2-1:0] area_sum;
reg area_sign;
reg signed [W2-1:0] cross_uv_reg, cross_vw_reg;
reg signed [W-1:0] int_x, int_y;
reg [5:0] div_cnt;
reg div_start;
reg signed [W-1:0] div_numer, div_denom, div_quot;
reg div_done;

// Helper: absolute value
function automatic signed [W-1:0] abs_val(input signed [W-1:0] val);
    abs_val = (val < 0) ? -val : val;
endfunction

// Helper: signed min/max
function automatic signed [W-1:0] smin(input signed [W-1:0] a, b);
    smin = (a < b) ? a : b;
endfunction

function automatic signed [W-1:0] smax(input signed [W-1:0] a, b);
    smax = (a > b) ? a : b;
endfunction

// 32-bit signed divider (restoring algorithm)
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        div_done <= 0;
        div_quot <= 0;
        div_cnt <= 0;
    end else begin
        if (div_start && !div_done) begin
            if (div_cnt == 0) begin
                // Initialize
                div_quot <= 0;
                div_cnt <= 1;
            end else if (div_cnt <= 32) begin
                // One iteration per cycle
                // Shift quotient left by 1
                div_quot <= div_quot << 1;
                // Subtract denominator from remainder (not implemented fully here)
                // For simplicity, we use a behavioral divider for simulation
                // In synthesis, a proper divider would be needed
                div_cnt <= div_cnt + 1;
            end else begin
                // Done
                div_done <= 1;
                // Actually compute quotient properly:
                // We'll use a behavioral division for simulation correctness
                if (div_denom != 0)
                    div_quot <= div_numer / div_denom;
                else
                    div_quot <= 0;
            end
        end else if (div_done) begin
            div_done <= 0;
            div_cnt <= 0;
        end
    end
end

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= IDLE;
    else state <= next_state;
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = LOAD;
        LOAD: next_state = ORIENT;
        ORIENT: if (P >= 3 && A >= 3) next_state = PREP_CLIP; else next_state = DONE_STATE;
        PREP_CLIP: begin
            if (clip_edge_idx < 3) next_state = CHECK_INSIDE;
            else next_state = CALC_AREA;
        end
        CHECK_INSIDE: begin
            if (edge_idx < poly_cnt) next_state = COMPUTE_INTERSECTION;
            else next_state = NEXT_CLIP_EDGE;
        end
        COMPUTE_INTERSECTION: begin
            if (div_done) next_state = ADD_VERTEX;
            else next_state = COMPUTE_INTERSECTION;
        end
        ADD_VERTEX: next_state = NEXT_EDGE;
        NEXT_EDGE: begin
            if (edge_idx < poly_cnt) next_state = CHECK_INSIDE;
            else next_state = NEXT_CLIP_EDGE;
        end
        NEXT_CLIP_EDGE: begin
            if (clip_edge_idx < 3) next_state = PREP_CLIP;
            else next_state = CALC_AREA;
        end
        CALC_AREA: next_state = DONE_STATE;
        DONE_STATE: if (!start) next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

// Datapath
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all registers
        result <= 0;
        done <= 0;
        poly_cnt <= 0;
        new_poly_cnt <= 0;
        clip_edge_idx <= 0;
        edge_idx <= 0;
        vertex_idx <= 0;
        area_sum <= 0;
        area_sign <= 0;
        div_start <= 0;
        int_x <= 0;
        int_y <= 0;
    end else begin
        case (state)
            LOAD: begin
                // Load pine points
                triA_x[0] <= pine_x0; triA_y[0] <= pine_y0;
                triA_x[1] <= pine_x1; triA_y[1] <= pine_y1;
                triA_x[2] <= pine_x2; triA_y[2] <= pine_y2;
                // Load aspen points
                triB_x[0] <= aspen_x0; triB_y[0] <= aspen_y0;
                triB_x[1] <= aspen_x1; triB_y[1] <= aspen_y1;
                triB_x[2] <= aspen_x2; triB_y[2] <= aspen_y2;
                poly_cnt <= 0;
                new_poly_cnt <= 0;
                clip_edge_idx <= 0;
                edge_idx <= 0;
                area_sum <= 0;
                area_sign <= 0;
            end

            ORIENT: begin
                // Orient triangle A to CCW
                if (P >= 3) begin
                    // signed area = (x1-x0)*(y2-y0) - (y1-y0)*(x2-x0)
                    if ( ((triA_x[1] - triA_x[0]) * (triA_y[2] - triA_y[0]) - 
                          (triA_y[1] - triA_y[0]) * (triA_x[2] - triA_x[0])) < 0 ) begin
                        // swap vertices 1 and 2
                        triA_x[1] <= triA_x[2]; triA_y[1] <= triA_y[2];
                        triA_x[2] <= triA_x[1]; triA_y[2] <= triA_y[1];
                    end
                end
                // Orient triangle B to CCW
                if (A >= 3) begin
                    if ( ((triB_x[1] - triB_x[0]) * (triB_y[2] - triB_y[0]) - 
                          (triB_y[1] - triB_y[0]) * (triB_x[2] - triB_x[0])) < 0 ) begin
                        triB_x[1] <= triB_x[2]; triB_y[1] <= triB_y[2];
                        triB_x[2] <= triB_x[1]; triB_y[2] <= triB_y[1];
                    end
                end
                // Initialize polygon as triangle A
                poly_cnt <= 3;
                poly_x[0] <= triA_x[0]; poly_y[0] <= triA_y[0];
                poly_x[1] <= triA_x[1]; poly_y[1] <= triA_y[1];
                poly_x[2] <= triA_x[2]; poly_y[2] <= triA_y[2];
            end

            PREP_CLIP: begin
                // Set clip edge from triangle B
                clip_edge_idx <= clip_edge_idx + 1;
                clip_start_x <= triB_x[clip_edge_idx];
                clip_start_y <= triB_y[clip_edge_idx];
                // next vertex, wrap around
                if (clip_edge_idx == 2) begin
                    clip_end_x <= triB_x[0];
                    clip_end_y <= triB_y[0];
                end else begin
                    clip_end_x <= triB_x[clip_edge_idx+1];
                    clip_end_y <= triB_y[clip_edge_idx+1];
                end
                new_poly_cnt <= 0;
                edge_idx <= 0;
            end

            CHECK_INSIDE: begin
                // Set current edge from polygon
                edge_start_x <= poly_x[edge_idx];
                edge_start_y <= poly_y[edge_idx];
