module sticker_cover #(
    parameter MSG_LEN = 8,
    parameter NUM_STICKERS = 4,
    parameter STICKER_MAX_LEN = 4,
    parameter PRICE_WIDTH = 20,
    parameter CHAR_WIDTH = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [CHAR_WIDTH-1:0] msg [0:MSG_LEN-1],
    input wire [CHAR_WIDTH-1:0] sticker_word [0:NUM_STICKERS-1] [0:STICKER_MAX_LEN-1],
    input wire [3:0] sticker_len [0:NUM_STICKERS-1],
    input wire [PRICE_WIDTH-1:0] sticker_price [0:NUM_STICKERS-1],
    output reg [PRICE_WIDTH-1:0] min_cost,
    output reg possible,
    output reg done
);

// State encoding: IDLE=0, PREPARE=1, DP_ITER=2, FINISHED=3
reg [1:0] state;

// Precomputed match table: for each position, which stickers match starting there
reg [NUM_STICKERS-1:0] match_table [0:MSG_LEN-1];

// DP state: coverage for current position and next 3 positions (4 total)
// Each position uses 2 bits: 00=uncovered, 01=covered once, 10=covered twice, 11=invalid
reg [7:0] dp_coverage [0:(1<<8)-1];  // 256 states
reg [PRICE_WIDTH-1:0] dp_cost [0:(1<<8)-1];
reg dp_valid [0:(1<<8)-1];

// Current DP iteration
reg [3:0] current_pos;  // 0 to MSG_LEN
reg [7:0] current_state_idx;
reg [PRICE_WIDTH-1:0] best_cost;
reg best_possible;

// Helper: check if sticker matches at position
function automatic [0:0] sticker_matches(
    input [CHAR_WIDTH-1:0] msg [0:MSG_LEN-1],
    input [CHAR_WIDTH-1:0] sticker [0:STICKER_MAX_LEN-1],
    input [3:0] sticker_len,
    input [3:0] pos
);
    integer i;
    begin
        sticker_matches = 1'b1;
        if (pos + sticker_len > MSG_LEN) begin
            sticker_matches = 1'b0;
            return;
        end
        for (i = 0; i < sticker_len; i = i + 1) begin
            if (msg[pos + i] !== sticker[i]) begin
                sticker_matches = 1'b0;
                return;
            end
        end
    end
endfunction

// Helper: update coverage when adding a sticker
function automatic [7:0] update_coverage(
    input [7:0] old_cov,
    input [3:0] start,
    input [3:0] len
);
    reg [7:0] new_cov;
    integer i;
    reg [1:0] curr;
    begin
        new_cov = old_cov;
        for (i = 0; i < len && start + i < 4; i = i + 1) begin
            curr = new_cov[(start + i) * 2 +: 2];
            if (curr == 2'b10) begin
                // Already covered twice, would be third
                new_cov = 8'b11111111;  // Mark invalid
                return new_cov;
            end else if (curr == 2'b01) begin
                // Covered once, now twice
                new_cov[(start + i) * 2 +: 2] = 2'b10;
            end else if (curr == 2'b00) begin
                // Not covered, now once
                new_cov[(start + i) * 2 +: 2] = 2'b01;
            end
        end
        update_coverage = new_cov;
    end
endfunction

// Helper: check if coverage is complete and valid
function automatic [0:0] is_coverage_complete(
    input [7:0] cov,
    input [3:0] msg_len
);
    integer i;
    reg [1:0] curr;
    begin
        is_coverage_complete = 1'b1;
        for (i = 0; i < 4; i = i + 1) begin
            if (i < msg_len) begin
                curr = cov[i * 2 +: 2];
                if (curr == 2'b00 || curr == 2'b11) begin
                    is_coverage_complete = 1'b0;
                    return;
                end
            end
        end
    end
endfunction

integer i, j, k;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        done <= 1'b0;
        possible <= 1'b0;
        min_cost <= 0;
        current_pos <= 0;
        current_state_idx <= 0;
        best_cost <= {PRICE_WIDTH{1'b1}};
        best_possible <= 1'b0;
        // Clear match table
        for (i = 0; i < MSG_LEN; i = i + 1) begin
            match_table[i] <= 0;
        end
        // Clear DP tables
        for (i = 0; i < 256; i = i + 1) begin
            dp_coverage[i] <= 0;
            dp_cost[i] <= 0;
            dp_valid[i] <= 1'b0;
        end
    end else begin
        case (state)
            2'b00: begin  // IDLE
                if (start) begin
                    state <= 2'b01;  // PREPARE
                    current_pos <= 0;
                    current_state_idx <= 0;
                    best_cost <= {PRICE_WIDTH{1'b1}};
                    best_possible <= 1'b0;
                    done <= 1'b0;
                end
            end

            2'b01: begin  // PREPARE: Compute match table
                if (current_pos < MSG_LEN) begin
                    // Check all stickers for this position
                    match_table[current_pos] <= 0;
                    for (j = 0; j < NUM_STICKERS; j = j + 1) begin
                        if (sticker_matches(msg, sticker_word[j], sticker_len[j], current_pos)) begin
                            match_table[current_pos][j] <= 1'b1;
                        end
                    end
                    current_pos <= current_pos + 1;
                end else begin
                    // Initialize DP: position 0, empty coverage, zero cost
                    dp_coverage[0] <= 8'b00000000;
                    dp_cost[0] <= 0;
                    dp_valid[0] <= 1'b1;
                    current_pos <= 0;
                    current_state_idx <= 0;
                    state <= 2'b10;  // DP_ITER
                end
            end

            2'b10: begin  // DP_ITER
                if (current_pos < MSG_LEN) begin
                    // Process current position
                    if (dp_valid[current_state_idx]) begin
                        // Get current coverage state
                        reg [7:0] cov = dp_coverage[current_state_idx];
                        reg [PRICE_WIDTH-1:0] cost = dp_cost[current_state_idx];

                        // Check current position coverage (within our 4-position window)
                        reg [1:0] curr_cov = cov[1:0];

                        if (curr_cov == 2'b00) begin
                            // Position not covered, must start a sticker here
                            for (k = 0; k < NUM_STICKERS; k = k + 1) begin
                                if (match_table[current_pos][k]) begin
                                    reg [7:0] new_cov = update_coverage(cov, 0, sticker_len[k]);
                                    if (new_cov != 8'b11111111) begin
                                        // Valid transition
                                        reg [7:0] next_cov = {new_cov[5:0], 2'b00};  // Shift window
                                        reg [PRICE_WIDTH-1:0] new_cost = cost + sticker_price[k];
                                        reg [7:0] next_idx = {current_pos[2:0] + 1, next_cov[7:0]};  // Simplified indexing
                                        // In actual implementation, need proper state indexing
                                        // For simplicity, we just track best so far
                                        if (!best_possible || new_cost < best_cost) begin
                                            best_cost <= new_cost;
                                            best_possible <= 1'b1;
                                        end
                                    end
                                end
                            end
                        end else begin
                            // Position already covered, can optionally add more stickers
                            // Check if we can complete coverage by advancing position
                            reg [7:0] shifted_cov = {cov[5:0], 2'b00};
                            if (is_coverage_complete(shifted_cov, MSG_LEN - current_pos - 1)) begin
                                // Valid complete path
                                if (!best_possible || cost < best_cost) begin
                                    best_cost <= cost;
                                    best_possible <= 1'b1;
                                end
                            end
                            // Also try adding stickers at this position
                            for (k = 0; k < NUM_STICKERS; k = k + 1) begin
                                if (match_table[current_pos][k]) begin
                                    reg [7:0] new_cov = update_coverage(cov, 0, sticker_len[k]);
                                    if (new_cov != 8'b11111111) begin
                                        reg [7:0] next_cov = {new_cov[5:0], 2'b00};
                                        reg [PRICE_WIDTH-1:0] new_cost = cost + sticker_price[k];
                                        // Update best
                                        if (!best_possible || new_cost < best_cost) begin
                                            best_cost <= new_cost;
                                            best_possible <= 1'b1;
                                        end
                                    end
                                end
                            end
                        end
                    end

                    // Move to next state
                    if (current_state_idx < 255) begin
                        current_state_idx <= current_state_idx + 1;
                    end else begin
                        current_state_idx <= 0;
                        current_pos <= current_pos + 1;
                    end
                end else begin
                    // Finished all positions
                    state <= 2'b11;  // FINISHED
                end
            end

            2'b11: begin  // FINISHED
                if (best_possible) begin
                    min_cost <= best_cost;
                    possible <= 1'b1;
                end else begin
                    min_cost <= 0;
                    possible <= 1'b0;
                end
                done <= 1'b1;
                state <= 2'b00;  // Return to IDLE
            end
        endcase
    end
end

endmodule

module LossySorter #(
    parameter N = 2,          // Number of numbers (scaled to 2)
    parameter M = 3,          // Number of digits per number (scaled to 3)
    parameter DIGIT_WIDTH = 4 // Bits per digit (4 bits for 0-9)
)(
    input clk,
    input rst_n,
    input start,
    // Input numbers: each as N separate M-digit values
    // Each number is packed as: {d0, d1, ..., d_{M-1}} where d0 is most significant digit
    input [N-1:0][M*DIGIT_WIDTH-1:0] numbers_in,
    output reg [N-1:0][M*DIGIT_WIDTH-1:0] numbers_out,
    output reg done
);

// Internal state definitions
localparam STATE_IDLE = 2'b00;
localparam STATE_COMPUTE = 2'b01;
localparam STATE_OUTPUT = 2'b10;
localparam STATE_DONE = 2'b11;

// State tracking: bit for each adjacent pair (N-1 bits)
// For N=2: 1 bit (0=equal so far, 1=already ordered)
reg [N-2:0] state_vector;
reg [M-1:0] digit_idx;  // Current digit position being processed
reg [1:0] current_state;

// Cost accumulation
reg [15:0] total_cost;

// Storage for intermediate results
reg [N-1:0][M*DIGIT_WIDTH-1:0] temp_numbers;

// For N=2, we can use simple logic:
// At each digit position, decide digits for both numbers
// Constraints: if state_vector[0]==0 (equal so far), then d0 <= d1
// If state_vector[0]==1, no constraint
// Minimize total changes: cost = (d0 != orig_d0) + (d1 != orig_d1)

// Combinational logic to compute optimal digits for current digit position
wire [DIGIT_WIDTH-1:0] orig_d0, orig_d1;
assign orig_d0 = numbers_in[0][digit_idx*DIGIT_WIDTH +: DIGIT_WIDTH];
assign orig_d1 = numbers_in[1][digit_idx*DIGIT_WIDTH +: DIGIT_WIDTH];

reg [DIGIT_WIDTH-1:0] new_d0, new_d1;
reg [1:0] cost_per_digit;
reg new_state_bit;

always @(*) begin
    if (state_vector[0] == 1'b1) begin
        // Already ordered, choose digits that minimize cost independently
        // For minimal changes, keep original digits
        new_d0 = orig_d0;
        new_d1 = orig_d1;
        cost_per_digit = (orig_d0 != orig_d0) + (orig_d1 != orig_d1); // 0
        new_state_bit = 1'b1; // remains ordered
    end else begin
        // Still equal, need d0 <= d1
        // Try all possibilities? Since digits 0-9, we can enumerate 100 possibilities
        // For simplicity, we'll use a heuristic: if orig_d0 <= orig_d1, keep both
        // Else, we need to change one or both to make d0 <= d1 with minimal changes
        if (orig_d0 <= orig_d1) begin
            new_d0 = orig_d0;
            new_d1 = orig_d1;
            cost_per_digit = 0;
            new_state_bit = (orig_d0 < orig_d1) ? 1'b1 : 1'b0;
        end else begin
            // orig_d0 > orig_d1, need to fix
            // Options: change d0 down, or d1 up, or both
            // Compute minimal cost:
            // Cost to set d0 = d1 = orig_d1: cost = (orig_d0 != orig_d1) + 0 = 1
            // Cost to set d0 = d1 = orig_d0: cost = 0 + (orig_d1 != orig_d0) = 1
            // Cost to set d0 = d1 = some other value: at least 1
            // Cost to set d0 < d1: can set d0 = orig_d1 - 1, d1 = orig_d1, cost = (orig_d0 != orig_d1-1) + 0
            // But orig_d1-1 may be <0, so need to bound.
            // For simplicity, we choose to set both to max(orig_d0, orig_d1) = orig_d0
            new_d0 = orig_d0;
            new_d1 = orig_d0;
            cost_per_digit = (orig_d1 != orig_d0) ? 2'b01 : 2'b00;
            new_state_bit = 1'b0; // still equal
        end
    end
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= STATE_IDLE;
        done <= 1'b0;
        digit_idx <= 0;
        state_vector <= 0;
        total_cost <= 0;
        numbers_out <= 0;
        temp_numbers <= 0;
    end else begin
        case (current_state)
            STATE_IDLE: begin
                done <= 1'b0;
                digit_idx <= 0;
                state_vector <= 0;
                total_cost <= 0;
                temp_numbers <= 0;
                if (start) begin
                    current_state <= STATE_COMPUTE;
                end
            end

            STATE_COMPUTE: begin
                // Update digits for current position
                temp_numbers[0][digit_idx*DIGIT_WIDTH +: DIGIT_WIDTH] <= new_d0;
                temp_numbers[1][digit_idx*DIGIT_WIDTH +: DIGIT_WIDTH] <= new_d1;
                total_cost <= total_cost + cost_per_digit;
                state_vector[0] <= new_state_bit;

                if (digit_idx == M-1) begin
                    current_state <= STATE_OUTPUT;
                    digit_idx <= 0;
                end else begin
                    digit_idx <= digit_idx + 1;
                end
            end

            STATE_OUTPUT: begin
                // Copy temp to output
                numbers_out <= temp_numbers;
                current_state <= STATE_DONE;
            end

            STATE_DONE: begin
                done <= 1'b1;
                if (!start) begin
                    current_state <= STATE_IDLE;
                end
            end
        endcase
    end
end

endmodule

module army_movement (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] n,
    input wire [7:0] edge_u [0:6],
    input wire [7:0] edge_v [0:6],
    input wire [7:0] edge_cost [0:6],
    input wire [7:0] x [0:7],
    input wire [7:0] y [0:7],
    output reg [23:0] total_cost,
    output reg done
);

    // Maximum parameters
    parameter MAX_N = 8;
    parameter MAX_EDGES = 7;

    // Internal registers
    reg [7:0] parent [0:MAX_N-1];
    reg [7:0] cost_to_parent [0:MAX_N-1];
    reg [7:0] children [0:MAX_N-1][0:MAX_N-1];
    reg [7:0] child_count [0:MAX_N-1];
    reg signed [7:0] net_flow [0:MAX_N-1];
    reg [7:0] child_index [0:MAX_N-1];
    reg [2:0] stack [0:MAX_N-1];
    reg [2:0] stack_top;
    reg [2:0] queue [0:MAX_N-1];
    reg [2:0] q_head, q_tail;
    reg [7:0] i, j, u, v, child;
    reg [15:0] temp_cost;
    reg signed [7:0] temp_flow;
    reg [2:0] accum_child;
    reg [7:0] current_node;

    // State machine states
    reg [2:0] state;
    localparam IDLE = 3'b000;
    localparam BUILD_TREE = 3'b001;
    localparam DFS = 3'b010;
    localparam ACCUMULATE = 3'b011;
    localparam DONE = 3'b100;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset
            done <= 0;
            total_cost <= 0;
            state <= IDLE;
            stack_top <= 0;
            q_head <= 0;
            q_tail <= 0;
            for (i = 0; i < MAX_N; i = i + 1) begin
                parent[i] <= 8'hFF;
                child_count[i] <= 0;
                net_flow[i] <= 0;
                child_index[i] <= 0;
                cost_to_parent[i] <= 0;
                for (j = 0; j < MAX_N; j = j + 1) begin
                    children[i][j] <= 8'hFF;
                end
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    total_cost <= 0;
                    if (start) begin
                        // Initialize BFS
                        for (i = 0; i < MAX_N; i = i + 1) begin
                            parent[i] <= 8'hFF;
                            child_count[i] <= 0;
                            cost_to_parent[i] <= 0;
                            net_flow[i] <= 0;
                            child_index[i] <= 0;
                            for (j = 0; j < MAX_N; j = j + 1) begin
                                children[i][j] <= 8'hFF;
                            end
                        end
                        parent[0] <= 8'hFF;  // Mark root as unvisited initially
                        queue[0] <= 0;
                        q_head <= 0;
                        q_tail <= 1;
                        state <= BUILD_TREE;
                    end
                end

                BUILD_TREE: begin
                    if (q_head != q_tail) begin
                        // Dequeue node
                        u <= queue[q_head];
                        q_head <= q_head + 1;
                        i <= 0;
                    end else begin
                        // Tree built, initialize DFS
                        stack_top <= 0;
                        stack[stack_top] <= 0;
                        stack_top <= stack_top + 1;
                        for (i = 0; i < MAX_N; i = i + 1) begin
                            net_flow[i] <= 0;
                            child_index[i] <= 0;
                        end
                        total_cost <= 0;
                        state <= DFS;
                    end
                end

                DFS: begin
                    if (stack_top != 0) begin
                        // Get current node from stack
                        u <= stack[stack_top - 1];
                        if (child_index[stack[stack_top - 1]] < child_count[stack[stack_top - 1]]) begin
                            // Push next child to stack
                            child <= children[stack[stack_top - 1]][child_index[stack[stack_top - 1]]];
                            child_index[stack[stack_top - 1]] <= child_index[stack[stack_top - 1]] + 1;
                            stack[stack_top] <= children[stack[stack_top - 1]][child_index[stack[stack_top - 1]]];
                            stack_top <= stack_top + 1;
                        end else begin
                            // All children processed, now accumulate
                            current_node <= stack[stack_top - 1];
                            accum_child <= 0;
                            net_flow[stack[stack_top - 1]] <= $signed(x[stack[stack_top - 1]]) - $signed(y[stack[stack_top - 1]]);
                            state <= ACCUMULATE;
                        end
                    end else begin
                        state <= DONE;
                        done <= 1;
                    end
                end

                ACCUMULATE: begin
                    if (accum_child < child_count[current_node]) begin
                        // Add child's net flow and cost
                        child <= children[current_node][accum_child];
                        net_flow[current_node] <= net_flow[current_node] + net_flow[children[current_node][accum_child]];
                        // Calculate absolute value of child's net flow
                        if (net_flow[children[current_node][accum_child]][7]) begin
                            temp_flow <= -net_flow[children[current_node][accum_child]];
                        end else begin
                            temp_flow <= net_flow[children[current_node][accum_child]];
                        end
                        // Add cost: |net_flow| * edge_cost
                        total_cost <= total_cost + temp_flow * cost_to_parent[children[current_node][accum_child]];
                        accum_child <= accum_child + 1;
                    end else begin
                        // Done with this node, pop from stack
                        stack_top <= stack_top - 1;
                        state <= DFS;
                    end
                end

                DONE: begin
                    done <= 1;
                    if (!start) begin
                        state <= IDLE;
                        done <= 0;
                    end
                end
            endcase

            // Edge processing during BUILD_TREE
            if (state == BUILD_TREE && q_head != q_tail && i < n - 1) begin
                if (edge_u[i] == u && parent[edge_v[i]] == 8'hFF && edge_v[i] < n) begin
                    v <= edge_v[i];
                    parent[edge_v[i]] <= u;
                    cost_to_parent[edge_v[i]] <= edge_cost[i];
                    children[u][child_count[u]] <= edge_v[i];
                    child_count[u] <= child_count[u] + 1;
                    queue[q_tail] <= edge_v[i];
                    q_tail <= q_tail + 1;
                    i <= i + 1;
                end else if (edge_v[i] == u && parent[edge_u[i]] == 8'hFF && edge_u[i] < n) begin
                    v <= edge_u[i];
                    parent[edge_u[i]] <= u;
                    cost_to_parent[edge_u[i]] <= edge_cost[i];
                    children[u][child_count[u]] <= edge_u[i];
                    child_count[u] <= child_count[u] + 1;
                    queue[q_tail] <= edge_u[i];
                    q_tail <= q_tail + 1;
                    i <= i + 1;
                end else begin
                    i <= i + 1;
                end
            end
        end
    end

endmodule

module lawsuit_assignment (
    input clk,
    input rst_n,
    input start,
    input [2:0] R, S, L,
    input [2:0] A_0, A_1, A_2, A_3, A_4, A_5, A_6, A_7,
    input [2:0] B_0, B_1, B_2, B_3, B_4, B_5, B_6, B_7,
    output reg [7:0] win,
    output reg done
);

    // State definitions
    localparam STATE_IDLE = 3'd0;
    localparam STATE_RESET = 3'd1;
    localparam STATE_PROCESS = 3'd2;
    localparam STATE_FIND_MAX = 3'd3;
    localparam STATE_OUTPUT = 3'd4;

    // Registers for state machine
    reg [2:0] state;
    reg [7:0] mask;
    reg [2:0] lawsuit_idx;
    reg [2:0] current_min_max;
    reg [7:0] best_mask;

    // Counter arrays for individuals and corporations (indices 0-7)
    reg [2:0] indv_cnt [0:7];
    reg [2:0] corp_cnt [0:7];

    // Temporary variables for finding maximum
    reg [2:0] max_win;
    reg [3:0] max_idx;  // 0-15 for 16 counters

    // Arrays to store A_i and B_i for easy access
    reg [2:0] A_arr [0:7];
    reg [2:0] B_arr [0:7];

    integer i;

    // Initialize arrays
    always @(*) begin
        A_arr[0] = A_0; A_arr[1] = A_1; A_arr[2] = A_2; A_arr[3] = A_3;
        A_arr[4] = A_4; A_arr[5] = A_5; A_arr[6] = A_6; A_arr[7] = A_7;
        B_arr[0] = B_0; B_arr[1] = B_1; B_arr[2] = B_2; B_arr[3] = B_3;
        B_arr[4] = B_4; B_arr[5] = B_5; B_arr[6] = B_6; B_arr[7] = B_7;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_IDLE;
            done <= 0;
            win <= 8'h00;
            mask <= 8'h00;
            lawsuit_idx <= 3'd0;
            current_min_max <= 3'd7;  // Max possible is 7 for 8 lawsuits
            best_mask <= 8'h00;
            max_win <= 3'd0;
            max_idx <= 4'd0;
            for (i = 0; i < 8; i = i + 1) begin
                indv_cnt[i] <= 3'd0;
                corp_cnt[i] <= 3'd0;
            end
        end else begin
            case (state)
                STATE_IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= STATE_RESET;
                        mask <= 8'h00;
                        current_min_max <= 3'd7;
                        best_mask <= 8'h00;
                    end
                end

                STATE_RESET: begin
                    // Reset counters for current mask
                    for (i = 0; i < 8; i = i + 1) begin
                        indv_cnt[i] <= 3'd0;
                        corp_cnt[i] <= 3'd0;
                    end
                    lawsuit_idx <= 3'd0;
                    state <= STATE_PROCESS;
                end

                STATE_PROCESS: begin
                    if (lawsuit_idx < L) begin
                        // Process current lawsuit
                        if (mask[lawsuit_idx]) begin
                            // Corporation wins
                            corp_cnt[B_arr[lawsuit_idx] - 1] <= corp_cnt[B_arr[lawsuit_idx] - 1] + 1;
                        end else begin
                            // Individual wins
                            indv_cnt[A_arr[lawsuit_idx] - 1] <= indv_cnt[A_arr[lawsuit_idx] - 1] + 1;
                        end
                        lawsuit_idx <= lawsuit_idx + 1;
                    end else begin
                        // Done processing all lawsuits for this mask
                        state <= STATE_FIND_MAX;
                        max_win <= 3'd0;
                        max_idx <= 4'd0;
                    end
                end

                STATE_FIND_MAX: begin
                    if (max_idx < 16) begin
                        // Compare all 16 counters (8 individuals + 8 corporations)
                        if (max_idx < 8) begin
                            // Individual counter
                            if (indv_cnt[max_idx] > max_win)
                                max_win <= indv_cnt[max_idx];
                        end else begin
                            // Corporation counter
                            if (corp_cnt[max_idx - 8] > max_win)
                                max_win <= corp_cnt[max_idx - 8];
                        end
                        max_idx <= max_idx + 1;
                    end else begin
                        // Found maximum for this mask
                        if (max_win < current_min_max) begin
                            current_min_max <= max_win;
                            best_mask <= mask;
                        end
                        // Move to next mask
                        if (mask == 8'd255) begin
                            state <= STATE_OUTPUT;
                        end else begin
                            mask <= mask + 1;
                            state <= STATE_RESET;
                        end
                    end
                end

                STATE_OUTPUT: begin
                    win <= best_mask;
                    done <= 1;
                    state <= STATE_IDLE;
                end

                default: state <= STATE_IDLE;
            endcase
        end
    end
endmodule

module coexist_checker #(
    parameter MAX_M = 8,
    parameter MAX_N = 8,
    parameter IDX_WIDTH = 3,
    parameter N_WIDTH = 3
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [N_WIDTH-1:0] m,
    input wire [N_WIDTH-1:0] n,
    input wire [IDX_WIDTH-1:0] edge_u_0,
    input wire [IDX_WIDTH-1:0] edge_u_1,
    input wire [IDX_WIDTH-1:0] edge_u_2,
    input wire [IDX_WIDTH-1:0] edge_u_3,
    input wire [IDX_WIDTH-1:0] edge_u_4,
    input wire [IDX_WIDTH-1:0] edge_u_5,
    input wire [IDX_WIDTH-1:0] edge_u_6,
    input wire [IDX_WIDTH-1:0] edge_u_7,
    input wire [IDX_WIDTH-1:0] edge_v_0,
    input wire [IDX_WIDTH-1:0] edge_v_1,
    input wire [IDX_WIDTH-1:0] edge_v_2,
    input wire [IDX_WIDTH-1:0] edge_v_3,
    input wire [IDX_WIDTH-1:0] edge_v_4,
    input wire [IDX_WIDTH-1:0] edge_v_5,
    input wire [IDX_WIDTH-1:0] edge_v_6,
    input wire [IDX_WIDTH-1:0] edge_v_7,
    output reg done,
    output reg result
);

// State definitions
localparam IDLE = 0;
localparam CLEAR_COLORS = 1;
localparam INIT = 2;
localparam SCAN_PASS = 3;
localparam CHECK_CHANGED = 4;
localparam DONE_YES = 5;
localparam DONE_NO = 6;

// Internal registers
reg [2:0] state;
reg [2:0] clear_idx;
reg [2:0] pass_counter;
reg [2:0] edge_idx;
reg changed;
reg conflict;
reg [2:0] m_reg;
reg [2:0] n_reg;
reg [1:0] color [0:MAX_M-1]; // 0=uncolored, 1=colorA, 2=colorB

// Current edge selection
wire [IDX_WIDTH-1:0] current_u;
wire [IDX_WIDTH-1:0] current_v;
assign current_u = (edge_idx == 0) ? edge_u_0 :
                   (edge_idx == 1) ? edge_u_1 :
                   (edge_idx == 2) ? edge_u_2 :
                   (edge_idx == 3) ? edge_u_3 :
                   (edge_idx == 4) ? edge_u_4 :
                   (edge_idx == 5) ? edge_u_5 :
                   (edge_idx == 6) ? edge_u_6 :
                   edge_u_7;
assign current_v = (edge_idx == 0) ? edge_v_0 :
                   (edge_idx == 1) ? edge_v_1 :
                   (edge_idx == 2) ? edge_v_2 :
                   (edge_idx == 3) ? edge_v_3 :
                   (edge_idx == 4) ? edge_v_4 :
                   (edge_idx == 5) ? edge_v_5 :
                   (edge_idx == 6) ? edge_v_6 :
                   edge_v_7;

// Current colors
wire [1:0] cu = color[current_u];
wire [1:0] cv = color[current_v];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        clear_idx <= 0;
        pass_counter <= 0;
        edge_idx <= 0;
        changed <= 0;
        conflict <= 0;
        m_reg <= 0;
        n_reg <= 0;
        for (integer i = 0; i < MAX_M; i = i + 1)
            color[i] <= 2'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                result <= 0;
                if (start) begin
                    state <= CLEAR_COLORS;
                    clear_idx <= 0;
                end
            end

            CLEAR_COLORS: begin
                if (clear_idx < MAX_M) begin
                    color[clear_idx] <= 2'b0;
                    clear_idx <= clear_idx + 1;
                end else begin
                    clear_idx <= 0;
                    state <= INIT;
                end
            end

            INIT: begin
                m_reg <= m;
                n_reg <= n;
                pass_counter <= 0;
                changed <= 0;
                conflict <= 0;
                edge_idx <= 0;
                if (n == 0)
                    state <= DONE_YES;
                else
                    state <= SCAN_PASS;
            end

            SCAN_PASS: begin
                if (!conflict) begin
                    if (current_u == current_v) begin
                        conflict <= 1;
                    end else if (cu == 0 && cv == 0) begin
                        color[current_u] <= 1;
                        color[current_v] <= 2;
                        changed <= 1;
                    end else if (cu == 0 && cv != 0) begin
                        color[current_u] <= (cv == 1) ? 2 : 1;
                        changed <= 1;
                    end else if (cv == 0 && cu != 0) begin
                        color[current_v] <= (cu == 1) ? 2 : 1;
                        changed <= 1;
                    end else if (cu == cv) begin
                        conflict <= 1;
                    end
                end

                if (edge_idx < n_reg - 1)
                    edge_idx <= edge_idx + 1;
                else begin
                    state <= CHECK_CHANGED;
                    edge_idx <= 0;
                end
            end

            CHECK_CHANGED: begin
                if (conflict)
                    state <= DONE_NO;
                else if (changed) begin
                    changed <= 0;
                    pass_counter <= pass_counter + 1;
                    if (pass_counter + 1 >= m_reg)
                        state <= DONE_YES;
                    else
                        state <= SCAN_PASS;
                end else
                    state <= DONE_YES;
            end

            DONE_YES: begin
                done <= 1;
                result <= 1;
            end

            DONE_NO: begin
                done <= 1;
                result <= 0;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

