module TreePlanner (
    input clk,
    input rst_n,
    input start,
    input [13:0] L,       // Road length (0-10000)
    input [4:0] W,        // Road width (0-20)
    input [13:0] pos [0:7], // Sorted positions (max 8 trees)
    output reg [31:0] result, // Q16.16 fixed-point result
    output reg done
);

// Parameters
parameter MAX_N = 8;
parameter K = MAX_N / 2; // Number of pairs

// State machine
localparam IDLE = 3'b000,
           COMPUTE_DP = 3'b001,
           FINALIZE = 3'b010,
           DONE_STATE = 3'b011;
reg [2:0] state;

// DP state tracking
reg [3:0] i, j; // i = left assigned, j = right assigned
reg [31:0] dp [0:4][0:4]; // DP table [0..4][0..4]

// Computation registers
reg [31:0] current_pos;
reg [31:0] left_target;
reg [31:0] right_target;
reg [31:0] dist_left;
reg [31:0] dist_right;
reg [31:0] candidate1, candidate2;

// Fixed-point constants
wire [31:0] W_fp; // W in Q16.16
assign W_fp = {W, 16'b0}; // Scale by 2^16

// DP Initialization
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        j <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Initialize DP table
                    for (int idx = 0; idx <= K; idx = idx + 1) begin
                        for (int jdx = 0; jdx <= K; jdx = jdx + 1) begin
                            dp[idx][jdx] <= 32'h7FFFFFFF; // Initialize to max
                        end
                    end
                    dp[0][0] <= 0;
                    i <= 0;
                    j <= 0;
                    state <= COMPUTE_DP;
                end
            end

            COMPUTE_DP: begin
                if (i <= K && j <= K) begin
                    // Current tree index = i+j-1
                    if (i+j < MAX_N) begin
                        current_pos <= {18'b0, pos[i+j]}; // Convert to Q16.16
                        left_target <= (K > 1) ? ((i * L) / (K-1)) << 16 : 0;
                        right_target <= (K > 1) ? ((j * L) / (K-1)) << 16 : 0;

                        // Calculate distances
                        if (i > 0) begin
                            // Manhattan distance to left target
                            if (current_pos >= left_target)
                                dist_left <= (current_pos - left_target);
                            else
                                dist_left <= (left_target - current_pos);
                        end

                        if (j > 0) begin
                            // Manhattan distance to right target + vertical
                            if (current_pos >= right_target)
                                dist_right <= (current_pos - right_target) + W_fp;
                            else
                                dist_right <= (right_target - current_pos) + W_fp;
                        end

                        state <= FINALIZE;
                    end else begin
                        state <= DONE_STATE;
                    end
                end else begin
                    // Move to next state
                    if (i < K) begin
                        i <= i + 1;
                        j <= j;
                    end else if (j < K) begin
                        i <= 0;
                        j <= j + 1;
                    end else begin
                        state <= DONE_STATE;
                    end
                end
            end

            FINALIZE: begin
                // Update DP table
                if (i > 0) begin
                    candidate1 = dp[i-1][j] + dist_left;
                    if (candidate1 < dp[i][j])
                        dp[i][j] <= candidate1;
                end
                if (j > 0) begin
                    candidate2 = dp[i][j-1] + dist_right;
                    if (candidate2 < dp[i][j])
                        dp[i][j] <= candidate2;
                end

                // Next state
                state <= COMPUTE_DP;

                // Increment counters if needed
                if (i < K) begin
                    i <= i + 1;
                end else begin
                    i <= 0;
                    j <= j + 1;
                end
            end

            DONE_STATE: begin
                result <= dp[K][K];
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module JobScheduler (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] N,
    input wire [15:0] times [0:7],
    output reg [5:0] result,
    output reg done
);

localparam S_IDLE = 0, S_SET_I = 1, S_FIND_J = 2, S_NEXT_L = 3, S_UPDATE_DP = 4;

reg [2:0] state;
reg [2:0] i;
reg [1:0] L_state;
reg [2:0] j;
reg [5:0] dp [0:7];
reg [15:0] time_i;
reg [16:0] add_val;
reg [5:0] candidate_max;
reg [5:0] candidate;
reg [5:0] dp_next;

integer k;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        result <= 0;
        for (k = 0; k < 8; k = k + 1) dp[k] <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= S_SET_I;
                    i <= (N > 0) ? N - 1 : 0;
                    dp_next <= 0;
                end
            end

            S_SET_I: begin
                time_i <= times[i];
                candidate_max <= dp_next;
                L_state <= 0;
                state <= S_FIND_J;
                j <= i + 1;
            end

            S_FIND_J: begin
                add_val <= time_i + (2 + L_state);
                if (j < N && {1'b0, times[j]} >= add_val) begin
                    candidate <= (2 + L_state) + dp[j];
                    state <= S_NEXT_L;
                end else if (j < N) begin
                    j <= j + 1;
                end else begin
                    candidate <= (2 + L_state);
                    state <= S_NEXT_L;
                end
            end

            S_NEXT_L: begin
                if (candidate > candidate_max) candidate_max <= candidate;
                if (L_state == 2) begin
                    dp[i] <= candidate_max;
                    dp_next <= candidate_max;
                    state <= S_UPDATE_DP;
                end else begin
                    L_state <= L_state + 1;
                    j <= i + 1;
                    state <= S_FIND_J;
                end
            end

            S_UPDATE_DP: begin
                if (i == 0) begin
                    result <= candidate_max;
                    done <= 1;
                    state <= S_IDLE;
                end else begin
                    i <= i - 1;
                    state <= S_SET_I;
                end
            end

            default: state <= S_IDLE;
        endcase
    end
end

