    await RisingEdge(dut.clk)
    dut.start.value = 0

def compute_max_cookies(times, durations, N):
    dp = [0] * (N + 1)
    for i in range(N-1, -1, -1):
        max_val = dp[i+1]
        for L in durations:
            j = i+1
            while j < N and times[j] < times[i] + L:
                j += 1
            val = L + dp[j]
            if val > max_val:
                max_val = val
        dp[i] = max_val
    return dp[0]

