        state <= next_state;

        case (state)
            IDLE: begin
                if (start) begin
                    idx <= 0;
                    num_count <= 0;
                    den_count <= 0;
                    error_flag <= 0;
                    proc_idx <= 0;
                    num1_reg <= 0;
                    num2_reg <= 0;
