module data_collection (
  input wire clk,
  input wire rst_n,
  input wire start,
  input wire [63:0] x0, y0, ax, ay, bx, by, xs, ys, t,
  output reg [63:0] result,
  output reg done
);
  parameter MAX_NODES = 100;
  localparam IDLE=0, GENERATE=1, COMPUTE_DIST=2, DOUBLE_LOOP=3, DONE=4;
  reg [2:0] state;
  reg [6:0] node_idx, i, j;
  reg [63:0] x[0:MAX_NODES-1], y[0:MAX_NODES-1];
  reg [63:0] dist_prefix[0:MAX_NODES-1];
  reg [63:0] max_count;

  wire [63:0] abs_x_i = (xs >= x[i]) ? (xs - x[i]) : (x[i] - xs);
  wire [63:0] abs_y_i = (ys >= y[i]) ? (ys - y[i]) : (y[i] - ys);
  wire [63:0] dist_i = abs_x_i + abs_y_i;
  wire [63:0] abs_x_j = (xs >= x[j]) ? (xs - x[j]) : (x[j] - xs);
  wire [63:0] abs_y_j = (ys >= y[j]) ? (ys - y[j]) : (y[j] - ys);
  wire [63:0] dist_j = abs_x_j + abs_y_j;
  wire [63:0] travel = dist_prefix[j] - dist_prefix[i];
  wire [63:0] total1 = dist_i + travel;
  wire [63:0] total2 = dist_j + travel;
  wire condition = (total1 <= t) || (total2 <= t);
  wire [63:0] count = j - i + 1;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      done <= 0;
      result <= 0;
      node_idx <= 0;
      i <= 0;
      j <= 0;
      max_count <= 0;
    end else begin
      case (state)
        IDLE: if (start) begin
          x[0] <= x0;
          y[0] <= y0;
          dist_prefix[0] <= 0;
          node_idx <= 1;
          state <= GENERATE;
          done <= 0;
        end
        GENERATE: if (node_idx < MAX_NODES) begin
          x[node_idx] <= ax * x[node_idx-1] + bx;
          y[node_idx] <= ay * y[node_idx-1] + by;
          state <= COMPUTE_DIST;
        end else begin
          state <= DOUBLE_LOOP;
          i <= 0;
          j <= 0;
          max_count <= 0;
        end
        COMPUTE_DIST: begin
          // Manhattan distance between node_idx-1 and node_idx
          dist_prefix[node_idx] <= dist_prefix[node_idx-1] + 
            ((x[node_idx] >= x[node_idx-1]) ? (x[node_idx] - x[node_idx-1]) : (x[node_idx-1] - x[node_idx])) +
            ((y[node_idx] >= y[node_idx-1]) ? (y[node_idx] - y[node_idx-1]) : (y[node_idx-1] - y[node_idx]));
          node_idx <= node_idx + 1;
          state <= GENERATE;
        end
        DOUBLE_LOOP: begin
          if (condition) 
            max_count <= (count > max_count) ? count : max_count;
          if (j < MAX_NODES-1) 
            j <= j + 1;
          else begin
            j <= i + 1;
            if (i < MAX_NODES-1) 
              i <= i + 1;
            else 
              state <= DONE;
          end
        end
        DONE: begin
          result <= max_count;
          done <= 1;
        end
      endcase
    end
  end
endmodule

module StoneGame(
    input [3:0] n,
    input [31:0] a0, a1, a2, a3, a4, a5, a6, a7,
    output reg win
);
    // Internal array
    wire [31:0] arr [0:7];
    assign arr[0] = a0;
    assign arr[1] = a1;
    assign arr[2] = a2;
    assign arr[3] = a3;
    assign arr[4] = a4;
    assign arr[5] = a5;
    assign arr[6] = a6;
    assign arr[7] = a7;

    // Sorting and processing
    reg [31:0] temp [0:7];
    integer i, j, k;
    reg [31:0] swap;
    reg [2:0] dup_count;
    reg [31:0] dup_value;
    reg triple;
    reg lose_condition;
    reg found_dup_value_minus_one;
    reg [31:0] sum_val;
    reg [31:0] base;
    reg [31:0] S;

    always @(*) begin
        // Initialize with padding
        for (i = 0; i < 8; i = i + 1) begin
            if (i < n)
                temp[i] = arr[i];
            else
                temp[i] = 32'hFFFF_FFFF;
        end

        // Bubble sort
        for (i = 0; i < 8; i = i + 1) begin
            for (j = 0; j < 7 - i; j = j + 1) begin
                if (temp[j] > temp[j+1]) begin
                    swap = temp[j];
                    temp[j] = temp[j+1];
                    temp[j+1] = swap;
                end
            end
        end

        // Duplicate detection
        dup_count = 0;
        dup_value = 0;
        triple = 0;
        lose_condition = 0;

        for (i = 0; i < n-1; i = i + 1) begin
            if (temp[i] == temp[i+1]) begin
                dup_count = dup_count + 1;
                dup_value = temp[i];
                if (i+2 < n && temp[i] == temp[i+2])
                    triple = 1;
            end
        end

        if (triple || dup_count >= 2)
            lose_condition = 1;
        else if (dup_count == 1) begin
            if (dup_value == 0)
                lose_condition = 1;
            else begin
                found_dup_value_minus_one = 0;
                for (k = 0; k < n; k = k + 1) begin
                    if (temp[k] == dup_value - 1)
                        found_dup_value_minus_one = 1;
                end
                if (found_dup_value_minus_one)
                    lose_condition = 1;
            end
        end

        // Parity calculation
        sum_val = 0;
        for (i = 0; i < n; i = i + 1)
            sum_val = sum_val + temp[i];
        base = (n * (n-1)) >> 1;
        S = sum_val - base;

        // Win determination
        win = lose_condition ? 0 : S[0];
    end
endmodule

module dog_show (
    input clk,
    input rst_n,
    input start,
    input [2:0] n,        // number of bowls (1-8)
    input [7:0] T,        // time limit
    input [7:0] t_i [0:7], // array of t_i values
    output reg [3:0] result,
    output reg done
);

// State definitions
localparam IDLE = 4'd0;
localparam PREPROCESS = 4'd1;
localparam SORT_EVENTS = 4'd2;
localparam SWEEP = 4'd3;
localparam DONE = 4'd4;

reg [3:0] state;
reg [2:0] i;          // bowl index
reg [4:0] event_count; // number of events (0-16)
reg [7:0] events_time [0:15];
reg events_is_end [0:15]; // 0=start, 1=end

reg [7:0] counter, max_count;
reg [3:0] j, k;       // sorting indices

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        event_count <= 0;
        counter <= 0;
        max_count <= 0;
        i <= 0;
        j <= 0;
        k <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= PREPROCESS;
                    i <= 0;
                    event_count <= 0;
                end
            end

            PREPROCESS: begin
                if (i < n) begin
                    if (T >= (i + 2)) begin
                        // Compute m = max(0, t_i[i] - i - 1)
                        reg [7:0] m_val;
                        if (t_i[i] > (i + 1)) 
                            m_val = t_i[i] - i - 1;
                        else 
                            m_val = 0;
                        // Compute M = T - i - 2
                        reg [7:0] M_val = T - i - 2;

                        if (m_val <= M_val) begin
                            events_time[event_count] <= m_val;
                            events_is_end[event_count] <= 0;
                            events_time[event_count+1] <= M_val;
                            events_is_end[event_count+1] <= 1;
                            event_count <= event_count + 2;
                        end
                    end
                    i <= i + 1;
                end else begin
                    if (event_count > 0) begin
                        state <= SORT_EVENTS;
                        j <= 0;
                        k <= 0;
                    end else begin
                        state <= DONE;
                        result <= 0;
                    end
                end
            end

            SORT_EVENTS: begin
                if (j < event_count - 1) begin
                    if (k < event_count - j - 1) begin
                        // Compare events[k] and events[k+1]
                        if (events_time[k] > events_time[k+1]) begin
                            // Swap events
                            events_time[k] <= events_time[k+1];
                            events_time[k+1] <= events_time[k];
                            events_is_end[k] <= events_is_end[k+1];
                            events_is_end[k+1] <= events_is_end[k];
                        end else if (events_time[k] == events_time[k+1]) begin
                            if (events_is_end[k] > events_is_end[k+1]) begin
                                events_time[k] <= events_time[k+1];
                                events_time[k+1] <= events_time[k];
                                events_is_end[k] <= events_is_end[k+1];
                                events_is_end[k+1] <= events_is_end[k];
                            end
                        end
                        k <= k + 1;
                    end else begin
                        k <= 0;
                        j <= j + 1;
                    end
                end else begin
                    state <= SWEEP;
                    i <= 0;
                    counter <= 0;
                    max_count <= 0;
                end
            end

            SWEEP: begin
                if (i < event_count) begin
                    if (events_is_end[i] == 0) begin
                        counter <= counter + 1;
                        if (counter + 1 > max_count)
                            max_count <= counter + 1;
                    end else begin
                        counter <= counter - 1;
                    end
                    i <= i + 1;
                end else begin
                    state <= DONE;
                    result <= max_count;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module beautiful_number(
    input clk,
    input rst_n,
    input start,
    input [3:0] n,              // number of digits (1-16)
    input [3:0] k,              // pattern length (1-8)
    input [3:0] digits [0:15],  // input digits (each 0-9)
    output reg [3:0] m,         // output digit count
    output reg [3:0] y_digits [0:15], // output digits
    output reg done
);

// State encoding
localparam IDLE = 3'd0;
localparam INIT = 3'd1;
localparam COMPARE = 3'd2;
localparam INCREMENT = 3'd3;
localparam OUTPUT = 3'd4;
localparam DONE = 3'd5;

reg [2:0] state;
reg [3:0] pattern [0:7];      // First k digits (pattern)
reg [3:0] i, j;               // Counters
reg [3:0] carry;              // For increment
reg [1:0] cmp_flag;           // 0: equal, 1: pattern < input, 2: pattern > input
reg [3:0] pattern_digit;      // Current pattern digit for comparison
reg [3:0] input_digit;        // Current input digit for comparison

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        m <= 0;
        for (i = 0; i < 16; i = i + 1) begin
            y_digits[i] <= 4'd0;
        end
        for (i = 0; i < 8; i = i + 1) begin
            pattern[i] <= 4'd0;
        end
        i <= 4'd0;
        j <= 4'd0;
        carry <= 4'd0;
        cmp_flag <= 2'd0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Initialize: copy first k digits to pattern buffer
                    for (i = 0; i < 8; i = i + 1) begin
                        if (i < k) begin
                            pattern[i] <= digits[i];
                        end else begin
                            pattern[i] <= 4'd0;
                        end
                    end
                    i <= 4'd0;
                    cmp_flag <= 2'd0;
                    state <= INIT;
                    done <= 0;
                end
            end

            INIT: begin
                // Start comparison
                i <= 4'd0;
                state <= COMPARE;
            end

            COMPARE: begin
                // Compare input with pattern repeated
                if (i < n) begin
                    // Get pattern digit for position i
                    if (i < k) begin
                        pattern_digit <= pattern[i];
                    end else begin
                        pattern_digit <= pattern[i - k];
                    end
                    input_digit <= digits[i];

                    // Compare
                    if (cmp_flag == 2'd0) begin
                        if (digits[i] > pattern_digit) begin
                            cmp_flag <= 2'd1;  // Pattern < input
                        end else if (digits[i] < pattern_digit) begin
                            cmp_flag <= 2'd2;  // Pattern > input
                        end
                    end
                    i <= i + 1;
                end else begin
                    // Finished comparison
                    if (cmp_flag == 2'd1) begin  // Pattern < input, need increment
                        i <= k - 1;
                        carry <= 1;
                        state <= INCREMENT;
                    end else begin  // Pattern >= input, can output
                        state <= OUTPUT;
                    end
                end
            end

            INCREMENT: begin
                // Increment the pattern (first k digits)
                if (i < 8 && i >= 0 && carry > 0) begin
                    // Add carry to current digit
                    if (pattern[i] + carry >= 10) begin
                        pattern[i] <= pattern[i] + carry - 10;
                        carry <= 1;
                    end else begin
                        pattern[i] <= pattern[i] + carry;
                        carry <= 0;
                    end

                    if (i == 0 && carry > 0) begin
                        // Overflow: set pattern to 1 followed by k-1 zeros
                        pattern[0] <= 4'd1;
                        for (j = 1; j < 8; j = j + 1) begin
                            if (j < k) begin
                                pattern[j] <= 4'd0;
                            end
                        end
                        state <= OUTPUT;
                    end else if (carry > 0) begin
                        i <= i - 1;
                    end else begin
                        state <= OUTPUT;
                    end
                end else begin
                    state <= OUTPUT;
                end
            end

            OUTPUT: begin
                // Generate output by repeating pattern
                m <= n;
                for (i = 0; i < 16; i = i + 1) begin
                    if (i < n) begin
                        if (i < k) begin
                            y_digits[i] <= pattern[i];
                        end else begin
                            y_digits[i] <= pattern[i - k];
                        end
                    end else begin
                        y_digits[i] <= 4'd0;
                    end
                end
                state <= DONE;
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module election_solver (
  input clk, rst_n, start,
  input [2:0] n, k,
  input [4:0] m, a,
  input [4:0] vote_count [0:7],
  input [4:0] last_vote [0:7],
  output reg [1:0] result [0:7],
  output reg done
);

  function automatic [4:0] compute_cost;
    input [4:0] v_j, v_i, last_j, last_i, a;
    begin
      if (v_j > v_i) 
        compute_cost = 0;
      else if (v_j == v_i) 
        if (last_j < last_i)
          compute_cost = 0;
        else
          compute_cost = 1;
      else begin
        reg [4:0] need1, need2;
        need1 = v_i - v_j + 1;
        if (v_i - v_j == 1 && last_i > a)
          need2 = 1;
        else
          need2 = need1;
        compute_cost = (need1 < need2) ? need1 : need2;
      end
    end
  endfunction

  reg [1:0] next_result [0:7];
  integer i, j, idx, p, q, s;
  reg [4:0] costs [0:6];
  reg [4:0] temp;
  reg [4:0] total_cost;
  reg [4:0] R;
  reg [4:0] count;

  always @(*) begin
    R = m - a;
    for (i=0; i<8; i=i+1) begin
      if (i < n) begin
        idx = 0;
        for (j=0; j<8; j=j+1) begin
          if (j < n && j != i) begin
            costs[idx] = compute_cost(vote_count[j], vote_count[i], last_vote[j], last_vote[i], a);
            idx = idx + 1;
          end
        end
        for (p=0; p<idx-1; p=p+1) begin
          for (q=0; q<idx-1-p; q=q+1) begin
            if (costs[q] > costs[q+1]) begin
              temp = costs[q];
              costs[q] = costs[q+1];
              costs[q+1] = temp;
            end
          end
        end
        total_cost = 0;
        for (s=0; s<k; s=s+1) begin
          if (s < idx)
            total_cost = total_cost + costs[s];
        end
        if (total_cost > R)
          next_result[i] = 1;
        else begin
          if (vote_count[i] + R == 0)
            next_result[i] = 3;
          else begin
            count = 0;
            for (j=0; j<8; j=j+1) begin
              if (j < n && j != i) begin
                if (vote_count[j] > vote_count[i] + R)
                  count = count + 1;
                else if (vote_count[j] == vote_count[i] + R && last_vote[j] < m-1)
                  count = count + 1;
              end
            end
            if (count < k)
              next_result[i] = 2;
            else
              next_result[i] = 3;
          end
        end
      end else begin
        next_result[i] = 0;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result <= 0;
      done <= 0;
    end else begin
      if (start) begin
        result <= next_result;
        done <= 1;
      end else begin
        done <= 0;
      end
    end
  end

endmodule

