module recycling_optimization (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] ax, ay,  // Adil initial position
    input wire [31:0] bx, by,  // Bera initial position  
    input wire [31:0] tx, ty,  // Bin position
    input wire [2:0] num_bottles,  // 1-8 bottles
    input wire [31:0] bottle_x [0:7],  // Bottles x coordinates
    input wire [31:0] bottle_y [0:7],  // Bottles y coordinates
    output reg [63:0] total_distance,  // Q16.16 format
    output reg done
);

// Parameters
parameter MAX_BOTTLES = 8;
parameter MAX_ITER = 64;
parameter DATA_WIDTH = 32;
parameter FP_WIDTH = 64;  // Q16.16

// State machine
reg [2:0] state;
reg [5:0] counter;
reg [2:0] bottle_idx;

// Internal storage for distances
reg [63:0] dist_bin [0:7];    // Distance from bin to each bottle
reg [63:0] dist_adil [0:7];   // Distance from Adil to each bottle  
reg [63:0] dist_bera [0:7];   // Distance from Bera to each bottle
reg [63:0] savings_adil [0:7]; // Savings if Adil picks bottle
reg [63:0] savings_bera [0:7]; // Savings if Bera picks bottle
reg [63:0] best_savings [0:1]; // Top 2 savings for each person
reg [2:0] best_idx [0:1];      // Indices of top savings

// Fixed-point multiplication function
function automatic [63:0] fp_mult;
    input [31:0] a, b;
    reg [63:0] prod;
    begin
        prod = {{32{a[31]}}, a} * {{32{b[31]}}, b};
        fp_mult = prod >>> 16;
    end
endfunction

// Fixed-point square root approximation (using shift-add method)
function automatic [31:0] fp_sqrt;
    input [63:0] n;
    reg [63:0] t, q, b, r;
    integer i;
    begin
        t = 64'h8000000000000000;
        q = 64'h0;
        r = n;
        for (i = 0; i < 32; i = i + 1) begin
            b = q | t;
            q = q >> 1;
            if (r >= b) begin
                r = r - b;
                q = q | t;
            end
            t = t >> 2;
        end
        fp_sqrt = q[31:0];
    end
endfunction

// Distance calculation: sqrt((x1-x2)^2 + (y1-y2)^2) -> Q16.16
function automatic [63:0] calc_distance;
    input [31:0] x1, y1, x2, y2;
    reg [31:0] dx, dy;
    reg [63:0] dx_sq, dy_sq, sum_sq;
    begin
        dx = (x1 > x2) ? (x1 - x2) : (x2 - x1);
        dy = (y1 > y2) ? (y1 - y2) : (y2 - y1);
        dx_sq = fp_mult(dx, dx);
        dy_sq = fp_mult(dy, dy);
        sum_sq = dx_sq + dy_sq;
        calc_distance = fp_sqrt(sum_sq);
    end
endfunction

// Combinational logic for savings calculation
always @(*) begin
    for (integer i = 0; i < MAX_BOTTLES; i = i + 1) begin
        if (i < num_bottles) begin
            // Base cost: 2 * distance from bin to bottle
            // Savings if Adil picks: base_cost - (dist_adil_to_bottle + dist_bin_to_bottle)
            // = dist_bin_to_bottle - dist_adil_to_bottle
            savings_adil[i] = dist_bin[i] - dist_adil[i];
            savings_bera[i] = dist_bin[i] - dist_bera[i];
        end else begin
            savings_adil[i] = 0;
            savings_bera[i] = 0;
        end
    end
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        counter <= 0;
        bottle_idx <= 0;
        total_distance <= 0;
        done <= 0;
        // Reset arrays
        for (integer i = 0; i < MAX_BOTTLES; i = i + 1) begin
            dist_bin[i] <= 0;
            dist_adil[i] <= 0;
            dist_bera[i] <= 0;
            best_idx[i] <= 0;
            best_savings[i] <= 0;
        end
    end else begin
        case (state)
            0: begin  // Idle
                done <= 0;
                if (start) begin
                    state <= 1;
                    counter <= 0;
                    bottle_idx <= 0;
                end
            end

            1: begin  // Calculate distances
                if (counter < num_bottles) begin
                    dist_bin[counter] <= calc_distance(tx, ty, bottle_x[counter], bottle_y[counter]);
                    dist_adil[counter] <= calc_distance(ax, ay, bottle_x[counter], bottle_y[counter]);
                    dist_bera[counter] <= calc_distance(bx, by, bottle_x[counter], bottle_y[counter]);
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= 2;
                end
            end

            2: begin  // Find top 2 savings for Adil
                if (counter < num_bottles) begin
                    if (counter == 0 || savings_adil[counter] > best_savings[0]) begin
                        best_savings[1] <= best_savings[0];
                        best_idx[1] <= best_idx[0];
                        best_savings[0] <= savings_adil[counter];
                        best_idx[0] <= counter;
                    end else if (savings_adil[counter] > best_savings[1]) begin
                        best_savings[1] <= savings_adil[counter];
                        best_idx[1] <= counter;
                    end
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= 3;
                end
            end

            3: begin  // Find top 2 savings for Bera
                if (counter < num_bottles) begin
                    if (counter == 0 || savings_bera[counter] > best_savings[0]) begin
                        best_savings[1] <= best_savings[0];
                        best_idx[1] <= best_idx[0];
                        best_savings[0] <= savings_bera[counter];
                        best_idx[0] <= counter;
                    end else if (savings_bera[counter] > best_savings[1]) begin
                        best_savings[1] <= savings_bera[counter];
                        best_idx[1] <= counter;
                    end
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= 4;
                end
            end

            4: begin  // Calculate result
                // Base cost: 2 * sum of all bin distances
                // Optimal savings: max of single best, or best pair (if different bottles)
                // Total = Base cost - Best Savings
                total_distance <= (2 * dist_bin[0] + 2 * dist_bin[1] + 2 * dist_bin[2] + 2 * dist_bin[3] + 
                                 2 * dist_bin[4] + 2 * dist_bin[5] + 2 * dist_bin[6] + 2 * dist_bin[7]) - 
                                (best_savings[0] + best_savings[1]);
                done <= 1;
                state <= 0;
            end

            default: state <= 0;
        endcase
    end
end

endmodule

module ways_to_choose(
    input [63:0] n,
    input [63:0] k,
    output reg [63:0] result
);

    // Internal variables
    reg [63:0] lower_bound;
    reg [63:0] upper_bound;
    reg [63:0] temp;

    always @(*) begin
        // Compute lower_bound = max(1, k - n)
        if (k > n)
            lower_bound = k - n;
        else
            lower_bound = 64'd1;

        // Compute upper_bound = min(n, (k-1)//2)
        temp = (k - 1) >> 1;
        if (temp < n)
            upper_bound = temp;
        else
            upper_bound = n;

        // Compute result = max(0, upper_bound - lower_bound + 1)
        if (lower_bound <= upper_bound)
            result = upper_bound - lower_bound + 64'd1;
        else
            result = 64'd0;
    end

endmodule

module fib_seq_solver(
    input [19:0] n,  // Unused but included for interface compatibility
    input [19:0] a,
    input [19:0] d,
    output [63:0] b,
    output [63:0] e
);

    // Constants
    wire [63:0] CONST = 368131125;
    wire [63:0] MOD = 1000000000;
    wire [63:0] SCALE = 12000000000;

    // Compute b and e
    assign b = ((CONST * a) % MOD) * SCALE + 1;
    assign e = ((CONST * d) % MOD) * SCALE;

endmodule

module oven_decision (
    input [9:0] n,   // Number of cakes needed (1-1000)
    input [9:0] t,   // Time to bake k cakes (1-1000)
    input [9:0] k,   // Cakes per batch (1-1000)
    input [9:0] d,   // Time to build second oven (1-1000)
    output reg reason // 1 if building oven is reasonable, 0 otherwise
);

    // Calculate number of batches needed: ceil(n/k)
    wire [9:0] batches = (n + k - 1) / k;

    // Calculate threshold time: (batches - 1) * t
    wire [19:0] threshold = (batches - 1) * t;

    // Decision logic: YES if d < threshold
    always @(*) begin
        reason = (d < threshold) ? 1'b1 : 1'b0;
    end

endmodule

module min_cost(
  input clk, rst_n, start,
  input [15:0] a,   // 16-bit binary string (a[0]=first char, a[15]=last char)
  input [31:0] x, y, // Operation costs
  output reg [39:0] result,
  output reg done
);
  // States
  localparam IDLE = 2'b00;
  localparam TRAVERSE = 2'b01;
  localparam COMPUTE = 2'b10;
  localparam FINISH = 2'b11;

  reg [1:0] state, next_state;
  reg [4:0] idx;          // 0-16 counter
  reg [3:0] groups;       // Zero group count (max 16)
  reg prev_bit;           // Previous bit (1 at start)
  reg [31:0] min_val;     // min(x,y)
  reg [3:0] add_count;    // Addition counter
  reg [39:0] accumulator; // Sum accumulator
  reg [39:0] result_reg;  // Registered result
  reg done_reg;

  // State transition
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      done_reg <= 0;
      result_reg <= 0;
    end else begin
      state <= next_state;
      done_reg <= (state == FINISH);
      if (state == COMPUTE && add_count == 0)
        result_reg <= accumulator + y;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = state;
    case (state)
      IDLE: if (start) next_state = TRAVERSE;
      TRAVERSE: if (idx == 16) next_state = (groups == 0) ? FINISH : COMPUTE;
      COMPUTE: if (add_count == 0) next_state = FINISH;
      FINISH: if (!start) next_state = IDLE;
    endcase
  end

  // Datapath
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      idx <= 0;
      groups <= 0;
      prev_bit <= 1;
      min_val <= 0;
      add_count <= 0;
      accumulator <= 0;
    end else begin
      case (state)
        IDLE: begin
          idx <= 0;
          groups <= 0;
          prev_bit <= 1;
        end

        TRAVERSE: begin
          if (idx < 16) begin
            // Count new zero group: current=0 and previous=1
            if (a[idx] == 0 && prev_bit == 1)
              groups <= groups + 1;
            prev_bit <= a[idx];
            idx <= idx + 1;
          end else if (groups > 0) begin
            min_val <= (x < y) ? x : y;
            add_count <= groups - 1;  // Number of additions needed
            accumulator <= 0;
          end
        end

        COMPUTE: begin
          if (add_count > 0) begin
            accumulator <= accumulator + min_val;
            add_count <= add_count - 1;
          end
        end
      endcase
    end
  end

  // Output assignments
  assign result = result_reg;
  assign done = done_reg;
endmodule

module min_time_path (
    input wire clk,              // Clock signal
    input wire rst_n,            // Active-low reset
    input wire start,            // Start computation
    input wire setup_mode,       // Setup mode for volcano input
    input wire volcano_valid,    // Valid volcano coordinate
    input wire [3:0] volcano_x,  // Volcano x-coordinate (0-indexed)
    input wire [3:0] volcano_y,  // Volcano y-coordinate (0-indexed)
    input wire [3:0] n,          // Grid size (1-16)
    output reg done,             // Computation complete
    output reg [7:0] result      // Result: steps or 8'hFF for -1
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam DONE = 2'b10;

    // Registers
    reg [1:0] state_reg;
    reg [3:0] i_reg, j_reg;       // Current cell indices
    reg [15:0] prev_row_reg;      // Previous row of DP
    reg [15:0] curr_row_reg;      // Current row of DP
    reg [15:0] blocked_rows [0:15]; // Blocked grid (16x16)

    // Combinational bit calculation
    wire bit_val;
    assign bit_val = blocked_rows[i_reg][j_reg] ? 0 :
                     (i_reg == 0 && j_reg == 0) ? 1 :
                     ((i_reg > 0 ? prev_row_reg[j_reg] : 0) |
                      (j_reg > 0 ? curr_row_reg[j_reg-1] : 0));

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state_reg <= IDLE;
            done <= 0;
            result <= 0;
            i_reg <= 0;
            j_reg <= 0;
            prev_row_reg <= 0;
            curr_row_reg <= 0;
            // Clear blocked grid
            for (int i = 0; i < 16; i++) 
                blocked_rows[i] <= 16'b0;
        end else begin
            done <= 0;
            case (state_reg)
                IDLE: begin
                    // Handle volcano setup
                    if (setup_mode && volcano_valid) 
                        blocked_rows[volcano_x][volcano_y] <= 1;

                    if (start) begin
                        // Initialize computation
                        i_reg <= 0;
                        j_reg <= 0;
                        prev_row_reg <= 16'b0;
                        curr_row_reg <= 16'b0;
                        state_reg <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    // Update current cell
                    curr_row_reg[j_reg] <= bit_val;

                    // Move to next cell
                    if (j_reg == n-1) begin
                        j_reg <= 0;
                        if (i_reg == n-1) begin
                            // Grid complete
                            state_reg <= DONE;
                            result <= bit_val ? (n-1) << 1 : 8'hFF;
                        end else begin
                            // Next row
                            i_reg <= i_reg + 1;
                            prev_row_reg <= curr_row_reg;
                        end
                    end else begin
                        j_reg <= j_reg + 1;
                    end
                end

                DONE: begin
                    done <= 1;
                    state_reg <= IDLE;
                end
            endcase
        end
    end
endmodule

module optimized_blacklist (
    input clk,
    input rst_n,
    input start,
    input [7:0] addr_i [0:7],
    input [3:0] mask_i [0:7],
    input [7:0] sign_i,
    input [7:0] valid_i,
    output reg [7:0] result_addr [0:7],
    output reg [3:0] result_mask [0:7],
    output reg [3:0] result_count,
    output reg done
);

    // Internal state machine
    reg [2:0] state;
    reg [2:0] next_state;

    // State definitions
    localparam IDLE = 3'd0;
    localparam PARSE = 3'd1;
    localparam CHECK = 3'd2;
    localparam COMPUTE = 3'd3;
    localparam OUTPUT = 3'd4;

    // Storage for parsed intervals
    reg [7:0] black_start [0:7];
    reg [7:0] black_end [0:7];
    reg [7:0] white_start [0:7];
    reg [7:0] white_end [0:7];
    reg [2:0] black_count;
    reg [2:0] white_count;

    // Temporary registers
    reg [7:0] temp_start;
    reg [7:0] temp_end;
    reg [2:0] idx;
    reg conflict;

    // Next state logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // State transition
    always @(*) begin
        case (state)
            IDLE: next_state = start ? PARSE : IDLE;
            PARSE: next_state = (idx == 8) ? CHECK : PARSE;
            CHECK: next_state = conflict ? OUTPUT : COMPUTE;
            COMPUTE: next_state = OUTPUT;
            OUTPUT: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Main logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            black_count <= 0;
            white_count <= 0;
            idx <= 0;
            conflict <= 0;
            result_count <= 0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    idx <= 0;
                    conflict <= 0;
                end

                PARSE: begin
                    if (valid_i[idx]) begin
                        // Parse subnet: a.b.c.d/x format simplified
                        // For 8-bit address: assume /0 to /8
                        if (sign_i[idx] == 0) begin // Black
                            black_start[black_count] <= addr_i[idx] & (8'hFF << (8 - mask_i[idx]));
                            black_end[black_count] <= addr_i[idx] | (8'hFF >> mask_i[idx]);
                            black_count <= black_count + 1;
                        end else begin // White
                            white_start[white_count] <= addr_i[idx] & (8'hFF << (8 - mask_i[idx]));
                            white_end[white_count] <= addr_i[idx] | (8'hFF >> mask_i[idx]);
                            white_count <= white_count + 1;
                        end
                    end
                    idx <= idx + 1;
                end

                CHECK: begin
                    // Simple conflict check: if any black interval overlaps any white interval
                    if (black_count > 0 && white_count > 0) begin
                        for (integer i = 0; i < black_count; i = i + 1) begin
                            for (integer j = 0; j < white_count; j = j + 1) begin
                                if (black_start[i] <= white_end[j] && black_end[i] >= white_start[j]) begin
                                    conflict <= 1;
                                end
                            end
                        end
                    end
                end

                COMPUTE: begin
                    // Simplified: output the first black interval if no conflict
                    if (!conflict && black_count > 0) begin
                        result_addr[0] <= black_start[0];
                        result_mask[0] <= 8 - (black_end[0] - black_start[0] + 1);
                        result_count <= 1;
                    end else if (!conflict) begin
                        // No black intervals, block everything
                        result_addr[0] <= 8'h00;
                        result_mask[0] <= 0;
                        result_count <= 1;
                    end
                    done <= 1;
                end

                OUTPUT: begin
                    done <= 1;
                end
            endcase
        end
    end

endmodule

