always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        index <= 0;
        cnt0 <= 0; cnt1 <= 0; cnt2 <= 0; cnt3 <= 0; cnt4 <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    index <= 0;
                    cnt0 <= 0; cnt1 <= 0; cnt2 <= 0; cnt3 <= 0; cnt4 <= 0;
