                case (index)
                    0: case(arr0) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    1: case(arr1) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    2: case(arr2) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    3: case(arr3) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    4: case(arr4) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    5: case(arr5) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    6: case(arr6) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                    7: begin
                        case(arr7) 0: cnt0<=cnt0+1; 1: cnt1<=cnt1+1; 2: cnt2<=cnt2+1; 3: cnt3<=cnt3+1; 4: cnt4<=cnt4+1; endcase
                        state <= CALC1;
                    end
                endcase
                index <= index + 1;
            end

            CALC1: begin
                reg [7:0] total;
                total = cnt1 + (cnt2<<1) + (cnt3*3) + (cnt4<<2);
                if (total < 3 || total == 5) begin
                    result <= 16'hFFFF;
                    state <= DONE;
                end else begin
                    state <= CALC2;
                end
            end

            CALC2: begin
                reg [15:0] ans;
                reg [3:0] t1, t2, t3, groups, rem;
                if (cnt1 >= cnt2) begin
                    ans = cnt2;
                    t1 = cnt1 - cnt2;
                    t3 = cnt3 + cnt2;
                    groups = t1 / 3;
                    ans = ans + (groups << 1);
                    t3 = t3 + groups;
                    rem = t1 % 3;
                    if (rem == 0) result <= ans;
                    else if (t3 > 0) result <= ans + rem;
                    else result <= ans + 2;
                end else begin
                    ans = cnt1;
                    t2 = cnt2 - cnt1;
                    groups = t2 / 3;
                    ans = ans + (groups << 1);
                    rem = t2 % 3;
                    if (rem == 0) result <= ans;
                    else if (cnt4 > 0) result <= ans + rem;
                    else result <= ans + 2;
                end
                state <= DONE;
            end

            DONE: begin
                done <= 1;
            end
        endcase
    end
end
endmodule

module chocolate_cutting (
    input clk,
    input rst_n,
    input start,
    input [15:0] n,
    input [15:0] m,
    input [15:0] k,
    output reg [31:0] result,
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam CHECK_POSSIBLE = 3'b001;
    localparam COMPUTE_ALPHA = 3'b010;
    localparam COMPUTE_BETA = 3'b011;
    localparam UPDATE_RESULT = 3'b100;
    localparam FINISHED = 3'b101;

    reg [2:0] state;
    reg [31:0] alpha, beta;
    reg [31:0] temp_n, temp_m;
    reg [15:0] cuts_remaining;
    reg [31:0] division_result;
    reg [31:0] multiplication_result;

    // Combinational division and multiplication logic
    always @(*) begin
        if (state == COMPUTE_ALPHA) begin
            if (cuts_remaining >= temp_n) begin
                // alpha = m // (cuts_remaining - temp_n + 2)
                division_result = temp_m / (cuts_remaining - temp_n + 2);
            end else begin
                // alpha = m * (temp_n // (cuts_remaining + 1))
                division_result = temp_m * (temp_n / (cuts_remaining + 1));
            end
        end else if (state == COMPUTE_BETA) begin
            if (cuts_remaining >= temp_m) begin
                // beta = n // (cuts_remaining - temp_m + 2)
                division_result = temp_n / (cuts_remaining - temp_m + 2);
            end else begin
                // beta = n * (m // (cuts_remaining + 1))
                division_result = temp_n * (temp_m / (cuts_remaining + 1));
            end
        end else begin
            division_result = 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            alpha <= 0;
            beta <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= CHECK_POSSIBLE;
                        temp_n <= n;
                        temp_m <= m;
                        cuts_remaining <= k;
                    end
                end

                CHECK_POSSIBLE: begin
                    // Check if k > (n-1) + (m-1)
                    if (k > (n - 1) + (m - 1)) begin
                        result <= 32'hFFFFFFFF; // -1
                        state <= FINISHED;
                    end else begin
                        state <= COMPUTE_ALPHA;
                    end
                end

                COMPUTE_ALPHA: begin
                    alpha <= division_result;
                    state <= COMPUTE_BETA;
                end

                COMPUTE_BETA: begin
                    beta <= division_result;
                    state <= UPDATE_RESULT;
                end

                UPDATE_RESULT: begin
                    if (alpha > beta) begin
                        result <= alpha;
                    end else begin
                        result <= beta;
                    end
                    state <= FINISHED;
                end

                FINISHED: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module find_common_point (
    input clk,
    input rst_n,
    input start,
    input [31:0] x1 [0:15],
    input [31:0] y1 [0:15],
    input [31:0] x2 [0:15],
    input [31:0] y2 [0:15],
    input [7:0] n,
    output reg [31:0] result_x,
    output reg [31:0] result_y,
    output reg done
);

    // State definitions
    localparam IDLE = 2'd0;
    localparam CHECK_ALL = 2'd1;
    localparam CHECK_EXCEPT = 2'd2;

    // Constants
    localparam signed NEG_INF = 32'h80000000;
    localparam signed POS_INF = 32'h7FFFFFFF;

    // Registers
    reg [1:0] state;
    reg [7:0] i, j;
    reg signed [31:0] all_max_x1, all_min_x2, all_max_y1, all_min_y2;
    reg signed [31:0] except_max_x1, except_min_x2, except_max_y1, except_min_y2;

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result_x <= 0;
            result_y <= 0;
            i <= 0;
            j <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        if (n > 1) begin
                            // Initialize for checking all rectangles
                            all_max_x1 <= x1[0];
                            all_min_x2 <= x2[0];
                            all_max_y1 <= y1[0];
                            all_min_y2 <= y2[0];
                            i <= 1;
                            state <= CHECK_ALL;
                        end else begin
                            // For n=1, just output first rectangle's corner
                            result_x <= x1[0];
                            result_y <= y1[0];
                            done <= 1;
                        end
                    end
                end

                CHECK_ALL: begin
                    if (i < n) begin
                        // Update intersection of all rectangles
                        if (x1[i] > all_max_x1) all_max_x1 <= x1[i];
                        if (x2[i] < all_min_x2) all_min_x2 <= x2[i];
                        if (y1[i] > all_max_y1) all_max_y1 <= y1[i];
                        if (y2[i] < all_min_y2) all_min_y2 <= y2[i];
                        i <= i + 1;
                    end else begin
                        // Check if all rectangles intersect
                        if (all_max_x1 <= all_min_x2 && all_max_y1 <= all_min_y2) begin
                            result_x <= all_max_x1;
                            result_y <= all_max_y1;
                            done <= 1;
                            state <= IDLE;
                        end else begin
                            // Start checking by removing each rectangle
                            j <= 0;
                            state <= CHECK_EXCEPT;
                        end
                    end
                end

                CHECK_EXCEPT: begin
                    if (j < n) begin
                        // Initialize intersection except rectangle j
                        except_max_x1 <= NEG_INF;
                        except_min_x2 <= POS_INF;
                        except_max_y1 <= NEG_INF;
                        except_min_y2 <= POS_INF;
                        i <= 0;
                        // Compute intersection of all except j
                        for (integer k = 0; k < 16; k = k + 1) begin
                            if (k != j && k < n) begin
                                if (x1[k] > except_max_x1) except_max_x1 <= x1[k];
                                if (x2[k] < except_min_x2) except_min_x2 <= x2[k];
                                if (y1[k] > except_max_y1) except_max_y1 <= y1[k];
                                if (y2[k] < except_min_y2) except_min_y2 <= y2[k];
                            end
                        end
                        // Check intersection after this cycle
                        if (except_max_x1 <= except_min_x2 && except_max_y1 <= except_min_y2) begin
                            result_x <= except_max_x1;
                            result_y <= except_max_y1;
                            done <= 1;
                            state <= IDLE;
                        end else begin
                            j <= j + 1;
                        end
                    end else begin
                        // Should not happen per problem statement
                        result_x <= 0;
                        result_y <= 0;
                        done <= 1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

module ball_checker (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [5:0] n,           // Number of balls (3-8)
    input wire [63:0] sizes_flat, // 8x8-bit sizes packed [63:0]
    output reg result,
    output reg done
);

    // State definitions
    localparam IDLE = 3'd0;
    localparam CLEAR = 3'd1;
    localparam MARK = 3'd2;
    localparam CHECK = 3'd3;
    localparam DONE = 3'd4;

    // Internal registers
    reg [256:1] present;          // Present array (1-256)
    reg [5:0] n_reg;              // Stored n
    reg [63:0] sizes_flat_reg;    // Stored sizes
    reg [2:0] state;              // State machine
    reg [2:0] i;                  // Index counter (0-7)
    reg [7:0] current_size;       // Current size being processed

    // Combinational check for three consecutive sizes
    wire any_three;
    assign any_three = |(present[1:254] & present[2:255] & present[3:256]);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            present <= 0;
            n_reg <= 0;
            sizes_flat_reg <= 0;
            i <= 0;
            current_size <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        n_reg <= n;
                        sizes_flat_reg <= sizes_flat;
                        state <= CLEAR;
                    end
                end

                CLEAR: begin
                    present <= 0;
                    i <= 0;
                    state <= MARK;
                end

                MARK: begin
                    if (i < n_reg && i < 4'd8) begin
                        // Extract current size (8-bit from flattened array)
                        current_size <= sizes_flat_reg[8*i +: 8];
                        // Only mark valid sizes (1-255)
                        if (sizes_flat_reg[8*i +: 8] >= 8'd1 && 
                            sizes_flat_reg[8*i +: 8] <= 8'd255) begin
                            present[sizes_flat_reg[8*i +: 8]] <= 1;
                        end
                        i <= i + 1;
                    end else begin
                        state <= CHECK;
                    end
                end

                CHECK: begin
                    result <= any_three;
                    done <= 1;
                    state <= DONE;
                end

                DONE: begin
                    done <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module interesting_problemset (
  input [2:0] k,         // Number of teams (1-4)
  input [15:0] presence, // Bit i=1 if mask i exists
  output reg ans         // 1=Valid subset exists
);

always @(*) begin
  // Condition 1: Problem unknown to all teams exists
  if (presence[0]) 
    ans = 1'b1;
  // Condition 2: For k=1, only mask 0 works
  else if (k == 3'b001) 
    ans = 1'b0;
  // Condition 3: Check for disjoint pair
  else begin
    ans = 1'b0;
    for (integer i = 0; i < 16; i = i + 1) begin
      for (integer j = i + 1; j < 16; j = j + 1) begin
        if (presence[i] && presence[j] && ((i & j) == 0))
          ans = 1'b1;
      end
    end
  end
end
endmodule

module longest_alternating_subsequence(
    input [4:0] n,           // String length (1-16)
    input [15:0] s,          // Binary string (s[0] = first character)
    output reg [4:0] result  // Result: min(n, changes + 3)
);

integer i;
reg [4:0] changes;

always @(*) begin
    changes = 0;
    // Count adjacent differences
    for (i = 0; i < 15; i = i + 1) begin
        if (i < n - 1) begin
            if (s[i] != s[i + 1])
                changes = changes + 1;
        end
    end
    // Compute result = min(n, changes + 3)
    if (changes + 3 > n)
        result = n;
    else
        result = changes + 3;
end

endmodule

module arpa_land (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] n,           // Number of people (1-8)
    input wire [2:0] crush_0,     // Crush array (0-indexed)
    input wire [2:0] crush_1,
    input wire [2:0] crush_2,
    input wire [2:0] crush_3,
    input wire [2:0] crush_4,
    input wire [2:0] crush_5,
    input wire [2:0] crush_6,
    input wire [2:0] crush_7,
    output reg [9:0] result,      // LCM result or -1 (10'h3FF)
    output reg done               // Computation finished
);

// State definitions
localparam S_IDLE = 4'd0;
localparam S_INIT = 4'd1;
localparam S_CHECK = 4'd2;
localparam S_TRAVERSE = 4'd3;
localparam S_ADJUST = 4'd4;
localparam S_NEXT = 4'd5;
localparam S_COMPUTE = 4'd6;
localparam S_DONE = 4'd7;
localparam S_ERROR = 4'd8;

// Registers
reg [3:0] state, next_state;
reg [2:0] n_reg;
reg [2:0] crush_reg [0:7];
reg visited [0:7];
reg [2:0] i;                  // Node counter
reg [2:0] current;            // Current node in traversal
reg [2:0] start_node;         // Start node of current cycle
reg [3:0] count;              // Cycle length counter
reg [1:0] max2;               // Max exponent of 2 in adjusted lengths
reg max3, max5, max7;         // Flags for primes
reg error;

// Combinational next_state logic
always @(*) begin
    next_state = state;
    case (state)
        S_IDLE: if (start) next_state = S_INIT;
        S_INIT: next_state = S_CHECK;
        S_CHECK: begin
            if (i < n_reg) begin
                if (!visited[i]) next_state = S_TRAVERSE;
                else next_state = S_NEXT;
            end else begin
                if (error) next_state = S_ERROR;
                else next_state = S_COMPUTE;
            end
        end
        S_TRAVERSE: begin
            if (visited[current]) begin
                if (current == start_node) next_state = S_ADJUST;
                else next_state = S_ERROR;
            end else begin
                next_state = S_TRAVERSE;
            end
        end
        S_ADJUST: next_state = S_NEXT;
        S_NEXT: next_state = S_CHECK;
        S_COMPUTE: next_state = S_DONE;
        S_DONE: next_state = S_DONE;
        S_ERROR: next_state = S_DONE;
        default: next_state = S_IDLE;
    endcase
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        result <= 0;
        n_reg <= 0;
        for (integer idx = 0; idx < 8; idx = idx + 1) begin
            crush_reg[idx] <= 0;
            visited[idx] <= 0;
        end
        i <= 0;
        current <= 0;
        start_node <= 0;
        count <= 0;
        max2 <= 0;
        max3 <= 0;
        max5 <= 0;
        max7 <= 0;
        error <= 0;
    end else begin
        state <= next_state;
        case (state)
            S_IDLE: if (start) begin
                // Latch inputs
                n_reg <= (n > 3'd0 && n <= 3'd8) ? n : 3'd8;
                crush_reg[0] <= crush_0;
                crush_reg[1] <= crush_1;
                crush_reg[2] <= crush_2;
                crush_reg[3] <= crush_3;
                crush_reg[4] <= crush_4;
                crush_reg[5] <= crush_5;
                crush_reg[6] <= crush_6;
                crush_reg[7] <= crush_7;
                // Reset outputs
                done <= 0;
                result <= 0;
                error <= 0;
            end
            S_INIT: begin
                // Initialize visited and factors
                for (integer idx = 0; idx < 8; idx = idx + 1) begin
                    visited[idx] <= (idx < n_reg) ? 0 : 1; // Mark out-of-range as visited
                end
                i <= 0;
                max2 <= 0;
                max3 <= 0;
                max5 <= 0;
                max7 <= 0;
            end
            S_CHECK: begin
                if (i < n_reg && visited[i]) begin
                    i <= i + 1;
                end
            end
            S_TRAVERSE: begin
                if (!visited[current]) begin
                    visited[current] <= 1;
                    current <= crush_reg[current];
                    count <= count + 1;
                end
            end
            S_ADJUST: begin
                // Adjust cycle length
                if (count % 2 == 0) begin
                    count <= count >> 1; // Divide by 2
                end
                // Update factors based on adjusted count
                case (count)
                    1: begin end // Do nothing
                    2: if (max2 < 1) max2 <= 1;
                    3: max3 <= 1;
                    4: if (max2 < 2) max2 <= 2;
                    5: max5 <= 1;
                    7: max7 <= 1;
                    default: error <= 1; // Should not happen
                endcase
                // Reset count and advance i
                count <= 0;
                i <= i + 1;
            end
            S_NEXT: begin
                if (i < n_reg && !visited[i]) begin
                    current <= i;
                    start_node <= i;
                    count <= 0;
                end
            end
            S_COMPUTE: begin
                // Compute LCM = (2^max2) * (3 if max3) * (5 if max5) * (7 if max7)
                result <= (1 << max2) * (max3 ? 3 : 1) * (max5 ? 5 : 1) * (max7 ? 7 : 1);
            end
            S_DONE: begin
                done <= 1;
                if (state == S_ERROR) begin
                    result <= 10'h3FF; // -1 in two's complement
                end
            end
            S_ERROR: begin
                error <= 1;
            end
        endcase
    end
end

endmodule

module spaceship_destroyer (
    input clk, rst_n, start,
    input signed [7:0] group1_0, group1_1,
    input signed [7:0] group2_0, group2_1,
    input [1:0] n, m,
    output reg [7:0] result,
    output reg done
);

// States
parameter IDLE = 2'b00;
parameter PREPARE_SUMS = 2'b01;
parameter ITERATE = 2'b10;
parameter DONE = 2'b11;

// Registers
reg signed [7:0] g1 [0:1];
reg signed [7:0] g2 [0:1];
reg signed [7:0] sums [0:3];
reg [1:0] i, j;
reg [7:0] best;
reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
    end else begin
        case (state)
            IDLE: if (start) begin
                g1[0] <= group1_0;
                g1[1] <= group1_1;
                g2[0] <= group2_0;
                g2[1] <= group2_1;
                state <= PREPARE_SUMS;
                done <= 0;
            end

            PREPARE_SUMS: begin
                // Only compute valid sums based on n and m
                sums[0] <= (n >= 1 && m >= 1) ? g1[0] + g2[0] : 8'sd0;
                sums[1] <= (n >= 1 && m >= 2) ? g1[0] + g2[1] : 8'sd0;
                sums[2] <= (n >= 2 && m >= 1) ? g1[1] + g2[0] : 8'sd0;
                sums[3] <= (n >= 2 && m >= 2) ? g1[1] + g2[1] : 8'sd0;
                i <= 0;
                j <= 0;
                best <= 0;
                state <= ITERATE;
            end

            ITERATE: begin
                // Compute destruction for current pair (i,j)
                // Group1 ship0
                bit0_group1 = (n >= 1) && (
                    (sums[i] - g1[0] == g2[0]) ||
                    (sums[i] - g1[0] == g2[1]) ||
                    (sums[j] - g1[0] == g2[0]) ||
                    (sums[j] - g1[0] == g2[1])
                );
                // Group1 ship1
                bit1_group1 = (n >= 2) && (
                    (sums[i] - g1[1] == g2[0]) ||
                    (sums[i] - g1[1] == g2[1]) ||
                    (sums[j] - g1[1] == g2[0]) ||
                    (sums[j] - g1[1] == g2[1])
                );
                // Group2 ship0
                bit0_group2 = (m >= 1) && (
                    (sums[i] - g2[0] == g1[0]) ||
                    (sums[i] - g2[0] == g1[1]) ||
                    (sums[j] - g2[0] == g1[0]) ||
                    (sums[j] - g2[0] == g1[1])
                );
                // Group2 ship1
                bit1_group2 = (m >= 2) && (
                    (sums[i] - g2[1] == g1[0]) ||
                    (sums[i] - g2[1] == g1[1]) ||
                    (sums[j] - g2[1] == g1[0]) ||
                    (sums[j] - g2[1] == g1[1])
                );

                total = bit0_group1 + bit1_group1 + bit0_group2 + bit1_group2;
                if (total > best) best <= total;

                // Update indices
                if (j < 3) begin
                    j <= j + 1;
                end else begin
                    j <= 0;
                    if (i < 3) begin
                        i <= i + 1;
                    end else begin
                        state <= DONE;
                    end
                end
            end

            DONE: begin
                result <= best;
                done <= 1;
            end
        endcase
    end
end
endmodule

module powers_game(
    input clk,
    input rst_n,
    input start,
    input [9:0] n,
    output reg winner,
    output reg done
);
    // State definitions
    localparam IDLE = 3'b000;
    localparam INIT = 3'b001;
    localparam LOOP = 3'b010;
    localparam CALC_L = 3'b011;
    localparam UPDATE = 3'b100;
    localparam FINAL = 3'b101;

    // Internal registers
    reg [2:0] state;
    reg [9:0] i;              // Current base
    reg [9:0] s;              // Sum of chain lengths
    reg [3:0] ans;            // Current XOR value
    reg [3:0] L;              // Current chain length
    reg [31:0] current_power; // For exponentiation
    reg [3:0] exponent;
    reg [9:0] sqrt_n;         // Precomputed sqrt(n)

    // Lookup table for arr[0:15] (Grundy numbers)
    reg [3:0] arr [0:15];
    initial begin
        arr[0] = 0;
        arr[1] = 1;
        arr[2] = 2;
        arr[3] = 1;
        arr[4] = 4;
        arr[5] = 3;
        arr[6] = 2;
        arr[7] = 1;
        arr[8] = 5;
        arr[9] = 6;
        arr[10] = 2;
        arr[11] = 1;
        arr[12] = 8;
        arr[13] = 7;
        arr[14] = 5;
        arr[15] = 9;
    end

    // Perfect power flags for i=3 to 31
    reg is_perfect [3:31];
    initial begin
        // Initialize all to 0
        for (int idx = 3; idx <= 31; idx++) is_perfect[idx] = 0;
        // Mark perfect powers
        is_perfect[4] = 1;  // 2^2
        is_perfect[8] = 1;  // 2^3
        is_perfect[9] = 1;  // 3^2
        is_perfect[16] = 1; // 2^4
        is_perfect[25] = 1; // 5^2
        is_perfect[27] = 1; // 3^3
        is_perfect[32] = 1; // 2^5 (but i max=31)
        is_perfect[36] = 1; // 6^2
        is_perfect[49] = 1; // 7^2
        is_perfect[64] = 1; // 8^2, 4^3, 2^6
        is_perfect[81] = 1; // 9^2, 3^4
        is_perfect[100] = 1; // 10^2
    end

    // Helper: Find floor of square root
    function [9:0] sqrt;
        input [9:0] x;
        integer i;
        begin
            sqrt = 0;
            for (i = 15; i >= 0; i = i - 1) begin
                if ((sqrt + (1 << i)) * (sqrt + (1 << i)) <= x)
                    sqrt = sqrt + (1 << i);
            end
        end
    endfunction

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            winner <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= INIT;
                    end
                end

                INIT: begin
                    // Compute s0 = floor(log2(n))
                    if (n < 2) begin
                        ans <= arr[0];
                        s <= 0;
                    end else begin
                        // Priority encoder for highest bit
                        if (n[9]) ans <= arr[9];
                        else if (n[8]) ans <= arr[8];
                        else if (n[7]) ans <= arr[7];
                        else if (n[6]) ans <= arr[6];
                        else if (n[5]) ans <= arr[5];
                        else if (n[4]) ans <= arr[4];
                        else if (n[3]) ans <= arr[3];
                        else if (n[2]) ans <= arr[2];
                        else if (n[1]) ans <= arr[1];
                        else ans <= arr[0];
                        s <= (n[9]?9:(n[8]?8:(n[7]?7:(n[6]?6:(n[5]?5:(n[4]?4:(n[3]?3:(n[2]?2:(n[1]?1:0))))))));
                    end
                    i <= 3;
                    sqrt_n <= sqrt(n);
                    state <= LOOP;
                end

                LOOP: begin
                    if (i > sqrt_n) begin
                        state <= FINAL;
                    end else if (i <= 31 && is_perfect[i]) begin
                        i <= i + 1;
                    end else begin
                        L <= 0;
                        current_power <= 1;
                        exponent <= 0;
                        state <= CALC_L;
                    end
                end

                CALC_L: begin
                    // Compute current_power = i^(exponent+1)
                    if (exponent == 0) begin
                        current_power <= i;
                    end else begin
                        current_power <= current_power * i;
                    end
                    // Check after one cycle delay
                    if (exponent > 0 && current_power > n) begin
                        // If current_power (i^exponent) > n, then L is exponent-1
                        L <= exponent - 1;
                        state <= UPDATE;
                    end else if (exponent > 0 && current_power <= n) begin
                        L <= exponent;
                    end
                    exponent <= exponent + 1;
                    // Terminate if exponent too large or power exceeds n
                    if (exponent >= 10 || (exponent > 0 && current_power > n)) begin
                        state <= UPDATE;
                    end
                end

                UPDATE: begin
                    if (L >= 1 && L <= 15) begin
                        ans <= ans ^ arr[L];
                        s <= s + L;
                    end
                    i <= i + 1;
                    state <= LOOP;
                end

                FINAL: begin
                    // ans = ans XOR ((n - s) % 2)
                    if ((n - s) & 1) ans <= ans ^ 1;
                    // winner = 1 if ans != 0
                    winner <= (ans != 0);
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module snuke_string_counter (
    input clk,
    input rst_n,
    input start,
    input [3:0] N,      // N in [2,16] (4-bit)
    input c_AA,         // 0=A, 1=B
    input c_AB,
    input c_BA,
    input c_BB,
    output reg [29:0] result,
    output reg done
);

    // States
    localparam IDLE = 3'b000;
    localparam DECODE = 3'b001;
    localparam COMPUTE_POWER = 3'b010;
    localparam COMPUTE_FIB = 3'b011;
    localparam DONE = 3'b100;

    reg [2:0] state;
    reg [3:0] N_reg;    // Store N
    reg [3:0] rule;     // {c_AA, c_AB, c_BA, c_BB}
    reg [1:0] rule_type; // 00: type1, 01: type2, 10: type3

    // Power computation registers
    reg [29:0] base;
    reg [3:0] count_power; // counts from 0 to N-3
    wire [3:0] max_power = N_reg - 3;
    localparam [29:0] MOD = 30'd1000000007;

    // Fibonacci computation registers
    reg [29:0] a, b, c;
    reg [3:0] count_fib;   // counts from 4 to N

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 30'd0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        N_reg <= N;
                        rule <= {c_AA, c_AB, c_BA, c_BB};
                        state <= DECODE;
                    end
                end

                DECODE: begin
                    // Determine rule type
                    case (rule)
                        // Type 1: Always 1
                        4'b0000, 4'b0001, 4'b0010, 4'b0011, 
                        4'b0101, 4'b0111, 4'b1101, 4'b1111: 
                            rule_type <= 2'b00;
                        // Type 2: 2^(N-3)
                        4'b0100, 4'b1010, 4'b1011, 4'b1100:
                            rule_type <= 2'b01;
                        // Type 3: Fibonacci
                        4'b0110, 4'b1000, 4'b1001, 4'b1110:
                            rule_type <= 2'b10;
                        default: 
                            rule_type <= 2'b00;
                    endcase

                    // Trivial cases
                    if (rule_type == 2'b00) begin
                        result <= 30'd1;
                        state <= DONE;
                    end else if (rule_type == 2'b01) begin
                        if (N_reg <= 3'd3) begin
                            result <= 30'd1;
                            state <= DONE;
                        end else begin
                            base <= 30'd1;
                            count_power <= 4'd0;
                            state <= COMPUTE_POWER;
                        end
                    end else begin
                        if (N_reg <= 3'd3) begin
                            result <= 30'd1;
                            state <= DONE;
                        end else begin
                            a <= 30'd1;
                            b <= 30'd1;
                            count_fib <= 4'd4;
                            state <= COMPUTE_FIB;
                        end
                    end
                end

                COMPUTE_POWER: begin
                    if (count_power < max_power) begin
                        // Multiply by 2 modulo MOD
                        base <= (base << 1) % MOD;
                        count_power <= count_power + 1;
                    end else begin
                        result <= base;
                        state <= DONE;
                    end
                end

                COMPUTE_FIB: begin
                    if (count_fib <= N_reg) begin
                        c <= (a + b) % MOD;
                        a <= b;
                        b <= c;
                        count_fib <= count_fib + 1;
                    end else begin
                        result <= b;
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1'b1;
                    if (!start) begin
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module longest_subsegment (
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    input [3:0] len,
    output reg [7:0] result,
    output reg done
);
    // Parameters
    parameter N = 8;
    parameter IDLE = 4'd0;
    parameter CAPTURE = 4'd1;
    parameter COMPUTE_LEFT = 4'd2;
    parameter COMPUTE_RIGHT = 4'd3;
    parameter COMPUTE_ANSWER = 4'd4;
    parameter DONE = 4'd5;

    // Internal registers
    reg [7:0] arr_reg [0:N-1];
    reg [3:0] left [0:N-1];
    reg [3:0] right [0:N-1];
    reg [7:0] ans;
    reg [3:0] state;
    reg [3:0] i;
    reg [3:0] len_reg;

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            ans <= 0;
            i <= 0;
            len_reg <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= CAPTURE;
                        i <= 0;
                        ans <= 0;
                        len_reg <= (len > N) ? N : len; // Clamp to N
                    end
                end

                CAPTURE: begin
                    // Capture input array
                    if (i < len_reg) begin
                        case (i)
                            0: arr_reg[0] <= arr_0;
                            1: arr_reg[1] <= arr_1;
                            2: arr_reg[2] <= arr_2;
                            3: arr_reg[3] <= arr_3;
                            4: arr_reg[4] <= arr_4;
                            5: arr_reg[5] <= arr_5;
                            6: arr_reg[6] <= arr_6;
                            7: arr_reg[7] <= arr_7;
                        endcase
                        i <= i + 1;
                    end else begin
                        i <= 0;
                        if (len_reg > 0) begin
                            state <= COMPUTE_LEFT;
                        end else begin
                            state <= DONE;
                        end
                    end
                end

                COMPUTE_LEFT: begin
                    if (i < len_reg) begin
                        if (i == 0) begin
                            left[0] <= 1;
                            if (1 > ans) ans <= 1;
                        end else begin
                            if (arr_reg[i] > arr_reg[i-1]) begin
                                left[i] <= left[i-1] + 1;
                                if (left[i-1] + 1 > ans) ans <= left[i-1] + 1;
                            end else begin
                                left[i] <= 1;
                                if (1 > ans) ans <= 1;
                            end
                        end
                        i <= i + 1;
                    end else begin
                        i <= len_reg - 1;
                        state <= COMPUTE_RIGHT;
                    end
                end

                COMPUTE_RIGHT: begin
                    if (i >= 0 && i < len_reg) begin
                        if (i == len_reg - 1) begin
                            right[i] <= 1;
                        end else begin
                            if (arr_reg[i] < arr_reg[i+1]) begin
                                right[i] <= right[i+1] + 1;
                            end else begin
                                right[i] <= 1;
                            end
                        end
                        if (i == 0) begin
                            i <= len_reg; // Done
                        end else begin
                            i <= i - 1;
                        end
                    end else begin
                        i <= 0;
                        state <= COMPUTE_ANSWER;
                    end
                end

                COMPUTE_ANSWER: begin
                    if (i < len_reg) begin
                        // Check left extension (change element after left segment)
                        if (i > 0) begin
                            if (left[i-1] + 1 > ans) ans <= left[i-1] + 1;
                        end
                        // Check right extension (change element before right segment)
                        if (i < len_reg - 1) begin
                            if (right[i+1] + 1 > ans) ans <= right[i+1] + 1;
                        end
                        // Check merge
                        if (i > 0 && i < len_reg - 1) begin
                            // Check if there exists a value between arr[i-1] and arr[i+1]
                            if (arr_reg[i-1] + 1 < arr_reg[i+1]) begin
                                if (left[i-1] + 1 + right[i+1] > ans) ans <= left[i-1] + 1 + right[i+1];
                            end
                        end
                        i <= i + 1;
                    end else begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    result <= ans;
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module beautiful_sequence(
    input clk,
    input rst_n,
    input start,
    input [7:0] a,  // count of 0s
    input [7:0] b,  // count of 1s
    input [7:0] c,  // count of 2s
    input [7:0] d,  // count of 3s
    output reg [7:0] seq_out [0:31],  // output sequence (max 32 elements)
    output reg [5:0] seq_len,          // length of output sequence
    output reg done
);

// Internal state
reg [7:0] counts [0:3];  // counts for 0,1,2,3
reg [7:0] temp_counts [0:3];  // temporary copy for simulation
reg [2:0] current_start;  // current starting point
reg [5:0] idx;            // index in sequence
reg [2:0] current_num;    // current number in sequence
reg [2:0] next_num;       // next number to try
reg [1:0] state;          // state machine: 0=idle, 1=run, 2=check, 3=done
reg [2:0] attempts;       // which start we are trying

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 0;
        state <= 0;
        seq_len <= 0;
        attempts <= 0;
    end else begin
        case (state)
            0: begin  // idle
                if (start) begin
                    // Initialize counts
                    counts[0] <= a;
                    counts[1] <= b;
                    counts[2] <= c;
                    counts[3] <= d;
                    attempts <= 0;
                    state <= 1;
                    done <= 0;
                end
            end

            1: begin  // try next starting point
                if (attempts < 4) begin
                    if (counts[attempts] > 0) begin
                        // Make copy of counts
                        temp_counts[0] <= counts[0];
                        temp_counts[1] <= counts[1];
                        temp_counts[2] <= counts[2];
                        temp_counts[3] <= counts[3];
                        current_start <= attempts;
                        current_num <= attempts;
                        idx <= 0;
                        seq_out[0] <= attempts;
                        temp_counts[attempts] <= temp_counts[attempts] - 1;
                        state <= 2;
                    end else begin
                        attempts <= attempts + 1;
                    end
                end else begin
                    // All attempts failed
                    state <= 3;
                    done <= 1;
                end
            end

            2: begin  // run sequence construction
                if (idx < 31) begin
                    // Find next number
                    case (current_num)
                        0: begin
                            if (temp_counts[1] > 0) begin
                                next_num <= 1;
                                temp_counts[1] <= temp_counts[1] - 1;
                                idx <= idx + 1;
                                seq_out[idx + 1] <= 1;
                                current_num <= 1;
                            end else begin
                                // Cannot continue
                                state <= 1;  // try next start
                                attempts <= attempts + 1;
                            end
                        end
                        1: begin
                            if (temp_counts[0] > 0) begin
                                next_num <= 0;
                                temp_counts[0] <= temp_counts[0] - 1;
                                idx <= idx + 1;
                                seq_out[idx + 1] <= 0;
                                current_num <= 0;
                            end else if (temp_counts[2] > 0) begin
                                next_num <= 2;
                                temp_counts[2] <= temp_counts[2] - 1;
                                idx <= idx + 1;
                                seq_out[idx + 1] <= 2;
                                current_num <= 2;
                            end else begin
                                state <= 1;
                                attempts <= attempts + 1;
                            end
                        end
                        2: begin
                            if (temp_counts[3] > 0) begin
                                next_num <= 3;
                                temp_counts[3] <= temp_counts[3] - 1;
                                idx <= idx + 1;
                                seq_out[idx + 1] <= 3;
                                current_num <= 3;
                            end else if (temp_counts[1] > 0) begin
                                next_num <= 1;
                                temp_counts[1] <= temp_counts[1] - 1;
                                idx <= idx + 1;
                                seq_out[idx + 1] <= 1;
                                current_num <= 1;
                            end else begin
                                state <= 1;
                                attempts <= attempts + 1;
                            end
                        end
                        3: begin
                            if (temp_counts[2] > 0) begin
                                next_num <= 2;
                                temp_counts[2] <= temp_counts[2] - 1;
                                idx <= idx + 1;
                                seq_out[idx + 1] <= 2;
                                current_num <= 2;
                            end else begin
                                state <= 1;
                                attempts <= attempts + 1;
                            end
                        end
                    endcase
                end else begin
                    // Sequence too long
                    state <= 1;
                    attempts <= attempts + 1;
                end

                // Check if all used
                if (temp_counts[0] == 0 && temp_counts[1] == 0 && 
                    temp_counts[2] == 0 && temp_counts[3] == 0) begin
                    seq_len <= idx + 1;
                    state <= 3;
                    done <= 1;
                end
            end

            3: begin  // done
                // Stay in done state
            end
        endcase
    end
end

endmodule

module day_checker (
    input clk,
    input rst_n,
    input start,
    input [2:0] day1,  // 0=Monday, 1=Tuesday, ..., 6=Sunday
    input [2:0] day2,
    output reg result,
    output reg done
);

// States
reg [1:0] state;

// Internal registers
reg [2:0] diff;

// State definitions
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam COMPLETE = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 0;
        done <= 0;
        diff <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= COMPUTE;
                    // Calculate difference modulo 7
                    diff <= (day2 - day1 + 7) % 7;
                end
            end
            COMPUTE: begin
                // Check if difference is 0, 2, or 3
                if (diff == 3'd0 || diff == 3'd2 || diff == 3'd3) begin
                    result <= 1;
                end else begin
                    result <= 0;
                end
                state <= COMPLETE;
            end
            COMPLETE: begin
                done <= 1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

module prob_calc(
    input [7:0] f,
    input [7:0] w,
    input [7:0] h,
    output reg [31:0] p
);

    localparam MOD = 1000000007;
    localparam MAX_N = 16;

    // Binomial coefficient table: C[n][k]
    reg [15:0] C [0:MAX_N][0:MAX_N];

    // Initialize C using Pascal's triangle
    integer i, j;
    initial begin
        // Initialize all to 0
        for (i = 0; i <= MAX_N; i = i + 1) begin
            for (j = 0; j <= MAX_N; j = j + 1) begin
                C[i][j] = 0;
            end
        end
        // Compute Pascal's triangle
        for (i = 0; i <= MAX_N; i = i + 1) begin
            C[i][0] = 1;
            C[i][i] = 1;
            for (j = 1; j < i; j = j + 1) begin
                C[i][j] = C[i-1][j-1] + C[i-1][j];
            end
        end
    end

    // Function to lookup modular inverse (precomputed for possible totals)
    function [31:0] inv_lookup;
        input [15:0] total;
        begin
            case(total)
                1: inv_lookup = 1;
                2: inv_lookup = 500000004;
                3: inv_lookup = 333333336;
                6: inv_lookup = 166666668;
                20: inv_lookup = 850000006;
                default: inv_lookup = 0;
            endcase
        end
    endfunction

    // Combinational logic
    reg [15:0] total, liked;
    reg [15:0] kmax;
    reg [15:0] term1, term2;
    reg [15:0] n2, r2;
    reg [15:0] k;
    reg [31:0] inv_total;

    always @(*) begin
        // Compute total = C[f+w][w]
        total = C[f + w][w];

        // Compute liked
        if (w == 0) begin
            liked = 1;
        end else begin
            liked = 0;
            // Compute kmax = min(w / (h+1), f+1)
            if (h == 8'hFF) begin
                kmax = 0;
            end else begin
                kmax = w / (h + 1);
            end
            if (kmax > f + 1) kmax = f + 1;

            for (k = 1; k <= kmax; k = k + 1) begin
                term1 = C[f + 1][k];
                n2 = w - k * h - 1;
                r2 = k - 1;
                if (n2 >= r2 && r2 >= 0) begin
                    term2 = C[n2][r2];
                end else begin
                    term2 = 0;
                end
                liked = liked + term1 * term2;
            end
        end

        // Lookup inverse
        inv_total = inv_lookup(total);

        // Compute result
        p = (liked * inv_total) % MOD;
    end

endmodule

module mirror_checker(
    input clk,
    input rst_n,
    input start,
    input [127:0] string_in,   // 16 characters packed: char0 at [7:0], char1 at [15:8], ... char15 at [127:120]
    input [4:0] len,           // actual string length (1-16)
    output reg result,
    output reg done
);
    // State definitions
    localparam IDLE = 2'b00;
    localparam CHECK = 2'b01;
    localparam DONE = 2'b10;

    // Registers
    reg [1:0] state, next_state;
    reg [3:0] i, next_i;         // loop counter (0-15)
    reg next_result;

    // Helper function to check if char is mirror-symmetric
    function is_in_set;
        input [7:0] char;
        begin
            case(char)
                8'h41, 8'h48, 8'h49, 8'h4D, 8'h4F, 
                8'h54, 8'h55, 8'h56, 8'h57, 8'h58, 
                8'h59: is_in_set = 1'b1;  // A,H,I,M,O,T,U,V,W,X,Y
                default: is_in_set = 1'b0;
            endcase
        end
    endfunction

    // Combinational next state logic
    always @(*) begin
        // Defaults
        next_state = state;
        next_i = i;
        next_result = result;
        next_done = 1'b0;

        case(state)
            IDLE: begin
                if(start) begin
                    next_state = CHECK;
                    next_i = 0;
                    next_result = 1;  // Assume pass until fail
                end
            end

            CHECK: begin
                // Compute half of (len-1) for comparison
                if(i > ((len-1) >> 1)) begin
                    // Finished all pairs without failure
                    next_state = DONE;
                    next_done = 1'b1;
                end else begin
                    // Extract characters
                    char_i = string_in[i*8 +: 8];
                    char_j = string_in[(len-1-i)*8 +: 8];

                    // Check conditions
                    if(!is_in_set(char_i)) begin
                        next_result = 0;
                        next_state = DONE;
                        next_done = 1'b1;
                    end else if(i != (len-1-i)) begin
                        if(!is_in_set(char_j) || (char_i != char_j)) begin
                            next_result = 0;
                            next_state = DONE;
                            next_done = 1'b1;
                        end else begin
                            next_i = i + 1;
                        end
                    end else begin
                        // Middle character (i == j), already checked set condition
                        next_i = i + 1;
                    end
                end
            end

            DONE: begin
                next_state = IDLE;
                next_done = 1'b0;
            end

            default: begin
                next_state = IDLE;
                next_i = 0;
                next_result = 0;
            end
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            state <= IDLE;
            i <= 0;
            result <= 0;
            done <= 0;
        end else begin
            state <= next_state;
            i <= next_i;
            result <= next_result;
            done <= next_done;
        end
    end
endmodule

module sound_compression (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] n,           // Number of elements (1-16)
    input wire [31:0] I,          // Disk size in bytes
    input wire [31:0] data_in,    // Single data input (sequential)
    output reg [7:0] result,      // Minimal number of changed elements
    output reg done               // Computation complete
);

// Fixed-point arithmetic parameters
parameter FRAC_BITS = 8;
parameter MAX_N = 16;

// State machine states
parameter IDLE = 0,
          LOAD = 1,
          SORT = 2,
          COUNT = 3,
          CALCULATE = 4,
          SLIDE = 5,
          DONE = 6;

reg [3:0] state;
reg [4:0] counter;           // General purpose counter
reg [4:0] write_ptr;         // Array write pointer
reg [31:0] array [0:15];     // Input array storage
reg [31:0] sorted [0:15];    // Sorted array
reg [4:0] distinct_count;    // Number of distinct values
reg [3:0] freq [0:15];       // Frequency of each distinct value
reg [7:0] k_max;             // Maximum bits per element
reg [4:0] window_size;       // Window size for sliding
reg [7:0] max_sum;           // Maximum sum in window
reg [7:0] current_sum;       // Current window sum
reg [4:0] window_start;      // Window start index

// Intermediate calculations
reg [31:0] bits_per_element; // I*8/n in Q8.8 format
reg [31:0] temp_dividend;
reg [7:0] temp_quotient;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        counter <= 0;
        write_ptr <= 0;
        distinct_count <= 0;
        k_max <= 0;
        window_size <= 0;
        max_sum <= 0;
        current_sum <= 0;
        window_start <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= LOAD;
                    counter <= 0;
                    write_ptr <= 0;
                end
            end

            LOAD: begin
                // Load data sequentially (one per cycle)
                if (counter < n && counter < MAX_N) begin
                    array[counter] <= data_in;
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= SORT;
                    // Initialize sorted array
                    for (integer i = 0; i < MAX_N; i = i + 1) begin
                        sorted[i] <= array[i];
                    end
                end
            end

            SORT: begin
                // Bubble sort (hardware-friendly, fixed iterations)
                if (counter < n - 1) begin
                    for (integer i = 0; i < n - 1 - counter; i = i + 1) begin
                        if (sorted[i] > sorted[i+1]) begin
                            sorted[i] <= sorted[i+1];
                            sorted[i+1] <= sorted[i];
                        end
                    end
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= COUNT;
                    distinct_count <= 0;
                end
            end

            COUNT: begin
                // Count distinct values and their frequencies
                if (counter < n) begin
                    if (counter == 0 || sorted[counter] != sorted[counter-1]) begin
                        // New distinct value
                        if (distinct_count < MAX_N) begin
                            freq[distinct_count] <= 1;
                            distinct_count <= distinct_count + 1;
                        end
                    end else begin
                        // Same as previous
                        freq[distinct_count-1] <= freq[distinct_count-1] + 1;
                    end
                    counter <= counter + 1;
                end else begin
                    counter <= 0;
                    state <= CALCULATE;
                    // Calculate bits per element: I*8/n
                    // Using Q8.8 fixed-point (8 integer, 8 fractional bits)
                    temp_dividend <= (I * 8) << FRAC_BITS; // Q8.8 format
                    temp_quotient <= 0;
                end
            end

            CALCULATE: begin
                // Fixed-point division: (I*8)/n
                if (temp_dividend >= (n << FRAC_BITS)) begin
                    temp_dividend <= temp_dividend - (n << FRAC_BITS);
                    temp_quotient <= temp_quotient + 1;
                end else begin
                    // Convert back to integer, cap at 30
                    if (temp_quotient[15:8] >= 20) begin // Check integer part
                        k_max <= 16; // Cap to avoid overflow
                    end else begin
                        k_max <= temp_quotient[15:8]; // Integer part only
                    end
                    window_size <= 1 << temp_quotient[15:8];
                    state <= SLIDE;
                    counter <= 0;
                    max_sum <= 0;
                    current_sum <= 0;
                    window_start <= 0;
                end
            end

            SLIDE: begin
                // Sliding window over frequencies
                if (window_start + window_size <= distinct_count) begin
                    // Calculate sum for current window
                    current_sum <= 0;
                    for (integer i = 0; i < window_size; i = i + 1) begin
                        current_sum <= current_sum + freq[window_start + i];
                    end
                    // Update max sum
                    if (current_sum > max_sum) begin
                        max_sum <= current_sum;
                    end
                    window_start <= window_start + 1;
                end else begin
                    // Final calculation
                    if (k_max >= 20 || window_size >= distinct_count) begin
                        result <= 0; // No compression needed
                    end else begin
                        result <= n - max_sum;
                    end
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module steward_support (
    input clk,
    input rst_n,
    input start,
    input [2:0] n,              // Number of stewards (1-8)
    input [7:0] arr_0,          // Array elements
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    output reg [3:0] result,    // Count of supported stewards
    output reg done
);

    // Internal state
    reg [2:0] idx;
    reg [7:0] min_val;
    reg [7:0] max_val;
    reg [3:0] count;
    reg [1:0] state;

    // State definitions
    localparam IDLE = 2'b00;
    localparam FIND_MIN_MAX = 2'b01;
    localparam COUNT_SUPPORT = 2'b10;
    localparam FINISHED = 2'b11;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state <= IDLE;
            done <= 0;
            result <= 0;
            idx <= 0;
            min_val <= 0;
            max_val <= 0;
            count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        if (n < 3'd2) begin
                            // Less than 2 stewards - impossible to support anyone
                            result <= 0;
                            done <= 1;
                            state <= FINISHED;
                        end else begin
                            // Initialize for finding min/max
                            idx <= 3'd1;
                            case (n)
                                3'd2: begin
                                    min_val <= (arr_0 < arr_1) ? arr_0 : arr_1;
                                    max_val <= (arr_0 > arr_1) ? arr_0 : arr_1;
                                end
                                3'd3: begin
                                    min_val <= (((arr_0 < arr_1) && (arr_0 < arr_2)) || ((arr_0 < arr_1) && (arr_0 >= arr_2)) || ((arr_0 >= arr_1) && (arr_0 < arr_2))) ? arr_0 : ((arr_1 < arr_2) ? arr_1 : arr_2);
                                    max_val <= (((arr_0 > arr_1) && (arr_0 > arr_2)) || ((arr_0 > arr_1) && (arr_0 <= arr_2)) || ((arr_0 <= arr_1) && (arr_0 > arr_2))) ? arr_0 : ((arr_1 > arr_2) ? arr_1 : arr_2);
                                end
                                default: begin
                                    min_val <= arr_0;
                                    max_val <= arr_0;
                                end
                            endcase
                            state <= FIND_MIN_MAX;
                        end
                    end
                end

                FIND_MIN_MAX: begin
                    if (idx < n) begin
                        // Update min and max based on current element
                        case (idx)
                            3'd1: begin
                                if (arr_1 < min_val) min_val <= arr_1;
                                if (arr_1 > max_val) max_val <= arr_1;
                            end
                            3'd2: begin
                                if (arr_2 < min_val) min_val <= arr_2;
                                if (arr_2 > max_val) max_val <= arr_2;
                            end
                            3'd3: begin
                                if (arr_3 < min_val) min_val <= arr_3;
                                if (arr_3 > max_val) max_val <= arr_3;
                            end
                            3'd4: begin
                                if (arr_4 < min_val) min_val <= arr_4;
                                if (arr_4 > max_val) max_val <= arr_4;
                            end
                            3'd5: begin
                                if (arr_5 < min_val) min_val <= arr_5;
                                if (arr_5 > max_val) max_val <= arr_5;
                            end
                            3'd6: begin
                                if (arr_6 < min_val) min_val <= arr_6;
                                if (arr_6 > max_val) max_val <= arr_6;
                            end
                            3'd7: begin
                                if (arr_7 < min_val) min_val <= arr_7;
                                if (arr_7 > max_val) max_val <= arr_7;
                            end
                        endcase
                        idx <= idx + 1;
                    end else begin
                        // Finished finding min/max
                        if (min_val == max_val) begin
                            // All stewards have same strength - none supported
                            result <= 0;
                            done <= 1;
                            state <= FINISHED;
                        end else begin
                            // Initialize for counting supported stewards
                            idx <= 0;
                            count <= 0;
                            state <= COUNT_SUPPORT;
                        end
                    end
                end

                COUNT_SUPPORT: begin
                    if (idx < n) begin
                        // Check if current element is strictly between min and max
                        case (idx)
                            3'd0: if (arr_0 > min_val && arr_0 < max_val) count <= count + 1;
                            3'd1: if (arr_1 > min_val && arr_1 < max_val) count <= count + 1;
                            3'd2: if (arr_2 > min_val && arr_2 < max_val) count <= count + 1;
                            3'd3: if (arr_3 > min_val && arr_3 < max_val) count <= count + 1;
                            3'd4: if (arr_4 > min_val && arr_4 < max_val) count <= count + 1;
                            3'd5: if (arr_5 > min_val && arr_5 < max_val) count <= count + 1;
                            3'd6: if (arr_6 > min_val && arr_6 < max_val) count <= count + 1;
                            3'd7: if (arr_7 > min_val && arr_7 < max_val) count <= count + 1;
                        endcase
                        idx <= idx + 1;
                    end else begin
                        // Finished counting
                        result <= count;
                        done <= 1;
                        state <= FINISHED;
                    end
                end

                FINISHED: begin
                    done <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module digit_sum_opt (
    input [63:0] n,
    output reg [8:0] result
);

    reg [63:0] a;
    reg [63:0] b;
    reg [8:0] sum_a, sum_b;
    reg [63:0] temp;
    integer i;

    always @(*) begin
        // Determine a based on n
        if (n < 10) a = 0;
        else if (n < 100) a = 9;
        else if (n < 1000) a = 99;
        else if (n < 10000) a = 999;
        else if (n < 100000) a = 9999;
        else if (n < 1000000) a = 99999;
        else if (n < 10000000) a = 999999;
        else if (n < 100000000) a = 9999999;
        else if (n < 1000000000) a = 99999999;
        else if (n < 10000000000) a = 999999999;
        else if (n < 100000000000) a = 9999999999;
        else if (n < 1000000000000) a = 99999999999;
        else a = 999999999999;

        b = n - a;

        // Compute digit sum for a
        sum_a = 0;
        temp = a;
        for (i = 0; i < 15; i = i + 1) begin
            if (temp != 0) begin
                sum_a = sum_a + temp % 10;
                temp = temp / 10;
            end
        end

        // Compute digit sum for b
        sum_b = 0;
        temp = b;
        for (i = 0; i < 15; i = i + 1) begin
            if (temp != 0) begin
                sum_b = sum_b + temp % 10;
                temp = temp / 10;
            end
        end

        result = sum_a + sum_b;
    end

endmodule

