module robot_reach (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char,
    input wire char_valid,
    input wire [6:0] len,
    input wire signed [31:0] a,
    input wire signed [31:0] b,
    output reg result,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam RECEIVE = 2'b01;
    localparam CHECK = 2'b10;
    localparam FINISHED = 2'b11;

    // Internal registers
    reg [1:0] state;
    reg [6:0] count;
    reg signed [31:0] current_x, current_y;
    reg signed [31:0] dx, dy;
    reg [6:0] index;
    reg signed [31:0] x_mem [0:100];
    reg signed [31:0] y_mem [0:100];

    // Helper signals for condition checking
    wire signed [31:0] ax = a - x_mem[index];
    wire signed [31:0] by = b - y_mem[index];
    wire signed [63:0] prod1 = ax * dy;
    wire signed [63:0] prod2 = by * dx;
    wire sign_ok_dx = (dx > 0 && ax >= 0) || (dx < 0 && ax <= 0) || (dx == 0);
    wire sign_ok_dy = (dy > 0 && by >= 0) || (dy < 0 && by <= 0) || (dy == 0);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            count <= 0;
            index <= 0;
            current_x <= 0;
            current_y <= 0;
            dx <= 0;
            dy <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= RECEIVE;
                        count <= 0;
                        current_x <= 0;
                        current_y <= 0;
                        x_mem[0] <= 0;
                        y_mem[0] <= 0;
                        done <= 0;
                        result <= 0;
                    end
                end

                RECEIVE: begin
                    if (char_valid) begin
                        // Update current position
                        case (char)
                            "U", "u": current_y <= current_y + 1;
                            "D", "d": current_y <= current_y - 1;
                            "L", "l": current_x <= current_x - 1;
                            "R", "r": current_x <= current_x + 1;
                            default: ; // Ignore invalid
                        endcase

                        // Store new position
                        x_mem[count + 1] <= (char == "L" || char == "l") ? current_x - 1 :
                                          (char == "R" || char == "r") ? current_x + 1 : current_x;
                        y_mem[count + 1] <= (char == "U" || char == "u") ? current_y + 1 :
                                          (char == "D" || char == "d") ? current_y - 1 : current_y;

                        count <= count + 1;

                        if (count + 1 == len) begin
                            dx <= (char == "L" || char == "l") ? current_x - 1 :
                                  (char == "R" || char == "r") ? current_x + 1 : current_x;
                            dy <= (char == "U" || char == "u") ? current_y + 1 :
                                  (char == "D" || char == "d") ? current_y - 1 : current_y;
                            state <= CHECK;
                            index <= 0;
                        end
                    end
                end

                CHECK: begin
                    if (index <= len) begin
                        if (dx == 0 && dy == 0) begin
                            if (a == x_mem[index] && b == y_mem[index]) begin
                                result <= 1;
                                state <= FINISHED;
                            end else if (index == len) begin
                                result <= 0;
                                state <= FINISHED;
                            end else begin
                                index <= index + 1;
                            end
                        end else if (dx == 0) begin
                            if (a == x_mem[index]) begin
                                if (b == y_mem[index]) begin
                                    result <= 1;
                                    state <= FINISHED;
                                end else if (dy != 0 && (b - y_mem[index]) % dy == 0) begin
                                    integer k = (b - y_mem[index]) / dy;
                                    if (k >= 0) begin
                                        result <= 1;
                                        state <= FINISHED;
                                    end else if (index == len) begin
                                        result <= 0;
                                        state <= FINISHED;
                                    end else begin
                                        index <= index + 1;
                                    end
                                end else if (index == len) begin
                                    result <= 0;
                                    state <= FINISHED;
                                end else begin
                                    index <= index + 1;
                                end
                            end else if (index == len) begin
                                result <= 0;
                                state <= FINISHED;
                            end else begin
                                index <= index + 1;
                            end
                        end else if (dy == 0) begin
                            if (b == y_mem[index]) begin
                                if (a == x_mem[index]) begin
                                    result <= 1;
                                    state <= FINISHED;
                                end else if (dx != 0 && (a - x_mem[index]) % dx == 0) begin
                                    integer k = (a - x_mem[index]) / dx;
                                    if (k >= 0) begin
                                        result <= 1;
                                        state <= FINISHED;
                                    end else if (index == len) begin
                                        result <= 0;
                                        state <= FINISHED;
                                    end else begin
                                        index <= index + 1;
                                    end
                                end else if (index == len) begin
                                    result <= 0;
                                    state <= FINISHED;
                                end else begin
                                    index <= index + 1;
                                end
                            end else if (index == len) begin
                                result <= 0;
                                state <= FINISHED;
                            end else begin
                                index <= index + 1;
                            end
                        end else begin
                            // Both dx and dy non-zero
                            if (prod1 == prod2 && sign_ok_dx && sign_ok_dy) begin
                                result <= 1;
                                state <= FINISHED;
                            end else if (index == len) begin
                                result <= 0;
                                state <= FINISHED;
                            end else begin
                                index <= index + 1;
                            end
                        end
                    end else begin
                        result <= 0;
                        state <= FINISHED;
                    end
                end

                FINISHED: begin
                    done <= 1;
                end
            endcase
        end
    end
endmodule

module garland_minimizer (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [5:0] n,          // Number of bulbs (max 16)
    input wire [7:0] p_0, p_1, p_2, p_3, p_4, p_5, p_6, p_7,
    input wire [7:0] p_8, p_9, p_10, p_11, p_12, p_13, p_14, p_15,
    output reg [4:0] result,
    output reg done
);

    // Constants
    parameter MAX_N = 16;
    parameter MAX_E = 8;          // Max even numbers
    parameter MAX_O = 8;          // Max odd numbers
    parameter INF = 5'b11111;     // Infinity for DP

    // State machine states
    typedef enum logic [2:0] {
        IDLE,
        PRECOMPUTE,
        INIT_DP,
        DP_ITER,
        FINALIZE
    } state_t;

    state_t state;

    // Input storage
    reg [7:0] p_arr [0:15];

    // Precomputation registers
    reg [4:0] fixed_count [0:16];  // fixed_count[i] = count of non-zero in first i elements
    reg [3:0] total_odd, total_even;
    reg [3:0] missing_odd, missing_even;
    reg [3:0] odd_count, even_count;

    // DP registers
    reg [4:0] dp_cur [0:MAX_E] [0:1];  // [even_used][prev_parity]
    reg [4:0] dp_next [0:MAX_E] [0:1];

    // Iteration counters
    reg [4:0] i_counter;          // Current position (0 to n)
    reg [3:0] e_counter;          // Even counter (0 to missing_even)
    reg p_counter;                // Parity counter (0,1)

    // Helper wires
    wire [7:0] current_p;
    assign current_p = p_arr[i_counter];

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            // Reset DP arrays
            for (int e = 0; e <= MAX_E; e++) begin
                dp_cur[e][0] <= INF;
                dp_cur[e][1] <= INF;
                dp_next[e][0] <= INF;
                dp_next[e][1] <= INF;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= PRECOMPUTE;
                        // Store input array
                        p_arr[0] <= p_0;  p_arr[1] <= p_1;  p_arr[2] <= p_2;  p_arr[3] <= p_3;
                        p_arr[4] <= p_4;  p_arr[5] <= p_5;  p_arr[6] <= p_6;  p_arr[7] <= p_7;
                        p_arr[8] <= p_8;  p_arr[9] <= p_9;  p_arr[10] <= p_10; p_arr[11] <= p_11;
                        p_arr[12] <= p_12; p_arr[13] <= p_13; p_arr[14] <= p_14; p_arr[15] <= p_15;
                    end
                end

                PRECOMPUTE: begin
                    // Initialize counters
                    odd_count <= 0;
                    even_count <= 0;
                    fixed_count[0] <= 0;

                    // Compute fixed_count and count existing odds/evens
                    for (int idx = 0; idx < MAX_N; idx++) begin
                        if (idx < n) begin
                            if (p_arr[idx] != 8'd0) begin
                                if (p_arr[idx][0]) begin  // Odd
                                    odd_count <= odd_count + 1;
                                end else begin            // Even
                                    even_count <= even_count + 1;
                                end
                                fixed_count[idx+1] <= fixed_count[idx] + 1;
                            end else begin
                                fixed_count[idx+1] <= fixed_count[idx];
                            end
                        end else begin
                            fixed_count[idx+1] <= fixed_count[idx];
                        end
                    end

                    // Compute totals
                    total_odd <= (n + 1) >> 1;      // (n+1)//2
                    total_even <= n >> 1;           // n//2

                    state <= INIT_DP;
                end

                INIT_DP: begin
                    // Compute missing counts
                    missing_odd <= total_odd - odd_count;
                    missing_even <= total_even - even_count;

                    // Initialize DP arrays
                    for (int e = 0; e <= MAX_E; e++) begin
                        dp_cur[e][0] <= INF;
                        dp_cur[e][1] <= INF;
                        dp_next[e][0] <= INF;
                        dp_next[e][1] <= INF;
                    end

                    // Base case: i=0
                    dp_cur[0][0] <= 0;
                    dp_cur[0][1] <= 0;

                    // Initialize iteration counters
                    i_counter <= 0;
                    e_counter <= 0;
                    p_counter <= 0;

                    state <= DP_ITER;
                end

                DP_ITER: begin
                    if (i_counter < n) begin
                        // Check if we've processed all (e, p) for current i
                        if (e_counter > missing_even && p_counter == 1'b1) begin
                            // Move to next i
                            i_counter <= i_counter + 1;
                            e_counter <= 0;
                            p_counter <= 0;

                            // Copy dp_next to dp_cur for next iteration
                            for (int e = 0; e <= MAX_E; e++) begin
                                dp_cur[e][0] <= dp_next[e][0];
                                dp_cur[e][1] <= dp_next[e][1];
                                dp_next[e][0] <= INF;
                                dp_next[e][1] <= INF;
                            end
                        end else begin
                            // Process current (e_counter, p_counter) state
                            if (dp_cur[e_counter][p_counter] != INF) begin
                                if (current_p != 8'd0) begin
                                    // Fixed element
                                    logic q;
                                    logic [4:0] cost;
                                    q = current_p[0];  // Parity (0=even, 1=odd)
                                    cost = (p_counter != q) ? 1 : 0;

                                    if (dp_cur[e_counter][p_counter] + cost < dp_next[e_counter][q]) begin
                                        dp_next[e_counter][q] <= dp_cur[e_counter][p_counter] + cost;
                                    end
                                end else begin
                                    // Missing element
                                    logic [3:0] missing_count_i;
                                    logic [3:0] placed_odds;
                                    logic [4:0] cost_even, cost_odd;

                                    missing_count_i = i_counter - fixed_count[i_counter];
                                    placed_odds = missing_count_i - e_counter;

                                    // Option 1: Place even
                                    if (e_counter < missing_even) begin
                                        cost_even = (p_counter != 1'b0) ? 1 : 0;
                                        if (dp_cur[e_counter][p_counter] + cost_even < dp_next[e_counter+1][0]) begin
                                            dp_next[e_counter+1][0] <= dp_cur[e_counter][p_counter] + cost_even;
                                        end
                                    end

                                    // Option 2: Place odd
                                    if (placed_odds < missing_odd) begin
                                        cost_odd = (p_counter != 1'b1) ? 1 : 0;
                                        if (dp_cur[e_counter][p_counter] + cost_odd < dp_next[e_counter][1]) begin
                                            dp_next[e_counter][1] <= dp_cur[e_counter][p_counter] + cost_odd;
                                        end
                                    end
                                end
                            end

                            // Increment counters
                            if (p_counter == 1'b1) begin
                                p_counter <= 0;
                                e_counter <= e_counter + 1;
                            end else begin
                                p_counter <= 1;
                            end
                        end
                    end else begin
                        // i_counter >= n, done with DP
                        state <= FINALIZE;
                    end
                end

                FINALIZE: begin
                    // Take minimum of dp_cur[missing_even][0] and dp_cur[missing_even][1]
                    if (dp_cur[missing_even][0] < dp_cur[missing_even][1]) begin
                        result <= dp_cur[missing_even][0];
                    end else begin
                        result <= dp_cur[missing_even][1];
                    end
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module obfuscation_check (
    input wire clk,           // Clock, rising edge
    input wire rst_n,         // Active-low reset
    input wire start,         // Start pulse (1 cycle)
    input wire [4:0] char_0,  // Character 0
    input wire [4:0] char_1,  // Character 1
    input wire [4:0] char_2,  // Character 2
    input wire [4:0] char_3,  // Character 3
    input wire [4:0] char_4,  // Character 4
    input wire [4:0] char_5,  // Character 5
    input wire [4:0] char_6,  // Character 6
    input wire [4:0] char_7,  // Character 7
    input wire [3:0] len,     // Number of valid characters (1-8)
    output reg result,        // 1 if valid, 0 otherwise
    output reg done           // Pulsed high for 1 cycle when finished
);

// State encoding
localparam IDLE = 2'b00;
localparam PROC = 2'b01;
localparam DONE = 2'b10;

reg [1:0] state, next_state;
reg [2:0] index, next_index;
reg [7:0] seen, next_seen;
reg [2:0] next_expected, next_next_expected;
reg next_result, next_done;

wire [4:0] current_char;
assign current_char = (index == 3'd0) ? char_0 :
                      (index == 3'd1) ? char_1 :
                      (index == 3'd2) ? char_2 :
                      (index == 3'd3) ? char_3 :
                      (index == 3'd4) ? char_4 :
                      (index == 3'd5) ? char_5 :
                      (index == 3'd6) ? char_6 :
                      char_7;

// Combinational next-state logic
always @(*) begin
    // Defaults
    next_state = state;
    next_index = index;
    next_seen = seen;
    next_next_expected = next_expected;
    next_result = result;
    next_done = 1'b0;

    case (state)
        IDLE: begin
            if (start) begin
                next_state = PROC;
                next_index = 3'b0;
                next_seen = 8'b0;
                next_next_expected = 3'b0;
                next_result = 1'b1;
            end
        end

        PROC: begin
            if (index < len) begin
                // Check if letter already seen
                if (seen[current_char[2:0]]) begin
                    // Already seen, just move to next
                    next_index = index + 1'b1;
                end else begin
                    // New letter
                    if (current_char[2:0] == next_expected) begin
                        // Correct order
                        next_seen = seen | (1'b1 << current_char[2:0]);
                        next_next_expected = next_expected + 1'b1;
                        next_index = index + 1'b1;
                    end else begin
                        // Wrong order
                        next_result = 1'b0;
                        next_state = DONE;
                        next_done = 1'b1;
                    end
                end
            end else begin
                // Processed all characters
                next_state = DONE;
                next_done = 1'b1;
                next_result = result; // still valid
            end
        end

        DONE: begin
            // Return to IDLE after one cycle
            next_state = IDLE;
            next_done = 1'b0;
        end
    endcase
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        index <= 3'b0;
        seen <= 8'b0;
        next_expected <= 3'b0;
        result <= 1'b0;
        done <= 1'b0;
    end else begin
        state <= next_state;
        index <= next_index;
        seen <= next_seen;
        next_expected <= next_next_expected;
        result <= next_result;
        done <= next_done;
    end
end

endmodule

module team_selection (
    input clk, rst_n, start,
    input [3:0] n, p, s,
    input [7:0] a [0:7],
    input [7:0] b [0:7],
    output reg [15:0] total,
    output reg [7:0] prog_indices [0:7],
    output reg [7:0] sports_indices [0:7],
    output reg [3:0] prog_count,
    output reg [3:0] sports_count,
    output reg done
);

// Internal state
reg [2:0] state;
reg [7:0] temp_a [0:7];
reg [7:0] temp_b [0:7];
reg [2:0] i, j, k;
reg [15:0] current_sum;
reg [7:0] conversion [0:7]; // b - a

// State definitions
localparam IDLE = 3'd0;
localparam SORT_A = 3'd1;
localparam CALC_CONV = 3'd2;
localparam SELECT_TEAMS = 3'd3;
localparam CALC_TOTAL = 3'd4;
localparam DONE = 3'd5;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        total <= 0;
        prog_count <= 0;
        sports_count <= 0;
        for (integer idx = 0; idx < 8; idx = idx + 1) begin
            prog_indices[idx] <= 0;
            sports_indices[idx] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Copy inputs to temp arrays
                    for (integer idx = 0; idx < 8; idx = idx + 1) begin
                        temp_a[idx] <= (idx < n) ? a[idx] : 8'd0;
                        temp_b[idx] <= (idx < n) ? b[idx] : 8'd0;
                    end
                    i <= 0;
                    j <= 0;
                    k <= 0;
                    state <= SORT_A;
                end
            end

            SORT_A: begin
                // Simple bubble sort for a values (max 8 elements)
                if (i < n - 1) begin
                    if (j < n - 1 - i) begin
                        if (temp_a[j] < temp_a[j+1]) begin
                            // Swap a
                            temp_a[j] <= temp_a[j+1];
                            temp_a[j+1] <= temp_a[j];
                            // Swap b accordingly
                            temp_b[j] <= temp_b[j+1];
                            temp_b[j+1] <= temp_b[j];
                        end
                        j <= j + 1;
                    end else begin
                        j <= 0;
                        i <= i + 1;
                    end
                end else begin
                    i <= 0;
                    state <= CALC_CONV;
                end
            end

            CALC_CONV: begin
                // Calculate conversion gains (b - a)
                if (i < n) begin
                    conversion[i] <= temp_b[i] - temp_a[i];
                    i <= i + 1;
                end else begin
                    i <= 0;
                    j <= 0;
                    state <= SELECT_TEAMS;
                end
            end

            SELECT_TEAMS: begin
                // Select top p for programming (based on a)
                // Then consider conversions for sports
                if (i < p) begin
                    prog_indices[i] <= i; // Store index in sorted order
                    i <= i + 1;
                end else if (i < p + s) begin
                    // For sports, consider conversion gains from top p+s students
                    // Find best conversions
                    if (j < n && j < p + s) begin
                        if (j < p) begin
                            // Already in programming, consider converting to sports
                            // Check if better than current sports selection
                            sports_indices[i - p] <= j;
                        end else begin
                            // Add directly to sports
                            sports_indices[i - p] <= j;
                        end
                        j <= j + 1;
                        i <= i + 1;
                    end else begin
                        state <= CALC_TOTAL;
                    end
                end else begin
                    state <= CALC_TOTAL;
                end
            end

            CALC_TOTAL: begin
                // Calculate total strength
                current_sum <= 0;
                for (integer idx = 0; idx < 8; idx = idx + 1) begin
                    if (prog_indices[idx] < n && idx < p) begin
                        current_sum <= current_sum + temp_a[prog_indices[idx]];
                    end
                    if (sports_indices[idx] < n && idx < s) begin
                        current_sum <= current_sum + temp_b[sports_indices[idx]];
                    end
                end
                prog_count <= p;
                sports_count <= s;
                state <= DONE;
            end

            DONE: begin
                total <= current_sum;
                done <= 1;
                // Wait for reset
            end
        endcase
    end
end

endmodule

module table_tennis(
    input signed [31:0] k,
    input signed [31:0] a,
    input signed [31:0] b,
    output reg signed [31:0] result
);

reg signed [31:0] X, Y;
reg signed [31:0] rem_a, rem_b;

always @(*) begin
    X = a / k;
    Y = b / k;
    rem_a = a % k;
    rem_b = b % k;

    if ((rem_a != 0 && Y == 0) || (rem_b != 0 && X == 0)) begin
        result = -1;
    end else begin
        result = X + Y;
    end
end

endmodule

module cook_time (
    input [15:0] k,    // Stove on time
    input [15:0] d,    // Julia's check interval
    input [15:0] t,    // Cooking time when stove is on
    output [31:0] total_time  // Total cooking time in Q16.16 format
);

// Internal signals (32-bit to prevent overflow)
wire [31:0] k32 = {16'b0, k};
wire [31:0] d32 = {16'b0, d};
wire [31:0] t32 = {16'b0, t};

// Calculate cycle length T = ceil(k/d) * d
wire [31:0] ceil_div = (k32 + d32 - 1) / d32;
wire [31:0] T = ceil_div * d32;

// Check if k is divisible by d (stove always on)
wire is_divisible = (k % d == 0);

// Calculate cooking per cycle in fixed-point units
// One cooking unit = 2*t (to avoid fractions)
wire [31:0] two_t = t32 << 1;
wire [31:0] cycle_units = k32 + ((T - k32) >> 1);  // k + (T-k)/2

// Number of full cycles
wire [31:0] full_cycles = two_t / cycle_units;
wire [31:0] remaining_units = two_t - full_cycles * cycle_units;

// Calculate remaining cooking time
wire [31:0] remaining_time;
assign remaining_time = (remaining_units <= k32) ? 
                        remaining_units : 
                        k32 + ((remaining_units - k32) << 1);

// Final result: (full_cycles * T + remaining_time) converted to Q16.16
// Multiply by 65536 (2^16) to convert to fixed-point
wire [31:0] result = is_divisible ? 
                    (t32 << 16) : 
                    ((full_cycles * T + remaining_time) << 16);

assign total_time = result;

endmodule

module treasure_island #(
    parameter MAX_N = 8,
    parameter MAX_M = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,
    input wire [3:0] m,
    input wire [MAX_N*MAX_M-1:0] grid_flat,
    output reg [1:0] result,
    output reg done
);

localparam IDLE = 3'd0;
localparam LOAD = 3'd1;
localparam FORWARD = 3'd2;
localparam BACKWARD = 3'd3;
localparam COUNT = 3'd4;
localparam CHECK = 3'd5;
localparam DONE = 3'd6;

reg [MAX_M-1:0] grid [0:MAX_N-1];
reg [MAX_M-1:0] reachable [0:MAX_N-1];
reg [MAX_M-1:0] can_reach [0:MAX_N-1];
reg [3:0] diag_cnt [0:14];

reg [2:0] state;
reg [3:0] i, j;
reg [3:0] diag_idx;
reg path_exists;

wire cell_forest = grid[i][j];

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        j <= 0;
        path_exists <= 0;
        for (int k = 0; k < 15; k++) begin
            diag_cnt[k] <= 4'd0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= LOAD;
                    i <= 0;
                    j <= 0;
                end
            end

            LOAD: begin
                if (i < n) begin
                    if (j < m) begin
                        grid[i][j] <= grid_flat[i*MAX_M + j];
                        reachable[i][j] <= 1'b0;
                        can_reach[i][j] <= 1'b0;
                        j <= j + 1'b1;
                    end else begin
                        j <= 0;
                        i <= i + 1'b1;
                    end
                end else begin
                    i <= 0;
                    j <= 0;
                    state <= FORWARD;
                end
            end

            FORWARD: begin
                if (i < n && j < m) begin
                    if (i == 0 && j == 0) begin
                        reachable[0][0] <= ~grid[0][0];
                    end else if (!cell_forest) begin
                        if ((i > 0 && reachable[i-1][j]) || (j > 0 && reachable[i][j-1])) begin
                            reachable[i][j] <= 1'b1;
                        end
                    end
                    if (j + 1'b1 < m) begin
                        j <= j + 1'b1;
                    end else begin
                        j <= 0;
                        i <= i + 1'b1;
                    end
                end else begin
                    if (reachable[n-1][m-1]) begin
                        path_exists <= 1'b1;
                        i <= n - 1'b1;
                        j <= m - 1'b1;
                        state <= BACKWARD;
                    end else begin
                        result <= 2'd0;
                        state <= DONE;
                    end
                end
            end

            BACKWARD: begin
                if (i >= 0 && j >= 0) begin
                    if (i == n-1 && j == m-1) begin
                        can_reach[n-1][m-1] <= ~grid[n-1][m-1];
                    end else if (!cell_forest) begin
                        if ((i < n-1 && can_reach[i+1][j]) || (j < m-1 && can_reach[i][j+1])) begin
                            can_reach[i][j] <= 1'b1;
                        end
                    end
                    if (j > 0) begin
                        j <= j - 1'b1;
                    end else begin
                        j <= m - 1'b1;
                        if (i > 0) i <= i - 1'b1;
                        else begin
                            i <= 0;
                            j <= 0;
                            state <= COUNT;
                        end
                    end
                end else begin
                    state <= COUNT;
                end
            end

            COUNT: begin
                if (i < n && j < m) begin
                    if (reachable[i][j] && can_reach[i][j] && !cell_forest) begin
                        diag_idx = i + j;
                        if (diag_idx < 15) begin
                            diag_cnt[diag_idx] <= diag_cnt[diag_idx] + 1'b1;
                        end
                    end
                    if (j + 1'b1 < m) begin
                        j <= j + 1'b1;
                    end else begin
                        j <= 0;
                        i <= i + 1'b1;
                    end
                end else begin
                    i <= 0;
                    state <= CHECK;
                end
            end

            CHECK: begin
                if (i < (n + m - 2)) begin
                    if (diag_cnt[i] == 4'd1) begin
                        result <= 2'd1;
                        state <= DONE;
                    end else begin
                        i <= i + 1'b1;
                    end
                end else begin
                    result <= 2'd2;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1'b1;
                if (!start) state <= IDLE;
            end
        endcase
    end
end

endmodule

module symmetry_check (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] grid [0:11] [0:11],  // Fixed 12x12 grid, each element 8-bit ASCII
    input wire [3:0] H, W,                  // Actual dimensions (max 12)
    output reg result,
    output reg done
);

    // This module determines if an HxW grid can be made symmetric by swapping rows/columns.
    // The grid is stored as 12x12, but we only use H rows and W columns.
    // Each element is 8-bit ASCII (lowercase letters).

    // Outputs:
    //   result: 1 if symmetric possible, 0 otherwise
    //   done:   asserted for one cycle when computation completes

    // Timing: After start is pulsed, done will be asserted within 1000 cycles.
    // Reset: active-low, clears all internal state.

    // Implementation approach:
    // 1. Generate all row pairings (assignments to symmetric positions)
    // 2. For each pairing, build temporary grid
    // 3. Check if columns can be matched using frequency counting
    // 4. If any pairing works, set result=1

    // Internal state machine:
    // - IDLE: Wait for start
    // - GEN_ROWS: Generate next row pairing
    // - BUILD_GRID: Construct temporary grid with current row assignment
    // - CHECK_COLS: Verify column matching
    // - DONE: Set done signal

    // Register width calculations:
    // - Row pairing counter: up to 12! = 479001600, use 28 bits
    // - Column index: 4 bits (0-11)
    // - Frequency counters: 4 bits (max 12 columns)

endmodule

module find_rectangle (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] n,
    input wire [31:0] m,
    input wire [31:0] x,
    input wire [31:0] y,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] x1,
    output reg [31:0] y1,
    output reg [31:0] x2,
    output reg [31:0] y2,
    output reg done
);

    // State definitions
    localparam S_IDLE = 4'd0;
    localparam S_GCD = 4'd1;
    localparam S_REDUCE = 4'd2;
    localparam S_SCALE = 4'd3;
    localparam S_POSITION = 4'd4;
    localparam S_DONE = 4'd5;

    reg [3:0] state;
    reg [3:0] next_state;

    // Internal registers for intermediate results
    reg [31:0] gcd_a;
    reg [31:0] gcd_b;
    reg [31:0] gcd_temp;
    reg [31:0] a_reduced;
    reg [31:0] b_reduced;
    reg [31:0] k;
    reg [31:0] width;
    reg [31:0] height;
    reg [31:0] cx;
    reg [31:0] cy;
    reg [31:0] dx;
    reg [31:0] dy;
    reg [31:0] max_k;
    reg [31:0] div_temp;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            S_IDLE: begin
                if (start) next_state = S_GCD;
                else next_state = S_IDLE;
            end
            S_GCD: begin
                if (gcd_b == 0) next_state = S_REDUCE;
                else next_state = S_GCD;
            end
            S_REDUCE: next_state = S_SCALE;
            S_SCALE: next_state = S_POSITION;
            S_POSITION: next_state = S_DONE;
            S_DONE: next_state = S_IDLE;
            default: next_state = S_IDLE;
        endcase
    end

    // Output and datapath logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            x1 <= 0; y1 <= 0; x2 <= 0; y2 <= 0; done <= 0;
            gcd_a <= 0; gcd_b <= 0; gcd_temp <= 0;
            a_reduced <= 0; b_reduced <= 0;
            k <= 0; width <= 0; height <= 0;
            cx <= 0; cy <= 0; dx <= 0; dy <= 0;
            max_k <= 0; div_temp <= 0;
        end else begin
            case (state)
                S_IDLE: begin
                    done <= 0;
                    if (start) begin
                        gcd_a <= a;
                        gcd_b <= b;
                    end
                end

                S_GCD: begin
                    if (gcd_b != 0) begin
                        gcd_temp <= gcd_a % gcd_b;
                        gcd_a <= gcd_b;
                        gcd_b <= gcd_temp;
                    end
                end

                S_REDUCE: begin
                    a_reduced <= a / gcd_a;
                    b_reduced <= b / gcd_a;
                end

                S_SCALE: begin
                    // Compute min(n / a_reduced, m / b_reduced)
                    if (a_reduced != 0 && b_reduced != 0) begin
                        if (n / a_reduced < m / b_reduced) begin
                            k <= n / a_reduced;
                        end else begin
                            k <= m / b_reduced;
                        end
                    end else begin
                        k <= 0;
                    end
                    // Compute width and height
                    width <= a_reduced * k;
                    height <= b_reduced * k;
                end

                S_POSITION: begin
                    // Compute center offsets
                    cx <= (width + 1) >> 1;  // (width + 1) // 2
                    cy <= (height + 1) >> 1; // (height + 1) // 2

                    // Compute dx and dy
                    if (x > cx) begin
                        dx <= x - cx;
                    end else begin
                        dx <= 0;
                    end

                    if (y > cy) begin
                        dy <= y - cy;
                    end else begin
                        dy <= 0;
                    end

                    // Clamp to boundaries
                    if (dx + width > n) begin
                        dx <= n - width;
                    end

                    if (dy + height > m) begin
                        dy <= m - height;
                    end

                    // Compute final outputs
                    x1 <= dx;
                    y1 <= dy;
                    x2 <= dx + width;
                    y2 <= dy + height;
                end

                S_DONE: begin
                    done <= 1;
                end
            endcase
        end
    end

endmodule

module packman_time (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [127:0] field,  // 16 characters, each 8 bits
    output reg [15:0] result,
    output reg done
);

    // Parameters
    parameter MAX_N = 16;
    parameter MAX_STARS = 16;
    parameter MAX_PACKMEN = 16;

    // State definitions
    localparam IDLE = 0;
    localparam PARSE = 1;
    localparam BINARY_SEARCH_INIT = 2;
    localparam BINARY_SEARCH_LOOP = 3;
    localparam CHECK = 4;
    localparam BINARY_SEARCH_UPDATE = 5;
    localparam DONE = 6;

    // Registers for state
    reg [3:0] state;

    // Parse state registers
    reg [3:0] parse_index;
    reg [3:0] star_count;
    reg [3:0] packmen_count;
    reg [3:0] stars [0:15];
    reg [3:0] packmen [0:15];

    // Binary search registers
    reg [5:0] low, high, mid;
    reg [5:0] current_T;

    // DP state registers
    reg [3:0] dp_i, dp_j, dp_l;
    reg [0:0] dp [0:16][0:16]; // dp[i][j] for i=0..16, j=0..16

    // Intermediate computation for condition
    reg [5:0] option1, option2, min_option;
    reg condition;

    // Helper signals
    reg [7:0] char;
    integer i, j, l;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            parse_index <= 0;
            star_count <= 0;
            packmen_count <= 0;
            low <= 0;
            high <= 0;
            mid <= 0;
            current_T <= 0;
            dp_i <= 0;
            dp_j <= 0;
            dp_l <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= PARSE;
                        parse_index <= 0;
                        star_count <= 0;
                        packmen_count <= 0;
                    end
                end

                PARSE: begin
                    if (parse_index < MAX_N) begin
                        char = field[parse_index*8 +: 8];
                        if (char == 8'h2A) begin  // ASCII for '*'
                            stars[star_count] <= parse_index;
                            star_count <= star_count + 1;
                        end else if (char == 8'h50) begin  // ASCII for 'P'
                            packmen[packmen_count] <= parse_index;
                            packmen_count <= packmen_count + 1;
                        end
                        parse_index <= parse_index + 1;
                    end else begin
                        state <= BINARY_SEARCH_INIT;
                    end
                end

                BINARY_SEARCH_INIT: begin
                    low <= 0;
                    high <= 2 * MAX_N; // 32
                    state <= BINARY_SEARCH_LOOP;
                end

                BINARY_SEARCH_LOOP: begin
                    if (low + 1 < high) begin
                        mid <= (low + high) >> 1;
                        current_T <= (low + high) >> 1;
                        state <= CHECK;
                        dp_i <= 0;
                        dp_j <= 0;
                        dp_l <= 0;
                        // Initialize dp table to 0
                        for (i = 0; i <= 16; i = i + 1) begin
                            for (j = 0; j <= 16; j = j + 1) begin
                                dp[i][j] <= 0;
                            end
                        end
                        dp[0][0] <= 1;
                    end else begin
                        state <= DONE;
                        result <= high;
                    end
                end

                CHECK: begin
                    // If we have finished the DP, check result
                    if (dp_i > packmen_count) begin
                        if (dp[packmen_count][star_count]) begin
                            state <= BINARY_SEARCH_UPDATE;
                        end else begin
                            state <= BINARY_SEARCH_UPDATE;
                        end
                    end else begin
                        if (dp_i == 0) begin
                            dp_i <= 1;
                            dp_j <= 0;
                            dp_l <= 0;
                        end else begin
                            if (dp_l <= dp_j) begin
                                if (dp[dp_i-1][dp_l]) begin
                                    if (dp_l == dp_j) begin
                                        dp[dp_i][dp_j] <= 1;
                                    end else begin
                                        option1 = 2*(packmen[dp_i-1] - stars[dp_l]) + (stars[dp_j-1] - packmen[dp_i-1]);
                                        option2 = 2*(stars[dp_j-1] - packmen[dp_i-1]) + (packmen[dp_i-1] - stars[dp_l]);
                                        min_option = (option1 < option2) ? option1 : option2;
                                        condition = (min_option <= current_T);
                                        if (condition) begin
                                            dp[dp_i][dp_j] <= 1;
                                        end
                                    end
                                end
                                dp_l <= dp_l + 1;
                            end else begin
                                dp_j <= dp_j + 1;
                                dp_l <= 0;
                                if (dp_j == star_count) begin
                                    dp_i <= dp_i + 1;
                                    dp_j <= 0;
                                end
                            end
                        end
                    end
                end

                BINARY_SEARCH_UPDATE: begin
                    if (dp[packmen_count][star_count]) begin
                        high <= mid;
                    end else begin
                        low <= mid;
                    end
                    state <= BINARY_SEARCH_LOOP;
                end

                DONE: begin
                    done <= 1;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module string_constructor (
    input clk,
    input rst_n,
    input start,
    input [15:0] a00,
    input [15:0] a01,
    input [15:0] a10,
    input [15:0] a11,
    output reg [7:0] char,
    output reg valid,
    output reg done
);

// Parameters for maximum constraints
parameter MAX_LEN = 16;
parameter MAX_N = 16;

// State definitions
parameter IDLE = 3'b000;
parameter COMPUTE_N = 3'b001;
parameter CHECK_COND = 3'b010;
parameter BUILD_STRING = 3'b011;
parameter OUTPUT_STRING = 3'b100;
parameter FINISHED = 3'b101;

// Internal registers
reg [2:0] state, next_state;
reg [4:0] n0, n1;  // Count of 0s and 1s
reg [4:0] i, j;    // Loop counters
reg [4:0] gap [0:MAX_N];  // Gap distribution
reg [7:0] string_buffer [0:MAX_LEN-1];  // Output string buffer
reg [4:0] buf_len;  // Actual string length
reg [4:0] out_idx;  // Output index

// Helper function: Check if value is triangular number
function [4:0] find_n;
    input [15:0] val;
    reg [15:0] tri;
    integer k;
    begin
        find_n = 0;
        for (k = 0; k <= MAX_N; k = k + 1) begin
            tri = k * (k - 1) / 2;
            if (tri == val) begin
                find_n = k;
            end
        end
    end
endfunction

// State transition
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: begin
            if (start) next_state = COMPUTE_N;
        end
        COMPUTE_N: begin
            next_state = CHECK_COND;
        end
        CHECK_COND: begin
            // If valid, go to build, else finish
            if ((n0 * n1 == a01 + a10) && (n0 + n1 <= MAX_LEN)) begin
                next_state = BUILD_STRING;
            end else begin
                next_state = FINISHED;
            end
        end
        BUILD_STRING: begin
            if (i >= buf_len) begin
                next_state = OUTPUT_STRING;
            end else begin
                next_state = BUILD_STRING;
            end
        end
        OUTPUT_STRING: begin
            if (out_idx >= buf_len) begin
                next_state = FINISHED;
            end else begin
                next_state = OUTPUT_STRING;
            end
        end
        FINISHED: next_state = FINISHED;
        default: next_state = IDLE;
    endcase
end

// Output logic and operations
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        char <= 8'b0;
        valid <= 1'b0;
        done <= 1'b0;
        n0 <= 0;
        n1 <= 0;
        i <= 0;
        j <= 0;
        buf_len <= 0;
        out_idx <= 0;
    end else begin
        case (state)
            IDLE: begin
                char <= 8'b0;
                valid <= 1'b0;
                done <= 1'b0;
            end

            COMPUTE_N: begin
                // Compute n0 and n1 from triangular numbers
                n0 <= find_n(a00);
                n1 <= find_n(a11);
                // Handle special case where all are zero
                if (a00 == 0 && a01 == 0 && a10 == 0 && a11 == 0) begin
                    n0 <= 1;
                    n1 <= 0;
                end
            end

            CHECK_COND: begin
                // Reset counters
                i <= 0;
                j <= 0;
                buf_len <= 0;
            end

            BUILD_STRING: begin
                if (i == 0) begin
                    // Initialize gap array for distribution
                    // Simple greedy distribution: place zeros in gaps
                    gap[0] <= n0;
                    for (integer k = 1; k <= MAX_N; k = k + 1) begin
                        gap[k] <= 0;
                    end
                    // Distribute zeros based on a01 value
                    if (n1 > 0 && n0 > 0) begin
                        gap[0] <= a01 / n1;
                        gap[1] <= n0 - (a01 / n1);
                    end
                end

                // Build string buffer
                if (i < n1) begin
                    // Add zeros for this gap
                    if (j < gap[i]) begin
                        string_buffer[buf_len] <= "0";
                        buf_len <= buf_len + 1;
                        j <= j + 1;
                    end else begin
                        // Add one after zeros
                        string_buffer[buf_len] <= "1";
                        buf_len <= buf_len + 1;
                        i <= i + 1;
                        j <= 0;
                    end
                end else if (i == n1 && j < gap[n1]) begin
                    // Add remaining zeros
                    string_buffer[buf_len] <= "0";
                    buf_len <= buf_len + 1;
                    j <= j + 1;
                end else if (i == n1) begin
                    // Add final one if needed (rare case)
                    if (n1 > 0 && buf_len > 0 && string_buffer[buf_len-1] != "1") begin
                        string_buffer[buf_len] <= "1";
                        buf_len <= buf_len + 1;
                    end
                    i <= i + 1;  // Mark complete
                end

                // Special case: all zeros
                if (n1 == 0 && n0 > 0 && i < n0) begin
                    string_buffer[buf_len] <= "0";
                    buf_len <= buf_len + 1;
                    i <= i + 1;
                end
                // Special case: all ones  
                if (n0 == 0 && n1 > 0 && i < n1) begin
                    string_buffer[buf_len] <= "1";
                    buf_len <= buf_len + 1;
                    i <= i + 1;
                end
            end

            OUTPUT_STRING: begin
                if (out_idx < buf_len) begin
                    char <= string_buffer[out_idx];
                    valid <= 1'b1;
                    out_idx <= out_idx + 1;
                end else begin
                    valid <= 1'b0;
                    done <= 1'b1;
                end
            end

            FINISHED: begin
                done <= 1'b1;
                valid <= 1'b0;
            end
        endcase
    end
end

endmodule

module ranger_strength (
  input clk,
  input rst_n,
  input start,
  input [3:0] n,          // number of rangers (1 to 8)
  input [3:0] k,          // k up to 8
  input [9:0] x,          // x up to 1000
  input [9:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
  output reg [9:0] max_out,
  output reg [9:0] min_out,
  output reg done
);

// Parameters
parameter N = 8;
parameter DATA_WIDTH = 10;
parameter K_WIDTH = 4;

// State definitions
localparam IDLE = 3'b000;
localparam SORT = 3'b001;
localparam XOR = 3'b010;
localparam CHECK_K = 3'b011;
localparam FINISH = 3'b100;

// Registers
reg [2:0] state, next_state;
reg [K_WIDTH-1:0] k_count;
reg [2:0] sort_step; // 0 to 7
reg [DATA_WIDTH-1:0] arr [0:N-1]; // current array
reg [DATA_WIDTH-1:0] next_arr [0:N-1]; // next array

// Combinational logic for next array (sorting and XOR)
integer i;
always @(*) begin
  // Default: next_arr = arr
  for (i=0; i<N; i=i+1) next_arr[i] = arr[i];

  if (state == SORT) begin
    // Odd-even transposition sort step
    if (sort_step[0] == 0) begin
      // Even step: compare (0,1), (2,3), (4,5), (6,7) if within n
      if (n > 1 && 0 < n && 1 < n && arr[0] > arr[1]) begin
        next_arr[0] = arr[1];
        next_arr[1] = arr[0];
      end
      if (n > 3 && 2 < n && 3 < n && arr[2] > arr[3]) begin
        next_arr[2] = arr[3];
        next_arr[3] = arr[2];
      end
      if (n > 5 && 4 < n && 5 < n && arr[4] > arr[5]) begin
        next_arr[4] = arr[5];
        next_arr[5] = arr[4];
      end
      if (n > 7 && 6 < n && 7 < n && arr[6] > arr[7]) begin
        next_arr[6] = arr[7];
        next_arr[7] = arr[6];
      end
    end else begin
      // Odd step: compare (1,2), (3,4), (5,6) if within n
      if (n > 2 && 1 < n && 2 < n && arr[1] > arr[2]) begin
        next_arr[1] = arr[2];
        next_arr[2] = arr[1];
      end
      if (n > 4 && 3 < n && 4 < n && arr[3] > arr[4]) begin
        next_arr[3] = arr[4];
        next_arr[4] = arr[3];
      end
      if (n > 6 && 5 < n && 6 < n && arr[5] > arr[6]) begin
        next_arr[5] = arr[6];
        next_arr[6] = arr[5];
      end
    end
  end else if (state == XOR) begin
    // XOR even indices that are less than n
    for (i=0; i<N; i=i+1) begin
      if (i < n && i[0] == 0) // even index and within n
        next_arr[i] = arr[i] ^ x;
      else
        next_arr[i] = arr[i];
    end
  end
end

// Min and max calculation (combinational) for indices < n
reg [9:0] max_val, min_val;
always @(*) begin
  // Initialize with the first element if n>0, else 0
  if (n > 0) begin
    max_val = arr[0];
    min_val = arr[0];
  end else begin
    max_val = 0;
    min_val = 0;
  end
  for (i=1; i<N; i=i+1) begin
    if (i < n) begin
      if (arr[i] > max_val) max_val = arr[i];
      if (arr[i] < min_val) min_val = arr[i];
    end
  end
end

// State transition and register update
always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state <= IDLE;
    k_count <= 0;
    sort_step <= 0;
    done <= 0;
    max_out <= 0;
    min_out <= 0;
    // Reset array
    for (i=0; i<N; i=i+1) begin
      arr[i] <= 0;
    end
  end else begin
    case (state)
      IDLE: begin
        done <= 0;
        if (start) begin
          // Load input array
          arr[0] <= arr_0;
          arr[1] <= arr_1;
          arr[2] <= arr_2;
          arr[3] <= arr_3;
          arr[4] <= arr_4;
          arr[5] <= arr_5;
          arr[6] <= arr_6;
          arr[7] <= arr_7;
          k_count <= k;
          sort_step <= 0;
          state <= SORT;
        end
      end

      SORT: begin
        // Update array with next_arr
        for (i=0; i<N; i=i+1) arr[i] <= next_arr[i];
        sort_step <= sort_step + 1;
        if (sort_step == 3'd7) begin
          // After 8 cycles of sorting (0 to 7), we have sorted array
          sort_step <= 0;
          state <= XOR;
        end
      end

      XOR: begin
        // Update array with next_arr (which includes XOR)
        for (i=0; i<N; i=i+1) arr[i] <= next_arr[i];
        state <= CHECK_K;
      end

      CHECK_K: begin
        if (k_count > 0) begin
          k_count <= k_count - 1;
          state <= SORT;
        end else begin
          state <= FINISH;
        end
      end

      FINISH: begin
        // Compute min and max
        max_out <= max_val;
        min_out <= min_val;
        done <= 1;
        state <= IDLE;
      end

      default: state <= IDLE;
    endcase
  end
end

endmodule

module soda_bottles(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,              // Number of bottles (1-16)
    input wire [7:0] a [15:0],       // Soda amounts
    input wire [7:0] b [15:0],       // Bottle volumes
    output reg [3:0] k,              // Minimal number of bottles
    output reg [15:0] t,             // Minimal pouring time
    output reg done
);

// State machine states
localparam IDLE = 3'd0;
localparam COMPUTE_S = 3'd1;
localparam SORT = 3'd2;
localparam DP_INIT = 3'd3;
localparam DP_UPDATE = 3'd4;
localparam FIND_RESULT = 3'd5;
localparam COMPLETE = 3'd6;

reg [2:0] state;
reg [3:0] i, j, k_idx;
reg [15:0] S;                      // Total soda
reg [7:0] a_sorted [15:0];         // Sorted soda amounts
reg [7:0] b_sorted [15:0];         // Sorted bottle volumes
reg [15:0] dp_addr;                // Address for DP table
reg [11:0] dp_write_data;          // Data to write to DP table
reg [11:0] dp_read_data;           // Data read from DP table
reg dp_write_en;                   // DP table write enable
reg [15:0] max_v;                  // Maximum v for DP
reg [11:0] best_sum;               // Best sum for current k
reg [3:0] found_k;                 // Found k value
reg [15:0] found_t;                // Found t value

// DP table: [k][v] where k=0-15, v=0-S (max 4080)
// Stored as 12-bit values (sum of a_i)
// Address = {k_idx[3:0], v[11:0]} (v truncated to 12 bits since S<4096)
reg [11:0] dp_table [0:4095];      // 4K entries, each 12 bits

integer idx;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        k <= 0;
        t <= 0;
        S <= 0;
        dp_write_en <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= COMPUTE_S;
                    i <= 0;
                    S <= 0;
                end
            end

            COMPUTE_S: begin
                // Compute total soda S
                S <= S + a[i];
                if (i == n-1) begin
                    i <= 0;
                    state <= SORT;
                end else begin
                    i <= i + 1;
                end
            end

            SORT: begin
                // Bubble sort by b_i in descending order
                if (i < n-1) begin
                    if (b[i] < b[i+1]) begin
                        // Swap
                        a_sorted[i] <= a[i+1];
                        a_sorted[i+1] <= a[i];
                        b_sorted[i] <= b[i+1];
                        b_sorted[i+1] <= b[i];
                    end else begin
                        a_sorted[i] <= a[i];
                        a_sorted[i+1] <= a[i+1];
                        b_sorted[i] <= b[i];
                        b_sorted[i+1] <= b[i+1];
                    end
                    i <= i + 1;
                end else begin
                    i <= 0;
                    j <= 0;
                    k_idx <= 0;
                    state <= DP_INIT;
                end
            end

            DP_INIT: begin
                // Initialize DP table to -1 (invalid)
                if (k_idx < 16) begin
                    if (j <= S) begin
                        dp_table[{k_idx[3:0], j[11:0]}] <= 12'hFFF; // -1
                        j <= j + 1;
                    end else begin
                        j <= 0;
                        k_idx <= k_idx + 1;
                    end
                end else begin
                    // Set dp[0][0] = 0
                    dp_table[16'd0] <= 12'd0;
                    i <= 0;  // bottle index
                    k_idx <= 0;  // k index for DP update
                    j <= S;  // v index (start from S)
                    state <= DP_UPDATE;
                end
            end

            DP_UPDATE: begin
                // Update DP for each bottle
                if (i < n) begin
                    // Update in reverse order for k and v
                    if (k_idx > 0) begin
                        if (j > 0) begin
                            // Check if dp[k-1][v] is valid
                            dp_read_data <= dp_table[{k_idx[3:0] - 1'd1, j[11:0]}];
                            if (dp_table[{k_idx[3:0] - 1'd1, j[11:0]}] != 12'hFFF) begin
                                // Compute new v = min(S, j + b_sorted[i])
                                max_v <= (j + b_sorted[i] > S) ? S : (j + b_sorted[i]);
                                // Read current dp[k][max_v] for comparison
                                dp_read_data <= dp_table[{k_idx[3:0], max_v[11:0]}];
                                // Write if better
                                if (dp_table[{k_idx[3:0], max_v[11:0]}] < (dp_table[{k_idx[3:0] - 1'd1, j[11:0]}] + a_sorted[i])) begin
                                    dp_table[{k_idx[3:0], max_v[11:0]}] <= dp_table[{k_idx[3:0] - 1'd1, j[11:0]}] + a_sorted[i];
                                end
                            end
                            j <= j - 1;
                        end else begin
                            j <= S;
                            k_idx <= k_idx - 1;
                        end
                    end else begin
                        // Done for this bottle
                        i <= i + 1;
                        k_idx <= 15;  // Start from high k
                        j <= S;
                    end
                end else begin
                    // Done with all bottles
                    state <= FIND_RESULT;
                    k_idx <= 1;  // Start searching from k=1
                    best_sum <= 0;
                    found_k <= 0;
                end
            end

            FIND_RESULT: begin
                // Find minimal k such that dp[k][S] is valid
                if (k_idx <= n) begin
                    dp_read_data <= dp_table[{k_idx[3:0], S[11:0]}];
                    if (dp_table[{k_idx[3:0], S[11:0]}] != 12'hFFF) begin
                        found_k <= k_idx;
                        found_t <= S - dp_table[{k_idx[3:0], S[11:0]}];
                        state <= COMPLETE;
                    end else begin
                        k_idx <= k_idx + 1;
                    end
                end else begin
                    // Should not happen, but fallback
                    found_k <= n;
                    found_t <= 0;
                    state <= COMPLETE;
                end
            end

            COMPLETE: begin
                k <= found_k;
                t <= found_t;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module hanabi_min_hints (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire input_valid,
    input wire [7:0] input_card,   // {color[3:0], value[3:0]}
    input wire [4:0] n_in,         // number of cards (1-16)
    output reg done,
    output reg [3:0] answer
);

// Interface specification:
// - Colors: 0=R, 1=G, 2=B, 3=Y, 4=W (4-bit encoding)
// - Values: 0=1, 1=2, 2=3, 3=4, 4=5 (4-bit encoding)
// - Pattern: {color[3:0], value[3:0]} -> 10-bit pattern = (1<<color) | (1<<(5+value))
// - Input: Serial cards over n_in cycles with input_valid=1
// - Output: Minimum hints (0-10) when done=1
// - Timing: Done pulses for 1 cycle when computation completes
// - Reset: Active-low rst_n clears all state

// States: IDLE=0, READ=1, INIT_MASK=2, CHECK_MASK=3, NEXT_MASK=4, DONE=5
// Internal: distinct_cards[0:7] (10-bit patterns), mask (10-bit), min_hints (4-bit)
// Algorithm: For each mask (0-1023), compute signatures = distinct_cards & mask
//            Check if all signatures are distinct; update min_hints with popcount(mask)

endmodule

module robot_checker (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] instruction,  // 1-bit per char: 1=F, 0=T
    input wire [3:0] target_x,     // 4-bit signed (-8 to 7)
    input wire [3:0] target_y,
    output reg result,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam PARSE = 2'b01;
    localparam CHECK = 2'b10;
    localparam DONE = 2'b11;

    reg [1:0] state;
    reg [2:0] seg_count;       // Number of segments found
    reg [3:0] segments [0:4];  // 5 segments max
    reg [2:0] idx;             // Bit index for parsing

    // Wires for computation
    wire signed [4:0] x0_s, x2_s, x4_s, y1_s, y3_s;
    wire signed [4:0] x_target_s, y_target_s;
    wire signed [4:0] x_target_adj;
    wire signed [4:0] x_cand [0:8];
    wire signed [4:0] y_cand [0:8];
    wire x_check, y_check;

    // Parse logic (combinational)
    reg [2:0] count;
    reg [2:0] seg_idx;
    integer i;

    always @(*) begin
        // Initialize segments
        segments[0] = 0;
        segments[1] = 0;
        segments[2] = 0;
        segments[3] = 0;
        segments[4] = 0;

        count = 0;
        seg_idx = 0;

        for (i = 0; i < 8; i = i + 1) begin
            if (instruction[i]) begin
                count = count + 1;
            end else begin
                if (seg_idx < 5) begin
                    segments[seg_idx] = count;
                    seg_idx = seg_idx + 1;
                end
                count = 0;
            end
        end
        if (seg_idx < 5) begin
            segments[seg_idx] = count;
        end
    end

    // Assign segments to axes
    assign x0_s = $signed({1'b0, segments[0]});
    assign x2_s = $signed({1'b0, segments[2]});
    assign x4_s = $signed({1'b0, segments[4]});
    assign y1_s = $signed({1'b0, segments[1]});
    assign y3_s = $signed({1'b0, segments[3]});

    // Target assignments
    assign x_target_s = $signed(target_x);
    assign y_target_s = $signed(target_y);
    assign x_target_adj = x_target_s - x0_s;

    // Generate candidate sets
    assign x_cand[0] = 5'sd0;
    assign x_cand[1] = x2_s;
    assign x_cand[2] = -x2_s;
    assign x_cand[3] = x4_s;
    assign x_cand[4] = -x4_s;
    assign x_cand[5] = x2_s + x4_s;
    assign x_cand[6] = x2_s - x4_s;
    assign x_cand[7] = -x2_s + x4_s;
    assign x_cand[8] = -x2_s - x4_s;

    assign y_cand[0] = 5'sd0;
    assign y_cand[1] = y1_s;
    assign y_cand[2] = -y1_s;
    assign y_cand[3] = y3_s;
    assign y_cand[4] = -y3_s;
    assign y_cand[5] = y1_s + y3_s;
    assign y_cand[6] = y1_s - y3_s;
    assign y_cand[7] = -y1_s + y3_s;
    assign y_cand[8] = -y1_s - y3_s;

    // Check functions
    assign x_check = (x_target_adj == x_cand[0]) || (x_target_adj == x_cand[1]) ||
                     (x_target_adj == x_cand[2]) || (x_target_adj == x_cand[3]) ||
                     (x_target_adj == x_cand[4]) || (x_target_adj == x_cand[5]) ||
                     (x_target_adj == x_cand[6]) || (x_target_adj == x_cand[7]) ||
                     (x_target_adj == x_cand[8]);

    assign y_check = (y_target_s == y_cand[0]) || (y_target_s == y_cand[1]) ||
                     (y_target_s == y_cand[2]) || (y_target_s == y_cand[3]) ||
                     (y_target_s == y_cand[4]) || (y_target_s == y_cand[5]) ||
                     (y_target_s == y_cand[6]) || (y_target_s == y_cand[7]) ||
                     (y_target_s == y_cand[8]);

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 0;
            done <= 0;
            idx <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) state <= PARSE;
                end

                PARSE: begin
                    // Parse done in combinational logic
                    state <= CHECK;
                end

                CHECK: begin
                    result <= x_check && y_check;
                    state <= DONE;
                end

                DONE: begin
                    done <= 1;
                    if (!start) state <= IDLE;
                end
            endcase
        end
    end
endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] instruction,
    input wire [3:0] target_x,
    input wire [3:0] target_y,
