    output wire done
);
    robot_checker rc (
        .clk(clk),
        .rst_n(rst_n),
        .start(start),
        .instruction(instruction),
        .target_x(target_x),
        .target_y(target_y),
        .result(result),
        .done(done)
    );
endmodule

module find_min_extensions (
    input clk,
    input rst_n,
    input start,
    input [15:0] a, b, h, w,
    input [17:0] mult0, mult1, mult2, mult3, mult4, mult5, mult6, mult7,
    output reg [4:0] k,
    output reg done
);

    // State definitions
    localparam STATE_IDLE = 3'b000;
    localparam STATE_CHECK0 = 3'b001;
    localparam STATE_INIT = 3'b010;
    localparam STATE_UPDATE = 3'b011;
    localparam STATE_CHECK = 3'b100;
    localparam STATE_NEXT = 3'b101;
    localparam STATE_FAIL = 3'b110;
    localparam STATE_DONE = 3'b111;

    // Maximum set size for non-dominated pairs
    localparam SET_SIZE = 256;

    // Registers for state machine
    reg [2:0] state, next_state;
    reg [3:0] i, next_i;  // Current multiplier index (0-8)
    reg [4:0] next_k;
    reg next_done;

    // Current set and next set for DP
    reg [SET_SIZE-1:0] curr_valid, next_valid;
    reg [16:0] curr_h_mult [SET_SIZE-1:0];
    reg [16:0] curr_w_mult [SET_SIZE-1:0];
    reg [16:0] next_h_mult [SET_SIZE-1:0];
    reg [16:0] next_w_mult [SET_SIZE-1:0];

    // Multiplier array
    wire [17:0] mult [0:7];
    assign mult[0] = mult0;
    assign mult[1] = mult1;
    assign mult[2] = mult2;
    assign mult[3] = mult3;
    assign mult[4] = mult4;
    assign mult[5] = mult5;
    assign mult[6] = mult6;
    assign mult[7] = mult7;

    // Temporary registers for update
    reg [16:0] cap_h, cap_w;
    reg [33:0] temp_product;
    reg [16:0] new_h, new_w;
    reg condition_met;

    // Pointer for iterating through current set
    reg [7:0] ptr;
    reg [7:0] next_ptr;
    reg [7:0] set_count;
    reg [7:0] next_set_count;

    // Variables for dominance checking
    reg is_dominated;
    reg [7:0] dom_ptr;

    // Combinational next state logic
    always @(*) begin
        next_state = state;
        next_i = i;
        next_k = k;
        next_done = done;
        next_ptr = ptr;
        next_set_count = set_count;
        next_valid = curr_valid;
        for (integer j = 0; j < SET_SIZE; j = j + 1) begin
            next_h_mult[j] = curr_h_mult[j];
            next_w_mult[j] = curr_w_mult[j];
        end

        case (state)
            STATE_IDLE: begin
                if (start) begin
                    next_state = STATE_CHECK0;
                    next_done = 0;
                    next_k = 5'b11111;  // Initialize to -1
                end
            end

            STATE_CHECK0: begin
                // Check if no extensions needed
                if ((h >= a && w >= b) || (h >= b && w >= a)) begin
                    next_k = 0;
                    next_state = STATE_DONE;
                end else begin
                    next_state = STATE_INIT;
                end
            end

            STATE_INIT: begin
                // Initialize set with (1,1)
                next_valid = 1'b1;
                next_h_mult[0] = 17'd1;
                next_w_mult[0] = 17'd1;
                for (integer j = 1; j < SET_SIZE; j = j + 1) begin
                    next_valid[j] = 1'b0;
                end
                next_i = 0;
                next_ptr = 0;
                next_set_count = 1;
                next_state = STATE_UPDATE;
            end

            STATE_UPDATE: begin
                // Compute caps to prevent overflow
                cap_h = (a > b) ? ((a / h) + 1) : ((b / h) + 1);
                cap_w = (a > b) ? ((a / w) + 1) : ((b / w) + 1);

                // Process current pair
                if (ptr < SET_SIZE && curr_valid[ptr]) begin
                    // Option 1: multiply h by multiplier[i]
                    temp_product = curr_h_mult[ptr] * mult[i];
                    if (temp_product > cap_h) new_h = cap_h;
                    else new_h = temp_product[16:0];
                    new_w = curr_w_mult[ptr];

                    // Check dominance and add to next set
                    is_dominated = 0;
                    for (dom_ptr = 0; dom_ptr < next_set_count && !is_dominated; dom_ptr = dom_ptr + 1) begin
                        if (next_valid[dom_ptr] && 
                            next_h_mult[dom_ptr] >= new_h && 
                            next_w_mult[dom_ptr] >= new_w) begin
                            is_dominated = 1;
                        end
                    end
                    if (!is_dominated && next_set_count < SET_SIZE) begin
                        next_h_mult[next_set_count] = new_h;
                        next_w_mult[next_set_count] = new_w;
                        next_valid[next_set_count] = 1'b1;
                        next_set_count = next_set_count + 1;
                    end

                    // Option 2: multiply w by multiplier[i]
                    temp_product = curr_w_mult[ptr] * mult[i];
                    if (temp_product > cap_w) new_w = cap_w;
                    else new_w = temp_product[16:0];
                    new_h = curr_h_mult[ptr];

                    // Check dominance and add to next set
                    is_dominated = 0;
                    for (dom_ptr = 0; dom_ptr < next_set_count && !is_dominated; dom_ptr = dom_ptr + 1) begin
                        if (next_valid[dom_ptr] && 
                            next_h_mult[dom_ptr] >= new_h && 
                            next_w_mult[dom_ptr] >= new_w) begin
                            is_dominated = 1;
                        end
                    end
                    if (!is_dominated && next_set_count < SET_SIZE) begin
                        next_h_mult[next_set_count] = new_h;
                        next_w_mult[next_set_count] = new_w;
                        next_valid[next_set_count] = 1'b1;
                        next_set_count = next_set_count + 1;
                    end

                    next_ptr = ptr + 1;
                    next_state = STATE_UPDATE;
                end else begin
                    next_ptr = 0;
                    next_state = STATE_CHECK;
                end
            end

            STATE_CHECK: begin
                // Check if any pair satisfies the condition
                condition_met = 0;
                for (integer j = 0; j < next_set_count && !condition_met; j = j + 1) begin
                    if (next_valid[j]) begin
                        if (((h * next_h_mult[j] >= a && w * next_w_mult[j] >= b) ||
                             (h * next_h_mult[j] >= b && w * next_w_mult[j] >= a))) begin
                            condition_met = 1;
                            next_k = i + 1;
                        end
                    end
                end
                if (condition_met) begin
                    next_state = STATE_DONE;
                end else begin
                    next_state = STATE_NEXT;
                end
            end

            STATE_NEXT: begin
                if (i >= 7) begin
                    next_state = STATE_FAIL;
                end else begin
                    // Copy next set to current set
                    next_i = i + 1;
                    next_ptr = 0;
                    next_set_count = 0;
                    next_valid = 0;
                    // Move next set to current set
                    for (integer j = 0; j < SET_SIZE; j = j + 1) begin
                        if (curr_valid[j]) begin
                            next_h_mult[j] = curr_h_mult[j];
                            next_w_mult[j] = curr_w_mult[j];
                            next_valid[j] = 1'b1;
                            next_set_count = next_set_count + 1;
                        end else begin
                            next_h_mult[j] = 0;
                            next_w_mult[j] = 0;
                            next_valid[j] = 1'b0;
                        end
                    end
                    next_state = STATE_UPDATE;
                end
            end

            STATE_FAIL: begin
                next_k = 5'b11111;  // -1
                next_state = STATE_DONE;
            end

            STATE_DONE: begin
                next_done = 1;
                if (!start) next_state = STATE_IDLE;
            end
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_IDLE;
            i <= 0;
            k <= 5'b11111;
            done <= 0;
            ptr <= 0;
            set_count <= 0;
            curr_valid <= 0;
            for (integer j = 0; j < SET_SIZE; j = j + 1) begin
                curr_h_mult[j] <= 0;
                curr_w_mult[j] <= 0;
            end
        end else begin
            state <= next_state;
            i <= next_i;
            k <= next_k;
            done <= next_done;
            ptr <= next_ptr;
            set_count <= next_set_count;
            curr_valid <= next_valid;
            for (integer j = 0; j < SET_SIZE; j = j + 1) begin
                curr_h_mult[j] <= next_h_mult[j];
                curr_w_mult[j] <= next_w_mult[j];
            end
        end
    end

endmodule

module resistor_network (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [63:0] a_in,
    input wire [63:0] b_in,
    output reg [63:0] result,
    output reg done
);

    // State encoding
    localparam IDLE = 1'b0;
    localparam COMPUTE = 1'b1;

    // Internal registers
    reg state;
    reg [63:0] a, b, count;

    // Next state logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            a <= 64'd0;
            b <= 64'd0;
            count <= 64'd0;
            result <= 64'd0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        a <= a_in;
                        b <= b_in;
                        count <= 64'd0;
                        state <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    if (b == 64'd0) begin
                        result <= count;
                        done <= 1'b1;
                        state <= IDLE;
                    end else begin
                        // quotient = a / b (integer division)
                        count <= count + (a / b);
                        // Update: a = b, b = a % b
                        a <= b;
                        b <= a % b;
                    end
                end
            endcase
        end
    end

endmodule

Module: max_chessmen

// Module to compute maximum number of chessmen for a given n x m board
// with Manhattan distance exactly 3.
// Inputs: n, m (16-bit, 0..65535)
// Output: result (32-bit)
// The logic is based on mathematical analysis:
//   if n == 1: result = m - min(m%6, 6 - m%6)
//   elif n == 2: 
//        if m == 2: result = 0
//        elif m == 3: result = 4
//        elif m == 7: result = 12
//        else: result = 2*m
//   else: result = n*m - 1 if both n and m are odd, else n*m
// Note: The module automatically sorts n and m so that n <= m.

module max_chessmen (
    input [15:0] n,
    input [15:0] m,
    output reg [31:0] result
);

    // Sort inputs to have n_min <= n_max
    wire [15:0] n_min;
    wire [15:0] n_max;
    assign n_min = (n < m) ? n : m;
    assign n_max = (n < m) ? m : n;

    always @(*) begin
        // Case 1: one dimension is 1
        if (n_min == 16'd1) begin
            reg [3:0] r = n_max % 6;
            reg [3:0] min_val = (r < 3'd3) ? r : (6 - r);
            result = n_max - min_val;
        end
        // Case 2: one dimension is 2
        else if (n_min == 16'd2) begin
            if (n_max == 16'd2)
                result = 32'd0;
            else if (n_max == 16'd3)
                result = 32'd4;
            else if (n_max == 16'd7)
                result = 32'd12;
            else
                result = 32'd2 * n_max;
        end
        // Case 3: both dimensions >= 3
        else begin
            result = n_min * n_max;
            // Subtract one if both are odd
            if (n_min[0] && n_max[0])
                result = result - 32'd1;
        end
    end

endmodule

module rescue_rangers(
    input clk, rst_n, start,
    input [15:0] x1, y1, x2, y2,  // Original coordinates (signed)
    input [15:0] v_max, t,         // Max speed, wind change time (unsigned)
    input [15:0] vx, vy, wx, wy,   // Wind vectors (signed)
    output reg [31:0] time_result,  // Q16.16 fixed-point result
    output reg done
);

// Parameters and state definitions
parameter IDLE = 2'b00, COMPUTE = 2'b01, ITERATE = 2'b10, FINISH = 2'b11;
reg [1:0] state;
reg [5:0] iterations;  // 50 iterations for 1e-6 precision
reg [31:0] low, high, mid;  // Q16.16 fixed-point
reg condition_met;

// Fixed-point scaling: 1.0 = 16'h10000 (Q16.16)
wire [31:0] t_scaled = t << 16;  // Convert t to Q16.16

// Intermediate calculations (combinational)
always @(*) begin
    // Wind period: t1 = min(mid, t_scaled), t2 = max(mid - t_scaled, 0)
    reg [31:0] t1, t2;
    reg [31:0] dx, dy;  // Q16.16
    reg [63:0] dx_sq, dy_sq;  // Q32.32
    reg [63:0] left_sq, right_sq;  // Q32.32

    if (mid < t_scaled) begin
        t1 = mid;
        t2 = 0;
    end else begin
        t1 = t_scaled;
        t2 = mid - t_scaled;
    end

    // Wind displacement: (vx*t1 + wx*t2, vy*t1 + wy*t2)
    // Multiply 16-bit signed by Q16.16, result is Q32.16, then shift to Q16.16
    reg [31:0] wind_x = ($signed(vx) * $signed(t1)) + ($signed(wx) * $signed(t2));
    reg [31:0] wind_y = ($signed(vy) * $signed(t1)) + ($signed(wy) * $signed(t2));
    wind_x = wind_x >>> 16;  // Convert to Q16.16
    wind_y = wind_y >>> 16;

    // Remaining displacement
    dx = {x2 - x1, 16'b0} - wind_x;  // Convert coord diff to Q16.16
    dy = {y2 - y1, 16'b0} - wind_y;

    // Square and compare
    dx_sq = $signed(dx) * $signed(dx);  // Q32.32
    dy_sq = $signed(dy) * $signed(dy);
    left_sq = dx_sq + dy_sq;

    // Right side: (v_max * mid)^2
    reg [31:0] v_max_mid = $signed(v_max) * $signed(mid);  // Q16.16 * Q16.16 = Q32.32
    right_sq = v_max_mid * v_max_mid;  // Q64.64, but we only need comparison

    // Compare left_sq <= right_sq (both Q32.32, but we can compare as unsigned)
    condition_met = (left_sq <= right_sq);
end

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        time_result <= 0;
        iterations <= 0;
        low <= 0;
        high <= 32'h4F1A0000;  // 1e9 in Q16.16: 1e9 * 65536 = 0x4F1A0000
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= COMPUTE;
                    iterations <= 0;
                    low <= 0;
                    high <= 32'h4F1A0000;
                    done <= 0;
                end
            end

            COMPUTE: begin
                mid <= (low + high) >> 1;  // Divide by 2
                state <= ITERATE;
            end

            ITERATE: begin
                if (condition_met)
                    high <= mid;
                else
                    low <= mid;

                if (iterations == 50) begin
                    state <= FINISH;
                    time_result <= mid;  // Or use high for final result
                end else begin
                    iterations <= iterations + 1;
                    state <= COMPUTE;
                end
            end

            FINISH: begin
                done <= 1;
                if (!start) state <= IDLE;
            end
        endcase
    end
end

endmodule

module maze_solver (
    input clk, rst_n, start,
    input [3:0] n, m,  // Grid dimensions (1-8)
    input [5:0] k,     // Walls to add (0-63)
    input [1:0] grid_in [0:7][0:7],  // 0=wall, 1=empty
    output reg [1:0] grid_out [0:7][0:7],  // 0=wall, 1=empty, 2=X
    output reg done
);

// State definitions
localparam IDLE = 0, INIT_SCAN = 1, SCAN = 2, BFS_INIT = 3;
localparam BFS_LOOP = 4, BFS_DEQUEUE = 5, BFS_PROCESS = 6;
localparam BFS_ENQUEUE = 7, MARK = 8, MARK_LOOP = 9, DONE = 10;

// Internal registers
reg [3:0] state;
reg [2:0] row_idx, col_idx;
reg [5:0] s, target, visited_count;
reg found_start;
reg [2:0] start_row, start_col;
reg [2:0] cur_row, cur_col;
reg [1:0] neighbor_count;

// Arrays (8x8)
reg [0:7] visited [0:7];
reg [0:7] in_queue [0:7];
reg [5:0] queue [0:63];  // {row[2:0], col[2:0]}
reg [6:0] head, tail;    // 0-64

// Next state logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) state <= INIT_SCAN;
            end

            INIT_SCAN: begin
                row_idx <= 0;
                col_idx <= 0;
                s <= 0;
                found_start <= 0;
                state <= SCAN;
            end

            SCAN: begin
                if (grid_in[row_idx][col_idx] == 1) begin
                    s <= s + 1;
                    if (!found_start) begin
                        start_row <= row_idx;
                        start_col <= col_idx;
                        found_start <= 1;
                    end
                end
                if (row_idx == n-1 && col_idx == m-1) state <= BFS_INIT;
                else begin
                    if (col_idx == m-1) begin
                        col_idx <= 0;
                        row_idx <= row_idx + 1;
                    end else col_idx <= col_idx + 1;
                    state <= SCAN;
                end
            end

            BFS_INIT: begin
                // Reset arrays
                for (integer i=0; i<8; i=i+1) begin
                    visited[i] <= 0;
                    in_queue[i] <= 0;
                end
                head <= 0;
                tail <= 0;
                visited_count <= 0;
                target <= (s > k) ? (s - k) : 0;
                if (s > 0) begin
                    queue[0] <= {start_row, start_col};
                    tail <= 1;
                    in_queue[start_row][start_col] <= 1;
                end
                state <= BFS_LOOP;
            end

            BFS_LOOP: begin
                if (visited_count == target) state <= MARK;
                else if (head == tail) state <= MARK; // Queue empty
                else state <= BFS_DEQUEUE;
            end

            BFS_DEQUEUE: begin
                cur_row <= queue[head][5:3];
                cur_col <= queue[head][2:0];
                head <= head + 1;
                state <= BFS_PROCESS;
            end

            BFS_PROCESS: begin
                if (visited[cur_row][cur_col] == 0) begin
                    visited[cur_row][cur_col] <= 1;
                    visited_count <= visited_count + 1;
                    if (visited_count + 1 == target) state <= MARK;
                    else begin
                        state <= BFS_ENQUEUE;
                        neighbor_count <= 0;
                    end
                end else state <= BFS_LOOP;
            end

            BFS_ENQUEUE: begin
                case (neighbor_count)
                    0: if (cur_row < n-1 && grid_in[cur_row+1][cur_col] == 1 && 
                           !visited[cur_row+1][cur_col] && !in_queue[cur_row+1][cur_col]) begin
                           queue[tail] <= {cur_row+1, cur_col};
                           tail <= tail + 1;
                           in_queue[cur_row+1][cur_col] <= 1;
                       end
                    1: if (cur_row > 0 && grid_in[cur_row-1][cur_col] == 1 && 
                           !visited[cur_row-1][cur_col] && !in_queue[cur_row-1][cur_col]) begin
                           queue[tail] <= {cur_row-1, cur_col};
                           tail <= tail + 1;
                           in_queue[cur_row-1][cur_col] <= 1;
                       end
                    2: if (cur_col < m-1 && grid_in[cur_row][cur_col+1] == 1 && 
                           !visited[cur_row][cur_col+1] && !in_queue[cur_row][cur_col+1]) begin
                           queue[tail] <= {cur_row, cur_col+1};
                           tail <= tail + 1;
                           in_queue[cur_row][cur_col+1] <= 1;
                       end
                    3: if (cur_col > 0 && grid_in[cur_row][cur_col-1] == 1 && 
                           !visited[cur_row][cur_col-1] && !in_queue[cur_row][cur_col-1]) begin
                           queue[tail] <= {cur_row, cur_col-1};
                           tail <= tail + 1;
                           in_queue[cur_row][cur_col-1] <= 1;
                       end
                endcase
                if (neighbor_count == 3) state <= BFS_LOOP;
                else begin
                    neighbor_count <= neighbor_count + 1;
                    state <= BFS_ENQUEUE;
                end
            end

            MARK: begin
                row_idx <= 0;
                col_idx <= 0;
                state <= MARK_LOOP;
            end

            MARK_LOOP: begin
                if (grid_in[row_idx][col_idx] == 1 && visited[row_idx][col_idx] == 0)
                    grid_out[row_idx][col_idx] <= 2;
                else
                    grid_out[row_idx][col_idx] <= grid_in[row_idx][col_idx];
                if (row_idx == n-1 && col_idx == m-1) state <= DONE;
                else begin
                    if (col_idx == m-1) begin
                        col_idx <= 0;
                        row_idx <= row_idx + 1;
                    end else col_idx <= col_idx + 1;
                    state <= MARK_LOOP;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

