module apple_tree #(
  parameter N = 16,      // Maximum number of nodes
  parameter DATA_WIDTH = 4 // Bit width for node indices (1-16)
) (
  input wire clk,
  input wire rst_n,
  input wire start,
  input wire load,           // Load signal for parent input
  input wire [DATA_WIDTH-1:0] parent,   // Parent of current node (1-based)
  output reg [DATA_WIDTH-1:0] result,
  output reg done
);

  // Internal signals and registers
  reg [DATA_WIDTH-1:0] depth_mem [0:N-1];   // Depth storage for each node
  reg parity_mem [0:15];         // Parity storage for depths 0-15
  reg [DATA_WIDTH-1:0] total;    // Total apples collected
  reg [DATA_WIDTH-1:0] idx;      // Current node index (0 to N-1)
  reg [2:0] state;               // State machine

  // States
  localparam IDLE = 3'b000;
  localparam INIT = 3'b001;
  localparam LOAD = 3'b010;
  localparam DONE = 3'b011;

  integer i;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      done <= 0;
      result <= 0;
      total <= 0;
      idx <= 0;
      // Reset parity memory
      for (i = 0; i < 16; i = i + 1) begin
        parity_mem[i] <= 0;
      end
    end else begin
      case (state)
        IDLE: begin
          if (start) begin
            // Initialize node 1 (root)
            depth_mem[0] <= 0;
            // Update parity for depth 0
            parity_mem[0] <= ~parity_mem[0];
            if (parity_mem[0] == 0)
              total <= total + 1;
            else
              total <= total - 1;
            idx <= 1;  // Next node will be node 2 (index 1)
            state <= INIT;
            done <= 0;
          end
        end

        INIT: begin
          state <= LOAD;
        end

        LOAD: begin
          if (load && idx < N) begin
            // Compute depth: depth = depth_mem[parent-1] + 1
            // Update depth memory for current node
            depth_mem[idx] <= depth_mem[parent-1] + 1;
            // Update parity and total for the new depth
            if (parity_mem[depth_mem[parent-1] + 1] == 0) begin
              total <= total + 1;
            end else begin
              total <= total - 1;
            end
            parity_mem[depth_mem[parent-1] + 1] <= ~parity_mem[depth_mem[parent-1] + 1];
            idx <= idx + 1;
            if (idx == N-1) begin
              state <= DONE;
              done <= 1;
              result <= total;
            end
          end else if (idx >= N) begin
            state <= DONE;
            done <= 1;
            result <= total;
          end
        end

        DONE: begin
          // Hold result until reset
          done <= 1;
        end

        default: state <= IDLE;
      endcase
    end
  end

endmodule

module gcd_split (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    output reg done,
    output reg result,
    output reg [7:0] assignment
);

// State machine states
localparam IDLE = 3'b000;
localparam COMPUTE = 3'b001;
localparam CHECK = 3'b010;
localparam FINISHED = 3'b011;

reg [2:0] state;
reg [7:0] mask;  // Current split mask (bit i = 1 means arr[i] in group 1)
reg [7:0] gcd1, gcd2;
reg [7:0] count1, count2;

// Helper: GCD function for two numbers
function automatic [7:0] gcd2;
    input [7:0] a, b;
    begin
        if (b == 0) gcd2 = a;
        else gcd2 = gcd2(b, a % b);
    end
endfunction

// Helper: GCD of array subset
function automatic [7:0] gcd_array;
    input [7:0] arr [0:7];
    input [7:0] mask;
    input [7:0] current_gcd;
    integer i;
    begin
        gcd_array = current_gcd;
        for (i = 0; i < 8; i = i + 1) begin
            if (mask[i]) begin
                if (gcd_array == 0)
                    gcd_array = arr[i];
                else
                    gcd_array = gcd2(gcd_array, arr[i]);
            end
        end
    end
endfunction

// Combinational logic for GCD computation
reg [7:0] arr_reg [0:7];
reg [7:0] gcd1_temp, gcd2_temp;
reg [7:0] count1_temp, count2_temp;

always @(*) begin
    // Initialize
    gcd1_temp = 0;
    gcd2_temp = 0;
    count1_temp = 0;
    count2_temp = 0;

    // Compute GCD for group 1
    for (integer i = 0; i < 8; i = i + 1) begin
        if (mask[i]) begin
            if (gcd1_temp == 0)
                gcd1_temp = arr_reg[i];
            else
                gcd1_temp = gcd2(gcd1_temp, arr_reg[i]);
            count1_temp = count1_temp + 1;
        end
    end

    // Compute GCD for group 2
    for (integer i = 0; i < 8; i = i + 1) begin
        if (~mask[i]) begin
            if (gcd2_temp == 0)
                gcd2_temp = arr_reg[i];
            else
                gcd2_temp = gcd2(gcd2_temp, arr_reg[i]);
            count2_temp = count2_temp + 1;
        end
    end
end

// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        assignment <= 8'b0;
        mask <= 8'b0;
        gcd1 <= 0;
        gcd2 <= 0;
        count1 <= 0;
        count2 <= 0;
        // Initialize array registers
        for (integer i = 0; i < 8; i = i + 1) begin
            arr_reg[i] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Capture inputs
                    arr_reg[0] <= arr_0;
                    arr_reg[1] <= arr_1;
                    arr_reg[2] <= arr_2;
                    arr_reg[3] <= arr_3;
                    arr_reg[4] <= arr_4;
                    arr_reg[5] <= arr_5;
                    arr_reg[6] <= arr_6;
                    arr_reg[7] <= arr_7;
                    mask <= 8'b00000001;  // Start with first element in group 1
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                // Use combinational results
                gcd1 <= gcd1_temp;
                gcd2 <= gcd2_temp;
                count1 <= count1_temp;
                count2 <= count2_temp;
                state <= CHECK;
            end

            CHECK: begin
                // Check if this split is valid
                if (count1 > 0 && count2 > 0 && gcd1 == 1 && gcd2 == 1) begin
                    result <= 1;
                    assignment <= mask;
                    done <= 1;
                    state <= FINISHED;
                end else begin
                    // Try next mask
                    if (mask == 8'b11111110) begin
                        // All possibilities tried
                        result <= 0;
                        assignment <= 8'b0;
                        done <= 1;
                        state <= FINISHED;
                    end else begin
                        // Increment mask to next valid split (skip 0 and 255)
                        if (mask == 8'b00000000) 
                            mask <= 8'b00000001;
                        else if (mask == 8'b11111111)
                            mask <= 8'b00000001;
                        else
                            mask <= mask + 1;
                        state <= COMPUTE;
                    end
                end
            end

            FINISHED: begin
                // Wait for reset or new start
                if (!start) begin
                    done <= 0;
                end
            end
        endcase
    end
end

endmodule

module boomerang_4x4 (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [1:0] a0, a1, a2, a3,
    output reg done,
    output reg valid,
    output reg target_valid,
    output reg [2:0] target_row,
    output reg [2:0] target_col
);

// Parameters and states
localparam IDLE = 3'b000;
localparam PROCESS = 3'b001;
localparam OUTPUT = 3'b010;
localparam NEXT_COLUMN = 3'b011;
localparam DONE = 3'b100;
localparam ERROR = 3'b101;

// Registers
reg [2:0] state;
reg [1:0] a_reg0, a_reg1, a_reg2, a_reg3;
reg signed [2:0] col_index;
reg [1:0] sp_one;
reg [1:0] sp_two;
reg [1:0] stack_one_row [3:0];
reg [1:0] stack_one_col [3:0];
reg [1:0] stack_two_row [3:0];
reg [1:0] stack_two_col [3:0];
reg [1:0] target1_row, target1_col, target2_row, target2_col;
reg [1:0] remaining_targets;
reg [1:0] output_index;

wire [1:0] a_current;

assign a_current = (col_index == 3) ? a_reg3 :
                   (col_index == 2) ? a_reg2 :
                   (col_index == 1) ? a_reg1 :
                   a_reg0;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        valid <= 0;
        target_valid <= 0;
        sp_one <= 0;
        sp_two <= 0;
        col_index <= 3;
        remaining_targets <= 0;
        output_index <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    a_reg0 <= a0;
                    a_reg1 <= a1;
                    a_reg2 <= a2;
                    a_reg3 <= a3;
                    sp_one <= 0;
                    sp_two <= 0;
                    col_index <= 3;
                    remaining_targets <= 0;
                    output_index <= 0;
                    done <= 0;
                    valid <= 0;
                    target_valid <= 0;
                    state <= PROCESS;
                end
            end

            PROCESS: begin
                if (col_index < 0) begin
                    state <= DONE;
                end else begin
                    case (a_current)
                        2'b00: begin
                            state <= NEXT_COLUMN;
                        end
                        2'b01: begin
                            stack_one_row[sp_one] <= col_index;
                            stack_one_col[sp_one] <= col_index;
                            sp_one <= sp_one + 1;
                            target1_row <= col_index;
                            target1_col <= col_index;
                            remaining_targets <= 1;
                            output_index <= 0;
                            state <= OUTPUT;
                        end
                        2'b10: begin
                            if (sp_one == 0) begin
                                state <= ERROR;
                            end else begin
                                target1_row <= stack_one_row[sp_one-1];
                                target1_col <= col_index;
                                stack_two_row[sp_two] <= stack_one_row[sp_one-1];
                                stack_two_col[sp_two] <= col_index;
                                sp_two <= sp_two + 1;
                                sp_one <= sp_one - 1;
                                remaining_targets <= 1;
                                output_index <= 0;
                                state <= OUTPUT;
                            end
                        end
                        2'b11: begin
                            if (sp_two > 0) begin
                                target1_row <= col_index;
                                target1_col <= stack_two_col[sp_two-1];
                                target2_row <= col_index;
                                target2_col <= col_index;
                                stack_two_row[sp_two-1] <= col_index;
                                stack_two_col[sp_two-1] <= col_index;
                                remaining_targets <= 2;
                                output_index <= 0;
                                state <= OUTPUT;
                            end else if (sp_one > 0) begin
                                target1_row <= col_index;
                                target1_col <= stack_one_col[sp_one-1];
                                target2_row <= col_index;
                                target2_col <= col_index;
                                stack_two_row[sp_two] <= col_index;
                                stack_two_col[sp_two] <= col_index;
                                sp_two <= sp_two + 1;
                                sp_one <= sp_one - 1;
                                remaining_targets <= 2;
                                output_index <= 0;
                                state <= OUTPUT;
                            end else begin
                                state <= ERROR;
                            end
                        end
                        default: state <= NEXT_COLUMN;
                    endcase
                end
            end

            OUTPUT: begin
                if (remaining_targets > 0) begin
                    target_valid <= 1;
                    if (output_index == 0) begin
                        target_row <= target1_row + 1;
                        target_col <= target1_col + 1;
                    end else begin
                        target_row <= target2_row + 1;
                        target_col <= target2_col + 1;
                    end
                    remaining_targets <= remaining_targets - 1;
                    output_index <= output_index + 1;
                end else begin
                    target_valid <= 0;
                    state <= NEXT_COLUMN;
                end
            end

            NEXT_COLUMN: begin
                col_index <= col_index - 1;
                state <= PROCESS;
            end

            DONE: begin
                done <= 1;
                valid <= 1;
            end

            ERROR: begin
                done <= 1;
                valid <= 0;
                target_valid <= 0;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

cocotb_testbench:
import cocotb
from cocotb.triggers import Timer, RisingEdge, FallingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure
import cocotb.log

# CONFIGURATION
DATA_WIDTH = 2
ROW_COL_WIDTH = 3
N = 4
MAX_TARGETS = 8
CLK_PERIOD_NS = 10
MAX_CYCLES = 50

# HELPER FUNCTIONS

def is_value_defined(value):
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    try:
        return int(value)
    except ValueError:
        return default

def to_signed(val, bits):
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(value, bits):
    max_val = (1 << bits) - 1
    if value < 0:
        return from_signed(max(-((1 << (bits-1))), min((1 << (bits-1)) - 1, value)), bits)
    return min(max_val, max(0, value))

async def reset_dut(dut, cycles=2):
    dut.rst_n.value = 0
    if has_signal(dut, 'start'):
        dut.start.value = 0
    for _ in range(cycles):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f'Timeout: done not asserted after {max_cycles} cycles')

# SOLVE FUNCTION
def solve(a):
    n = len(a)
    ans = []
    one = []
    tt = []
    for i in range(n-1, -1, -1):
        val = a[i]
        if val == 0:
            continue
        if val == 1:
            ans.append((i+1, i+1))
            one.append((i+1, i+1))
        elif val == 2:
            if not one:
                return None
            row, _ = one.pop()
            ans.append((row, i+1))
            tt.append((row, i+1))
        elif val == 3:
            if tt:
                row, col = tt.pop()
                ans.append((i+1, col))
                ans.append((i+1, i+1))
                tt.append((i+1, i+1))
            elif one:
                row, col = one.pop()
                ans.append((i+1, col))
                ans.append((i+1, i+1))
                tt.append((i+1, i+1))
            else:
                return None
    return ans

# MAIN TEST
@cocotb.test(timeout_time=1000, timeout_unit='ms')
async def test_boomerang(dut):
    cocotb.start_soon(Clock(dut.clk, CLK_PERIOD_NS, units='ns').start())
    await reset_dut(dut)

    captured = []
    async def monitor():
        while True:
            await RisingEdge(dut.target_valid)
            if int(dut.target_valid) == 1:
                row = int(dut.target_row)
                col = int(dut.target_col)
                captured.append((row, col))
    cocotb.start_soon(monitor())

    test_cases = [
        ([0,0,0,0], 'All zeros'),
        ([1,1,1,1], 'All ones'),
        ([2,2,2,2], 'All twos'),
        ([3,3,3,3], 'All threes'),
        ([2,0,3,0], 'Two and three'),
        ([1,2,3,1], 'Mixed'),
        ([3,2,1,0], 'Decreasing'),
        ([2,1,2,3], 'Complex'),
    ]

    for i, (a_list, desc) in enumerate(test_cases):
        dut._log.info(f'Test {i+1}: {desc} - a={a_list}')
        captured.clear()

        dut.a0.value = a_list[0]
        dut.a1.value = a_list[1]
        dut.a2.value = a_list[2]
        dut.a3.value = a_list[3]

        dut.start.value = 1
        await RisingEdge(dut.clk)
        dut.start.value = 0

        await wait_for_done(dut)

        expected = solve(a_list)
        valid = int(dut.valid.value)

        if expected is None:
            if valid:
                raise TestFailure(f'Expected invalid, but valid=1')
            if len(captured) > 0:
                raise TestFailure(f'Expected no targets, but got {len(captured)}')
            dut._log.info('  PASS (correctly invalid)')
        else:
            if not valid:
                raise TestFailure(f'Expected valid, but valid=0')
            await Timer(1, units='ns')
            if len(captured) != len(expected):
                raise TestFailure(f'Expected {len(expected)} targets, got {len(captured)}')
            for j, (exp_row, exp_col) in enumerate(expected):
                if j >= len(captured):
                    raise TestFailure(f'Missing target {j}')
                row, col = captured[j]
                if (row, col) != (exp_row, exp_col):
                    raise TestFailure(f'Target {j}: expected ({exp_row},{exp_col}), got ({row},{col})')
            dut._log.info('  PASS')

    dut._log.info('All tests passed')

