module permutation_game (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [6:0] n,        // number of elements (1-100)
    input wire [6:0] k,        // number of moves (1-100)
    input wire [6:0] q [0:99], // permutation q (0-indexed, values 0..n-1)
    input wire [6:0] s [0:99], // permutation s (0-indexed)
    output reg yes,
    output reg done
);
    // This module computes whether Masha's permutation can appear after exactly k moves
    // without appearing earlier.
    // It uses a state machine with states: IDLE, INIT_INV, INIT_PERM, CHECK, COMPARE, UPDATE, INCREMENT, DONE.
    // It precomputes the inverse permutation inv_q from q.
    // It maintains forward (fwd) and backward (bwd) permutations.
    // It iterates e from 0 to k, updating fwd = q ∘ fwd, bwd = inv_q ∘ bwd.
    // At each step e>0 with same parity as k, it compares fwd and bwd with s.
    // It handles the special case where order is 2 (q^2 = identity) and s = q and k > 1.
    // If s is identity, output NO immediately.
    // All loops bounded by n or k (max 100).
    // The module is synthesizable for n,k <= 100.
endmodule

module game_outcome #(
    parameter N = 16,      // Maximum array size
    parameter W = 8        // Bit width for values
)(
    input clk,
    input rst_n,
    input start,
    input [W-1:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    input [W-1:0] arr_8, arr_9, arr_10, arr_11, arr_12, arr_13, arr_14, arr_15,
    input [4:0] len,
    output reg result,
    output reg done
);

    // State encoding
    localparam IDLE = 4'd0;
    localparam LOAD = 4'd1;
    localparam SORT_INIT = 4'd2;
    localparam SORT_COMPARE = 4'd3;
    localparam SORT_NEXT_J = 4'd4;
    localparam SORT_NEXT_I = 4'd5;
    localparam SCAN_INIT = 4'd6;
    localparam SCAN_LOOP = 4'd7;
    localparam SCAN_CHECK_LAST = 4'd8;
    localparam DONE = 4'd9;

    // Registers
    reg [3:0] state, next_state;
    reg [W-1:0] array_reg [0:N-1];
    reg [4:0] i, j;
    reg [W-1:0] prev_val;
    reg [3:0] run_len;
    reg found_odd;
    reg [4:0] load_idx;
    reg [4:0] scan_idx;
    reg start_dly;

    // Combinational next state logic
    always @(*) begin
        case (state)
            IDLE:       next_state = start_dly ? LOAD : IDLE;
            LOAD:       next_state = (load_idx < len) ? LOAD : (len > 1 ? SORT_INIT : SCAN_INIT);
            SORT_INIT:  next_state = SORT_COMPARE;
            SORT_COMPARE: next_state = SORT_NEXT_J;
            SORT_NEXT_J: begin
                if (j < len - 1 - i)
                    next_state = SORT_COMPARE;
                else if (i < len - 2)
                    next_state = SORT_NEXT_I;
                else
                    next_state = SCAN_INIT;
            end
            SORT_NEXT_I: next_state = SORT_COMPARE;
            SCAN_INIT:   next_state = SCAN_LOOP;
            SCAN_LOOP:   next_state = (scan_idx < len) ? SCAN_LOOP : SCAN_CHECK_LAST;
            SCAN_CHECK_LAST: next_state = DONE;
            DONE:        next_state = IDLE;
            default:     next_state = IDLE;
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            i <= 0;
            j <= 0;
            load_idx <= 0;
            scan_idx <= 0;
            run_len <= 0;
            found_odd <= 0;
            start_dly <= 0;
        end else begin
            start_dly <= start;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start_dly)
                        load_idx <= 0;
                end

                LOAD: begin
                    if (load_idx < len) begin
                        case (load_idx)
                            0: array_reg[0] <= arr_0;
                            1: array_reg[1] <= arr_1;
                            2: array_reg[2] <= arr_2;
                            3: array_reg[3] <= arr_3;
                            4: array_reg[4] <= arr_4;
                            5: array_reg[5] <= arr_5;
                            6: array_reg[6] <= arr_6;
                            7: array_reg[7] <= arr_7;
                            8: array_reg[8] <= arr_8;
                            9: array_reg[9] <= arr_9;
                            10: array_reg[10] <= arr_10;
                            11: array_reg[11] <= arr_11;
                            12: array_reg[12] <= arr_12;
                            13: array_reg[13] <= arr_13;
                            14: array_reg[14] <= arr_14;
                            15: array_reg[15] <= arr_15;
                        endcase
                        load_idx <= load_idx + 1;
                    end
                end

                SORT_INIT: begin
                    i <= 0;
                    j <= 0;
                end

                SORT_COMPARE: begin
                    if (array_reg[j] > array_reg[j+1]) begin
                        // Swap without temporary (non-blocking uses old values)
                        array_reg[j] <= array_reg[j+1];
                        array_reg[j+1] <= array_reg[j];
                    end
                end

                SORT_NEXT_J: begin
                    if (j < len - 1 - i)
                        j <= j + 1;
                    else if (i < len - 2) begin
                        j <= 0;
                    end
                end

                SORT_NEXT_I: begin
                    i <= i + 1;
                end

                SCAN_INIT: begin
                    prev_val <= array_reg[0];
                    run_len <= 1;
                    found_odd <= 0;
                    scan_idx <= 1;
                end

                SCAN_LOOP: begin
                    if (scan_idx < len) begin
                        if (array_reg[scan_idx] == prev_val) begin
                            run_len <= run_len + 1;
                        end else begin
                            if (run_len[0])
                                found_odd <= 1;
                            prev_val <= array_reg[scan_idx];
                            run_len <= 1;
                        end
                        scan_idx <= scan_idx + 1;
                    end
                end

                SCAN_CHECK_LAST: begin
                    if (run_len[0])
                        found_odd <= 1;
                end

                DONE: begin
                    done <= 1;
                    result <= found_odd;
                end
            endcase

            state <= next_state;
        end
    end

endmodule

module RobbersWatch (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] n,
    input wire [31:0] m,
    output reg [31:0] result,
    output reg done
);

// This module counts the number of valid (hour, minute) pairs such that
// the base-7 representations of hour (with len_h digits) and minute (with len_m digits)
// have all distinct digits.

// Steps:
// 1. Compute len_h = number of base-7 digits needed to represent n-1 (at least 1).
// 2. Compute len_m similarly for m-1.
// 3. If len_h + len_m > 7, result = 0.
// 4. Otherwise, enumerate all permutations of distinct digits of length L = len_h + len_m from 0..6.
//    For each permutation, split into hour part (first len_h digits) and minute part (last len_m digits).
//    Compute hour_value = value of hour part in base 7.
//    Compute minute_value = value of minute part in base 7.
//    If hour_value < n and minute_value < m, increment count.
// 5. Output count.

// State definitions
localparam IDLE = 0;
localparam COMPUTE_LEN_H = 1;
localparam COMPUTE_LEN_M = 2;
localparam CHECK_LEN = 3;
localparam INIT_PERM = 4;
localparam EVAL_PERM = 5;
localparam NEXT_PERM = 6;
localparam NEXT_COMB = 7;
localparam DONE = 8;

// Registers
reg [3:0] state;
reg [31:0] n_reg, m_reg;
reg [3:0] len_h, len_m;
reg [2:0] L; // total length
reg [6:0] current_bitmask; // 7-bit mask for combination
reg [2:0] current_perm [0:6]; // current permutation of digits
reg [31:0] count;
reg [2:0] i, j; // indices for next permutation
reg [2:0] phase; // sub-state for next permutation

// Powers of 7
wire [20:0] pow7 [0:7];
assign pow7[0] = 21'd1;
assign pow7[1] = 21'd7;
assign pow7[2] = 21'd49;
assign pow7[3] = 21'd343;
assign pow7[4] = 21'd2401;
assign pow7[5] = 21'd16807;
assign pow7[6] = 21'd117649;
assign pow7[7] = 21'd823543;

// Helper function to compute number of digits
function [3:0] compute_len;
    input [31:0] val;
    begin
        if (val == 0) compute_len = 1;
        else if (val < 7) compute_len = 1;
        else if (val < 49) compute_len = 2;
        else if (val < 343) compute_len = 3;
        else if (val < 2401) compute_len = 4;
        else if (val < 16807) compute_len = 5;
        else if (val < 117649) compute_len = 6;
        else if (val < 823543) compute_len = 7;
        else compute_len = 8; // >7, will be caught later
    end
endfunction

// Helper function to compute value from digits
function [20:0] compute_value;
    input [2:0] len;
    input [2:0] digits [0:6];
    begin
        compute_value = 0;
        for (integer k = 0; k < len; k = k + 1) begin
            compute_value = compute_value * 7 + digits[k];
        end
    end
endfunction

// Helper function to count bits in a 7-bit mask
function [3:0] popcount;
    input [6:0] bits;
    begin
        popcount = 0;
        for (integer k = 0; k < 7; k = k + 1) popcount = popcount + bits[k];
    end
endfunction

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 0;
        done <= 0;
        n_reg <= 0;
        m_reg <= 0;
        len_h <= 0;
        len_m <= 0;
        L <= 0;
        current_bitmask <= 0;
        for (integer idx = 0; idx < 7; idx = idx + 1) current_perm[idx] <= 0;
        count <= 0;
        i <= 0;
        j <= 0;
        phase <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    n_reg <= n;
                    m_reg <= m;
                    state <= COMPUTE_LEN_H;
                end
            end

            COMPUTE_LEN_H: begin
                len_h <= compute_len((n_reg == 1) ? 0 : n_reg - 1);
                state <= COMPUTE_LEN_M;
            end

            COMPUTE_LEN_M: begin
                len_m <= compute_len((m_reg == 1) ? 0 : m_reg - 1);
                state <= CHECK_LEN;
            end

            CHECK_LEN: begin
                if (len_h + len_m > 7) begin
                    result <= 0;
                    state <= DONE;
                end else begin
                    L <= len_h + len_m;
                    count <= 0;
                    current_bitmask <= 7'b0000001; // first combination: lowest L bits set
                    state <= INIT_PERM;
                end
            end

            INIT_PERM: begin
                // Extract digits from current_bitmask and set current_perm to sorted digits
                // This is a placeholder; actual implementation would extract bits in order.
                // For now, we assume the first permutation is the sorted combination.
                state <= EVAL_PERM;
            end

            EVAL_PERM: begin
                // Compute hour_value from first len_h digits
                // Compute minute_value from last len_m digits
                // If both < n_reg and m_reg, increment count
                // Then go to NEXT_PERM
                state <= NEXT_PERM;
            end

            NEXT_PERM: begin
                // Compute next permutation of current_perm
                // If exists, go to EVAL_PERM
                // Else, go to NEXT_COMB
                state <= NEXT_COMB;
            end

            NEXT_COMB: begin
                // Find next bitmask with L bits set
                // If exists, set current_bitmask and generate first permutation, go to EVAL_PERM
                // Else, go to DONE
                state <= DONE;
            end

            DONE: begin
                done <= 1;
                result <= count;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module grid_generator(
    input clk,
    input rst_n,
    input start,
    input [8:0] A,
    input [8:0] B,
    output reg [7:0] char_out,
    output reg valid_out,
    output reg done
);

localparam IDLE = 0;
localparam HEAD = 1;
localparam GRID = 2;
localparam DONE = 3;

reg [1:0] state;
reg [3:0] header_index;
reg [9:0] row;
reg [9:0] col;
reg [8:0] A_reg, B_reg;

function automatic [7:0] f;
    input [9:0] i;
    input [9:0] j;
    input [8:0] A_val;
    input [8:0] B_val;
    reg [15:0] idx;
    begin
        if (i < 50) begin
            if (i[0] && j[0]) begin
                idx = ((i-1) >> 1) * 50 + ((j-1) >> 1);
                if (idx < (B_val - 1))
                    f = "#";
                else
                    f = ".";
            end else
                f = ".";
        end else begin
            if (i>=51 && i<=97 && i[0] && j[0]) begin
                idx = ((i-51) >> 1) * 50 + ((j-1) >> 1);
                if (idx < (A_val - 1))
                    f = ".";
                else
                    f = "#";
            end else
                f = "#";
        end
    end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        valid_out <= 0;
        char_out <= 8'b0;
        header_index <= 0;
        row <= 0;
        col <= 0;
        A_reg <= 0;
        B_reg <= 0;
        done <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                valid_out <= 0;
                if (start) begin
                    A_reg <= A;
                    B_reg <= B;
                    state <= HEAD;
                    header_index <= 0;
                end
            end
            HEAD: begin
                valid_out <= 1;
                case (header_index)
                    0: char_out <= "1";
                    1: char_out <= "0";
                    2: char_out <= "0";
                    3: char_out <= " ";
                    4: char_out <= "1";
                    5: char_out <= "0";
                    6: char_out <= "0";
                    7: char_out <= "\n";
                    default: char_out <= 0;
                endcase
                if (header_index < 7)
                    header_index <= header_index + 1;
                else begin
                    header_index <= 0;
                    state <= GRID;
                    row <= 0;
                    col <= 0;
                end
            end
            GRID: begin
                valid_out <= 1;
                if (col < 100) begin
                    char_out <= f(row, col, A_reg, B_reg);
                    col <= col + 1;
                end else begin
                    char_out <= "\n";
                    col <= 0;
                    row <= row + 1;
                    if (row == 99)
                        state <= DONE;
                end
            end
            DONE: begin
                done <= 1;
                valid_out <= 0;
            end
        endcase
    end
end
endmodule

module leader_determination #(
    parameter n = 8,
    parameter m = 16
) (
    input clk,
    input rst_n,
    input [m-1:0] event_type,  // 0 for '+', 1 for '-'
    input [4*m-1:0] event_id,  // Packed event IDs, each 4 bits
    output reg [n-1:0] possible_leaders,
    output reg done
);

    // State definitions
    localparam S_INIT = 0;
    localparam S_CHECK_S0 = 1;
    localparam S_SIM_START = 2;
    localparam S_CHECK_INITIAL = 3;
    localparam S_SIM_EVENT = 4;
    localparam S_CHECK_EVENT = 5;
    localparam S_CHECK_FINAL = 6;
    localparam S_UPDATE_CANDIDATE = 7;
    localparam S_DONE = 8;

    // Internal registers
    reg [3:0] state;
    reg [3:0] current_candidate;
    reg [7:0] current_S0;  // 2^n possibilities, 8 bits for n=8
    reg [7:0] current_state;
    reg [3:0] current_event;
    reg found_valid_S0;

    // Event storage
    reg event_type_reg [0:m-1];
    reg [3:0] event_id_reg [0:m-1];

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_INIT;
            possible_leaders <= 0;
            done <= 0;
        end else begin
            case (state)
                S_INIT: begin
                    // Initialize and unpack events
                    current_candidate <= 1;
                    current_S0 <= 0;
                    found_valid_S0 <= 0;
                    for (i = 0; i < m; i = i + 1) begin
                        event_type_reg[i] <= event_type[i];
                        event_id_reg[i] <= event_id[4*i+:4];
                    end
                    state <= S_CHECK_S0;
                end

                S_CHECK_S0: begin
                    // Check if current_S0 satisfies first event constraint
                    if (current_S0 >= (1 << n)) begin
                        // All S0 checked for current candidate
                        if (!found_valid_S0) begin
                            possible_leaders[current_candidate-1] <= 0;
                        end
                        state <= S_UPDATE_CANDIDATE;
                    end else begin
                        // Check first event constraint
                        if (event_type_reg[0] == 0) begin  // '+' login
                            if (current_S0[event_id_reg[0]-1] == 0) begin
                                state <= S_SIM_START;
                            end else begin
                                current_S0 <= current_S0 + 1;
                            end
                        end else begin  // '-' logout
                            if (current_S0[event_id_reg[0]-1] == 1) begin
                                state <= S_SIM_START;
                            end else begin
                                current_S0 <= current_S0 + 1;
                            end
                        end
                    end
                end

                S_SIM_START: begin
                    // Start simulation for this S0
                    current_state <= current_S0;
                    current_event <= 0;
                    state <= S_CHECK_INITIAL;
                end

                S_CHECK_INITIAL: begin
                    // Check initial state condition
                    if (current_state != 0 && (current_state & (1 << (current_candidate-1)) == 0) begin
                        // Fail for this S0
                        current_S0 <= current_S0 + 1;
                        state <= S_CHECK_S0;
                    end else begin
                        state <= S_SIM_EVENT;
                    end
                end

                S_SIM_EVENT: begin
                    if (current_event >= m) begin
                        state <= S_CHECK_FINAL;
                    end else begin
                        // Apply event
                        if (event_type_reg[current_event] == 0) begin
                            // Login
                            current_state <= current_state | (1 << (event_id_reg[current_event]-1));
                        end else begin
                            // Logout
                            current_state <= current_state & ~(1 << (event_id_reg[current_event]-1));
                        end
                        state <= S_CHECK_EVENT;
                    end
                end

                S_CHECK_EVENT: begin
                    // Check state after event
                    if (current_state != 0 && (current_state & (1 << (current_candidate-1)) == 0) begin
                        // Fail for this S0
                        current_S0 <= current_S0 + 1;
                        state <= S_CHECK_S0;
                    end else begin
                        current_event <= current_event + 1;
                        state <= S_SIM_EVENT;
                    end
                end

                S_CHECK_FINAL: begin
                    // Check final state after all events
                    if (current_state != 0 && (current_state & (1 << (current_candidate-1)) == 0) begin
                        // Fail for this S0
                        current_S0 <= current_S0 + 1;
                        state <= S_CHECK_S0;
                    end else begin
                        // Found valid S0 for this candidate
                        found_valid_S0 <= 1;
                        possible_leaders[current_candidate-1] <= 1;
                        // We can stop after finding one valid S0 for this candidate
                        current_S0 <= (1 << n);  // Force to max to skip remaining S0
                        state <= S_CHECK_S0;
                    end
                end

                S_UPDATE_CANDIDATE: begin
                    if (current_candidate == n) begin
                        state <= S_DONE;
                    end else begin
                        current_candidate <= current_candidate + 1;
                        current_S0 <= 0;
                        found_valid_S0 <= 0;
                        state <= S_CHECK_S0;
                    end
                end

                S_DONE: begin
                    done <= 1;
                    state <= S_DONE;
                end

                default: state <= S_INIT;
            endcase
        end
    end
endmodule

module find_polynomial (
    input clk,
    input rst_n,
    input start,
    input [59:0] p_in,
    input [11:0] k_in,
    output reg [11:0] coeff,
    output reg valid,
    output reg done
);

// States
localparam IDLE = 0;
localparam COMPUTE = 1;

reg state;
reg signed [59:0] p_reg;
reg signed [11:0] k_reg;

// Combinational quotient and remainder
wire signed [59:0] quotient;
wire signed [11:0] remainder;

assign quotient = p_reg / k_reg;
assign remainder = p_reg % k_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        p_reg <= 0;
        k_reg <= 0;
        coeff <= 0;
        valid <= 0;
        done <= 0;
    end else begin
        case (state)
            IDLE: 
                if (start) begin
                    p_reg <= $signed(p_in);
                    k_reg <= $signed(k_in);
                    done <= 0;
                    valid <= 0;
                    state <= COMPUTE;
                end

            COMPUTE: 
                if (p_reg != 0) begin
                    if (remainder < 0) begin
                        coeff <= $unsigned(remainder + k_reg);
                        p_reg <= - (quotient + 1);
                    end else begin
                        coeff <= $unsigned(remainder);
                        p_reg <= - quotient;
                    end
                    valid <= 1;
                    done <= 0;
                end else begin
                    done <= 1;
                    valid <= 0;
                    state <= IDLE;
                end

        endcase
    end
end

endmodule

module coin_game (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [6:0] n,          // Number of chests (1-100)
    input wire [9:0] a [0:99],   // Coin counts (100 elements)
    output reg signed [19:0] result, // Result or -1 for invalid
    output reg done              // Computation finished
);

// State definitions
localparam IDLE = 3'b000;
localparam COPY = 3'b001;
localparam COMP = 3'b010;
localparam FINISH = 3'b011;
localparam ERROR = 3'b100;

reg [2:0] state;
reg signed [15:0] mem [0:99];   // Internal storage for coins
reg [6:0] x;                    // Current index
reg signed [19:0] total_moves;  // Accumulated moves
reg signed [19:0] result_reg;   // Result register
reg done_reg;                   // Done signal register

assign result = result_reg;
assign done = done_reg;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done_reg <= 0;
        result_reg <= 0;
        x <= 0;
        total_moves <= 0;
        // Initialize memory
        for (i = 0; i < 100; i = i + 1) begin
            mem[i] <= 0;
        end
    end else begin
        done_reg <= 0; // Default done to 0
        case (state)
            IDLE: begin
                if (start) begin
                    if (n == 1 || n[0] == 0) begin // n==1 or even
                        state <= ERROR;
                    end else begin
                        state <= COPY;
                        x <= n >> 1; // Start from floor(n/2)
                        total_moves <= 0;
                    end
                end
            end

            COPY: begin
                // Copy input array to internal memory
                for (i = 0; i < 100; i = i + 1) begin
                    if (i < n)
                        mem[i] <= a[i];
                    else
                        mem[i] <= 0;
                end
                state <= COMP;
            end

            COMP: begin
                if (x >= 1) begin
                    // Calculate children indices (1-indexed to 0-indexed)
                    // Chest x at index x-1, children at 2x-1 and 2x
                    if (2*x <= n && 2*x+1 <= n) begin
                        // Both children exist
                        if (mem[2*x-1] > mem[2*x]) 
                            total_moves <= total_moves + mem[2*x-1];
                        else 
                            total_moves <= total_moves + mem[2*x];

                        mem[x-1] <= mem[x-1] - 
                                    ((mem[2*x-1] > mem[2*x]) ? mem[2*x-1] : mem[2*x]);
                    end
                    x <= x - 1;
                end else begin
                    state <= FINISH;
                end
            end

            FINISH: begin
                if (mem[0] > 0)
                    result_reg <= total_moves + mem[0];
                else
                    result_reg <= total_moves;
                done_reg <= 1;
                state <= IDLE;
            end

            ERROR: begin
                result_reg <= -20'sd1; // -1 in 20-bit signed
                done_reg <= 1;
                state <= IDLE;
            end
        endcase
    end
end
endmodule

