module subset_sum_mask (
    input clk, rst_n,
    input start,
    input [3:0] n,        // Number of coins (1-8)
    input [4:0] k,        // Target sum (1-16)
    input [7:0] coin_in,  // Coin value (8-bit)
    output done,
    output [16:0] result_mask  // Bitmask of possible x values
);

parameter MAX_N = 8;
parameter MAX_K = 16;

// State encoding
localparam IDLE = 2'b00;
localparam PROCESS = 2'b01;
localparam DONE = 2'b10;

reg [1:0] state, next_state;
reg [3:0] counter, next_counter;
reg [16:0] dp [0:MAX_K];  // dp[s] = bitmask of subset sums for total sum s
reg [4:0] k_reg;
reg [3:0] n_reg;

integer s;

// State and counter update
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        counter <= 0;
        k_reg <= 0;
        n_reg <= 0;
        // Reset dp: only dp[0] = 1 (subset sum 0 possible with total sum 0)
        for (s = 0; s <= MAX_K; s = s + 1) begin
            dp[s] <= 0;
        end
        dp[0] <= 1;
    end else begin
        state <= next_state;
        counter <= next_counter;
        if (state == IDLE && start) begin
            k_reg <= k;
            n_reg <= n;
        end
        // Process coin in PROCESS state
        if (state == PROCESS) begin
            for (s = 0; s <= MAX_K; s = s + 1) begin
                if (s < coin_in) begin
                    dp[s] <= dp[s];
                end else begin
                    // Update: existing subsets + subsets without coin + subsets with coin
                    dp[s] <= dp[s] | dp[s-coin_in] | (dp[s-coin_in] << coin_in);
                end
            end
        end
    end
end

// Next state logic
always @(*) begin
    next_state = state;
    next_counter = counter;
    case (state)
        IDLE: 
            if (start) begin
                next_state = PROCESS;
                next_counter = 0;
            end
        PROCESS: 
            begin
                next_counter = counter + 1;
                if (counter + 1 == n_reg) begin
                    next_state = DONE;
                end
            end
        DONE: 
            next_state = DONE;
    endcase
end

assign done = (state == DONE);
assign result_mask = (state == DONE) ? dp[k_reg] : 0;

endmodule

module golden_circle (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [4:0] n,      // number of restaurants, max 16
    input wire [8:0] k,      // distance between restaurants, max 256
    input wire [7:0] a,      // distance from start to nearest restaurant, max 128
    input wire [7:0] b,      // distance from first stop to nearest restaurant, max 128
    output reg [11:0] min_stops, // minimum number of stops
    output reg [11:0] max_stops, // maximum number of stops
    output reg done               // computation finished
);

    // Data width for nk, l, gcd, stops (12 bits: max 4096)
    localparam DATA_WIDTH = 12;
    localparam N_WIDTH = 5;
    localparam K_WIDTH = 9;
    localparam A_WIDTH = 8;
    localparam B_WIDTH = 8;

    // State definitions
    localparam IDLE = 3'd0;
    localparam CALC_L = 3'd1;
    localparam COMPUTE_GCD = 3'd2;
    localparam COMPUTE_STOPS = 3'd3;
    localparam UPDATE_MIN_MAX = 3'd4;
    localparam NEXT_COMBO = 3'd5;
    localparam NEXT_I = 3'd6;
    localparam DONE = 3'd7;

    // Registers
    reg [2:0] state;
    reg [DATA_WIDTH-1:0] nk_reg;          // n*k
    reg [N_WIDTH-1:0] i_reg;              // current i (0..n-1)
    reg [1:0] combo_reg;                  // 0..3 for four combinations
    reg [DATA_WIDTH-1:0] l_reg;           // current l value
    reg [DATA_WIDTH-1:0] min_reg, max_reg;
    reg [DATA_WIDTH-1:0] stops_temp;
    reg gcd_start;
    reg gcd_done_flag;
    reg [DATA_WIDTH-1:0] gcd_result_reg;

    // GCD module internal signals
    reg [DATA_WIDTH-1:0] gcd_a, gcd_b, gcd_rem;
    reg [1:0] gcd_state;
    localparam GCD_IDLE = 2'd0;
    localparam GCD_MOD = 2'd1;
    localparam GCD_UPDATE = 2'd2;

    // Combinational signals
    wire [DATA_WIDTH-1:0] i_k = i_reg * k; // i*k
    wire signed [DATA_WIDTH:0] nk_signed = nk_reg; // signed version for comparison
    reg signed [DATA_WIDTH:0] l_temp_signed; // signed temporary l
    wire [DATA_WIDTH-1:0] gcd_result = (l_reg == 0) ? nk_reg : gcd_result_reg;

    // GCD block (sequential)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            gcd_state <= GCD_IDLE;
            gcd_done_flag <= 0;
            gcd_result_reg <= 0;
        end else begin
            gcd_done_flag <= 0;
            case (gcd_state)
                GCD_IDLE: begin
                    if (gcd_start) begin
                        if (gcd_b == 0) begin
                            gcd_result_reg <= gcd_a;
                            gcd_done_flag <= 1;
                        end else begin
                            gcd_state <= GCD_MOD;
                        end
                    end
                end
                GCD_MOD: begin
                    gcd_rem <= gcd_a % gcd_b;
                    gcd_state <= GCD_UPDATE;
                end
                GCD_UPDATE: begin
                    gcd_a <= gcd_b;
                    gcd_b <= gcd_rem;
                    if (gcd_rem == 0) begin
                        gcd_result_reg <= gcd_b;
                        gcd_done_flag <= 1;
                        gcd_state <= GCD_IDLE;
                    end else begin
                        gcd_state <= GCD_MOD;
                    end
                end
            endcase
        end
    end

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            min_stops <= 0;
            max_stops <= 0;
            min_reg <= {DATA_WIDTH{1'b1}}; // max value
            max_reg <= 0;
            i_reg <= 0;
            combo_reg <= 0;
            gcd_start <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        nk_reg <= n * k;
                        i_reg <= 0;
                        combo_reg <= 0;
                        min_reg <= {DATA_WIDTH{1'b1}};
                        max_reg <= 0;
                        state <= CALC_L;
                    end
                end

                CALC_L: begin
                    // Compute l_temp based on combo
                    case (combo_reg)
                        2'd0: l_temp_signed = i_k + b - a;
                        2'd1: l_temp_signed = i_k - b - a;
                        2'd2: l_temp_signed = i_k + b - (k - a);
                        2'd3: l_temp_signed = i_k - b - (k - a);
                        default: l_temp_signed = 0;
                    endcase
                    // Adjust to [0, nk_reg-1]
                    if (l_temp_signed >= nk_signed) begin
                        l_reg <= l_temp_signed - nk_signed;
                    end else if (l_temp_signed < 0) begin
                        l_reg <= l_temp_signed + nk_signed;
                    end else begin
                        l_reg <= l_temp_signed[DATA_WIDTH-1:0];
                    end
                    state <= COMPUTE_GCD;
                end

                COMPUTE_GCD: begin
                    if (l_reg == 0) begin
                        // If l is zero, gcd is nk
                        gcd_result_reg <= nk_reg;
                        state <= COMPUTE_STOPS;
                    end else begin
                        if (!gcd_start && !gcd_done_flag) begin
                            gcd_start <= 1;
                            gcd_a <= nk_reg;
                            gcd_b <= l_reg;
                        end else if (gcd_done_flag) begin
                            gcd_start <= 0;
                            state <= COMPUTE_STOPS;
                        end
                    end
                end

                COMPUTE_STOPS: begin
                    // stops = nk / gcd
                    if (gcd_result != 0) begin
                        stops_temp <= nk_reg / gcd_result;
                    end else begin
                        stops_temp <= 0; // should not happen
                    end
                    state <= UPDATE_MIN_MAX;
                end

                UPDATE_MIN_MAX: begin
                    if (stops_temp < min_reg) begin
                        min_reg <= stops_temp;
                    end
                    if (stops_temp > max_reg) begin
                        max_reg <= stops_temp;
                    end
                    state <= NEXT_COMBO;
                end

                NEXT_COMBO: begin
                    if (combo_reg < 2'd3) begin
                        combo_reg <= combo_reg + 1;
                        state <= CALC_L;
                    end else begin
                        combo_reg <= 0;
                        state <= NEXT_I;
                    end
                end

                NEXT_I: begin
                    if (i_reg < n - 1) begin
                        i_reg <= i_reg + 1;
                        state <= CALC_L;
                    end else begin
                        state <= DONE;
                    end
                end

                DONE: begin
                    min_stops <= min_reg;
                    max_stops <= max_reg;
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module duel_game (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] initial_state,  // 8-bit initial state (0=down, 1=up)
    input wire [3:0] k,              // flip length (1-8)
    output reg [1:0] result,         // 0=Tokitsukaze, 1=Quailty, 2=Once again
    output reg done
);

    // Constants
    parameter MAX_CYCLES = 256;
    parameter STATE_WIDTH = 8;
    parameter MAX_K = 8;

    // Internal state
    reg [STATE_WIDTH-1:0] current_state;
    reg [7:0] cycle_count;
    reg [1:0] game_state;  // 0=playing, 1=toki_win, 2=quailty_win, 3=draw
    reg [STATE_WIDTH-1:0] state_history [0:15];  // History for cycle detection (last 16 states)
    reg [3:0] history_index;
    reg [STATE_WIDTH-1:0] temp_state;

    // Helper wires for state analysis
    wire all_same;
    wire [STATE_WIDTH-1:0] flipped_up;
    wire [STATE_WIDTH-1:0] flipped_down;
    wire can_win_next;

    // Check if all bits are the same
    assign all_same = (current_state == 8'b00000000) || (current_state == 8'b11111111);

    // Check winning moves for current player
    assign can_win_next = check_win(current_state, k);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= 8'b0;
            cycle_count <= 8'b0;
            game_state <= 2'b0;
            history_index <= 4'b0;
            done <= 1'b0;
            result <= 2'b0;
        end else if (start && !done) begin
            // Initialize game
            current_state <= initial_state;
            cycle_count <= 8'b0;
            history_index <= 4'b0;
            if (all_same) begin
                // Already uniform - Tokitsukaze wins immediately
                game_state <= 2'b01;  // Tokitsukaze
                done <= 1'b1;
                result <= 2'b00;
            end else begin
                game_state <= 2'b00;  // Playing
                done <= 1'b0;
            end
        end else if (game_state == 2'b00 && !done) begin
            // Game logic
            if (cycle_count >= MAX_CYCLES) begin
                game_state <= 2'b11;  // Draw
                done <= 1'b1;
                result <= 2'b10;  // Once again
            end else if (can_win_next) begin
                // Current player can win
                game_state <= (cycle_count[0] == 1'b0) ? 2'b01 : 2'b10;  // Tokitsukaze on even cycles, Quailty on odd
                done <= 1'b1;
                result <= (cycle_count[0] == 1'b0) ? 2'b00 : 2'b01;
            end else begin
                // Check for draw condition (cycle detection)
                if (is_in_history(current_state, state_history, history_index)) begin
                    game_state <= 2'b11;  // Draw
                    done <= 1'b1;
                    result <= 2'b10;  // Once again
                end else begin
                    // Make a move (simulate optimal play)
                    // For simplicity, we flip the first k cards to alternating pattern
                    if (k <= STATE_WIDTH) begin
                        current_state <= simulate_move(current_state, k, cycle_count[0]);
                    end
                    // Update history
                    state_history[history_index] <= current_state;
                    history_index <= history_index + 1;
                    cycle_count <= cycle_count + 1;
                end
            end
        end
    end

    // Functions for game logic
    function automatic [STATE_WIDTH-1:0] simulate_move;
        input [STATE_WIDTH-1:0] state;
        input [3:0] flip_len;
        input player;  // 0=Toki, 1=Quailty
        integer i;
        begin
            simulate_move = state;
            // Flip first flip_len cards to 0 for Toki, 1 for Quailty (heuristic)
            for (i = 0; i < flip_len && i < STATE_WIDTH; i = i + 1) begin
                simulate_move[i] = player ? 1'b1 : 1'b0;
            end
        end
    endfunction

    function automatic check_win;
        input [STATE_WIDTH-1:0] state;
        input [3:0] flip_len;
        integer i, j;
        reg [STATE_WIDTH-1:0] test_state;
        begin
            check_win = 0;
            // Check all possible flips
            for (i = 0; i <= STATE_WIDTH - flip_len; i = i + 1) begin
                // Try flipping to all 0s
                test_state = state;
                for (j = 0; j < flip_len; j = j + 1) begin
                    test_state[i+j] = 1'b0;
                end
                if (test_state == 8'b00000000 || test_state == 8'b11111111) begin
                    check_win = 1;
                    return 1;
                end
                // Try flipping to all 1s
                test_state = state;
                for (j = 0; j < flip_len; j = j + 1) begin
                    test_state[i+j] = 1'b1;
                end
                if (test_state == 8'b00000000 || test_state == 8'b11111111) begin
                    check_win = 1;
                    return 1;
                end
            end
        end
    endfunction

    function automatic is_in_history;
        input [STATE_WIDTH-1:0] state;
        input [STATE_WIDTH-1:0] history [0:15];
        input [3:0] idx;
        integer i;
        begin
            is_in_history = 0;
            for (i = 0; i < 16 && i < idx; i = i + 1) begin
                if (history[i] == state) begin
                    is_in_history = 1;
                    return 1;
                end
            end
        end
    endfunction

endmodule

module find_min_piles(
    input clk,
    input rst_n,
    input start,
    input [3:0] n,                    // Number of boxes (1-8)
    input [7:0] strengths [0:7],      // Box strengths (0-100)
    output reg [3:0] result,          // Minimal number of piles
    output reg done
);

// State encoding
localparam S0_IDLE = 4'd0;
localparam S1_SORT_START = 4'd1;
localparam S2_SORT_ACTIVE = 4'd2;
localparam S3_SORT_DONE = 4'd3;
localparam S4_PROCESS_BOX = 4'd4;
localparam S5_CHECK_PILE = 4'd5;
localparam S6_INCREMENT_PILE = 4'd6;
localparam S7_NEW_PILE = 4'd7;
localparam S8_DONE = 4'd8;

// Internal registers
reg [3:0] state;
reg [7:0] sorted [0:7];          // Sorted strengths
reg [3:0] pile_heights [0:7];    // Current height of each pile
reg [2:0] pass;                  // Bubble sort pass counter
reg [2:0] i;                     // Bubble sort index
reg [2:0] current_box_index;     // Current box being processed
reg [2:0] current_pile_index;    // Current pile being checked
reg [3:0] number_of_piles;       // Number of piles formed
reg found;                       // Found pile for current box

integer j;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all registers
        state <= S0_IDLE;
        result <= 4'd0;
        done <= 1'b0;
        pass <= 3'd0;
        i <= 3'd0;
        current_box_index <= 3'd0;
        current_pile_index <= 3'd0;
        number_of_piles <= 4'd0;
        found <= 1'b0;
        for (j = 0; j < 8; j = j + 1) begin
            sorted[j] <= 8'd0;
            pile_heights[j] <= 4'd0;
        end
    end else begin
        case (state)
            S0_IDLE: begin
                done <= 1'b0;
                if (start && n != 4'd0) begin
                    // Load input and initialize
                    for (j = 0; j < 8; j = j + 1) begin
                        if (j < n)
                            sorted[j] <= strengths[j];
                        else
                            sorted[j] <= 8'hFF; // Fill unused with max
                        pile_heights[j] <= 4'd0;
                    end
                    pass <= 3'd0;
                    i <= 3'd0;
                    number_of_piles <= 4'd0;
                    state <= S1_SORT_START;
                end else if (start && n == 4'd0) begin
                    result <= 4'd0;
                    done <= 1'b1;
                    state <= S8_DONE;
                end
            end

            S1_SORT_START: begin
                // Start bubble sort
                if (n > 3'd1) begin
                    pass <= 3'd0;
                    i <= 3'd0;
                    state <= S2_SORT_ACTIVE;
                end else begin
                    // Only one box, skip sorting
                    state <= S3_SORT_DONE;
                end
            end

            S2_SORT_ACTIVE: begin
                if (pass < n - 1) begin
                    if (i < n - pass - 1) begin
                        // Compare and swap
                        if (sorted[i] > sorted[i + 1]) begin
                            sorted[i] <= sorted[i + 1];
                            sorted[i + 1] <= sorted[i];
                        end
                        i <= i + 1;
                        state <= S2_SORT_ACTIVE;
                    end else begin
                        // End of pass
                        i <= 3'd0;
                        pass <= pass + 1;
                        state <= S2_SORT_ACTIVE;
                    end
                end else begin
                    state <= S3_SORT_DONE;
                end
            end

            S3_SORT_DONE: begin
                // Initialize for greedy assignment
                for (j = 0; j < 8; j = j + 1) begin
                    pile_heights[j] <= 4'd0;
                end
                current_box_index <= 3'd0;
                number_of_piles <= 4'd0;
                state <= S4_PROCESS_BOX;
            end

            S4_PROCESS_BOX: begin
                if (current_box_index < n) begin
                    current_pile_index <= 3'd0;
                    found <= 1'b0;
                    state <= S5_CHECK_PILE;
                end else begin
                    result <= number_of_piles;
                    done <= 1'b1;
                    state <= S8_DONE;
                end
            end

            S5_CHECK_PILE: begin
                if (current_pile_index < number_of_piles) begin
                    if (pile_heights[current_pile_index] <= sorted[current_box_index]) begin
                        // Found valid pile
                        pile_heights[current_pile_index] <= pile_heights[current_pile_index] + 1;
                        found <= 1'b1;
                        state <= S6_INCREMENT_PILE;
                    end else begin
                        // Try next pile
                        current_pile_index <= current_pile_index + 1;
                        state <= S5_CHECK_PILE;
                    end
                end else begin
                    if (!found) begin
                        state <= S7_NEW_PILE;
                    end else begin
                        state <= S6_INCREMENT_PILE;
                    end
                end
            end

            S6_INCREMENT_PILE: begin
                current_box_index <= current_box_index + 1;
                state <= S4_PROCESS_BOX;
            end

            S7_NEW_PILE: begin
                pile_heights[number_of_piles] <= 4'd1;
                number_of_piles <= number_of_piles + 1;
                state <= S6_INCREMENT_PILE;
            end

            S8_DONE: begin
                done <= 1'b0;
                if (!start)
                    state <= S0_IDLE;
            end

            default: state <= S0_IDLE;
        endcase
    end
end

endmodule

module non_decreasing_array #(
    parameter DATA_WIDTH = 24,
    parameter MAX_N = 50,
    parameter INDEX_WIDTH = 6
) (
    input clk,
    input rst_n,
    input start,
    input [5:0] N,
    input [DATA_WIDTH*MAX_N-1:0] array_in,
    output reg count_valid,
    output reg [7:0] count,
    output reg op_valid,
    output reg [INDEX_WIDTH-1:0] op_x,
    output reg [INDEX_WIDTH-1:0] op_y,
    output reg done
);

// State definitions
localparam IDLE = 0;
localparam FIND_MAX_MIN = 1;
localparam DECIDE = 2;
localparam OUTPUT_COUNT = 3;
localparam FIX = 4;
localparam PREFIX = 5;
localparam SUFFIX = 6;
localparam DONE = 7;

reg [2:0] state;
reg [DATA_WIDTH-1:0] array_reg [0:MAX_N-1];
reg [DATA_WIDTH-1:0] max_val, min_val;
reg [INDEX_WIDTH-1:0] max_index, min_index;
reg [6:0] neg_count, pos_count;
reg [6:0] total_count;
reg [1:0] strategy;
reg [INDEX_WIDTH-1:0] i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        count_valid <= 0;
        op_valid <= 0;
        done <= 0;
        i <= 0;
        count <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= FIND_MAX_MIN;
                    i <= 0;
                    max_val <= {1'b0, {DATA_WIDTH-1{1'b1}}};
                    min_val <= {1'b1, {DATA_WIDTH-1{1'b0}}};
                    max_index <= 0;
                    min_index <= 0;
                    neg_count <= 0;
                    pos_count <= 0;
                end
            end

            FIND_MAX_MIN: begin
                if (i == 0) begin
                    for (integer j = 0; j < MAX_N; j = j + 1) begin
                        array_reg[j] <= array_in[DATA_WIDTH*j +: DATA_WIDTH];
                    end
                    if (N > 0) begin
                        max_val <= array_in[0 +: DATA_WIDTH];
                        min_val <= array_in[0 +: DATA_WIDTH];
                        if (array_in[0 +: DATA_WIDTH] < 0)
                            neg_count <= 1;
                        else if (array_in[0 +: DATA_WIDTH] > 0)
                            pos_count <= 1;
                    end
                    i <= 1;
                end else if (i < N) begin
                    if (array_reg[i] > max_val) begin
                        max_val <= array_reg[i];
                        max_index <= i;
                    end
                    if (array_reg[i] < min_val) begin
                        min_val <= array_reg[i];
                        min_index <= i;
                    end
                    if (array_reg[i] < 0)
                        neg_count <= neg_count + 1;
                    else if (array_reg[i] > 0)
                        pos_count <= pos_count + 1;
                    i <= i + 1;
                end else begin
                    state <= DECIDE;
                    i <= 0;
                end
            end

            DECIDE: begin
                if (min_val >= 0) begin
                    strategy <= 0;
                    total_count <= N - 1;
                end else if (max_val <= 0) begin
                    strategy <= 1;
                    total_count <= N - 1;
                end else if (max_val >= -min_val) begin
                    strategy <= 2;
                    total_count <= neg_count + (N - 1);
                end else begin
                    strategy <= 3;
                    total_count <= pos_count + (N - 1);
                end
                state <= OUTPUT_COUNT;
            end

            OUTPUT_COUNT: begin
                count_valid <= 1;
                count <= total_count;
                case (strategy)
                    0: state <= PREFIX;
                    1: state <= SUFFIX;
                    2, 3: state <= FIX;
                    default: state <= DONE;
                endcase
            end

            FIX: begin
                count_valid <= 0;
                if (i < N) begin
                    if ((strategy == 2 && array_reg[i] < 0) || (strategy == 3 && array_reg[i] > 0)) begin
                        op_valid <= 1;
                        if (strategy == 2) begin
                            op_x <= max_index + 1;
                            op_y <= i + 1;
                        end else begin
                            op_x <= min_index + 1;
                            op_y <= i + 1;
                        end
                    end else begin
                        op_valid <= 0;
                    end
                    i <= i + 1;
                end else begin
                    op_valid <= 0;
                    i <= 0;
                    if (strategy == 2)
                        state <= PREFIX;
                    else
                        state <= SUFFIX;
                end
            end

            PREFIX: begin
                if (i < N - 1) begin
                    op_valid <= 1;
                    op_x <= i + 1;
                    op_y <= i + 2;
                    i <= i + 1;
                end else begin
                    op_valid <= 0;
                    state <= DONE;
                end
            end

            SUFFIX: begin
                if (i < N - 1) begin
                    op_valid <= 1;
                    op_x <= (N - 1 - i) + 1;
                    op_y <= (N - 1 - i);
                    i <= i + 1;
                end else begin
                    op_valid <= 0;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module largest_non_square (
    input clk,
    input rst_n,
    input start,
    input [15:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    output reg [15:0] result,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam INIT = 3'b001;
localparam CHECK = 3'b010;
localparam UPDATE = 3'b011;
localparam NEXT = 3'b100;
localparam DONE = 3'b101;

reg [2:0] state;
reg [2:0] current_index;
reg [15:0] max_val;
reg [15:0] current_val;
reg [7:0] y;  // Counter for square root (0-181)

wire [15:0] y_squared = y * y;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        max_val <= 0;
        current_index <= 0;
        current_val <= 0;
        y <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) state <= INIT;
            end
            INIT: begin
                max_val <= 16'sd32768;  // Min value for comparison
                current_index <= 0;
                current_val <= arr_0;
                y <= 0;
                state <= CHECK;
            end
            CHECK: begin
                if (current_val[15]) begin  // Negative numbers are not perfect squares
                    state <= UPDATE;
                end else begin
                    if (y_squared == current_val) begin
                        state <= NEXT;  // Is a perfect square, skip
                    end else if (y_squared > current_val) begin
                        state <= UPDATE;  // Not a perfect square
                    end else begin
                        y <= y + 1;  // Continue checking
                    end
                end
            end
            UPDATE: begin
                if ($signed(current_val) > $signed(max_val)) begin
                    max_val <= current_val;
                end
                state <= NEXT;
            end
            NEXT: begin
                if (current_index < 7) begin
                    current_index <= current_index + 1;
                    case (current_index + 1)
                        3'd0: current_val <= arr_0;
                        3'd1: current_val <= arr_1;
                        3'd2: current_val <= arr_2;
                        3'd3: current_val <= arr_3;
                        3'd4: current_val <= arr_4;
                        3'd5: current_val <= arr_5;
                        3'd6: current_val <= arr_6;
                        3'd7: current_val <= arr_7;
                    endcase
                    y <= 0;
                    state <= CHECK;
                end else begin
                    state <= DONE;
                end
            end
            DONE: begin
                result <= max_val;
                done <= 1;
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

module packet_distribution (
    input [29:0] n,       // Input n (0 to 1e9, fits in 30 bits)
    output [4:0] ans      // Output answer (max 30, fits in 5 bits)
);

// Combinational logic to find minimum number of packets
// For n >= 1, answer = ceil(log2(n+1))
// This is equivalent to finding the smallest k such that (2^k - 1) >= n

reg [4:0] result;
integer i;

always @(*) begin
    result = 5'd0;
    // Check from highest possible k down to 1
    // Since n <= 1e9, max k is 30
    for (i = 30; i >= 1; i = i - 1) begin
        if ((1 << i) - 1 >= n) begin
            result = i;
        end
    end
    // Special case: n = 0 should give 0, but n >= 1 per problem
end

assign ans = result;

endmodule

// Note: This is a combinational module without clock/reset.
// The testbench will write to 'n' and read 'ans' after a small delay.

module group_photo_area (
    input clk, rst_n, start,
    input [2:0] n,                   // number of friends (1-8)
    input [9:0] max_h,               // candidate max height
    // Friend dimensions (10 bits each)
    input [9:0] w0, h0, w1, h1, w2, h2, w3, h3,
    input [9:0] w4, h4, w5, h5, w6, h6, w7, h7,
    output reg [23:0] area,          // computed area (total_width * max_h)
    output reg done                  // computation finished
);

// State definitions
localparam IDLE = 3'b000;
localparam STEP1 = 3'b001;  // Process friends
localparam STEP2 = 3'b010;  // Sort by (h-w)
localparam STEP3 = 3'b011;  // Calculate total width
localparam DONE  = 3'b100;
localparam ERROR = 3'b101;

// Registers
reg [2:0] state;
reg [2:0] i;               // Friend index
reg [2:0] k;               // Remaining lies
reg [9:0] w_arr[0:7];      // Width array
reg [9:0] h_arr[0:7];      // Height array
reg [12:0] total_width;    // Accumulated width (max 8000)
reg [2:0] sort_pass;       // Bubble sort pass counter
reg [2:0] sort_idx;        // Bubble sort index

// Combinational helpers
wire signed [10:0] diff0 = h_arr[sort_idx] - w_arr[sort_idx];
wire signed [10:0] diff1 = h_arr[sort_idx+1] - w_arr[sort_idx+1];

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        area <= 0;
        k <= 0;
        total_width <= 0;
        sort_pass <= 0;
        sort_idx <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    k <= n >> 1; // Initialize lies count
                    i <= 0;
                    state <= STEP1;
                end
            end

            STEP1: begin  // Process each friend
                // Get current friend's dimensions
                case (i)
                    0: begin w_arr[0] <= w0; h_arr[0] <= h0; end
                    1: begin w_arr[1] <= w1; h_arr[1] <= h1; end
                    2: begin w_arr[2] <= w2; h_arr[2] <= h2; end
                    3: begin w_arr[3] <= w3; h_arr[3] <= h3; end
                    4: begin w_arr[4] <= w4; h_arr[4] <= h4; end
                    5: begin w_arr[5] <= w5; h_arr[5] <= h5; end
                    6: begin w_arr[6] <= w6; h_arr[6] <= h6; end
                    7: begin w_arr[7] <= w7; h_arr[7] <= h7; end
                endcase

                // Force lie if height > max_h
                if (h_arr[i] > max_h) begin
                    if (k > 0 && w_arr[i] <= max_h) begin
                        // Swap dimensions
                        w_arr[i] <= h_arr[i];
                        h_arr[i] <= w_arr[i];
                        k <= k - 1;
                    end else begin
                        state <= ERROR;
                    end
                end

                if (i == 7) begin
                    sort_pass <= 0;
                    sort_idx <= 0;
                    state <= STEP2;
                end else begin
                    i <= i + 1;
                end
            end

            STEP2: begin  // Bubble sort by (h-w) increasing
                if (diff0 > diff1) begin  // Swap if out of order
                    w_arr[sort_idx] <= w_arr[sort_idx+1];
                    w_arr[sort_idx+1] <= w_arr[sort_idx];
                    h_arr[sort_idx] <= h_arr[sort_idx+1];
                    h_arr[sort_idx+1] <= h_arr[sort_idx];
                end
                sort_idx <= sort_idx + 1;
                if (sort_idx >= 6) begin  // End of pass
                    sort_idx <= 0;
                    sort_pass <= sort_pass + 1;
                    if (sort_pass >= 6) begin  // 7 passes for 8 elements
                        total_width <= 0;
                        i <= 0;
                        state <= STEP3;
                    end
                end
            end

            STEP3: begin  // Calculate total width
                if (i < 8) begin
                    // Lie if allowed and reduces width
                    if (k > 0 && w_arr[i] <= max_h && h_arr[i] < w_arr[i]) begin
                        total_width <= total_width + h_arr[i];
                        k <= k - 1;
                    end else begin
                        total_width <= total_width + w_arr[i];
                    end
                    i <= i + 1;
                end else begin
                    // Compute area (width * height)
                    area <= total_width * max_h;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1;
                if (!start) state <= IDLE;
            end

            ERROR: begin
                area <= 24'hFFFFFF;  // Large error value
                state <= DONE;
            end

            default: state <= IDLE;
        endcase
    end
end
endmodule

Lucky Permutation Triple Module

// Module: lucky_permutation_triple
// Description: Computes a Lucky Permutation Triple for n (1 <= n <= 8). If n is even or n > 8, outputs invalid.
// Inputs:
//   clk       : Clock signal (rising edge triggered)
//   rst_n     : Active-low synchronous reset
//   start     : Start pulse (assert for 1 cycle to begin computation)
//   n[3:0]    : 4-bit input, value of n (1 to 8). n=0 is treated as invalid.
// Outputs:
//   done      : Asserted high for 1 cycle when computation is complete
//   valid     : High when n is odd and n <= 8, indicating outputs are valid permutations
//   a[7:0][7:0] : 8-element output array, each element 8 bits, representing permutation a
//   b[7:0][7:0] : 8-element output array, each element 8 bits, representing permutation b
//   c[7:0][7:0] : 8-element output array, each element 8 bits, representing permutation c
//
// Functionality:
//   When start is asserted, the module computes the three permutations.
//   For valid=1, for i = 0 to n-1:
//     a[i] = i
//     b[i] = i
//     c[i] = (2*i) % n
//   For i >= n, the arrays are set to 0 (don't care).
//   The module asserts done one cycle after start.
//   The module must be reset before first use.
//
// Timing:
//   - Assert start for 1 clock cycle.
//   - done will go high on the next clock cycle.
//   - valid and the arrays are available on the same cycle as done.
//   - After done, the module returns to IDLE state.
//
// Reset behavior:
//   On rst_n=0: done=0, valid=0, arrays are cleared to 0.
//   Minimum 2 clock cycles of reset recommended.
//
// Constraints:
//   - n must be between 1 and 8 inclusive.
//   - For n even or n > 8, valid will be 0.
//   - The output arrays are 8 elements each, but only the first n elements are meaningful when valid=1.
//
// Note: The module uses combinatorial logic inside a sequential state machine. The computation is completed in one cycle.

// Verilog code:
`timescale 1ns/1ps

module lucky_permutation_triple (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,
    output reg done,
    output reg valid,
    output reg [7:0] a [0:7],
    output reg [7:0] b [0:7],
    output reg [7:0] c [0:7]
);

// State machine
reg state;
localparam IDLE = 1'b0;
localparam DONE = 1'b1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 1'b0;
        valid <= 1'b0;
        // Initialize arrays to zero
        for (integer i = 0; i < 8; i = i + 1) begin
            a[i] <= 8'd0;
            b[i] <= 8'd0;
            c[i] <= 8'd0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    // Compute valid flag: n must be odd and <=8
                    valid <= (n[0] == 1'b1) && (n <= 8);
                    // Compute arrays
                    for (integer i = 0; i < 8; i = i + 1) begin
                        if (i < n && n[0] == 1'b1) begin
                            a[i] <= i;
                            b[i] <= i;
                            // Compute c_i = (2*i) % n
                            if (2*i >= n)
                                c[i] <= 2*i - n;
                            else
                                c[i] <= 2*i;
                        end else begin
                            a[i] <= 8'd0;
                            b[i] <= 8'd0;
                            c[i] <= 8'd0;
                        end
                    end
                    state <= DONE;
                    done <= 1'b1;
                end
            end
            DONE: begin
                done <= 1'b0;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module min_cost_gather #(
    parameter N = 2,           // Number of cities (1 to N)
    parameter MAX_FLIGHTS = 8, // Maximum number of flights
    parameter MAX_DAY = 16     // Maximum day value
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    // Packed flight data: each flight is 28 bits {valid[0], day[4:0], from[2:0], to[2:0], cost[15:0]}
    input wire [28*MAX_FLIGHTS-1:0] flights,
    output reg [19:0] min_cost,  // 20-bit to prevent overflow
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam INIT_ARRIVALS = 3'b001;
localparam PROCESS_ARRIVALS = 3'b010;
localparam INIT_DEPARTURES = 3'b011;
localparam PROCESS_DEPARTURES = 3'b100;
localparam COMPUTE_MIN = 3'b101;
localparam FINISHED = 3'b110;

// Internal signals and registers
reg [2:0] state;
reg [4:0] day_counter;          // Current day (1 to MAX_DAY)
reg [3:0] flight_counter;       // Current flight index (0 to MAX_FLIGHTS-1)
reg [19:0] arrival_cost_per_city [1:N];  // Min arrival cost per city
reg [19:0] departure_cost_per_city [1:N]; // Min departure cost per city
reg [19:0] arrival_cost [1:MAX_DAY];     // Total arrival cost for each day
reg [19:0] departure_cost [1:MAX_DAY];   // Total departure cost for each day
reg [19:0] total_arrival_cost;
reg [19:0] total_departure_cost;
reg [3:0] arrival_count;        // Number of cities with arrival flights
reg [3:0] departure_count;      // Number of cities with departure flights
reg [19:0] best_cost;
reg [4:0] compute_day;

// Unpack flights into arrays
wire flight_valid [0:MAX_FLIGHTS-1];
wire [4:0] flight_day [0:MAX_FLIGHTS-1];
wire [2:0] flight_from [0:MAX_FLIGHTS-1];
wire [2:0] flight_to [0:MAX_FLIGHTS-1];
wire [15:0] flight_cost [0:MAX_FLIGHTS-1];

generate
    genvar i;
    for (i = 0; i < MAX_FLIGHTS; i = i + 1) begin
        assign flight_valid[i] = flights[i*28 + 27];
        assign flight_day[i] = flights[i*28 + 26: i*28 + 22];
        assign flight_from[i] = flights[i*28 + 21: i*28 + 19];
        assign flight_to[i] = flights[i*28 + 18: i*28 + 16];
        assign flight_cost[i] = flights[i*28 + 15: i*28];
    end
endgenerate

// State machine and logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        min_cost <= 20'hFFFFF; // INF
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT_ARRIVALS;
                end
            end

            INIT_ARRIVALS: begin
                // Initialize arrival data
                arrival_count <= 0;
                total_arrival_cost <= 0;
                for (int j = 1; j <= N; j = j + 1) begin
                    arrival_cost_per_city[j] <= 20'hFFFFF;
                end
                day_counter <= 1;
                flight_counter <= 0;
                state <= PROCESS_ARRIVALS;
            end

            PROCESS_ARRIVALS: begin
                if (flight_counter < MAX_FLIGHTS) begin
                    if (flight_valid[flight_counter] && flight_to[flight_counter] == 0 && flight_day[flight_counter] == day_counter) begin
                        // Arrival flight
                        reg [2:0] city = flight_from[flight_counter];
                        if (city >= 1 && city <= N) begin
                            if (arrival_cost_per_city[city] > {4'b0, flight_cost[flight_counter]}) begin
                                if (arrival_cost_per_city[city] == 20'hFFFFF) begin
                                    arrival_count <= arrival_count + 1;
                                end
                                total_arrival_cost <= total_arrival_cost - arrival_cost_per_city[city] + {4'b0, flight_cost[flight_counter]};
                                arrival_cost_per_city[city] <= {4'b0, flight_cost[flight_counter]};
                            end
                        end
                    end
                    flight_counter <= flight_counter + 1;
                end else begin
                    // All flights processed for this day
                    if (arrival_count == N) begin
                        arrival_cost[day_counter] <= total_arrival_cost;
                    end else begin
                        arrival_cost[day_counter] <= 20'hFFFFF;
                    end
                    if (day_counter < MAX_DAY) begin
                        day_counter <= day_counter + 1;
                        flight_counter <= 0;
                    end else begin
                        state <= INIT_DEPARTURES;
                    end
                end
            end

            INIT_DEPARTURES: begin
                // Initialize departure data
                departure_count <= 0;
                total_departure_cost <= 0;
                for (int j = 1; j <= N; j = j + 1) begin
                    departure_cost_per_city[j] <= 20'hFFFFF;
                end
                day_counter <= MAX_DAY;
                flight_counter <= 0;
                state <= PROCESS_DEPARTURES;
            end

            PROCESS_DEPARTURES: begin
                if (flight_counter < MAX_FLIGHTS) begin
                    if (flight_valid[flight_counter] && flight_from[flight_counter] == 0 && flight_day[flight_counter] == day_counter) begin
                        // Departure flight
                        reg [2:0] city = flight_to[flight_counter];
                        if (city >= 1 && city <= N) begin
                            if (departure_cost_per_city[city] > {4'b0, flight_cost[flight_counter]}) begin
                                if (departure_cost_per_city[city] == 20'hFFFFF) begin
                                    departure_count <= departure_count + 1;
                                end
                                total_departure_cost <= total_departure_cost - departure_cost_per_city[city] + {4'b0, flight_cost[flight_counter]};
                                departure_cost_per_city[city] <= {4'b0, flight_cost[flight_counter]};
                            end
                        end
                    end
                    flight_counter <= flight_counter + 1;
                end else begin
                    // All flights processed for this day
                    if (departure_count == N) begin
                        departure_cost[day_counter] <= total_departure_cost;
                    end else begin
                        departure_cost[day_counter] <= 20'hFFFFF;
                    end
                    if (day_counter > 1) begin
                        day_counter <= day_counter - 1;
                        flight_counter <= 0;
                    end else begin
                        state <= COMPUTE_MIN;\n                        compute_day <= 1;
                        best_cost <= 20'hFFFFF;
                    end
                end
            end

            COMPUTE_MIN: begin
                // Find min cost for k-day window
                if (compute_day <= MAX_DAY - k) begin
                    if (arrival_cost[compute_day] != 20'hFFFFF && departure_cost[compute_day + k] != 20'hFFFFF) begin
                        reg [19:0] total = arrival_cost[compute_day] + departure_cost[compute_day + k];
                        if (total < best_cost) begin
                            best_cost <= total;
                        end
                    end
                    compute_day <= compute_day + 1;
                end else begin
                    state <= FINISHED;
                    if (best_cost != 20'hFFFFF) begin
                        min_cost <= best_cost;
                    end else begin
                        min_cost <= 20'hFFFFF;
                    end
                end
            end

            FINISHED: begin
                done <= 1;
                if (!start) begin
                    state <= IDLE;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module palindrome_sequence_counter (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] N,
    input wire [7:0] K,
    output reg [31:0] result,
    output reg done
);

// State definitions
localparam S_IDLE = 0;
localparam S_FIND_DIV_START = 1;
localparam S_FIND_DIV_CHECK = 2;
localparam S_FIND_DIV_STORE = 3;
localparam S_FIND_DIV_NEXT = 4;
localparam S_PREPARE = 5;
localparam S_COMPUTE_BASE_START = 6;
localparam S_COMPUTE_BASE_LOOP = 7;
localparam S_INCLUSION_EXCLUSION_START = 8;
localparam S_INCLUSION_EXCLUSION_LOOP = 9;
localparam S_INCLUSION_EXCLUSION_SUB = 10;
localparam S_CONTRIBUTION = 11;
localparam S_NEXT_DIVISOR = 12;
localparam S_DONE = 13;

// Constants
localparam MOD = 1000000007;

// Internal registers
reg [7:0] state;
reg [7:0] divisors [0:31];
reg [31:0] v_values [0:31];
reg [7:0] divisor_count;
reg [7:0] i_counter;
reg [7:0] current_idx;
reg [7:0] d;
reg [31:0] base;
reg [7:0] exp;
reg [31:0] temp_v;
reg [7:0] j_counter;
reg [31:0] contrib;
reg [31:0] total_sum;

// Helper functions
function [7:0] mod8(input [7:0] a, input [7:0] b);
    integer k;
    reg [7:0] r;
begin
    r = a;
    for (k = 0; k < 256; k = k + 1) begin
        if (r >= b) r = r - b;
    end
    mod8 = r;
end
endfunction

function [31:0] mul_mod(input [31:0] a, input [31:0] b);
begin
    mul_mod = (a * b) % MOD;
end
endfunction

function [31:0] add_mod(input [31:0] a, input [31:0] b);
begin
    add_mod = (a + b) % MOD;
end
endfunction

function [31:0] sub_mod(input [31:0] a, input [31:0] b);
begin
    sub_mod = (a + MOD - b) % MOD;
end
endfunction

function [31:0] pow_mod(input [7:0] base, input [7:0] exp);
    reg [31:0] res;
    integer i;
begin
    res = 1;
    for (i = 0; i < exp; i = i + 1) begin
        res = mul_mod(res, {24'b0, base});
    end
    pow_mod = res;
end
endfunction

function [7:0] ceil_half(input [7:0] d);
begin
    ceil_half = (d + 1) >> 1;
end
endfunction

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        done <= 0;
        result <= 0;
        divisor_count <= 0;
        total_sum <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    state <= S_FIND_DIV_START;
                    i_counter <= 1;
                    divisor_count <= 0;
                    total_sum <= 0;
                end
            end

            S_FIND_DIV_START: begin
                state <= S_FIND_DIV_CHECK;
            end

            S_FIND_DIV_CHECK: begin
                if (i_counter > N) begin
                    state <= S_PREPARE;
                    current_idx <= 0;
                end else begin
                    if (mod8(N, i_counter) == 0) begin
                        state <= S_FIND_DIV_STORE;
                    end else begin
                        state <= S_FIND_DIV_NEXT;
                    end
                end
            end

            S_FIND_DIV_STORE: begin
                divisors[divisor_count] <= i_counter;
                divisor_count <= divisor_count + 1;
                state <= S_FIND_DIV_NEXT;
            end

            S_FIND_DIV_NEXT: begin
                i_counter <= i_counter + 1;
                state <= S_FIND_DIV_CHECK;
            end

            S_PREPARE: begin
                if (current_idx >= divisor_count) begin
                    state <= S_DONE;
                end else begin
                    d <= divisors[current_idx];
                    exp <= ceil_half(divisors[current_idx]);
                    state <= S_COMPUTE_BASE_START;
                end
            end

            S_COMPUTE_BASE_START: begin
                base <= pow_mod(K, exp);
                state <= S_COMPUTE_BASE_LOOP;
            end

            S_COMPUTE_BASE_LOOP: begin
                temp_v <= base;
                j_counter <= 0;
                state <= S_INCLUSION_EXCLUSION_START;
            end

            S_INCLUSION_EXCLUSION_START: begin
                if (j_counter >= current_idx) begin
                    state <= S_CONTRIBUTION;
                end else begin
                    if (mod8(d, divisors[j_counter]) == 0) begin
                        temp_v <= sub_mod(temp_v, v_values[j_counter]);
                    end
                    state <= S_INCLUSION_EXCLUSION_SUB;
                end
            end

            S_INCLUSION_EXCLUSION_SUB: begin
                j_counter <= j_counter + 1;
                state <= S_INCLUSION_EXCLUSION_START;
            end

            S_CONTRIBUTION: begin
                v_values[current_idx] <= temp_v;
                if (d[0]) begin
                    contrib <= mul_mod(temp_v, {24'b0, d});
                end else begin
                    contrib <= mul_mod(temp_v, {24'b0, d >> 1});
                end
                state <= S_NEXT_DIVISOR;
            end

            S_NEXT_DIVISOR: begin
                total_sum <= add_mod(total_sum, contrib);
                current_idx <= current_idx + 1;
                state <= S_PREPARE;
            end

            S_DONE: begin
                result <= total_sum;
                done <= 1;
                state <= S_IDLE;
            end

            default: state <= S_IDLE;
        endcase
    end
end

endmodule

module card_game (
  input clk,
  input rst_n,
  input start,
  input [7:0] n, m,
  input [15:0] jiro_strength [0:99],
  input [99:0] jiro_type,  // 0 for DEF, 1 for ATK
  input [15:0] ciel_strength [0:99],
  output reg [15:0] result,
  output reg done
);

// State definitions
localparam IDLE = 0;
localparam READ_N_M = 1;
localparam READ_JIRO = 2;
localparam READ_CIEL = 3;
localparam SEPARATE = 4;
localparam SORT_DEF = 5;
localparam SORT_ATK = 6;
localparam SORT_CIEL = 7;
localparam COMPUTE_TOTAL_CIEL = 8;
localparam POSS1_DEF = 9;
localparam POSS1_ATK = 10;
localparam POSS2 = 11;
localparam COMPUTE_RESULT = 12;
localparam DONE = 13;

reg [3:0] state;
reg [7:0] i, j, k;
reg [15:0] def_list [0:99];
reg [15:0] atk_list [0:99];
reg [15:0] ciel_sorted [0:99];
reg [99:0] used;
reg [15:0] total_ciel;
reg [15:0] sum_def_used;
reg [15:0] damage1, damage2;
reg [7:0] num_def, num_atk;
reg [15:0] temp;
reg found;

// For Possibility 2
reg [15:0] sum_c, sum_a;

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    state <= IDLE;
    done <= 0;
    result <= 0;
    i <= 0;
    j <= 0;
    k <= 0;
    num_def <= 0;
    num_atk <= 0;
    total_ciel <= 0;
    sum_def_used <= 0;
    damage1 <= 0;
    damage2 <= 0;
    sum_c <= 0;
    sum_a <= 0;
    used <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (start) begin
          state <= READ_N_M;
          i <= 0;
          j <= 0;
          k <= 0;
          num_def <= 0;
          num_atk <= 0;
          total_ciel <= 0;
          sum_def_used <= 0;
          damage1 <= 0;
          damage2 <= 0;
          sum_c <= 0;
          sum_a <= 0;
          used <= 0;
          done <= 0;
        end
      end

      READ_N_M: begin
        // n and m are already provided, move to reading Jiro cards
        state <= READ_JIRO;
      end

      READ_JIRO: begin
        // Store Jiro cards into def_list and atk_list based on type
        if (i < n) begin
          if (jiro_type[i] == 0) begin
            def_list[num_def] <= jiro_strength[i];
            num_def <= num_def + 1;
          end else begin
            atk_list[num_atk] <= jiro_strength[i];
            num_atk <= num_atk + 1;
          end
          i <= i + 1;
        end else begin
          i <= 0;
          state <= READ_CIEL;
        end
      end

      READ_CIEL: begin
        // Store Ciel cards into ciel_sorted
        if (i < m) begin
          ciel_sorted[i] <= ciel_strength[i];
          i <= i + 1;
        end else begin
          i <= 0;
          state <= SEPARATE;
        end
      end

      SEPARATE: begin
        // Separate completed, move to sorting
        state <= SORT_DEF;
        i <= 0;
        j <= 0;
      end

      SORT_DEF: begin
        // Bubble sort def_list
        if (i < num_def) begin
          if (j < num_def - 1) begin
            if (def_list[j] > def_list[j+1]) begin
              temp <= def_list[j];
              def_list[j] <= def_list[j+1];
              def_list[j+1] <= temp;
            end
            j <= j + 1;
          end else begin
            j <= 0;
            i <= i + 1;
          end
        end else begin
          i <= 0;
          j <= 0;
          state <= SORT_ATK;
        end
      end

      SORT_ATK: begin
        // Bubble sort atk_list
        if (i < num_atk) begin
          if (j < num_atk - 1) begin
            if (atk_list[j] > atk_list[j+1]) begin
              temp <= atk_list[j];
              atk_list[j] <= atk_list[j+1];
              atk_list[j+1] <= temp;
            end
            j <= j + 1;
          end else begin
            j <= 0;
            i <= i + 1;
          end
        end else begin
          i <= 0;
          j <= 0;
          state <= SORT_CIEL;
        end
      end

      SORT_CIEL: begin
        // Bubble sort ciel_sorted
        if (i < m) begin
          if (j < m - 1) begin
            if (ciel_sorted[j] > ciel_sorted[j+1]) begin
              temp <= ciel_sorted[j];
              ciel_sorted[j] <= ciel_sorted[j+1];
              ciel_sorted[j+1] <= temp;
            end
            j <= j + 1;
          end else begin
            j <= 0;
            i <= i + 1;
          end
        end else begin
          i <= 0;
          j <= 0;
          state <= COMPUTE_TOTAL_CIEL;
        end
      end

      COMPUTE_TOTAL_CIEL: begin
        if (i < m) begin
          total_ciel <= total_ciel + ciel_sorted[i];
          i <= i + 1;
        end else begin
          i <= 0;
          j <= 0;
          used <= 0;
          sum_def_used <= 0;
          state <= POSS1_DEF;
        end
      end

      POSS1_DEF: begin
        if (i < num_def) begin
          found <= 0;
          if (j < m) begin
            if (!used[j] && ciel_sorted[j] > def_list[i]) begin
              used[j] <= 1;
              sum_def_used <= sum_def_used + ciel_sorted[j];
              found <= 1;
            end
            j <= j + 1;
          end else begin
            if (!found) begin
              // Cannot destroy this DEF card
              damage1 <= 0;
              state <= POSS2;
              i <= 0;
              j <= 0;
            end else begin
              i <= i + 1;
              j <= 0;
            end
          end
        end else begin
          // All DEF destroyed, move to ATK destruction
          i <= 0;
          j <= 0;
          state <= POSS1_ATK;
        end
      end

      POSS1_ATK: begin
        if (i < num_atk) begin
          found <= 0;
          if (j < m) begin
            if (!used[j] && ciel_sorted[j] >= atk_list[i]) begin
              used[j] <= 1;
              found <= 1;
            end
            j <= j + 1;
          end else begin
            if (!found) begin
              damage1 <= 0;
              state <= POSS2;
              i <= 0;
              j <= 0;
            end else begin
              i <= i + 1;
              j <= 0;
            end
          end
        end else begin
          // All ATK destroyed, compute damage1
          // damage1 = total_ciel - sum_def_used - sum(atk_list)
          temp <= 0;
          i <= 0;
          state <= COMPUTE_RESULT;
        end
      end

      POSS2: begin
        // Possibility 2: destroy only some ATK cards
        // We use the largest k Ciel cards and smallest k ATK cards
        // Sort ATK already in ascending order, ciel_sorted in ascending order
        // So largest k Ciel cards are ciel_sorted[m-1], ciel_sorted[m-2], ... 
        // Smallest k ATK cards are atk_list[0], atk_list[1], ...
        if (i < num_atk && i < m) begin
          // Check if the i-th largest Ciel card (ciel_sorted[m-1-i]) >= i-th smallest ATK card (atk_list[i])
          if (ciel_sorted[m-1-i] >= atk_list[i]) begin
            sum_c <= sum_c + ciel_sorted[m-1-i];
            sum_a <= sum_a + atk_list[i];
            // Compute damage for this k = i+1
            damage2 <= (sum_c + ciel_sorted[m-1-i]) - (sum_a + atk_list[i]);
            i <= i + 1;
          end else begin
            // Stop when condition fails
            state <= COMPUTE_RESULT;
            i <= 0;
          end
        end else begin
          state <= COMPUTE_RESULT;
          i <= 0;
        end
      end

      COMPUTE_RESULT: begin
        if (i == 0) begin
          // Compute damage1 if not done
          if (damage1 == 0 && state == POSS1_ATK && i >= num_atk) begin
            // Actually, we need to compute damage1 here
            // damage1 = total_ciel - sum_def_used - sum(atk_list)
            temp <= 0;
            i <= 1; // Mark that we are computing damage1
          end else begin
            i <= 2; // Mark that we are comparing
          end
        end else if (i == 1) begin
          // Compute sum of atk_list
          if (j < num_atk) begin
            temp <= temp + atk_list[j];
            j <= j + 1;
          end else begin
            damage1 <= total_ciel - sum_def_used - temp;
            i <= 2;
            j <= 0;
          end
        end else if (i == 2) begin
          // Compare damage1 and damage2
          if (damage1 > damage2) begin
            result <= damage1;
          end else begin
            result <= damage2;
          end
          state <= DONE;
        end
      end

      DONE: begin
        done <= 1;
        state <= IDLE;
      end

      default: state <= IDLE;
    endcase
  end
end

endmodule

