module random_pictures (
    input clk,
    input rst_n,
    input start,
    input [7:0] n,
    input [7:0] m,
    output reg [31:0] result,
    output reg done
);

// Parameters
parameter MOD = 1000000007;

// States
localparam IDLE = 3'b001;
localparam COMPUTE = 3'b010;
localparam DONE = 3'b100;

// Registers
reg [2:0] state;
reg [7:0] i;
reg [7:0] max_idx;
reg [7:0] n_minus_1;
reg [7:0] m_minus_1;
reg [31:0] curr;
reg [31:0] next;
reg [31:0] val_n;
reg [31:0] val_m;

// Combinational signals for first cycle
wire [7:0] n_minus_1_comb = (n > 0) ? n - 1 : 0;
wire [7:0] m_minus_1_comb = (m > 0) ? m - 1 : 0;
wire [7:0] max_idx_comb = (n_minus_1_comb > m_minus_1_comb) ? n_minus_1_comb : m_minus_1_comb;

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        curr <= 0;
        next <= 0;
        val_n <= 0;
        val_m <= 0;
        max_idx <= 0;
        n_minus_1 <= 0;
        m_minus_1 <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Initialize registers based on inputs
                    n_minus_1 <= n_minus_1_comb;
                    m_minus_1 <= m_minus_1_comb;
                    max_idx <= max_idx_comb;
                    i <= 0;
                    curr <= 32'd1; // F(0)
                    next <= 32'd2; // F(1)
                    // Capture F(0) if needed
                    val_n <= (n_minus_1_comb == 0) ? 32'd1 : 32'd0;
                    val_m <= (m_minus_1_comb == 0) ? 32'd1 : 32'd0;
                    // Transition
                    if (max_idx_comb == 0)
                        state <= DONE;
                    else
                        state <= COMPUTE;
                end
            end

            COMPUTE: begin
                // Capture current Fibonacci value if needed
                if (i == n_minus_1 && val_n == 0)
                    val_n <= curr;
                if (i == m_minus_1 && val_m == 0)
                    val_m <= curr;

                // Check if done
                if (i == max_idx) begin
                    state <= DONE;
                end else begin
                    // Update for next index
                    i <= i + 1;
                    curr <= next;
                    // Compute next Fibonacci number modulo MOD
                    if (curr + next >= MOD)
                        next <= curr + next - MOD;
                    else
                        next <= curr + next;
                end
            end

            DONE: begin
                // Compute result: 2 * (val_n + val_m - 1) mod MOD
                // First compute sum - 1
                reg [31:0] sum;
                if (val_n + val_m >= 1) begin
                    if (val_n + val_m - 1 >= MOD)
                        sum <= val_n + val_m - 1 - MOD;
                    else
                        sum <= val_n + val_m - 1;
                end else begin
                    sum <= MOD - 1; // Should not happen for valid inputs
                end
                // Then multiply by 2
                if (sum >= (MOD >> 1)) // sum >= MOD/2
                    result <= (sum << 1) - MOD;
                else
                    result <= sum << 1;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module curfew_enforcement (
    input clk,
    input rst_n,
    input start,
    input [4:0] n,        // Number of rooms (max 16)
    input [3:0] d,        // Maximum movement distance (max 15)
    input [7:0] b,        // Target students per room (max 255)
    input [7:0] a [0:15], // Initial students per room (8-bit each)
    output reg [7:0] result, // Result: minimal max(x1, x2)
    output reg done        // Completion signal
);

// Parameters for scaling
parameter MAX_ROOMS = 16;
parameter DATA_WIDTH = 8;
parameter ADDR_WIDTH = 4;

// State machine states
reg [3:0] state;
localparam IDLE = 0;
localparam COMPUTE_PREFIX = 1;
localparam COMPUTE_X = 2;
localparam UPDATE_RESULT = 3;
localparam FINISHED = 4;

// Registers
reg [15:0] prefix [0:16];  // Prefix sums, 16-bit to handle large totals
reg [15:0] total_students;
reg [7:0] current_result;
reg [4:0] i;               // Loop counter for rooms
reg [4:0] half_n;          // (n+1)//2
reg [7:0] left_index, right_index;
reg [15:0] available_left, available_right, available;
reg [7:0] rooms_filled;
reg [7:0] x_i;
reg [7:0] max_x;

integer j;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        current_result <= 0;
        max_x <= 0;
        i <= 0;
        total_students <= 0;
        for (j = 0; j <= 16; j = j + 1) begin
            prefix[j] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= COMPUTE_PREFIX;
                    i <= 0;
                    total_students <= 0;
                    prefix[0] <= 0;
                end
            end

            COMPUTE_PREFIX: begin
                // Compute prefix sums: prefix[i] = sum(a[0:i-1])
                if (i < n) begin
                    total_students <= total_students + a[i];
                    prefix[i+1] <= total_students + a[i];
                    i <= i + 1;
                end else begin
                    i <= 1;  // Start from i=1
                    max_x <= 0;
                    state <= COMPUTE_X;
                end
            end

            COMPUTE_X: begin
                // Compute x_i = i - min(prefix[min(n, i*d)], (total_students - prefix[max(0, n-i*d)])) / b
                half_n = (n + 1) >> 1;

                if (i <= half_n) begin
                    // left_index = min(n, i*d)
                    if (i * d < n)
                        left_index = i * d;
                    else
                        left_index = n;

                    // right_index = max(0, n - i*d)
                    if (n > i * d)
                        right_index = n - i * d;
                    else
                        right_index = 0;

                    // available_left = prefix[left_index]
                    available_left = prefix[left_index];

                    // available_right = total_students - prefix[right_index]
                    available_right = total_students - prefix[right_index];

                    // available = min(available_left, available_right)
                    if (available_left < available_right)
                        available = available_left;
                    else
                        available = available_right;

                    // rooms_filled = available / b (integer division)
                    rooms_filled = available / b;

                    // x_i = i - rooms_filled
                    if (i > rooms_filled)
                        x_i = i - rooms_filled;
                    else
                        x_i = 0;

                    state <= UPDATE_RESULT;
                end else begin
                    state <= FINISHED;
                end
            end

            UPDATE_RESULT: begin
                // Update max_x
                if (x_i > max_x)
                    max_x <= x_i;

                i <= i + 1;
                state <= COMPUTE_X;
            end

            FINISHED: begin
                result <= max_x;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module gerald_coins (
    input clk,
    input rst_n,
    input start,
    input [63:0] n,
    output [63:0] result,
    output done
);

    // States
    localparam IDLE = 2'b00;
    localparam DIVIDE = 2'b01;
    localparam COMPUTE = 2'b10;
    localparam FINISH = 2'b11;

    reg [1:0] state, next_state;
    reg [63:0] current_n;
    reg [63:0] quotient;
    reg [1:0] remainder;
    reg divider_start;
    reg [5:0] counter; // For 64-bit division
    reg [63:0] result_reg;
    reg done_reg;

    // Divider module for division by 3
    divider_3 divider (
        .clk(clk),
        .rst_n(rst_n),
        .start(divider_start),
        .dividend(current_n),
        .quotient(quotient),
        .remainder(remainder),
        .done(divider_done)
    );

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: next_state = start ? DIVIDE : IDLE;
            DIVIDE: next_state = divider_done ? COMPUTE : DIVIDE;
            COMPUTE: begin
                if (remainder == 0) begin
                    next_state = DIVIDE; // Continue dividing
                end else begin
                    next_state = FINISH;
                end
            end
            FINISH: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output and datapath logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_n <= 64'd0;
            divider_start <= 1'b0;
            result_reg <= 64'd0;
            done_reg <= 1'b0;
        end else begin
            done_reg <= 1'b0;
            divider_start <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        current_n <= n;
                    end
                end
                DIVIDE: begin
                    divider_start <= 1'b1;
                end
                COMPUTE: begin
                    if (remainder == 0) begin
                        current_n <= quotient; // Continue with n/3
                    end else begin
                        result_reg <= quotient + 1; // n/3 + 1
                        done_reg <= 1'b1;
                    end
                end
                FINISH: begin
                    // Wait for next start
                end
            endcase
        end
    end

    assign result = result_reg;
    assign done = done_reg;

endmodule

// Divider by 3 module
module divider_3 (
    input clk,
    input rst_n,
    input start,
    input [63:0] dividend,
    output [63:0] quotient,
    output [1:0] remainder,
    output done
);

    reg [63:0] quotient_reg;
    reg [1:0] remainder_reg;
    reg running;
    reg [5:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            quotient_reg <= 64'd0;
            remainder_reg <= 2'd0;
            running <= 1'b0;
            counter <= 6'd0;
        end else begin
            if (start && !running) begin
                // Start new division
                running <= 1'b1;
                counter <= 6'd0;
                quotient_reg <= 64'd0;
                remainder_reg <= 2'd0;
            end else if (running) begin
                if (counter < 64) begin
                    // Shift remainder left by 1 and bring in next bit
                    remainder_reg <= (remainder_reg << 1) | (dividend[63-counter]);

                    // If remainder >= 3, subtract 3 and set quotient bit
                    if ({(remainder_reg << 1) | (dividend[63-counter])} >= 2'd3) begin
                        remainder_reg <= ((remainder_reg << 1) | (dividend[63-counter])) - 2'd3;
                        quotient_reg <= {quotient_reg[62:0], 1'b1};
                    end else begin
                        quotient_reg <= {quotient_reg[62:0], 1'b0};
                    end

                    counter <= counter + 1;
                end else begin
                    running <= 1'b0;
                end
            end
        end
    end

    assign quotient = quotient_reg;
    assign remainder = remainder_reg;
    assign done = !running && (counter == 64) && (start || running);

endmodule

module suspect_pair_counter #(
    parameter N_MAX = 10
)(
    input [3:0] n,
    input [3:0] p,
    input [3:0] x0, y0,
    input [3:0] x1, y1,
    input [3:0] x2, y2,
    input [3:0] x3, y3,
    input [3:0] x4, y4,
    input [3:0] x5, y5,
    input [3:0] x6, y6,
    input [3:0] x7, y7,
    input [3:0] x8, y8,
    input [3:0] x9, y9,
    output reg [5:0] result
);

    reg [3:0] deg [0:N_MAX-1];          // degree of each node
    reg [3:0] edge_cnt [0:N_MAX-1][0:N_MAX-1]; // number of coders that named both nodes

    integer i, a, b;

    always_comb begin
        // Initialize deg and edge_cnt to zero
        for (i = 0; i < N_MAX; i = i + 1) begin
            deg[i] = 4'b0;
            for (int j = 0; j < N_MAX; j = j + 1) begin
                edge_cnt[i][j] = 4'b0;
            end
        end

        // Process each coder
        for (i = 0; i < N_MAX; i = i + 1) begin
            if (i < n) begin
                logic [3:0] x, y;
                case (i)
                    0: begin x = x0 - 1; y = y0 - 1; end
                    1: begin x = x1 - 1; y = y1 - 1; end
                    2: begin x = x2 - 1; y = y2 - 1; end
                    3: begin x = x3 - 1; y = y3 - 1; end
                    4: begin x = x4 - 1; y = y4 - 1; end
                    5: begin x = x5 - 1; y = y5 - 1; end
                    6: begin x = x6 - 1; y = y6 - 1; end
                    7: begin x = x7 - 1; y = y7 - 1; end
                    8: begin x = x8 - 1; y = y8 - 1; end
                    9: begin x = x9 - 1; y = y9 - 1; end
                endcase

                // Update degrees
                deg[x] = deg[x] + 1;
                deg[y] = deg[y] + 1;

                // Update edge count for the unordered pair
                if (x < y)
                    edge_cnt[x][y] = edge_cnt[x][y] + 1;
                else if (y < x)
                    edge_cnt[y][x] = edge_cnt[y][x] + 1;
            end
        end

        // Count valid pairs (a,b) with a < b, both < n
        result = 0;
        for (a = 0; a < N_MAX; a = a + 1) begin
            if (a < n) begin
                for (b = a + 1; b < N_MAX; b = b + 1) begin
                    if (b < n) begin
                        logic [5:0] agreement = deg[a] + deg[b] - edge_cnt[a][b];
                        if (agreement >= p)
                            result = result + 1;
                    end
                end
            end
        end
    end

endmodule

module FoodAssignment (
  input clk, rst_n,
  input config_en,
  input [3:0] a_in, b_in,  // Chair indices (0-15)
  input [3:0] n,           // Number of couples (1-8)
  output reg done,
  output reg output_valid,
  output reg [2:0] output_index,
  output reg [1:0] output_boy, output_girl
);

  // Internal arrays
  reg [3:0] couple_list_a [0:7];  // Boy chairs
  reg [3:0] couple_list_b [0:7];  // Girl chairs
  reg [3:0] partner [0:15];       // Partner of each chair
  reg [1:0] food [0:15];          // 00=unassigned, 01=food1, 10=food2

  // States
  parameter IDLE=0, CONFIG=1, RUN=2, OUTPUT=3;
  reg [1:0] state;
  reg [2:0] config_index;   // 0-7
  reg [3:0] i_reg;          // Chair index counter
  reg [3:0] temp_j;         // Chain traversal
  reg [1:0] assign_state;   // 0=IDLE, 1=FIND_NEXT, 2=CHAIN
  reg [3:0] max_chairs;     // 2*n

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      // Reset all
      state <= IDLE;
      config_index <= 0;
      done <= 1;
      output_valid <= 0;
      for (integer i=0; i<16; i=i+1) begin
        partner[i] <= 0;
        food[i] <= 0;
      end
      for (integer i=0; i<8; i=i+1) begin
        couple_list_a[i] <= 0;
        couple_list_b[i] <= 0;
      end
    end else begin
      case (state)
        IDLE: if (config_en) begin
          // Start configuration
          couple_list_a[config_index] <= a_in;
          couple_list_b[config_index] <= b_in;
          partner[a_in] <= b_in;
          partner[b_in] <= a_in;
          config_index <= config_index + 1;
          state <= CONFIG;
          done <= 0;
          max_chairs <= (n << 1);  // 2*n
        end

        CONFIG: if (config_en) begin
          if (config_index < 8) begin
            couple_list_a[config_index] <= a_in;
            couple_list_b[config_index] <= b_in;
            partner[a_in] <= b_in;
            partner[b_in] <= a_in;
            config_index <= config_index + 1;
          end
          if (config_index == n-1 && config_en) begin
            state <= RUN;
            i_reg <= 0;
            assign_state <= 1;  // FIND_NEXT
          end
        end

        RUN: begin
          case (assign_state)
            1: begin  // FIND_NEXT
              if (i_reg >= max_chairs) begin
                state <= OUTPUT;
                output_index <= 0;
                output_valid <= 1;
                output_boy <= food[couple_list_a[0]];
                output_girl <= food[couple_list_b[0]];
              end else if (food[i_reg] != 0) begin
                i_reg <= i_reg + 1;
              end else begin
                temp_j <= i_reg;
                assign_state <= 2;  // CHAIN
              end
            end

            2: begin  // CHAIN
              if (food[temp_j] != 0) begin
                i_reg <= i_reg + 1;
                assign_state <= 1;  // Back to FIND_NEXT
              end else begin
                food[temp_j] <= 2'b01;       // Food type 1
                food[temp_j ^ 1] <= 2'b10;   // Food type 2
                temp_j <= partner[temp_j ^ 1];
              end
            end
          endcase
        end

        OUTPUT: begin
          if (output_index < n-1) begin
            output_index <= output_index + 1;
            output_boy <= food[couple_list_a[output_index+1]];
            output_girl <= food[couple_list_b[output_index+1]];
          end else begin
            output_valid <= 0;
            state <= IDLE;
            done <= 1;
          end
        end
      endcase
    end
  end
endmodule

module slime_combiner (
    input wire [16:0] n,
    output reg [7:0] values [0:16],
    output reg [4:0] count
);

integer i;
reg [4:0] idx;

always @(*) begin
    // Initialize all values to 0
    for (i = 0; i < 17; i = i + 1) begin
        values[i] = 8'd0;
    end

    idx = 0;
    // Process bits from high to low
    for (i = 16; i >= 0; i = i - 1) begin
        if (n[i]) begin
