    input clk,
    input rst_n,
    input start,
    input [3:0] actual_length,   // 1 to 16
    input [15:0] string_in,       // each bit: 0 for 'b', 1 for 'w'
    output reg [4:0] result,
    output reg done
);

// Internal state
reg [1:0] state;
reg [4:0] i;          // 0 to 31 (2*n)
reg [3:0] idx;        // circular index (0 to 15)
reg [4:0] run_reg;    // current run length
reg [4:0] max_run_reg; // max run length
reg prev_char;        // previous character
reg [15:0] string_storage;
reg [3:0] n;          // actual_length

// Combinational next index
wire [3:0] next_idx = (idx == n-1) ? 0 : idx + 1;
wire next_char = string_storage[next_idx];

// States
localparam IDLE = 0;
localparam NEXT = 1;
localparam DONE = 2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        idx <= 0;
        run_reg <= 0;
        max_run_reg <= 0;
        prev_char <= 0;
        string_storage <= 0;
        n <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    if (actual_length == 0) begin
                        result <= 0;
                        done <= 1;
                        state <= DONE;
                    end else begin
                        n <= actual_length;
                        string_storage <= string_in;
                        i <= 0;
                        idx <= 0;
                        run_reg <= 1;
                        max_run_reg <= 1;
                        prev_char <= string_in[0];
                        state <= NEXT;
                    end
                end
            end

            NEXT: begin
                // Check alternation
                if (next_char != prev_char) begin
                    if (run_reg < n)
                        run_reg <= run_reg + 1;
                    else
                        run_reg <= n;
                    if (run_reg + 1 > max_run_reg)
                        max_run_reg <= run_reg + 1;
                end else begin
                    run_reg <= 1;
                end

                // Update state
                prev_char <= next_char;
                idx <= next_idx;
                i <= i + 1;

                // Finish after 2*n-1 iterations
                if (i == 2*n - 2)
                    state <= DONE;
            end

            DONE: begin
                // Cap result at n
                result <= (max_run_reg > n) ? n : max_run_reg;
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end
endmodule

module hexagon_triangles (
    input [9:0] a1, a2, a3, a4, a5, a6,
    output [23:0] result
);
    // Combinational logic to compute number of unit triangles
    // Formula: (a1 + a2 + a3)^2 - a1^2 - a3^2 - a5^2
    wire [31:0] sum;
    wire [31:0] sum_sq;
    wire [31:0] a1_sq, a3_sq, a5_sq;

    assign sum = a1 + a2 + a3;
    assign sum_sq = sum * sum;
    assign a1_sq = a1 * a1;
    assign a3_sq = a3 * a3;
    assign a5_sq = a5 * a5;

    assign result = sum_sq - a1_sq - a3_sq - a5_sq;
endmodule

module permutation_generator (
    input [4:0] N, A, B,
    output reg valid,
    output reg [4:0] perm [0:15]
);

    reg [4:0] x, y;
    reg found;
    integer i, k;

    always @(*) begin
        // Step 1: Solve x*A + y*B = N
        found = 0;
        y = 0;
        for (x = 0; x <= 16; x = x + 1) begin
            if (x * A <= N) begin
                if ((N - x * A) % B == 0) begin
                    y = (N - x * A) / B;
                    found = 1;
                    break;
                end
            end
        end

        valid = found;

        // Initialize permutation array
        for (i = 0; i < 16; i = i + 1) begin
            perm[i] = 0;
        end

        if (found) begin
            // Build A cycles
            for (k = 0; k < x; k = k + 1) begin
                for (i = 0; i < A; i = i + 1) begin
                    if (i < A - 1)
                        perm[k*A + i] = k*A + i + 2;
                    else
                        perm[k*A + i] = k*A + 1;
                end
            end

            // Build B cycles
            for (k = 0; k < y; k = k + 1) begin
                for (i = 0; i < B; i = i + 1) begin
                    if (i < B - 1)
                        perm[x*A + k*B + i] = x*A + k*B + i + 2;
                    else
                        perm[x*A + k*B + i] = x*A + k*B + 1;
                end
            end
        end else begin
            // Set -1 (represented as 5'b11111) for invalid case
            perm[0] = 5'b11111;
        end
    end
endmodule

module string_compression (
    input clk,
    input rst_n,
    input start,
    input [7:0] s0, s1, s2, s3, s4, s5, s6, s7,
    input [15:0] a, b,
    input [3:0] n,
    output reg [15:0] min_cost,
    output reg done
);

// Internal registers to store inputs
reg [7:0] s_reg [0:7];
reg [15:0] a_reg, b_reg;
reg [3:0] n_reg;

// Internal tables for LCP and DP
reg [3:0] lcp [0:8][0:8];  // 9x9 to avoid boundary issues
reg [3:0] maxL [0:7];
reg [15:0] dp [0:8];

// Combinational logic for computation
always @(*) begin
    // Initialize LCP table to zero
    for (integer i = 0; i <= 8; i = i + 1) begin
        for (integer j = 0; j <= 8; j = j + 1) begin
            lcp[i][j] = 0;
        end
    end

    // Compute LCP table
    for (integer j = 7; j >= 1; j = j - 1) begin
        for (integer k = j - 1; k >= 0; k = k - 1) begin
            if (s_reg[k] == s_reg[j])
                lcp[k][j] = 1 + lcp[k + 1][j + 1];
            else
                lcp[k][j] = 0;
        end
    end

    // Compute maxL for each position
    for (integer j = 0; j < 8; j = j + 1) begin
        maxL[j] = 0;
        for (integer k = 0; k < j; k = k + 1) begin
            integer L = (lcp[k][j] < (j - k)) ? lcp[k][j] : (j - k);
            if (L > maxL[j])
                maxL[j] = L;
        end
    end

    // Compute DP
    dp[0] = 0;
    for (integer i = 1; i <= 8; i = i + 1) begin
        dp[i] = dp[i - 1] + a_reg;
        for (integer j = 0; j < i; j = j + 1) begin
            if (i - j <= maxL[j]) begin
                if (dp[j] + b_reg < dp[i])
                    dp[i] = dp[j] + b_reg;
            end
        end
    end

    // Output result
    min_cost = dp[n_reg];
end

// Sequential logic for input capture and done signal
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 0;
    end else begin
        if (start) begin
            // Capture inputs
            s_reg[0] <= s0;
            s_reg[1] <= s1;
            s_reg[2] <= s2;
            s_reg[3] <= s3;
            s_reg[4] <= s4;
            s_reg[5] <= s5;
            s_reg[6] <= s6;
            s_reg[7] <= s7;
            a_reg <= a;
            b_reg <= b;
            n_reg <= n;
            done <= 1;
        end else begin
            done <= 0;
        end
    end
end

endmodule

module tree_checker (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,            // number of nodes (2-16)
    input edge_valid,
    input [3:0] edge_u,
    input [3:0] edge_v,
    output reg result,        // 1 for YES (no deg2), 0 for NO (has deg2)
    output reg done
);

// State definitions
localparam IDLE = 2'b00;
localparam LOAD = 2'b01;
localparam CHECK = 2'b10;

reg [1:0] state;
reg [3:0] deg [0:15]; // degree counters for 16 nodes (0-indexed: node1->deg[0])
reg [3:0] edge_count;
wire has_deg2;

// Combinational logic for has_deg2
assign has_deg2 = (deg[0]==4'd2) | (deg[1]==4'd2) | (deg[2]==4'd2) | (deg[3]==4'd2) |
                  (deg[4]==4'd2) | (deg[5]==4'd2) | (deg[6]==4'd2) | (deg[7]==4'd2) |
                  (deg[8]==4'd2) | (deg[9]==4'd2) | (deg[10]==4'd2) | (deg[11]==4'd2) |
                  (deg[12]==4'd2) | (deg[13]==4'd2) | (deg[14]==4'd2) | (deg[15]==4'd2);

// State transition and sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        edge_count <= 4'b0;
        // Reset degree array
        for (integer i=0; i<16; i=i+1) begin
            deg[i] <= 4'b0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    // Reset degree array and edge_count
                    for (integer i=0; i<16; i=i+1) begin
                        deg[i] <= 4'b0;
                    end
                    edge_count <= 4'b0;
                    state <= LOAD;
                end
            end

            LOAD: begin
                if (edge_valid) begin
                    // Update degrees for the edge (convert 1-indexed to 0-indexed)
                    deg[edge_u - 1] <= deg[edge_u - 1] + 1;
                    deg[edge_v - 1] <= deg[edge_v - 1] + 1;
                    edge_count <= edge_count + 1;

                    // Check if this is the last edge (n-1 edges total)
                    if (edge_count + 1 == n - 1) begin
                        state <= CHECK;
                    end
                end
            end

            CHECK: begin
                done <= 1;
                result <= ~has_deg2; // If no degree 2, result=1 (YES), else 0 (NO)
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module TravelCardOptimizer (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] a,      // Regular trip cost
    input wire [7:0] b,      // Transshipment cost
    input wire [3:0] k,      // Max travel cards (0-8)
    input wire [15:0] f,     // Travel card cost
    input wire [2:0] n,      // Number of trips (1-8)
    input wire [31:0] stop1, // Start stop hash
    input wire [31:0] stop2, // End stop hash
    output reg [15:0] total_cost,
    output reg done
);

// Internal memory for route table (max 8 routes)
reg [31:0] route_start [0:7];  // Sorted start (min)
reg [31:0] route_end [0:7];    // Sorted end (max)
reg [15:0] route_cost [0:7];   // Accumulated cost
reg [2:0] route_count;          // Number of routes

// State machine states
localparam IDLE = 4'd0;
localparam PROCESS_TRIP = 4'd1;
localparam UPDATE_ROUTES = 4'd2;
localparam SORT_INIT = 4'd3;
localparam SORT_COMPARE = 4'd4;
localparam SORT_SWAP = 4'd5;
localparam SORT_NEXT = 4'd6;
localparam APPLY_CARDS = 4'd7;
localparam CALC_TOTAL = 4'd8;
localparam FINISH = 4'd9;

reg [3:0] state;
reg [2:0] trip_idx;
reg [31:0] last_end_stop;
reg [31:0] curr_start, curr_end;
reg [15:0] current_cost;
reg [2:0] sort_i, sort_j;
reg [2:0] card_idx;
reg [15:0] temp_cost;

integer i;

// Helper: Find or create route
function [2:0] find_route;
    input [31:0] s1, s2;
    reg [31:0] min_stop, max_stop;
    integer r;
    begin
        min_stop = (s1 < s2) ? s1 : s2;
        max_stop = (s1 < s2) ? s2 : s1;
        find_route = 4'hF;
        for (r = 0; r < route_count; r = r + 1) begin
            if (route_start[r] == min_stop && route_end[r] == max_stop)
                find_route = r;
        end
    end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        total_cost <= 0;
        route_count <= 0;
        trip_idx <= 0;
        last_end_stop <= 0;
        for (i = 0; i < 8; i = i + 1) begin
            route_cost[i] <= 0;
            route_start[i] <= 0;
            route_end[i] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start && n > 0) begin
                    state <= PROCESS_TRIP;
                    trip_idx <= 0;
                    route_count <= 0;
                    last_end_stop <= 0;
                    total_cost <= 0;
                end
            end

            PROCESS_TRIP: begin
                curr_start <= stop1;
                curr_end <= stop2;
                // Calculate trip cost
                current_cost <= (stop1 == last_end_stop) ? {8'd0, b} : {8'd0, a};
                state <= UPDATE_ROUTES;
            end

            UPDATE_ROUTES: begin
                // Update total cost
                total_cost <= total_cost + current_cost;

                // Find existing route or create new
                reg [2:0] route_idx;
                route_idx = find_route(curr_start, curr_end);

                if (route_idx < 4'hF) begin
                    // Existing route
                    route_cost[route_idx] <= route_cost[route_idx] + current_cost;
                end else if (route_count < 8) begin
                    // New route
                    if (curr_start < curr_end) begin
                        route_start[route_count] <= curr_start;
                        route_end[route_count] <= curr_end;
                    end else begin
                        route_start[route_count] <= curr_end;
                        route_end[route_count] <= curr_start;
                    end
                    route_cost[route_count] <= current_cost;
                    route_count <= route_count + 1;
                end

                last_end_stop <= curr_end;

                if (trip_idx + 1 >= n) begin
                    state <= SORT_INIT;
                    sort_i <= 0;
                    sort_j <= 0;
                end else begin
                    state <= PROCESS_TRIP;
                    trip_idx <= trip_idx + 1;
                end
            end

            SORT_INIT: begin
                sort_i <= 0;
                sort_j <= 0;
                state <= SORT_COMPARE;
            end

            SORT_COMPARE: begin
                if (sort_j < route_count - sort_i - 1) begin
                    if (route_cost[sort_j] < route_cost[sort_j + 1]) begin
                        state <= SORT_SWAP;
                    end else begin
                        state <= SORT_NEXT;
                    end
                end else begin
                    sort_i <= sort_i + 1;
                    sort_j <= 0;
                    if (sort_i >= route_count - 2) begin
                        state <= APPLY_CARDS;
                        card_idx <= 0;
                    end else begin
                        state <= SORT_COMPARE;
                    end
                end
            end

            SORT_SWAP: begin
                // Swap cost
                temp_cost <= route_cost[sort_j];
                route_cost[sort_j] <= route_cost[sort_j + 1];
                route_cost[sort_j + 1] <= temp_cost;
                // Swap start/end too
                route_start[sort_j] <= route_start[sort_j + 1];
                route_start[sort_j + 1] <= route_start[sort_j];
                route_end[sort_j] <= route_end[sort_j + 1];
                route_end[sort_j + 1] <= route_end[sort_j];
                state <= SORT_NEXT;
            end

            SORT_NEXT: begin
                sort_j <= sort_j + 1;
                state <= SORT_COMPARE;
            end

            APPLY_CARDS: begin
                if (card_idx < route_count && card_idx < k) begin
                    if (route_cost[card_idx] > f) begin
                        total_cost <= total_cost - (route_cost[card_idx] - f);
                    end
                    card_idx <= card_idx + 1;
                end else begin
                    state <= FINISH;
                end
            end

            FINISH: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module tree_checker(
  input clk,
  input rst_n,
  input start,
  input [2:0] n,           // Number of nodes (1-8)
  input [7:0] c0, c1, c2, c3, c4, c5, c6, c7, // Subtree sizes
  output reg done,
  output reg yes           // Result: 1=valid, 0=invalid
);

// Internal state
reg [2:0] current_node;
reg [2:0] parent [0:7];   // Parent assignment
reg [2:0] children_count [0:7]; // Number of children per node
reg [7:0] subtree_size [0:7];   // Actual computed subtree sizes
reg [7:0] c_array [0:7];        // Input c values stored
reg [2:0] search_depth;
reg found_valid;
reg [2:0] backtrack_node;
reg [2:0] temp_children [0:7];

// Helper to count children and validate
function valid_tree;
  integer i, child_count;
  begin
    valid_tree = 1;
    // Check root has subtree size n
    if (c_array[0] != n) valid_tree = 0;

    // Check no node has size 2
    for (i = 0; i < n; i = i + 1) begin
      if (c_array[i] == 2) valid_tree = 0;
    end

    // Check parent-child relationships
    for (i = 1; i < n; i = i + 1) begin
      if (parent[i] >= n) valid_tree = 0; // Invalid parent
      if (parent[i] == i) valid_tree = 0; // Self-loop
    end

    // Check internal nodes have ≥2 children
    for (i = 0; i < n; i = i + 1) begin
      child_count = children_count[i];
      if (child_count > 0 && child_count < 2) valid_tree = 0;
    end

    // Check computed subtree sizes match input
    for (i = 0; i < n; i = i + 1) begin
      if (subtree_size[i] != c_array[i]) valid_tree = 0;
    end
  end
endfunction

// State machine states
reg [2:0] state;
localparam IDLE = 0;
localparam INIT = 1;
localparam ASSIGN_PARENT = 2;
localparam VALIDATE = 3;
localparam BACKTRACK = 4;
localparam DONE_STATE = 5;

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    done <= 0;
    yes <= 0;
    state <= IDLE;
    found_valid <= 0;
  end else begin
    case (state)
      IDLE: begin
        if (start) begin
          state <= INIT;
          done <= 0;
          found_valid <= 0;
        end
      end

      INIT: begin
        // Initialize
        current_node <= 3'd1;
        parent[0] <= 0; // Root is node 0
        children_count[0] <= 0;
        // Store input c values
        c_array[0] <= c0;
        c_array[1] <= c1;
        c_array[2] <= c2;
        c_array[3] <= c3;
        c_array[4] <= c4;
        c_array[5] <= c5;
        c_array[6] <= c6;
        c_array[7] <= c7;
        // Initialize all parents to invalid
        for (integer i = 1; i < 8; i = i + 1) begin
          parent[i] <= 3'd7; // Invalid
          children_count[i] <= 0;
        end
        state <= ASSIGN_PARENT;
      end

      ASSIGN_PARENT: begin
        // Try to assign parent for current_node
        if (parent[current_node] < n - 1) begin
          parent[current_node] <= parent[current_node] + 1;
          // Update children count
          if (parent[current_node] < n) begin
            children_count[parent[current_node]] <= children_count[parent[current_node]] - 1;
          end
          if (parent[current_node] + 1 < n) begin
            children_count[parent[current_node] + 1] <= children_count[parent[current_node] + 1] + 1;
          end
        end else begin
          // No more parents to try, backtrack
          state <= BACKTRACK;
        end
        state <= VALIDATE;
      end

      VALIDATE: begin
        // Compute subtree sizes
        // This is simplified - real implementation would need recursive computation
        // For now, we use a simplified check
        if (current_node == n - 1) begin
          // Check if this assignment is valid
          if (valid_tree()) begin
            found_valid <= 1;
            state <= DONE_STATE;
          end else begin
            state <= ASSIGN_PARENT;
          end
        end else begin
          current_node <= current_node + 1;
          state <= ASSIGN_PARENT;
        end
      end

      BACKTRACK: begin
        // Move to previous node and try different parent
        if (current_node > 1) begin
          current_node <= current_node - 1;
          parent[current_node] <= 0;
          state <= ASSIGN_PARENT;
        end else begin
          // Cannot backtrack further, no valid tree
          state <= DONE_STATE;
        end
      end

      DONE_STATE: begin
        done <= 1;
        yes <= found_valid;
        if (!start) state <= IDLE;
      end
    endcase
  end
end

endmodule

module power_segment_counter (
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    input [3:0] len,
    input signed [3:0] k,
    output reg [15:0] result,
    output reg done
);
    // Unpack array
    wire [7:0] arr [0:7];
    assign arr[0] = arr_0;
    assign arr[1] = arr_1;
    assign arr[2] = arr_2;
    assign arr[3] = arr_3;
    assign arr[4] = arr_4;
    assign arr[5] = arr_5;
    assign arr[6] = arr_6;
    assign arr[7] = arr_7;

    // State machine parameters
    localparam S_IDLE = 0;
    localparam S_ADD = 1;
    localparam S_CHECK_POWER = 2;
    localparam S_CHECK_POWER_LOOP = 3;
    localparam S_CHECK_POWER_END = 4;
    localparam S_NEXT_J = 5;
    localparam S_NEXT_I = 6;
    localparam S_DONE = 7;

    reg [2:0] state;
    reg [3:0] i, j;
    reg signed [15:0] sum;
    reg signed [15:0] p;
    reg found;
    reg [15:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            i <= 0;
            j <= 0;
            sum <= 0;
            p <= 0;
            found <= 0;
            count <= 0;
            result <= 0;
            done <= 0;
        end else begin
            case (state)
                S_IDLE: begin
                    done <= 0;
                    if (start) begin
                        i <= 0;
                        j <= 0;
                        sum <= 0;
                        count <= 0;
                        state <= S_ADD;
                    end
                end

                S_ADD: begin
                    if (j < len) begin
                        sum <= sum + $signed(arr[j]);
                        state <= S_CHECK_POWER;
                    end else begin
                        state <= S_NEXT_I;
                    end
                end

                S_CHECK_POWER: begin
                    if (k == 1) begin
                        found <= (sum == 1);
                        state <= S_CHECK_POWER_END;
                    end else if (k == -1) begin
                        found <= (sum == 1) || (sum == -1);
                        state <= S_CHECK_POWER_END;
                    end else begin
                        p <= 1;
                        state <= S_CHECK_POWER_LOOP;
                    end
                end

                S_CHECK_POWER_LOOP: begin
                    // Check if |p| > 1016 or p == sum
                    if (p[15] ? (-p > 16'sd1016) : (p > 16'sd1016)) begin
                        found <= 0;
                        state <= S_CHECK_POWER_END;
                    end else if (p == sum) begin
                        found <= 1;
                        state <= S_CHECK_POWER_END;
                    end else begin
                        p <= p * k;
                        // Stay in same state
                    end
                end

                S_CHECK_POWER_END: begin
                    if (found) count <= count + 1;
                    state <= S_NEXT_J;
                end

                S_NEXT_J: begin
                    j <= j + 1;
                    state <= S_ADD;
                end

                S_NEXT_I: begin
                    i <= i + 1;
                    if (i < len) begin
                        j <= i;
                        sum <= 0;
                        state <= S_ADD;
                    end else begin
                        state <= S_DONE;
                    end
                end

                S_DONE: begin
                    result <= count;
                    done <= 1;
                    state <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end
endmodule

module domino_coloring (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] segment_types,  // bit i: 0=X (vertical domino), 1=Y (horizontal segment)
    input wire [3:0] num_segments,   // number of segments (1-8)
    output reg [31:0] result,
    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam DONE = 2'b10;

    // Modulo constant: 1000000007
    localparam MOD = 32'd1000000007;

    // Registers
    reg [1:0] state;
    reg [7:0] types_reg;      // Registered copy of segment_types
    reg [3:0] num_segs_reg;   // Registered copy of num_segments
    reg [3:0] idx;            // Current segment index
    reg prev_type;            // Previous segment type
    reg first_seg;            // First segment flag
    reg [31:0] temp_result;   // Temporary result during computation

    // Combinational: current segment type
    wire curr_type = types_reg[idx];

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 32'd0;
            done <= 1'b0;
            types_reg <= 8'b0;
            num_segs_reg <= 4'b0;
            idx <= 4'd0;
            prev_type <= 1'b0;
            first_seg <= 1'b1;
            temp_result <= 32'd1;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPUTE;
                        types_reg <= segment_types;  // Register inputs
                        num_segs_reg <= num_segments;
                        idx <= 4'd0;
                        first_seg <= 1'b1;
                        temp_result <= 32'd1;
                    end
                end

                COMPUTE: begin
                    if (idx < num_segs_reg) begin
                        // Compute multiplier based on segment types
                        if (first_seg) begin
                            // First segment: 3 if vertical (X), 6 if horizontal (Y)
                            if (curr_type == 1'b0) begin
                                temp_result <= (temp_result * 32'd3) % MOD;
                            end else begin
                                temp_result <= (temp_result * 32'd6) % MOD;
                            end
                            first_seg <= 1'b0;
                        end else begin
                            // Subsequent segments: use case statement for clarity
                            case ({prev_type, curr_type})
                                2'b00: temp_result <= (temp_result * 32'd2) % MOD;  // X then X
                                2'b01: temp_result <= (temp_result * 32'd2) % MOD;  // X then Y
                                2'b10: temp_result <= temp_result;                  // Y then X (factor 1)
                                2'b11: temp_result <= (temp_result * 32'd3) % MOD;  // Y then Y
                            endcase
                        end
                        prev_type <= curr_type;
                        idx <= idx + 1'b1;
                    end else begin
                        // All segments processed
                        result <= temp_result;
                        state <= DONE;
                        done <= 1'b1;
                    end
                end

                DONE: begin
                    done <= 1'b0;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module MinMexOptimizer (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,
    input wire [3:0] m,
    input wire valid_in,
    input wire [3:0] l_in,
    input wire [3:0] r_in,
    output reg [4:0] min_length,
    output reg [63:0] result_array,
    output reg done
);
    localparam IDLE = 2'b00;
    localparam PROCESS = 2'b01;
    localparam GENERATE = 2'b10;

    reg [1:0] state;
    reg [3:0] query_count;
    reg [4:0] current_min;
    reg [4:0] length;
    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            min_length <= 0;
            result_array <= 0;
            query_count <= 0;
            current_min <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        query_count <= 0;
                        current_min <= 5'b11111; // Initialize to max value
                        state <= PROCESS;
                    end
                end

                PROCESS: begin
                    if (valid_in && (query_count < m)) begin
                        length <= r_in - l_in + 1;
                        if (length < current_min)
                            current_min <= length;
                        query_count <= query_count + 1;
                    end else if (query_count == m) begin
                        state <= GENERATE;
                    end
                end

                GENERATE: begin
                    // Generate array using periodic pattern
                    for (i = 0; i < 16; i = i + 1) begin
                        if (i < n) begin
                            // Compute modulus without division (small values)
                            if (current_min != 0) begin
                                result_array[i*4 +: 4] <= i % current_min;
                            end else begin
                                result_array[i*4 +: 4] <= 4'b0000;
                            end
                        end else begin
                            result_array[i*4 +: 4] <= 4'b0000;
                        end
                    end
                    min_length <= current_min;
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module bipartite_remover #(
    parameter N = 4,
    parameter W = 16
)(
    input wire [W-1:0] arr [0:N-1],
    output wire [N-1:0] remove_mask
);

    function automatic [3:0] trailing_zeros;
        input [W-1:0] val;
        integer i;
        reg found;
        begin
            found = 0;
            trailing_zeros = 0;
            for (i = 0; i < W; i = i + 1) begin
                if (val[i] && !found) begin
                    trailing_zeros = i;
                    found = 1;
                end
            end
        end
    endfunction

    wire [3:0] tz [0:N-1];
    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : tz_gen
            assign tz[g] = trailing_zeros(arr[g]);
        end
    endgenerate

    reg [3:0] mode;
    integer i, j;
    reg [3:0] max_count;
    reg [3:0] count_i;

    always @(*) begin
        max_count = 0;
        mode = tz[0];
        for (i = 0; i < N; i = i + 1) begin
            count_i = 0;
            for (j = 0; j < N; j = j + 1) begin
                if (tz[j] == tz[i]) count_i = count_i + 1;
            end
            if (count_i > max_count) begin
                max_count = count_i;
                mode = tz[i];
            end
        end
    end

    reg [N-1:0] mask;
    always @(*) begin
        mask = 0;
        for (i = 0; i < N; i = i + 1) begin
            if (tz[i] != mode) mask[i] = 1;
        end
    end

    assign remove_mask = mask;

endmodule

