    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state;
    reg [63:0] x, y;
    reg [63:0] a_reg, b_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        a_reg <= a;
                        b_reg <= b;
                        state <= COMPUTE;
                        done <= 0;
                    end
                end

                COMPUTE: begin
                    if (b_reg == 0) begin
                        result <= a_reg;
                        state <= FINISH;
                    end else begin
                        x <= a_reg;
                        y <= b_reg;
                        a_reg <= y;
                        b_reg <= x % y;
                    end
                end

                FINISH: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

