    reg [MAX_ROWS-1:0] row_mask;
    wire [MAX_ROWS:0] limit;
    assign limit = 1 << r_cnt;

    wire [RESULT_WIDTH-1:0] sum_rows_comb;
    wire [RESULT_WIDTH-1:0] sum_cols_comb;
    wire [RESULT_WIDTH-1:0] total_comb;

