                failed += 1
            else:
                dut._log.info(f"  PASS: Got expected {result_arr}")
                passed += 1

    # Summary
    dut._log.info(f"{'='*50}")
    dut._log.info(f"Results: {passed}/{passed+failed} tests passed")

    if failed > 0:
        raise TestFailure(f"{failed} tests failed")

