reg [DATA_WIDTH-1:0] current_max;
reg [DATA_WIDTH-1:0] temp_sum;
reg [3:0] swap_count;
reg [3:0] inner_size;
reg [3:0] outer_size;
reg signed [DATA_WIDTH-1:0] inner_sorted [0:N-1];
reg signed [DATA_WIDTH-1:0] outer_sorted [0:N-1];
reg [3:0] sort_idx;
reg [3:0] swap_idx;

// Helper function for min
function [3:0] min;
    input [3:0] a, b;
    begin
        min = (a < b) ? a : b;
    end
endfunction

// Bubble sort for inner array (ascending)
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sort_idx <= 0;
    end else if (state == COMPUTE) begin
        if (sort_idx < inner_size - 1) begin
            if (inner_sorted[sort_idx] > inner_sorted[sort_idx + 1]) begin
                inner_sorted[sort_idx] <= inner_sorted[sort_idx + 1];
                inner_sorted[sort_idx + 1] <= inner_sorted[sort_idx];
            end
            sort_idx <= sort_idx + 1;
        end else begin
            sort_idx <= 0;
        end
    end else if (state == UPDATE) begin
        sort_idx <= 0;
    end
end

// Bubble sort for outer array (descending)
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset handled elsewhere
    end else if (state == COMPUTE) begin
        if (sort_idx < outer_size - 1) begin
            if (outer_sorted[sort_idx] < outer_sorted[sort_idx + 1]) begin
                outer_sorted[sort_idx] <= outer_sorted[sort_idx + 1];
                outer_sorted[sort_idx + 1] <= outer_sorted[sort_idx];
            end
        end
    end
end

// Swap comparison logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        swap_count <= 0;
        temp_sum <= 0;
    end else if (state == COMPUTE && sort_idx >= inner_size - 1 && sort_idx >= outer_size - 1) begin
        if (swap_count < min(K, min(inner_size, outer_size))) begin
            if (outer_sorted[swap_count] > inner_sorted[swap_count]) begin
                temp_sum <= temp_sum + (outer_sorted[swap_count] - inner_sorted[swap_count]);
            end
            swap_count <= swap_count + 1;
        end
    end else if (state == UPDATE) begin
        swap_count <= 0;
        temp_sum <= 0;
    end
end

// Main state machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        l <= 0;
        r <= 0;
        current_max <= {DATA_WIDTH{1'b1}}; // Initialize to minimum value
        inner_size <= 0;
        outer_size <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= COMPUTE;
                    l <= 0;
                    r <= 0;
                    current_max <= {DATA_WIDTH{1'b1}};
                end
            end

            COMPUTE: begin
                // Extract inner and outer arrays
                if (l == 0 && r == 0) begin
                    for (integer i = 0; i < N; i = i + 1) begin
                        if (i >= l && i <= r) begin
                            inner_sorted[i] <= a[i];
                        end else begin
                            outer_sorted[i] <= a[i];
                        end
                    end
                    inner_size <= r - l + 1;
                    outer_size <= N - (r - l + 1);
                    sort_idx <= 0;
                    swap_count <= 0;
                    temp_sum <= 0;
                    // Calculate initial sum of inner array
                    for (integer j = 0; j < N; j = j + 1) begin
                        if (j >= l && j <= r) begin
                            temp_sum <= temp_sum + a[j];
                        end
                    end
                end

                // After sorting and swapping completes, move to UPDATE
                if (swap_count >= min(K, min(inner_size, outer_size)) && 
                    sort_idx >= inner_size - 1 && sort_idx >= outer_size - 1) begin
                    state <= UPDATE;
                end
            end

            UPDATE: begin
                if (temp_sum > current_max) begin
                    current_max <= temp_sum;
                end

                // Move to next subarray
                if (r < N - 1) begin
                    r <= r + 1;
                    state <= COMPUTE;
                end else if (l < N - 2) begin
                    l <= l + 1;
                    r <= l + 1;
                    state <= COMPUTE;
                end else begin
                    state <= FINISHED;
                end
            end

            FINISHED: begin
                // Stay here until reset
            end
        endcase
    end
end

assign max_sum = current_max;
assign done = (state == FINISHED);

endmodule

module purification (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,
    input wire [15:0] grid [0:15],
    output reg output_valid,
    output reg [3:0] row_out,
    output reg [3:0] col_out,
    output reg done,
    output reg no_solution
);

localparam IDLE = 3'b000;
localparam CHECK_ROWS = 3'b001;
localparam DECIDE = 3'b010;
localparam OUTPUT = 3'b011;
localparam OUTPUT_NEXT = 3'b100;

reg [2:0] state;
reg [3:0] i, j;
reg [15:0] row_has_dot;
reg [15:0] col_has_dot;
reg [3:0] row_dot_col [0:15];
reg [3:0] col_dot_row [0:15];
reg [1:0] mode;

integer k;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        output_valid <= 0;
        done <= 0;
        no_solution <= 0;
        i <= 0;
        j <= 0;
        row_has_dot <= 0;
        col_has_dot <= 0;
        mode <= 0;
        for (k = 0; k < 16; k = k + 1) begin
            row_dot_col[k] <= 0;
            col_dot_row[k] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                output_valid <= 0;
                done <= 0;
                no_solution <= 0;
                if (start) begin
                    state <= CHECK_ROWS;
                    i <= 0;
                    j <= 0;
                    row_has_dot <= 0;
                    col_has_dot <= 0;
                    for (k = 0; k < 16; k = k + 1) begin
                        row_dot_col[k] <= 0;
                        col_dot_row[k] <= 0;
                    end
                end
            end

            CHECK_ROWS: begin
                if (i < n) begin
                    if (j < n) begin
                        if (grid[i][j] == 0) begin
                            if (!row_has_dot[i]) begin
                                row_dot_col[i] <= j;
                                row_has_dot[i] <= 1;
                            end
                            if (!col_has_dot[j]) begin
                                col_dot_row[j] <= i;
                                col_has_dot[j] <= 1;
                            end
                        end
                        j <= j + 1;
                    end else begin
                        j <= 0;
                        i <= i + 1;
                    end
                end else begin
                    i <= 0;
                    j <= 0;
                    state <= DECIDE;
                end
            end

            DECIDE: begin
                if (&row_has_dot[0+:n]) begin
                    mode <= 0;
                end else if (&col_has_dot[0+:n]) begin
                    mode <= 1;
                end else begin
                    mode <= 2;
                end
                i <= 0;
                state <= OUTPUT;
            end

            OUTPUT: begin
                if (mode == 0 || mode == 1) begin
                    if (i < n) begin
                        if (mode == 0) begin
                            row_out <= i + 1;
                            col_out <= row_dot_col[i] + 1;
                        end else begin
                            row_out <= col_dot_row[i] + 1;
                            col_out <= i + 1;
                        end
                        output_valid <= 1;
                        i <= i + 1;
                        state <= OUTPUT_NEXT;
                    end else begin
                        done <= 1;
                        state <= IDLE;
                    end
                end else begin
                    no_solution <= 1;
                    done <= 1;
                    state <= IDLE;
                end
            end

            OUTPUT_NEXT: begin
                output_valid <= 0;
                state <= OUTPUT;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module treeland_max_distance (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,          // Number of towns (1-16)
    input [3:0] k,          // Number of university pairs (1-8)
    input [15:0] universities, // Bitmask of towns with universities (16 bits)
    input [15:0] adj [0:15], // Adjacency matrix for tree connections
    output reg [7:0] result,
    output reg done
);

    // Internal registers and state machine
    reg [2:0] state;
    reg [3:0] node_counter;
    reg [3:0] parent [0:15];
    reg [3:0] subtree_count [0:15];
    reg [7:0] total_distance;
    reg [3:0] i, j;
    reg [15:0] visited;
    reg [3:0] queue [0:15];
    reg [3:0] head, tail;
    reg [3:0] bfs_order [0:15];
    reg [3:0] bfs_index;

    // States
    localparam IDLE = 3'b000;
    localparam BUILD_TREE = 3'b001;
    localparam CALC_SUBTREE = 3'b010;
    localparam CALC_DISTANCE = 3'b011;
    localparam DONE_STATE = 3'b100;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            total_distance <= 0;
            visited <= 0;
            head <= 0;
            tail <= 0;
            bfs_index <= 0;
            node_counter <= 0;
            for (integer idx = 0; idx < 16; idx = idx + 1) begin
                parent[idx] <= 4'b1111; // Mark as invalid
                subtree_count[idx] <= 0;
                bfs_order[idx] <= 0;
                queue[idx] <= 0;
            end
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        // Initialize subtree counts with university markers
                        for (integer idx = 0; idx < 16; idx = idx + 1) begin
                            subtree_count[idx] <= universities[idx] ? 4'b0001 : 4'b0000;
                        end
                        state <= BUILD_TREE;
                        node_counter <= 0;
                        visited <= 16'b0000000000000001; // Mark node 0 as visited
                        parent[0] <= 0;
                        head <= 0;
                        tail <= 1;
                        queue[0] <= 0;
                        bfs_index <= 0;
                    end
                end

                BUILD_TREE: begin
                    // BFS to build tree structure and get order
                    if (head < tail) begin
                        // Dequeue current node
                        i <= queue[head];
                        head <= head + 1;
                        j <= 0;
                        state <= BUILD_TREE; // Stay for neighbor processing
                    end else if (bfs_index < 16) begin
                        // Process nodes in reverse BFS order for subtree calculation
                        state <= CALC_SUBTREE;
                        node_counter <= 15; // Start from last node
                    end else begin
                        state <= IDLE;
                    end
                end

                CALC_SUBTREE: begin
                    if (node_counter > 0) begin
                        // For each node except root, add its subtree count to parent
                        if (parent[node_counter] != 4'b1111 && parent[node_counter] != node_counter) begin
                            subtree_count[parent[node_counter]] <= subtree_count[parent[node_counter]] + subtree_count[node_counter];
                        end
                        node_counter <= node_counter - 1;
                    end else begin
                        state <= CALC_DISTANCE;
                        node_counter <= 1; // Start from node 1 (skip root)
                        total_distance <= 0;
                    end
                end

                CALC_DISTANCE: begin
                    if (node_counter < n) begin
                        // For each edge, calculate contribution
                        if (subtree_count[node_counter] > 0 && subtree_count[node_counter] < (k << 1)) begin
                            // Contribution = min(subtree_count, 2*k - subtree_count)
                            if (subtree_count[node_counter] <= k) begin
                                total_distance <= total_distance + subtree_count[node_counter];
                            end else begin
                                total_distance <= total_distance + ((k << 1) - subtree_count[node_counter]);
                            end
                        end
                        node_counter <= node_counter + 1;
                    end else begin
                        state <= DONE_STATE;
                        result <= total_distance;
                        done <= 1;
                    end
                end

                DONE_STATE: begin
                    if (!start) begin
                        state <= IDLE;
                        done <= 0;
                    end
                end

                default: state <= IDLE;
            endcase

            // BUILD_TREE neighbor processing (combinational logic within state)
            if (state == BUILD_TREE && head < tail) begin
                if (j < 16) begin
                    if (adj[i][j] && !visited[j]) begin
                        parent[j] <= i;
                        visited[j] <= 1'b1;
                        queue[tail] <= j;
                        tail <= tail + 1;
                        bfs_order[bfs_index] <= j;
                        bfs_index <= bfs_index + 1;
                    end
                    j <= j + 1;
                end
            end
        end
    end
endmodule

// Test Interface:
// - n: 4-bit input (1-16)
// - k: 4-bit input (1-8)  
// - universities: 16-bit bitmask where bit i=1 if town i has a university
// - adj[15:0]: 16x16 adjacency matrix for tree connections
// - result: 8-bit output for maximum total distance
// - done: pulses high when computation completes

module zebra_divider (
  input clk,
  input rst_n,
  input start,
  input [15:0] s,
  input [3:0] length,
  output reg valid,
  output reg [3:0] k,
  output reg [3:0] zebra_length [0:15],
  output reg [4:0] zebra_indices [0:15][0:15],
  output reg done
);

  localparam IDLE = 2'b00;
  localparam PROCESS = 2'b01;
  localparam DONE = 2'b10;

  reg [1:0] state, next_state;
  reg [4:0] pos;
  reg [3:0] num_zebras;
  reg [3:0] stack0 [0:15];
  reg [3:0] stack1 [0:15];
  reg [4:0] stack0_ptr, stack1_ptr;
  reg [4:0] zebras [0:15][0:15];
  reg [4:0] zebra_length_reg [0:15];

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      pos <= 0;
      num_zebras <= 0;
      stack0_ptr <= 0;
      stack1_ptr <= 0;
      valid <= 0;
      done <= 0;
      k <= 0;
      for (integer i = 0; i < 16; i = i + 1) begin
        zebra_length_reg[i] <= 0;
        zebra_length[i] <= 0;
        for (integer j = 0; j < 16; j = j + 1) begin
          zebras[i][j] <= 0;
          zebra_indices[i][j] <= 0;
        end
      end
    end else begin
      case (state)
        IDLE: begin
          if (start) begin
            state <= PROCESS;
            pos <= 0;
            num_zebras <= 0;
            stack0_ptr <= 0;
            stack1_ptr <= 0;
            valid <= 0;
            done <= 0;
            k <= 0;
            for (integer i = 0; i < 16; i = i + 1) begin
              zebra_length_reg[i] <= 0;
              zebra_length[i] <= 0;
              for (integer j = 0; j < 16; j = j + 1) begin
                zebras[i][j] <= 0;
                zebra_indices[i][j] <= 0;
              end
            end
          end
        end

        PROCESS: begin
          if (pos < length) begin
            if (s[pos] == 1'b0) begin
              if (stack1_ptr > 0) begin
                stack1_ptr <= stack1_ptr - 1;
                zebras[stack1[stack1_ptr-1]][zebra_length_reg[stack1[stack1_ptr-1]]] <= pos + 1;
                zebra_length_reg[stack1[stack1_ptr-1]] <= zebra_length_reg[stack1[stack1_ptr-1]] + 1;
                stack0[stack0_ptr] <= stack1[stack1_ptr-1];
                stack0_ptr <= stack0_ptr + 1;
              end else begin
                zebras[num_zebras][0] <= pos + 1;
                zebra_length_reg[num_zebras] <= 1;
                stack0[stack0_ptr] <= num_zebras;
                stack0_ptr <= stack0_ptr + 1;
                num_zebras <= num_zebras + 1;
              end
            end else begin
              if (stack0_ptr == 0) begin
                state <= DONE;
                valid <= 0;
                done <= 1;
              end else begin
                stack0_ptr <= stack0_ptr - 1;
                zebras[stack0[stack0_ptr-1]][zebra_length_reg[stack0[stack0_ptr-1]]] <= pos + 1;
                zebra_length_reg[stack0[stack0_ptr-1]] <= zebra_length_reg[stack0[stack0_ptr-1]] + 1;
                stack1[stack1_ptr] <= stack0[stack0_ptr-1];
                stack1_ptr <= stack1_ptr + 1;
              end
            end
            pos <= pos + 1;
          end else begin
            state <= DONE;
            done <= 1;
            if (stack1_ptr == 0) begin
              valid <= 1;
              k <= num_zebras;
              for (integer i = 0; i < 16; i = i + 1) begin
                zebra_length[i] <= zebra_length_reg[i];
                for (integer j = 0; j < 16; j = j + 1) begin
                  zebra_indices[i][j] <= zebras[i][j];
                end
              end
            end else begin
              valid <= 0;
            end
          end
        end

        DONE: begin
          // Stay in done state until reset
        end
      endcase
    end
  end

endmodule

