module pokemon_evolution(
    input clk,
    input rst_n,
    input start,
    input [2:0] g1, g2,
    input [5:0] types1, types2,
    output reg [15:0] result,
    output reg done
);
    // Precompute factorials for 0,1,2,3
    function [15:0] factorial;
        input [1:0] n;
        begin
            case(n)
                2'd0: factorial = 1;
                2'd1: factorial = 1;
                2'd2: factorial = 2;
                2'd3: factorial = 6;
                default: factorial = 1;
            endcase
        end
    endfunction

    // Type encoding: 01=1, 10=2, 11=3
    wire [1:0] count_gym1_type1, count_gym1_type2, count_gym1_type3;
    wire [1:0] count_gym2_type1, count_gym2_type2, count_gym2_type3;

    // Count occurrences in gym1
    assign count_gym1_type1 = 
        (g1 >= 1 && types1[1:0] == 2'b01 ? 1 : 0) +
        (g1 >= 2 && types1[3:2] == 2'b01 ? 1 : 0) +
        (g1 >= 3 && types1[5:4] == 2'b01 ? 1 : 0);
    assign count_gym1_type2 = 
        (g1 >= 1 && types1[1:0] == 2'b10 ? 1 : 0) +
        (g1 >= 2 && types1[3:2] == 2'b10 ? 1 : 0) +
        (g1 >= 3 && types1[5:4] == 2'b10 ? 1 : 0);
    assign count_gym1_type3 = 
        (g1 >= 1 && types1[1:0] == 2'b11 ? 1 : 0) +
        (g1 >= 2 && types1[3:2] == 2'b11 ? 1 : 0) +
        (g1 >= 3 && types1[5:4] == 2'b11 ? 1 : 0);

    // Count occurrences in gym2
    assign count_gym2_type1 = 
        (g2 >= 1 && types2[1:0] == 2'b01 ? 1 : 0) +
        (g2 >= 2 && types2[3:2] == 2'b01 ? 1 : 0) +
        (g2 >= 3 && types2[5:4] == 2'b01 ? 1 : 0);
    assign count_gym2_type2 = 
        (g2 >= 1 && types2[1:0] == 2'b10 ? 1 : 0) +
        (g2 >= 2 && types2[3:2] == 2'b10 ? 1 : 0) +
        (g2 >= 3 && types2[5:4] == 2'b10 ? 1 : 0);
    assign count_gym2_type3 = 
        (g2 >= 1 && types2[1:0] == 2'b11 ? 1 : 0) +
        (g2 >= 2 && types2[3:2] == 2'b11 ? 1 : 0) +
        (g2 >= 3 && types2[5:4] == 2'b11 ? 1 : 0);

    // Form keys (4-bit: gym1 count, gym2 count)
    wire [3:0] key1 = {count_gym1_type1, count_gym2_type1};
    wire [3:0] key2 = {count_gym1_type2, count_gym2_type2};
    wire [3:0] key3 = {count_gym1_type3, count_gym2_type3};

    // Combinational grouping and product calculation
    reg [15:0] result_comb;
    always @(*) begin
        reg [1:0] group_count;
        reg [2:0] counted;
        reg [15:0] product;

        counted = 3'b000;
        product = 1;

        // Process type1
        if (!counted[0]) begin
            group_count = 1;
            counted[0] = 1;
            if (key2 == key1) begin
                group_count = group_count + 1;
                counted[1] = 1;
            end
            if (key3 == key1) begin
                group_count = group_count + 1;
                counted[2] = 1;
            end
            product = product * factorial(group_count);
        end

        // Process type2
        if (!counted[1]) begin
            group_count = 1;
            counted[1] = 1;
            if (key3 == key2) begin
                group_count = group_count + 1;
                counted[2] = 1;
            end
            product = product * factorial(group_count);
        end

        // Process type3
        if (!counted[2]) begin
            group_count = 1;
            product = product * factorial(group_count);
        end

        result_comb = product;
    end

    // Sequential output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 0;
            done <= 0;
        end else begin
            if (start) begin
                result <= result_comb;
                done <= 1;
            end else begin
                done <= 0;
            end
        end
    end
endmodule

module maze_solver #(
    parameter MOD = 32'd1000000007,
    parameter MAX_N = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,           // Number of rooms (1 to 8)
    input wire [3:0] p_0, p_1, p_2, p_3, p_4, p_5, p_6, p_7,
    output reg [31:0] result,
    output reg done
);
    // State machine states
    reg [1:0] state;
    localparam S_IDLE = 2'b00;
    localparam S_COMPUTE = 2'b01;
    localparam S_DONE = 2'b10;

    // Data registers
    reg [3:0] i;  // Counter from 1 to n
    reg [31:0] dp [0:MAX_N];  // DP array: dp[0] through dp[8]

    // Helper: select current p value
    wire [3:0] p_val;
    assign p_val = (i == 4'd1) ? p_0 :
                   (i == 4'd2) ? p_1 :
                   (i == 4'd3) ? p_2 :
                   (i == 4'd4) ? p_3 :
                   (i == 4'd5) ? p_4 :
                   (i == 4'd6) ? p_5 :
                   (i == 4'd7) ? p_6 : p_7;

    // State machine and sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            i <= 4'd0;
            result <= 32'd0;
            done <= 1'b0;
            dp[0] <= 32'd0;
            // Initialize all dp entries to 0
            dp[1] <= 32'd0;
            dp[2] <= 32'd0;
            dp[3] <= 32'd0;
            dp[4] <= 32'd0;
            dp[5] <= 32'd0;
            dp[6] <= 32'd0;
            dp[7] <= 32'd0;
            dp[8] <= 32'd0;
        end else begin
            case (state)
                S_IDLE: begin
                    done <= 1'b0;
                    if (start && n != 0) begin
                        state <= S_COMPUTE;
                        i <= 4'd1;
                    end
                end

                S_COMPUTE: begin
                    // Compute dp[i] = (2*dp[i-1] + 2 - dp[p_val-1]) mod MOD
                    // Use (a + MOD - b) to handle negative correctly
                    dp[i] <= (2 * dp[i-1] + 2 + MOD - dp[p_val-1]) % MOD;

                    if (i == n) begin
                        state <= S_DONE;
                        result <= (2 * dp[i-1] + 2 + MOD - dp[p_val-1]) % MOD;
                        done <= 1'b1;
                    end else begin
                        i <= i + 1;
                    end
                end

                S_DONE: begin
                    if (!start) begin
                        state <= S_IDLE;
                        done <= 1'b0;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module max_f #(parameter N=8) (
    input [63:0] a [0:N-1],
    output reg [63:0] max_value
);
    // Compute differences
    wire [63:0] diff [0:N-2];
    generate
        for (genvar i = 0; i < N-1; i = i+1) begin : diff_gen
            assign diff[i] = (a[i] > a[i+1]) ? (a[i] - a[i+1]) : (a[i+1] - a[i]);
        end
    endgenerate

    // Compute signed sequences b1 and b2
    wire signed [63:0] b1 [0:N-2];
    wire signed [63:0] b2 [0:N-2];
    generate
        for (genvar i = 0; i < N-1; i = i+1) begin : b_gen
            assign b1[i] = (i[0] == 0) ? diff[i] : -diff[i];
            assign b2[i] = -b1[i];
        end
    endgenerate

    // Kadane's algorithm for b1
    wire signed [63:0] max_b1;
    kadane #(.LEN(N-1)) kadane_b1 (.arr(b1), .max_sum(max_b1));

    // Kadane's algorithm for b2
    wire signed [63:0] max_b2;
    kadane #(.LEN(N-1)) kadane_b2 (.arr(b2), .max_sum(max_b2));

    // Final maximum
    always @(*) begin
        max_value = (max_b1 > max_b2) ? max_b1 : max_b2;
    end

endmodule

module kadane #(parameter LEN=7) (
    input signed [63:0] arr [0:LEN-1],
    output reg signed [63:0] max_sum
);

    integer i;
    reg signed [63:0] max_ending_here;
    reg signed [63:0] max_so_far;

    always @(*) begin
        max_ending_here = arr[0];
        max_so_far = arr[0];
        for (i = 1; i < LEN; i = i + 1) begin
            if (max_ending_here + arr[i] > arr[i])
                max_ending_here = max_ending_here + arr[i];
            else
                max_ending_here = arr[i];
            if (max_ending_here > max_so_far)
                max_so_far = max_ending_here;
        end
        max_sum = max_so_far;
    end

endmodule

