module max_points #(
    parameter MAX_VAL = 64,       // Maximum value (0 to 63)
    parameter MAX_INPUT_LEN = 16, // Maximum number of input elements
    parameter VAL_BITS = 6,       // Bits to represent a value
    parameter CNT_BITS = 5,       // Bits for frequency count (max 16)
    parameter RESULT_BITS = 16    // Bits for result
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [VAL_BITS-1:0] arr [0:MAX_INPUT_LEN-1],
    input wire [3:0] len,
    output wire [RESULT_BITS-1:0] result,
    output wire done
);
    // State definitions
    localparam IDLE = 2'b00;
    localparam LOAD = 2'b01;
    localparam DP = 2'b10;
    localparam DONE = 2'b11;

    reg [1:0] state, next_state;
    reg [3:0] load_idx;
    reg [5:0] dp_idx;
    reg [CNT_BITS-1:0] freq [0:MAX_VAL-1];
    reg [RESULT_BITS-1:0] dp_prev, dp_curr;
    reg [RESULT_BITS-1:0] result_reg;
    reg done_reg;

    // Combinational DP calculation
    wire [RESULT_BITS-1:0] contribution;
    wire [RESULT_BITS-1:0] dp_new;

    assign contribution = dp_idx * freq[dp_idx];
    assign dp_new = (dp_curr > dp_prev + contribution) ? dp_curr : (dp_prev + contribution);

    assign result = result_reg;
    assign done = done_reg;

    // State transition and sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            load_idx <= 0;
            dp_idx <= 0;
            dp_prev <= 0;
            dp_curr <= 0;
            result_reg <= 0;
            done_reg <= 0;
            // Clear frequency array
            for (integer i = 0; i < MAX_VAL; i = i + 1) begin
                freq[i] <= 0;
            end
        end else begin
            done_reg <= 0; // default, may be overridden
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= LOAD;
                        load_idx <= 0;
                        // Clear frequency array for new computation
                        for (integer i = 0; i < MAX_VAL; i = i + 1) begin
                            freq[i] <= 0;
                        end
                    end
                end
                LOAD: begin
                    if (load_idx < len) begin
                        // Increment frequency of the current element
                        freq[arr[load_idx]] <= freq[arr[load_idx]] + 1;
                        load_idx <= load_idx + 1;
                    end else begin
                        state <= DP;
                        dp_idx <= 0;
                        dp_prev <= 0;
                        dp_curr <= 0;
                    end
                end
                DP: begin
                    if (dp_idx < MAX_VAL) begin
                        // Update dp registers
                        dp_prev <= dp_curr;
                        dp_curr <= dp_new;
                        dp_idx <= dp_idx + 1;
                    end else begin
                        state <= DONE;
                        result_reg <= dp_curr;
                        done_reg <= 1; // Pulse done
                    end
                end
                DONE: begin
                    state <= IDLE;
                    // done_reg will be cleared in next cycle (already set to 0 at start of always)
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module paint_the_numbers (
    input clk, rst_n, start,
    input [6:0] n,  // Number of elements (1-16)
    input [7:0] arr_0, arr_1, arr_2, arr_3,
    input [7:0] arr_4, arr_5, arr_6, arr_7,
    input [7:0] arr_8, arr_9, arr_10, arr_11,
    input [7:0] arr_12, arr_13, arr_14, arr_15,
    output reg [7:0] color_count,
    output reg done
);

    // State encoding
    localparam IDLE = 4'd0, INIT = 4'd1, FIND_MIN = 4'd2, FIND_MIN_LOOP = 4'd3,
               FOUND_MIN = 4'd4, SET_COLOR = 4'd5, MARK_LOOP = 4'd6, DONE = 4'd7;

    // Internal registers
    reg [3:0] state, next_state;
    reg [15:0] colored;  // Bitmask for colored elements
    reg [3:0] k, j;       // Loop counters
    reg [7:0] temp_min;
    reg [3:0] temp_index;
    reg [7:0] min_val;
    wire [7:0] arr_k, arr_j;
    wire [7:0] remainder;

    // Multiplexers for array access
    assign arr_k = (k == 0) ? arr_0 : (k == 1) ? arr_1 : (k == 2) ? arr_2 : (k == 3) ? arr_3 :
                   (k == 4) ? arr_4 : (k == 5) ? arr_5 : (k == 6) ? arr_6 : (k == 7) ? arr_7 :
                   (k == 8) ? arr_8 : (k == 9) ? arr_9 : (k == 10) ? arr_10 : (k == 11) ? arr_11 :
                   (k == 12) ? arr_12 : (k == 13) ? arr_13 : (k == 14) ? arr_14 : arr_15;

    assign arr_j = (j == 0) ? arr_0 : (j == 1) ? arr_1 : (j == 2) ? arr_2 : (j == 3) ? arr_3 :
                   (j == 4) ? arr_4 : (j == 5) ? arr_5 : (j == 6) ? arr_6 : (j == 7) ? arr_7 :
                   (j == 8) ? arr_8 : (j == 9) ? arr_9 : (j == 10) ? arr_10 : (j == 11) ? arr_11 :
                   (j == 12) ? arr_12 : (j == 13) ? arr_13 : (j == 14) ? arr_14 : arr_15;

    // Combinational modulo (division by zero is impossible as values >=1)
    assign remainder = (min_val != 0) ? (arr_j % min_val) : 0;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            IDLE:       next_state = start ? INIT : IDLE;
            INIT:       next_state = FIND_MIN;
            FIND_MIN:   next_state = FIND_MIN_LOOP;
            FIND_MIN_LOOP: 
                if (k >= n) next_state = FOUND_MIN;
                else if (colored[k]) next_state = FIND_MIN_LOOP; // Skip colored
                else next_state = FIND_MIN_LOOP; // Continue checking
            FOUND_MIN:  next_state = (temp_min == 8'd255) ? DONE : SET_COLOR;
            SET_COLOR:  next_state = MARK_LOOP;
            MARK_LOOP:  
                if (j >= n) next_state = FIND_MIN;
                else next_state = MARK_LOOP;
            DONE:       next_state = DONE;
            default:    next_state = IDLE;
        endcase
    end

    // Sequential logic for state actions
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all registers
            color_count <= 8'd0;
            done <= 1'b0;
            colored <= 16'd0;
            k <= 4'd0;
            j <= 4'd0;
            temp_min <= 8'd255;
            temp_index <= 4'd0;
            min_val <= 8'd0;
        end else begin
            case (state)
                INIT: begin
                    colored <= 16'd0;
                    color_count <= 8'd0;
                    k <= 4'd0;
                    j <= 4'd0;
                    temp_min <= 8'd255;
                    temp_index <= 4'd0;
                    done <= 1'b0;
                end

                FIND_MIN: begin
                    k <= 4'd0;
                    temp_min <= 8'd255;
                    temp_index <= 4'd0;
                end

                FIND_MIN_LOOP: begin
                    if (k < n) begin
                        if (!colored[k]) begin
                            if (arr_k < temp_min) begin
                                temp_min <= arr_k;
                                temp_index <= k;
                            end
                        end
                        k <= k + 1;
                    end
                end

                FOUND_MIN: begin
                    // No action needed
                end

                SET_COLOR: begin
                    color_count <= color_count + 1;
                    min_val <= temp_min;
                    colored[temp_index] <= 1'b1;  // Mark the min element
                    j <= 4'd0;
                end

                MARK_LOOP: begin
                    if (j < n) begin
                        // If uncolored and divisible by min_val, mark it
                        if (!colored[j] && (remainder == 0)) begin
                            colored[j] <= 1'b1;
                        end
                        j <= j + 1;
                    end
                end

                DONE: begin
                    done <= 1'b1;
                end
            endcase
        end
    end
endmodule

module find_positions (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,   // Actual size of a (≤16)
    input wire [3:0] m,   // Actual size of b (≤8)
    input wire [3:0] p,   // Step size (≤8)
    // Input array a (16 elements, 4-bit each)
    input wire [3:0] a0, a1, a2, a3, a4, a5, a6, a7,
    input wire [3:0] a8, a9, a10, a11, a12, a13, a14, a15,
    // Input array b (8 elements, 4-bit each)
    input wire [3:0] b0, b1, b2, b3, b4, b5, b6, b7,
    output reg done,
    output reg [3:0] count,    // Number of valid positions
    // Output positions (max 16, 5-bit each)
    output reg [4:0] pos0, pos1, pos2, pos3, pos4, pos5, pos6, pos7,
    output reg [4:0] pos8, pos9, pos10, pos11, pos12, pos13, pos14, pos15
);

// State definitions
localparam IDLE = 0;
localparam PREPARE_B = 1;
localparam CHECK_Q = 2;
localparam INIT_WINDOW = 3;
localparam CHECK_WINDOW = 4;
localparam SLIDE = 5;
localparam SORT = 6;
localparam FINISH = 7;

// Registers
reg [2:0] state;
reg [3:0] q;              // Current starting position
reg [3:0] j;              // Window offset counter
reg [3:0] elem_count;     // Elements in current sequence
reg [3:0] pos_count;      // Count of found positions
reg signed [4:0] temp_pos [0:15]; // Temporary position storage

// Frequency tables (values 0-15)
reg [2:0] freq_b [0:15];   // Frequency of b values
reg [2:0] freq_win [0:15]; // Frequency in current window

// Helper signals
reg [3:0] a_vals [0:15];   // Input a array
reg [3:0] b_vals [0:15];   // Input b array (padded to 16)
reg [3:0] next_q;
reg [4:0] next_pos;
reg freq_match;

// Map inputs to arrays
always @(*) begin
    a_vals[0] = a0;  a_vals[1] = a1;  a_vals[2] = a2;  a_vals[3] = a3;
    a_vals[4] = a4;  a_vals[5] = a5;  a_vals[6] = a6;  a_vals[7] = a7;
    a_vals[8] = a8;  a_vals[9] = a9;  a_vals[10] = a10; a_vals[11] = a11;
    a_vals[12] = a12; a_vals[13] = a13; a_vals[14] = a14; a_vals[15] = a15;

    b_vals[0] = b0;  b_vals[1] = b1;  b_vals[2] = b2;  b_vals[3] = b3;
    b_vals[4] = b4;  b_vals[5] = b5;  b_vals[6] = b6;  b_vals[7] = b7;
    // Pad remaining to 0
    for (integer i = 8; i < 16; i = i + 1) b_vals[i] = 0;
end

// Frequency comparison
always @(*) begin
    freq_match = 1;
    for (integer i = 0; i < 16; i = i + 1) begin
        if (freq_b[i] != freq_win[i]) freq_match = 0;
    end
end

// Next state logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        count <= 0;
        {pos0, pos1, pos2, pos3, pos4, pos5, pos6, pos7,
         pos8, pos9, pos10, pos11, pos12, pos13, pos14, pos15} <= 0;
        q <= 0;
        j <= 0;
        pos_count <= 0;
        // Reset frequency tables
        for (integer i = 0; i < 16; i = i + 1) begin
            freq_b[i] <= 0;
            freq_win[i] <= 0;
            temp_pos[i] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= PREPARE_B;
                    q <= 0;
                    j <= 0;
                    pos_count <= 0;
                    // Reset frequency tables
                    for (integer i = 0; i < 16; i = i + 1) begin
                        freq_b[i] <= 0;
                        freq_win[i] <= 0;
                    end
                end
            end

            PREPARE_B: begin
                // Build frequency table for b (first m elements)
                if (j < m) begin
                    if (b_vals[j] < 16)  // Safety check
                        freq_b[b_vals[j]] <= freq_b[b_vals[j]] + 1;
                    j <= j + 1;
                end else begin
                    j <= 0;
                    state <= CHECK_Q;
                end
            end

            CHECK_Q: begin
                if (q < p) begin
                    // Check if valid sequence exists
                    if (n > q) begin
                        elem_count <= (n - q - 1) / p + 1;  // Number of elements
                        state <= INIT_WINDOW;
                        j <= 0;
                        // Reset freq_win
                        for (integer i = 0; i < 16; i = i + 1) freq_win[i] <= 0;
                    end else begin
                        q <= q + 1;
                    end
                end else begin
                    state <= SORT;
                    j <= 0; // Use j as counter for sort
                end
            end

            INIT_WINDOW: begin
                if (j < m) begin
                    // Get element at position q + j*p
                    if (q + j*p < 16 && a_vals[q + j*p] < 16)
                        freq_win[a_vals[q + j*p]] <= freq_win[a_vals[q + j*p]] + 1;
                    j <= j + 1;
                end else begin
                    j <= 0;
                    state <= CHECK_WINDOW;
                end
            end

            CHECK_WINDOW: begin
                if (elem_count >= m && freq_match) begin
                    // Record position (1-indexed)
                    if (pos_count < 16) begin
                        temp_pos[pos_count] <= q + 1;
                        pos_count <= pos_count + 1;
                    end
                end

                // Check if we can slide
                if (elem_count > m) begin
                    state <= SLIDE;
                end else begin
                    q <= q + 1;
                    state <= CHECK_Q;
                end
            end

            SLIDE: begin
                // Remove leftmost element (at j in sequence)
                if (q + j*p < 16 && a_vals[q + j*p] < 16)
                    freq_win[a_vals[q + j*p]] <= freq_win[a_vals[q + j*p]] - 1;

                // Add new element (at j+m in sequence)
                if (q + (j+m)*p < 16 && a_vals[q + (j+m)*p] < 16)
                    freq_win[a_vals[q + (j+m)*p]] <= freq_win[a_vals[q + (j+m)*p]] + 1;

                j <= j + 1;
                elem_count <= elem_count - 1; // One less window available
                state <= CHECK_WINDOW;
            end

            SORT: begin
                // Bubble sort on temp_pos (only first pos_count elements)
                if (j < pos_count - 1) begin
                    if (temp_pos[j] > temp_pos[j+1]) begin
                        // Swap
                        temp_pos[j] <= temp_pos[j+1];
                        temp_pos[j+1] <= temp_pos[j];
                    end
                    j <= j + 1;
                end else begin
                    j <= 0;
                    state <= FINISH;
                end
            end

            FINISH: begin
                // Assign outputs
                count <= pos_count;
                {pos0, pos1, pos2, pos3, pos4, pos5, pos6, pos7,
                 pos8, pos9, pos10, pos11, pos12, pos13, pos14, pos15} <= 
                    {temp_pos[0], temp_pos[1], temp_pos[2], temp_pos[3],
                     temp_pos[4], temp_pos[5], temp_pos[6], temp_pos[7],
                     temp_pos[8], temp_pos[9], temp_pos[10], temp_pos[11],
                     temp_pos[12], temp_pos[13], temp_pos[14], temp_pos[15]};
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module government_graph (
  input clk, rst_n, start,
  input [3:0] n,
  input [1:0] k,
  input [2:0] gov0, gov1, gov2,
  input [4:0] m,
  input [95:0] edges,
  output reg [15:0] result,
  output reg done
);
  // State definitions
  parameter IDLE=0, INIT=1, BUILD_ADJ=2, PROCESS_GOV_START=3, BFS_LOOP=4, 
            BFS_CHECK_NEIGH=5, CALCULATE_NON_GOV=6, CALCULATE_GOV_EDGES=7, 
            CALCULATE_RESULT=8, DONE=9;

  reg [3:0] state;
  reg [7:0] adj [0:7];
  reg [7:0] visited;
  reg [3:0] gov_component_sizes [0:2];
  reg [3:0] total_gov_nodes;
  reg [1:0] index;
  reg [2:0] queue [0:7];
  reg [2:0] head, tail;
  reg [3:0] size;
  reg [2:0] current_u;
  reg [2:0] v_counter;
  reg [4:0] i_edge;
  reg [3:0] non_gov_count;
  reg [3:0] max_gov;
  reg [15:0] total_edges;
  reg [1:0] i_calc;
  reg [7:0] temp1, temp2;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      done <= 0;
      result <= 0;
      visited <= 0;
      adj[0] <= 0; adj[1] <= 0; adj[2] <= 0; adj[3] <= 0;
      adj[4] <= 0; adj[5] <= 0; adj[6] <= 0; adj[7] <= 0;
      gov_component_sizes[0] <= 0; gov_component_sizes[1] <= 0; gov_component_sizes[2] <= 0;
      total_gov_nodes <= 0;
      index <= 0;
      head <= 0; tail <= 0; size <= 0; v_counter <= 0;
      i_edge <= 0;
      non_gov_count <= 0; max_gov <= 0; total_edges <= 0; i_calc <= 0;
    end
    else begin
      case (state)
        IDLE: begin
          done <= 0;
          if (start) state <= INIT;
        end
        INIT: begin
          visited <= 0;
          adj[0] <= 0; adj[1] <= 0; adj[2] <= 0; adj[3] <= 0;
          adj[4] <= 0; adj[5] <= 0; adj[6] <= 0; adj[7] <= 0;
          gov_component_sizes[0] <= 0; gov_component_sizes[1] <= 0; gov_component_sizes[2] <= 0;
          total_gov_nodes <= 0;
          index <= 0;
          i_edge <= 0;
          state <= BUILD_ADJ;
        end
        BUILD_ADJ: begin
          if (i_edge < m) begin
            if (edges[6*i_edge +: 3] < n && edges[6*i_edge + 3 +: 3] < n && edges[6*i_edge +: 3] != edges[6*i_edge + 3 +: 3]) begin
              adj[edges[6*i_edge +: 3]][edges[6*i_edge + 3 +: 3]] <= 1;
              adj[edges[6*i_edge + 3 +: 3]][edges[6*i_edge +: 3]] <= 1;
            end
            i_edge <= i_edge + 1;
          end
          else state <= PROCESS_GOV_START;
        end
        PROCESS_GOV_START: begin
          if (index < k) begin
            case (index)
              0: current_u <= gov0;
              1: current_u <= gov1;
              2: current_u <= gov2;
            endcase
            if (visited[current_u] == 0) begin
              queue[0] <= current_u;
              head <= 0;
              tail <= 1;
              visited[current_u] <= 1;
              size <= 0;
              state <= BFS_LOOP;
            end
            else begin
              gov_component_sizes[index] <= 0;
              index <= index + 1;
              state <= PROCESS_GOV_START;
            end
          end
          else state <= CALCULATE_NON_GOV;
        end
        BFS_LOOP: begin
          if (head < tail) begin
            current_u <= queue[head];
            head <= head + 1;
            size <= size + 1;
            v_counter <= 0;
            state <= BFS_CHECK_NEIGH;
          end
          else begin
            gov_component_sizes[index] <= size;
            total_gov_nodes <= total_gov_nodes + size;
            index <= index + 1;
            state <= PROCESS_GOV_START;
          end
        end
        BFS_CHECK_NEIGH: begin
          if (v_counter < n) begin
            if (adj[current_u][v_counter] && !visited[v_counter]) begin
              visited[v_counter] <= 1;
              queue[tail] <= v_counter;
              tail <= tail + 1;
            end
            v_counter <= v_counter + 1;
          end
          else state <= BFS_LOOP;
        end
        CALCULATE_NON_GOV: begin
          non_gov_count <= n - total_gov_nodes;
          max_gov <= gov_component_sizes[0];
          if (k > 1 && gov_component_sizes[1] > max_gov) max_gov <= gov_component_sizes[1];
          if (k > 2 && gov_component_sizes[2] > max_gov) max_gov <= gov_component_sizes[2];
          total_edges <= 0;
          i_calc <= 0;
          state <= CALCULATE_GOV_EDGES;
        end
        CALCULATE_GOV_EDGES: begin
          if (i_calc < k) begin
            if (gov_component_sizes[i_calc] != max_gov) begin
              temp1 = gov_component_sizes[i_calc] * (gov_component_sizes[i_calc] - 1);
              total_edges <= total_edges + (temp1 >> 1);
            end
            i_calc <= i_calc + 1;
          end
          else begin
            temp2 = (non_gov_count + max_gov) * (non_gov_count + max_gov - 1);
            total_edges <= total_edges + (temp2 >> 1);
            state <= CALCULATE_RESULT;
          end
        end
        CALCULATE_RESULT: begin
          result <= total_edges - m;
          state <= DONE;
        end
        DONE: begin
          done <= 1;
          state <= IDLE;
        end
        default: state <= IDLE;
      endcase
    end
  end
endmodule

module bookland_ordering (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,               // number of words (1..8)
    input wire [3:0] m,               // alphabet size (1..8)
    // word data: for each word i (0..MAX_WORDS-1)
    input wire [3:0]  word_len  [0:7],   // length of word i
    input wire [31:0] word_data [0:7],   // packed letters: bits 3:0 = first, 7:4 = second, ... (each 4 bits)
    output reg yes,                    // 1 if possible
    output reg [3:0] k,                // number of letters to capitalize
    output reg [7:0] letters_out,      // bitmask of letters to capitalize (bit 0 = letter 1)
    output reg done                    // asserted when computation finishes
);

// Parameters for scaling
parameter MAX_WORDS = 8;
parameter MAX_LEN   = 8;
parameter MAX_M     = 8;

// Internal state
localparam S_IDLE       = 3'b000;
localparam S_CHECK_MASK = 3'b001;
localparam S_CHECK_PAIR = 3'b010;
localparam S_NEXT_MASK  = 3'b011;
localparam S_FOUND      = 3'b100;
localparam S_NO_RESULT  = 3'b101;
localparam S_OUTPUT     = 3'b110;

reg [2:0] state;
reg [2:0] pair_idx;               // current adjacent pair index (0..n-2)
reg [MAX_M-1:0] current_mask;     // current subset of letters to capitalize

// Combinational signals for word selection
wire [3:0]  w1_len, w2_len;
wire [31:0] w1_data, w2_data;
wire valid;                       // comparator result

// Select the two words for the current pair
assign w1_len  = (pair_idx < n) ? word_len[pair_idx]   : 4'd0;
assign w1_data = (pair_idx < n) ? word_data[pair_idx]  : 32'd0;
assign w2_len  = (pair_idx + 1 < n) ? word_len[pair_idx+1]   : 4'd0;
assign w2_data = (pair_idx + 1 < n) ? word_data[pair_idx+1]  : 32'd0;

// Comparator: check whether word1 <= word2 under current_mask
always @(*) begin
    reg [3:0] a, b;
    reg cap_a, cap_b;
    reg diff_found;
    reg valid_int;
    integer j;

    diff_found = 0;
    valid_int  = 1;   // default: valid if no diff and len1 <= len2

    for (j = 0; j < MAX_LEN; j = j + 1) begin
        if (!diff_found && j < w1_len && j < w2_len) begin
            a = w1_data[j*4 +: 4];   // extract letter j from packed data
            b = w2_data[j*4 +: 4];
            if (a != b) begin
                diff_found = 1;
                cap_a = current_mask[a-1];   // a >= 1 always
                cap_b = current_mask[b-1];
                if (cap_a == cap_b) begin
                    valid_int = (a < b);
                end else if (cap_a < cap_b) begin  // a large, b small => a < b
                    valid_int = 1;
                end else begin                     // a small, b large => a > b
                    valid_int = 0;
                end
            end
        end
    end

    if (!diff_found) begin   // one word is prefix of the other
        valid_int = (w1_len <= w2_len);
    end

    valid = valid_int;
end

// Function to count number of 1's in a mask
function automatic [3:0] count_bits(input [MAX_M-1:0] mask);
    reg [3:0] cnt;
    integer i;
    cnt = 0;
    for (i = 0; i < MAX_M; i = i + 1) begin
        if (mask[i]) cnt = cnt + 1;
    end
    count_bits = cnt;
endfunction

// Main FSM
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S_IDLE;
        yes <= 0;
        k <= 0;
        letters_out <= 0;
        done <= 0;
        current_mask <= 0;
        pair_idx <= 0;
    end else begin
        case (state)
            S_IDLE: begin
                done <= 0;
                if (start) begin
                    if (n <= 1) begin   // always ordered
                        yes <= 1;
                        letters_out <= 0;
                        k <= 0;
                        state <= S_OUTPUT;
                    end else begin
                        current_mask <= 0;
                        state <= S_CHECK_MASK;
                    end
                end
            end

            S_CHECK_MASK: begin
                pair_idx <= 0;
                state <= S_CHECK_PAIR;
            end

            S_CHECK_PAIR: begin
                if (!valid) begin
                    state <= S_NEXT_MASK;
                end else begin
                    if (pair_idx == n-2) begin   // all pairs checked
                        state <= S_FOUND;
                    end else begin
                        pair_idx <= pair_idx + 1;   // move to next pair
                        // state remains S_CHECK_PAIR
                    end
                end
            end

            S_NEXT_MASK: begin
                if (current_mask == (1 << m) - 1) begin
                    state <= S_NO_RESULT;   // tried all subsets, none worked
                end else begin
                    current_mask <= current_mask + 1;
                    state <= S_CHECK_MASK;
                end
            end

            S_FOUND: begin
                yes <= 1;
                letters_out <= current_mask;
                k <= count_bits(current_mask);
                state <= S_OUTPUT;
            end

            S_NO_RESULT: begin
                yes <= 0;
                letters_out <= 0;
                k <= 0;
                state <= S_OUTPUT;
            end

            S_OUTPUT: begin
                done <= 1;
                // stay here until reset
            end
        endcase
    end
end

endmodule

