module subset_sum_calculator #(
    parameter MAX_N = 8,
    parameter DATA_WIDTH = 32,
    parameter MOD = 1000000007
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] arr [0:MAX_N-1],
    input wire [3:0] len,
    output reg [DATA_WIDTH-1:0] result,
    output reg done
);

// State definitions
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam DONE = 2'b10;

// Registers
reg [1:0] state, next_state;
reg [3:0] i, next_i;

// Power lookup table: pow_minus_one[k] = (2^k - 1) % MOD for k = 0 to MAX_N
reg [DATA_WIDTH-1:0] pow_minus_one [0:MAX_N];
initial begin
    pow_minus_one[0] = 32'd0;   // 2^0 - 1
    pow_minus_one[1] = 32'd1;   // 2^1 - 1
    pow_minus_one[2] = 32'd3;   // 2^2 - 1
    pow_minus_one[3] = 32'd7;   // 2^3 - 1
    pow_minus_one[4] = 32'd15;  // 2^4 - 1
    pow_minus_one[5] = 32'd31;  // 2^5 - 1
    pow_minus_one[6] = 32'd63;  // 2^6 - 1
    pow_minus_one[7] = 32'd127; // 2^7 - 1
    pow_minus_one[8] = 32'd255; // 2^8 - 1
end

// Combinational logic for term calculation (current gap contribution)
wire [DATA_WIDTH-1:0] gap = (i < len - 1) ? (arr[i+1] - arr[i]) : 0;
wire [DATA_WIDTH-1:0] left = (i < len - 1) ? pow_minus_one[i+1] : 0;
wire [DATA_WIDTH-1:0] right = (i < len - 1) ? pow_minus_one[len-i-1] : 0;
wire [63:0] term_mult1 = (gap % MOD) * (left % MOD);
wire [63:0] term_mult2 = (term_mult1 % MOD) * (right % MOD);
wire [DATA_WIDTH-1:0] term = term_mult2 % MOD;

// State register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        i <= 0;
        result <= 0;
    end else begin
        state <= next_state;
        i <= next_i;
        result <= next_result;
    end
end

// Next state and output logic
always @(*) begin
    next_state = state;
    next_i = i;
    next_result = result;

    case (state)
        IDLE: begin
            if (start) begin
                next_state = COMPUTE;
                next_i = 0;
                next_result = 0;
            end
        end

        COMPUTE: begin
            if (i < len - 1) begin
                next_result = (result + term) % MOD;
                next_i = i + 1;
            end else begin
                next_state = DONE;
                next_i = 0;
            end
        end

        DONE: begin
            if (!start) begin
                next_state = IDLE;
            end
        end

        default: next_state = IDLE;
    endcase
end

// Done output
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 0;
    end else begin
        done <= (state == DONE);
    end
end

endmodule

module chocolate_division (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,
    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    output reg [15:0] result,
    output reg done
);

// State definitions
localparam IDLE = 3'b000;
localparam SUM = 3'b001;
localparam CHECK_S = 3'b010;
localparam FACTORIZE = 3'b011;
localparam COMPUTE_COST = 3'b100;
localparam DONE = 3'b101;

// Registers
reg [2:0] state;
reg [15:0] S;
reg [7:0] a_reg [0:7];
reg [4:0] prime_index;
reg [15:0] min_cost;
reg [15:0] current_cost;
reg [7:0] current_p;
reg [7:0] current_residue;
reg [3:0] i;
reg [15:0] temp_sum;
reg [7:0] remainder;
reg [15:0] divisor;

// Combinational logic for prime checking (simplified)
wire [7:0] next_prime;
assign next_prime = (prime_index == 0) ? 2 :
                    (prime_index == 1) ? 3 :
                    (prime_index == 2) ? 5 :
                    (prime_index == 3) ? 7 :
                    (prime_index == 4) ? 11 :
                    (prime_index == 5) ? 13 :
                    (prime_index == 6) ? 17 :
                    19;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        S <= 0;
        min_cost <= 16'hFFFF;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    // Load array
                    a_reg[0] <= arr_0;
                    a_reg[1] <= arr_1;
                    a_reg[2] <= arr_2;
                    a_reg[3] <= arr_3;
                    a_reg[4] <= arr_4;
                    a_reg[5] <= arr_5;
                    a_reg[6] <= arr_6;
                    a_reg[7] <= arr_7;
                    temp_sum <= 0;
                    i <= 0;
                    state <= SUM;
                end
            end

            SUM: begin
                if (i < n) begin
                    temp_sum <= temp_sum + a_reg[i];
                    i <= i + 1;
                end else begin
                    S <= temp_sum;
                    state <= CHECK_S;
                end
            end

            CHECK_S: begin
                if (S == 1) begin
                    result <= 16'hFFFF; // -1
                    done <= 1;
                    state <= DONE;
                end else begin
                    prime_index <= 0;
                    min_cost <= 16'hFFFF;
                    state <= FACTORIZE;
                end
            end

            FACTORIZE: begin
                if (prime_index < 8) begin
                    current_p <= next_prime;
                    if (S % next_prime == 0) begin
                        current_cost <= 0;
                        current_residue <= 0;
                        i <= 0;
                        state <= COMPUTE_COST;
                    end else begin
                        prime_index <= prime_index + 1;
                    end
                end else begin
                    // Check if remaining S is prime > 19
                    if (S > 19 && S % 2 != 0 && S % 3 != 0 && S % 5 != 0 && 
                        S % 7 != 0 && S % 11 != 0 && S % 13 != 0 && S % 17 != 0 && S % 19 != 0) begin
                        current_p <= S[7:0];
                        current_cost <= 0;
                        current_residue <= 0;
                        i <= 0;
                        state <= COMPUTE_COST;
                    end else begin
                        result <= min_cost;
                        done <= 1;
                        state <= DONE;
                    end
                end
            end

            COMPUTE_COST: begin
                if (i < n) begin
                    // Compute mod = a_reg[i] % current_p
                    remainder <= a_reg[i] % current_p;
                    // Wait one cycle for mod operation
                    i <= i + 1;
                end else begin
                    // After processing all elements
                    if (current_cost < min_cost)
                        min_cost <= current_cost;
                    prime_index <= prime_index + 1;
                    state <= FACTORIZE;
                end
            end

            DONE: begin
                done <= 0; // Pulse done for one cycle
                state <= IDLE;
            end
        endcase

        // Cost computation logic (combinational within COMPUTE_COST state)
        if (state == COMPUTE_COST && i < n && i > 0) begin
            // Update residue: (current_residue + remainder) % current_p
            if (current_residue + remainder >= current_p)
                current_residue <= current_residue + remainder - current_p;
            else
                current_residue <= current_residue + remainder;

            // Add cost
            if (current_residue <= (current_p >> 1))
                current_cost <= current_cost + current_residue;
            else
                current_cost <= current_cost + current_p - current_residue;
        end
    end
end

endmodule

module lights_max (
    input clk,
    input rst_n,
    input start,
    input [7:0] initial_state,  // 8-bit initial state for lights
    input [2:0] a [0:7],        // periods for 8 lights (1-5)
    input [2:0] b [0:7],        // offsets for 8 lights (1-5)
    output reg [7:0] max_count  // maximum number of lights on simultaneously
);

// State definitions
localparam IDLE = 3'b000;
localparam SIMULATE = 3'b001;
localparam UPDATE_MAX = 3'b010;
localparam NEXT_TIME = 3'b011;
localparam DONE = 3'b100;

// Registers
reg [2:0] state;
reg [6:0] time_counter;     // 0-120 seconds
reg [2:0] light_counter;    // 0-7 lights
reg [7:0] current_states;   // current state of all lights
reg [7:0] max_count_reg;    // internal max counter
reg [7:0] current_count;    // count of current on lights

// Combinational logic for toggle detection
wire should_toggle;
wire [2:0] period;
wire [2:0] offset;
wire light_on;

assign period = a[light_counter];
assign offset = b[light_counter];
assign light_on = current_states[light_counter];

// Check if this light should toggle at current time
assign should_toggle = (time_counter >= offset) && 
                      ((time_counter - offset) % period == 0);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        time_counter <= 0;
        light_counter <= 0;
        current_states <= 8'b0;
        max_count_reg <= 8'b0;
        current_count <= 8'b0;
        max_count <= 8'b0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    current_states <= initial_state;
                    time_counter <= 0;
                    light_counter <= 0;
                    max_count_reg <= 8'b0;
                    state <= SIMULATE;
                end
            end

            SIMULATE: begin
                // Check if this light should toggle
                if (should_toggle) begin
                    current_states[light_counter] <= ~light_on;
                    // Update current count if state changes
                    if (light_on) begin
                        current_count <= current_count - 1;
                    end else begin
                        current_count <= current_count + 1;
                    end
                end

                if (light_counter == 7) begin
                    light_counter <= 0;
                    state <= UPDATE_MAX;
                end else begin
                    light_counter <= light_counter + 1;
                end
            end

            UPDATE_MAX: begin
                if (current_count > max_count_reg) begin
                    max_count_reg <= current_count;
                end
                state <= NEXT_TIME;
            end

            NEXT_TIME: begin
                if (time_counter == 120) begin
                    max_count <= max_count_reg;
                    state <= DONE;
                end else begin
                    time_counter <= time_counter + 1;
                    light_counter <= 0;
                    // Reset current_count for new time step
                    current_count <= 8'b0;
                    // Recalculate current_count from current_states
                    current_count <= current_states[0] + current_states[1] + 
                                   current_states[2] + current_states[3] + 
                                   current_states[4] + current_states[5] + 
                                   current_states[6] + current_states[7];
                    state <= SIMULATE;
                end
            end

            DONE: begin
                // Stay done until reset
            end
        endcase
    end
end

endmodule

module minimal_unique_substring #(
    parameter MAX_N = 32
)(
    input wire [4:0] n,      // String length (1 to MAX_N)
    input wire [4:0] k,      // Desired minimal unique substring length
    output wire [MAX_N-1:0] result // Generated string, bit 0 = first character
);

    // Compute pattern parameters
    wire [4:0] a = (n - k) >> 1;      // Number of zeros before each '1'
    wire [4:0] period = a + 1;        // Pattern period length

    // Combinational logic to generate output bits
    reg [MAX_N-1:0] result_reg;

    integer i;
    always @(*) begin
        for (i = 0; i < MAX_N; i = i + 1) begin
            if (i < n) begin
                if (a == 5'd0) begin
                    // Case: n == k, all bits are 1
                    result_reg[i] = 1'b1;
                end else begin
                    // Pattern: positions that are multiples of period minus 1 get '1'
                    result_reg[i] = ((i % period) == a) ? 1'b1 : 1'b0;
                end
            end else begin
                // Unused positions (i >= n) are set to 0
                result_reg[i] = 1'b0;
            end
        end
    end

    assign result = result_reg;

endmodule

module dragon (
    input clk,
    input rst_n,
    input start,
    input [3:0] n,          // Array length (1-8)
    input [7:0] arr_0,      // Individual array ports (8 elements max)
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    output reg [7:0] result,
    output reg done
);

// State definitions
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam DONE_STATE = 2'b10;

reg [1:0] state;
reg [3:0] i;              // Current element index
reg [7:0] dp0, dp1, dp2, dp3; // DP states
reg [7:0] temp_result;

// Helper to read array element based on index
function [7:0] read_array;
    input [3:0] idx;
    begin
        case(idx)
            4'd0: read_array = arr_0;
            4'd1: read_array = arr_1;
            4'd2: read_array = arr_2;
            4'd3: read_array = arr_3;
            4'd4: read_array = arr_4;
            4'd5: read_array = arr_5;
            4'd6: read_array = arr_6;
            4'd7: read_array = arr_7;
            default: read_array = 8'd0;
        endcase
    end
endfunction

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        dp0 <= 0;
        dp1 <= 0;
        dp2 <= 0;
        dp3 <= 0;
        temp_result <= 0;
    end else begin
        case(state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= COMPUTE;
                    i <= 0;
                    dp0 <= 0;
                    dp1 <= 0;
                    dp2 <= 0;
                    dp3 <= 0;
                end
            end

            COMPUTE: begin
                if (i < n) begin
                    // Process current element
                    if (read_array(i) == 8'd1) begin
                        dp0 <= dp0 + 1;
                        dp2 <= (dp1 > dp2) ? (dp1 + 1) : (dp2 + 1);
                    end else begin
                        dp1 <= (dp0 > dp1) ? (dp0 + 1) : (dp1 + 1);
                        dp3 <= (dp2 > dp3) ? (dp2 + 1) : (dp3 + 1);
                    end
                    i <= i + 1;
                end else begin
                    // Compute final result
                    temp_result <= dp0;
                    if (dp1 > temp_result) temp_result <= dp1;
                    if (dp2 > temp_result) temp_result <= dp2;
                    if (dp3 > temp_result) temp_result <= dp3;
                    state <= DONE_STATE;
                end
            end

            DONE_STATE: begin
                result <= temp_result;
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module tree_control #(
    parameter MAX_N = 8
) (
    input [2:0] n,
    input [15:0] a [0:MAX_N-1],
    input [2:0] parent [0:MAX_N-2],
    input [15:0] weight [0:MAX_N-2],
    output reg [15:0] ans [0:MAX_N-1]
);

reg [15:0] d [0:MAX_N-1];
integer i, j, u, v;
reg [15:0] diff;
reg is_anc;

always @(*) begin
    // Compute distances from root (vertex 0)
    d[0] = 0;
    for (i = 1; i < MAX_N; i = i + 1) begin
        if (i < n) begin
            d[i] = d[parent[i-1]] + weight[i-1];
        end
    end

    // Compute answers for each vertex v
    for (v = 0; v < MAX_N; v = v + 1) begin
        ans[v] = 0;
        if (v >= n) continue;
        for (u = 0; u < n; u = u + 1) begin
            if (u == v) continue;
            is_anc = 0;
            if (v == 0) begin
                is_anc = 1; // Root is ancestor of all
            end else begin
                j = u;
                while (j != 0) begin
                    if (j == v) begin
                        is_anc = 1;
                        break;
                    end
                    j = parent[j-1];
                end
            end
            if (is_anc) begin
                diff = d[u] - d[v];
                if (diff <= a[u]) begin
                    ans[v] = ans[v] + 1;
                end
            end
        end
    end
end

endmodule

module rating_equalizer (
    input clk,
    input rst_n,
    input start,
    input [3:0] ratings_0, ratings_1, ratings_2, ratings_3,
    input [3:0] ratings_4, ratings_5, ratings_6, ratings_7,
    input [3:0] n,  // Number of friends (2-8)
    output reg [3:0] final_rating,
    output reg [13:0] match_count,  // Up to 10,000 matches
    output reg [7:0] match_0, match_1, match_2, match_3,
    output reg [7:0] match_4, match_5, match_6, match_7,
    output reg match_valid,
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam COMPUTE_MAX = 3'b001;
    localparam FORM_PARTY = 3'b010;
    localparam UPDATE_RATINGS = 3'b011;
    localparam CHECK_EQUAL = 3'b100;
    localparam OUTPUT_MATCH = 3'b101;
    localparam FINISHED = 3'b110;

    // Internal registers
    reg [2:0] state;
    reg [3:0] current_ratings [0:7];
    reg [13:0] match_counter;
    reg [2:0] match_index;
    reg [3:0] max_rating;
    reg [2:0] max_count;
    reg [2:0] selected_friends [0:4];
    reg [2:0] selected_count;
    reg [3:0] step_counter;

    // Helper: Find maximum rating and count
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            max_rating <= 4'b0;
            max_count <= 3'b0;
        end else if (state == COMPUTE_MAX) begin
            max_rating <= 4'b0;
            max_count <= 3'b0;
            for (integer i = 0; i < 8; i = i + 1) begin
                if (i < n) begin
                    if (current_ratings[i] > max_rating) begin
                        max_rating <= current_ratings[i];
                        max_count <= 3'b1;
                    end else if (current_ratings[i] == max_rating) begin
                        max_count <= max_count + 1;
                    end
                end
            end
        end
    end

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            final_rating <= 4'b0;
            match_count <= 14'b0;
            match_valid <= 1'b0;
            done <= 1'b0;
            match_counter <= 14'b0;
            step_counter <= 4'b0;
            for (integer i = 0; i < 8; i = i + 1) begin
                current_ratings[i] <= 4'b0;
                if (i < 5) selected_friends[i] <= 3'b0;
            end
            match_0 <= 8'b0; match_1 <= 8'b0; match_2 <= 8'b0; match_3 <= 8'b0;
            match_4 <= 8'b0; match_5 <= 8'b0; match_6 <= 8'b0; match_7 <= 8'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        // Initialize ratings
                        current_ratings[0] <= ratings_0;
                        current_ratings[1] <= ratings_1;
                        current_ratings[2] <= ratings_2;
                        current_ratings[3] <= ratings_3;
                        current_ratings[4] <= ratings_4;
                        current_ratings[5] <= ratings_5;
                        current_ratings[6] <= ratings_6;
                        current_ratings[7] <= ratings_7;
                        match_counter <= 14'b0;
                        step_counter <= 4'b0;
                        state <= COMPUTE_MAX;
                        done <= 1'b0;
                        match_valid <= 1'b0;
                    end
                end

                COMPUTE_MAX: begin
                    // Maximum computed in separate always block
                    state <= FORM_PARTY;
                end

                FORM_PARTY: begin
                    // Form party based on max count
                    selected_count <= 3'b0;
                    if (max_count >= 2 && max_count <= 5) begin
                        // Take all friends with max rating
                        for (integer i = 0; i < 8; i = i + 1) begin
                            if (i < n && current_ratings[i] == max_rating && selected_count < 5) begin
                                selected_friends[selected_count] <= i;
                                selected_count <= selected_count + 1;
                            end
                        end
                    end else begin
                        // Take two highest rated friends
                        reg [2:0] first_max, second_max;
                        first_max = 3'b0; second_max = 3'b0;
                        // Find first maximum
                        for (integer i = 1; i < 8; i = i + 1) begin
                            if (i < n && current_ratings[i] > current_ratings[first_max]) begin
                                first_max = i;
                            end
                        end
                        // Find second maximum (different from first)
                        for (integer i = 0; i < 8; i = i + 1) begin
                            if (i < n && i != first_max) begin
                                if (second_max == first_max || current_ratings[i] > current_ratings[second_max]) begin
                                    second_max = i;
                                end
                            end
                        end
                        selected_friends[0] <= first_max;
                        selected_friends[1] <= second_max;
                        selected_count <= 3'b10;
                    end
                    state <= UPDATE_RATINGS;
                end

                UPDATE_RATINGS: begin
                    // Update ratings for selected friends
                    for (integer i = 0; i < 5; i = i + 1) begin
                        if (i < selected_count) begin
                            reg [2:0] friend_idx;
                            friend_idx = selected_friends[i];
                            if (current_ratings[friend_idx] > 0) begin
                                current_ratings[friend_idx] <= current_ratings[friend_idx] - 1;
                            end
                        end
                    end
                    state <= OUTPUT_MATCH;
                end

                OUTPUT_MATCH: begin
                    // Output the current match
                    match_valid <= 1'b1;
                    match_0 <= (selected_count > 0 && selected_friends[0] == 0) ? 8'b1 : 8'b0;
                    match_1 <= (selected_count > 0 && selected_friends[0] == 1) ? 8'b1 : 8'b0;
                    match_2 <= (selected_count > 0 && selected_friends[0] == 2) ? 8'b1 : 8'b0;
                    match_3 <= (selected_count > 0 && selected_friends[0] == 3) ? 8'b1 : 8'b0;
                    match_4 <= (selected_count > 1 && selected_friends[1] == 4) ? 8'b1 : 8'b0;
                    match_5 <= (selected_count > 1 && selected_friends[1] == 5) ? 8'b1 : 8'b0;
                    match_6 <= (selected_count > 1 && selected_friends[1] == 6) ? 8'b1 : 8'b0;
                    match_7 <= (selected_count > 1 && selected_friends[1] == 7) ? 8'b1 : 8'b0;
                    // Handle more than 2 friends (simplified)
                    if (selected_count > 2) begin
                        match_0 <= match_0 | ((selected_count > 2 && selected_friends[2] == 0) ? 8'b1 : 8'b0);
                        match_1 <= match_1 | ((selected_count > 2 && selected_friends[2] == 1) ? 8'b1 : 8'b0);
                        match_2 <= match_2 | ((selected_count > 2 && selected_friends[2] == 2) ? 8'b1 : 8'b0);
                        match_3 <= match_3 | ((selected_count > 2 && selected_friends[2] == 3) ? 8'b1 : 8'b0);
                    end
                    match_counter <= match_counter + 1;
                    state <= CHECK_EQUAL;
                end

                CHECK_EQUAL: begin
                    match_valid <= 1'b0;
                    // Check if all ratings equal
                    reg all_equal;
                    all_equal = 1'b1;
                    for (integer i = 1; i < 8; i = i + 1) begin
                        if (i < n && current_ratings[i] != current_ratings[0]) begin
                            all_equal = 1'b0;
                        end
                    end
                    if (all_equal || step_counter >= 15) begin
                        final_rating <= current_ratings[0];
                        match_count <= match_counter;
                        state <= FINISHED;
                    end else begin
                        step_counter <= step_counter + 1;
                        state <= COMPUTE_MAX;
                    end
                end

                FINISHED: begin
                    done <= 1'b1;
                    if (!start) begin
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module rearrange_to_divisible_by_7 (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] input_digits [0:15],
    input wire [3:0] input_length,
    output reg [3:0] output_digits [0:15],
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam COUNT = 3'b001;
    localparam DECREMENT = 3'b010;
    localparam CALCULATE_MOD = 3'b011;
    localparam LOOKUP = 3'b100;
    localparam OUTPUT = 3'b101;

    reg [2:0] state, next_state;
    reg [4:0] count [0:9]; // counts for digits 0-9 (max 16)
    reg [2:0] mod_result;
    reg [3:0] digit_counter;
    reg [3:0] output_index;
    reg [15:0] current_perm;

    // Permutation table: for each possible modulo result (0-6), store 4-digit permutation
    reg [15:0] perm_table [0:6];
    initial begin
        perm_table[0] = 16'h1869; // 1869
        perm_table[1] = 16'h1896; // 1896
        perm_table[2] = 16'h1986; // 1986
        perm_table[3] = 16'h1698; // 1698
        perm_table[4] = 16'h6198; // 6198
        perm_table[5] = 16'h1689; // 1689
        perm_table[6] = 16'h1968; // 1968
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            digit_counter <= 0;
            output_index <= 0;
            mod_result <= 0;
            current_perm <= 0;
            // Reset counts
            for (integer i = 0; i < 10; i = i + 1) begin
                count[i] <= 0;
            end
            // Reset output
            for (integer i = 0; i < 16; i = i + 1) begin
                output_digits[i] <= 0;
            end
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Reset counters
                        for (integer i = 0; i < 10; i = i + 1) begin
                            count[i] <= 0;
                        end
                        digit_counter <= 0;
                        mod_result <= 0;
                        current_perm <= 0;
                    end
                end

                COUNT: begin
                    if (digit_counter < input_length) begin
                        count[input_digits[digit_counter]] <= count[input_digits[digit_counter]] + 1;
                        digit_counter <= digit_counter + 1;
                    end
                end

                DECREMENT: begin
                    count[1] <= count[1] - 1;
                    count[6] <= count[6] - 1;
                    count[8] <= count[8] - 1;
                    count[9] <= count[9] - 1;
                    digit_counter <= 0;
                end

                CALCULATE_MOD: begin
                    // Calculate modulo of remaining digits in ascending order
                    if (digit_counter < 10) begin
                        if (count[digit_counter] > 0) begin
                            mod_result <= (mod_result * 10 + digit_counter) % 7;
                            count[digit_counter] <= count[digit_counter] - 1;
                        end else begin
                            digit_counter <= digit_counter + 1;
                        end
                    end
                end

                LOOKUP: begin
                    current_perm <= perm_table[mod_result];
                    output_index <= 0;
                    digit_counter <= 1; // Start from digit 1 for output
                end

                OUTPUT: begin
                    if (output_index < input_length) begin
                        if (digit_counter <= 9 && digit_counter != 0) begin
                            if (count[digit_counter] > 0) begin
                                output_digits[output_index] <= digit_counter;
                                output_index <= output_index + 1;
                                count[digit_counter] <= count[digit_counter] - 1;
                            end else begin
                                digit_counter <= digit_counter + 1;
                            end
                        end else if (digit_counter == 10) begin
                            // Output permutation
                            if (output_index < input_length - 4'd4) begin
                                // Wait until we have space for 4 digits
                                output_digits[output_index] <= current_perm[15:12];
                                output_digits[output_index + 1] <= current_perm[11:8];
                                output_digits[output_index + 2] <= current_perm[7:4];
                                output_digits[output_index + 3] <= current_perm[3:0];
                                output_index <= output_index + 4;
                            end
                            digit_counter <= 0; // Now for zeros
                        end else if (digit_counter == 0) begin
                            // Output zeros
                            if (count[0] > 0) begin
                                output_digits[output_index] <= 0;
                                output_index <= output_index + 1;
                                count[0] <= count[0] - 1;
                            end else begin
                                done <= 1;
                            end
                        end
                    end else begin
                        done <= 1;
                    end
                end
            endcase
        end
    end

    always @(*) begin
        case (state)
            IDLE: next_state = start ? COUNT : IDLE;
            COUNT: next_state = (digit_counter >= input_length) ? DECREMENT : COUNT;
            DECREMENT: next_state = CALCULATE_MOD;
            CALCULATE_MOD: begin
                if (digit_counter >= 10) next_state = LOOKUP;
                else if (count[digit_counter] > 0) next_state = CALCULATE_MOD;
                else next_state = CALCULATE_MOD; // Will increment counter
            end
            LOOKUP: next_state = OUTPUT;
            OUTPUT: begin
                if (done) next_state = IDLE;
                else next_state = OUTPUT;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

