module find_min #(
    parameter ARRAY_SIZE = 8,
    parameter DATA_WIDTH = 8,
    parameter RESULT_WIDTH = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [DATA_WIDTH-1:0] arr [0:ARRAY_SIZE-1],
    input wire [3:0] len,  // Number of valid elements (1-8)
    output reg [RESULT_WIDTH-1:0] result,
    output reg done
);

// State machine states
reg [2:0] state;
localparam IDLE = 3'b000;
localparam COMPARE = 3'b001;
localparam FINISHED = 3'b010;

// Internal registers
reg [DATA_WIDTH-1:0] current_min;
reg [3:0] index;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset state
        state <= IDLE;
        result <= 0;
        done <= 0;
        current_min <= 0;
        index <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start && len > 0) begin
                    // Initialize with first element
                    current_min <= arr[0];
                    index <= 1;  // Start comparing from element 1
                    state <= COMPARE;
                end
            end

            COMPARE: begin
                if (index < len) begin
                    // Compare current element with running minimum
                    if (arr[index] < current_min) begin
                        current_min <= arr[index];
                    end
                    index <= index + 1;
                end else begin
                    // All elements processed
                    result <= current_min;
                    state <= FINISHED;
                end
            end

            FINISHED: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module harmonic_sum (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] n,           // Input n (max 255)
    output reg [15:0] result,     // Q8.8 fixed-point result
    output reg done
);

// Parameters
parameter MAX_ITER = 255;
parameter CLK_DELAY = 120;       // Cycles for division approximation

// State machine
reg [2:0] state;
reg [7:0] counter;              // Current iteration (i)
reg [15:0] accumulator;         // Q8.8 fixed-point accumulator
reg [15:0] divisor;             // Q8.8 divisor (1/n)
reg [7:0] iterations_remaining; // Counter for division delay
reg division_done;              // Division completion flag

// States
localparam IDLE = 3'd0;
localparam CALC_START = 3'd1;
localparam DIVIDE = 3'd2;
localparam ACCUMULATE = 3'd3;
localparam COMPLETE = 3'd4;

// Division approximation: 1/n in Q8.8
// Uses lookup table for n=1..255
reg [15:0] reciprocal_lut [0:255];

// Initialize LUT (combinational)
integer i;
initial begin
    // Precompute 1/n in Q8.8 format
    // Q8.8 = integer * 256
    reciprocal_lut[0] = 16'hFFFF;  // Undefined, max
    reciprocal_lut[1] = 16'h0100;  // 1.0 * 256 = 256
    reciprocal_lut[2] = 16'h0080;  // 0.5 * 256 = 128
    reciprocal_lut[3] = 16'h0055;  // 0.333 * 256 ≈ 85
    reciprocal_lut[4] = 16'h0040;  // 0.25 * 256 = 64
    reciprocal_lut[5] = 16'h0033;  // 0.2 * 256 ≈ 51
    reciprocal_lut[6] = 16'h002A;  // 0.166 * 256 ≈ 42
    reciprocal_lut[7] = 16'h0024;  // 0.1428 * 256 ≈ 36
    reciprocal_lut[8] = 16'h0020;  // 0.125 * 256 = 32
    reciprocal_lut[9] = 16'h001C;  // 0.111 * 256 ≈ 28
    reciprocal_lut[10] = 16'h0019; // 0.1 * 256 = 25
    // Values 11-255: scale down by factor of 256/n
    for (i = 11; i <= 255; i = i + 1) begin
        reciprocal_lut[i] = (256 * 256) / i;  // (256/ i) * 256 in Q8.8
    end
end

// State register and next state logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 16'd0;
        done <= 1'b0;
        accumulator <= 16'd0;
        counter <= 8'd0;
        divisor <= 16'd0;
        iterations_remaining <= 8'd0;
        division_done <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    // Initialize: accumulator = 0, counter = n
                    accumulator <= 16'd0;
                    counter <= n;
                    state <= CALC_START;
                end
            end

            CALC_START: begin
                // Check if counter >= 2 (harmonic sum of n-1)
                if (counter >= 8'd2) begin
                    // Get reciprocal of counter
                    divisor <= reciprocal_lut[counter];
                    iterations_remaining <= CLK_DELAY;
                    division_done <= 1'b0;
                    state <= DIVIDE;
                end else begin
                    // Base case: harmonic_sum(1) = 1, add final value
                    accumulator <= accumulator + 16'h0100; // Add 1.0 in Q8.8
                    state <= COMPLETE;
                end
            end

            DIVIDE: begin
                // Simulate division delay
                if (iterations_remaining > 8'd0) begin
                    iterations_remaining <= iterations_remaining - 8'd1;
                    division_done <= 1'b0;
                end else begin
                    division_done <= 1'b1;
                end

                if (division_done) begin
                    state <= ACCUMULATE;
                end
            end

            ACCUMULATE: begin
                // Add 1/n to accumulator
                accumulator <= accumulator + divisor;
                // Decrement counter and continue
                counter <= counter - 8'd1;
                state <= CALC_START;
            end

            COMPLETE: begin
                result <= accumulator;
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module majority_element (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] n,  // Array length (1-8)
    input wire [7:0] x,  // Element to search
    output reg result,
    output reg done
);

    // State machine states
    localparam IDLE = 2'd0;
    localparam SEARCH = 2'd1;
    localparam CHECK = 2'd2;
    localparam FINISH = 2'd3;

    reg [1:0] state;
    reg [3:0] low, high, mid;
    reg [7:0] target;
    reg [3:0] arr_len;
    reg found_flag;
    reg [3:0] found_idx;
    reg [3:0] check_cnt;

    // Search logic (iterative binary search)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 0;
            done <= 0;
            found_flag <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        target <= x;
                        arr_len <= n;
                        low <= 0;
                        high <= n - 1;
                        found_flag <= 0;
                        check_cnt <= 0;
                        state <= (n > 0) ? SEARCH : FINISH;
                    end
                end

                SEARCH: begin
                    // Iterative binary search for first occurrence
                    if (high >= low) begin
                        mid <= (low + high) >> 1;
                        // Determine next state based on comparison
                        // We need to read array value at mid - will be done in next cycle
                        // For simplicity, we use combinational logic below
                        if (mid == 0 || (get_arr_val(mid-1) < target)) begin
                            if (get_arr_val(mid) == target) begin
                                found_flag <= 1;
                                found_idx <= mid;
                                state <= CHECK;
                            end else if (target > get_arr_val(mid)) begin
                                low <= mid + 1;
                            end else begin
                                if (mid == 0) state <= FINISH;
                                else high <= mid - 1;
                            end
                        end else begin
                            high <= mid - 1;
                        end
                    end else begin
                        state <= FINISH;
                    end
                end

                CHECK: begin
                    // Check if element at found_idx + n/2 equals target
                    if (found_idx + (arr_len >> 1) < arr_len) begin
                        if (get_arr_val(found_idx + (arr_len >> 1)) == target) begin
                            result <= 1;
                        end else begin
                            result <= 0;
                        end
                    end else begin
                        result <= 0;
                    end
                    state <= FINISH;
                end

                FINISH: begin
                    if (!found_flag && state != FINISH) begin
                        result <= 0;
                    end
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

    // Combinational array read function
    function [7:0] get_arr_val;
        input [3:0] idx;
        begin
            case (idx)
                4'd0: get_arr_val = arr_0;
                4'd1: get_arr_val = arr_1;
                4'd2: get_arr_val = arr_2;
                4'd3: get_arr_val = arr_3;
                4'd4: get_arr_val = arr_4;
                4'd5: get_arr_val = arr_5;
                4'd6: get_arr_val = arr_6;
                4'd7: get_arr_val = arr_7;
                default: get_arr_val = 8'hXX;
            endcase
        end
    endfunction

endmodule

module max_product_subarray (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] len,
    output reg [15:0] result,
    output reg done
);

    // State encoding
    localparam IDLE = 3'b000;
    localparam COMPUTE = 3'b001;
    localparam FINISH = 3'b010;
    localparam ERROR = 3'b011;

    // Internal registers
    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] index;
    reg [15:0] max_ending_here;
    reg [15:0] min_ending_here;
    reg [15:0] max_so_far;
    reg has_non_zero;
    reg [7:0] current_element;
    reg [15:0] temp_max;
    reg [15:0] temp_min;

    // Helper signals for multiplication with overflow protection
    wire signed [16:0] max_times_current;
    wire signed [16:0] min_times_current;

    // Signed multiplication (treating inputs as signed for correct product behavior)
    assign max_times_current = $signed({1'b0, max_ending_here}) * $signed(current_element);
    assign min_times_current = $signed({1'b0, min_ending_here}) * $signed(current_element);

    // Current element selection
    always @(*) begin
        case(index)
            3'd0: current_element = arr_0;
            3'd1: current_element = arr_1;
            3'd2: current_element = arr_2;
            3'd3: current_element = arr_3;
            3'd4: current_element = arr_4;
            3'd5: current_element = arr_5;
            3'd6: current_element = arr_6;
            3'd7: current_element = arr_7;
            default: current_element = 8'd0;
        endcase
    end

    // Next state logic
    always @(*) begin
        case(state)
            IDLE: begin
                if (start)
                    next_state = COMPUTE;
                else
                    next_state = IDLE;
            end
            COMPUTE: begin
                if (index >= len)
                    next_state = FINISH;
                else
                    next_state = COMPUTE;
            end
            FINISH: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Main computation logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            index <= 3'd0;
            max_ending_here <= 16'd1;
            min_ending_here <= 16'd1;
            max_so_far <= 16'd0;
            has_non_zero <= 1'b0;
            result <= 16'd0;
            done <= 1'b0;
        end else begin
            case(state)
                IDLE: begin
                    if (start) begin
                        index <= 3'd0;
                        max_ending_here <= 16'd1;
                        min_ending_here <= 16'd1;
                        max_so_far <= 16'd0;
                        has_non_zero <= 1'b0;
                        done <= 1'b0;
                    end
                end

                COMPUTE: begin
                    if (index < len) begin
                        if (current_element > 8'sd0) begin
                            // Positive number
                            max_ending_here <= max_ending_here * current_element;
                            if (min_ending_here * current_element < 16'sd1)
                                min_ending_here <= 16'd1;
                            else
                                min_ending_here <= min_ending_here * current_element;
                            has_non_zero <= 1'b1;
                        end else if (current_element == 8'sd0) begin
                            // Zero
                            max_ending_here <= 16'd1;
                            min_ending_here <= 16'd1;
                        end else begin
                            // Negative number
                            temp_max <= (min_ending_here * current_element > 16'sd1) ? 
                                        (min_ending_here * current_element) : 16'd1;
                            temp_min <= max_ending_here * current_element;
                            // Update in next cycle to avoid race condition
                        end

                        // Update max_so_far (compare after computing new values)
                        if (current_element != 8'sd0) begin
                            if (current_element > 8'sd0) begin
                                if (max_ending_here * current_element > max_so_far)
                                    max_so_far <= max_ending_here * current_element;
                            end else begin
                                if (min_ending_here * current_element > max_so_far)
                                    max_so_far <= min_ending_here * current_element;
                            end
                        end

                        index <= index + 1'b1;
                    end
                end

                FINISH: begin
                    result <= max_so_far;
                    done <= 1'b1;
                end

                default: begin
                    index <= 3'd0;
                    max_ending_here <= 16'd1;
                    min_ending_here <= 16'd1;
                    max_so_far <= 16'd0;
                    has_non_zero <= 1'b0;
                    result <= 16'd0;
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

