module positive_ratio(
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [3:0] len,
    output reg [15:0] result,
    output reg done
);

    // Internal state registers
    reg [3:0] idx;           // Current array index (0-8)
    reg [3:0] pos_count;     // Count of positive numbers (0-8)
    reg processing;          // FSM state: 0=idle, 1=processing
    reg [1:0] state;         // State machine: 00=idle, 01=counting, 10=calculating, 11=done

    // Fixed-point arithmetic: Q8.8 format (8 integer, 8 fractional bits)
    // For division: result = (pos_count * 256) / len
    reg [15:0] numerator;    // pos_count * 256
    reg [15:0] quotient;     // Division result
    reg [5:0] bit_idx;       // Bit index for division (0-16)

    // Combinational logic for array element access
    wire [7:0] current_elem;
    assign current_elem = (idx == 4'd0) ? arr_0 :
                          (idx == 4'd1) ? arr_1 :
                          (idx == 4'd2) ? arr_2 :
                          (idx == 4'd3) ? arr_3 :
                          (idx == 4'd4) ? arr_4 :
                          (idx == 4'd5) ? arr_5 :
                          (idx == 4'd6) ? arr_6 :
                          arr_7;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state <= 2'b00;
            idx <= 4'd0;
            pos_count <= 4'd0;
            result <= 16'd0;
            done <= 1'b0;
            numerator <= 16'd0;
            quotient <= 16'd0;
            bit_idx <= 6'd0;
        end else begin
            case (state)
                2'b00: begin // Idle state
                    done <= 1'b0;
                    if (start) begin
                        state <= 2'b01;  // Go to counting
                        idx <= 4'd0;
                        pos_count <= 4'd0;
                    end
                end

                2'b01: begin // Counting positive numbers
                    if (idx < len) begin
                        // Check if current element is positive (> 0)
                        // Treat signed values: if bit 7 is 0 and not zero, it's positive
                        if (current_elem[7] == 1'b0 && current_elem != 8'h00) begin
                            pos_count <= pos_count + 1'b1;
                        end
                        idx <= idx + 1'b1;
                    end else begin
                        // Done counting, prepare for division
                        state <= 2'b10;  // Go to calculating
                        numerator <= {8'd0, pos_count} << 8;  // Multiply by 256
                        quotient <= 16'd0;
                        bit_idx <= 6'd16;  // 16-bit division
                    end
                end

                2'b10: begin // Calculate ratio using restoring division
                    if (bit_idx > 0) begin
                        // Shift quotient left
                        quotient <= quotient << 1;

                        // Subtract divisor (len) from remainder (numerator[31:16])
                        if (numerator[15:8] >= {1'b0, len}) begin
                            quotient[0] <= 1'b1;
                            numerator[15:8] <= numerator[15:8] - {1'b0, len};
                        end

                        // Shift numerator left
                        numerator <= numerator << 1;
                        bit_idx <= bit_idx - 1'b1;
                    end else begin
                        state <= 2'b11;  // Go to done state
                        result <= quotient;
                        done <= 1'b1;
                    end
                end

                2'b11: begin // Done state
                    done <= 1'b0;
                    if (!start) begin
                        state <= 2'b00;  // Return to idle when start is low
                    end
                end

                default: state <= 2'b00;
            endcase
        end
    end

endmodule

module rear_extract(
    // Inputs: 3 tuples, each with 3 elements (8-bit each)
    input [7:0] tuple_0_elem_0,
    input [7:0] tuple_0_elem_1,
    input [7:0] tuple_0_elem_2,
