// Module: merge_three_dictionaries
// Description: Merges three dictionaries into one with priority resolution.
// If keys are duplicated, values from later dictionaries override earlier ones.
//
// Implementation Strategy:
// - Fixed capacity: Maximum 8 unique keys total
// - Key/Value width: 8 characters (8-bit ASCII each)
// - Input: Three dictionaries provided as parallel arrays
//   (each dictionary has up to 8 key-value pairs)
// - Output: Flattened arrays of keys and values, with valid count
//
// INTERFACE SPECIFICATION:
//
// Inputs (dict1, dict2, dict3 - all have same structure):
//   - dict1_valid[0:7] : 8-bit, indicates which entries are valid in dict1
//   - dict1_keys[0:7][7:0] : 8x8-bit array, ASCII keys for dict1
//   - dict1_vals[0:7][7:0] : 8x8-bit array, ASCII values for dict1
//   - dict2_valid[0:7] : 8-bit, valid entries mask for dict2
//   - dict2_keys[0:7][7:0] : 8x8-bit keys for dict2
//   - dict2_vals[0:7][7:0] : 8x8-bit values for dict2
//   - dict3_valid[0:7] : 8-bit, valid entries mask for dict3
//   - dict3_keys[0:7][7:0] : 8x8-bit keys for dict3
//   - dict3_vals[0:7][7:0] : 8x8-bit values for dict3
//
// Outputs (merged result):
//   - out_keys[0:7][7:0] : 8x8-bit array, merged keys (priority order)
//   - out_vals[0:7][7:0] : 8x8-bit array, corresponding values
//   - out_count[2:0] : 3-bit count of valid merged entries (0-8)
//   - overflow : 1-bit flag, asserted if more than 8 unique keys
//
// Control Signals:
//   - clk : Clock input (rising edge)
//   - rst_n : Active-low reset
//   - start : Start pulse (1 cycle) to begin merge
//   - done : Asserted high when merge complete (1 cycle pulse)
//
// Operation:
//   1. Assert start for 1 clock cycle
//   2. Module processes merge in multiple cycles
//   3. done goes high when complete
//   4. out_count and overflow indicate result
//   5. out_keys/out_vals contain merged data
//
// Priority Rules:
//   - dict3 values override dict2 and dict1
//   - dict2 values override dict1
//   - dict1 values are base values
//   - Only 8 unique keys can be stored in output
//   - If duplicate keys exist within same dict, later index wins
//
// Example:
//   dict1: {"R":"Red", "B":"Black"}  -> valid=00000011
//   dict2: {"G":"Green", "W":"White"} -> valid=00000011
//   dict3: {"O":"Orange", "W":"White", "B":"Black"} -> valid=00000111
//   Result: 6 entries, overflow=0, key order: R,B,G,W,O,B
//   Values: Red, Black, Green, White, Orange, Black (B from dict3 wins)

module merge_three_dictionaries (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Dictionary 1 inputs
    input wire [7:0] dict1_valid,
    input wire [7:0] dict1_keys [0:7],
    input wire [7:0] dict1_vals [0:7],

    // Dictionary 2 inputs
    input wire [7:0] dict2_valid,
    input wire [7:0] dict2_keys [0:7],
    input wire [7:0] dict2_vals [0:7],

    // Dictionary 3 inputs
    input wire [7:0] dict3_valid,
    input wire [7:0] dict3_keys [0:7],
    input wire [7:0] dict3_vals [0:7],

    // Merged dictionary outputs
    output reg [7:0] out_keys [0:7],
    output reg [7:0] out_vals [0:7],
    output reg [2:0] out_count,
    output reg overflow,

    output reg done
);

    // Internal state
    reg [2:0] state;
    reg [2:0] counter;
    reg [7:0] temp_keys [0:7];
    reg [7:0] temp_vals [0:7];
    reg [7:0] temp_valid;

    // State definitions
    localparam IDLE = 3'b000;
    localparam PROCESS_DICT1 = 3'b001;
    localparam PROCESS_DICT2 = 3'b010;
    localparam PROCESS_DICT3 = 3'b011;
    localparam PACK_RESULTS = 3'b100;
    localparam DONE_STATE = 3'b101;

    integer i, j;
    reg found;
    reg [7:0] key_to_check;
    reg [7:0] val_to_add;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            out_count <= 0;
            overflow <= 0;
            temp_valid <= 0;
            for (i = 0; i < 8; i = i + 1) begin
                temp_keys[i] <= 8'h00;
                temp_vals[i] <= 8'h00;
                out_keys[i] <= 8'h00;
                out_vals[i] <= 8'h00;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= PROCESS_DICT1;
                        counter <= 0;
                        temp_valid <= 0;
                        for (i = 0; i < 8; i = i + 1) begin
                            temp_keys[i] <= 8'h00;
                            temp_vals[i] <= 8'h00;
                        end
                    end
                end

                PROCESS_DICT1: begin
                    if (counter < 8) begin
                        if (dict1_valid[counter]) begin
                            key_to_check <= dict1_keys[counter];
                            val_to_add <= dict1_vals[counter];
                            // Continue to check next cycle
                        end
                        counter <= counter + 1;
                        // Simple add without duplicate check for first dict
                        if (dict1_valid[counter]) begin
                            // Add to temp array
                            for (i = 0; i < 8; i = i + 1) begin
                                if (i == counter) begin
                                    temp_keys[i] <= dict1_keys[i];
                                    temp_vals[i] <= dict1_vals[i];
                                end
                            end
                            temp_valid[counter] <= 1;
                        end
                    end else begin
                        counter <= 0;
                        state <= PROCESS_DICT2;
                    end
                end

                PROCESS_DICT2: begin
                    if (counter < 8) begin
                        if (dict2_valid[counter]) begin
                            key_to_check <= dict2_keys[counter];
                            val_to_add <= dict2_vals[counter];
                            // Check for match in existing temp entries
                            found <= 0;
                            for (i = 0; i < 8; i = i + 1) begin
                                if (temp_valid[i] && temp_keys[i] == dict2_keys[counter]) begin
                                    temp_vals[i] <= dict2_vals[counter];
                                    found <= 1;
                                end
                            end
                            // If not found, add to first empty slot
                            if (!found) begin
                                for (i = 0; i < 8; i = i + 1) begin
                                    if (!temp_valid[i]) begin
                                        temp_keys[i] <= dict2_keys[counter];
                                        temp_vals[i] <= dict2_vals[counter];
                                        temp_valid[i] <= 1;
                                        // Check for overflow
                                        if (i >= 7) overflow <= 1;
                                        break;
                                    end
                                end
                            end
                        end
                        counter <= counter + 1;
                    end else begin
                        counter <= 0;
                        state <= PROCESS_DICT3;
                    end
                end

                PROCESS_DICT3: begin
                    if (counter < 8) begin
                        if (dict3_valid[counter]) begin
                            key_to_check <= dict3_keys[counter];
                            val_to_add <= dict3_vals[counter];
                            // Always override if key exists
                            found <= 0;
                            for (i = 0; i < 8; i = i + 1) begin
                                if (temp_valid[i] && temp_keys[i] == dict3_keys[counter]) begin
                                    temp_vals[i] <= dict3_vals[counter];
                                    found <= 1;
                                end
                            end
                            // If not found, add to first empty slot
                            if (!found) begin
                                for (i = 0; i < 8; i = i + 1) begin
                                    if (!temp_valid[i]) begin
                                        temp_keys[i] <= dict3_keys[counter];
                                        temp_vals[i] <= dict3_vals[counter];
                                        temp_valid[i] <= 1;
                                        if (i >= 7) overflow <= 1;
                                        break;
                                    end
                                end
                            end
                        end
                        counter <= counter + 1;
                    end else begin
                        counter <= 0;
                        state <= PACK_RESULTS;
                    end
                end

                PACK_RESULTS: begin
                    // Pack temp arrays into output arrays
                    out_count <= 0;
                    for (i = 0; i < 8; i = i + 1) begin
                        out_keys[i] <= 8'h00;
                        out_vals[i] <= 8'h00;
                    end

                    j = 0;
                    for (i = 0; i < 8; i = i + 1) begin
                        if (temp_valid[i]) begin
                            out_keys[j] <= temp_keys[i];
                            out_vals[j] <= temp_vals[i];
                            j = j + 1;
                        end
                    end
                    out_count <= j[2:0];
                    state <= DONE_STATE;
                end

                DONE_STATE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module is_sum_of_powers_of_two(
  input [7:0] n,
  output is_sum
);
  // Check if n can be represented as sum of non-zero powers of 2
  // According to test cases: even numbers return True, odd numbers return False
  // This is simply checking if the least significant bit is 0

  assign is_sum = (n[0] == 1'b0);

endmodule

module median_three_numbers (
    // Inputs (3 numbers)
    input  [7:0] a,
    input  [7:0] b,
    input  [7:0] c,

    // Output (median value)
    output [7:0] median
);

// Combinational logic to find median of three 8-bit numbers
// Strategy: Use comparators to determine which value is the middle

// Internal signals
wire a_gt_b;
wire a_gt_c;
wire b_gt_c;

// Comparison results
assign a_gt_b = (a > b);
assign a_gt_c = (a > c);
assign b_gt_c = (b > c);

// The median is the value that is not the maximum and not the minimum
// a is median when: (a >= b && a <= c) or (a <= b && a >= c)
// b is median when: (b >= a && b <= c) or (b <= a && b >= c)
// otherwise c is median

wire use_a;
wire use_b;

assign use_a = (a_gt_b && a_gt_c == 0) || (a_gt_b == 0 && a_gt_c);
assign use_b = (a_gt_b == 0 && b_gt_c) || (a_gt_b && b_gt_c == 0);

// Final multiplexer
assign median = use_a ? a :
                use_b ? b :
                        c;

endmodule

module largest_neg(
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    output reg [7:0] result,
    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state;
    reg [2:0] index;
    reg signed [7:0] current_max;
    reg signed [7:0] arr_reg [0:5];

    integer i;

    // Load input registers on start
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state <= IDLE;
            done <= 0;
            result <= 8'sd0;
            index <= 3'd0;
            current_max <= 8'sd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load inputs into registers
                        arr_reg[0] <= arr_0;
                        arr_reg[1] <= arr_1;
                        arr_reg[2] <= arr_2;
                        arr_reg[3] <= arr_3;
                        arr_reg[4] <= arr_4;
                        arr_reg[5] <= arr_5;
                        // Initialize with first element
                        current_max <= $signed(arr_0);
                        index <= 3'd1;
                        state <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    if (index < 6) begin
                        // Compare: since we want largest negative, 
                        // we're actually finding minimum value
                        if ($signed(arr_reg[index]) < current_max) begin
                            current_max <= $signed(arr_reg[index]);
                        end
                        index <= index + 1'b1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    result <= current_max;
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module tuple_concatenator (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input tuple elements (8-bit ASCII characters each)
    // Fixed 4-element tuple as specified in test cases
    input wire [7:0] elem0,
    input wire [7:0] elem1,
    input wire [7:0] elem2,
    input wire [7:0] elem3,

    // Output: concatenated string (max 32 characters, 256 bits)
    output reg [255:0] result,
    output reg [5:0] length,  // Actual length of result (0-32)
    output reg done
);

    // Constants
    localparam DELIM = 8'h2D;  // ASCII '-' = 0x2D
    localparam MAX_LEN = 32;

    // State machine states
    typedef enum logic [2:0] {
        IDLE,
        CONCAT0,  // Process elem0
        ADD_DELIM0,
        CONCAT1,  // Process elem1
        ADD_DELIM1,
        CONCAT2,  // Process elem2
        ADD_DELIM2,
        CONCAT3,  // Process elem3 (no delimiter after)
        COMPLETE
    } state_t;

    state_t current_state, next_state;

    // Internal registers for building result
    reg [255:0] result_reg;
    reg [5:0] pos_reg;  // Current position in result

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            result_reg <= 256'h0;
            pos_reg <= 6'd0;
            done <= 1'b0;
            length <= 6'd0;
        end else begin
            current_state <= next_state;

            case (current_state)
                IDLE: begin
                    result_reg <= 256'h0;
                    pos_reg <= 6'd0;
                    done <= 1'b0;
                    length <= 6'd0;
                end

                CONCAT0: begin
                    // Copy elem0 bytes to result (assuming 1 byte per char)
                    result_reg[7:0] <= elem0;
                    pos_reg <= 6'd1;
                end

                ADD_DELIM0: begin
                    result_reg[15:8] <= DELIM;
                    pos_reg <= 6'd2;
                end

                CONCAT1: begin
                    result_reg[23:16] <= elem1;
                    pos_reg <= 6'd3;
                end

                ADD_DELIM1: begin
                    result_reg[31:24] <= DELIM;
                    pos_reg <= 6'd4;
                end

                CONCAT2: begin
                    result_reg[39:32] <= elem2;
                    pos_reg <= 6'd5;
                end

                ADD_DELIM2: begin
                    result_reg[47:40] <= DELIM;
                    pos_reg <= 6'd6;
                end

                CONCAT3: begin
                    result_reg[55:48] <= elem3;
                    pos_reg <= 6'd7;
                    length <= 6'd7;  // 7 characters total
                end

                COMPLETE: begin
                    result <= result_reg;
                    done <= 1'b1;
                end
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                if (start)
                    next_state = CONCAT0;
            end

            CONCAT0: begin
                next_state = ADD_DELIM0;
            end

            ADD_DELIM0: begin
                next_state = CONCAT1;
            end

            CONCAT1: begin
                next_state = ADD_DELIM1;
            end

            ADD_DELIM1: begin
                next_state = CONCAT2;
            end

            CONCAT2: begin
                next_state = ADD_DELIM2;
            end

            ADD_DELIM2: begin
                next_state = CONCAT3;
            end

            CONCAT3: begin
                next_state = COMPLETE;
            end

            COMPLETE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

module odd_values_string (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] str [0:15],  // 16-character input string (ASCII bytes)
    input wire [4:0] len,          // Actual string length (0-16)
    output reg [7:0] result [0:7], // Result: max 8 chars (for 16-char input)
    output reg done,
    output reg [3:0] result_len    // Result length
);

    // State machine states
    reg [2:0] state;
    localparam IDLE = 3'b000;
    localparam COMPUTE = 3'b001;
    localparam FINISH = 3'b010;

    // Internal counters and registers
    reg [4:0] i;  // Input index
    reg [3:0] j;  // Output index
    reg [4:0] len_reg;  // Store length

    integer k;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset
            state <= IDLE;
            done <= 1'b0;
            result_len <= 4'b0;
            for (k = 0; k < 8; k = k + 1) begin
                result[k] <= 8'h00;
            end
            i <= 5'b0;
            j <= 4'b0;
            len_reg <= 5'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPUTE;
                        i <= 5'b0;
                        j <= 4'b0;
                        len_reg <= len;
                        // Clear result array
                        for (k = 0; k < 8; k = k + 1) begin
                            result[k] <= 8'h00;
                        end
                    end
                end

                COMPUTE: begin
                    if (i < len_reg && j < 8) begin
                        // Check if index is even (i % 2 == 0)
                        if (i[0] == 1'b0) begin  // Even index
                            result[j] <= str[i];
                            j <= j + 1;
                        end
                        i <= i + 1;
                    end else begin
                        // Done processing
                        result_len <= j;
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module cylinder_volume (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] radius,      // Fixed-point Q8.8 format (8 integer, 8 fractional)
    input wire [15:0] height,      // Fixed-point Q8.8 format
    output reg [31:0] volume,      // Fixed-point Q16.16 format
    output reg done
);

    // Constants: π * 65536 for Q16.16 fixed-point
    // π = 3.14159265 * 65536 = 205887
    localparam PI_FIXED = 205887;

    // State machine states
    localparam IDLE = 2'b00;
    localparam CALC_R_SQ = 2'b01;
    localparam CALC_VOL = 2'b10;
    localparam FINISH = 2'b11;

    reg [1:0] state;
    reg [1:0] next_state;

    // Intermediate registers for multiplication
    reg [31:0] r_squared;      // r * r in Q16.16
    reg [31:0] r_squared_h;    // r² * h in Q16.16

    // Multiplier stage registers
    reg [31:0] mult_a;
    reg [31:0] mult_b;
    wire [63:0] mult_result;

    // Sequential multiplication (2 cycles)
    // Input Q8.8, Output Q16.16
    // (a * b) >> 8 = (a * b) / 256
    assign mult_result = mult_a * mult_b;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            volume <= 0;
            r_squared <= 0;
            r_squared_h <= 0;
            mult_a <= 0;
            mult_b <= 0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Start r_squared = radius * radius
                        mult_a <= {16'b0, radius};  // Q8.8 to Q16.16
                        mult_b <= {16'b0, radius};
                    end
                end

                CALC_R_SQ: begin
                    // r_squared = (mult_result >> 8) for Q8.8 * Q8.8 -> Q16.16
                    r_squared <= mult_result[47:16];
                    // Start r_squared_h = r_squared * height
                    mult_a <= mult_result[47:16];
                    mult_b <= {16'b0, height};
                end

                CALC_VOL: begin
                    // r_squared_h = (mult_result >> 8)
                    r_squared_h <= mult_result[47:16];
                end

                FINISH: begin
                    // volume = r_squared_h * PI >> 16 for Q16.16 * Q16.16 -> Q16.16
                    // Actually: (r_squared_h * PI) >> 16
                    volume <= (r_squared_h * PI_FIXED) >> 16;
                    done <= 1;
                end
            endcase
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = CALC_R_SQ;
            CALC_R_SQ: next_state = CALC_VOL;
            CALC_VOL: next_state = FINISH;
            FINISH: next_state = IDLE;
        endcase
    end

endmodule

module SortTuplesByScore #(
    parameter NUM_ELEMENTS = 4,
    parameter DATA_WIDTH = 16,   // Width for the score (second tuple element)
    parameter NAME_WIDTH = 8     // Width for name/ID (first tuple element)
) (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input array of tuples - packed format
    // Each tuple: [NAME_WIDTH-1:0] name, [DATA_WIDTH-1:0] score
    // Using separate signals for clarity
    input wire [NAME_WIDTH-1:0] in_name_0,
    input wire [DATA_WIDTH-1:0] in_score_0,
    input wire [NAME_WIDTH-1:0] in_name_1,
    input wire [DATA_WIDTH-1:0] in_score_1,
    input wire [NAME_WIDTH-1:0] in_name_2,
    input wire [DATA_WIDTH-1:0] in_score_2,
    input wire [NAME_WIDTH-1:0] in_name_3,
    input wire [DATA_WIDTH-1:0] in_score_3,

    // Output sorted array of tuples
    output reg [NAME_WIDTH-1:0] out_name_0,
    output reg [DATA_WIDTH-1:0] out_score_0,
    output reg [NAME_WIDTH-1:0] out_name_1,
    output reg [DATA_WIDTH-1:0] out_score_1,
    output reg [NAME_WIDTH-1:0] out_name_2,
    output reg [DATA_WIDTH-1:0] out_score_2,
    output reg [NAME_WIDTH-1:0] out_name_3,
    output reg [DATA_WIDTH-1:0] out_score_3,

    output reg done
);

    // State machine for sorting
    reg [2:0] state;
    reg [2:0] next_state;

    // Internal storage for sorting
    reg [NAME_WIDTH-1:0] names [0:3];
    reg [DATA_WIDTH-1:0] scores [0:3];

    // Comparator result signals
    wire comp_0_1;
    wire comp_1_2;
    wire comp_2_3;

    // Comparator logic - compare scores only
    assign comp_0_1 = scores[0] > scores[1];
    assign comp_1_2 = scores[1] > scores[2];
    assign comp_2_3 = scores[2] > scores[3];

    // State definitions
    localparam STATE_IDLE = 3'd0;
    localparam STATE_LOAD = 3'd1;
    localparam STATE_SORT_1 = 3'd2;
    localparam STATE_SORT_2 = 3'd3;
    localparam STATE_SORT_3 = 3'd4;
    localparam STATE_DONE = 3'd5;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            STATE_IDLE: begin
                if (start)
                    next_state = STATE_LOAD;
                else
                    next_state = STATE_IDLE;
            end
            STATE_LOAD: next_state = STATE_SORT_1;
            STATE_SORT_1: next_state = STATE_SORT_2;
            STATE_SORT_2: next_state = STATE_SORT_3;
            STATE_SORT_3: next_state = STATE_DONE;
            STATE_DONE: next_state = STATE_IDLE;
            default: next_state = STATE_IDLE;
        endcase
    end

    // Sorting logic (bubble sort passes)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset outputs
            out_name_0 <= 0; out_score_0 <= 0;
            out_name_1 <= 0; out_score_1 <= 0;
            out_name_2 <= 0; out_score_2 <= 0;
            out_name_3 <= 0; out_score_3 <= 0;
            done <= 0;
        end else begin
            done <= 0;

            case (state)
                STATE_LOAD: begin
                    // Load input data
                    names[0] <= in_name_0;
                    scores[0] <= in_score_0;
                    names[1] <= in_name_1;
                    scores[1] <= in_score_1;
                    names[2] <= in_name_2;
                    scores[2] <= in_score_2;
                    names[3] <= in_name_3;
                    scores[3] <= in_score_3;
                end

                STATE_SORT_1: begin
                    // First pass: compare adjacent pairs (0-1, 1-2, 2-3)
                    if (comp_0_1) begin
                        names[0] <= names[1];
                    scores[0] <= scores[1];
                        names[1] <= names[0];
                    scores[1] <= scores[0];
                    end
                    if (comp_1_2) begin
                        names[1] <= names[2];
                    scores[1] <= scores[2];
                        names[2] <= names[1];
                    scores[2] <= scores[1];
                    end
                    if (comp_2_3) begin
                        names[2] <= names[3];
                    scores[2] <= scores[3];
                        names[3] <= names[2];
                    scores[3] <= scores[2];
                    end
                end

                STATE_SORT_2: begin
                    // Second pass
                    if (comp_0_1) begin
                        names[0] <= names[1];
                    scores[0] <= scores[1];
                        names[1] <= names[0];
                    scores[1] <= scores[0];
                    end
                    if (comp_1_2) begin
                        names[1] <= names[2];
                    scores[1] <= scores[2];
                        names[2] <= names[1];
                    scores[2] <= scores[1];
                    end
                    if (comp_2_3) begin
                        names[2] <= names[3];
                    scores[2] <= scores[3];
                        names[3] <= names[2];
                    scores[3] <= scores[2];
                    end
                end

                STATE_SORT_3: begin
                    // Third pass
                    if (comp_0_1) begin
                        names[0] <= names[1];
                    scores[0] <= scores[1];
                        names[1] <= names[0];
                    scores[1] <= scores[0];
                    end
                    if (comp_1_2) begin
                        names[1] <= names[2];
                    scores[1] <= scores[2];
                        names[2] <= names[1];
                    scores[2] <= scores[1];
                    end
                    if (comp_2_3) begin
                        names[2] <= names[3];
                    scores[2] <= scores[3];
                        names[3] <= names[2];
                    scores[3] <= scores[2];
                    end

                    // Output the sorted array
                    out_name_0 <= names[0];
                    out_score_0 <= scores[0];
                    out_name_1 <= names[1];
                    out_score_1 <= scores[1];
                    out_name_2 <= names[2];
                    out_score_2 <= scores[2];
                    out_name_3 <= names[3];
                    out_score_3 <= scores[3];
                end

                STATE_DONE: begin
                    done <= 1;
                end
            endcase
        end
    end

endmodule

module find_common_elements (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr0_0, input wire [7:0] arr0_1, input wire [7:0] arr0_2, input wire [7:0] arr0_3,
    input wire [7:0] arr0_4, input wire [7:0] arr0_5, input wire [7:0] arr0_6, input wire [7:0] arr0_7,
    input wire [7:0] arr1_0, input wire [7:0] arr1_1, input wire [7:0] arr1_2, input wire [7:0] arr1_3,
    input wire [7:0] arr1_4, input wire [7:0] arr1_5, input wire [7:0] arr1_6, input wire [7:0] arr1_7,
    input wire [7:0] arr2_0, input wire [7:0] arr2_1, input wire [7:0] arr2_2, input wire [7:0] arr2_3,
    input wire [7:0] arr2_4, input wire [7:0] arr2_5, input wire [7:0] arr2_6, input wire [7:0] arr2_7,
    input wire [3:0] len0, input wire [3:0] len1, input wire [3:0] len2,
    output reg [63:0] result,
    output reg [3:0] result_count,
    output reg done
);

localparam IDLE = 3'b000;
localparam CHECK = 3'b001;
localparam VALIDATE = 3'b010;
localparam STORE = 3'b011;
localparam NEXT = 3'b100;
localparam COMPLETE = 3'b101;

reg [2:0] state, next_state;
reg [3:0] idx0;
reg [3:0] result_idx;
reg [7:0] candidate;
reg found1, found2;

wire [7:0] arr0_data [0:7];
wire [7:0] arr1_data [0:7];
wire [7:0] arr2_data [0:7];

assign arr0_data[0] = arr0_0; assign arr0_data[1] = arr0_1; assign arr0_data[2] = arr0_2; assign arr0_data[3] = arr0_3;
assign arr0_data[4] = arr0_4; assign arr0_data[5] = arr0_5; assign arr0_data[6] = arr0_6; assign arr0_data[7] = arr0_7;
assign arr1_data[0] = arr1_0; assign arr1_data[1] = arr1_1; assign arr1_data[2] = arr1_2; assign arr1_data[3] = arr1_3;
assign arr1_data[4] = arr1_4; assign arr1_data[5] = arr1_5; assign arr1_data[6] = arr1_6; assign arr1_data[7] = arr1_7;
assign arr2_data[0] = arr2_0; assign arr2_data[1] = arr2_1; assign arr2_data[2] = arr2_2; assign arr2_data[3] = arr2_3;
assign arr2_data[4] = arr2_4; assign arr2_data[5] = arr2_5; assign arr2_data[6] = arr2_6; assign arr2_data[7] = arr2_7;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        idx0 <= 4'd0;
        result_idx <= 4'd0;
        result_count <= 4'd0;
        result <= 64'b0;
        done <= 1'b0;
        candidate <= 8'd0;
        found1 <= 1'b0;
        found2 <= 1'b0;
    end else begin
        state <= next_state;
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    idx0 <= 4'd0;
                    result_idx <= 4'd0;
                    result_count <= 4'd0;
                    result <= 64'b0;
                end
            end
            CHECK: begin
                candidate <= arr0_data[idx0];
                found1 <= 1'b0;
                found2 <= 1'b0;
            end
            VALIDATE: begin
                if (idx0 < len0) begin
                    if (idx0 < len1 && arr1_data[idx0] == candidate) found1 <= 1'b1;
                    if (idx0 < len2 && arr2_data[idx0] == candidate) found2 <= 1'b1;
                end
            end
            STORE: begin
                if (idx0 < len0 && found1 && found2 && idx0 < 8) begin
                    result[result_idx*8 +: 8] <= candidate;
                    result_count <= result_count + 1'b1;
                    result_idx <= result_idx + 1'b1;
                end
            end
            NEXT: begin
                idx0 <= idx0 + 1'b1;
            end
            COMPLETE: begin
                done <= 1'b1;
            end
        endcase
    end
end

always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = CHECK;
        CHECK: next_state = VALIDATE;
        VALIDATE: next_state = STORE;
        STORE: next_state = NEXT;
        NEXT: next_state = (idx0 < 8'd7 && idx0 + 1'b1 < len0) ? CHECK : COMPLETE;
        COMPLETE: if (!start) next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

endmodule

module string_is_integer(
  input [127:0] char_array,  // 16 characters, ASCII values, packed (char0 at [7:0], char1 at [15:8], etc.)
  input [3:0] length,        // Number of valid characters (0 to 16)
  output reg is_integer      // 1 = true, 0 = false
);

// Function to check if a character code is a digit
function automatic is_digit(input [7:0] c);
  begin
    is_digit = (c >= 8'd48) && (c <= 8'd57); // '0' to '9'
  end
endfunction

// Function to check if a character code is + or -
function automatic is_sign(input [7:0] c);
  begin
    is_sign = (c == 8'd43) || (c == 8'd45); // '+' or '-'
  end
endfunction

// Combinational logic
always @(*) begin
  // Default to false
  is_integer = 1'b0;

  // Case 0: Empty string
  if (length == 4'd0) begin
    is_integer = 1'b0; // Per spec, return False or None
  end
  // Case 1: Check all digits (no sign)
  else begin
    // We will use a loop for checking (unrollable for synthesis)
    reg all_digits;
    reg all_digits_after_sign;
    reg first_is_sign;
    integer i;

    // Check if all characters are digits
    all_digits = 1'b1;
    for (i = 0; i < 16; i = i + 1) begin
      if (i < length) begin
        if (!is_digit(char_array[i*8 +: 8])) all_digits = 1'b0;
      end
    end

    // Check if first is sign
    first_is_sign = is_sign(char_array[7:0]);

    // Check if all after first are digits
    all_digits_after_sign = 1'b1;
    for (i = 1; i < 16; i = i + 1) begin
      if (i < length) begin
        if (!is_digit(char_array[i*8 +: 8])) all_digits_after_sign = 1'b0;
      end
    end

    // Final logic
    if (length == 1 && is_digit(char_array[7:0])) begin
      is_integer = 1'b1;
    end else if (all_digits && length > 0) begin
      is_integer = 1'b1;
    end else if (first_is_sign && (length > 1) && all_digits_after_sign) begin
      is_integer = 1'b1;
    end
  end
end

endmodule

module circle_circumference (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] radius,          // Radius in Q8.8 format (8 integer, 8 fractional bits)
    output wire [31:0] circumference,   // Result in Q16.16 format (16 integer, 16 fractional bits)
    output wire done
);

// Implementation notes:
// - Fixed-point arithmetic using Q-format
// - pi constant = 3.141592653589793 * 2^16 = 205887
// - Formula: 2 * pi * r
// - Uses sequential computation for division of concerns
// - All operations within 32-bit width

// Internal state machine
reg [1:0] state;
reg [31:0] result_reg;
reg done_reg;

// Constants (Q16.16 format)
localparam PI_FIXED = 32'd205887;  // 3.141592653589793 * 65536
localparam TWO_FIXED = 32'd131072; // 2.0 * 65536

// Computation registers
reg [31:0] mult1_result;
reg [31:0] mult2_result;

// State definitions
localparam IDLE = 2'b00;
localparam CALC1 = 2'b01;  // Compute 2 * pi
localparam CALC2 = 2'b10;  // Multiply by radius
localparam DONE = 2'b11;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result_reg <= 32'd0;
        done_reg <= 1'b0;
        mult1_result <= 32'd0;
        mult2_result <= 32'd0;
    end else begin
        case (state)
            IDLE: begin
                done_reg <= 1'b0;
                if (start) begin
                    state <= CALC1;
                    // Calculate 2 * pi (scaled)
                    mult1_result <= TWO_FIXED * PI_FIXED;
                end
            end

            CALC1: begin
                state <= CALC2;
                // Multiply by radius (convert radius to Q16.16 by shifting left 8 bits)
                mult2_result <= mult1_result * (radius << 8);
            end

            CALC2: begin
                state <= DONE;
                // Final result (right shift 16 to normalize from Q32.32 to Q16.16)
                result_reg <= mult2_result >> 16;
            end

            DONE: begin
                done_reg <= 1'b1;
                if (!start) begin
                    state <= IDLE;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

// Assign outputs
assign done = done_reg;
assign circumference = result_reg;

endmodule

module max_product (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] len,
    output reg [31:0] result,
    output reg done
);

    // Internal state
    reg [3:0] i, j;
    reg [31:0] current_prod;
    reg [31:0] mpis [0:7];
    reg [2:0] state;

    // State definitions
    localparam IDLE = 3'b000;
    localparam INIT = 3'b001;
    localparam INNER_LOOP = 3'b010;
    localparam UPDATE_MPI = 3'b011;
    localparam FIND_MAX = 3'b100;
    localparam DONE_STATE = 3'b101;

    // Array storage
    reg [7:0] arr [0:7];

    always @(posedge clk) begin
        if (!rst_n) begin
            // Reset state
            state <= IDLE;
            done <= 0;
            result <= 0;
            i <= 0;
            j <= 0;
            current_prod <= 0;
            // Clear mpis array
            mpis[0] <= 0;
            mpis[1] <= 0;
            mpis[2] <= 0;
            mpis[3] <= 0;
            mpis[4] <= 0;
            mpis[5] <= 0;
            mpis[6] <= 0;
            mpis[7] <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start && len > 0) begin
                        // Store input array
                        arr[0] <= arr_0;
                        arr[1] <= arr_1;
                        arr[2] <= arr_2;
                        arr[3] <= arr_3;
                        arr[4] <= arr_4;
                        arr[5] <= arr_5;
                        arr[6] <= arr_6;
                        arr[7] <= arr_7;
                        i <= 0;
                        state <= INIT;
                    end
                end

                INIT: begin
                    // Initialize mpis[i] = arr[i]
                    if (i < len) begin
                        mpis[i] <= {24'b0, arr[i]};
                        i <= i + 1;
                    end else begin
                        i <= 0;
                        j <= 0;
                        state <= INNER_LOOP;
                    end
                end

                INNER_LOOP: begin
                    // Outer loop: i from 0 to len-1
                    if (i < len) begin
                        // Initialize inner loop
                        current_prod <= {24'b0, arr[i]};
                        j <= i + 1;
                        state <= UPDATE_MPI;
                    end else begin
                        // Done with all loops, find max
                        result <= 0;
                        i <= 0;
                        state <= FIND_MAX;
                    end
                end

                UPDATE_MPI: begin
                    // Inner loop: j from i+1 to len-1
                    if (j < len) begin
                        // Check if increasing (arr[j-1] <= arr[j])
                        if (arr[j-1] <= arr[j]) begin
                            // Update current_prod and mpis[j]
                            current_prod <= current_prod * {24'b0, arr[j]};
                            // Wait one cycle for multiplication
                            state <= 3'b110;
                        end else begin
                            // Not increasing, break inner loop
                            i <= i + 1;
                            state <= INNER_LOOP;
                        end
                    end else begin
                        // Inner loop complete
                        i <= i + 1;
                        state <= INNER_LOOP;
                    end
                end

                3'b110: begin
                    // Update mpis[j] and increment j
                    if (current_prod > mpis[j]) begin
                        mpis[j] <= current_prod;
                    end
                    j <= j + 1;
                    state <= UPDATE_MPI;
                end

                FIND_MAX: begin
                    // Find max value in mpis array
                    if (i < len) begin
                        if (mpis[i] > result) begin
                            result <= mpis[i];
                        end
                        i <= i + 1;
                    end else begin
                        state <= DONE_STATE;
                    end
                end

                DONE_STATE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module average_of_cube (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [2:0] n,           // n in range 1-8
    output reg [31:0] result,     // Fixed-point Q16.16 format
    output reg done
);

    // Internal registers
    reg [2:0] counter;            // Current number i (1 to n)
    reg [31:0] accumulator;       // Sum of cubes
    reg [2:0] divisor;            // Store n for division
    reg [1:0] state;              // State machine
    reg [4:0] div_counter;        // Division cycle counter

    // Division shift register for Q16.16
    reg [47:0] dividend;          // {accumulator, 16'b0} for division
    reg [31:0] quotient;

    // State definitions
    localparam IDLE = 2'd0;
    localparam ACCUMULATE = 2'd1;
    localparam DIVIDE = 2'd2;
    localparam COMPLETE = 2'd3;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            counter <= 3'd0;
            accumulator <= 32'd0;
            divisor <= 3'd0;
            state <= IDLE;
            done <= 1'b0;
            result <= 32'd0;
            div_counter <= 5'd0;
            dividend <= 48'd0;
            quotient <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start && n >= 3'd1) begin
                        counter <= 3'd1;           // Start from i=1
                        accumulator <= 32'd0;
                        divisor <= n;
                        state <= ACCUMULATE;
                    end
                end

                ACCUMULATE: begin
                    // Calculate i³ and add to accumulator
                    if (counter <= divisor) begin
                        // i³ = i * i * i
                        accumulator <= accumulator + (counter * counter * counter);
                        counter <= counter + 3'd1;
                    end else begin
                        // Done accumulating, prepare for division
                        dividend <= {accumulator, 16'd0};  // Shift left 16 for Q16.16
                        quotient <= 32'd0;
                        div_counter <= 5'd0;
                        state <= DIVIDE;
                    end
                end

                DIVIDE: begin
                    // Simple shift-subtract division (16 cycles for precision)
                    if (div_counter < 5'd16) begin
                        // Shift left
                        quotient <= quotient << 1;
                        dividend <= dividend << 1;

                        // Check if we can subtract divisor
                        if (dividend[47:16] >= {29'd0, divisor}) begin
                            dividend[47:16] <= dividend[47:16] - {29'd0, divisor};
                            quotient <= quotient + 32'd1;
                        end

                        div_counter <= div_counter + 5'd1;
                    end else begin
                        // Division complete
                        result <= quotient;
                        state <= COMPLETE;
                    end
                end

                COMPLETE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

// Interface Specification:
// - Clock: clk (rising edge)
// - Reset: rst_n (active low, synchronous)
// - Start: pulse high for 1 cycle to begin
// - Input n: 3-bit value 1-8
// - Output result: 32-bit Q16.16 fixed-point
// - Done: pulses high for 1 cycle when complete
// - Latency: ~18-20 cycles max (8 accumulations + 16 division cycles)

module empty_dict_check (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] dict_flags [0:7],  // Each byte: 0=empty, 1=non-empty
    input wire [3:0] num_dicts,         // Number of dictionaries (1-8)
    output reg result,
    output reg done
);

// Parameters
parameter MAX_DICTS = 8;

// Internal state
reg [3:0] current_index;
reg checking;
reg all_empty;

// State machine
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset state
        result <= 1'b0;
        done <= 1'b0;
        current_index <= 4'd0;
        checking <= 1'b0;
        all_empty <= 1'b1;
    end else begin
        if (start && !checking) begin
            // Start new computation
            current_index <= 4'd0;
            checking <= 1'b1;
            all_empty <= 1'b1;
            done <= 1'b0;
        end else if (checking) begin
            // Process current dictionary
            if (current_index < num_dicts) begin
                // Check if current dictionary is empty
                if (dict_flags[current_index] != 8'h00) begin
                    all_empty <= 1'b0;
                end
                current_index <= current_index + 4'd1;
            end else begin
                // All dictionaries processed
                result <= all_empty;
                done <= 1'b1;
                checking <= 1'b0;
            end
        end else begin
            // Idle state - clear done
            done <= 1'b0;
        end
    end
end

endmodule

module bitwise_xor_array (
    input clk,
    input rst_n,
    input start,
    input [7:0] arr1 [0:7],
    input [7:0] arr2 [0:7],
    output reg [7:0] result [0:7],
    output reg done
);

    // Parameters
    parameter ARRAY_SIZE = 8;
    parameter DATA_WIDTH = 8;

    // State machine states
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    // State registers
    reg [1:0] state;
    reg [3:0] index;

    // Reset and state transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            index <= 4'd0;
            done <= 1'b0;
            // Clear result array
            for (integer i = 0; i < ARRAY_SIZE; i = i + 1) begin
                result[i] <= 8'd0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    index <= 4'd0;
                    if (start) begin
                        state <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    // Perform XOR for current index
                    result[index] <= arr1[index] ^ arr2[index];
                    index <= index + 1;

                    if (index == ARRAY_SIZE - 1) begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module sum_of_digits (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [2:0] len,
    output reg [15:0] result,
    output reg done
);

    reg [2:0] state;
    localparam IDLE = 3'b000;
    localparam PROCESS = 3'b001;
    localparam CALCULATE = 3'b010;
    localparam FINISH = 3'b011;

    reg [2:0] idx;
    reg [15:0] total_sum;
    reg [7:0] current_val;
    reg [7:0] abs_val;
    reg [3:0] digit_sum;
    reg [1:0] calc_state;
    reg [7:0] temp_val;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 16'b0;
            done <= 1'b0;
            idx <= 3'b0;
            total_sum <= 16'b0;
            digit_sum <= 4'b0;
            abs_val <= 8'b0;
            calc_state <= 2'b00;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= PROCESS;
                        idx <= 3'b0;
                        total_sum <= 16'b0;
                    end
                end

                PROCESS: begin
                    if (idx < len) begin
                        case (idx)
                            3'd0: current_val <= arr_0;
                            3'd1: current_val <= arr_1;
                            3'd2: current_val <= arr_2;
                            3'd3: current_val <= arr_3;
                            3'd4: current_val <= arr_4;
                            3'd5: current_val <= arr_5;
                            3'd6: current_val <= arr_6;
                            3'd7: current_val <= arr_7;
                        endcase
                        state <= CALCULATE;
                        calc_state <= 2'b00;
                        digit_sum <= 4'b0;
                    end else begin
                        state <= FINISH;
                    end
                end

                CALCULATE: begin
                    case (calc_state)
                        2'b00: begin
                            // Get absolute value
                            if (current_val[7]) begin
                                abs_val <= (~current_val + 8'b1);
                            end else begin
                                abs_val <= current_val;
                            end
                            temp_val <= current_val;
                            calc_state <= 2'b01;
                        end
                        2'b01: begin
                            // Extract ones digit
                            if (temp_val >= 8'd10) begin
                                total_sum <= total_sum + {12'b0, temp_val[3:0]};
                                temp_val <= temp_val - 8'd10;
                            end else begin
                                total_sum <= total_sum + {12'b0, temp_val[3:0]};
                                calc_state <= 2'b10;
                            end
                        end
                        2'b10: begin
                            // Extract tens digit
                            if (abs_val >= 8'd100) begin
                                total_sum <= total_sum + 16'd10;
                                abs_val <= abs_val - 8'd100;
                                calc_state <= 2'b11;
                            end else if (abs_val >= 8'd10) begin
                                total_sum <= total_sum + 16'd10;
                                abs_val <= abs_val - 8'd10;
                                calc_state <= 2'b11;
                            end else begin
                                idx <= idx + 1'b1;
                                state <= PROCESS;
                            end
                        end
                        2'b11: begin
                            // Extract hundreds digit
                            if (abs_val != 8'd0) begin
                                total_sum <= total_sum + {12'b0, abs_val[3:0]};
                            end
                            idx <= idx + 1'b1;
                            state <= PROCESS;
                        end
                    endcase
                end

                FINISH: begin
                    result <= total_sum;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

