module longest_word_length(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] str_len_0,
    input wire [7:0] str_len_1,
    input wire [7:0] str_len_2,
    input wire [2:0] word_count,
    output reg [7:0] max_length,
