);

// Fixed maximum of 3 words, each with max length 255 chars
// State machine: IDLE -> COMPARE_0 -> COMPARE_1 -> COMPARE_2 -> COMPLETE

reg [1:0] state;
reg [7:0] current_max;
reg [2:0] index;

localparam IDLE = 2'd0;
localparam COMPARE = 2'd1;
localparam COMPLETE = 2'd2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        max_length <= 8'd0;
        done <= 1'b0;
        current_max <= 8'd0;
        index <= 3'd0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start && word_count > 0) begin
                    // Initialize with first word
                    current_max <= str_len_0;
                    max_length <= str_len_0;
                    index <= 3'd1;
                    if (word_count > 1)
                        state <= COMPARE;
                    else
                        state <= COMPLETE;
                end
            end

            COMPARE: begin
                // Compare current index with max
                if (index < word_count) begin
                    case (index)
                        3'd1: begin
