                            end
                        end
                    endcase
                    index <= index + 1'd1;
                    if (index >= word_count - 1'd1)
                        state <= COMPLETE;
                end else begin
                    state <= COMPLETE;
                end
            end

            COMPLETE: begin
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

