module pos_counter (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [3:0] len,
    output reg [3:0] result,
    output reg done
);
    // Parameters
    parameter MAX_SIZE = 4;

    // Internal state
    reg [1:0] state;
    reg [1:0] index;
    reg [3:0] count;
    reg signed [7:0] current_num;

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    // Main FSM
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            count <= 0;
            index <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= COMPUTE;
                        index <= 0;
                        count <= 0;
                    end
                end

                COMPUTE: begin
                    // Select current number based on index
                    case (index)
                        0: current_num <= arr_0;
                        1: current_num <= arr_1;
                        2: current_num <= arr_2;
                        3: current_num <= arr_3;
                        default: current_num <= 8'sd0;
                    endcase

                    // Count if positive (>= 0) and within length
                    if (index < len && current_num >= 0) begin
                        count <= count + 1;
                    end

                    // Move to next element or finish
                    if (index < len - 1) begin
                        index <= index + 1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    result <= count;
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module count_integer (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    output reg [3:0] result,
    output reg done
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam COUNT = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state;
    reg [1:0] index;
    reg [3:0] count_reg;

    // Detect integer: In this hardware adaptation, we define an "integer"
    // as a value that is NOT a string character (non-printable range)
    // and NOT a float marker. We use simple heuristics:
    // - Values 0-9 (ASCII '0'-'9') are NOT integers (they're chars)
    // - Values 48-57 (ASCII '0'-'9') are NOT integers
    // - Values 32 (space) and above are typically strings
    // - Values below 32 or above 126 could be integers
    // For simplicity: we count values that are < 32 OR > 126
    // This simulates detecting actual int vs string/float types

    wire is_integer;
    assign is_integer = (arr_0 < 8'd32 || arr_0 > 8'd126) && index == 2'd0 ? 1'b1 :
                       (arr_1 < 8'd32 || arr_1 > 8'd126) && index == 2'd1 ? 1'b1 :
                       (arr_2 < 8'd32 || arr_2 > 8'd126) && index == 2'd2 ? 1'b1 :
                       (arr_3 < 8'd32 || arr_3 > 8'd126) && index == 2'd3 ? 1'b1 : 1'b0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 4'd0;
            done <= 1'b0;
            index <= 2'd0;
            count_reg <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    index <= 2'd0;
                    count_reg <= 4'd0;
                    if (start) begin
                        state <= COUNT;
                    end
                end

                COUNT: begin
                    // Check current element
                    if (index == 2'd0) begin
                        if (arr_0 < 8'd32 || arr_0 > 8'd126)
                            count_reg <= count_reg + 1'b1;
                    end else if (index == 2'd1) begin
                        if (arr_1 < 8'd32 || arr_1 > 8'd126)
                            count_reg <= count_reg + 1'b1;
                    end else if (index == 2'd2) begin
                        if (arr_2 < 8'd32 || arr_2 > 8'd126)
                            count_reg <= count_reg + 1'b1;
                    end else if (index == 2'd3) begin
                        if (arr_3 < 8'd32 || arr_3 > 8'd126)
                            count_reg <= count_reg + 1'b1;
                    end

                    if (index < 2'd3) begin
                        index <= index + 1'b1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    result <= count_reg;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module modulo_product (
    input wire clk,              // Clock signal
    input wire rst_n,            // Active-low reset
    input wire start,            // Start pulse (1 cycle)

    // Input array - 8 elements, each 8-bit
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,

    input wire [3:0] len,        // Number of valid elements (1-8)
    input wire [7:0] mod_val,    // Modulo value n (max 255)

    output reg [15:0] result,    // 16-bit result (product can be large)
    output reg done              // Done signal, high for 1 cycle
);

    // Internal state
    reg [2:0] state;             // State machine
    reg [2:0] index;             // Current array index
    reg [15:0] acc;              // Accumulator

    // State definitions
    localparam IDLE = 3'd0;
    localparam COMPUTE = 3'd1;
    localparam DONE = 3'd2;

    // Combinational logic for array access
    wire [7:0] current_val;
    assign current_val = (index == 3'd0) ? arr_0 :
                        (index == 3'd1) ? arr_1 :
                        (index == 3'd2) ? arr_2 :
                        (index == 3'd3) ? arr_3 :
                        (index == 3'd4) ? arr_4 :
                        (index == 3'd5) ? arr_5 :
                        (index == 3'd6) ? arr_6 :
                        arr_7;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state <= IDLE;
            result <= 16'd0;
            done <= 1'b0;
            acc <= 16'd1;
            index <= 3'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // Initialize computation
                        acc <= 16'd1;
                        index <= 3'd0;
                        if (mod_val == 8'd0) begin
                            // Modulo zero - undefined, return 0
                            result <= 16'd0;
                            state <= DONE;
                        end else if (len == 4'd0) begin
                            // Empty array - return 1 % n
                            result <= (16'd1 % mod_val);
                            state <= DONE;
                        end else begin
                            state <= COMPUTE;
                        end
                    end
                end

                COMPUTE: begin
                    // Multiply current element modulo n
                    if (index < len) begin
                        // acc = (acc * (current_val % mod_val)) % mod_val
                        acc <= (acc * (current_val % mod_val)) % mod_val;
                        index <= index + 1'b1;
                    end else begin
                        // Computation complete
                        result <= acc;
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module bell_numbers(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,  // Input n (0-8)
    output reg [63:0] result,
    output reg done
);

// Internal state and registers
reg [2:0] state;
reg [3:0] i, j;
reg [63:0] bell [0:8][0:8]; // 9x9 array for n=0..8
reg processing;

// State definitions
localparam IDLE = 3'd0;
localparam INIT = 3'd1;
localparam LOOP_I = 3'd2;
localparam LOOP_J = 3'd3;
localparam UPDATE = 3'd4;
localparam FINISH = 3'd5;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        processing <= 0;
        i <= 0;
        j <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    state <= INIT;
                    i <= 0;
                    j <= 0;
                end
            end

            INIT: begin
                // Initialize bell[0][0] = 1
                bell[0][0] <= 64'd1;
                i <= 1;
                j <= 0;
                state <= LOOP_I;
            end

            LOOP_I: begin
                if (i <= n) begin
                    bell[i][0] <= bell[i-1][i-1];
                    j <= 1;
                    state <= LOOP_J;
                end else begin
                    state <= FINISH;
                end
            end

            LOOP_J: begin
                if (j <= i) begin
                    state <= UPDATE;
                end else begin
                    i <= i + 1;
                    j <= 0;
                    state <= LOOP_I;
                end
            end

            UPDATE: begin
                bell[i][j] <= bell[i-1][j-1] + bell[i][j-1];
                j <= j + 1;
                state <= LOOP_J;
            end

            FINISH: begin
                result <= bell[n][0];
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module is_undulating (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] digit_0,
    input wire [3:0] digit_1,
    input wire [3:0] digit_2,
    input wire [3:0] digit_3,
    input wire [3:0] digit_4,
    input wire [3:0] digit_5,
    input wire [3:0] digit_6,
    input wire [3:0] digit_7,
    input wire [3:0] length,
    output reg result,
    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam CHECK = 2'b01;
    localparam COMPLETE = 2'b10;

    reg [1:0] state, next_state;
    reg [3:0] index;
    reg temp_result;

    // Array to access digits easily
    wire [3:0] digits [0:7];
    assign digits[0] = digit_0;
    assign digits[1] = digit_1;
    assign digits[2] = digit_2;
    assign digits[3] = digit_3;
    assign digits[4] = digit_4;
    assign digits[5] = digit_5;
    assign digits[6] = digit_6;
    assign digits[7] = digit_7;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            index <= 4'd0;
            temp_result <= 1'b0;
            result <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;

            if (state == IDLE && start) begin
                index <= 4'd2;
                temp_result <= 1'b1;
                done <= 1'b0;
            end else if (state == CHECK) begin
                if (index < length) begin
                    if (digits[index] != digits[index - 2]) begin
                        temp_result <= 1'b0;
                    end
                    index <= index + 1'b1;
                end
            end else if (state == COMPLETE) begin
                result <= temp_result && (length > 4'd2);
                done <= 1'b1;
            end else if (state == IDLE) begin
                done <= 1'b0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = CHECK;
                else
                    next_state = IDLE;
            end

            CHECK: begin
                if (index >= length)
                    next_state = COMPLETE;
                else
                    next_state = CHECK;
            end

            COMPLETE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

module cube_array(
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [3:0] len,          // Number of valid elements (1-8)
    output reg [15:0] result_0,
    output reg [15:0] result_1,
    output reg [15:0] result_2,
    output reg [15:0] result_3,
    output reg [15:0] result_4,
    output reg [15:0] result_5,
    output reg [15:0] result_6,
    output reg [15:0] result_7,
    output reg done
);

    // State definitions
    reg [2:0] state;
    reg [2:0] counter;

    localparam IDLE = 3'd0;
    localparam COMPUTE = 3'd1;
    localparam FINISH = 3'd2;

    // Temporary storage for computation
    reg [7:0] current_val;
    reg [15:0] square;
    reg [15:0] cube;
    reg [2:0] stage;

    // Input array storage
    reg [7:0] arr_reg [0:7];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            counter <= 0;
            stage <= 0;
            // Clear results
            result_0 <= 0; result_1 <= 0; result_2 <= 0; result_3 <= 0;
            result_4 <= 0; result_5 <= 0; result_6 <= 0; result_7 <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    counter <= 0;
                    stage <= 0;
                    if (start) begin
                        // Store inputs
                        arr_reg[0] <= arr_0;
                        arr_reg[1] <= arr_1;
                        arr_reg[2] <= arr_2;
                        arr_reg[3] <= arr_3;
                        arr_reg[4] <= arr_4;
                        arr_reg[5] <= arr_5;
                        arr_reg[6] <= arr_6;
                        arr_reg[7] <= arr_7;
                        state <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    // 3-stage pipeline per element: square (2 cycles), multiply (1 cycle)
                    if (counter < len) begin
                        case (stage)
                            3'd0: begin
                                // Stage 0: Start square = val * val
                                current_val <= arr_reg[counter];
                                square <= arr_reg[counter] * arr_reg[counter];
                                stage <= 3'd1;
                            end
                            3'd1: begin
                                // Stage 1: Wait for square (in this simple design, result ready)
                                stage <= 3'd2;
                            end
                            3'd2: begin
                                // Stage 2: Compute cube = square * val
                                cube <= square * current_val;
                                stage <= 3'd3;
                            end
                            3'd3: begin
                                // Stage 3: Store result and move to next element
                                case (counter)
                                    3'd0: result_0 <= cube;
                                    3'd1: result_1 <= cube;
                                    3'd2: result_2 <= cube;
                                    3'd3: result_3 <= cube;
                                    3'd4: result_4 <= cube;
                                    3'd5: result_5 <= cube;
                                    3'd6: result_6 <= cube;
                                    3'd7: result_7 <= cube;
                                endcase
                                counter <= counter + 1;
                                stage <= 0;
                            end
                        endcase
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module word_finder (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input string: 32 characters total (4 lines * 8 chars)
    // Stored as: arr[0:31] where each element is 1 ASCII char (8 bits)
    input wire [7:0] char_in [0:31],

    output reg [7:0] word1 [0:7],  // First 8-char word (padded with zeros if shorter)
    output reg [7:0] word2 [0:7],  // Second 8-char word (padded with zeros if shorter)
    output reg found,
    output reg done
);

// State machine states
localparam IDLE = 3'b000;
localparam SEARCH_START = 3'b001;
localparam CAPTURE_W1 = 3'b010;
localparam CAPTURE_W2 = 3'b011;
localparam FINISHED = 3'b100;

reg [2:0] state;
reg [5:0] idx;           // Index through 32 chars
reg [5:0] w1_idx;        // Index for word1 (0-7)
reg [5:0] w2_idx;        // Index for word2 (0-7)
reg space_seen;          // Flag for space between words
reg w1_has_p;            // Flag if first word starts with P/p

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        found <= 0;
        done <= 0;
        idx <= 0;
        w1_idx <= 0;
        w2_idx <= 0;
        space_seen <= 0;
        w1_has_p <= 0;
        // Clear output words
        for (i = 0; i < 8; i = i + 1) begin
            word1[i] <= 8'b0;
            word2[i] <= 8'b0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                found <= 0;
                if (start) begin
                    state <= SEARCH_START;
                    idx <= 0;
                    w1_idx <= 0;
                    w2_idx <= 0;
                    space_seen <= 0;
                    w1_has_p <= 0;
                    // Clear word buffers
                    for (i = 0; i < 8; i = i + 1) begin
                        word1[i] <= 8'b0;
                        word2[i] <= 8'b0;
                    end
                end
            end

            SEARCH_START: begin
                if (idx < 32) begin
                    // Check for uppercase P (80) or lowercase p (112)
                    if ((char_in[idx] == 8'h50 || char_in[idx] == 8'h70) && !space_seen) begin
                        // Found 'P' or 'p' as first character
                        w1_has_p <= 1;
                        word1[0] <= char_in[idx];
                        w1_idx <= 1;
                        state <= CAPTURE_W1;
                    end else if (char_in[idx] == 8'h20 && w1_has_p && w1_idx > 0) begin
                        // Space after first word with P
                        space_seen <= 1;
                        state <= CAPTURE_W2;
                        w2_idx <= 0;
                    end else if (char_in[idx] == 8'h20 && !w1_has_p) begin
                        // Space without finding first P-word yet, keep searching
                        state <= SEARCH_START;
                    end else if (char_in[idx] != 8'h20 && w1_has_p && !space_seen) begin
                        // Continue capturing first word
                        if (w1_idx < 8) begin
                            word1[w1_idx] <= char_in[idx];
                            w1_idx <= w1_idx + 1;
                        end
                        state <= CAPTURE_W1;
                    end
                    idx <= idx + 1;
                end else begin
                    // End of input, no match
                    state <= FINISHED;
                    found <= 0;
                end
            end

            CAPTURE_W1: begin
                if (idx < 32) begin
                    if (char_in[idx] == 8'h20) begin
                        // Space after word1
                        space_seen <= 1;
                        state <= CAPTURE_W2;
                        w2_idx <= 0;
                        idx <= idx + 1;
                    end else begin
                        // Continue word1
                        if (w1_idx < 8) begin
                            word1[w1_idx] <= char_in[idx];
                            w1_idx <= w1_idx + 1;
                        end
                        idx <= idx + 1;
                    end
                end else begin
                    state <= FINISHED;
                    found <= 0;
                end
            end

            CAPTURE_W2: begin
                if (idx < 32) begin
                    // Check if this char starts with P/p
                    if ((char_in[idx] == 8'h50 || char_in[idx] == 8'h70) && w2_idx == 0) begin
                        // Valid second word starts with P/p
                        word2[0] <= char_in[idx];
                        w2_idx <= 1;
                        idx <= idx + 1;
                    end else if (w2_idx > 0 && char_in[idx] != 8'h20) begin
                        // Continue second word
                        if (w2_idx < 8) begin
                            word2[w2_idx] <= char_in[idx];
                            w2_idx <= w2_idx + 1;
                        end
                        idx <= idx + 1;
                    end else if (char_in[idx] == 8'h20 && w2_idx > 0) begin
                        // End of second word
                        state <= FINISHED;
                        found <= 1;
                        done <= 1;
                    end else if (char_in[idx] != 8'h20 && w2_idx == 0) begin
                        // Non-P character before second word, invalid
                        state <= FINISHED;
                        found <= 0;
                        done <= 1;
                    end else begin
                        idx <= idx + 1;
                    end
                end else if (w2_idx > 0) begin
                    // End of input with valid second word captured
                    state <= FINISHED;
                    found <= 1;
                    done <= 1;
                end else begin
                    state <= FINISHED;
                    found <= 0;
                    done <= 1;
                end
            end

            FINISHED: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module string_splitter #(
    parameter MAX_INPUT_LEN = 8,
    parameter MAX_TOKENS = 4,
    parameter MAX_TOKEN_LEN = 8,
    parameter CHAR_WIDTH = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [CHAR_WIDTH-1:0] input_string [MAX_INPUT_LEN-1:0],
    output reg [CHAR_WIDTH-1:0] tokens [MAX_TOKENS-1:0][MAX_TOKEN_LEN-1:0],
    output reg [2:0] token_count,
    output reg done,
    output reg error
);

    // State machine states
    localparam IDLE = 3'b000;
    localparam PARSE = 3'b001;
    localparam FINISHED = 3'b010;
    localparam ERROR = 3'b011;

    reg [2:0] state, next_state;
    reg [2:0] token_idx;      // Current token being built
    reg [3:0] char_idx;       // Current character in input
    reg [3:0] token_char_idx; // Current position in current token
    reg [CHAR_WIDTH-1:0] current_token [MAX_TOKEN_LEN-1:0];
    reg [3:0] current_token_len;
    reg in_token;

    integer i;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            token_count <= 0;
            done <= 0;
            error <= 0;
            token_idx <= 0;
            char_idx <= 0;
            token_char_idx <= 0;
            current_token_len <= 0;
            in_token <= 0;
            // Clear output tokens
            for (i = 0; i < MAX_TOKENS; i = i + 1) begin
                tokens[i][0] <= 0; tokens[i][1] <= 0; tokens[i][2] <= 0; tokens[i][3] <= 0;
                tokens[i][4] <= 0; tokens[i][5] <= 0; tokens[i][6] <= 0; tokens[i][7] <= 0;
            end
            // Clear current_token
            for (i = 0; i < MAX_TOKEN_LEN; i = i + 1)
                current_token[i] <= 0;
        end else begin
            state <= next_state;
            if (state == IDLE && start) begin
                token_idx <= 0;
                char_idx <= 0;
                token_char_idx <= 0;
                current_token_len <= 0;
                in_token <= 0;
                done <= 0;
                error <= 0;
                token_count <= 0;
                for (i = 0; i < MAX_TOKEN_LEN; i = i + 1)
                    current_token[i] <= 0;
            end
            if (state == PARSE) begin
                if (char_idx < MAX_INPUT_LEN) begin
                    // Read current character
                    if (input_string[char_idx] != 0) begin // Not null terminator
                        if (input_string[char_idx] == 8'h20) begin // Space character
                            if (in_token) begin
                                // End current token
                                if (token_idx < MAX_TOKENS) begin
                                    for (i = 0; i < MAX_TOKEN_LEN; i = i + 1) begin
                                        if (i < current_token_len)
                                            tokens[token_idx][i] <= current_token[i];
                                        else
                                            tokens[token_idx][i] <= 0;
                                    end
                                    token_idx <= token_idx + 1;
                                    token_count <= token_idx + 1;
                                end
                                in_token <= 0;
                                token_char_idx <= 0;
                                current_token_len <= 0;
                                // Clear current_token
                                for (i = 0; i < MAX_TOKEN_LEN; i = i + 1)
                                    current_token[i] <= 0;
                            end
                        end else begin // Non-space character
                            in_token <= 1;
                            if (token_char_idx < MAX_TOKEN_LEN) begin
                                current_token[token_char_idx] <= input_string[char_idx];
                                token_char_idx <= token_char_idx + 1;
                                current_token_len <= token_char_idx + 1;
                            end else begin
                                // Token too long
                                next_state <= ERROR;
                            end
                        end
                    end else begin // Null terminator
                        if (in_token) begin
                            // Add final token
                            if (token_idx < MAX_TOKENS) begin
                                for (i = 0; i < MAX_TOKEN_LEN; i = i + 1) begin
                                    if (i < current_token_len)
                                        tokens[token_idx][i] <= current_token[i];
                                    else
                                        tokens[token_idx][i] <= 0;
                                end
                                token_count <= token_idx + 1;
                            end
                        end
                        next_state <= FINISHED;
                    end
                    char_idx <= char_idx + 1;
                end else begin
                    // Reached end of input buffer without null
                    if (in_token) begin
                        if (token_idx < MAX_TOKENS) begin
                            for (i = 0; i < MAX_TOKEN_LEN; i = i + 1) begin
                                if (i < current_token_len)
                                    tokens[token_idx][i] <= current_token[i];
                                else
                                    tokens[token_idx][i] <= 0;
                            end
                            token_count <= token_idx + 1;
                        end
                    end
                    next_state <= FINISHED;
                end
            end
            if (state == FINISHED || state == ERROR) begin
                done <= 1;
                if (state == ERROR)
                    error <= 1;
            end
            if (next_state == FINISHED || next_state == ERROR) begin
                // Stay in done state until reset
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start)
                    next_state = PARSE;
                else
                    next_state = IDLE;
            end
            PARSE: begin
                // State transitions handled in sequential logic
                if (char_idx >= MAX_INPUT_LEN && !in_token)
                    next_state = FINISHED;
            end
            FINISHED: next_state = FINISHED;
            ERROR: next_state = ERROR;
            default: next_state = IDLE;
        endcase
    end

endmodule

module tuple_list_counter (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] tuple_data,  // 8-bit vector where each bit represents a list (1) or non-list (0)
    output reg [3:0] result,
    output reg done
);

// State machine to count number of lists in tuple
// Fixed constraint: maximum 8 elements in tuple

reg [3:0] count_reg;       // Counter for lists
reg [2:0] index;           // Current element index (0-7)
reg [1:0] state;           // State machine

// State definitions
localparam IDLE = 2'b00;
localparam COUNTING = 2'b01;
localparam COMPLETE = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        result <= 4'b0;
        done <= 1'b0;
        state <= IDLE;
        count_reg <= 4'b0;
        index <= 3'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                count_reg <= 4'b0;
                index <= 3'b0;

                if (start) begin
                    state <= COUNTING;
                end
            end

            COUNTING: begin
                // Check if current element is a list (bit = 1)
                if (tuple_data[index]) begin
                    count_reg <= count_reg + 1'b1;
                end

                // Move to next element
                if (index < 3'b111) begin
                    index <= index + 1'b1;
                end else begin
                    state <= COMPLETE;
                end
            end

            COMPLETE: begin
                result <= count_reg;
                done <= 1'b1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module find_single_element (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] len,           // Number of valid elements (1-8)
    output reg [7:0] result,
    output reg done
);

    // State machine states
    reg [1:0] state;
    reg [3:0] idx;
    reg [7:0] xor_accum;

    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 8'b0;
            done <= 1'b0;
            idx <= 4'b0;
            xor_accum <= 8'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPUTE;
                        idx <= 4'b0;
                        xor_accum <= 8'b0;
                    end
                end

                COMPUTE: begin
                    if (idx < len) begin
                        // XOR with current element based on index
                        case (idx)
                            4'd0: xor_accum <= xor_accum ^ arr_0;
                            4'd1: xor_accum <= xor_accum ^ arr_1;
                            4'd2: xor_accum <= xor_accum ^ arr_2;
                            4'd3: xor_accum <= xor_accum ^ arr_3;
                            4'd4: xor_accum <= xor_accum ^ arr_4;
                            4'd5: xor_accum <= xor_accum ^ arr_5;
                            4'd6: xor_accum <= xor_accum ^ arr_6;
                            4'd7: xor_accum <= xor_accum ^ arr_7;
                            default: xor_accum <= xor_accum;
                        endcase
                        idx <= idx + 1'b1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    result <= xor_accum;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module tuple_intersection (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input tuples: 2 elements of 8 bits each
    // We receive 4 tuples from test_list1 and 4 from test_list2
    // Using individual ports for inputs
    input wire [7:0] list1_a_0, list1_b_0,
    input wire [7:0] list1_a_1, list1_b_1,
    input wire [7:0] list1_a_2, list1_b_2,
    input wire [7:0] list1_a_3, list1_b_3,

    input wire [7:0] list2_a_0, list2_b_0,
    input wire [7:0] list2_a_1, list2_b_1,
    input wire [7:0] list2_a_2, list2_b_2,
    input wire [7:0] list2_a_3, list2_b_3,

    // Number of valid tuples in each list (1-4)
    input wire [2:0] len1,
    input wire [2:0] len2,

    // Output matches: up to 4 matches
    // Each match is a normalized tuple (min, max)
    output reg [7:0] match_a_0, match_b_0,
    output reg [7:0] match_a_1, match_b_1,
    output reg [7:0] match_a_2, match_b_2,
    output reg [7:0] match_a_3, match_b_3,
    output reg [2:0] match_count,

    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam NORMALIZE_LIST1 = 2'b01;
    localparam SEARCH_LIST2 = 2'b10;
    localparam FINISH = 2'b11;

    reg [1:0] state;
    reg [2:0] idx1;
    reg [2:0] idx2;
    reg [2:0] match_idx;

    // Storage for normalized list1
    reg [7:0] norm1_a [0:3];
    reg [7:0] norm1_b [0:3];
    reg valid1 [0:3];

    // Temporary normalization
    reg [7:0] temp_a, temp_b;
    reg [7:0] cur_a, cur_b;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            match_count <= 0;
            idx1 <= 0;
            idx2 <= 0;
            match_idx <= 0;
            for (i = 0; i < 4; i = i + 1) begin
                valid1[i] <= 0;
                norm1_a[i] <= 0;
                norm1_b[i] <= 0;
            end
            match_a_0 <= 0; match_b_0 <= 0;
            match_a_1 <= 0; match_b_1 <= 0;
            match_a_2 <= 0; match_b_2 <= 0;
            match_a_3 <= 0; match_b_3 <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= NORMALIZE_LIST1;
                        idx1 <= 0;
                        match_count <= 0;
                        match_idx <= 0;
                    end
                end

                NORMALIZE_LIST1: begin
                    if (idx1 < len1 && idx1 < 4) begin
                        // Normalize current tuple (swap if needed)
                        case (idx1)
                            0: begin cur_a <= list1_a_0; cur_b <= list1_b_0; end
                            1: begin cur_a <= list1_a_1; cur_b <= list1_b_1; end
                            2: begin cur_a <= list1_a_2; cur_b <= list1_b_2; end
                            3: begin cur_a <= list1_a_3; cur_b <= list1_b_3; end
                        endcase

                        // Store normalized (min, max)
                        if (cur_a <= cur_b) begin
                            norm1_a[idx1] <= cur_a;
                            norm1_b[idx1] <= cur_b;
                        end else begin
                            norm1_a[idx1] <= cur_b;
                            norm1_b[idx1] <= cur_a;
                        end
                        valid1[idx1] <= 1;
                        idx1 <= idx1 + 1;
                    end else begin
                        state <= SEARCH_LIST2;
                        idx1 <= 0;
                        idx2 <= 0;
                    end
                end

                SEARCH_LIST2: begin
                    if (idx2 < len2 && idx2 < 4) begin
                        // Get and normalize current list2 tuple
                        case (idx2)
                            0: begin temp_a <= list2_a_0; temp_b <= list2_b_0; end
                            1: begin temp_a <= list2_a_1; temp_b <= list2_b_1; end
                            2: begin temp_a <= list2_a_2; temp_b <= list2_b_2; end
                            3: begin temp_a <= list2_a_3; temp_b <= list2_b_3; end
                        endcase

                        // Compare with all valid list1 tuples
                        if (temp_a > temp_b) begin
                            // Swap for comparison
                            cur_a <= temp_b;
                            cur_b <= temp_a;
                        end else begin
                            cur_a <= temp_a;
                            cur_b <= temp_b;
                        end

                        // Check match (need one cycle for comparison)
                        idx1 <= 0;
                        state <= SEARCH_LIST2; // Stay, but will move to next on next cycle

                        // We need an intermediate state for comparison
                        // For simplicity, do inline comparison and register match
                        if (match_idx < 4 && valid1[0] && ((norm1_a[0] == temp_a && norm1_b[0] == temp_b) || 
                            (norm1_a[0] == temp_b && norm1_b[0] == temp_a))) begin
                            match_a_0 <= cur_a; match_b_0 <= cur_b; match_idx <= match_idx + 1; match_count <= match_count + 1;
                        end else if (match_idx < 4 && valid1[1] && ((norm1_a[1] == temp_a && norm1_b[1] == temp_b) || 
                            (norm1_a[1] == temp_b && norm1_b[1] == temp_a))) begin
                            match_a_1 <= cur_a; match_b_1 <= cur_b; match_idx <= match_idx + 1; match_count <= match_count + 1;
                        end else if (match_idx < 4 && valid1[2] && ((norm1_a[2] == temp_a && norm1_b[2] == temp_b) || 
                            (norm1_a[2] == temp_b && norm1_b[2] == temp_a))) begin
                            match_a_2 <= cur_a; match_b_2 <= cur_b; match_idx <= match_idx + 1; match_count <= match_count + 1;
                        end else if (match_idx < 4 && valid1[3] && ((norm1_a[3] == temp_a && norm1_b[3] == temp_b) || 
                            (norm1_a[3] == temp_b && norm1_b[3] == temp_a))) begin
                            match_a_3 <= cur_a; match_b_3 <= cur_b; match_idx <= match_idx + 1; match_count <= match_count + 1;
                        end

                        idx2 <= idx2 + 1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module top (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [2:0] n,
    output reg [7:0] result_0,
    output reg [7:0] result_1,
    output reg [7:0] result_2,
    output reg [7:0] result_3,
    output reg [7:0] result_4,
    output reg done
);

    // Maximum constants
    parameter MAX_SIZE = 8;
    parameter MAX_N = 5;

    // Internal state registers
    reg [7:0] sorted [0:MAX_SIZE-1];
    reg [3:0] idx;
    reg [3:0] comp_idx;
    reg [2:0] output_idx;
    reg processing;
    reg outputting;

    // Combinational comparison result
    wire swap;
    assign swap = (sorted[comp_idx] < sorted[comp_idx+1]);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            idx <= 4'd0;
            comp_idx <= 4'd0;
            output_idx <= 3'd0;
            processing <= 1'b0;
            outputting <= 1'b0;
            done <= 1'b0;
            result_0 <= 8'd0;
            result_1 <= 8'd0;
            result_2 <= 8'd0;
            result_3 <= 8'd0;
            result_4 <= 8'd0;
            // Initialize sorted array to zeros
            sorted[0] <= 8'd0;
            sorted[1] <= 8'd0;
            sorted[2] <= 8'd0;
            sorted[3] <= 8'd0;
            sorted[4] <= 8'd0;
            sorted[5] <= 8'd0;
            sorted[6] <= 8'd0;
            sorted[7] <= 8'd0;
        end else if (start && !processing && !outputting) begin
            // Load input array and start processing
            sorted[0] <= arr_0;
            sorted[1] <= arr_1;
            sorted[2] <= arr_2;
            sorted[3] <= arr_3;
            sorted[4] <= arr_4;
            sorted[5] <= arr_5;
            sorted[6] <= arr_6;
            sorted[7] <= arr_7;
            idx <= 4'd0;
            comp_idx <= 4'd0;
            processing <= 1'b1;
            outputting <= 1'b0;
            done <= 1'b0;
        end else if (processing) begin
            // Bubble sort: bubble largest elements to the end
            if (comp_idx < 4'd7) begin
                if (swap) begin
                    // Swap elements
                    sorted[comp_idx] <= sorted[comp_idx+1];
                    sorted[comp_idx+1] <= sorted[comp_idx];
                end
                comp_idx <= comp_idx + 1'b1;
            end else begin
                // End of one pass
                comp_idx <= 4'd0;
                if (idx < 4'd7) begin
                    idx <= idx + 1'b1;
                end else begin
                    // Sorting complete, prepare for output
                    processing <= 1'b0;
                    outputting <= 1'b1;
                    output_idx <= 3'd0;
                end
            end
        end else if (outputting) begin
            // Output the n largest values (from the end of sorted array)
            if (output_idx < n && output_idx < MAX_N) begin
                case (output_idx)
                    3'd0: result_0 <= sorted[MAX_SIZE - 1];
                    3'd1: result_1 <= sorted[MAX_SIZE - 2];
                    3'd2: result_2 <= sorted[MAX_SIZE - 3];
                    3'd3: result_3 <= sorted[MAX_SIZE - 4];
                    3'd4: result_4 <= sorted[MAX_SIZE - 5];
                    default: begin
                        result_0 <= result_0;
                        result_1 <= result_1;
                        result_2 <= result_2;
                        result_3 <= result_3;
                        result_4 <= result_4;
                    end
                endcase
                output_idx <= output_idx + 1'b1;
            end else begin
                // Output complete
                done <= 1'b1;
                outputting <= 1'b0;
            end
        end else begin
            done <= 1'b0;
        end
    end

endmodule

module swap_numbers(
    input clk,
    input rst_n,
    input start,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out_first,
    output reg [7:0] out_second,
    output reg done
);

// Combinational swap logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        out_first <= 8'd0;
        out_second <= 8'd0;
        done <= 1'b0;
    end else if (start) begin
        // Swap: output (b, a) - second number first, then first number
        out_first <= b;
        out_second <= a;
        done <= 1'b1;
    end else begin
        done <= 1'b0;
    end
end

endmodule

module string_replace (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,      // Current character to check
    input wire [7:0] target_char,   // Character to replace
    input wire [7:0] replace_char,  // Replacement character
    input wire valid_in,            // Valid input character
    input wire end_of_string,       // Signal end of string
    output reg [7:0] char_out,      // Output character
    output reg valid_out,           // Valid output
    output reg done                 // Completion signal
);

    // Internal state
    reg processing;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            char_out <= 8'b0;
            valid_out <= 1'b0;
            done <= 1'b0;
            processing <= 1'b0;
        end else begin
            if (start && !processing) begin
                processing <= 1'b1;
                done <= 1'b0;
                valid_out <= 1'b0;
            end else if (processing) begin
                if (valid_in) begin
                    // Replace if character matches target
                    if (char_in == target_char) begin
                        char_out <= replace_char;
                    end else begin
                        char_out <= char_in;
                    end
                    valid_out <= 1'b1;
                end else if (end_of_string) begin
                    // End of string reached
                    valid_out <= 1'b0;
                    done <= 1'b1;
                    processing <= 1'b0;
                end
            end
        end
    end

endmodule

module equal_tuples_check #(
  parameter NUM_TUPLES = 4,  // Maximum number of tuples
  parameter MAX_TUPLE_LEN = 8  // Maximum elements per tuple
) (
  input wire clk,
  input wire rst_n,
  input wire start,

  // Individual length inputs for each tuple
  // Each tuple length is 4 bits (0-15)
  input wire [3:0] tuple_len_0,
  input wire [3:0] tuple_len_1,
  input wire [3:0] tuple_len_2,
  input wire [3:0] tuple_len_3,
  input wire [3:0] tuple_len_4,
  input wire [3:0] tuple_len_5,
  input wire [3:0] tuple_len_6,
  input wire [3:0] tuple_len_7,

  // Number of valid tuples (1-8)
  input wire [3:0] num_tuples,

  output reg result,  // 1 if all equal, 0 otherwise
  output reg done
);

  // Internal state
  reg [2:0] state;
  reg [3:0] reference_len;
  reg [3:0] compare_idx;

  // State encoding
  localparam IDLE = 3'd0;
  localparam LOAD_REF = 3'd1;
  localparam COMPARE = 3'd2;
  localparam FINISHED = 3'd3;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      result <= 0;
      done <= 0;
      reference_len <= 0;
      compare_idx <= 0;
    end else begin
      case (state)
        IDLE: begin
          done <= 0;
          if (start) begin
            if (num_tuples == 0 || num_tuples == 1) begin
              // Empty or single tuple always "equal"
              result <= 1;
              state <= FINISHED;
            end else begin
              state <= LOAD_REF;
              compare_idx <= 0;
            end
          end
        end

        LOAD_REF: begin
          // Load reference length from first tuple
          case (compare_idx)
            4'd0: reference_len <= tuple_len_0;
            4'd1: reference_len <= tuple_len_1;
            4'd2: reference_len <= tuple_len_2;
            4'd3: reference_len <= tuple_len_3;
            4'd4: reference_len <= tuple_len_4;
            4'd5: reference_len <= tuple_len_5;
            4'd6: reference_len <= tuple_len_6;
            4'd7: reference_len <= tuple_len_7;
            default: reference_len <= tuple_len_0;
          endcase
          compare_idx <= compare_idx + 1;
          state <= COMPARE;
          result <= 1; // Assume equal until proven otherwise
        end

        COMPARE: begin
          // Compare current tuple length with reference
          if (compare_idx < num_tuples) begin
            // Get current tuple length
            reg [3:0] current_len;
            case (compare_idx)
              4'd0: current_len = tuple_len_0;
              4'd1: current_len = tuple_len_1;
              4'd2: current_len = tuple_len_2;
              4'd3: current_len = tuple_len_3;
              4'd4: current_len = tuple_len_4;
              4'd5: current_len = tuple_len_5;
              4'd6: current_len = tuple_len_6;
              4'd7: current_len = tuple_len_7;
              default: current_len = 4'd0;
            endcase

            if (current_len != reference_len) begin
              result <= 0;
              state <= FINISHED;
            end else begin
              compare_idx <= compare_idx + 1;
              if (compare_idx >= num_tuples - 1) begin
                state <= FINISHED;
              end
            end
          end else begin
            state <= FINISHED;
          end
        end

        FINISHED: begin
          done <= 1;
          if (!start) begin
            state <= IDLE;
          end
        end

        default: state <= IDLE;
      endcase
    end
  end

endmodule

module find_minimum_tuple (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_second_0,  // Second value of tuple 0
    input wire [7:0] arr_second_1,  // Second value of tuple 1
    input wire [7:0] arr_second_2,  // Second value of tuple 2
    input wire [7:0] arr_second_3,  // Second value of tuple 3
    input wire [7:0] arr_second_4,  // Second value of tuple 4
    input wire [7:0] arr_second_5,  // Second value of tuple 5
    input wire [7:0] arr_second_6,  // Second value of tuple 6
    input wire [7:0] arr_second_7,  // Second value of tuple 7
    input wire [7:0] arr_first_0,   // First value of tuple 0 (identifier)
    input wire [7:0] arr_first_1,   // First value of tuple 1
    input wire [7:0] arr_first_2,   // First value of tuple 2
    input wire [7:0] arr_first_3,   // First value of tuple 3
    input wire [7:0] arr_first_4,   // First value of tuple 4
    input wire [7:0] arr_first_5,   // First value of tuple 5
    input wire [7:0] arr_first_6,   // First value of tuple 6
    input wire [7:0] arr_first_7,   // First value of tuple 7
    input wire [3:0] num_tuples,    // Number of valid tuples (1-8)
    output reg [7:0] result_first,
    output reg done,
    output reg valid
);

    // State machine states
    reg [3:0] state;
    reg [3:0] idx;
    reg [7:0] min_second;
    reg [7:0] result_first_reg;
    reg [7:0] next_min_second;
    reg [7:0] next_result_first;

    // State definitions
    localparam IDLE = 4'd0;
    localparam INIT = 4'd1;
    localparam COMPARE = 4'd2;
    localparam UPDATE = 4'd3;
    localparam DONE = 4'd4;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 4'd0;
            min_second <= 8'hFF;
            result_first <= 8'd0;
            done <= 1'b0;
            valid <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    valid <= 1'b0;
                    if (start) begin
                        state <= INIT;
                        idx <= 4'd0;
                        min_second <= 8'hFF;
                    end
                end

                INIT: begin
                    // Initialize with first tuple
                    if (num_tuples > 0) begin
                        min_second <= arr_second_0;
                        result_first <= arr_first_0;
                        idx <= 4'd1;
                        state <= (num_tuples > 1) ? COMPARE : DONE;
                    end else begin
                        state <= DONE;
                        valid <= 1'b0;
                    end
                end

                COMPARE: begin
                    // Compare current tuple with minimum
                    if (idx < num_tuples) begin
                        case (idx)
                            4'd1: begin
                                if (arr_second_1 < min_second) begin
                                    next_min_second <= arr_second_1;
                                    next_result_first <= arr_first_1;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            4'd2: begin
                                if (arr_second_2 < min_second) begin
                                    next_min_second <= arr_second_2;
                                    next_result_first <= arr_first_2;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            4'd3: begin
                                if (arr_second_3 < min_second) begin
                                    next_min_second <= arr_second_3;
                                    next_result_first <= arr_first_3;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            4'd4: begin
                                if (arr_second_4 < min_second) begin
                                    next_min_second <= arr_second_4;
                                    next_result_first <= arr_first_4;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            4'd5: begin
                                if (arr_second_5 < min_second) begin
                                    next_min_second <= arr_second_5;
                                    next_result_first <= arr_first_5;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            4'd6: begin
                                if (arr_second_6 < min_second) begin
                                    next_min_second <= arr_second_6;
                                    next_result_first <= arr_first_6;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            4'd7: begin
                                if (arr_second_7 < min_second) begin
                                    next_min_second <= arr_second_7;
                                    next_result_first <= arr_first_7;
                                end else begin
                                    next_min_second <= min_second;
                                    next_result_first <= result_first;
                                end
                            end
                            default: begin
                                next_min_second <= min_second;
                                next_result_first <= result_first;
                            end
                        endcase
                        state <= UPDATE;
                    end else begin
                        state <= DONE;
                    end
                end

                UPDATE: begin
                    min_second <= next_min_second;
                    result_first <= next_result_first;
                    idx <= idx + 1;
                    state <= COMPARE;
                end

                DONE: begin
                    done <= 1'b1;
                    valid <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module parity_calculator (
    input  [31:0] num,      // 32-bit input number
    output        parity    // 1 if odd parity (odd number of 1s), 0 if even parity
);

    // Combinational logic to compute parity using XOR reduction tree
    // This implements the algorithm: y = x ^ (x>>1) ^ (x>>2) ^ (x>>4) ... then check LSB

    wire [31:0] stage1;
    wire [31:0] stage2;
    wire [31:0] stage3;
    wire [31:0] stage4;
    wire [31:0] stage5;

    assign stage1 = num ^ (num >> 1);
    assign stage2 = stage1 ^ (stage1 >> 2);
    assign stage3 = stage2 ^ (stage2 >> 4);
    assign stage4 = stage3 ^ (stage3 >> 8);
    assign stage5 = stage4 ^ (stage4 >> 16);

    // The LSB of the final result contains the parity
    // 1 = odd number of 1s (odd parity)
    // 0 = even number of 1s (even parity)
    assign parity = stage5[0];

endmodule

module spec_list_subtractor(
    // Clock and reset
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input arrays (8 elements, 8-bit each)
    input wire [7:0] arr1_0, arr1_1, arr1_2, arr1_3,
    input wire [7:0] arr1_4, arr1_5, arr1_6, arr1_7,
    input wire [7:0] arr2_0, arr2_1, arr2_2, arr2_3,
    input wire [7:0] arr2_4, arr2_5, arr2_6, arr2_7,

    // Length control (1-8 elements)
    input wire [3:0] len,

    // Output array (9-bit signed results)
    output reg [8:0] result_0, result_1, result_2, result_3,
    output reg [8:0] result_4, result_5, result_6, result_7,

    // Status
    output reg done
);

// Combinational implementation - element-wise subtraction
// Result width = 9 bits to handle signed 8-bit subtraction
// (range: -255 to +255)

always @(*) begin
    // Default outputs
    result_0 = 9'sd0;
    result_1 = 9'sd0;
    result_2 = 9'sd0;
    result_3 = 9'sd0;
    result_4 = 9'sd0;
    result_5 = 9'sd0;
    result_6 = 9'sd0;
    result_7 = 9'sd0;

    // Perform subtraction for valid elements
    if (start && len > 0) begin
        result_0 = {1'b0, arr1_0} - {1'b0, arr2_0};
        if (len > 1) result_1 = {1'b0, arr1_1} - {1'b0, arr2_1};
        if (len > 2) result_2 = {1'b0, arr1_2} - {1'b0, arr2_2};
        if (len > 3) result_3 = {1'b0, arr1_3} - {1'b0, arr2_3};
        if (len > 4) result_4 = {1'b0, arr1_4} - {1'b0, arr2_4};
        if (len > 5) result_5 = {1'b0, arr1_5} - {1'b0, arr2_5};
        if (len > 6) result_6 = {1'b0, arr1_6} - {1'b0, arr2_6};
        if (len > 7) result_7 = {1'b0, arr1_7} - {1'b0, arr2_7};
    end
end

// Done signal generation (combinational)
always @(*) begin
    done = start && (len > 0);
end

endmodule

module shell_sort (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    output reg [7:0] sorted_0,
    output reg [7:0] sorted_1,
    output reg [7:0] sorted_2,
    output reg [7:0] sorted_3,
    output reg [7:0] sorted_4,
    output reg [7:0] sorted_5,
    output reg [7:0] sorted_6,
    output reg [7:0] sorted_7,
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam LOAD = 3'b001;
    localparam GAP_LOOP = 3'b010;
    localparam INNER_LOOP = 3'b011;
    localparam COMPARE = 3'b100;
    localparam SHIFT = 3'b101;
    localparam INSERT = 3'b110;
    localparam NEXT_I = 3'b111;

    // Internal registers
    reg [2:0] state;
    reg [2:0] next_state;
    reg [7:0] data [0:7];  // Working memory
    reg [2:0] gap;          // Gap size (0-4)
    reg [2:0] i;            // Outer loop index
    reg [2:0] j;            // Inner loop index
    reg [7:0] current_item; // Temp for insertion
    reg [2:0] gap_next;     // Next gap value

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 1'b0;
        end else begin
            state <= next_state;
            done <= (state == NEXT_I && i >= 8 && gap == 0) ? 1'b1 : 1'b0;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: next_state = start ? LOAD : IDLE;
            LOAD: next_state = GAP_LOOP;
            GAP_LOOP: next_state = (gap > 0) ? INNER_LOOP : IDLE;
            INNER_LOOP: next_state = (i < 8) ? COMPARE : NEXT_I;
            COMPARE: next_state = (j >= gap && data[j-gap] > current_item) ? SHIFT : INSERT;
            SHIFT: next_state = COMPARE;
            INSERT: next_state = NEXT_I;
            NEXT_I: begin
                if (i + 1 < 8) next_state = INNER_LOOP;
                else next_state = GAP_LOOP;
            end
            default: next_state = IDLE;
        endcase
    end

    // Data path
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            gap <= 3'd4;
            i <= 3'd0;
            j <= 3'd0;
            current_item <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    gap <= 3'd4;
                    i <= 3'd0;
                end
                LOAD: begin
                    data[0] <= arr_0;
                    data[1] <= arr_1;
                    data[2] <= arr_2;
                    data[3] <= arr_3;
                    data[4] <= arr_4;
                    data[5] <= arr_5;
                    data[6] <= arr_6;
                    data[7] <= arr_7;
                end
                GAP_LOOP: begin
                    gap <= gap >> 1;
                    i <= gap >> 1;
                end
                INNER_LOOP: begin
                    if (i < 8) begin
                        current_item <= data[i];
                        j <= i;
                    end
                end
                SHIFT: begin
                    data[j] <= data[j - gap];
                    j <= j - gap;
                end
                INSERT: begin
                    data[j] <= current_item;
                end
                NEXT_I: begin
                    i <= i + 1;
                end
            endcase
        end
    end

    // Output assignment
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sorted_0 <= 8'd0;
            sorted_1 <= 8'd0;
            sorted_2 <= 8'd0;
            sorted_3 <= 8'd0;
            sorted_4 <= 8'd0;
            sorted_5 <= 8'd0;
            sorted_6 <= 8'd0;
            sorted_7 <= 8'd0;
        end else if (state == NEXT_I && i >= 8 && gap == 0) begin
            sorted_0 <= data[0];
            sorted_1 <= data[1];
            sorted_2 <= data[2];
            sorted_3 <= data[3];
            sorted_4 <= data[4];
            sorted_5 <= data[5];
            sorted_6 <= data[6];
            sorted_7 <= data[7];
        end
    end

endmodule

module max_tuple_elements (
    // Clock and reset
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input tuples: 4 rows x 2 columns of 8-bit values
    // Input format: arr_0_0, arr_0_1, arr_1_0, arr_1_1, ... arr_3_1
    input wire [7:0] arr_0_0, arr_0_1,
    input wire [7:0] arr_1_0, arr_1_1,
    input wire [7:0] arr_2_0, arr_2_1,
    input wire [7:0] arr_3_0, arr_3_1,

    // Second tuple (parallel inputs)
    input wire [7:0] brr_0_0, brr_0_1,
    input wire [7:0] brr_1_0, brr_1_1,
    input wire [7:0] brr_2_0, brr_2_1,
    input wire [7:0] brr_3_0, brr_3_1,

    // Outputs: 4 rows x 2 columns of maximized values
    output reg [7:0] result_0_0, result_0_1,
    output reg [7:0] result_1_0, result_1_1,
    output reg [7:0] result_2_0, result_2_1,
    output reg [7:0] result_3_0, result_3_1,

    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam COMPLETE = 2'b10;

    reg [1:0] state, next_state;

    // Combinational max logic (single cycle for all elements)
    wire [7:0] max_0_0, max_0_1;
    wire [7:0] max_1_0, max_1_1;
    wire [7:0] max_2_0, max_2_1;
    wire [7:0] max_3_0, max_3_1;

    assign max_0_0 = (arr_0_0 > brr_0_0) ? arr_0_0 : brr_0_0;
    assign max_0_1 = (arr_0_1 > brr_0_1) ? arr_0_1 : brr_0_1;
    assign max_1_0 = (arr_1_0 > brr_1_0) ? arr_1_0 : brr_1_0;
    assign max_1_1 = (arr_1_1 > brr_1_1) ? arr_1_1 : brr_1_1;
    assign max_2_0 = (arr_2_0 > brr_2_0) ? arr_2_0 : brr_2_0;
    assign max_2_1 = (arr_2_1 > brr_2_1) ? arr_2_1 : brr_2_1;
    assign max_3_0 = (arr_3_0 > brr_3_0) ? arr_3_0 : brr_3_0;
    assign max_3_1 = (arr_3_1 > brr_3_1) ? arr_3_1 : brr_3_1;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: next_state = start ? COMPUTE : IDLE;
            COMPUTE: next_state = COMPLETE;
            COMPLETE: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result_0_0 <= 8'b0; result_0_1 <= 8'b0;
            result_1_0 <= 8'b0; result_1_1 <= 8'b0;
            result_2_0 <= 8'b0; result_2_1 <= 8'b0;
            result_3_0 <= 8'b0; result_3_1 <= 8'b0;
            done <= 1'b0;
        end else begin
            case (state)
                COMPUTE: begin
                    result_0_0 <= max_0_0;
                    result_0_1 <= max_0_1;
                    result_1_0 <= max_1_0;
                    result_1_1 <= max_1_1;
                    result_2_0 <= max_2_0;
                    result_2_1 <= max_2_1;
                    result_3_0 <= max_3_0;
                    result_3_1 <= max_3_1;
                    done <= 1'b1;
                end
                COMPLETE, IDLE: begin
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

module cube_volume(
    input [7:0] side_length,
    output reg [23:0] volume
);

// Calculate volume = side_length³
// side_length: 8-bit unsigned (0-255)
// volume: 24-bit unsigned (max 255³ = 16,581,375 fits in 24 bits)
// Combinational logic

always @(*) begin
    volume = side_length * side_length * side_length;
end

endmodule

// INTERFACE SPECIFICATION:
// Inputs:
//   - side_length [7:0] : 8-bit unsigned integer representing cube side length
// Outputs:
//   - volume [23:0] : 24-bit unsigned integer representing cube volume
// Timing: Combinational (output updates immediately when input changes)
// Max value: side_length=255 produces volume=16,581,375 (within 24-bit range)

module large_product #(
    parameter LIST_SIZE = 8,    // Maximum size of input lists
    parameter DATA_WIDTH = 8,   // Width of each number
    parameter N_WIDTH = 4,      // Width of N parameter (max 16)
    parameter RESULT_WIDTH = 16 // Width of product result
  ) (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input lists - using individual ports for clarity
    // Each list has up to 8 elements, valid elements indicated by len
    input wire [DATA_WIDTH-1:0] nums1_0, nums1_1, nums1_2, nums1_3,
    input wire [DATA_WIDTH-1:0] nums1_4, nums1_5, nums1_6, nums1_7,
    input wire [DATA_WIDTH-1:0] nums2_0, nums2_1, nums2_2, nums2_3,
    input wire [DATA_WIDTH-1:0] nums2_4, nums2_5, nums2_6, nums2_7,

    input wire [N_WIDTH-1:0] len1,  // Number of valid elements in nums1
    input wire [N_WIDTH-1:0] len2,  // Number of valid elements in nums2  
    input wire [N_WIDTH-1:0] N,     // Number of largest products to return

    // Output ports - top N products in descending order
    output reg [RESULT_WIDTH-1:0] products_0,
    output reg [RESULT_WIDTH-1:0] products_1,
    output reg [RESULT_WIDTH-1:0] products_2,
    output reg [RESULT_WIDTH-1:0] products_3,
    output reg [RESULT_WIDTH-1:0] products_4,
    output reg [RESULT_WIDTH-1:0] products_5,
    output reg [RESULT_WIDTH-1:0] products_6,
    output reg [RESULT_WIDTH-1:0] products_7,

    output reg done
  );

  // Maximum products: 8x8 = 64 products
  localparam MAX_PRODUCTS = LIST_SIZE * LIST_SIZE;
  localparam LOG_MAX_PRODUCTS = 6; // ceil(log2(64))

  // State machine states
  typedef enum logic [2:0] {
    IDLE,
    GENERATE_PRODUCTS,
    SORT_PRODUCTS,
    OUTPUT_RESULTS
  } state_t;

  state_t current_state, next_state;

  // Storage for all generated products
  reg [RESULT_WIDTH-1:0] product_array [0:MAX_PRODUCTS-1];

  // Working array for sorting (also holds final sorted results)
  reg [RESULT_WIDTH-1:0] sorted_array [0:MAX_PRODUCTS-1];

  // Counters
  reg [3:0] i1, i2;  // Iterators for product generation
  reg [5:0] prod_idx; // Index for product storage
  reg [3:0] sort_pass; // Sorting pass counter
  reg [3:0] output_idx; // Output index counter
  reg [N_WIDTH-1:0] valid_N; // Clamped N value

  // Combinational product calculation
  wire [RESULT_WIDTH-1:0] current_product;
  assign current_product = nums1_0 * nums2_0; // Placeholder, will be dynamic

  // Control signals
  reg [3:0] num_to_generate; // Number of products to generate
  reg [5:0] num_to_sort;     // Number of elements to sort

  integer j;

  // State transition and sequential logic
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      current_state <= IDLE;
      products_0 <= 0; products_1 <= 0; products_2 <= 0; products_3 <= 0;
      products_4 <= 0; products_5 <= 0; products_6 <= 0; products_7 <= 0;
      done <= 0;
      i1 <= 0; i2 <= 0; prod_idx <= 0; sort_pass <= 0; output_idx <= 0;
      valid_N <= 0;
      // Clear product arrays
      for (j = 0; j < MAX_PRODUCTS; j = j + 1) begin
        product_array[j] <= 0;
        sorted_array[j] <= 0;
      end
    end else begin
      current_state <= next_state;

      case (current_state)
        IDLE: begin
          done <= 0;
          if (start) begin
            i1 <= 0; i2 <= 0; prod_idx <= 0; sort_pass <= 0; output_idx <= 0;
            // Clamp N to valid range and max products
            valid_N <= (N > MAX_PRODUCTS) ? MAX_PRODUCTS : N;
          end
        end

        GENERATE_PRODUCTS: begin
          // Store product for current i1, i2
          case (i1)
            0: case (i2)
              0: product_array[prod_idx] <= nums1_0 * nums2_0;
              1: product_array[prod_idx] <= nums1_0 * nums2_1;
              2: product_array[prod_idx] <= nums1_0 * nums2_2;
              3: product_array[prod_idx] <= nums1_0 * nums2_3;
              4: product_array[prod_idx] <= nums1_0 * nums2_4;
              5: product_array[prod_idx] <= nums1_0 * nums2_5;
              6: product_array[prod_idx] <= nums1_0 * nums2_6;
              7: product_array[prod_idx] <= nums1_0 * nums2_7;
            endcase
            1: case (i2)
              0: product_array[prod_idx] <= nums1_1 * nums2_0;
              1: product_array[prod_idx] <= nums1_1 * nums2_1;
              2: product_array[prod_idx] <= nums1_1 * nums2_2;
              3: product_array[prod_idx] <= nums1_1 * nums2_3;
              4: product_array[prod_idx] <= nums1_1 * nums2_4;
              5: product_array[prod_idx] <= nums1_1 * nums2_5;
              6: product_array[prod_idx] <= nums1_1 * nums2_6;
              7: product_array[prod_idx] <= nums1_1 * nums2_7;
            endcase
            2: case (i2)
              0: product_array[prod_idx] <= nums1_2 * nums2_0;
              1: product_array[prod_idx] <= nums1_2 * nums2_1;
              2: product_array[prod_idx] <= nums1_2 * nums2_2;
              3: product_array[prod_idx] <= nums1_2 * nums2_3;
              4: product_array[prod_idx] <= nums1_2 * nums2_4;
              5: product_array[prod_idx] <= nums1_2 * nums2_5;
              6: product_array[prod_idx] <= nums1_2 * nums2_6;
              7: product_array[prod_idx] <= nums1_2 * nums2_7;
            endcase
            3: case (i2)
              0: product_array[prod_idx] <= nums1_3 * nums2_0;
              1: product_array[prod_idx] <= nums1_3 * nums2_1;
              2: product_array[prod_idx] <= nums1_3 * nums2_2;
              3: product_array[prod_idx] <= nums1_3 * nums2_3;
              4: product_array[prod_idx] <= nums1_3 * nums2_4;
              5: product_array[prod_idx] <= nums1_3 * nums2_5;
              6: product_array[prod_idx] <= nums1_3 * nums2_6;
              7: product_array[prod_idx] <= nums1_3 * nums2_7;
            endcase
            4: case (i2)
              0: product_array[prod_idx] <= nums1_4 * nums2_0;
              1: product_array[prod_idx] <= nums1_4 * nums2_1;
              2: product_array[prod_idx] <= nums1_4 * nums2_2;
              3: product_array[prod_idx] <= nums1_4 * nums2_3;
              4: product_array[prod_idx] <= nums1_4 * nums2_4;
              5: product_array[prod_idx] <= nums1_4 * nums2_5;
              6: product_array[prod_idx] <= nums1_4 * nums2_6;
              7: product_array[prod_idx] <= nums1_4 * nums2_7;
            endcase
            5: case (i2)
              0: product_array[prod_idx] <= nums1_5 * nums2_0;
              1: product_array[prod_idx] <= nums1_5 * nums2_1;
              2: product_array[prod_idx] <= nums1_5 * nums2_2;
              3: product_array[prod_idx] <= nums1_5 * nums2_3;
              4: product_array[prod_idx] <= nums1_5 * nums2_4;
              5: product_array[prod_idx] <= nums1_5 * nums2_5;
              6: product_array[prod_idx] <= nums1_5 * nums2_6;
              7: product_array[prod_idx] <= nums1_5 * nums2_7;
            endcase
            6: case (i2)
              0: product_array[prod_idx] <= nums1_6 * nums2_0;
              1: product_array[prod_idx] <= nums1_6 * nums2_1;
              2: product_array[prod_idx] <= nums1_6 * nums2_2;
              3: product_array[prod_idx] <= nums1_6 * nums2_3;
              4: product_array[prod_idx] <= nums1_6 * nums2_4;
              5: product_array[prod_idx] <= nums1_6 * nums2_5;
              6: product_array[prod_idx] <= nums1_6 * nums2_6;
              7: product_array[prod_idx] <= nums1_6 * nums2_7;
            endcase
            7: case (i2)
              0: product_array[prod_idx] <= nums1_7 * nums2_0;
              1: product_array[prod_idx] <= nums1_7 * nums2_1;
              2: product_array[prod_idx] <= nums1_7 * nums2_2;
              3: product_array[prod_idx] <= nums1_7 * nums2_3;
              4: product_array[prod_idx] <= nums1_7 * nums2_4;
              5: product_array[prod_idx] <= nums1_7 * nums2_5;
              6: product_array[prod_idx] <= nums1_7 * nums2_6;
              7: product_array[prod_idx] <= nums1_7 * nums2_7;
            endcase
          endcase

          // Copy to sorted array initially
          sorted_array[prod_idx] <= product_array[prod_idx];

          // Increment counters
          prod_idx <= prod_idx + 1;
          i2 <= i2 + 1;
          if (i2 == len2 - 1) begin
            i2 <= 0;
            i1 <= i1 + 1;
          end
        end

        SORT_PRODUCTS: begin
          // Bubble sort pass - compare adjacent elements and swap if needed
          // We only sort the first num_to_sort elements
          if (sort_pass < num_to_sort - 1) begin
            // Perform comparison and potential swap
            if (sorted_array[sort_pass] < sorted_array[sort_pass + 1]) begin
              // Swap
              sorted_array[sort_pass] <= sorted_array[sort_pass + 1];
              sorted_array[sort_pass + 1] <= sorted_array[sort_pass];
            end
            sort_pass <= sort_pass + 1;
          end else if (sort_pass == num_to_sort - 1) begin
            // One full pass completed, check if we need another pass
            sort_pass <= 0;
            // Decrement counter for next pass - we need num_to_sort passes for full sort
            num_to_sort <= num_to_sort - 1;
            // If num_to_sort becomes 1 or less, sorting complete
          end
        end

        OUTPUT_RESULTS: begin
          // Output top N products in descending order
          if (output_idx < valid_N) begin
            case (output_idx)
              0: products_0 <= sorted_array[0];
              1: products_1 <= sorted_array[1];
              2: products_2 <= sorted_array[2];
              3: products_3 <= sorted_array[3];
              4: products_4 <= sorted_array[4];
              5: products_5 <= sorted_array[5];
              6: products_6 <= sorted_array[6];
              7: products_7 <= sorted_array[7];
            endcase
            output_idx <= output_idx + 1;
          end else begin
            done <= 1;
          end
        end
      endcase

      // Additional products to generate
      if (current_state == IDLE && start) begin
        num_to_generate <= len1 * len2;
        num_to_sort <= len1 * len2;
      end
    end
  end

  // Next state logic
  always @(*) begin
    next_state = current_state;
    case (current_state)
      IDLE: begin
        if (start && len1 > 0 && len2 > 0 && N > 0)
          next_state = GENERATE_PRODUCTS;
      end

      GENERATE_PRODUCTS: begin
        // Done when all products generated
        if (i1 >= len1 || (i1 == len1 - 1 && i2 >= len2)) begin
          next_state = SORT_PRODUCTS;
        end
      end

      SORT_PRODUCTS: begin
        // Done when sorting complete (num_to_sort becomes 1)
        if (num_to_sort <= 1) begin
          next_state = OUTPUT_RESULTS;
        end
      end

      OUTPUT_RESULTS: begin
        if (output_idx >= valid_N && !done) begin
          next_state = IDLE;
        end
      end

      default: next_state = IDLE;
    endcase
  end

endmodule

/*
COMB SORT IMPLEMENTATION IN VERILOG

Problem: Implement Comb Sort algorithm for small fixed-size arrays.

Adaptations for HDL:
- Maximum array size: 8 elements
- Data width: 8 bits per element (0-255 range)
- Gap shrink factor: 1.3 (implemented as integer division)
- Combinational logic with bounded iterations

Algorithm Overview:
1. Initialize gap = array_size
2. While gap > 1 or swapped:
   a. gap = gap / 1.3 (integer)
   b. For i from 0 to (array_size - gap):
      - Compare element[i] and element[i+gap]
      - Swap if out of order
   c. Track if any swap occurred

Interface Specification:

Inputs:
  - arr[0:7]   : 8-element input array, each 8-bit (unsigned)
                  Individual ports: arr_0, arr_1, ... arr_7
                  OR indexed: arr[0] to arr[7]

Outputs:
  - sorted[0:7]: 8-element sorted array, each 8-bit
                  Individual ports: sorted_0, sorted_1, ... sorted_7
                  OR indexed: sorted[0] to sorted[7]
  - done       : Single pulse when sorting complete (1 cycle)

Control Signals:
  - clk        : Clock for sequential operation
  - rst_n      : Active-low reset
  - start      : Start signal (pulse high for 1 cycle)

Behavior:
  1. On start pulse, load input array into internal buffer
  2. Perform comb sort algorithm (combinational per cycle)
  3. Assert done when sorted
  4. Output sorted array on sorted[] ports

Maximum Cycles: 64 (conservative bound for 8 elements)

Implementation Notes:
- Use combinational logic blocks inside sequential FSM
- Gap calculation: gap = gap * 13 / 10 (approximates /1.3)
- State machine: IDLE -> LOAD -> SORTING -> DONE
- Sorting state performs one pass per clock cycle
- Track swapped flag to detect completion
- Swap logic uses temporary registers

Example:
  Input:  arr = [5, 15, 37, 25, 79, 0, 0, 0]
  Output: sorted = [5, 15, 25, 37, 79, 0, 0, 0]
  done pulses high when complete.
*/

module comb_sort (
    // Clock and control
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input array (8 elements, 8-bit each)
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,

    // Output array (sorted)
    output reg [7:0] sorted_0,
    output reg [7:0] sorted_1,
    output reg [7:0] sorted_2,
    output reg [7:0] sorted_3,
    output reg [7:0] sorted_4,
    output reg [7:0] sorted_5,
    output reg [7:0] sorted_6,
    output reg [7:0] sorted_7,

    // Status
    output reg done
);

// Parameters
parameter NUM_ELEMENTS = 8;
parameter DATA_WIDTH = 8;
parameter MAX_CYCLES = 64;

// Internal memory for sorting
reg [7:0] buffer [0:7];

// State machine states
parameter STATE_IDLE = 2'b00;
parameter STATE_LOAD = 2'b01;
parameter STATE_SORT = 2'b10;
parameter STATE_DONE = 2'b11;

reg [1:0] state;
reg [1:0] next_state;

// Sorting variables
reg [7:0] gap;           // Current gap size
reg [7:0] next_gap;
reg swapped;             // Swapped flag
reg next_swapped;
reg [3:0] i;             // Loop counter
reg [3:0] next_i;
reg [5:0] cycle_count;   // Safety timeout
reg [5:0] next_cycle_count;

// Temporary swap registers
reg [7:0] temp_a;
reg [7:0] temp_b;

// Integer for loop (combinational logic)
integer idx;

// Next state logic
always @(*) begin
    next_state = state;
    next_gap = gap;
    next_swapped = swapped;
    next_i = i;
    next_cycle_count = cycle_count;

    case (state)
        STATE_IDLE: begin
            if (start) begin
                next_state = STATE_LOAD;
                next_cycle_count = 0;
            end
        end

        STATE_LOAD: begin
            // Load input array into buffer
            next_state = STATE_SORT;
            next_gap = NUM_ELEMENTS;  // Start with gap = size
            next_swapped = 1'b1;      // Force first iteration
            next_i = 0;
        end

        STATE_SORT: begin
            // Check for completion
            if (gap <= 1 && !swapped) begin
                next_state = STATE_DONE;
            end else if (cycle_count >= MAX_CYCLES) begin
                // Safety timeout
                next_state = STATE_DONE;
            end else begin
                // Perform one iteration of bubble sort with current gap
                if (i < (NUM_ELEMENTS - gap)) begin
                    // Compare and swap if needed
                    // This is handled in combinational block below
                    next_i = i + 1'b1;
                    // If we found a swap, mark swapped flag
                    if (buffer[i] > buffer[i+gap]) begin
                        next_swapped = 1'b1;
                    end
                end else begin
                    // End of this pass
                    next_i = 0;
                    next_cycle_count = cycle_count + 1'b1;

                    // Calculate next gap
                    if (gap > 1) begin
                        // gap = gap / 1.3 ≈ gap * 13 / 10
                        next_gap = (gap * 13) >> 3;  // Div by 8, ~1.625, slightly faster
                        if (next_gap < 1) next_gap = 1;
                    end else begin
                        next_gap = 0;
                    end

                    // Reset swapped flag for next pass
                    next_swapped = 1'b0;
                end
            end
        end

        STATE_DONE: begin
            // Hold done state until reset
            if (!start) begin
                next_state = STATE_IDLE;
            end
        end
    endcase
end

// Sequential state update
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= STATE_IDLE;
        done <= 1'b0;
        gap <= 0;
        swapped <= 0;
        i <= 0;
        cycle_count <= 0;
        // Reset output
        sorted_0 <= 8'b0;
        sorted_1 <= 8'b0;
        sorted_2 <= 8'b0;
        sorted_3 <= 8'b0;
        sorted_4 <= 8'b0;
        sorted_5 <= 8'b0;
        sorted_6 <= 8'b0;
        sorted_7 <= 8'b0;
    end else begin
        state <= next_state;
        gap <= next_gap;
        swapped <= next_swapped;
        i <= next_i;
        cycle_count <= next_cycle_count;

        // Load operation
        if (state == STATE_LOAD) begin
            buffer[0] <= arr_0;
            buffer[1] <= arr_1;
            buffer[2] <= arr_2;
            buffer[3] <= arr_3;
            buffer[4] <= arr_4;
            buffer[5] <= arr_5;
            buffer[6] <= arr_6;
            buffer[7] <= arr_7;
        end

        // Sort operation - perform swap if needed
        if (state == STATE_SORT && i < (NUM_ELEMENTS - gap)) begin
            if (buffer[i] > buffer[i+gap]) begin
                // Swap
                buffer[i] <= buffer[i+gap];
                buffer[i+gap] <= buffer[i];
            end
        end

        // Done operation - copy to output
        if (state == STATE_DONE) begin
            sorted_0 <= buffer[0];
            sorted_1 <= buffer[1];
            sorted_2 <= buffer[2];
            sorted_3 <= buffer[3];
            sorted_4 <= buffer[4];
            sorted_5 <= buffer[5];
            sorted_6 <= buffer[6];
            sorted_7 <= buffer[7];
            done <= 1'b1;
        end else begin
            done <= 1'b0;
        end
    end
end

endmodule

module divisor_counter (
    input clk,
    input rst_n,
    input start,
    input [7:0] n,           // Input number (max 255)
    output reg [7:0] result, // Number of divisors
    output reg done          // Asserted when computation complete
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b11;

    reg [1:0] state;
    reg [7:0] counter;       // Current number being tested (1 to n)
    reg [7:0] divisor_count; // Accumulated divisor count
    reg [7:0] n_reg;         // Store input n

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            counter <= 8'd0;
            divisor_count <= 8'd0;
            n_reg <= 8'd0;
            result <= 8'd0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        n_reg <= n;
                        counter <= 8'd1;  // Start from 1
                        divisor_count <= 8'd0;
                        state <= (n == 8'd0) ? FINISH : COMPUTE;
                    end
                end

                COMPUTE: begin
                    // Check if counter divides n
                    if (n_reg % counter == 8'd0) begin
                        divisor_count <= divisor_count + 1'b1;
                    end

                    // Move to next or finish
                    if (counter < n_reg) begin
                        counter <= counter + 1'b1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    result <= divisor_count;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module newman_shanks_williams (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] n,        // n value (0-8)
    output reg [15:0] result,
    output reg done
);

// Sequential implementation of NS(n) = 2*NS(n-1) + NS(n-2)
// Base cases: NS(0) = 1, NS(1) = 1
// Max n=8: NS(8) = 577 (fits in 10 bits, using 16 for safety)

reg [15:0] ns_prev;   // NS(n-2)
reg [15:0] ns_curr;   // NS(n-1) / current result
reg [3:0] counter;    // iteration counter
reg computing;        // state machine state

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        result <= 16'd0;
        done <= 1'b0;
        ns_prev <= 16'd0;
        ns_curr <= 16'd0;
        counter <= 4'd0;
        computing <= 1'b0;
    end else begin
        if (start && !computing) begin
            // Initialize based on n
            if (n == 4'd0) begin
                result <= 16'd1;
                done <= 1'b1;
                computing <= 1'b0;
            end else if (n == 4'd1) begin
                result <= 16'd1;
                done <= 1'b1;
                computing <= 1'b0;
            end else begin
                // Start computation for n >= 2
                ns_prev <= 16'd1;  // NS(0)
                ns_curr <= 16'd1;  // NS(1)
                counter <= 4'd2;   // Start from iteration 2
                computing <= 1'b1;
                done <= 1'b0;
            end
        end else if (computing) begin
            // NS(i) = 2*NS(i-1) + NS(i-2)
            ns_prev <= ns_curr;
            ns_curr <= (ns_curr << 1) + ns_prev;
            counter <= counter + 1'b1;

            if (counter + 1'b1 >= n) begin
                computing <= 1'b0;
                result <= (ns_curr << 1) + ns_prev;
                done <= 1'b1;
            end
        end else begin
            done <= 1'b0;
        end
    end
end

endmodule

module even_bit_set(
    input [15:0] n,
    output [15:0] result
);

// Set all even bits (bit positions 0, 2, 4, 6, 8, 10, 12, 14)
// Note: bit positions are 0-indexed from LSB
// Even positions: 0, 2, 4, 6, 8, 10, 12, 14
// Mask: 0101 0101 0101 0101 = 0x5555

assign result = n | 16'h5555;

endmodule

module complex_angle (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire signed [15:0] a,       // Real part (scaled integer)
    input wire signed [15:0] b,       // Imaginary part (scaled integer)
    output reg [15:0] angle,          // Result angle in Q8.8 fixed-point format
    output reg done                   // High for 1 cycle when result is valid
);

    // Implements atan2(b, a) using a simplified lookup/state machine
    // Input range: -32768 to 32767
    // Output range: -pi to pi, represented as Q8.8 (1 integer bit, 7 fractional bits)
    // Example: 3.14159 -> 0x0324 (approx)
    //          1.57079 -> 0x0192 (approx)
    //          0.46364 -> 0x0075 (approx)

    // Internal state definitions
    reg [2:0] state;
    reg signed [15:0] abs_a;
    reg signed [15:0] abs_b;
    reg [15:0] temp_angle;

    // Quadrant handling:
    // Q1 (a>=0, b>=0): normal
    // Q2 (a<0, b>=0): pi - atan(|b/a|)
    // Q3 (a<0, b<0): -pi + atan(|b/a|)
    // Q4 (a>=0, b<0): -atan(|b/a|)

    // Lookup table for atan(b/a) for 0 <= b/a <= 1 (scaled by 4096)
    // Values are approximated: atan(1.0) = 0.7854 -> 201 (Q8.8)
    // atan(0.0) = 0

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 3'b000;
            angle <= 16'b0;
            done <= 1'b0;
        end else begin
            case (state)
                3'b000: begin // Idle
                    done <= 1'b0;
                    if (start) begin
                        state <= 3'b001;
                    end
                end

                3'b001: begin // Abs values and boundary checks
                    abs_a <= (a[15] ? -a : a);
                    abs_b <= (b[15] ? -b : b);
                    state <= 3'b010;
                end

                3'b010: begin // Calculate ratio estimate (simplified)
                    // Use magnitude comparison instead of division
                    // If abs_b > abs_a, swap and adjust
                    temp_angle <= 16'b0;
                    state <= 3'b011;
                end

                3'b011: begin // Quadrant determination and base angle
                    // Simple approximation for atan2 based on quadrant
                    if (a == 0 && b == 0) begin
                        angle <= 16'b0; // Undefined, return 0
                        state <= 3'b100;
                    end else if (a == 0) begin
                        // Vertical: 90 or -90 degrees (1.5708)
                        if (b[15]) angle <= 16'hFE6E; // -1.5708 approx
                        else       angle <= 16'h0192; //  1.5708 approx
                        state <= 3'b100;
                    end else if (b == 0) begin
                        // Horizontal: 0 or 180 degrees
                        if (a[15]) angle <= 16'h0324; // 3.1416 approx
                        else       angle <= 16'h0000; // 0
                        state <= 3'b100;
                    end else begin
                        // General case: use precomputed approximation
                        // If abs_b approx abs_a, angle is 45 deg (0.7854)
                        // Scale difference to get approximation
                        if (abs_b > abs_a) begin
                            // Higher slope: 45 to 90
                            temp_angle <= 16'h00C8; // Base 45 deg
                        end else begin
                            // Lower slope: 0 to 45
                            temp_angle <= 16'h00C8; // Base 45 deg
                        end
                        state <= 3'b110;
                    end
                end

                3'b110: begin // Refined angle calculation
                    // Apply quadrant correction to temp_angle
                    if (!a[15] && !b[15]) begin // Q1
                        angle <= temp_angle;
                    end else if (a[15] && !b[15]) begin // Q2: pi - angle
                        angle <= 16'h0324 - temp_angle;
                    end else if (a[15] && b[15]) begin // Q3: -pi + angle
                        angle <= 16'hFCDc + temp_angle; // -3.1416 + angle
                    end else begin // Q4: -angle
                        angle <= 16'h0000 - temp_angle;
                    end
                    state <= 3'b100;
                end

                3'b100: begin // Finish
                    done <= 1'b1;
                    state <= 3'b000;
                end

                default: state <= 3'b000;
            endcase
        end
    end

endmodule

module dif_square (
    input [7:0] n,        // Input number (8-bit unsigned)
    output result          // 1-bit result: 1 if can be represented as difference of two squares, 0 otherwise
);

// A number can be represented as the difference of two squares if and only if
// it is NOT congruent to 2 modulo 4 (i.e., n % 4 != 2)
// This is because: n = a^2 - b^2 = (a+b)(a-b)
// For integer a,b, the product (a+b)(a-b) will never equal 2 mod 4

// Combinational logic: result = 1 if n[1:0] != 2'b10
// n % 4 is equivalent to n[1:0] (the 2 least significant bits)
// n % 4 == 2 means n[1:0] == 2'b10

assign result = (n[1:0] != 2'b10);

endmodule

module spec_frequency_lists(
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input array: flattened list of max 12 elements (3 sublists of 4 elements each)
    // Using individual ports for easier assignment
    input wire [7:0] arr_0, arr_1, arr_2, arr_3,
    input wire [7:0] arr_4, arr_5, arr_6, arr_7,
    input wire [7:0] arr_8, arr_9, arr_10, arr_11,
    input wire [3:0] num_elements,  // 1 to 12

    // Output: 2D array of (value, count) pairs
    // We output up to 12 pairs (worst case: all unique)
    output reg [7:0] out_val_0, out_val_1, out_val_2, out_val_3,
    output reg [7:0] out_val_4, out_val_5, out_val_6, out_val_7,
    output reg [7:0] out_val_8, out_val_9, out_val_10, out_val_11,
    output reg [3:0] out_count_0, out_count_1, out_count_2, out_count_3,
    output reg [3:0] out_count_4, out_count_5, out_count_6, out_count_7,
    output reg [3:0] out_count_8, out_count_9, out_count_10, out_count_11,
    output reg [3:0] out_num_pairs,  // Number of valid (value, count) pairs

    output reg done
);

    // State machine states
    localparam S_IDLE = 3'b000;
    localparam S_GATHER = 3'b001;  // Collect unique values
    localparam S_COUNT = 3'b010;   // Count frequencies
    localparam S_DONE = 3'b011;

    reg [2:0] state;
    reg [3:0] idx;           // Index for iterating through input array
    reg [3:0] pair_idx;      // Index for unique pairs found
    reg [3:0] scan_idx;      // Index for counting loop

    // Storage for unique values (max 12)
    reg [7:0] unique_vals [0:11];
    reg [3:0] counts [0:11];

    // Temp registers for comparison
    reg found;
    reg [3:0] j;

    integer k;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            done <= 0;
            idx <= 0;
            pair_idx <= 0;
            scan_idx <= 0;
            out_num_pairs <= 0;
            // Reset outputs
            {out_val_0, out_val_1, out_val_2, out_val_3} <= 32'b0;
            {out_val_4, out_val_5, out_val_6, out_val_7} <= 32'b0;
            {out_val_8, out_val_9, out_val_10, out_val_11} <= 32'b0;
            {out_count_0, out_count_1, out_count_2, out_count_3} <= 16'b0;
            {out_count_4, out_count_5, out_count_6, out_count_7} <= 16'b0;
            {out_count_8, out_count_9, out_count_10, out_count_11} <= 16'b0;
            for (k = 0; k < 12; k = k + 1) begin
                unique_vals[k] <= 8'b0;
                counts[k] <= 4'b0;
            end
        end else begin
            case (state)
                S_IDLE: begin
                    done <= 0;
                    idx <= 0;
                    pair_idx <= 0;
                    scan_idx <= 0;
                    out_num_pairs <= 0;
                    if (start && num_elements > 0) begin
                        state <= S_GATHER;
                    end
                end

                S_GATHER: begin
                    if (idx < num_elements) begin
                        // Get input value based on idx
                        case (idx)
                            0: unique_vals[pair_idx] <= arr_0;
                            1: unique_vals[pair_idx] <= arr_1;
                            2: unique_vals[pair_idx] <= arr_2;
                            3: unique_vals[pair_idx] <= arr_3;
                            4: unique_vals[pair_idx] <= arr_4;
                            5: unique_vals[pair_idx] <= arr_5;
                            6: unique_vals[pair_idx] <= arr_6;
                            7: unique_vals[pair_idx] <= arr_7;
                            8: unique_vals[pair_idx] <= arr_8;
                            9: unique_vals[pair_idx] <= arr_9;
                            10: unique_vals[pair_idx] <= arr_10;
                            11: unique_vals[pair_idx] <= arr_11;
                            default: unique_vals[pair_idx] <= 8'b0;
                        endcase

                        // Check if this value already exists in unique_vals
                        found <= 0;
                        j <= 0;

                        // Wait one cycle for value to stabilize
                        state <= 3'b100; // Temporary state for comparison
                        idx <= idx + 1;
                    end else begin
                        // All elements processed, go to counting
                        state <= S_COUNT;
                        scan_idx <= 0;
                    end
                end

                3'b100: begin // Compare state
                    // Compare current value (now in unique_vals[pair_idx]) with existing
                    if (j < pair_idx) begin
                        if (unique_vals[j] == unique_vals[pair_idx]) begin
                            found <= 1;
                        end
                        j <= j + 1;
                        state <= 3'b100; // Stay in compare
                    end else begin
                        // Finished comparing
                        if (!found) begin
                            // New unique value, increment pair_idx
                            pair_idx <= pair_idx + 1;
                        end
                        state <= S_GATHER;
                    end
                end

                S_COUNT: begin
                    if (scan_idx < pair_idx) begin
                        // Count occurrences of unique_vals[scan_idx]
                        // Reset count for this value
                        counts[scan_idx] <= 0;

                        // Need to scan all inputs
                        idx <= 0;
                        state <= 3'b101; // Counting scan state
                    end else begin
                        // Counting done, prepare output
                        out_num_pairs <= pair_idx;

                        // Copy to outputs
                        out_val_0 <= unique_vals[0]; out_count_0 <= counts[0];
                        out_val_1 <= unique_vals[1]; out_count_1 <= counts[1];
                        out_val_2 <= unique_vals[2]; out_count_2 <= counts[2];
                        out_val_3 <= unique_vals[3]; out_count_3 <= counts[3];
                        out_val_4 <= unique_vals[4]; out_count_4 <= counts[4];
                        out_val_5 <= unique_vals[5]; out_count_5 <= counts[5];
                        out_val_6 <= unique_vals[6]; out_count_6 <= counts[6];
                        out_val_7 <= unique_vals[7]; out_count_7 <= counts[7];
                        out_val_8 <= unique_vals[8]; out_count_8 <= counts[8];
                        out_val_9 <= unique_vals[9]; out_count_9 <= counts[9];
                        out_val_10 <= unique_vals[10]; out_count_10 <= counts[10];
                        out_val_11 <= unique_vals[11]; out_count_11 <= counts[11];

                        state <= S_DONE;
                    end
                end

                3'b101: begin // Inner counting loop
                    if (idx < num_elements) begin
                        // Get current input value
                        case (idx)
                            0: if (arr_0 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            1: if (arr_1 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            2: if (arr_2 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            3: if (arr_3 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            4: if (arr_4 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            5: if (arr_5 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            6: if (arr_6 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            7: if (arr_7 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            8: if (arr_8 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            9: if (arr_9 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            10: if (arr_10 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                            11: if (arr_11 == unique_vals[scan_idx]) counts[scan_idx] <= counts[scan_idx] + 1;
                        endcase
                        idx <= idx + 1;
                    end else begin
                        // Done counting this value
                        scan_idx <= scan_idx + 1;
                        state <= S_COUNT;
                    end
                end

                S_DONE: begin
                    done <= 1;
                    state <= S_IDLE;
                end

                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module pattern_checker (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Fixed-width color inputs (8 elements of 8 ASCII chars each)
    // Each color is represented as 64-bit packed ASCII (8 chars * 8 bits)
    input wire [63:0] colors_0,
    input wire [63:0] colors_1,
    input wire [63:0] colors_2,
    input wire [63:0] colors_3,
    input wire [63:0] colors_4,
    input wire [63:0] colors_5,
    input wire [63:0] colors_6,
    input wire [63:0] colors_7,

    // Pattern inputs (8 elements of 8-bit pattern codes)
    input wire [7:0] patterns_0,
    input wire [7:0] patterns_1,
    input wire [7:0] patterns_2,
    input wire [7:0] patterns_3,
    input wire [7:0] patterns_4,
    input wire [7:0] patterns_5,
    input wire [7:0] patterns_6,
    input wire [7:0] patterns_7,

    input wire [3:0] num_elements,  // Number of valid elements (1-8)

    output reg result,
    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam CHECK_LEN = 2'b01;
    localparam BUILD_MAP = 2'b10;
    localparam VERIFY = 2'b11;

    reg [1:0] state, next_state;
    reg [3:0] idx;
    reg [7:0] current_pattern;
    reg [63:0] expected_color;
    reg pattern_found;
    reg [7:0] unique_patterns [0:7];
    reg [63:0] mapped_colors [0:7];
    reg [7:0] pattern_count;
    reg [2:0] verify_idx;

    integer i;

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = CHECK_LEN;
            CHECK_LEN: next_state = BUILD_MAP;
            BUILD_MAP: if (idx >= num_elements) next_state = VERIFY;
            VERIFY: if (verify_idx >= pattern_count) next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // State register and combinational logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            idx <= 0;
            pattern_count <= 0;
            verify_idx <= 0;
            // Clear mappings
            for (i = 0; i < 8; i = i + 1) begin
                unique_patterns[i] <= 8'h00;
                mapped_colors[i] <= 64'h00;
            end
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    result <= 0;
                    idx <= 0;
                    pattern_count <= 0;
                    verify_idx <= 0;
                end

                CHECK_LEN: begin
                    // Just transition to BUILD_MAP
                    // In this simplified version, we assume num_elements is valid
                    // The "length mismatch" check is implied by num_elements range
                end

                BUILD_MAP: begin
                    if (idx < num_elements) begin
                        // Get current pattern and color
                        case (idx)
                            0: begin current_pattern <= patterns_0; expected_color <= colors_0; end
                            1: begin current_pattern <= patterns_1; expected_color <= colors_1; end
                            2: begin current_pattern <= patterns_2; expected_color <= colors_2; end
                            3: begin current_pattern <= patterns_3; expected_color <= colors_3; end
                            4: begin current_pattern <= patterns_4; expected_color <= colors_4; end
                            5: begin current_pattern <= patterns_5; expected_color <= colors_5; end
                            6: begin current_pattern <= patterns_6; expected_color <= colors_6; end
                            7: begin current_pattern <= patterns_7; expected_color <= colors_7; end
                        endcase

                        // Check if pattern exists in map
                        pattern_found <= 0;
                        for (i = 0; i < 8; i = i + 1) begin
                            if (unique_patterns[i] == current_pattern) begin
                                pattern_found <= 1;
                                // Verify color consistency
                                if (mapped_colors[i] != expected_color) begin
                                    result <= 0;
                                    done <= 1;
                                    state <= IDLE;
                                end
                            end
                        end

                        // Add new pattern if not found
                        if (!pattern_found && pattern_count < 8) begin
                            unique_patterns[pattern_count] <= current_pattern;
                            mapped_colors[pattern_count] <= expected_color;
                            pattern_count <= pattern_count + 1;
                        end

                        idx <= idx + 1;
                    end
                end

                VERIFY: begin
                    // Check if number of unique patterns equals number of unique colors
                    // Count unique colors
                    if (verify_idx == 0) begin
                        // This check is implicit in the mapping logic
                        // If we reach here without failing, patterns are consistent
                        result <= 1;
                    end
                    verify_idx <= verify_idx + 1;
                    if (verify_idx >= pattern_count - 1) begin
                        done <= 1;
                    end
                end
            endcase

            // Auto-clear done after one cycle
            if (done && state == IDLE) begin
                done <= 0;
            end
        end
    end

endmodule

module elementwise_division #(
    parameter NUM_ELEMENTS = 4,
    parameter DATA_WIDTH = 8,
    parameter RESULT_WIDTH = 8
)(
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input arrays - individual ports
    input wire [DATA_WIDTH-1:0] dividend_0,
    input wire [DATA_WIDTH-1:0] dividend_1,
    input wire [DATA_WIDTH-1:0] dividend_2,
    input wire [DATA_WIDTH-1:0] dividend_3,

    input wire [DATA_WIDTH-1:0] divisor_0,
    input wire [DATA_WIDTH-1:0] divisor_1,
    input wire [DATA_WIDTH-1:0] divisor_2,
    input wire [DATA_WIDTH-1:0] divisor_3,

    // Output arrays - individual ports
    output reg [RESULT_WIDTH-1:0] result_0,
    output reg [RESULT_WIDTH-1:0] result_1,
    output reg [RESULT_WIDTH-1:0] result_2,
    output reg [RESULT_WIDTH-1:0] result_3,

    output reg done
);

    // State machine
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state;
    reg [1:0] index;

    // Combinational division results
    wire [RESULT_WIDTH-1:0] div_result [0:3];

    // Division units (combinational)
    assign div_result[0] = (divisor_0 != 0) ? dividend_0 / divisor_0 : 0;
    assign div_result[1] = (divisor_1 != 0) ? dividend_1 / divisor_1 : 0;
    assign div_result[2] = (divisor_2 != 0) ? dividend_2 / divisor_2 : 0;
    assign div_result[3] = (divisor_3 != 0) ? dividend_3 / divisor_3 : 0;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            index <= 2'b00;
            done <= 1'b0;
            result_0 <= 0;
            result_1 <= 0;
            result_2 <= 0;
            result_3 <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPUTE;
                        index <= 2'b00;
                    end
                end

                COMPUTE: begin
                    // Store results sequentially
                    case (index)
                        2'b00: result_0 <= div_result[0];
                        2'b01: result_1 <= div_result[1];
                        2'b10: result_2 <= div_result[2];
                        2'b11: result_3 <= div_result[3];
                    endcase

                    if (index == 2'b11) begin
                        state <= FINISH;
                        index <= 2'b00;
                    end else begin
                        index <= index + 1'b1;
                    end
                end

                FINISH: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

cocotb_testbench:
import cocotb
from cocotb.triggers import Timer, RisingEdge, FallingEdge
from cocotb.clock import Clock
from cocotb.result import TestFailure

# ============================================================================
# CONFIGURATION
# ============================================================================
DATA_WIDTH = 8
RESULT_WIDTH = 8
CLK_PERIOD_NS = 10
MAX_CYCLES = 100

# ============================================================================
# MANDATORY HELPER FUNCTIONS
# ============================================================================

def is_value_defined(value):
    try:
        int(value)
        return True
    except ValueError:
        return False

def safe_int(value, default=0):
    try:
        return int(value)
    except ValueError:
        return default

def to_signed(val, bits):
    if val >= (1 << (bits - 1)):
        return val - (1 << bits)
    return val

def from_signed(val, bits):
    if val < 0:
        return val + (1 << bits)
    return val

def has_signal(dut, name):
    try:
        getattr(dut, name)
        return True
    except AttributeError:
        return False

def clamp_to_width(value, bits):
    max_val = (1 << bits) - 1
    if value < 0:
        return from_signed(max(-((1 << (bits-1))), min((1 << (bits-1)) - 1, value)), bits)
    return min(max_val, max(0, value))

# ============================================================================
# ARRAY ACCESS HELPERS
# ============================================================================

async def write_tuple_to_ports(dut, prefix, values, element_width):
    for i, val in enumerate(values):
        port_name = f"{prefix}_{i}"
        if has_signal(dut, port_name):
            getattr(dut, port_name).value = clamp_to_width(val, element_width)
        else:
            raise TestFailure(f"Cannot find port: {port_name}")

async def read_result_from_ports(dut, prefix, size):
    results = []
    for i in range(size):
        port_name = f"{prefix}_{i}"
        if has_signal(dut, port_name):
            val = getattr(dut, port_name).value
            if is_value_defined(val):
                results.append(int(val))
            else:
                results.append(None)
        else:
            results.append(None)
    return results

# ============================================================================
# SEQUENTIAL MODULE HELPERS
# ============================================================================

async def reset_dut(dut):
    dut.rst_n.value = 0
    dut.start.value = 0
    for _ in range(2):
        await RisingEdge(dut.clk)
    dut.rst_n.value = 1
    await RisingEdge(dut.clk)

async def wait_for_done(dut, max_cycles=MAX_CYCLES):
    for cycle in range(max_cycles):
        await RisingEdge(dut.clk)
        if is_value_defined(dut.done.value) and int(dut.done.value) == 1:
            return True
    raise TestFailure(f"Timeout: done not asserted after {max_cycles} cycles")

async def start_computation(dut):
    dut.start.value = 1
    await RisingEdge(dut.clk)
    dut.start.value = 0

# ============================================================================
# MAIN TEST
# ============================================================================

@cocotb.test(timeout_time=1000, timeout_unit="ms")
async def test_elementwise_division(dut):
    cocotb.start_soon(Clock(dut.clk, CLK_PERIOD_NS, units='ns').start())
    await reset_dut(dut)

    test_cases = [
        ((10, 4, 6, 9), (5, 2, 3, 3), (2, 2, 2, 3)),
        ((12, 6, 8, 16), (6, 3, 4, 4), (2, 2, 2, 4)),
        ((20, 14, 36, 18), (5, 7, 6, 9), (4, 2, 6, 2)),
    ]

    passed = 0
    failed = 0

    for i, (dividend, divisor, expected) in enumerate(test_cases):
        cocotb.log.info(f"Test {i+1}: {dividend} // {divisor} == {expected}")

        try:
            await write_tuple_to_ports(dut, 'dividend', dividend, DATA_WIDTH)
            await write_tuple_to_ports(dut, 'divisor', divisor, DATA_WIDTH)

            await start_computation(dut)
            await wait_for_done(dut)

            results = await read_result_from_ports(dut, 'result', 4)

            if any(r is None for r in results):
                raise TestFailure("Some result ports are undefined")

            result_tuple = tuple(results)

            if result_tuple != expected:
                raise TestFailure(f"Expected {expected}, got {result_tuple}")

            cocotb.log.info(f"  PASS: result = {result_tuple}")
            passed += 1
            await RisingEdge(dut.clk)

        except TestFailure as e:
            cocotb.log.error(f"  FAIL: {e}")
            failed += 1

    cocotb.log.info(f"{'='*50}")
    cocotb.log.info(f"Results: {passed}/{passed+failed} tests passed")

    if failed > 0:
        raise TestFailure(f"{failed} tests failed")

verilog_prompt:
/*
Task: Implement hardware to check if two lists have at least one common element.

Adaptation: Use 8-element arrays with 8-bit elements. Scale down from 5-element test cases.
Algorithm: Compare all pairs (list1[i] vs list2[j]) in parallel, OR reduce all comparison results.

Interface Specification:

Inputs:
  - clk         : Clock signal (rising edge triggered)
  - rst_n       : Active-low synchronous reset
  - start       : Start pulse (assert for 1 cycle to begin comparison)
  - list1[0:7]  : 8-element input array, each element 8 bits (MSB: list1[7], LSB: list1[0])
  - list2[0:7]  : 8-element input array, each element 8 bits (MSB: list2[7], LSB: list2[0])
  - len1        : 3-bit value (0-7) indicating number of valid elements in list1 (0=1 element, 7=8 elements)
  - len2        : 3-bit value (0-7) indicating number of valid elements in list2

Outputs:
  - has_common  : 1-bit result (1=true, 0=false)
  - done        : Asserted high for 1 cycle when comparison is complete

Timing:
  - Assert start for 1 clock cycle to initiate comparison
  - done will go high approximately 2 clock cycles after start
  - Sample has_common on the same cycle done is high
  - Start should not be asserted again until done goes high

Reset behavior:
  - On rst_n=0: done=0, has_common=0, all internal state cleared
  - Minimum 2 clock cycles of reset required before start

Implementation Requirements:
  - Use a state machine with IDLE, COMPARE, DONE states
  - Compare all valid elements: for i in 0..len1, for j in 0..len2, if list1[i]==list2[j] then result=1
  - Use combinational comparison logic for each (i,j) pair, then OR reduce
  - Only compare within valid length ranges
  - Optimization: Can break early if match found, but simple 2-cycle approach is acceptable
  - Maximum: 8x8 = 64 parallel comparators, each 8-bit wide
  - Result should be registered on cycle after comparison

Example:
  list1 = [0x01, 0x02, 0x03, 0x04, 0x05, 0x00, 0x00, 0x00]  (len1=4, meaning indices 0-4)
  list2 = [0x05, 0x06, 0x07, 0x08, 0x09, 0x00, 0x00, 0x00]  (len2=4)
  Expected: has_common=1 (element 0x05 is in both)

  list1 = [0x01, 0x02, 0x03, 0x04, 0x05, 0x00, 0x00, 0x00]  (len1=4)
  list2 = [0x06, 0x07, 0x08, 0x09, 0x00, 0x00, 0x00, 0x00]  (len2=3)
  Expected: has_common=0
*/

module common_element_check (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] list1 [0:7],
    input wire [7:0] list2 [0:7],
    input wire [2:0] len1,
    input wire [2:0] len2,
    output reg has_common,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPARE = 2'b01;
    localparam DONE = 2'b10;

    reg [1:0] state, next_state;
    reg result_reg, next_result;

    // Combinational comparison logic
    wire [63:0] pair_matches;  // 8x8 grid of comparison results
    wire all_matches_or;

    genvar i, j;
    generate
        for (i = 0; i < 8; i = i + 1) begin : compare_rows
            for (j = 0; j < 8; j = j + 1) begin : compare_cols
                // Only compare if within valid ranges
                assign pair_matches[i*8 + j] = (i <= len1) && (j <= len2) && 
                                                (list1[i] == list2[j]);
            end
        end
    endgenerate

    // OR reduce all comparison results
    assign all_matches_or = |pair_matches;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            has_common <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
            has_common <= next_result;
            done <= (next_state == DONE);
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        next_result = has_common;

        case (state)
            IDLE: begin
                if (start) begin
                    next_state = COMPARE;
                    next_result = 1'b0;
                end
            end

            COMPARE: begin
                next_result = all_matches_or;
                next_state = DONE;
            end

            DONE: begin
                next_state = IDLE;
                next_result = 1'b0;
            end

            default: begin
                next_state = IDLE;
                next_result = 1'b0;
            end
        endcase
    end

endmodule

// String to Lowercase Converter
// Converts ASCII string to lowercase
// Fixed-size buffer: 16 characters max
// Character processing: A-Z -> a-z (add 0x20), others unchanged

module string_to_lower (
    input wire clk,              // Clock signal
    input wire rst_n,            // Active-low reset
    input wire start,            // Start pulse (1 cycle)

    // Input string: 16x8-bit character array
    input wire [7:0] str_0, str_1, str_2, str_3,
    input wire [7:0] str_4, str_5, str_6, str_7,
    input wire [7:0] str_8, str_9, str_10, str_11,
    input wire [7:0] str_12, str_13, str_14, str_15,

    input wire [3:0] str_len,    // String length (0-16)

    // Output string: 16x8-bit character array
    output reg [7:0] result_0, result_1, result_2, result_3,
    output reg [7:0] result_4, result_5, result_6, result_7,
    output reg [7:0] result_8, result_9, result_10, result_11,
    output reg [7:0] result_12, result_13, result_14, result_15,

    output reg done              // Done signal
);

    // Internal state
    reg [3:0] idx;               // Current character index
    reg processing;              // Processing flag

    // Character conversion logic
    wire [7:0] current_char;
    wire [7:0] converted_char;

    // Mux to select current input character
    assign current_char = 
        (idx == 4'd0) ? str_0 :
        (idx == 4'd1) ? str_1 :
        (idx == 4'd2) ? str_2 :
        (idx == 4'd3) ? str_3 :
        (idx == 4'd4) ? str_4 :
        (idx == 4'd5) ? str_5 :
        (idx == 4'd6) ? str_6 :
        (idx == 4'd7) ? str_7 :
        (idx == 4'd8) ? str_8 :
        (idx == 4'd9) ? str_9 :
        (idx == 4'd10) ? str_10 :
        (idx == 4'd11) ? str_11 :
        (idx == 4'd12) ? str_12 :
        (idx == 4'd13) ? str_13 :
        (idx == 4'd14) ? str_14 :
        str_15;

    // Convert to lowercase: if A-Z, set bit 5 (add 0x20)
    assign converted_char = (current_char >= 8'h41 && current_char <= 8'h5A) ? 
                            (current_char | 8'h20) : current_char;

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            idx <= 4'd0;
            processing <= 1'b0;
            done <= 1'b0;
            result_0 <= 8'd0; result_1 <= 8'd0; result_2 <= 8'd0; result_3 <= 8'd0;
            result_4 <= 8'd0; result_5 <= 8'd0; result_6 <= 8'd0; result_7 <= 8'd0;
            result_8 <= 8'd0; result_9 <= 8'd0; result_10 <= 8'd0; result_11 <= 8'd0;
            result_12 <= 8'd0; result_13 <= 8'd0; result_14 <= 8'd0; result_15 <= 8'd0;
        end else begin
            if (start && !processing) begin
                // Start processing
                idx <= 4'd0;
                processing <= 1'b1;
                done <= 1'b0;
            end else if (processing) begin
                if (idx < str_len) begin
                    // Process current character
                    case (idx)
                        4'd0: result_0 <= converted_char;
                        4'd1: result_1 <= converted_char;
                        4'd2: result_2 <= converted_char;
                        4'd3: result_3 <= converted_char;
                        4'd4: result_4 <= converted_char;
                        4'd5: result_5 <= converted_char;
                        4'd6: result_6 <= converted_char;
                        4'd7: result_7 <= converted_char;
                        4'd8: result_8 <= converted_char;
                        4'd9: result_9 <= converted_char;
                        4'd10: result_10 <= converted_char;
                        4'd11: result_11 <= converted_char;
                        4'd12: result_12 <= converted_char;
                        4'd13: result_13 <= converted_char;
                        4'd14: result_14 <= converted_char;
                        4'd15: result_15 <= converted_char;
                    endcase
                    idx <= idx + 1'b1;
                end else begin
                    // Done processing
                    processing <= 1'b0;
                    done <= 1'b1;
                    idx <= 4'd0;
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

module text_match_wordz(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_array [0:15],  // 16-character input buffer
    input wire [4:0] str_len,             // Actual string length (1-16)
    output reg result,
    output reg done
);

// Sequential state machine
// States: IDLE, SCANNING, COMPLETE
reg [1:0] state;
reg [4:0] index;
reg found_z;

localparam IDLE = 2'b00;
localparam SCANNING = 2'b01;
localparam COMPLETE = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        index <= 5'b0;
        found_z <= 1'b0;
        result <= 1'b0;
        done <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                if (start) begin
                    state <= SCANNING;
                    index <= 5'b0;
                    found_z <= 1'b0;
                end
            end

            SCANNING: begin
                if (index < str_len) begin
                    // Check if current character is 'z' (0x7A)
                    if (char_array[index] == 8'h7A) begin
                        found_z <= 1'b1;
                    end
                    index <= index + 1'b1;
                end else begin
                    state <= COMPLETE;
                    result <= found_z;
                    done <= 1'b1;
                end
            end

            COMPLETE: begin
                done <= 1'b0;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module text_lowercase_underscore(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_array [0:15],  // 16-character fixed-width string
    input wire [3:0] length,              // Actual string length (1-16)
    output reg result,
    output reg done
);

    // State machine states
    localparam IDLE = 3'b000;
    localparam CHECK_START = 3'b001;
    localparam CHECK_UNDERSCORE = 3'b010;
    localparam CHECK_END = 3'b011;
    localparam FINISHED = 3'b100;

    reg [2:0] state, next_state;
    reg [3:0] pos;           // Current position in string
    reg [7:0] current_char;
    reg valid_sofar;         // Tracks if pattern matched so far

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            pos <= 4'd0;
            result <= 1'b0;
            done <= 1'b0;
            valid_sofar <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    if (start) begin
                        pos <= 4'd0;
                        valid_sofar <= 1'b1;
                        done <= 1'b0;
                    end
                end

                CHECK_START: begin
                    // Check first character is lowercase letter
                    if (length == 4'd0 || current_char < 8'h61 || current_char > 8'h7a) begin
                        valid_sofar <= 1'b0;
                    end
                    pos <= pos + 1;
                end

                CHECK_UNDERSCORE: begin
                    // Check for underscore and at least one more char
                    if (current_char != 8'h5f || pos >= length) begin
                        valid_sofar <= 1'b0;
                    end
                    pos <= pos + 1;
                end

                CHECK_END: begin
                    // Check remaining chars are lowercase letters
                    if (current_char < 8'h61 || current_char > 8'h7a) begin
                        valid_sofar <= 1'b0;
                    end
                    pos <= pos + 1;
                end

                FINISHED: begin
                    result <= valid_sofar;
                    done <= 1'b1;
                end
            endcase
        end
    end

    // Current character selection
    always @(*) begin
        if (pos < length && pos < 16) begin
            current_char = char_array[pos];
        end else begin
            current_char = 8'h00;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) next_state = CHECK_START;
            end

            CHECK_START: begin
                // Look for underscore (end of first sequence)
                if (current_char == 8'h5f && pos > 0 && valid_sofar) begin
                    next_state = CHECK_UNDERSCORE;
                end else if (pos >= length) begin
                    next_state = FINISHED; // No underscore found
                end
            end

            CHECK_UNDERSCORE: begin
                // Must have at least one char after underscore
                if (pos >= length) begin
                    next_state = FINISHED; // String ends at underscore
                end else begin
                    next_state = CHECK_END;
                end
            end

            CHECK_END: begin
                // Process until end of string
                if (pos >= length) begin
                    next_state = FINISHED;
                end
            end

            FINISHED: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

module min_product_tuple (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0_x, arr_0_y,
    input wire [7:0] arr_1_x, arr_1_y,
    input wire [7:0] arr_2_x, arr_2_y,
    input wire [7:0] arr_3_x, arr_3_y,
    input wire [2:0] num_pairs,
    output reg [15:0] result,
    output reg done
);

    reg [2:0] index;
    reg [15:0] current_min;
    reg [1:0] state;
    wire signed [15:0] product;
    wire [15:0] abs_product;

    localparam IDLE = 2'b00;
    localparam CALC = 2'b01;
    localparam UPDATE = 2'b10;
    localparam FINISH = 2'b11;

    reg [7:0] curr_x, curr_y;

    always @(*) begin
        case(index)
            3'd0: begin curr_x = arr_0_x; curr_y = arr_0_y; end
            3'd1: begin curr_x = arr_1_x; curr_y = arr_1_y; end
            3'd2: begin curr_x = arr_2_x; curr_y = arr_2_y; end
            3'd3: begin curr_x = arr_3_x; curr_y = arr_3_y; end
            default: begin curr_x = 8'd0; curr_y = 8'd0; end
        endcase
    end

    assign product = curr_x * curr_y;
    assign abs_product = product[15] ? -product : product;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            index <= 3'd0;
            current_min <= 16'hFFFF;
            result <= 16'd0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;
            case(state)
                IDLE: begin
                    if (start) begin
                        index <= 3'd0;
                        current_min <= 16'hFFFF;
                        state <= CALC;
                    end
                end
                CALC: begin
                    state <= UPDATE;
                end
                UPDATE: begin
                    if (abs_product < current_min)
                        current_min <= abs_product;
                    index <= index + 1'b1;
                    if (index + 1'b1 >= num_pairs)
                        state <= FINISH;
                    else
                        state <= CALC;
                end
                FINISH: begin
                    result <= current_min;
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

