module set_left_most_unset_bit (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] n,
    output reg [31:0] result,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam CHECK = 2'b01;
    localparam COMPUTE = 2'b10;
    localparam DONE = 2'b11;

    // Internal registers
    reg [1:0] state;
    reg [1:0] next_state;
    reg [31:0] temp_n;
    reg [4:0] pos;           // Position counter (0-31)
    reg [4:0] found_pos;     // Store the leftmost unset bit position
    reg all_set_flag;        // Flag to indicate all bits are set

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 32'd0;
            done <= 1'b0;
            temp_n <= 32'd0;
            pos <= 5'd0;
            found_pos <= 5'd0;
            all_set_flag <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        temp_n <= n;
                        pos <= 5'd0;
                        found_pos <= 5'd0;
                        // Check if n == 32'hFFFFFFFF (all bits set)
                        if (n == 32'hFFFFFFFF) begin
                            all_set_flag <= 1'b1;
                        end else begin
                            all_set_flag <= 1'b0;
                        end
                    end
                end

                CHECK: begin
                    // Scan from MSB to find leftmost unset bit
                    if (pos < 31) begin
                        if (!temp_n[31]) begin
                            found_pos <= pos;
                        end
                        temp_n <= {temp_n[30:0], 1'b1}; // Shift left
                        pos <= pos + 1'b1;
                    end else begin
                        // Check bit 31 one more time
                        if (!temp_n[31]) begin
                            found_pos <= pos;
                        end
                    end
                end

                COMPUTE: begin
                    // Set the leftmost unset bit
                    if (!all_set_flag) begin
                        result <= n | (32'd1 << found_pos);
                    end else begin
                        result <= n; // All bits set, return as is
                    end
                end

                DONE: begin
                    done <= 1'b1;
                end
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) next_state = CHECK;
                else next_state = IDLE;
            end

            CHECK: begin
                if (pos >= 31) next_state = COMPUTE;
                else next_state = CHECK;
            end

            COMPUTE: begin
                next_state = DONE;
            end

            DONE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

module trapezium_median (
    input  wire        clk,        // Clock signal
    input  wire        rst_n,      // Active-low reset
    input  wire        start,      // Start computation
    input  wire [15:0] base1,      // First base (Q16.16 fixed-point)
    input  wire [15:0] base2,      // Second base (Q16.16 fixed-point)
    input  wire [15:0] height,     // Height (Q16.16 fixed-point, unused)
    output reg  [15:0] median,     // Result (Q16.16 fixed-point)
    output reg         done        // Computation complete
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam ADD  = 2'b01;
    localparam DIV2 = 2'b10;

    reg [1:0] state, next_state;
    reg [16:0] sum;  // 17-bit to hold sum of two 16-bit values

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            median <= 16'b0;
            done <= 1'b0;
            sum <= 17'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        sum <= {1'b0, base1} + {1'b0, base2};
                    end
                end

                ADD: begin
                    // Sum is already computed in IDLE
                    // Fall through to DIV2
                    median <= sum[16:1];  // Divide by 2 (shift right)
                end

                DIV2: begin
                    done <= 1'b1;
                end
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = ADD;
            ADD:  next_state = DIV2;
            DIV2: next_state = IDLE;
        endcase
    end

endmodule

module max_sub_array_repeated (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] arr_0,
    input wire [15:0] arr_1,
    input wire [15:0] arr_2,
    input wire [15:0] arr_3,
    input wire [15:0] arr_4,
    input wire [15:0] arr_5,
    input wire [15:0] arr_6,
    input wire [15:0] arr_7,
    input wire [3:0] n,           // Array length (1-8)
    input wire [3:0] k,           // Repeat count (1-3)
    output reg [31:0] result,
    output reg done
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISHED = 2'b10;

    // Internal registers
    reg [1:0] state;
    reg [7:0] iter_count;         // Total iterations: n * k
    reg [31:0] max_so_far;
    reg signed [31:0] max_ending_here;
    reg [3:0] arr_index;
    reg [2:0] cycle_delay;        // Pipeline delay counter

    // Wire to hold current array element
    reg signed [15:0] current_val;

    // Array lookup (combinational)
    always @(*) begin
        case(arr_index)
            4'd0: current_val = arr_0;
            4'd1: current_val = arr_1;
            4'd2: current_val = arr_2;
            4'd3: current_val = arr_3;
            4'd4: current_val = arr_4;
            4'd5: current_val = arr_5;
            4'd6: current_val = arr_6;
            4'd7: current_val = arr_7;
            default: current_val = 16'sd0;
        endcase
    end

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 1'b0;
            result <= 32'd0;
            max_so_far <= 32'h80000000;  // -2^31
            max_ending_here <= 32'sd0;
            iter_count <= 8'd0;
            arr_index <= 4'd0;
            cycle_delay <= 3'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPUTE;
                        iter_count <= 8'd0;
                        arr_index <= 4'd0;
                        max_so_far <= 32'h80000000;
                        max_ending_here <= 32'sd0;
                        cycle_delay <= 3'd0;
                    end
                end

                COMPUTE: begin
                    if (cycle_delay == 3'd0) begin
                        // First cycle of new element
                        if (iter_count < (n * k)) begin
                            // Calculate new max_ending_here
                            if (max_ending_here + current_val > 32'sd0) begin
                                max_ending_here <= max_ending_here + current_val;
                            end else begin
                                max_ending_here <= 32'sd0;
                            end
                            cycle_delay <= 3'd1;
                        end else begin
                            // All iterations complete
                            state <= FINISHED;
                            cycle_delay <= 3'd0;
                        end
                    end else if (cycle_delay == 3'd1) begin
                        // Update max_so_far with pipelined result
                        if (max_ending_here > max_so_far) begin
                            max_so_far <= max_ending_here;
                        end
                        cycle_delay <= 3'd2;
                    end else if (cycle_delay == 3'd2) begin
                        // Prepare for next iteration
                        iter_count <= iter_count + 1'b1;
                        arr_index <= (arr_index + 1'b1) % n;
                        cycle_delay <= 3'd0;
                    end
                end

                FINISHED: begin
                    result <= max_so_far;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module square_perimeter(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] side_length,
    output reg [15:0] perimeter,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state, next_state;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic and output logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start) begin
                    next_state = COMPUTE;
                    done = 0;
                    perimeter = 0;
                end else begin
                    next_state = IDLE;
                    done = 0;
                    perimeter = 0;
                end
            end

            COMPUTE: begin
                // Perimeter = 4 * side_length
                // Multiplication by 4 is left shift by 2
                perimeter = {2'b00, side_length, 2'b00}; // side_length << 2
                next_state = FINISH;
                done = 0;
            end

            FINISH: begin
                perimeter = perimeter; // Hold result
                done = 1;
                next_state = IDLE;
            end

            default: begin
                next_state = IDLE;
                done = 0;
                perimeter = 0;
            end
        endcase
    end

endmodule

module check_monthnumb_number(
    input [3:0] monthnum2,
    output reg has_31_days
);

// Check if month has 31 days
// Month numbers: 1=Jan, 2=Feb, 3=Mar, 4=Apr, 5=May, 6=Jun, 7=Jul, 8=Aug, 9=Sep, 10=Oct, 11=Nov, 12=Dec
// Months with 31 days: 1, 3, 5, 7, 8, 10, 12

always @(*) begin
    case (monthnum2)
        4'd1, 4'd3, 4'd5, 4'd7, 4'd8, 4'd10, 4'd12: has_31_days = 1'b1;
        default: has_31_days = 1'b0;
    endcase
end

endmodule

module substring_counter(
    input [7:0] str_len,  // Length of string (0-8)
    output reg [15:0] result  // Number of substrings
);

// Combinational logic to calculate n*(n+1)/2
always @(*) begin
    result = str_len * (str_len + 1) >> 1;
end

endmodule

// Alternative sequential version with string input:
module substring_counter_seq(
    input clk,
    input rst_n,
    input start,
    input [7:0] char_in,  // Current character (ASCII)
    input valid,          // Valid character flag
    output reg [15:0] result,
    output reg done
);

reg [3:0] count;  // Count of valid characters (max 8)
reg computing;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 4'd0;
        result <= 16'd0;
        done <= 1'b0;
        computing <= 1'b0;
    end else begin
        if (start && !computing) begin
            computing <= 1'b1;
            count <= 4'd0;
            done <= 1'b0;
        end else if (computing && valid && count < 4'd8) begin
            count <= count + 1'b1;
        end else if (computing && (!valid || count >= 4'd8)) begin
            // Computation complete: n*(n+1)/2
            result <= count * (count + 1'b1) >> 1;
            done <= 1'b1;
            computing <= 1'b0;
        end else begin
            done <= 1'b0;
        end
    end
end

endmodule

module divisor_sum_comparator (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] num1,
    input wire [15:0] num2,
    output reg [15:0] sum1,
    output reg [15:0] sum2,
    output reg done,
    output reg equivalent
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam COMPUTE_SUM1 = 3'b001;
    localparam COMPUTE_SUM2 = 3'b010;
    localparam COMPARE = 3'b011;
    localparam DONE = 3'b100;

    reg [2:0] state;
    reg [2:0] next_state;

    // Computation registers
    reg [15:0] current_num;
    reg [15:0] current_sum;
    reg [15:0] i;
    reg computing_first;  // 1 = computing num1, 0 = computing num2
    reg [15:0] temp_sum;
    reg [15:0] quotient;

    // Maximum divisor iteration bound (for safety)
    localparam MAX_ITER = 16'd256;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = COMPUTE_SUM1;
                else
                    next_state = IDLE;
            end

            COMPUTE_SUM1: begin
                // Continue until i*i > current_num or max iterations
                if ((i * i > current_num) || (i >= MAX_ITER))
                    next_state = COMPUTE_SUM2;
                else
                    next_state = COMPUTE_SUM1;
            end

            COMPUTE_SUM2: begin
                if ((i * i > current_num) || (i >= MAX_ITER))
                    next_state = COMPARE;
                else
                    next_state = COMPUTE_SUM2;
            end

            COMPARE: begin
                next_state = DONE;
            end

            DONE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output and datapath logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum1 <= 16'd0;
            sum2 <= 16'd0;
            done <= 1'b0;
            equivalent <= 1'b0;
            current_num <= 16'd0;
            current_sum <= 16'd0;
            i <= 16'd2;
            computing_first <= 1'b1;
            temp_sum <= 16'd0;
            quotient <= 16'd0;
        end else begin
            done <= 1'b0;

            case (state)
                IDLE: begin
                    if (start) begin
                        // Initialize for num1
                        current_num <= num1;
                        current_sum <= 16'd1;  // Start with 1 (1 is always a divisor)
                        i <= 16'd2;
                        computing_first <= 1'b1;
                    end
                end

                COMPUTE_SUM1, COMPUTE_SUM2: begin
                    if (i * i <= current_num && i < MAX_ITER) begin
                        if (current_num % i == 16'd0) begin
                            quotient <= current_num / i;
                            // Check for perfect square
                            if (i * i == current_num) begin
                                current_sum <= current_sum + i;
                            end else begin
                                current_sum <= current_sum + i + (current_num / i);
                            end
                        end
                        i <= i + 16'd1;
                    end
                end

                COMPARE: begin
                    if (computing_first) begin
                        // Finished num1, setup for num2
                        sum1 <= current_sum;
                        current_num <= num2;
                        current_sum <= 16'd1;
                        i <= 16'd2;
                        computing_first <= 1'b0;
                        // Re-trigger COMPUTE_SUM2 on next cycle
                    end else begin
                        // Finished num2, do comparison
                        sum2 <= current_sum;
                        equivalent <= (sum1 == current_sum);
                    end
                end

                DONE: begin
                    done <= 1'b1;
                end
            endcase
        end
    end

endmodule

module cone_volume (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] radius,      // 16-bit unsigned radius
    input wire [15:0] height,      // 16-bit unsigned height
    output reg [31:0] volume,      // 32-bit fixed-point Q16.16 result
    output reg done
);

    // Fixed-point constants (Q16.16 format)
    // pi = 3.14159265 * 65536 = 205887
    // one_third = 0.33333333 * 65536 = 21845
    localparam PI_FIXED = 205887;
    localparam ONE_THIRD = 21845;

    // State machine
    reg [2:0] state;
    reg [31:0] r_squared;
    reg [31:0] r_squared_h;
    reg [31:0] temp_result;

    // State definitions
    localparam IDLE = 3'b000;
    localparam CALC_R2 = 3'b001;
    localparam CALC_R2H = 3'b010;
    localparam CALC_PI = 3'b011;
    localparam CALC_THIRD = 3'b100;
    localparam DONE_STATE = 3'b101;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            volume <= 0;
            r_squared <= 0;
            r_squared_h <= 0;
            temp_result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= CALC_R2;
                    end
                end

                CALC_R2: begin
                    // r_squared = radius * radius (16-bit * 16-bit = 32-bit)
                    r_squared <= radius * radius;
                    state <= CALC_R2H;
                end

                CALC_R2H: begin
                    // r_squared_h = r_squared * height (32-bit * 16-bit = 48-bit, truncate to 32-bit)
                    r_squared_h <= r_squared[31:0] * height;
                    state <= CALC_PI;
                end

                CALC_PI: begin
                    // Multiply by pi (21845 * 205887, then shift by 16 bits)
                    temp_result <= (r_squared_h * PI_FIXED) >> 16;
                    state <= CALC_THIRD;
                end

                CALC_THIRD: begin
                    // Multiply by 1/3 (divide by 3 using multiplication by 21845, shift by 16)
                    volume <= (temp_result * ONE_THIRD) >> 16;
                    state <= DONE_STATE;
                end

                DONE_STATE: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module square_sum (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] n,
    output reg [15:0] result,
    output reg done
);

// Combinational formula: 2*n*(n+1)*(2*n+1)/3
// Supports n from 0 to 8 (max result: 120 for n=4, fits in 16 bits)
// All operations use unsigned integer arithmetic

reg [15:0] temp1, temp2, temp3;

always @(*) begin
    // Compute: 2*n*(n+1)*(2*n+1)/3
    temp1 = n + 8'd1;                    // (n+1)
    temp2 = 2*n + 8'd1;                  // (2*n+1)
    temp3 = (2*n) * temp1;               // 2*n*(n+1)
    result = (temp3 * temp2) / 3;        // divide by 3
end

// Sequential interface
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 1'b0;
    end else if (start) begin
        done <= 1'b1;  // result is combinational, pulse done
    end else begin
        done <= 1'b0;
    end
end

endmodule

