module first_digit_finder (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] num_in,
    output reg [7:0] first_digit,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam COMPLETE = 2'b10;

    // Internal registers
    reg [1:0] state;
    reg [1:0] next_state;
    reg [7:0] current_num;
    reg [7:0] next_current_num;

    // Maximum 8 iterations for 8-bit number (log2(256) = 8)
    reg [3:0] iteration_count;
    reg [3:0] next_iteration_count;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            current_num <= 8'b0;
            iteration_count <= 4'b0;
        end else begin
            state <= next_state;
            current_num <= next_current_num;
            iteration_count <= next_iteration_count;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        next_current_num = current_num;
        next_iteration_count = iteration_count;

        case (state)
            IDLE: begin
                if (start) begin
                    next_state = COMPUTE;
                    next_current_num = num_in;
                    next_iteration_count = 4'b0;
                end
            end

            COMPUTE: begin
                if (current_num >= 8'd10 && iteration_count < 4'd8) begin
                    // Divide by 10 (current_num / 10)
                    next_current_num = current_num / 8'd10;
                    next_iteration_count = iteration_count + 1'b1;
                end else begin
                    next_state = COMPLETE;
                end
            end

            COMPLETE: begin
                next_state = IDLE;
            end

            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always @(*) begin
        if (state == COMPLETE) begin
            first_digit = current_num;
            done = 1'b1;
        end else begin
            first_digit = 8'b0;
            done = 1'b0;
        end
    end

endmodule

module snake_to_camel (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,      // Current input character (ASCII)
    input wire [3:0] char_index,   // Index of current character (0-7)
    input wire input_valid,        // High when char_in is valid
    output reg [7:0] char_out,     // Output character
    output reg [3:0] out_index,    // Index of output character
    output reg output_valid,       // High when char_out is valid
    output reg done               // High when conversion complete
);

    // Parameters
    parameter MAX_LEN = 8;
    parameter UNDERSCORE = 8'h5F;
    parameter LOWER_A = 8'h61;
    parameter LOWER_Z = 8'h7A;
    parameter TO_UPPER = 8'h20;

    // State machine states
    parameter IDLE = 3'b000;
    parameter READ_CHAR = 3'b001;
    parameter CHECK_UNDERSCORE = 3'b010;
    parameter CAPITALIZE = 3'b011;
    parameter OUTPUT_CHAR = 3'b100;
    parameter WAIT_DONE = 3'b101;

    // Internal registers
    reg [2:0] state, next_state;
    reg [7:0] input_buffer [0:7];  // Store input string
    reg [3:0] in_idx, out_idx;      // Input and output indices
    reg [3:0] read_count;           // Characters read
    reg capitalize_next;            // Flag to capitalize next character
    reg [7:0] current_char;         // Current character being processed

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = READ_CHAR;
                else
                    next_state = IDLE;
            end

            READ_CHAR: begin
                if (input_valid && read_count < MAX_LEN)
                    next_state = CHECK_UNDERSCORE;
                else if (!input_valid || read_count >= MAX_LEN)
                    next_state = WAIT_DONE;
                else
                    next_state = READ_CHAR;
            end

            CHECK_UNDERSCORE: begin
                if (current_char == UNDERSCORE) begin
                    next_state = READ_CHAR;
                end else begin
                    next_state = CAPITALIZE;
                end
            end

            CAPITALIZE: begin
                next_state = OUTPUT_CHAR;
            end

            OUTPUT_CHAR: begin
                if (out_idx < MAX_LEN)
                    next_state = READ_CHAR;
                else
                    next_state = WAIT_DONE;
            end

            WAIT_DONE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            char_out <= 8'h00;
            out_index <= 4'b0000;
            output_valid <= 1'b0;
            done <= 1'b0;
            in_idx <= 4'b0000;
            read_count <= 4'b0000;
            capitalize_next <= 1'b1;  // First character always capitalized
        end else begin
            case (state)
                IDLE: begin
                    output_valid <= 1'b0;
                    done <= 1'b0;
                    in_idx <= 4'b0000;
                    out_idx <= 4'b0000;
                    read_count <= 4'b0000;
                    capitalize_next <= 1'b1;
                end

                READ_CHAR: begin
                    if (input_valid && read_count < MAX_LEN) begin
                        input_buffer[in_idx] <= char_in;
                        current_char <= char_in;
                        in_idx <= in_idx + 1;
                        read_count <= read_count + 1;
                    end
                end

                CHECK_UNDERSCORE: begin
                    // State remains stable for decision
                end

                CAPITALIZE: begin
                    if (capitalize_next && (current_char >= LOWER_A) && (current_char <= LOWER_Z)) begin
                        char_out <= current_char - TO_UPPER;
                    end else begin
                        char_out <= current_char;
                    end

                    // Reset capitalize flag unless we just output a capitalized letter
                    capitalize_next <= 1'b0;
                end

                OUTPUT_CHAR: begin
                    output_valid <= 1'b1;
                    out_index <= out_idx;
                    out_idx <= out_idx + 1;

                    // Set capitalize_next for next word
                    if (current_char == UNDERSCORE) begin
                        capitalize_next <= 1'b1;
                    end
                end

                WAIT_DONE: begin
                    output_valid <= 1'b0;
                    done <= 1'b1;
                end
            endcase
        end
    end

endmodule

module next_smallest_palindrome (
    input [7:0] num,           // Input number (0-255)
    output reg [15:0] result,  // Result (max 9999 for 3-digit inputs)
    output reg valid           // Valid output flag
);

// Find next palindrome for 8-bit input
// Palindromes can be 1, 2, or 3 digits
// Combinational logic checks from num+1 upward

integer i;
reg [15:0] candidate;
reg [7:0] rev;

always @(*) begin
    valid = 1'b0;
    result = 16'd0;

    // Search from num+1 to 999 (bounded search)
    for (i = num + 1; i <= 999; i = i + 1) begin
        candidate = i;

        // Reverse digits manually
        if (candidate < 10) begin
            // 1-digit: always palindrome
            result = candidate;
            valid = 1'b1;
            disable next_smallest_palindrome; // Break
        end else if (candidate < 100) begin
            // 2-digit: check if digits equal
            if ((candidate / 10) == (candidate % 10)) begin
                result = candidate;
                valid = 1'b1;
                disable next_smallest_palindrome;
            end
        end else begin
            // 3-digit: check first == last
            if ((candidate / 100) == (candidate % 10)) begin
                result = candidate;
                valid = 1'b1;
                disable next_smallest_palindrome;
            end
        end
    end
end

endmodule

module check_greater(
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [7:0] number,
    output reg result,
    output reg done
);

    parameter ARRAY_SIZE = 8;
    parameter MAX_CYCLES = 20;

    reg [2:0] cycle_count;
    reg [7:0] current_max;
    reg [2:0] index;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 1'b0;
            done <= 1'b0;
            cycle_count <= 3'b0;
            current_max <= 8'b0;
            index <= 3'b0;
        end else begin
            if (start && !done) begin
                cycle_count <= 3'b0;
                current_max <= arr_0;
                index <= 3'b1;
                done <= 1'b0;
                result <= 1'b0;
            end else if (cycle_count < ARRAY_SIZE && !done) begin
                cycle_count <= cycle_count + 1;

                case (index)
                    3'd1: current_max <= (arr_1 > current_max) ? arr_1 : current_max;
                    3'd2: current_max <= (arr_2 > current_max) ? arr_2 : current_max;
                    3'd3: current_max <= (arr_3 > current_max) ? arr_3 : current_max;
                    3'd4: current_max <= (arr_4 > current_max) ? arr_4 : current_max;
                    3'd5: current_max <= (arr_5 > current_max) ? arr_5 : current_max;
                    3'd6: current_max <= (arr_6 > current_max) ? arr_6 : current_max;
                    3'd7: current_max <= (arr_7 > current_max) ? arr_7 : current_max;
                    default: current_max <= current_max;
                endcase

                index <= index + 1;
            end else if (cycle_count == ARRAY_SIZE && !done) begin
                result <= (number > current_max);
                done <= 1'b1;
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

module sequence_counter(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [4:0] m,
    input wire [2:0] n,
    output reg [15:0] result,
    output reg done
);

    // FSM states
    reg [2:0] state;
    localparam IDLE = 3'b000;
    localparam INIT_BASE = 3'b001;
    localparam COMPUTE = 3'b010;
    localparam FINISH = 3'b110;

    // Table storage: T[17][5] for i=0..16, j=0..4
    reg [15:0] T[16:0][4:0];

    // Iteration counters
    reg [4:0] i;
    reg [2:0] j;

    // Computation registers
    reg [15:0] temp_sum;
    reg [4:0] i_half;
    reg computing;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 0;
            done <= 0;
            i <= 0;
            j <= 0;
            computing <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        i <= 0;
                        j <= 0;
                        state <= INIT_BASE;
                    end
                end

                INIT_BASE: begin
                    // Initialize all base cases
                    if (i == 0 || j == 0 || i < j) begin
                        T[i][j] <= 0;
                    end else if (j == 1) begin
                        T[i][j] <= i;
                    end else begin
                        // Will compute in next state
                        state <= COMPUTE;
                        computing <= 1;
                        i_half <= i >> 1;
                        temp_sum <= T[i-1][j];
                        // Stay at same i,j for computation
                        i <= i;
                        j <= j;
                        computing <= 1;
                        state <= COMPUTE;
                        i_half <= i >> 1;
                        temp_sum <= T[i-1][j];
                    end

                    // Move to next cell
                    if (j < 4 && j < n) begin
                        j <= j + 1;
                    end else begin
                        j <= 0;
                        if (i < 16 && i < m) begin
                            i <= i + 1;
                        end else if (i == m && j == 0) begin
                            // All initialized, now compute recursively
                            i <= 2;
                            j <= 2;
                            computing <= 0;
                            state <= COMPUTE;
                        end else begin
                            i <= i + 1;
                            j <= 0;
                        end
                    end
                end

                COMPUTE: begin
                    if (computing) begin
                        // Complete recursive computation
                        if (j > 1 && i_half > 0) begin
                            temp_sum <= temp_sum + T[i_half][j-1];
                        end
                        T[i][j] <= temp_sum;
                        computing <= 0;
                        // Move to next entry
                        if (j < 4 && j < n) begin
                            j <= j + 1;
                        end else begin
                            j <= 2;
                            if (i < 16 && i < m) begin
                                i <= i + 1;
                            end else begin
                                result <= T[m][n];
                                done <= 1;
                                state <= FINISH;
                            end
                        end
                    end else if (i <= m && j <= n) begin
                        // Check if base case
                        if (i < j || j == 0 || j == 1) begin
                            // Skip or already initialized
                            if (j < n) begin
                                j <= j + 1;
                            end else begin
                                j <= 2;
                                if (i < m) begin
                                    i <= i + 1;
                                end else begin
                                    result <= T[m][n];
                                    done <= 1;
                                    state <= FINISH;
                                end
                            end
                        end else begin
                            // Need to compute
                            computing <= 1;
                            i_half <= i >> 1;
                            temp_sum <= T[i-1][j];
                        end
                    end
                end

                FINISH: begin
                    done <= 0;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module word_len(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,
    input wire valid_in,
    output reg result,
    output reg done
);

// Parameters for string processing
parameter MAX_LEN = 16; // Maximum string length
parameter CLK_TIMEOUT = 100; // Maximum cycles

// Internal state
reg [3:0] len_counter; // Count characters (0-15)
reg processing;
reg result_reg;
reg [3:0] cycle_counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        len_counter <= 4'b0;
        processing <= 1'b0;
        result_reg <= 1'b0;
        done <= 1'b0;
        cycle_counter <= 4'b0;
    end else begin
        if (start && !processing) begin
            // Start new computation
            len_counter <= 4'b0;
            processing <= 1'b1;
            result_reg <= 1'b0;
            done <= 1'b0;
            cycle_counter <= 4'b0;
        end else if (processing) begin
            if (valid_in) begin
                // Count non-zero characters
                if (char_in != 8'h00 && len_counter < MAX_LEN) begin
                    len_counter <= len_counter + 1;
                end
            end

            // Check for end condition or timeout
            cycle_counter <= cycle_counter + 1;

            if (!valid_in || len_counter >= MAX_LEN || cycle_counter >= CLK_TIMEOUT) begin
                // Compute result: true if length is odd
                result_reg <= (len_counter[0] == 1'b1) && (len_counter > 0);
                done <= 1'b1;
                processing <= 1'b0;
            end
        end else begin
            done <= 1'b0;
        end
    end
end

assign result = result_reg;

endmodule

module remove_odd (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    input wire [3:0] len,  // Number of valid elements (1-8)
    output reg [7:0] out_0, out_1, out_2, out_3, out_4, out_5, out_6, out_7,
    output reg [3:0] out_len,
    output reg done
);

    // State machine states
    reg [1:0] state;
    reg [3:0] idx;
    reg [3:0] write_idx;

    localparam IDLE = 2'b00;
    localparam PROCESS = 2'b01;
    localparam COMPLETE = 2'b10;

    // Input buffer (for pipelined access)
    reg [7:0] buffer [0:7];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 0;
            write_idx <= 0;
            out_len <= 0;
            done <= 0;
            // Clear outputs
            out_0 <= 0; out_1 <= 0; out_2 <= 0; out_3 <= 0;
            out_4 <= 0; out_5 <= 0; out_6 <= 0; out_7 <= 0;
            // Clear buffer
            buffer[0] <= 0; buffer[1] <= 0; buffer[2] <= 0; buffer[3] <= 0;
            buffer[4] <= 0; buffer[5] <= 0; buffer[6] <= 0; buffer[7] <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load input buffer
                        buffer[0] <= arr_0;
                        buffer[1] <= arr_1;
                        buffer[2] <= arr_2;
                        buffer[3] <= arr_3;
                        buffer[4] <= arr_4;
                        buffer[5] <= arr_5;
                        buffer[6] <= arr_6;
                        buffer[7] <= arr_7;
                        idx <= 0;
                        write_idx <= 0;
                        out_len <= 0;
                        state <= PROCESS;
                        // Clear outputs
                        out_0 <= 0; out_1 <= 0; out_2 <= 0; out_3 <= 0;
                        out_4 <= 0; out_5 <= 0; out_6 <= 0; out_7 <= 0;
                    end
                end

                PROCESS: begin
                    if (idx < len) begin
                        // Check if number is even (LSB = 0)
                        if (buffer[idx][0] == 1'b0) begin
                            // Even number - write to output
                            case (write_idx)
                                0: out_0 <= buffer[idx];
                                1: out_1 <= buffer[idx];
                                2: out_2 <= buffer[idx];
                                3: out_3 <= buffer[idx];
                                4: out_4 <= buffer[idx];
                                5: out_5 <= buffer[idx];
                                6: out_6 <= buffer[idx];
                                7: out_7 <= buffer[idx];
                            endcase
                            write_idx <= write_idx + 1;
                        end
                        idx <= idx + 1;
                    end else begin
                        // Processing complete
                        out_len <= write_idx;
                        state <= COMPLETE;
                    end
                end

                COMPLETE: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module lateral_surface_cube (
    input [7:0] side_length,
    output [15:0] area
);

// Lateral surface area = 4 * side * side
// Input: side_length (8-bit, values 0-255)
// Output: area (16-bit, can hold 4*255*255 = 260100)

assign area = 4 * side_length * side_length;

endmodule

module max_length (
    input wire clk,
    input wire rst_n,
    input wire start,

    // 2D array: 8 sublists, each 8 elements
    // We use individual port naming for compatibility
    input wire [7:0] arr_0_0, arr_0_1, arr_0_2, arr_0_3, arr_0_4, arr_0_5, arr_0_6, arr_0_7,
    input wire [7:0] arr_1_0, arr_1_1, arr_1_2, arr_1_3, arr_1_4, arr_1_5, arr_1_6, arr_1_7,
    input wire [7:0] arr_2_0, arr_2_1, arr_2_2, arr_2_3, arr_2_4, arr_2_5, arr_2_6, arr_2_7,
    input wire [7:0] arr_3_0, arr_3_1, arr_3_2, arr_3_3, arr_3_4, arr_3_5, arr_3_6, arr_3_7,
    input wire [7:0] arr_4_0, arr_4_1, arr_4_2, arr_4_3, arr_4_4, arr_4_5, arr_4_6, arr_4_7,
    input wire [7:0] arr_5_0, arr_5_1, arr_5_2, arr_5_3, arr_5_4, arr_5_5, arr_5_6, arr_5_7,
    input wire [7:0] arr_6_0, arr_6_1, arr_6_2, arr_6_3, arr_6_4, arr_6_5, arr_6_6, arr_6_7,
    input wire [7:0] arr_7_0, arr_7_1, arr_7_2, arr_7_3, arr_7_4, arr_7_5, arr_7_6, arr_7_7,

    // Length of each sublist (1-8 elements, 0 means empty/not used)
    input wire [3:0] len_0, len_1, len_2, len_3, len_4, len_5, len_6, len_7,

    output reg [3:0] max_len,
    output reg [7:0] max_list_0, max_list_1, max_list_2, max_list_3,
    output reg [7:0] max_list_4, max_list_5, max_list_6, max_list_7,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    reg [1:0] state;
    reg [2:0] sublist_idx;  // 0-7 for 8 sublists
    reg [3:0] current_len;
    reg [2:0] copy_idx;  // For copying longest list
    reg copy_valid;

    // Input array storage (flattened)
    reg [7:0] arr [0:7][0:7];
    reg [3:0] lens [0:7];

    integer i, j;

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            max_len <= 4'd0;
            done <= 1'b0;
            sublist_idx <= 3'd0;
            copy_idx <= 3'd0;
            copy_valid <= 1'b0;
            // Clear storage
            for (i = 0; i < 8; i = i + 1) begin
                lens[i] <= 4'd0;
                for (j = 0; j < 8; j = j + 1) begin
                    arr[i][j] <= 8'd0;
                end
            end
            // Clear outputs
            max_list_0 <= 8'd0; max_list_1 <= 8'd0; max_list_2 <= 8'd0; max_list_3 <= 8'd0;
            max_list_4 <= 8'd0; max_list_5 <= 8'd0; max_list_6 <= 8'd0; max_list_7 <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // Store inputs
                        arr[0][0] <= arr_0_0; arr[0][1] <= arr_0_1; arr[0][2] <= arr_0_2; arr[0][3] <= arr_0_3;
                        arr[0][4] <= arr_0_4; arr[0][5] <= arr_0_5; arr[0][6] <= arr_0_6; arr[0][7] <= arr_0_7;
                        arr[1][0] <= arr_1_0; arr[1][1] <= arr_1_1; arr[1][2] <= arr_1_2; arr[1][3] <= arr_1_3;
                        arr[1][4] <= arr_1_4; arr[1][5] <= arr_1_5; arr[1][6] <= arr_1_6; arr[1][7] <= arr_1_7;
                        arr[2][0] <= arr_2_0; arr[2][1] <= arr_2_1; arr[2][2] <= arr_2_2; arr[2][3] <= arr_2_3;
                        arr[2][4] <= arr_2_4; arr[2][5] <= arr_2_5; arr[2][6] <= arr_2_6; arr[2][7] <= arr_2_7;
                        arr[3][0] <= arr_3_0; arr[3][1] <= arr_3_1; arr[3][2] <= arr_3_2; arr[3][3] <= arr_3_3;
                        arr[3][4] <= arr_3_4; arr[3][5] <= arr_3_5; arr[3][6] <= arr_3_6; arr[3][7] <= arr_3_7;
                        arr[4][0] <= arr_4_0; arr[4][1] <= arr_4_1; arr[4][2] <= arr_4_2; arr[4][3] <= arr_4_3;
                        arr[4][4] <= arr_4_4; arr[4][5] <= arr_4_5; arr[4][6] <= arr_4_6; arr[4][7] <= arr_4_7;
                        arr[5][0] <= arr_5_0; arr[5][1] <= arr_5_1; arr[5][2] <= arr_5_2; arr[5][3] <= arr_5_3;
                        arr[5][4] <= arr_5_4; arr[5][5] <= arr_5_5; arr[5][6] <= arr_5_6; arr[5][7] <= arr_5_7;
                        arr[6][0] <= arr_6_0; arr[6][1] <= arr_6_1; arr[6][2] <= arr_6_2; arr[6][3] <= arr_6_3;
                        arr[6][4] <= arr_6_4; arr[6][5] <= arr_6_5; arr[6][6] <= arr_6_6; arr[6][7] <= arr_6_7;
                        arr[7][0] <= arr_7_0; arr[7][1] <= arr_7_1; arr[7][2] <= arr_7_2; arr[7][3] <= arr_7_3;
                        arr[7][4] <= arr_7_4; arr[7][5] <= arr_7_5; arr[7][6] <= arr_7_6; arr[7][7] <= arr_7_7;

                        lens[0] <= len_0; lens[1] <= len_1; lens[2] <= len_2; lens[3] <= len_3;
                        lens[4] <= len_4; lens[5] <= len_5; lens[6] <= len_6; lens[7] <= len_7;

                        max_len <= 4'd0;
                        max_list_0 <= 8'd0; max_list_1 <= 8'd0; max_list_2 <= 8'd0; max_list_3 <= 8'd0;
                        max_list_4 <= 8'd0; max_list_5 <= 8'd0; max_list_6 <= 8'd0; max_list_7 <= 8'd0;

                        sublist_idx <= 3'd0;
                        state <= COMPUTE;
                    end
                end

                COMPUTE: begin
                    // Compare current sublist length with max
                    if (lens[sublist_idx] > max_len) begin
                        max_len <= lens[sublist_idx];
                        copy_idx <= 3'd0;
                        copy_valid <= 1'b1;
                    end else begin
                        copy_valid <= 1'b0;
                    end

                    // Move to next sublist
                    if (sublist_idx < 3'd7) begin
                        sublist_idx <= sublist_idx + 3'd1;
                    end else if (copy_valid) begin
                        // Start copying after checking all
                        state <= FINISH;
                    end else begin
                        // Done without copying
                        done <= 1'b1;
                        state <= IDLE;
                    end
                end

                FINISH: begin
                    // Copy the longest list
                    if (copy_idx < max_len) begin
                        case (sublist_idx)
                            3'd0: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[0][0];
                                    4'd1: max_list_1 <= arr[0][1];
                                    4'd2: max_list_2 <= arr[0][2];
                                    4'd3: max_list_3 <= arr[0][3];
                                    4'd4: max_list_4 <= arr[0][4];
                                    4'd5: max_list_5 <= arr[0][5];
                                    4'd6: max_list_6 <= arr[0][6];
                                    4'd7: max_list_7 <= arr[0][7];
                                endcase
                            end
                            3'd1: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[1][0];
                                    4'd1: max_list_1 <= arr[1][1];
                                    4'd2: max_list_2 <= arr[1][2];
                                    4'd3: max_list_3 <= arr[1][3];
                                    4'd4: max_list_4 <= arr[1][4];
                                    4'd5: max_list_5 <= arr[1][5];
                                    4'd6: max_list_6 <= arr[1][6];
                                    4'd7: max_list_7 <= arr[1][7];
                                endcase
                            end
                            3'd2: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[2][0];
                                    4'd1: max_list_1 <= arr[2][1];
                                    4'd2: max_list_2 <= arr[2][2];
                                    4'd3: max_list_3 <= arr[2][3];
                                    4'd4: max_list_4 <= arr[2][4];
                                    4'd5: max_list_5 <= arr[2][5];
                                    4'd6: max_list_6 <= arr[2][6];
                                    4'd7: max_list_7 <= arr[2][7];
                                endcase
                            end
                            3'd3: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[3][0];
                                    4'd1: max_list_1 <= arr[3][1];
                                    4'd2: max_list_2 <= arr[3][2];
                                    4'd3: max_list_3 <= arr[3][3];
                                    4'd4: max_list_4 <= arr[3][4];
                                    4'd5: max_list_5 <= arr[3][5];
                                    4'd6: max_list_6 <= arr[3][6];
                                    4'd7: max_list_7 <= arr[3][7];
                                endcase
                            end
                            3'd4: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[4][0];
                                    4'd1: max_list_1 <= arr[4][1];
                                    4'd2: max_list_2 <= arr[4][2];
                                    4'd3: max_list_3 <= arr[4][3];
                                    4'd4: max_list_4 <= arr[4][4];
                                    4'd5: max_list_5 <= arr[4][5];
                                    4'd6: max_list_6 <= arr[4][6];
                                    4'd7: max_list_7 <= arr[4][7];
                                endcase
                            end
                            3'd5: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[5][0];
                                    4'd1: max_list_1 <= arr[5][1];
                                    4'd2: max_list_2 <= arr[5][2];
                                    4'd3: max_list_3 <= arr[5][3];
                                    4'd4: max_list_4 <= arr[5][4];
                                    4'd5: max_list_5 <= arr[5][5];
                                    4'd6: max_list_6 <= arr[5][6];
                                    4'd7: max_list_7 <= arr[5][7];
                                endcase
                            end
                            3'd6: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[6][0];
                                    4'd1: max_list_1 <= arr[6][1];
                                    4'd2: max_list_2 <= arr[6][2];
                                    4'd3: max_list_3 <= arr[6][3];
                                    4'd4: max_list_4 <= arr[6][4];
                                    4'd5: max_list_5 <= arr[6][5];
                                    4'd6: max_list_6 <= arr[6][6];
                                    4'd7: max_list_7 <= arr[6][7];
                                endcase
                            end
                            3'd7: begin
                                case (copy_idx)
                                    4'd0: max_list_0 <= arr[7][0];
                                    4'd1: max_list_1 <= arr[7][1];
                                    4'd2: max_list_2 <= arr[7][2];
                                    4'd3: max_list_3 <= arr[7][3];
                                    4'd4: max_list_4 <= arr[7][4];
                                    4'd5: max_list_5 <= arr[7][5];
                                    4'd6: max_list_6 <= arr[7][6];
                                    4'd7: max_list_7 <= arr[7][7];
                                endcase
                            end
                        endcase
                        copy_idx <= copy_idx + 3'd1;
                    end else begin
                        done <= 1'b1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

module lucas_number (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [4:0] n,  // n value (0-16)
    output reg [31:0] result,
    output reg done
);

    // FSM states
    parameter IDLE = 3'b000;
    parameter COMPUTE = 3'b001;
    parameter ITERATE = 3'b010;
    parameter FINISH = 3'b011;

    reg [2:0] state, next_state;
    reg [4:0] current_n;
    reg [31:0] a, b;  // L(i-1) and L(i-2)
    reg [31:0] next_a, next_b;

    // Lucas number lookup for base cases
    function [31:0] lucas_base;
        input [4:0] idx;
        begin
            case(idx)
                5'd0: lucas_base = 32'd2;
                5'd1: lucas_base = 32'd1;
                default: lucas_base = 32'd0;
            endcase
        end
    endfunction

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 32'd0;
            done <= 1'b0;
            current_n <= 5'd0;
            a <= 32'd0;
            b <= 32'd0;
        end else begin
            state <= next_state;
            if (state == IDLE && start) begin
                current_n <= n;
                // Initialize for iteration
                if (n == 5'd0) begin
                    result <= 32'd2;
                end else if (n == 5'd1) begin
                    result <= 32'd1;
                end
            end else if (state == COMPUTE) begin
                a <= next_a;
                b <= next_b;
                current_n <= current_n - 5'd1;
            end else if (state == ITERATE) begin
                a <= next_a;
                b <= next_b;
                current_n <= current_n - 5'd1;
            end else if (state == FINISH) begin
                result <= a;
                done <= 1'b1;
            end else if (state == IDLE) begin
                done <= 1'b0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        next_a = a;
        next_b = b;

        case(state)
            IDLE: begin
                if (start) begin
                    if (n <= 5'd1) begin
                        next_state = FINISH;
                    end else begin
                        next_state = COMPUTE;
                        next_a = 32'd1;  // L(1)
                        next_b = 32'd2;  // L(0)
                    end
                end
            end

            COMPUTE: begin
                next_a = a + b;  // L(i) = L(i-1) + L(i-2)
                next_b = a;
                if (current_n <= 5'd2) begin
                    next_state = FINISH;
                end else begin
                    next_state = ITERATE;
                end
            end

            ITERATE: begin
                next_a = a + b;
                next_b = a;
                if (current_n <= 5'd1) begin
                    next_state = FINISH;
                end else begin
                    next_state = ITERATE;
                end
            end

            FINISH: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

module find_even_pair (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] len,
    output reg [15:0] result,
    output reg done
);

    localparam STATE_IDLE = 2'b00;
    localparam STATE_COUNT = 2'b01;
    localparam STATE_CALC = 2'b10;
    localparam STATE_DONE = 2'b11;

    reg [1:0] state;
    reg [3:0] idx;
    reg [3:0] odd_count;
    reg [3:0] even_count;
    reg [7:0] current_val;

    always @(*) begin
        case (idx)
            4'd0: current_val = arr_0;
            4'd1: current_val = arr_1;
            4'd2: current_val = arr_2;
            4'd3: current_val = arr_3;
            4'd4: current_val = arr_4;
            4'd5: current_val = arr_5;
            4'd6: current_val = arr_6;
            4'd7: current_val = arr_7;
            default: current_val = 8'd0;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= STATE_IDLE;
            result <= 16'd0;
            done <= 1'b0;
            idx <= 4'd0;
            odd_count <= 4'd0;
            even_count <= 4'd0;
        end else begin
            case (state)
                STATE_IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= STATE_COUNT;
                        idx <= 4'd0;
                        odd_count <= 4'd0;
                        even_count <= 4'd0;
                    end
                end

                STATE_COUNT: begin
                    if (idx < len) begin
                        if (current_val[0]) begin
                            odd_count <= odd_count + 1'b1;
                        end else begin
                            even_count <= even_count + 1'b1;
                        end
                        idx <= idx + 1'b1;
                    end else begin
                        state <= STATE_CALC;
                        result <= 16'd0;
                        idx <= 4'd0;
                    end
                end

                STATE_CALC: begin
                    case (idx)
                        4'd0: begin
                            result <= odd_count * (odd_count - 1'b1);
                            idx <= idx + 1'b1;
                        end
                        4'd1: begin
                            result <= result + (even_count * (even_count - 1'b1));
                            idx <= idx + 1'b1;
                        end
                        4'd2: begin
                            result <= result >> 1;
                            state <= STATE_DONE;
                        end
                    endcase
                end

                STATE_DONE: begin
                    done <= 1'b1;
                    state <= STATE_IDLE;
                end
            endcase
        end
    end

endmodule

