module next_power_of_2 (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] n,          // 8-bit input number (0-255)
    output reg [8:0] result,      // 9-bit output (max: 256)
    output reg done               // Done signal, high for 1 cycle
);

    localparam IDLE = 2'd0;
    localparam CALC = 2'd1;
    localparam CHECK = 2'd2;
    localparam FINISH = 2'd3;

    reg [1:0] state;
    reg [7:0] temp_n;
    reg [7:0] original_n;         // Keep original n
    reg [3:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 9'd0;
            done <= 1'b0;
            temp_n <= 8'd0;
            original_n <= 8'd0;
            count <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        if (n == 8'd0) begin
                            result <= 9'd1;
                            done <= 1'b1;
                            state <= FINISH;
                        end else begin
                            original_n <= n;
                            temp_n <= n;
                            count <= 4'd0;
                            state <= CALC;
                        end
                    end
                end

                CALC: begin
                    if (temp_n != 8'd0) begin
                        temp_n <= {1'b0, temp_n[7:1]};
                        count <= count + 1'b1;
                    end else begin
                        state <= CHECK;
                    end
                end

                CHECK: begin
                    // count is number of bits in original_n
                    // Check if original_n is already power of 2
                    // Power of 2 has only one bit set: original_n & (original_n-1) == 0
                    // But we need original_n for this
                    // Easier: compute 1 << (count-1) and compare with original_n
                    // Since count is at least 1 here

                    if (count > 4'd1 && (original_n & (original_n - 1'b1)) == 8'd0) begin
                        // Already power of 2
                        result <= {1'b0, original_n};
                    end else begin
                        result <= 1 << count;
                    end
                    done <= 1'b1;
                    state <= FINISH;
                end

                FINISH: begin
                    done <= 1'b0;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module sphere_volume(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] radius,  // 16-bit unsigned radius (scaled by 256 for fractional input)
    output reg [31:0] volume,   // 32-bit result in Q16.16 format
    output reg done
);

    // Fixed-point constants for Q16.16 format
    // PI = 3.141592653589793 * 65536 = 205887
    localparam PI_FIXED = 205887;
    // 4/3 = 1.333333333333333 * 65536 = 87381
    localparam FOUR_THIRDS = 87381;

    // State machine states
    localparam IDLE = 3'b000;
    localparam COMPUTE_R2 = 3'b001;
    localparam COMPUTE_R3 = 3'b010;
    localparam COMPUTE_R3_PI = 3'b011;
    localparam COMPUTE_FINAL = 3'b100;
    localparam DONE_STATE = 3'b101;

    reg [2:0] state;
    reg [31:0] r2;      // r^2
    reg [31:0] r3;      // r^3
    reg [47:0] temp;    // 48-bit intermediate

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            volume <= 0;
            done <= 0;
            r2 <= 0;
            r3 <= 0;
            temp <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= COMPUTE_R2;
                        // Scale radius: radius is provided as value * 256
                        // r2 = (radius * radius) / 256 = radius * radius >> 8
                        r2 <= (radius * radius) >> 8;
                    end
                end

                COMPUTE_R2: begin
                    // r3 = (r2 * radius) / 256
                    // r2 is already scaled, multiply then shift
                    r3 <= (r2 * radius) >> 8;
                    state <= COMPUTE_R3;
                end

                COMPUTE_R3: begin
                    // Multiply r3 by PI, result scaled by 256 (from r3) * 65536 = 16777216
                    // temp = r3 * PI_FIXED
                    temp <= r3 * PI_FIXED;
                    state <= COMPUTE_R3_PI;
                end

                COMPUTE_R3_PI: begin
                    // Shift right by 16 to get Q16.16 format (remove extra scaling)
                    // temp is now r3 * PI, we need to divide by 256 (from radius scaling)
                    // temp >> 16 gives r3 * PI in Q16.16, but r3 still needs division by 256
                    // So: temp >> (16 + 8) = temp >> 24
                    temp <= temp >> 8;  // First shift 8 to divide by 256
                    state <= COMPUTE_FINAL;
                end

                COMPUTE_FINAL: begin
                    // Multiply by 4/3 and scale to Q16.16
                    // temp is now r3 * PI / 256 (value in Q16.16)
                    // Multiply by FOUR_THIRDS (1.3333... in Q16.16)
                    // temp * FOUR_THIRDS, then shift right 16 to maintain Q16.16
                    volume <= (temp[31:0] * FOUR_THIRDS) >> 16;
                    state <= DONE_STATE;
                end

                DONE_STATE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module max_frequency (
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [7:0] arr_8,
    input [7:0] arr_9,
    input [7:0] arr_10,
    input [7:0] arr_11,
    input [7:0] arr_12,
    input [7:0] arr_13,
    input [7:0] arr_14,
    input [7:0] arr_15,
    input [7:0] arr_16,
    input [7:0] arr_17,
    input [7:0] arr_18,
    input [7:0] arr_19,
    input [7:0] arr_20,
    output reg [7:0] result,
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam COUNT = 3'b001;
    localparam FIND_MAX = 3'b010;
    localparam FINISH = 3'b011;

    // Constants
    localparam INPUT_SIZE = 21;
    localparam MAX_VAL = 255; // 8-bit max

    // Registers
    reg [2:0] state, next_state;
    reg [7:0] idx; // Index for input array
    reg [7:0] search_val; // Value being counted
    reg [3:0] freq_count; // Current frequency count (max 21)
    reg [3:0] max_freq; // Maximum frequency found so far
    reg [7:0] max_val; // Value with maximum frequency
    reg [7:0] check_val; // Value being compared
    reg [7:0] val_lookup [0:255]; // Frequency lookup table
    reg [7:0] i; // General purpose index
    reg [7:0] j; // Secondary index

    // Input array storage (to enable sequential access)
    reg [7:0] stored_arr [0:INPUT_SIZE-1];

    // Next state logic
    always @(state, start, idx, j, i) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = COUNT;
                else
                    next_state = IDLE;
            end
            COUNT: begin
                if (idx >= INPUT_SIZE)
                    next_state = FIND_MAX;
                else
                    next_state = COUNT;
            end
            FIND_MAX: begin
                if (j > MAX_VAL)
                    next_state = FINISH;
                else
                    next_state = FIND_MAX;
            end
            FINISH: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // State machine sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 0;
            j <= 0;
            i <= 0;
            freq_count <= 0;
            max_freq <= 0;
            max_val <= 0;
            result <= 0;
            done <= 0;
            // Reset lookup table (optional, but good for clean state)
            // Synthesis tools may not support loop in reset, handled in COUNT state
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    done <= 0;
                    idx <= 0;
                    j <= 0;
                    i <= 0;
                    max_freq <= 0;
                    max_val <= 0;
                    freq_count <= 0;
                    // Store inputs sequentially on start (or assume inputs are stable)
                    if (start) begin
                        stored_arr[0] <= arr_0;
                        stored_arr[1] <= arr_1;
                        stored_arr[2] <= arr_2;
                        stored_arr[3] <= arr_3;
                        stored_arr[4] <= arr_4;
                        stored_arr[5] <= arr_5;
                        stored_arr[6] <= arr_6;
                        stored_arr[7] <= arr_7;
                        stored_arr[8] <= arr_8;
                        stored_arr[9] <= arr_9;
                        stored_arr[10] <= arr_10;
                        stored_arr[11] <= arr_11;
                        stored_arr[12] <= arr_12;
                        stored_arr[13] <= arr_13;
                        stored_arr[14] <= arr_14;
                        stored_arr[15] <= arr_15;
                        stored_arr[16] <= arr_16;
                        stored_arr[17] <= arr_17;
                        stored_arr[18] <= arr_18;
                        stored_arr[19] <= arr_19;
                        stored_arr[20] <= arr_20;
                    end
                end

                COUNT: begin
                    if (idx < INPUT_SIZE) begin
                        // Increment frequency count for current value
                        // val_lookup[stored_arr[idx]] is the count
                        val_lookup[stored_arr[idx]] <= val_lookup[stored_arr[idx]] + 1;
                        idx <= idx + 1;
                    end
                end

                FIND_MAX: begin
                    if (j <= MAX_VAL) begin
                        if (val_lookup[j] > max_freq) begin
                            max_freq <= val_lookup[j];
                            max_val <= j;
                        end
                        j <= j + 1;
                    end
                end

                FINISH: begin
                    result <= max_val;
                    done <= 1;
                end
            endcase
        end
    end

endmodule

