                                    3'd3: result_3 <= arr_6;
                                    3'd4: result_4 <= arr_6;
                                    3'd5: result_5 <= arr_6;
                                    3'd6: result_6 <= arr_6;
                                    3'd7: result_7 <= arr_6;
                                endcase
                                out_idx <= out_idx + 1'b1;
                            end
                            3'd7: if (arr_7[7]) begin
                                case (out_idx)
                                    3'd0: result_0 <= arr_7;
                                    3'd1: result_1 <= arr_7;
                                    3'd2: result_2 <= arr_7;
                                    3'd3: result_3 <= arr_7;
                                    3'd4: result_4 <= arr_7;
                                    3'd5: result_5 <= arr_7;
                                    3'd6: result_6 <= arr_7;
                                    3'd7: result_7 <= arr_7;
                                endcase
                                out_idx <= out_idx + 1'b1;
                            end
                        endcase
                        idx <= idx + 1'b1;
                    end else begin
                        result_len <= out_idx;
                        state <= COMPLETE;
                    end
                end

                COMPLETE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

