module bitonic_max_sum (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    output reg [15:0] result,
    output reg done
);

    // Fixed array size of 8 elements
    parameter ARRAY_SIZE = 8;

    // Internal memory for DP arrays
    reg [7:0] arr_reg [0:7];
    reg [15:0] MSIBS [0:7];  // Maximum sum increasing subsequence
    reg [15:0] MSDBS [0:7];  // Maximum sum decreasing subsequence

    // State machine states
    localparam IDLE = 3'b000;
    localparam LOAD = 3'b001;
    localparam CALC_MSIBS = 3'b010;
    localparam CALC_MSDBS = 3'b011;
    localparam FIND_MAX = 3'b100;
    localparam DONE = 3'b101;

    reg [2:0] state;
    reg [2:0] i, j, k;  // Loop counters
    reg [15:0] current_max;
    reg [15:0] temp_sum;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            i <= 0;
            j <= 0;
            k <= 0;
            current_max <= 0;
            temp_sum <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= LOAD;
                        i <= 0;
                    end
                end

                LOAD: begin
                    // Load input array
                    case (i)
                        0: arr_reg[0] <= arr_0;
                        1: arr_reg[1] <= arr_1;
                        2: arr_reg[2] <= arr_2;
                        3: arr_reg[3] <= arr_3;
                        4: arr_reg[4] <= arr_4;
                        5: arr_reg[5] <= arr_5;
                        6: arr_reg[6] <= arr_6;
                        7: arr_reg[7] <= arr_7;
                    endcase

                    if (i < 7) begin
                        i <= i + 1;
                    end else begin
                        i <= 0;
                        j <= 0;
                        state <= CALC_MSIBS;
                    end
                end

                CALC_MSIBS: begin
                    // Initialize MSIBS with array values
                    if (i == 0) begin
                        MSIBS[j] <= arr_reg[j];
                        if (j < 7) begin
                            j <= j + 1;
                        end else begin
                            i <= 1;
                            j <= 0;
                        end
                    end else begin
                        // DP calculation for increasing subsequence
                        if (j < i) begin
                            if (arr_reg[i] > arr_reg[j] && MSIBS[i] < MSIBS[j] + arr_reg[i]) begin
                                MSIBS[i] <= MSIBS[j] + arr_reg[i];
                            end
                            j <= j + 1;
                        end else begin
                            j <= 0;
                            if (i < 7) begin
                                i <= i + 1;
                            end else begin
                                i <= 0;
                                j <= 0;
                                state <= CALC_MSDBS;
                            end
                        end
                    end
                end

                CALC_MSDBS: begin
                    // Initialize MSDBS with array values (reverse processing)
                    if (i == 0) begin
                        MSDBS[7-j] <= arr_reg[7-j];
                        if (j < 7) begin
                            j <= j + 1;
                        end else begin
                            i <= 1;
                            j <= 0;
                        end
                    end else begin
                        // DP calculation for decreasing subsequence (reverse)
                        if (j < i) begin
                            if (arr_reg[7-i] > arr_reg[7-j] && MSDBS[7-i] < MSDBS[7-j] + arr_reg[7-i]) begin
                                MSDBS[7-i] <= MSDBS[7-j] + arr_reg[7-i];
                            end
                            j <= j + 1;
                        end else begin
                            j <= 0;
                            if (i < 7) begin
                                i <= i + 1;
                            end else begin
                                i <= 0;
                                current_max <= 0;
                                state <= FIND_MAX;
                            end
                        end
                    end
                end

                FIND_MAX: begin
                    // Find maximum bitonic sum: MSIBS[i] + MSDBS[i] - arr[i]
                    temp_sum <= MSIBS[i] + MSDBS[i] - arr_reg[i];

                    if (temp_sum > current_max) begin
                        current_max <= temp_sum;
                    end

                    if (i < 7) begin
                        i <= i + 1;
                    end else begin
                        result <= current_max;
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module remove_odd(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,          // Input character (ASCII)
    input wire [3:0] str_len,          // Length of input string (1-16)
    output reg [7:0] char_out,         // Output character
    output reg out_valid,              // Output valid signal
    output reg done                    // Completion signal
);

// Removes characters at odd positions (1-indexed)
// Keeps characters at EVEN positions: 2, 4, 6, ...
// Positions: pos 1 (skip), pos 2 (keep), pos 3 (skip), pos 4 (keep)...

reg [3:0] state;
reg [3:0] pos_counter;   // Current position (1 to str_len)

// State definitions
localparam IDLE = 4'd0;
localparam PROCESS = 4'd1;
localparam DONE = 4'd2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        pos_counter <= 4'd0;
        char_out <= 8'd0;
        out_valid <= 1'b0;
        done <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= PROCESS;
                    pos_counter <= 4'd1;  // Start at position 1
                    out_valid <= 1'b0;
                    done <= 1'b0;
                end
            end

            PROCESS: begin
                if (pos_counter <= str_len) begin
                    // Check if position is even (keep) or odd (skip)
                    if (pos_counter[0] == 1'b0) begin  // Even position
                        char_out <= char_in;
                        out_valid <= 1'b1;
                    end else begin  // Odd position
                        out_valid <= 1'b0;
                    end
                    pos_counter <= pos_counter + 1'b1;
                end else begin
                    // All characters processed
                    out_valid <= 1'b0;
                    done <= 1'b1;
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1'b0;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

// INTERFACE SPECIFICATION:
// Inputs: clk, rst_n, start, char_in, str_len
// Outputs: char_out, out_valid, done
// Timing: Assert start for 1 cycle, then feed characters one per cycle
// Process: For each input cycle, position increments; out_valid pulses for even positions
// Reset: rst_n=0 clears all state; minimum 2 cycles recommended

module max_product_finder (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire signed [7:0] arr_0,
    input wire signed [7:0] arr_1,
    input wire signed [7:0] arr_2,
    input wire signed [7:0] arr_3,
    input wire signed [7:0] arr_4,
    input wire signed [7:0] arr_5,
    input wire signed [7:0] arr_6,
    input wire signed [7:0] arr_7,
    input wire [3:0] len,  // Number of valid elements (2-8)
    output reg signed [15:0] result_x,
    output reg signed [15:0] result_y,
    output reg done
);

    // State machine states
    localparam IDLE = 2'd0;
    localparam COMPARE = 2'd1;
    localparam FINISHED = 2'd2;

    reg [1:0] state;
    reg [3:0] i;
    reg [3:0] j;
    reg signed [15:0] best_x;
    reg signed [15:0] best_y;
    reg signed [15:0] current_product;
    reg signed [15:0] best_product;

    // Input array storage (registered)
    reg signed [7:0] arr_reg [0:7];

    integer idx;

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result_x <= 16'sd0;
            result_y <= 16'sd0;
            i <= 4'd0;
            j <= 4'd0;
            best_x <= 16'sd0;
            best_y <= 16'sd0;
            best_product <= 16'sd0;
            current_product <= 16'sd0;
            // Clear array storage
            for (idx = 0; idx < 8; idx = idx + 1) begin
                arr_reg[idx] <= 8'sd0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start && len >= 2) begin
                        // Register all input values
                        arr_reg[0] <= arr_0;
                        arr_reg[1] <= arr_1;
                        arr_reg[2] <= arr_2;
                        arr_reg[3] <= arr_3;
                        arr_reg[4] <= arr_4;
                        arr_reg[5] <= arr_5;
                        arr_reg[6] <= arr_6;
                        arr_reg[7] <= arr_7;

                        // Initialize with first two elements
                        best_x <= {8'd0, arr_0};
                        best_y <= {8'd0, arr_1};
                        best_product <= arr_0 * arr_1;

                        i <= 4'd0;
                        j <= 4'd1;
                        state <= COMPARE;
                    end
                end

                COMPARE: begin
                    // Calculate current product
                    current_product <= arr_reg[i] * arr_reg[j];

                    // Compare with best (one cycle delay for multiplication)
                    if (arr_reg[i] * arr_reg[j] > best_product) begin
                        best_x <= {8'd0, arr_reg[i]};
                        best_y <= {8'd0, arr_reg[j]};
                        best_product <= arr_reg[i] * arr_reg[j];
                    end

                    // Increment indices
                    if (j < len - 1) begin
                        j <= j + 1;
                    end else begin
                        j <= i + 2;
                        if (i < len - 2) begin
                            i <= i + 1;
                        end else begin
                            state <= FINISHED;
                        end
                    end

                    // Check if we've completed all pairs
                    if (i >= len - 2 && j >= len - 1) begin
                        state <= FINISHED;
                    end
                end

                FINISHED: begin
                    result_x <= best_x;
                    result_y <= best_y;
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module ExtractFirstElements (
    // Input: 2D array - up to 8 sublists, each with up to 8 elements
    input [7:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,
    input [2:0] num_sublists,  // Number of valid sublists (1-8)

    // Output: First element of each sublist
    output reg [7:0] result_0, result_1, result_2, result_3,
                     result_4, result_5, result_6, result_7,
