    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            i <= 0;
            p[0] <= 8'd1;
            p[1] <= 8'd1;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        if (n == 1 || n == 2) begin
                            result <= 8'd1;
                            done <= 1;
                            state <= DONE_STATE;
                        end else begin
                            i <= 3;
                            state <= COMPUTE;
                        end
                    end
                end

                COMPUTE: begin
                    if (i <= n) begin
                        val1 <= p[i-2];  // P(i-1)
                        // Need two more cycles for memory reads
                        // This module needs restructuring
                        state <= COMPUTE;  // Stay in compute
                    end else begin
                        result <= p[n-1];
                        done <= 1;
