endmodule

// FINAL CORRECTED VERSION WITH MULTIPLE CYCLES PER COMPUTATION:

module newman_conway_seq(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [4:0] n,
    output reg [7:0] result,
    output reg done
);

    reg [4:0] i;  // Current index being computed
    reg [7:0] p [15:0];  // Lookup table, p[k] = P(k+1)
    reg [1:0] state;
    reg [2:0] substate;  // For multi-cycle computation

    // States
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam DONE_STATE = 2'b10;

    // Substates for computing P(i) = P(P(i-1)) + P(i-P(i-1))
    localparam READ1 = 3'b001;  // Read P(i-1)
    localparam READ2 = 3'b010;  // Read P(P(i-1)) and P(i-P(i-1))
    localparam WRITE = 3'b011;  // Write sum

    reg [7:0] val_i_minus_1;
    reg [7:0] p_of_val;
    reg [7:0] p_of_diff;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            substate <= READ1;
            done <= 0;
            result <= 0;
            i <= 0;
            // Initialize base cases
            p[0] <= 8'd1;  // P(1)
            p[1] <= 8'd1;  // P(2)
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start && n >= 1) begin
                        if (n == 1 || n == 2) begin
                            result <= 8'd1;
                            done <= 1;
                            state <= DONE_STATE;
                        end else begin
                            i <= 3;
                            substate <= READ1;
                            state <= COMPUTE;
                        end
                    end
                end

                COMPUTE: begin
                    case (substate)
                        READ1: begin
                            // Read P(i-1)
                            val_i_minus_1 <= p[i-2];  // p[i-2] = P(i-1)
                            substate <= READ2;
                        end

                        READ2: begin
                            // Read P(P(i-1)) and P(i-P(i-1))
                            p_of_val <= p[val_i_minus_1 - 1];  // P(P(i-1))
                            p_of_diff <= p[i - val_i_minus_1 - 1];  // P(i-P(i-1))
                            substate <= WRITE;
                        end

                        WRITE: begin
                            // Compute and store P(i)
                            p[i-1] <= p_of_val + p_of_diff;

                            if (i == n) begin
                                result <= p_of_val + p_of_diff;
                                done <= 1;
                                state <= DONE_STATE;
                            end else begin
                                i <= i + 1;
                                substate <= READ1;
                            end
                        end
                    endcase
                end

                DONE_STATE: begin
                    done <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module sum_even_even_pos (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] len,          // Number of valid elements (1 to 8)
    output reg [15:0] result,
    output reg done
);

    // Internal state registers
    reg [3:0] idx;
    reg [15:0] sum_reg;
    reg processing;

    // State definitions
    localparam IDLE = 2'b00;
    localparam CHECK = 2'b01;
    localparam ADD = 2'b10;
    localparam FINISH = 2'b11;
    reg [1:0] state;

    // Current value lookup based on index
    reg [7:0] current_val;
    always @(*) begin
        case(idx)
            4'd0: current_val = arr_0;
            4'd1: current_val = arr_1;
            4'd2: current_val = arr_2;
            4'd3: current_val = arr_3;
            4'd4: current_val = arr_4;
            4'd5: current_val = arr_5;
            4'd6: current_val = arr_6;
            4'd7: current_val = arr_7;
            default: current_val = 8'd0;
        endcase
    end

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 4'd0;
            sum_reg <= 16'd0;
            done <= 1'b0;
            result <= 16'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        idx <= 4'd0;
                        sum_reg <= 16'd0;
                        state <= CHECK;
                    end
                end

                CHECK: begin
                    if (idx < len) begin
                        // Check if index is even (idx[0] == 0) and value is even (current_val[0] == 0)
                        if (!idx[0] && !current_val[0]) begin
                            state <= ADD;
                        end else begin
                            // Skip adding, just increment
                            if (idx + 1 >= len) begin
                                state <= FINISH;
                            end else begin
                                idx <= idx + 1;
                                state <= CHECK;
                            end
                        end
                    end else begin
                        state <= FINISH;
                    end
                end

                ADD: begin
                    sum_reg <= sum_reg + current_val;
                    if (idx + 1 >= len) begin
                        state <= FINISH;
                    end else begin
                        idx <= idx + 1;
                        state <= CHECK;
                    end
                end

                FINISH: begin
                    result <= sum_reg;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module multi_concat #(
    parameter NUM_ELEMENTS = 8,
    parameter ELEMENT_WIDTH = 8,  // Each integer stored as 8-bit (0-99 range)
    parameter RESULT_WIDTH = 64   // 8 elements * 8 bits each
  ) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [ELEMENT_WIDTH-1:0] arr [NUM_ELEMENTS-1:0],
    input wire [3:0] len,  // Number of valid elements (1-8)
    output reg [RESULT_WIDTH-1:0] result,
    output reg done
  );

  // Internal state
  reg [3:0] idx;
  reg processing;
  reg [RESULT_WIDTH-1:0] temp_result;

  // Helper: Check if element is negative (MSB set)
  wire is_negative;
  assign is_negative = arr[0][ELEMENT_WIDTH-1] && (len > 0);

  // Helper: Convert element to 2-digit decimal value (0-99)
  function [15:0] to_decimal;
    input [ELEMENT_WIDTH-1:0] val;
    reg [7:0] abs_val;
    begin
      // Take absolute value, clamp to 99
      abs_val = val[ELEMENT_WIDTH-1] ? (~val + 1'b1) : val;
      if (abs_val > 99) abs_val = 99;
      // Convert to decimal: tens * 10 + ones
      to_decimal = ((abs_val / 10) * 100) + ((abs_val % 10) * 10);
    end
  endfunction

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      result <= 0;
      done <= 0;
      idx <= 0;
      processing <= 0;
      temp_result <= 0;
    end else begin
      if (start && !processing) begin
        // Start new computation
        idx <= 0;
        processing <= 1;
        done <= 0;
        temp_result <= 0;

        // Handle negative first element
        if (is_negative && len > 0) begin
          temp_result[RESULT_WIDTH-1] <= 1;  // Set sign bit
        end
      end else if (processing) begin
        if (idx < len) begin
          // Process element idx
          if (idx == 0 && is_negative) begin
            // First element is negative - already handled sign
            temp_result <= temp_result + (to_decimal(arr[0]) << ((len-1-idx)*8));
          end else begin
            // Regular element - shift and add
            temp_result <= temp_result + (to_decimal(arr[idx]) << ((len-1-idx)*8));
          end
          idx <= idx + 1;
        end else begin
          // Done
          result <= temp_result;
          done <= 1;
          processing <= 0;
        end
      end else begin
        done <= 0;
      end
    end
  end

endmodule

module max_length_list(
    // Input: 2D array, 5 sublists max, each 8 elements max
    input [7:0] arr_0_0, arr_0_1, arr_0_2, arr_0_3, arr_0_4, arr_0_5, arr_0_6, arr_0_7,
    input [7:0] arr_1_0, arr_1_1, arr_1_2, arr_1_3, arr_1_4, arr_1_5, arr_1_6, arr_1_7,
