module sum_negative_numbers (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] len,  // Number of elements (0-15)
    input wire signed [7:0] arr [0:7],  // 8-element array, 8-bit signed
    output reg signed [15:0] result,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam CALC = 2'b01;
    localparam FINISH = 2'b10;

    // Internal registers
    reg [1:0] state;
    reg [3:0] index;
    reg signed [15:0] sum;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            index <= 4'b0;
            sum <= 16'sd0;
            result <= 16'sd0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= CALC;
                        index <= 4'b0;
                        sum <= 16'sd0;
                    end
                end

                CALC: begin
                    if (index < len && index < 4'd8) begin
                        // Check if negative
                        if (arr[index] < 8'sd0) begin
                            // Sign-extend 8-bit to 16-bit and add
                            sum <= sum + {{8{arr[index][7]}}, arr[index]};
                        end
                        index <= index + 1'b1;
                    end else begin
                        state <= FINISH;
                        result <= sum;
                    end
                end

                FINISH: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module max_length_finder (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input array of strings (sublists). Each string is up to 8 characters.
    // Individual port interface for sublists.
    input wire [7:0] sublist_0,
    input wire [7:0] sublist_1,
    input wire [7:0] sublist_2,
    input wire [3:0] sublist_len_0,
    input wire [3:0] sublist_len_1,
    input wire [3:0] sublist_len_2,
    input wire [3:0] num_sublists,  // Number of valid sublists (1-3)

    output reg [7:0] max_sublist_out,
    output reg [3:0] max_len_out,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPARE = 2'b01;
    localparam UPDATE = 2'b10;
    localparam FINISH = 2'b11;

    reg [1:0] state, next_state;
    reg [3:0] idx, next_idx;
    reg [3:0] max_len_reg, next_max_len;
    reg [7:0] max_sublist_reg, next_max_sublist;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 4'd0;
            max_len_reg <= 4'd0;
            max_sublist_reg <= 8'd0;
        end else begin
            state <= next_state;
            idx <= next_idx;
            max_len_reg <= next_max_len;
            max_sublist_reg <= next_max_sublist;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        next_idx = idx;
        next_max_len = max_len_reg;
        next_max_sublist = max_sublist_reg;
        done = 1'b0;

        case (state)
            IDLE: begin
                if (start) begin
                    next_state = COMPARE;
                    next_idx = 4'd0;
                    next_max_len = 4'd0;
                    next_max_sublist = 8'd0;
                end
            end

            COMPARE: begin
                if (idx < num_sublists) begin
                    // Get current sublist length
                    reg [3:0] curr_len;
                    case (idx)
                        4'd0: curr_len = sublist_len_0;
                        4'd1: curr_len = sublist_len_1;
                        4'd2: curr_len = sublist_len_2;
                        default: curr_len = 4'd0;
                    endcase

                    if (curr_len > max_len_reg) begin
                        next_state = UPDATE;
                    end else begin
                        next_state = COMPARE;
                        next_idx = idx + 1'b1;
                    end
                end else begin
                    next_state = FINISH;
                end
            end

            UPDATE: begin
                // Update max values
                case (idx)
                    4'd0: begin
                        next_max_len = sublist_len_0;
                        next_max_sublist = sublist_0;
                    end
                    4'd1: begin
                        next_max_len = sublist_len_1;
                        next_max_sublist = sublist_1;
                    end
                    4'd2: begin
                        next_max_len = sublist_len_2;
                        next_max_sublist = sublist_2;
                    end
                    default: begin
                        next_max_len = 4'd0;
                        next_max_sublist = 8'd0;
                    end
                endcase
                next_state = COMPARE;
                next_idx = idx + 1'b1;
            end

            FINISH: begin
                done = 1'b1;
                if (!start) begin
                    next_state = IDLE;
                end
            end

            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output assignments
    always @(posedge clk) begin
        if (state == FINISH) begin
            max_sublist_out <= max_sublist_reg;
            max_len_out <= max_len_reg;
        end
    end

endmodule

module sum_div(
    input [7:0] number,      // Input number (0-255)
    output reg [15:0] result // Sum of all divisors (excluding the number itself)
);

integer i;
reg [15:0] divisor_sum;

always @(*) begin
    divisor_sum = 0;

    // Edge cases: 0 and 1 have no proper divisors
    if (number > 1) begin
        divisor_sum = 1;  // 1 is always a divisor for n > 1

        // Check each potential divisor from 2 to number-1
        for (i = 2; i < number; i = i + 1) begin
            if (number % i == 0) begin
                divisor_sum = divisor_sum + i;
            end
        end
    end

    result = divisor_sum;
end

endmodule

// INTERFACE SPECIFICATION:
// Inputs:
//   - number[7:0]  : 8-bit unsigned input (0-255)
// Outputs:
//   - result[15:0] : 16-bit sum of divisors (combinational)
//
// Example behavior:
//   number=8  -> result=7  (divisors: 1,2,4)
//   number=12 -> result=16 (divisors: 1,2,3,4,6)
//   number=7  -> result=1  (divisors: 1)
//   number=1  -> result=0  (no proper divisors)
//   number=0  -> result=0  (undefined behavior)

module lps(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] str_0, str_1, str_2, str_3, str_4, str_5, str_6, str_7,
    input wire [3:0] str_len,
    output reg [3:0] result,
    output reg done
);

// Longest Palindromic Subsequence - Sequential DP implementation
// Supports strings up to 8 characters (max length = 8)
// Uses 8x8 matrix stored in registers
// Computation completes in ~80 cycles (8x8 matrix fill)

// Internal state machine
reg [3:0] state;
reg [3:0] i, j, cl;
reg [7:0] L [0:7][0:7];  // 8x8 matrix for DP table
reg [3:0] len_reg;       // Store string length

// State definitions
localparam IDLE = 4'd0;
localparam INIT_DIAG = 4'd1;
localparam INIT_WAIT = 4'd2;
localparam CL_LOOP = 4'd3;
localparam I_LOOP = 4'd4;
localparam CHECK_CHARS = 4'd5;
localparam UPDATE_2 = 4'd6;
localparam UPDATE_MAX = 4'd7;
localparam COMPLETE = 4'd8;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset state
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        j <= 0;
        cl <= 0;
        len_reg <= 0;
        // Clear matrix (optional, but good practice)
        for (integer r = 0; r < 8; r = r + 1) begin
            for (integer c = 0; c < 8; c = c + 1) begin
                L[r][c] <= 8'd0;
            end
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    len_reg <= str_len;
                    state <= INIT_DIAG;
                    i <= 0;
                end else begin
                    state <= IDLE;
                end
            end

            INIT_DIAG: begin
                // Set L[i][i] = 1 for all i < len_reg
                if (i < len_reg) begin
                    L[i][i] <= 8'd1;
                    i <= i + 1;
                    state <= INIT_DIAG;
                end else begin
                    i <= 0;
                    cl <= 3'd2;
                    state <= CL_LOOP;
                end
            end

            CL_LOOP: begin
                // for cl in range(2, n+1)
                if (cl <= len_reg) begin
                    i <= 0;
                    state <= I_LOOP;
                end else begin
                    // Done with all loops, get final answer
                    if (len_reg >= 1) begin
                        result <= L[0][len_reg-1][3:0];
                    end else begin
                        result <= 4'd0;
                    end
                    state <= COMPLETE;
                end
            end

            I_LOOP: begin
                // for i in range(n-cl+1)
                if (i <= (len_reg - cl)) begin
                    j <= i + cl - 1;
                    state <= CHECK_CHARS;
                end else begin
                    cl <= cl + 1;
                    state <= CL_LOOP;
                end
            end

            CHECK_CHARS: begin
                // Check if str[i] == str[j]
                // Get characters from input ports
                case (i)
                    4'd0: begin if (str_0 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd1: begin if (str_1 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd2: begin if (str_2 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd3: begin if (str_3 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd4: begin if (str_4 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd5: begin if (str_5 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd6: begin if (str_6 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                    4'd7: begin if (str_7 == str_1) state <= (cl == 3'd2) ? UPDATE_2 : UPDATE_MAX; else state <= UPDATE_MAX; end
                endcase
                // Note: This is simplified - actual implementation needs proper j indexing
                // Let me restructure with proper character comparison
            end

            UPDATE_2: begin
                // L[i][j] = 2 when cl == 2 and str[i] == str[j]
                L[i][j] <= 8'd2;
                i <= i + 1;
                state <= I_LOOP;
            end

            UPDATE_MAX: begin
                // L[i][j] = max(L[i][j-1], L[i+1][j])
                // When str[i] != str[j]
                // OR L[i][j] = L[i+1][j-1] + 2 when str[i] == str[j] and cl > 2
                // This requires reading from L matrix - will be done in separate cycles
                // For now, simplify: just store max
                // Implementation requires multi-cycle reads
                // Let me provide a working simplified version
                if (str_0 == str_0) begin  // Placeholder - needs proper comparison
                    L[i][j] <= 8'd0;  // This is wrong - will fix
                end
                i <= i + 1;
                state <= I_LOOP;
            end

            COMPLETE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

// Combinational logic for character lookup
reg [7:0] char_i, char_j;
always @(*) begin
    case (i)
        4'd0: char_i = str_0;
        4'd1: char_i = str_1;
        4'd2: char_i = str_2;
        4'd3: char_i = str_3;
        4'd4: char_i = str_4;
        4'd5: char_i = str_5;
        4'd6: char_i = str_6;
        4'd7: char_i = str_7;
        default: char_i = 8'd0;
    endcase

    case (j)
        4'd0: char_j = str_0;
        4'd1: char_j = str_1;
        4'd2: char_j = str_2;
        4'd3: char_j = str_3;
        4'd4: char_j = str_4;
        4'd5: char_j = str_5;
        4'd6: char_j = str_6;
        4'd7: char_j = str_7;
        default: char_j = 8'd0;
    endcase
end

// Modified state machine with proper comparison
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        result <= 0;
        i <= 0;
        j <= 0;
        cl <= 0;
        len_reg <= 0;
        for (integer r = 0; r < 8; r = r + 1)
            for (integer c = 0; c < 8; c = c + 1)
                L[r][c] <= 8'd0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start) begin
                    len_reg <= str_len;
                    state <= INIT_DIAG;
                    i <= 0;
                end
            end

            INIT_DIAG: begin
                if (i < len_reg) begin
                    L[i][i] <= 8'd1;
                    i <= i + 1;
                end else begin
                    i <= 0;
                    cl <= 3'd2;
                    state <= CL_LOOP;
                end
            end

            CL_LOOP: begin
                if (cl <= len_reg) begin
                    i <= 0;
                    state <= I_LOOP;
                end else begin
                    if (len_reg >= 1) result <= L[0][len_reg-1][3:0];
                    else result <= 0;
                    state <= COMPLETE;
                end
            end

            I_LOOP: begin
                if (i <= (len_reg - cl)) begin
                    j <= i + cl - 1;
                    state <= CHECK_CHARS;
                end else begin
                    cl <= cl + 1;
                    state <= CL_LOOP;
                end
            end

            CHECK_CHARS: begin
                if (char_i == char_j) begin
                    if (cl == 2) begin
                        L[i][j] <= 8'd2;
                    end else begin
                        // Need to read L[i+1][j-1] and add 2
                        // This takes extra cycles for read/write
                        // Simplified: assume we can read in same cycle (not realistic but works for this exercise)
                        L[i][j] <= L[i+1][j-1] + 8'd2;
                    end
                end else begin
                    // max(L[i][j-1], L[i+1][j])
                    if (L[i][j-1] >= L[i+1][j]) begin
                        L[i][j] <= L[i][j-1];
                    end else begin
                        L[i][j] <= L[i+1][j];
                    end
                end
                i <= i + 1;
                state <= I_LOOP;
            end

            COMPLETE: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module array_append (
    // Clock and reset
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input arrays (fixed size: 8 elements, 8-bit each)
    input wire [7:0] tuple_arr [0:7],
    input wire [7:0] list_arr [0:7],

    // Length indicators (how many valid elements in each array)
    input wire [3:0] tuple_len,  // 1-8
    input wire [3:0] list_len,   // 1-8

    // Output array (max 16 elements for concatenation)
    output reg [7:0] result_arr [0:15],

    // Status signals
    output reg done
);

    // Maximum sizes
    localparam MAX_TUPLE_LEN = 8;
    localparam MAX_LIST_LEN = 8;
    localparam MAX_RESULT_LEN = 16;

    // State machine states
    reg [4:0] state;
    reg [4:0] next_state;
    reg [4:0] idx;

    // State definitions
    localparam IDLE = 5'd0;
    localparam COPY_TUPLE = 5'd1;
    localparam COPY_LIST = 5'd2;
    localparam FINISH = 5'd3;

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 5'd0;
            done <= 1'b0;
        end else begin
            state <= next_state;

            // Clear done when starting new operation
            if (start && state == IDLE) begin
                done <= 1'b0;
                idx <= 5'd0;
            end
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;

        case (state)
            IDLE: begin
                if (start) begin
                    next_state = COPY_TUPLE;
                end
            end

            COPY_TUPLE: begin
                if (idx >= tuple_len) begin
                    next_state = COPY_LIST;
                end
            end

            COPY_LIST: begin
                if (idx >= tuple_len + list_len) begin
                    next_state = FINISH;
                end
            end

            FINISH: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output logic
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset output array
            for (i = 0; i < 16; i = i + 1) begin
                result_arr[i] <= 8'd0;
            end
            idx <= 5'd0;
        end else begin
            case (state)
                COPY_TUPLE: begin
                    if (idx < tuple_len && idx < MAX_TUPLE_LEN) begin
                        result_arr[idx] <= tuple_arr[idx];
                        idx <= idx + 5'd1;
                    end
                end

                COPY_LIST: begin
                    if (idx < tuple_len + list_len && idx < MAX_RESULT_LEN) begin
                        result_arr[idx] <= list_arr[idx - tuple_len];
                        idx <= idx + 5'd1;
                    end
                end

                FINISH: begin
                    done <= 1'b1;
                    idx <= 5'd0;
                end

                default: begin
                    // Maintain current values
                end
            endcase
        end
    end

endmodule

module string_pattern_matcher (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,  // Current character input (ASCII)
    input wire [3:0] str_len,   // Input string length (1-16)
    output reg [7:0] count,     // Number of 'std' occurrences
    output reg done             // Computation complete
);

    // Internal state
    reg [3:0] index;            // Current character position
    reg [7:0] window [0:2];     // Sliding window: 3-character buffer
    reg [7:0] cnt;              // Accumulated count
    reg processing;             // Processing state flag
    reg [1:0] shift_count;      // Tracks shift operations after new char

    // ASCII values for pattern matching
    localparam CHAR_S = 8'h73;  // 's'
    localparam CHAR_T = 8'h74;  // 't'
    localparam CHAR_D = 8'h64;  // 'd'

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            index <= 4'd0;
            cnt <= 8'd0;
            done <= 1'b0;
            processing <= 1'b0;
            shift_count <= 2'd0;
            window[0] <= 8'd0;
            window[1] <= 8'd0;
            window[2] <= 8'd0;
            count <= 8'd0;
        end else begin
            if (start && !processing) begin
                // Start new computation
                index <= 4'd0;
                cnt <= 8'd0;
                done <= 1'b0;
                processing <= 1'b1;
                shift_count <= 2'd0;
                window[0] <= 8'd0;
                window[1] <= 8'd0;
                window[2] <= 8'd0;
            end else if (processing) begin
                if (shift_count == 2'd0) begin
                    // Load new character into window
                    if (index < str_len) begin
                        window[2] <= char_in;
                        shift_count <= 2'd1;
                        index <= index + 1'b1;
                    end else begin
                        // All characters processed
                        processing <= 1'b0;
                        done <= 1'b1;
                        count <= cnt;
                    end
                end else begin
                    // Shift window and check pattern
                    window[0] <= window[1];
                    window[1] <= window[2];
                    window[2] <= 8'd0;
                    shift_count <= shift_count - 1'b1;

                    // Check for 'std' pattern in window[0:2]
                    if (shift_count == 2'd1 && window[0] == CHAR_S && window[1] == CHAR_T && window[2] == CHAR_D) begin
                        cnt <= cnt + 1'b1;
                    end
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

module find_product_even_odd(
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [3:0] len,  // Number of valid elements (1-8)
    output reg [15:0] result,
    output reg done
);

    // State encoding
    localparam IDLE = 3'd0;
    localparam SCAN = 3'd1;
    localparam COMPUTE = 3'd2;
    localparam FINISH = 3'd3;

    reg [2:0] state, next_state;
    reg [3:0] idx;
    reg [7:0] first_even;
    reg [7:0] first_odd;
    reg found_even;
    reg found_odd;
    reg [7:0] current_val;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start && len > 0)
                    next_state = SCAN;
                else
                    next_state = IDLE;
            end
            SCAN: begin
                if (idx < len && (!found_even || !found_odd))
                    next_state = SCAN;
                else if (idx >= len)
                    next_state = COMPUTE;
                else
                    next_state = COMPUTE;
            end
            COMPUTE: begin
                next_state = FINISH;
            end
            FINISH: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Data path logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idx <= 4'd0;
            first_even <= 8'd0;
            first_odd <= 8'd0;
            found_even <= 1'b0;
            found_odd <= 1'b0;
            result <= 16'd0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;

            case (state)
                IDLE: begin
                    idx <= 4'd0;
                    first_even <= 8'd0;
                    first_odd <= 8'd0;
                    found_even <= 1'b0;
                    found_odd <= 1'b0;
                end

                SCAN: begin
                    if (idx < len) begin
                        // Select current value from input array
                        case (idx)
                            4'd0: current_val = arr_0;
                            4'd1: current_val = arr_1;
                            4'd2: current_val = arr_2;
                            4'd3: current_val = arr_3;
                            4'd4: current_val = arr_4;
                            4'd5: current_val = arr_5;
                            4'd6: current_val = arr_6;
                            4'd7: current_val = arr_7;
                            default: current_val = 8'd0;
                        endcase

                        // Check for even
                        if (!found_even && (current_val % 2 == 0)) begin
                            first_even <= current_val;
                            found_even <= 1'b1;
                        end

                        // Check for odd
                        if (!found_odd && (current_val % 2 != 0)) begin
                            first_odd <= current_val;
                            found_odd <= 1'b1;
                        end

                        idx <= idx + 1'b1;
                    end
                end

                COMPUTE: begin
                    // Multiply (with -1 default if not found)
                    if (found_even && found_odd)
                        result <= first_even * first_odd;
                    else if (found_even && !found_odd)
                        result <= {8'd0, first_even} * 8'd255; // -1 in two's complement 8-bit is 255
                    else if (!found_even && found_odd)
                        result <= 8'd255 * first_odd;
                    else
                        result <= 16'd65025; // -1 * -1 = 1 in two's complement 16-bit
                end

                FINISH: begin
                    done <= 1'b1;
                end
            endcase
        end
    end

endmodule

module month_has_30_days (
    input [3:0] month_num,  // Month number 1-12 (4 bits)
    output has_30_days       // High if month has exactly 30 days
);

    // Months with exactly 30 days: 4 (April), 6 (June), 9 (September), 11 (November)
    // Combinational logic
    assign has_30_days = (month_num == 4) || (month_num == 6) || 
                         (month_num == 9) || (month_num == 11);

endmodule

module tuple_to_dict (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] tuple_data [0:5],  // 6-element input tuple
    output reg [7:0] keys [0:2],         // Up to 3 keys
    output reg [7:0] values [0:2],       // Up to 3 values
    output reg [2:0] valid_pairs,        // Number of valid pairs (0-3)
    output reg done                      // Computation complete
);

// Parameters
parameter MAX_PAIRS = 3;
parameter TUPLE_SIZE = 6;
parameter DATA_WIDTH = 8;

// Internal state
reg [1:0] state;
reg [1:0] pair_idx;

// State definitions
localparam IDLE = 2'b00;
localparam COMPUTE = 2'b01;
localparam FINISHED = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset all outputs and state
        state <= IDLE;
        pair_idx <= 0;
        valid_pairs <= 0;
        done <= 0;
        keys[0] <= 0; keys[1] <= 0; keys[2] <= 0;
        values[0] <= 0; values[1] <= 0; values[2] <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                pair_idx <= 0;
                valid_pairs <= 0;
                if (start) begin
                    state <= COMPUTE;
                end
            end

            COMPUTE: begin
                if (pair_idx < MAX_PAIRS) begin
                    // Process adjacent pairs: tuple[0]=key, tuple[1]=val, tuple[2]=key, etc.
                    keys[pair_idx] <= tuple_data[pair_idx * 2];
                    values[pair_idx] <= tuple_data[pair_idx * 2 + 1];
                    pair_idx <= pair_idx + 1;
                    valid_pairs <= pair_idx + 1;

                    // Check if we just processed the last pair
                    if (pair_idx == MAX_PAIRS - 1) begin
                        state <= FINISHED;
                    end
                end else begin
                    state <= FINISHED;
                end
            end

            FINISHED: begin
                done <= 1;
                state <= IDLE;
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module tuple_str_int (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,
    input wire [3:0] char_len,
    output reg [7:0] result_arr [0:7],
    output reg [3:0] result_len,
    output reg done,
    output reg error
);

// This module parses a tuple string format: "(num1, num2, ...)"
// Input: Serial stream of ASCII characters via char_in
//        char_len = actual string length (excluding parentheses)
// Processing: 
//    - Accepts characters on each clock cycle after start
//    - Parses comma-separated integers
//    - Stores up to 8 numbers in output array
//    - Handles 1-2 digit numbers (0-99)
// Output: result_arr contains parsed integers, result_len = count

// States
parameter IDLE = 0, PARSING = 1, WAIT_DONE = 2;
reg [1:0] state;

// Internal counters and buffers
reg [3:0] char_idx;        // Current character index
reg [3:0] num_idx;         // Current number index in result array
reg [7:0] current_num;     // Accumulator for current number
reg [7:0] digit_count;     // Digits in current number
reg [7:0] temp_char;       // Current character buffer

// ASCII constants
parameter COMMA = 8'h2C;
parameter SPACE = 8'h20;
parameter RPAREN = 8'h29;
parameter ZERO = 8'h30;
parameter NINE = 8'h39;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        error <= 0;
        result_len <= 0;
        char_idx <= 0;
        num_idx <= 0;
        current_num <= 0;
        digit_count <= 0;
        for (i = 0; i < 8; i = i + 1) begin
            result_arr[i] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                error <= 0;
                if (start) begin
                    state <= PARSING;
                    char_idx <= 0;
                    num_idx <= 0;
                    current_num <= 0;
                    digit_count <= 0;
                end
            end

            PARSING: begin
                if (char_idx < char_len) begin
                    temp_char <= char_in;

                    // Process character
                    if (char_in >= ZERO && char_in <= NINE) begin
                        // Number digit
                        if (digit_count < 2) begin
                            current_num <= (current_num * 10) + (char_in - ZERO);
                            digit_count <= digit_count + 1;
                        end else begin
                            error <= 1;
                            state <= WAIT_DONE;
                        end
                    end else if (char_in == COMMA || char_in == SPACE) begin
                        // End of number (ignore space)
                        if (digit_count > 0 && num_idx < 8) begin
                            result_arr[num_idx] <= current_num;
                            num_idx <= num_idx + 1;
                            current_num <= 0;
                            digit_count <= 0;
                        end
                    end else if (char_in == RPAREN) begin
                        // End of string
                        if (digit_count > 0 && num_idx < 8) begin
                            result_arr[num_idx] <= current_num;
                            num_idx <= num_idx + 1;
                        end
                        result_len <= num_idx + (digit_count > 0 ? 1 : 0);
                        state <= WAIT_DONE;
                    end else begin
                        // Invalid character
                        error <= 1;
                        state <= WAIT_DONE;
                    end

                    char_idx <= char_idx + 1;
                end else begin
                    // End of input
                    result_len <= num_idx;
                    state <= WAIT_DONE;
                end
            end

            WAIT_DONE: begin
                done <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module tuple_comparator(
  input clk,
  input rst_n,
  input start,
  input [7:0] tup1_0, tup1_1, tup1_2, tup1_3, tup1_4, tup1_5, tup1_6, tup1_7,
  input [7:0] tup2_0, tup2_1, tup2_2, tup2_3, tup2_4, tup2_5, tup2_6, tup2_7,
  input [2:0] len,
  output reg result,
  output reg done
);

  // Parameters
  parameter MAX_SIZE = 8;

  // Internal state
  reg [2:0] index;
  reg processing;
  reg intermediate_result;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      // Reset state
      index <= 0;
      processing <= 0;
      done <= 0;
      result <= 0;
      intermediate_result <= 0;
    end else begin
      if (start && !processing) begin
        // Start computation
        processing <= 1;
        index <= 0;
        intermediate_result <= 1; // Start with true
        done <= 0;
      end else if (processing) begin
        if (index < len) begin
          // Compare current elements
          case (index)
            0: if (!(tup1_0 > tup2_0)) intermediate_result <= 0;
            1: if (!(tup1_1 > tup2_1)) intermediate_result <= 0;
            2: if (!(tup1_2 > tup2_2)) intermediate_result <= 0;
            3: if (!(tup1_3 > tup2_3)) intermediate_result <= 0;
            4: if (!(tup1_4 > tup2_4)) intermediate_result <= 0;
            5: if (!(tup1_5 > tup2_5)) intermediate_result <= 0;
            6: if (!(tup1_6 > tup2_6)) intermediate_result <= 0;
            7: if (!(tup1_7 > tup2_7)) intermediate_result <= 0;
          endcase
          index <= index + 1;
        end else begin
          // Computation complete
          result <= intermediate_result;
          done <= 1;
          processing <= 0;
        end
      end else begin
        done <= 0;
      end
    end
  end

endmodule

module tetrahedron_area (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] side,  // Q8.8 fixed-point format (8 integer, 8 fractional bits)
    output reg [31:0] result, // Q16.16 fixed-point output
    output reg done
);

    // Constants: sqrt(3) in Q16.16 format = 1.7320508075688772 * 65536 = 113513
    parameter SQRT3_FIXED = 32'd113513;  // Q16.16 representation of sqrt(3)

    // State machine states
    reg [1:0] state;
    parameter IDLE = 2'd0;
    parameter COMPUTE = 2'd1;
    parameter COMPLETE = 2'd2;

    // Internal registers
    reg [31:0] side_sq;      // side^2 in Q16.16
    reg [31:0] product;      // sqrt(3) * side^2 in Q16.16
    reg [7:0] cycle_count;   // Computation cycle counter

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 1'b0;
            result <= 32'd0;
            side_sq <= 32'd0;
            product <= 32'd0;
            cycle_count <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        // Convert side to Q16.16 (multiply by 256) and square
                        // side in Q8.8 -> Q16.16: shift left by 8
                        side_sq <= (side * side) << 8;  // [15:0] * [15:0] = [31:0], then shift
                        state <= COMPUTE;
                        cycle_count <= 8'd0;
                    end
                end

                COMPUTE: begin
                    cycle_count <= cycle_count + 1'b1;

                    // Single cycle multiplication (combinational in hardware)
                    // result = sqrt(3) * side^2
                    // Both are Q16.16, result Q16.16
                    // Multiply then shift right by 16 to keep Q16.16 format
                    product <= (SQRT3_FIXED * side_sq) >> 16;

                    // Move to complete state
                    state <= COMPLETE;
                end

                COMPLETE: begin
                    result <= product;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: begin
                    state <= IDLE;
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

module move_num #(
    parameter MAX_LEN = 16,      // Maximum string length
    parameter CHAR_WIDTH = 8     // ASCII character width
) (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input string: array of characters
    input wire [CHAR_WIDTH-1:0] str_in [0:MAX_LEN-1],
    input wire [4:0] len_in,     // Actual length of input string (1-16)

    // Output string: array of characters
    output reg [CHAR_WIDTH-1:0] str_out [0:MAX_LEN-1],
    output reg [4:0] len_out,    // Length of output string
    output reg done              // Completion signal
);

    // State machine states
    typedef enum logic [1:0] {
        IDLE = 2'b00,
        PROCESS = 2'b01,
        FINISH = 2'b10
    } state_t;

    state_t current_state, next_state;

    // Internal counters and buffers
    reg [4:0] read_idx;          // Current input position
    reg [4:0] write_letters_idx; // Next position for letter
    reg [4:0] write_digits_idx;  // Next position for digit (starts from end)

    // Character classification
    wire is_digit;
    assign is_digit = (str_in[read_idx] >= 8'h30) && (str_in[read_idx] <= 8'h39);

    // Temporary storage for digits (written in reverse order, then reversed)
    reg [CHAR_WIDTH-1:0] digit_buffer [0:MAX_LEN-1];
    reg [4:0] digit_count;

    // Output buffer
    reg [CHAR_WIDTH-1:0] temp_out [0:MAX_LEN-1];
    reg [4:0] temp_len;

    integer i;

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic and datapath
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            read_idx <= 0;
            write_letters_idx <= 0;
            digit_count <= 0;
            done <= 0;
            len_out <= 0;
            // Clear buffers
            for (i = 0; i < MAX_LEN; i = i + 1) begin
                temp_out[i] <= 0;
                digit_buffer[i] <= 0;
            end
        end else begin
            case (current_state)
                IDLE: begin
                    done <= 0;
                    if (start && len_in > 0) begin
                        read_idx <= 0;
                        write_letters_idx <= 0;
                        digit_count <= 0;
                        next_state <= PROCESS;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                PROCESS: begin
                    if (read_idx < len_in) begin
                        // Process current character
                        if (is_digit) begin
                            // Store digit in buffer (temporary order)
                            digit_buffer[digit_count] <= str_in[read_idx];
                            digit_count <= digit_count + 1;
                        end else begin
                            // Write letter immediately
                            temp_out[write_letters_idx] <= str_in[read_idx];
                            write_letters_idx <= write_letters_idx + 1;
                        end
                        read_idx <= read_idx + 1;
                        next_state <= PROCESS;
                    end else begin
                        // Done reading, now write digits in reverse order
                        // Build final output by reversing digit buffer
                        for (i = 0; i < digit_count; i = i + 1) begin
                            temp_out[write_letters_idx + i] <= digit_buffer[digit_count - 1 - i];
                        end
                        temp_len <= write_letters_idx + digit_count;
                        next_state <= FINISH;
                    end
                end

                FINISH: begin
                    // Copy to output
                    for (i = 0; i < MAX_LEN; i = i + 1) begin
                        str_out[i] <= temp_out[i];
                    end
                    len_out <= temp_len;
                    done <= 1;
                    next_state <= IDLE;
                end

                default: begin
                    next_state <= IDLE;
                end
            endcase
        end
    end

endmodule

module text_match_three(
    input [127:0] text_in,        // 16-character string, packed as ASCII bytes
    input [3:0] length,           // Actual length of string (1-16)
    output reg match              // 1 if pattern 'abbb' found
);

    // Pattern to match: 'a' (0x61) followed by three 'b' (0x62)
    // This is a combinational circuit that checks all possible positions

    integer i;
    always @(*) begin
        match = 0;

        // Search for pattern in the string
        // Extract each 8-bit character from the packed input
        for (i = 0; i < 13; i = i + 1) begin
            // Check if we have enough characters remaining
            if (i + 3 < length) begin
                // Extract characters at positions i, i+1, i+2, i+3
                if (text_in[i*8 +: 8] == 8'h61 &&           // 'a' at position i
                    text_in[(i+1)*8 +: 8] == 8'h62 &&       // 'b' at position i+1
                    text_in[(i+2)*8 +: 8] == 8'h62 &&       // 'b' at position i+2
                    text_in[(i+3)*8 +: 8] == 8'h62) begin   // 'b' at position i+3
                    match = 1;
                end
            end
        end
    end

endmodule

// INTERFACE SPECIFICATION:
// - text_in: 128-bit wire, packed ASCII characters (text_in[7:0] = first char)
// - length: 4-bit input, number of valid characters (0-15)
// - match: 1-bit output, high when pattern found
// - Combinational: output updates after logic propagation
// - ASCII values: 'a' = 0x61 (97), 'b' = 0x62 (98)

module string_length_sum (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input: 8 names, each 8 characters (8-bit ASCII each)
    // Interface: names_{name_idx}_{char_idx}
    input wire [7:0] names_0_0, names_0_1, names_0_2, names_0_3, names_0_4, names_0_5, names_0_6, names_0_7,
    input wire [7:0] names_1_0, names_1_1, names_1_2, names_1_3, names_1_4, names_1_5, names_1_6, names_1_7,
    input wire [7:0] names_2_0, names_2_1, names_2_2, names_2_3, names_2_4, names_2_5, names_2_6, names_2_7,
    input wire [7:0] names_3_0, names_3_1, names_3_2, names_3_3, names_3_4, names_3_5, names_3_6, names_3_7,
    input wire [7:0] names_4_0, names_4_1, names_4_2, names_4_3, names_4_4, names_4_5, names_4_6, names_4_7,
    input wire [7:0] names_5_0, names_5_1, names_5_2, names_5_3, names_5_4, names_5_5, names_5_6, names_5_7,
    input wire [7:0] names_6_0, names_6_1, names_6_2, names_6_3, names_6_4, names_6_5, names_6_6, names_6_7,
    input wire [7:0] names_7_0, names_7_1, names_7_2, names_7_3, names_7_4, names_7_5, names_7_6, names_7_7,

    output reg [15:0] result,
    output reg done
);

    // State definitions
    localparam IDLE = 3'd0;
    localparam VALIDATE_NAME = 3'd1;
    localparam COUNT_LENGTH = 3'd2;
    localparam UPDATE_ACCUM = 3'd3;
    localparam NEXT_NAME = 3'd4;
    localparam FINISHED = 3'd5;

    // Internal registers
    reg [2:0] state;
    reg [2:0] name_idx;
    reg [3:0] char_idx;
    reg [15:0] accumulator;
    reg [3:0] current_length;
    reg name_valid;

    // Helper: Get character value based on indices
    wire [7:0] current_char;
    assign current_char = get_char(name_idx, char_idx);

    function automatic [7:0] get_char(input [2:0] n_idx, input [3:0] c_idx);
        case (n_idx)
            3'd0: case (c_idx)
                4'd0: return names_0_0; 4'd1: return names_0_1; 4'd2: return names_0_2; 4'd3: return names_0_3,
                4'd4: return names_0_4; 4'd5: return names_0_5; 4'd6: return names_0_6; default: return names_0_7; endcase
            3'd1: case (c_idx)
                4'd0: return names_1_0; 4'd1: return names_1_1; 4'd2: return names_1_2; 4'd3: return names_1_3,
                4'd4: return names_1_4; 4'd5: return names_1_5; 4'd6: return names_1_6; default: return names_1_7; endcase
            3'd2: case (c_idx)
                4'd0: return names_2_0; 4'd1: return names_2_1; 4'd2: return names_2_2; 4'd3: return names_2_3,
                4'd4: return names_2_4; 4'd5: return names_2_5; 4'd6: return names_2_6; default: return names_2_7; endcase
            3'd3: case (c_idx)
                4'd0: return names_3_0; 4'd1: return names_3_1; 4'd2: return names_3_2; 4'd3: return names_3_3,
                4'd4: return names_3_4; 4'd5: return names_3_5; 4'd6: return names_3_6; default: return names_3_7; endcase
            3'd4: case (c_idx)
                4'd0: return names_4_0; 4'd1: return names_4_1; 4'd2: return names_4_2; 4'd3: return names_4_3,
                4'd4: return names_4_4; 4'd5: return names_4_5; 4'd6: return names_4_6; default: return names_4_7; endcase
            3'd5: case (c_idx)
                4'd0: return names_5_0; 4'd1: return names_5_1; 4'd2: return names_5_2; 4'd3: return names_5_3,
                4'd4: return names_5_4; 4'd5: return names_5_5; 4'd6: return names_5_6; default: return names_5_7; endcase
            3'd6: case (c_idx)
                4'd0: return names_6_0; 4'd1: return names_6_1; 4'd2: return names_6_2; 4'd3: return names_6_3,
                4'd4: return names_6_4; 4'd5: return names_6_5; 4'd6: return names_6_6; default: return names_6_7; endcase
            default: case (c_idx)
                4'd0: return names_7_0; 4'd1: return names_7_1; 4'd2: return names_7_2; 4'd3: return names_7_3,
                4'd4: return names_7_4; 4'd5: return names_7_5; 4'd6: return names_7_6; default: return names_7_7; endcase
        endcase
    endfunction

    // Character property checks
    wire is_upper = (current_char >= 8'd65) && (current_char <= 8'd90);
    wire is_lower = (current_char >= 8'd97) && (current_char <= 8'd122);
    wire is_null = (current_char == 8'd0);

    // Main state machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 16'd0;
            done <= 1'b0;
            accumulator <= 16'd0;
            name_idx <= 3'd0;
            char_idx <= 4'd0;
            current_length <= 4'd0;
            name_valid <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= VALIDATE_NAME;
                        accumulator <= 16'd0;
                        name_idx <= 3'd0;
                        char_idx <= 4'd0;
                        name_valid <= 1'b1;
                    end
                end

                VALIDATE_NAME: begin
                    // Check first char (must be uppercase)
                    if (char_idx == 4'd0) begin
                        if (!is_upper) begin
                            name_valid <= 1'b0;
                        end
                        char_idx <= 4'd1;
                    end else if (char_idx < 4'd8) begin
                        // Check remaining chars (must be lowercase or null)
                        if (name_valid && !is_null && !is_lower) begin
                            name_valid <= 1'b0;
                        end
                        char_idx <= char_idx + 1'b1;
                    end else begin
                        // Validation complete
                        char_idx <= 4'd0;
                        if (name_valid) begin
                            state <= COUNT_LENGTH;
                        end else begin
                            state <= NEXT_NAME;
                        end
                    end
                end

                COUNT_LENGTH: begin
                    if (char_idx < 4'd8) begin
                        if (!is_null) begin
                            current_length <= current_length + 1'b1;
                        end
                        char_idx <= char_idx + 1'b1;
                    end else begin
                        // Length counting complete
                        state <= UPDATE_ACCUM;
                        char_idx <= 4'd0;
                    end
                end

                UPDATE_ACCUM: begin
                    accumulator <= accumulator + {12'd0, current_length};
                    current_length <= 4'd0;
                    state <= NEXT_NAME;
                end

                NEXT_NAME: begin
                    if (name_idx == 3'd7) begin
                        state <= FINISHED;
                    end else begin
                        name_idx <= name_idx + 1'b1;
                        char_idx <= 4'd0;
                        name_valid <= 1'b1;
                        state <= VALIDATE_NAME;
                    end
                end

                FINISHED: begin
                    result <= accumulator;
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module new_tuple (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input array of strings: 8 elements, each 16 characters (128 bits)
    input wire [127:0] test_str_arr [0:7],
    input wire [2:0] input_len,  // Number of valid input strings (1-8)

    // Input string to append: 16 characters (128 bits)
    input wire [127:0] test_str,

    // Output array: input_len + 1 strings
    output reg [127:0] result_arr [0:8],
    output reg [3:0] output_len,  // = input_len + 1
    output reg done
);

// State machine for sequential processing
reg [2:0] state;
reg [2:0] idx;

localparam IDLE = 3'b000;
localparam COPY = 3'b001;
localparam APPEND = 3'b010;
localparam FINISH = 3'b011;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        idx <= 3'b0;
        done <= 1'b0;
        output_len <= 4'b0;
        // Clear result array
        for (integer i = 0; i < 9; i = i + 1) begin
            result_arr[i] <= 128'b0;
        end
    end else begin
        case (state)
            IDLE: begin
                done <= 1'b0;
                idx <= 3'b0;
                if (start) begin
                    state <= COPY;
                    output_len <= input_len + 4'd1;
                end
            end

            COPY: begin
                if (idx < input_len) begin
                    result_arr[idx] <= test_str_arr[idx];
                    idx <= idx + 3'd1;
                end else begin
                    state <= APPEND;
                end
            end

            APPEND: begin
                result_arr[input_len] <= test_str;
                state <= FINISH;
            end

            FINISH: begin
                done <= 1'b1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

module tuple_dict_appender (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] tuple_data [0:3],  // 4-element tuple, each 32-bit
    input wire [31:0] dict_data,          // Packed dictionary (3x key-value pairs)
    output reg [31:0] result [0:4],       // 5-element result tuple
    output reg done
);

// This module appends a dictionary value to a tuple
// Input tuple: 4 elements of 32-bit each (indices 0-3)
// Input dict: 32-bit packed value representing dictionary
// Output tuple: 5 elements, where result[4] = dict_data
// Timing: Assert start for 1 cycle, done goes high after 2 cycles

integer i;
reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset: clear all outputs
        for (i = 0; i < 5; i = i + 1) begin
            result[i] <= 32'b0;
        end
        done <= 1'b0;
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin  // Idle state
                done <= 1'b0;
                if (start) begin
                    state <= 2'b01;
                end
            end

            2'b01: begin  // Copy first 4 elements from tuple
                for (i = 0; i < 4; i = i + 1) begin
                    result[i] <= tuple_data[i];
                end
                state <= 2'b10;
            end

            2'b10: begin  // Append dictionary as 5th element
                result[4] <= dict_data;
                done <= 1'b1;
                state <= 2'b11;
            end

            2'b11: begin  // Wait for start to go low
                done <= 1'b0;
                if (!start) begin
                    state <= 2'b00;
                end
            end
        endcase
    end
end

endmodule

module even_position_check (
    input wire [7:0] arr_0,  // 8-bit elements
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [2:0] len,     // Number of valid elements (1-3)
    output wire result        // 1=pass, 0=fail
);

    // Internal wires for each comparison
    wire [2:0] checks;
    wire [2:0] element_parity;
    wire [2:0] index_parity;

    // Calculate parity for each element (even=0, odd=1)
    assign element_parity[0] = arr_0[0];
    assign element_parity[1] = arr_1[0];
    assign element_parity[2] = arr_2[0];

    // Index parity: 0%2=0, 1%2=1, 2%2=0
    assign index_parity[0] = 1'b0;
    assign index_parity[1] = 1'b1;
    assign index_parity[2] = 1'b0;

    // Check if element_parity == index_parity for each valid position
    assign checks[0] = (element_parity[0] == index_parity[0]);
    assign checks[1] = (element_parity[1] == index_parity[1]);
    assign checks[2] = (element_parity[2] == index_parity[2]);

    // Result is true only if ALL valid positions pass
    // len=1: check[0], len=2: check[0]&check[1], len=3: check[0]&check[1]&check[2]
    assign result = (
        (len >= 3'd1) && (checks[0]) &&
        (len >= 3'd2) && (checks[1]) &&
        (len >= 3'd3) && (checks[2])
    );

endmodule

module sector_area (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] radius,        // Q8.8 format: 8 integer, 8 fractional bits
    input wire [15:0] angle,         // Q8.8 format: angle in degrees with 8 fractional bits
    output reg [31:0] result,        // Q16.16 format result
    output reg done,
    output reg invalid               // High when angle > 360 degrees
);

    // Fixed-point constants
    // PI in Q16.16 format = 3.14159265 * 65536 = 205887
    localparam PI_Q16 = 205887;
    // 360 in Q8.8 format = 360 * 256 = 92160
    localparam ANGLE_360 = 92160;
    // Division by 360 implemented as multiplication by 1/360
    // 1/360 in Q16.16 = 65536 / 360 = 182 (approx)
    localparam INV_360_Q16 = 182;

    // State machine states
    localparam IDLE = 2'b00;
    localparam CHECK = 2'b01;
    localparam COMPUTE = 2'b10;
    localparam DONE = 2'b11;

    reg [1:0] state;
    reg [1:0] next_state;

    // Internal registers for intermediate results
    reg [31:0] r_squared;      // Q16.16
    reg [31:0] pi_r_sq;        // Q24.16
    reg [31:0] angle_norm;     // Q16.16 (angle normalized to 0-1 range)
    reg [31:0] result_temp;    // Q32.16 (temporary for multiplication)

    // Multiplier control
    reg mult_start;
    wire [31:0] mult_result;
    wire mult_done;
    reg [31:0] mult_a, mult_b;

    // Sequential multiplier (simplified - 32 cycles)
    reg [5:0] mult_count;
    reg mult_active;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mult_active <= 0;
            mult_count <= 0;
            mult_result <= 0;
        end else if (mult_start) begin
            mult_active <= 1;
            mult_count <= 0;
            mult_result <= mult_a * mult_b;  // Simplified: single-cycle multiplication
            mult_active <= 0;  // Mark as complete
        end
    end

    assign mult_done = mult_active;

    // State transitions
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = CHECK;
                else
                    next_state = IDLE;
            end
            CHECK: begin
                next_state = COMPUTE;
            end
            COMPUTE: begin
                next_state = DONE;
            end
            DONE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            result <= 0;
            done <= 0;
            invalid <= 0;
            mult_start <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    invalid <= 0;
                    mult_start <= 0;
                end

                CHECK: begin
                    // Check if angle > 360 (both in Q8.8)
                    if (angle > ANGLE_360) begin
                        invalid <= 1;
                        result <= 0;
                    end else begin
                        invalid <= 0;
                        // Compute r^2 in Q16.16
                        // radius is Q8.8, r^2 = (radius * radius) >> 8
                        r_squared <= (radius * radius) >> 8;
                    end
                end

                COMPUTE: begin
                    if (!invalid) begin
                        // Step 1: pi * r^2 -> pi_r_sq
                        // PI_Q16 (Q16.16) * r_squared (Q16.16) = Q32.32, shift right 16 = Q16.16
                        pi_r_sq <= (PI_Q16 * r_squared) >> 16;

                        // Step 2: normalize angle (divide by 360)
                        // angle (Q8.8) * INV_360_Q16 (Q16.16) = Q24.24, shift right 8 = Q16.16
                        angle_norm <= (angle * INV_360_Q16) >> 8;

                        // Step 3: multiply pi*r^2 * normalized angle
                        // pi_r_sq (Q16.16) * angle_norm (Q16.16) = Q32.32, shift right 16 = Q16.16
                        result_temp <= (pi_r_sq * angle_norm);
                    end
                end

                DONE: begin
                    if (!invalid) begin
                        // Final result in Q16.16
                        result <= result_temp >> 16;
                    end
                    done <= 1;
                end

                default: begin
                    result <= 0;
                    done <= 0;
                    invalid <= 0;
                end
            endcase
        end
    end

endmodule

module count_same_pair (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire signed [7:0] arr1 [0:7],
    input wire signed [7:0] arr2 [0:7],
    output reg signed [15:0] result,
    output reg done
);
    reg [2:0] idx;
    reg [3:0] count;
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam COMPARE = 2'b01;
    localparam DONE = 2'b10;

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            idx <= 3'b0;
            count <= 4'b0;
            result <= 16'sd0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= COMPARE;
                        idx <= 3'b0;
                        count <= 4'b0;
                    end
                end
                COMPARE: begin
                    if (arr1[idx] == arr2[idx]) begin
                        count <= count + 1'b1;
                    end
                    if (idx == 3'd7) begin
                        state <= DONE;
                    end else begin
                        idx <= idx + 1'b1;
                    end
                end
                DONE: begin
                    result <= {12'b0, count};
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

module first_repeated_char (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_0,
    input wire [7:0] char_1,
    input wire [7:0] char_2,
    input wire [7:0] char_3,
    input wire [7:0] char_4,
    input wire [7:0] char_5,
    input wire [7:0] char_6,
    input wire [7:0] char_7,
    input wire [7:0] char_8,
    input wire [7:0] char_9,
    input wire [7:0] char_10,
    input wire [7:0] char_11,
    input wire [7:0] char_12,
    input wire [7:0] char_13,
    input wire [7:0] char_14,
    input wire [7:0] char_15,
    input wire [4:0] str_len,         // Length of string (0-16)
    output reg [7:0] result_char,     // First repeated character
    output reg result_valid,           // High when result is valid
    output reg done                   // High for 1 cycle when complete
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam CHECKING = 2'b01;
    localparam DONE_STATE = 2'b10;

    reg [1:0] state;
    reg [4:0] check_idx;       // Current character being checked
    reg [4:0] compare_idx;     // Index to compare against
    reg [7:0] char_to_check;   // Current character value
    reg found_repeat;          // Flag if repeat found

    // Array to store characters for comparison (using flip-flops)
    reg [7:0] char_storage [0:15];
    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result_char <= 8'b0;
            result_valid <= 1'b0;
            done <= 1'b0;
            check_idx <= 5'b0;
            compare_idx <= 5'b0;
            found_repeat <= 1'b0;
            // Clear storage
            for (i = 0; i < 16; i = i + 1) begin
                char_storage[i] <= 8'b0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    result_valid <= 1'b0;
                    if (start && str_len > 0) begin
                        state <= CHECKING;
                        check_idx <= 5'b0;
                        compare_idx <= 5'b1;
                        found_repeat <= 1'b0;
                        // Load first character
                        case (5'b0)
                            5'd0: char_storage[0] <= char_0;
                            5'd1: char_storage[0] <= char_1;
                            5'd2: char_storage[0] <= char_2;
                            5'd3: char_storage[0] <= char_3;
                            5'd4: char_storage[0] <= char_4;
                            5'd5: char_storage[0] <= char_5;
                            5'd6: char_storage[0] <= char_6;
                            5'd7: char_storage[0] <= char_7;
                            5'd8: char_storage[0] <= char_8;
                            5'd9: char_storage[0] <= char_9;
                            5'd10: char_storage[0] <= char_10;
                            5'd11: char_storage[0] <= char_11;
                            5'd12: char_storage[0] <= char_12;
                            5'd13: char_storage[0] <= char_13;
                            5'd14: char_storage[0] <= char_14;
                            5'd15: char_storage[0] <= char_15;
                        endcase
                    end
                end

                CHECKING: begin
                    if (!found_repeat && check_idx < str_len) begin
                        // Get current character to check
                        case (check_idx)
                            5'd0: char_to_check <= char_0;
                            5'd1: char_to_check <= char_1;
                            5'd2: char_to_check <= char_2;
                            5'd3: char_to_check <= char_3;
                            5'd4: char_to_check <= char_4;
                            5'd5: char_to_check <= char_5;
                            5'd6: char_to_check <= char_6;
                            5'd7: char_to_check <= char_7;
                            5'd8: char_to_check <= char_8;
                            5'd9: char_to_check <= char_9;
                            5'd10: char_to_check <= char_10;
                            5'd11: char_to_check <= char_11;
                            5'd12: char_to_check <= char_12;
                            5'd13: char_to_check <= char_13;
                            5'd14: char_to_check <= char_14;
                            5'd15: char_to_check <= char_15;
                        endcase

                        // Compare with previous characters
                        if (compare_idx < check_idx) begin
                            if (char_to_check == char_storage[compare_idx]) begin
                                found_repeat <= 1'b1;
                                result_char <= char_to_check;
                                result_valid <= 1'b1;
                                state <= DONE_STATE;
                            end else begin
                                compare_idx <= compare_idx + 1;
                            end
                        end else begin
                            // Store current character and move to next
                            char_storage[check_idx] <= char_to_check;
                            check_idx <= check_idx + 1;
                            compare_idx <= 5'b1;
                        end
                    end else if (found_repeat || check_idx >= str_len) begin
                        // No repeat found or end of string
                        state <= DONE_STATE;
                        if (!found_repeat) begin
                            result_valid <= 1'b0;
                            result_char <= 8'b0;
                        end
                    end
                end

                DONE_STATE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module find_first_missing (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [2:0] len,  // Number of valid elements (1-8)
    output reg [7:0] result,
    output reg done
);

    // Internal state definitions
    reg [2:0] start_idx;
    reg [2:0] end_idx;
    reg [2:0] mid_idx;
    reg searching;
    reg [2:0] shift_count; // For reading array values

    // Combinational array access (MUX for arr[mid_idx])
    reg [7:0] arr_mid;
    always @(*) begin
        case (mid_idx)
            3'd0: arr_mid = arr_0;
            3'd1: arr_mid = arr_1;
            3'd2: arr_mid = arr_2;
            3'd3: arr_mid = arr_3;
            3'd4: arr_mid = arr_4;
            3'd5: arr_mid = arr_5;
            3'd6: arr_mid = arr_6;
            3'd7: arr_mid = arr_7;
            default: arr_mid = 8'hFF;
        endcase
    end

    // Combinational array access for start_idx
    reg [7:0] arr_start;
    always @(*) begin
        case (start_idx)
            3'd0: arr_start = arr_0;
            3'd1: arr_start = arr_1;
            3'd2: arr_start = arr_2;
            3'd3: arr_start = arr_3;
            3'd4: arr_start = arr_4;
            3'd5: arr_start = arr_5;
            3'd6: arr_start = arr_6;
            3'd7: arr_start = arr_7;
            default: arr_start = 8'hFF;
        endcase
    end

    // State machine
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 1'b0;
            result <= 8'b0;
            searching <= 1'b0;
            start_idx <= 3'b0;
            end_idx <= 3'b0;
            shift_count <= 3'b0;
        end else begin
            if (start && !searching && !done) begin
                // Initialize: use len for end, but cap at 8
                start_idx <= 3'b0;
                end_idx <= (len > 3'd7) ? 3'd7 : len - 1'b1;
                searching <= 1'b1;
                done <= 1'b0;
                shift_count <= 3'b0;
            end else if (searching) begin
                // Binary search state machine
                if (shift_count < 3'd3) begin
                    // Wait 3 cycles for combinational reads to settle
                    shift_count <= shift_count + 1'b1;
                end else begin
                    shift_count <= 3'b0;

                    if (start_idx > end_idx) begin
                        // Found: end_idx + 1
                        result <= end_idx + 1'b1;
                        searching <= 1'b0;
                        done <= 1'b1;
                    end else if (start_idx != arr_start) begin
                        // Found: start_idx
                        result <= start_idx;
                        searching <= 1'b0;
                        done <= 1'b1;
                    end else if (arr_mid == mid_idx) begin
                        // Search right half
                        start_idx <= mid_idx + 1'b1;
                        shift_count <= 3'b0;
                    end else begin
                        // Search left half
                        end_idx <= mid_idx - 1'b1;
                        shift_count <= 3'b0;
                    end
                end

                // Calculate mid (combinationally, but captured in state)
                mid_idx <= (start_idx + end_idx) >> 1;
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

module multiply_adjacent (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [3:0] length,  // Number of valid input elements (1-5)
    output reg [15:0] result,
    output reg result_valid,
    output reg done
);

    // State machine states
    reg [2:0] state;
    localparam IDLE = 3'b000;
    localparam COMPUTE = 3'b001;
    localparam OUTPUT = 3'b010;
    localparam FINISHED = 3'b011;

    // Internal registers
    reg [2:0] index;           // Current pair index (0 to length-2)
    reg [15:0] product_reg;    // Temporary product storage

    // Input array storage (for sequential access)
    reg [7:0] input_data [0:4];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state <= IDLE;
            result <= 16'b0;
            result_valid <= 1'b0;
            done <= 1'b0;
            index <= 3'b0;
            product_reg <= 16'b0;
        end else begin
            case (state)
                IDLE: begin
                    result_valid <= 1'b0;
                    done <= 1'b0;
                    index <= 3'b0;

                    if (start && length >= 2) begin
                        // Load input array
                        input_data[0] <= arr_0;
                        input_data[1] <= arr_1;
                        input_data[2] <= arr_2;
                        input_data[3] <= arr_3;
                        input_data[4] <= arr_4;
                        state <= COMPUTE;
                    end else if (start && length == 1) begin
                        // Special case: single element, return empty
                        done <= 1'b1;
                        state <= FINISHED;
                    end
                end

                COMPUTE: begin
                    // Compute product of current adjacent pair
                    product_reg <= input_data[index] * input_data[index + 1];
                    index <= index + 1;
                    state <= OUTPUT;
                end

                OUTPUT: begin
                    // Output the product and check if done
                    result <= product_reg;
                    result_valid <= 1'b1;

                    if (index >= length - 1) begin
                        // All pairs computed
                        done <= 1'b1;
                        state <= FINISHED;
                    end else begin
                        // More pairs to compute
                        state <= COMPUTE;
                    end
                end

                FINISHED: begin
                    // Wait for start to go low
                    if (!start) begin
                        result_valid <= 1'b0;
                        done <= 1'b0;
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module extract_quotation(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [5:0] input_len,  // 0-63 chars
    input wire [7:0] input_str [0:63],  // 64-char ASCII string
    output reg [5:0] count,  // Number of substrings found (0-4)
    output reg [4:0] found_len0, found_len1, found_len2, found_len3,  // Length of each substring
    output reg [7:0] found0 [0:15], found1 [0:15], found2 [0:15], found3 [0:15],  // Extracted substrings
    output reg done
);

// States
localparam IDLE = 2'b00;
localparam SCANNING = 2'b01;
localparam FINISHED = 2'b10;

reg [1:0] state;
reg [5:0] scan_idx;  // Index into input string
reg [3:0] sub_idx;   // Current substring index (0-3)
reg [3:0] char_idx;  // Character index within current substring (0-15)
reg in_quotes;       // Inside quote flag
reg [7:0] quote_char;  // Stores opening quote character

// Output registers
reg [5:0] count_reg;
reg [4:0] found_len_reg [0:3];
reg [7:0] found_reg0 [0:15];
reg [7:0] found_reg1 [0:15];
reg [7:0] found_reg2 [0:15];
reg [7:0] found_reg3 [0:15];
reg done_reg;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        scan_idx <= 0;
        sub_idx <= 0;
        char_idx <= 0;
        in_quotes <= 0;
        quote_char <= 0;
        count_reg <= 0;
        done_reg <= 0;
        for (i = 0; i < 16; i = i + 1) begin
            found_reg0[i] <= 0;
            found_reg1[i] <= 0;
            found_reg2[i] <= 0;
            found_reg3[i] <= 0;
        end
        for (i = 0; i < 4; i = i + 1) begin
            found_len_reg[i] <= 0;
        end
    end else begin
        case (state)
            IDLE: begin
                done_reg <= 0;
                if (start && input_len > 0) begin
                    state <= SCANNING;
                    scan_idx <= 0;
                    sub_idx <= 0;
                    char_idx <= 0;
                    in_quotes <= 0;
                    quote_char <= 0;
                    count_reg <= 0;
                end
            end

            SCANNING: begin
                if (scan_idx < input_len && sub_idx < 4) begin
                    // Process character
                    if (!in_quotes) begin
                        // Looking for opening quote
                        if (input_str[scan_idx] == 8'h22 || input_str[scan_idx] == 8'h27) begin
                            in_quotes <= 1;
                            quote_char <= input_str[scan_idx];
                            char_idx <= 0;
                        end
                    end else begin
                        // Inside quotes
                        if (input_str[scan_idx] == quote_char) begin
                            // Closing quote found
                            in_quotes <= 0;
                            // Record substring length
                            case (sub_idx)
                                0: found_len_reg[0] <= char_idx;
                                1: found_len_reg[1] <= char_idx;
                                2: found_len_reg[2] <= char_idx;
                                3: found_len_reg[3] <= char_idx;
                            endcase
                            sub_idx <= sub_idx + 1;
                            count_reg <= sub_idx + 1;
                        end else if (char_idx < 16) begin
                            // Store character in current substring
                            case (sub_idx)
                                0: found_reg0[char_idx] <= input_str[scan_idx];
                                1: found_reg1[char_idx] <= input_str[scan_idx];
                                2: found_reg2[char_idx] <= input_str[scan_idx];
                                3: found_reg3[char_idx] <= input_str[scan_idx];
                            endcase
                            char_idx <= char_idx + 1;
                        end
                    end
                    scan_idx <= scan_idx + 1;
                end else begin
                    // Done scanning
                    state <= FINISHED;
                end
            end

            FINISHED: begin
                done_reg <= 1;
                state <= IDLE;
            end
        endcase
    end
end

// Assign outputs
assign count = count_reg;
assign found_len0 = found_len_reg[0];
assign found_len1 = found_len_reg[1];
assign found_len2 = found_len_reg[2];
assign found_len3 = found_len_reg[3];
assign done = done_reg;

assign found0 = found_reg0;
assign found1 = found_reg1;
assign found2 = found_reg2;
assign found3 = found_reg3;

endmodule

module word_k_remover (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,  // Current character from string buffer (ASCII)
    input wire [3:0] k_len,     // Target length to remove (1-8)
    input wire [3:0] str_len,   // Total length of string (1-16)
    output reg [7:0] char_out,  // Output character
    output reg [3:0] out_idx,   // Output index
    output reg out_valid,       // High when char_out is valid
    output reg done             // High when processing complete
);

    // Internal state
    reg [3:0] state;
    reg [3:0] in_idx;           // Input index
    reg [3:0] word_len;         // Current word length
    reg [7:0] temp_chars [0:7]; // Buffer for up to 8 chars of current word
    reg [3:0] temp_idx;         // Index in temp buffer
    reg remove_flag;            // Flag if current word should be removed

    // State definitions
    localparam IDLE = 4'd0;
    localparam READ_CHAR = 4'd1;
    localparam CHECK_SPACE = 4'd2;
    localparam STORE_CHAR = 4'd3;
    localparam CALC_LEN = 4'd4;
    localparam DECIDE = 4'd5;
    localparam OUTPUT_WORD = 4'd6;
    localparam OUTPUT_SPACE = 4'd7;
    localparam FINISH = 4'd8;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            out_valid <= 0;
            out_idx <= 0;
            in_idx <= 0;
            word_len <= 0;
            temp_idx <= 0;
            remove_flag <= 0;
            char_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    out_valid <= 0;
                    out_idx <= 0;
                    in_idx <= 0;
                    word_len <= 0;
                    temp_idx <= 0;
                    if (start && str_len > 0) begin
                        state <= READ_CHAR;
                    end else begin
                        state <= IDLE;
                    end
                end

                READ_CHAR: begin
                    // In a real system, char_in would be a memory read
                    // Here we assume char_in is driven by external logic based on in_idx
                    // For this testbench compatibility, we act as a state machine
                    // Assume input stream comes in
                    // To make it synthesizable and testable, we need a standard interface
                    // Let's treat it as: state machine waits for input, processes it
                    // Since Verilog modules need defined ports, we assume external memory
                    // drives char_in based on in_idx.
                    // We need to wait for input to be valid.
                    // Simplification: Process 1 char per cycle.
                    // Check if it's space
                    if (char_in == 8'h20 || in_idx == str_len) begin
                        state <= CHECK_SPACE;
                    end else begin
                        state <= STORE_CHAR;
                    end
                end

                STORE_CHAR: begin
                    if (temp_idx < 8) begin
                        temp_chars[temp_idx] <= char_in;
                        temp_idx <= temp_idx + 1;
                        word_len <= word_len + 1;
                    end
                    in_idx <= in_idx + 1;
                    state <= READ_CHAR;
                end

                CHECK_SPACE: begin
                    // End of word or end of string
                    state <= CALC_LEN;
                end

                CALC_LEN: begin
                    // Compare word_len with k_len
                    if (word_len == k_len && word_len > 0) begin
                        remove_flag <= 1;
                    end else begin
                        remove_flag <= 0;
                    end
                    // Reset word_len for next word
                    word_len <= 0;
                    // Prepare to output
                    temp_idx <= 0;
                    if (in_idx == str_len && char_in != 8'h20 && temp_idx == 0) begin
                         // Edge case: end of string without space handled in READ_CHAR
                    end
                    state <= DECIDE;
                end

                DECIDE: begin
                    if (remove_flag) begin
                        // Skip outputting this word
                        temp_idx <= 0;
                        if (in_idx < str_len) begin
                            // Output space if not the first word and not removed
                            // Actually, logic is tricky. 
                            // We need to output space *between* kept words.
                            // Let's rely on a simpler flow:
                            // Just loop. If remove_flag, do nothing. 
                            // Output space only if previous word was kept.
                            // We'll use 'out_idx' to track if we have output anything yet.
                            state <= NEXT_STEP;
                        end else begin
                            state <= FINISH;
                        end
                    end else begin
                        state <= OUTPUT_WORD;
                    end
                end

                // Helper state to clean up
                NEXT_STEP: begin
                     temp_idx <= 0;
                     if (in_idx < str_len) begin
                         // We need to skip the space that triggered this word
                         // In this architecture, the space character triggered CHECK_SPACE
                         // We need to consume it or handle it.
                         // Let's assume input stream includes the space.
                         // We consumed the space? No, READ_CHAR triggered on space.
                         // So we need to advance input index past the space (if not end).
                         // Actually, in_idx increments only on STORE_CHAR.
                         // If we were at a space, in_idx hasn't incremented past it yet (unless logic changes).
                         // Let's re-verify READ_CHAR.
                         // If space -> CHECK_SPACE. in_idx not incremented.
                         // So we must increment in_idx here to skip the space.
                         in_idx <= in_idx + 1;
                         state <= READ_CHAR;
                     end else begin
                         state <= FINISH;
                     end
                end

                OUTPUT_WORD: begin
                    if (temp_idx < word_len) begin
                        char_out <= temp_chars[temp_idx];
                        out_valid <= 1;
                        temp_idx <= temp_idx + 1;
                        out_idx <= out_idx + 1;
                        state <= OUTPUT_WORD;
                    end else begin
                        out_valid <= 0;
                        // Output space if there are more words coming
                        if (in_idx < str_len) begin
                            state <= OUTPUT_SPACE;
                        end else begin
                            state <= FINISH;
                        end
                    end
                end

                OUTPUT_SPACE: begin
                    char_out <= 8'h20;
                    out_valid <= 1;
                    out_idx <= out_idx + 1;
                    // Skip the space in input stream (in_idx is already at the space? 
                    // No, in_idx is at the character AFTER the word. 
                    // The space was read. We need to move in_idx past it.
                    // In READ_CHAR, space triggers CHECK_SPACE. in_idx not incremented.
                    // So we increment here.
                    in_idx <= in_idx + 1;
                    state <= IDLE; // Go back to idle to process next word
                    // Wait, IDLE resets things. We want to continue.
                    // State should go to READ_CHAR to process next word.
                    // But we must preserve 'out_idx' and 'in_idx'.
                    // Let's create a CONTINUE state.
                    state <= CONTINUE;
                end

                CONTINUE: begin
                    out_valid <= 0;
                    state <= READ_CHAR;
                end

                FINISH: begin
                    done <= 1;
                    out_valid <= 0;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

// Module Name: grid_path_solver
// Description:
//   Sequential hardware accelerator for finding the maximum cost path in an N*N grid.
//   Supports N = 2 to 8. Costs are 8-bit unsigned integers.
//   Algorithm: Dynamic Programming.
//   Output: Maximum sum (16-bit) and Path Length (4-bit).
//   Note: Division for average is performed by the testbench.
//
// Interface:
//   - System: clk, rst_n (active low)
//   - Memory Load: din (8-bit data), addr (6-bit address), write (load enable)
//     Address format: row * 8 + col (row-major, stride 8 for max 8x8)
//   - Control: start (pulse high), N (grid size, 3-bit)
//   - Output: max_sum (16-bit), path_len (4-bit), valid (pulse high)
//
// Algorithm Steps:
//   1. IDLE: Wait for start. Handle 'write' to store 'din' into cost_mem[addr].
//   2. START: Initialize dp[0][0] = cost_mem[0].
//   3. ROW_FILL: Fill dp[0][j] = dp[0][j-1] + cost_mem[j] for j=1..N-1.
//   4. COL_FILL: Fill dp[i][0] = dp[i-1][0] + cost_mem[i*8] for i=1..N-1.
//   5. FILL: Fill dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost_mem[i*8+j] for i,j=1..N-1.
//   6. OUTPUT: Assign max_sum = dp[N-1][N-1], path_len = 2*N - 1, assert valid.

module grid_path_solver (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] din,
    input wire [5:0] addr,
    input wire write,
    input wire [2:0] N,
    output reg [15:0] max_sum,
    output reg [3:0] path_len,
    output reg valid
);
    // Internal Memory for Cost Matrix (64 entries x 8-bit)
    reg [7:0] cost_mem [0:63];

    // DP Table Registers (8x8 grid, 16-bit sums to handle max ~3800)
    reg [15:0] dp [0:7][0:7];

    // State Machine Definition
    localparam IDLE = 3'b000;
    localparam START = 3'b001;
    localparam ROW_FILL = 3'b010;
    localparam COL_FILL = 3'b011;
    localparam FILL = 3'b100;
    localparam OUTPUT = 3'b101;

    reg [2:0] state;
    reg [2:0] i, j; // Loop counters

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            valid <= 0;
            max_sum <= 0;
            path_len <= 0;
        end else begin
            valid <= 0; // Auto-clear valid

            case (state)
                IDLE: begin
                    // Handle synchronous memory loading
                    if (write) begin
                        cost_mem[addr] <= din;
                    end

                    if (start) begin
                        // Initialize counters for computation
                        i <= 0;
                        j <= 0;
                        state <= START;
                    end
                end

                START: begin
                    // Initialize top-left cell
                    dp[0][0] <= cost_mem[0];
                    j <= 1;
                    state <= ROW_FILL;
                end

                ROW_FILL: begin
                    if (j < N) begin
                        // Fill row 0: dp[0][j] = dp[0][j-1] + cost_mem[j]
                        dp[0][j] <= dp[0][j-1] + cost_mem[j];
                        j <= j + 1;
                    end else begin
                        // Row fill done, move to column fill
                        i <= 1;
                        state <= COL_FILL;
                    end
                end

                COL_FILL: begin
                    if (i < N) begin
                        // Fill col 0: dp[i][0] = dp[i-1][0] + cost_mem[i*8]
                        // i*8 is equivalent to {i, 3'b000}
                        dp[i][0] <= dp[i-1][0] + cost_mem[{i, 3'b000}];
                        i <= i + 1;
                    end else begin
                        // Column fill done, move to inner cells
                        i <= 1;
                        j <= 1;
                        state <= FILL;
                    end
                end

                FILL: begin
                    if (i < N) begin
                        if (j < N) begin
                            // Fill dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost_mem[i*8+j]
                            if (dp[i-1][j] > dp[i][j-1])
                                dp[i][j] <= dp[i-1][j] + cost_mem[{i, j}];
                            else
                                dp[i][j] <= dp[i][j-1] + cost_mem[{i, j}];
                            j <= j + 1;
                        end else begin
                            // End of row, increment i, reset j
                            j <= 1;
                            i <= i + 1;
                        end
                    end else begin
                        // Calculation complete, go to output
                        state <= OUTPUT;
                    end
                end

                OUTPUT: begin
                    max_sum <= dp[N-1][N-1];
                    // Calculate path length: 2*N - 1
                    // {N, 1'b0} is N*2
                    path_len <= {N, 1'b0} - 1;
                    valid <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

module sum_odd_range (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] l,      // Lower bound (1-10000)
    input wire [15:0] r,      // Upper bound (1-10000, r >= l)
    output reg [31:0] result, // Sum of odd numbers in range
    output reg done           // Computation complete signal
);

    // State machine states
    localparam IDLE = 2'b00;
    localparam CALC_SUM_R = 2'b01;
    localparam CALC_SUM_L = 2'b10;
    localparam FINISH = 2'b11;

    reg [1:0] state;
    reg [1:0] calc_step;      // Tracks which calculation step we're on
    reg signed [31:0] sum_r;  // Store sum_odd(r)
    reg signed [31:0] sum_l;  // Store sum_odd(l-1)
    reg [15:0] l_reg;         // Store l locally
    reg [15:0] r_reg;         // Store r locally
    reg [15:0] n_temp;        // Temp value for calculations
    reg [15:0] terms;         // terms = (n+1)/2
    reg [31:0] terms_sq;      // terms^2

    // Combinational helper for odd check
    wire is_odd;
    assign is_odd = n_temp[0];  // LSB determines odd/even

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 1'b0;
            result <= 32'b0;
            sum_r <= 32'b0;
            sum_l <= 32'b0;
            calc_step <= 2'b00;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        l_reg <= l;
                        r_reg <= r;
                        // Start calculating sum_odd(r)
                        n_temp <= r;
                        state <= CALC_SUM_R;
                        calc_step <= 2'b00;
                    end
                end

                CALC_SUM_R: begin
                    case (calc_step)
                        2'b00: begin
                            // Step 0: Calculate terms = (n+1)/2
                            // For r >= 1, this is safe with 16-bit
                            terms <= (n_temp + 16'd1) >> 1;  // Divide by 2
                            calc_step <= 2'b01;
                        end
                        2'b01: begin
                            // Step 1: Square the terms
                            terms_sq <= terms * terms;
                            calc_step <= 2'b10;
                        end
                        2'b10: begin
                            // Step 2: Store result and start sum_odd(l-1)
                            sum_r <= {16'b0, terms_sq[15:0]};  // Store as 32-bit
                            if (l_reg > 16'd1) begin
                                n_temp <= l_reg - 16'd1;
                            end else begin
                                n_temp <= 16'd0;  // l=1 means l-1=0
                            end
                            state <= CALC_SUM_L;
                            calc_step <= 2'b00;
                        end
                    endcase
                end

                CALC_SUM_L: begin
                    case (calc_step)
                        2'b00: begin
                            // Step 0: For n=0, sum is 0. Otherwise calculate.
                            if (n_temp == 16'd0) begin
                                sum_l <= 32'b0;
                                state <= FINISH;
                            end else begin
                                terms <= (n_temp + 16'd1) >> 1;
                                calc_step <= 2'b01;
                            end
                        end
                        2'b01: begin
                            terms_sq <= terms * terms;
                            calc_step <= 2'b10;
                        end
                        2'b10: begin
                            sum_l <= {16'b0, terms_sq[15:0]};
                            state <= FINISH;
                        end
                    endcase
                end

                FINISH: begin
                    result <= sum_r - sum_l;  // sum_in_range = sum_odd(r) - sum_odd(l-1)
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

