module substring_search #(
    parameter TEXT_LEN = 32,
    parameter PATTERN_LEN = 8,
    parameter CHAR_WIDTH = 8
) (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [CHAR_WIDTH-1:0] text[TEXT_LEN],
    input wire [CHAR_WIDTH-1:0] pattern[PATTERN_LEN],
    input wire [5:0] text_valid_len,  // Actual length of text (1-32)
    input wire [3:0] pattern_valid_len,  // Actual length of pattern (1-8)
    output reg found,
    output reg [5:0] match_start,
    output reg [5:0] match_end,
    output reg done
);

// State machine states
localparam IDLE = 2'd0;
localparam SEARCH = 2'd1;
localparam COMPLETE = 2'd2;

reg [1:0] state;
reg [5:0] text_idx;      // Position in text
reg [3:0] pattern_idx;   // Position in pattern
reg match_in_progress;
reg [5:0] current_match_start;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        found <= 0;
        match_start <= 0;
        match_end <= 0;
        done <= 0;
        text_idx <= 0;
        pattern_idx <= 0;
        match_in_progress <= 0;
        current_match_start <= 0;
    end else begin
        case (state)
            IDLE: begin
                done <= 0;
                if (start && text_valid_len > 0 && pattern_valid_len > 0) begin
                    state <= SEARCH;
                    text_idx <= 0;
                    pattern_idx <= 0;
                    match_in_progress <= 0;
                    found <= 0;
                end
            end

            SEARCH: begin
                if (text_idx < text_valid_len) begin
                    // Check if current text character matches pattern
                    if (text[text_idx] == pattern[pattern_idx]) begin
                        if (!match_in_progress) begin
                            // Start of new match
                            match_in_progress <= 1;
                            current_match_start <= text_idx;
                            pattern_idx <= 1;
                        end else begin
                            // Continue existing match
                            pattern_idx <= pattern_idx + 1;
                        end
                        text_idx <= text_idx + 1;

                        // Check if full pattern matched
                        if (pattern_idx == pattern_valid_len - 1) begin
                            found <= 1;
                            match_start <= current_match_start;
                            match_end <= text_idx + 1;
                            state <= COMPLETE;
                            done <= 1;
                            match_in_progress <= 0;
                        end
                    end else begin
                        // No match at this position
                        if (match_in_progress && text[text_idx] == pattern[0]) begin
                            // Check if first char matches - start new match
                            current_match_start <= text_idx;
                            pattern_idx <= 1;
                            text_idx <= text_idx + 1;
                        end else begin
                            // No match, move to next text position
                            match_in_progress <= 0;
                            pattern_idx <= 0;
                            text_idx <= text_idx + 1;
                        end
                    end
                end else begin
                    // Reached end of text without finding pattern
                    state <= COMPLETE;
                    done <= 1;
                    found <= 0;
                    match_start <= 0;
                    match_end <= 0;
                end
            end

            COMPLETE: begin
                // Wait for start to go low
                if (!start) begin
                    state <= IDLE;
                    done <= 0;
                end
            end

            default: state <= IDLE;
        endcase
    end
end

endmodule

module check_min_heap(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [2:0] len,
    output reg is_heap,
    output reg done
);

    // FSM states
    localparam IDLE = 3'd0;
    localparam CHECK_NODE = 3'd1;
    localparam COMPLETE = 3'd2;

    reg [2:0] state;
    reg [2:0] current_idx;
    reg [7:0] arr_reg [0:7];
    reg [2:0] len_reg;

    // Combinational signals
    wire [2:0] left_idx;
    wire [2:0] right_idx;
    wire has_left;
    wire has_right;
    wire left_ok;
    wire right_ok;

    assign left_idx = (current_idx << 1) + 1;
    assign right_idx = (current_idx << 1) + 2;

    assign has_left = (left_idx < len_reg);
    assign has_right = (right_idx < len_reg);

    assign left_ok = ~has_left || (arr_reg[current_idx] <= arr_reg[left_idx]);
    assign right_ok = ~has_right || (arr_reg[current_idx] <= arr_reg[right_idx]);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            is_heap <= 1'b1;
            done <= 1'b0;
            current_idx <= 3'd0;
            len_reg <= 3'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        arr_reg[0] <= arr_0;
                        arr_reg[1] <= arr_1;
                        arr_reg[2] <= arr_2;
                        arr_reg[3] <= arr_3;
                        arr_reg[4] <= arr_4;
                        arr_reg[5] <= arr_5;
                        arr_reg[6] <= arr_6;
                        arr_reg[7] <= arr_7;
                        len_reg <= len;
                        current_idx <= 3'd0;
                        is_heap <= 1'b1;

                        if (len >= 3'd1) begin
                            state <= CHECK_NODE;
                        end else begin
                            done <= 1'b1;
                            state <= COMPLETE;
                        end
                    end
                end

                CHECK_NODE: begin
                    if (!left_ok || !right_ok) begin
                        is_heap <= 1'b0;
                        state <= COMPLETE;
                    end else if (has_right) begin
                        current_idx <= left_idx;
                        state <= CHECK_NODE;
                    end else if (has_left) begin
                        state <= COMPLETE;
                    end else begin
                        state <= COMPLETE;
                    end
                end

                COMPLETE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module cone_lsa (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [15:0] radius,      // Q16.16 format
    input wire [15:0] height,      // Q16.16 format
    output reg [15:0] lsa,         // Q16.16 format
    output reg done
);

    // Parameters for Q16.16 format
    // PI approximation: 3.14159265 * 65536 = 205887
    parameter PI_FIXED = 205887;

    // State definitions
    parameter IDLE = 3'b000;
    parameter CALC_SQRT = 3'b001;
    parameter CALC_MULT = 3'b010;
    parameter CALC_FINAL = 3'b011;
    parameter DONE_STATE = 3'b100;

    reg [2:0] state;
    reg [2:0] next_state;

    // Internal registers for fixed-point calculations
    reg [31:0] r_sq;          // r^2 (Q32.0)
    reg [31:0] h_sq;          // h^2 (Q32.0)
    reg [31:0] sum_sq;        // r^2 + h^2 (Q32.0)
    reg [31:0] l_int;         // sqrt result (Q16.16)
    reg [47:0] r_mul_l;       // r * l (Q32.32)
    reg [47:0] pi_mul_r_l;    // pi * r * l (Q48.16)

    // CORDIC sqrt signals
    reg [31:0] sqrt_input;
    reg sqrt_start;
    wire sqrt_done;
    wire [15:0] sqrt_result;

    // Counter for multi-cycle operations
    reg [5:0] counter;

    // Instantiate sqrt module (simplified CORDIC)
    sqrt_cordic sqrt_inst (
        .clk(clk),
        .rst_n(rst_n),
        .start(sqrt_start),
        .number(sqrt_input),
        .result(sqrt_result),
        .done(sqrt_done)
    );

    // State transition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) next_state = CALC_SQRT;
            end
            CALC_SQRT: begin
                if (sqrt_done) next_state = CALC_MULT;
            end
            CALC_MULT: begin
                if (counter == 30) next_state = CALC_FINAL;
            end
            CALC_FINAL: begin
                if (counter == 50) next_state = DONE_STATE;
            end
            DONE_STATE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Control logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
            lsa <= 0;
            sqrt_start <= 0;
            counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Calculate r^2 and h^2 (shifted to integer)
                        r_sq <= radius * radius;  // Q32.0
                        h_sq <= height * height;  // Q32.0
                        sqrt_start <= 1;
                    end
                end

                CALC_SQRT: begin
                    sqrt_start <= 0;
                    if (sqrt_done) begin
                        l_int <= {sqrt_result, 16'h0};  // Convert to Q16.16
                        counter <= 0;
                    end
                end

                CALC_MULT: begin
                    counter <= counter + 1;
                    if (counter == 0) begin
                        sum_sq <= r_sq + h_sq;
                    end else if (counter == 1) begin
                        // Calculate r * l (Q16.16 * Q16.16 = Q32.32)
                        r_mul_l <= radius * l_int;
                    end
                end

                CALC_FINAL: begin
                    counter <= counter + 1;
                    if (counter == 0) begin
                        // Multiply by PI
                        // r_mul_l is Q32.32, PI is Q0.16
                        // Result needs to be Q16.16
                        pi_mul_r_l <= r_mul_l * PI_FIXED;
                    end else if (counter == 30) begin
                        // Shift right by 16 to get Q16.16
                        lsa <= pi_mul_r_l[47:16];
                    end
                end

                DONE_STATE: begin
                    done <= 1;
                end
            endcase
        end
    end

endmodule

// Simplified CORDIC Square Root Module
module sqrt_cordic (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [31:0] number,
    output reg [15:0] result,
    output reg done
);

    reg [31:0] guess;
    reg [31:0] x, y, z;
    reg [31:0] x_new, y_new;
    reg [5:0] iter;
    reg active;

    // Precomputed shift values for CORDIC
    wire [31:0] shift_val;
    assign shift_val = 32'h80000000 >> iter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
            active <= 0;
            result <= 0;
            iter <= 0;
        end else begin
            if (start && !active) begin
                active <= 1;
                iter <= 0;
                done <= 0;

                // Initialize for sqrt: x = number, y = 0, z = 0
                x <= number;
                y <= 0;
                z <= 0;
            end else if (active) begin
                if (iter < 16) begin
                    // CORDIC iteration
                    if (z < x) begin
                        x_new = x - shift_val;
                        y_new = y + shift_val;
                    end else begin
                        x_new = x + shift_val;
                        y_new = y - shift_val;
                    end
                    x <= x_new;
                    y <= y_new;
                    z <= z + 1;
                    iter <= iter + 1;
                end else begin
                    // Converged
                    result <= y[31:16];
                    done <= 1;
                    active <= 0;
                end
            end else begin
                done <= 0;
            end
        end
    end
endmodule

module replace_spaces(
  input clk,
  input rst_n,
  input start,
  input [7:0] char_array [0:15],  // 16-character input buffer
  input [4:0] len,                 // String length (0-16)
  output reg [7:0] result_array [0:15],  // Output buffer
  output reg done,
  output reg valid
);

  // Parameters
  parameter MAX_LEN = 16;
  parameter SPACE_ASCII = 8'd32;    // ' '
  parameter UNDERSCORE_ASCII = 8'd95; // '_'

  // State machine states
  parameter IDLE = 2'b00;
  parameter PROCESS = 2'b01;
  parameter FINISHED = 2'b10;

  // Registers
  reg [1:0] state;
  reg [4:0] index;  // Current character index
  reg [4:0] length; // Stored length

  integer i;

  // Output assignment for result_array (combinational for current index)
  always @(*) begin
    for (i = 0; i < MAX_LEN; i = i + 1) begin
      if (i < length && state == FINISHED) begin
        // Processing completed, output is ready
        // This is handled in sequential logic below
      end
    end
  end

  // Main state machine
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= IDLE;
      done <= 0;
      valid <= 0;
      index <= 0;
      length <= 0;
      // Clear output array
      for (i = 0; i < MAX_LEN; i = i + 1) begin
        result_array[i] <= 8'd0;
      end
    end else begin
      case (state)
        IDLE: begin
          done <= 0;
          valid <= 0;
          index <= 0;
          if (start && len > 0 && len <= MAX_LEN) begin
            length <= len;
            state <= PROCESS;
            // Initialize output with input
            for (i = 0; i < MAX_LEN; i = i + 1) begin
              if (i < len)
                result_array[i] <= char_array[i];
              else
                result_array[i] <= 8'd0;
            end
          end
        end

        PROCESS: begin
          if (index < length) begin
            // Process current character
            if (result_array[index] == SPACE_ASCII)
              result_array[index] <= UNDERSCORE_ASCII;
            else if (result_array[index] == UNDERSCORE_ASCII)
              result_array[index] <= SPACE_ASCII;
            // else keep as is

            index <= index + 1;
          end else begin
            // All characters processed
            state <= FINISHED;
            done <= 1;
            valid <= 1;
          end
        end

        FINISHED: begin
          done <= 0;
          // Wait for next start or reset
          if (!start) begin
            state <= IDLE;
          end
        end

        default: state <= IDLE;
      endcase
    end
  end

endmodule

module rgb_to_hsv(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] r_in,
    input wire [7:0] g_in,
    input wire [7:0] b_in,
    output reg [15:0] h_out,
    output reg [15:0] s_out,
    output reg [15:0] v_out,
    output reg done
);

// Fixed-point format: Q16.16 (16 integer bits, 16 fractional bits)
// Hue output: 0-360 in Q16.16
// Saturation: 0-100 in Q16.16
// Value: 0-100 in Q16.16

// State machine states
localparam IDLE = 4'd0;
localparam NORM = 4'd1;
localparam MX_MN = 4'd2;
localparam DF = 4'd3;
localparam HUE = 4'd4;
localparam SAT = 4'd5;
localparam VAL = 4'd6;
localparam DONE = 4'd7;

reg [3:0] state, next_state;

// Internal registers for intermediate calculations
reg [15:0] r_norm, g_norm, b_norm;  // Q16.16 normalized (0-1)
reg [15:0] mx, mn, df;              // Q16.16
reg [15:0] h_calc, s_calc, v_calc;  // Q16.16 results
reg [7:0] r_reg, g_reg, b_reg;      // Store inputs

// Multiplication result (for 16x16 -> 32-bit, then truncate)
reg [31:0] mult_result;

// Division state tracking
reg [1:0] div_step;

// Control signals
reg [15:0] divisor;
reg [15:0] dividend;
reg [15:0] quotient;
reg [3:0] div_counter;

// 60*100 = 6000 in Q16.16 = 6000 << 16 = 393216000
// But we'll compute as: (60 << 16) = 3932160
localparam SIXTY_FIXED = 32'd3932160;  // 60 in Q16.16
localparam SIXTY_FIXED_G = 32'd3932160; // 60 in Q16.16 for green case
localparam SIXTY_FIXED_B = 32'd3932160; // 60 in Q16.16 for blue case

// 100 in Q16.16 = 100 << 16 = 6553600
localparam HUNDRED_FIXED = 32'd6553600;

// 360 in Q16.16 = 360 << 16 = 23592960
localparam THREE_SIXTY_FIXED = 32'd23592960;

// 120 in Q16.16 = 120 << 16 = 7864320
localparam ONE_TWENTY_FIXED = 32'd7864320;

// 240 in Q16.16 = 240 << 16 = 15728640
localparam TWO_FOURTY_FIXED = 32'd15728640;

// Division by 255 (for normalization)
// 1/255 in Q16.16 ≈ 257 (actually 257.142, but we use 257 for approximation)
// More accurate: 65536/255 = 257 (rounded)
localparam INV_255 = 16'd257;

// Helper for max/min
reg [15:0] max_val, min_val;
reg mx_is_r, mx_is_g, mx_is_b;

// Combinational next state logic
always @(*) begin
    next_state = state;
    case (state)
        IDLE: if (start) next_state = NORM;
        NORM: next_state = MX_MN;
        MX_MN: next_state = DF;
        DF: next_state = HUE;
        HUE: if (div_counter == 4'd15) next_state = SAT;
        SAT: if (div_counter == 4'd15) next_state = VAL;
        VAL: next_state = DONE;
        DONE: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

// Sequential state update
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        done <= 0;
        h_out <= 0;
        s_out <= 0;
        v_out <= 0;
        div_counter <= 0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: begin
                done <= 0;
                div_counter <= 0;
                if (start) begin
                    r_reg <= r_in;
                    g_reg <= g_in;
                    b_reg <= b_in;
                end
            end

            NORM: begin
                // Normalize to 0-1 (divide by 255)
                // Use approximation: multiply by 257 then shift right by 8
                r_norm <= (r_reg * INV_255) >> 8;
                g_norm <= (g_reg * INV_255) >> 8;
                b_norm <= (b_reg * INV_255) >> 8;
            end

            MX_MN: begin
                // Find max and min
                if (r_norm >= g_norm && r_norm >= b_norm) begin
                    mx <= r_norm;
                    mx_is_r <= 1; mx_is_g <= 0; mx_is_b <= 0;
                end else if (g_norm >= r_norm && g_norm >= b_norm) begin
                    mx <= g_norm;
                    mx_is_r <= 0; mx_is_g <= 1; mx_is_b <= 0;
                end else begin
                    mx <= b_norm;
                    mx_is_r <= 0; mx_is_g <= 0; mx_is_b <= 1;
                end

                if (r_norm <= g_norm && r_norm <= b_norm) begin
                    mn <= r_norm;
                end else if (g_norm <= r_norm && g_norm <= b_norm) begin
                    mn <= g_norm;
                end else begin
                    mn <= b_norm;
                end
            end

            DF: begin
                df <= mx - mn;
            end

            HUE: begin
                if (div_counter == 0) begin
                    // Check mx == mn
                    if (mx == mn) begin
                        h_calc <= 0;
                        div_counter <= 15; // Skip to next state
                    end else if (mx_is_r) begin
                        // h = (60 * ((g-m)/df) + 360) % 360
                        // First compute (g-m)/df
                        if (df != 0) begin
                            dividend <= (g_norm > mn) ? (g_norm - mn) : 0;
                            divisor <= df;
                            quotient <= 0;
                            div_counter <= 1;
                        end else begin
                            h_calc <= 0;
                            div_counter <= 15;
                        end
                    end else if (mx_is_g) begin
                        // h = (60 * ((b-m)/df) + 120) % 360
                        if (df != 0) begin
                            dividend <= (b_norm > mn) ? (b_norm - mn) : 0;
                            divisor <= df;
                            quotient <= 0;
                            div_counter <= 1;
                        end else begin
                            h_calc <= 0;
                            div_counter <= 15;
                        end
                    end else begin // mx_is_b
                        // h = (60 * ((m-m)/df) + 240) % 360
                        if (df != 0) begin
                            dividend <= (r_norm > mn) ? (r_norm - mn) : 0;
                            divisor <= df;
                            quotient <= 0;
                            div_counter <= 1;
                        end else begin
                            h_calc <= 0;
                            div_counter <= 15;
                        end
                    end
                end else if (div_counter < 16) begin
                    // Long division: Q16.16 ÷ Q16.16 = Q16.16 result
                    if ({quotient, dividend[15:0]} >= {16'd0, divisor}) begin
                        quotient <= quotient + 1;
                        dividend <= {dividend[15:0], 1'b0} - {1'b0, divisor};
                    end else begin
                        dividend <= {dividend[15:0], 1'b0};
                    end
                    div_counter <= div_counter + 1;

                    if (div_counter == 15) begin
                        // Division complete, now multiply by 60 and add offset
                        if (mx_is_r) begin
                            mult_result <= SIXTY_FIXED * quotient;
                            // Will add 360 and modulo in next state transition
                        end else if (mx_is_g) begin
                            mult_result <= SIXTY_FIXED * quotient;
                        end else begin
                            mult_result <= SIXTY_FIXED * quotient;
                        end
                    end
                end
            end

            SAT: begin
                if (div_counter == 0) begin
                    // s = (df/mx)*100
                    if (mx != 0 && df != 0) begin
                        dividend <= df;
                        divisor <= mx;
                        quotient <= 0;
                        div_counter <= 1;
                    end else begin
                        s_calc <= 0;
                        div_counter <= 15;
                    end
                end else if (div_counter < 16) begin
                    // Long division
                    if ({quotient, dividend[15:0]} >= {16'd0, divisor}) begin
                        quotient <= quotient + 1;
                        dividend <= {dividend[15:0], 1'b0} - {1'b0, divisor};
                    end else begin
                        dividend <= {dividend[15:0], 1'b0};
                    end
                    div_counter <= div_counter + 1;

                    if (div_counter == 15) begin
                        // Multiply by 100
                        mult_result <= HUNDRED_FIXED * quotient;
                    end
                end
            end

            VAL: begin
                // v = mx*100
                v_out <= (mx * 100) >> 16;

                // Handle saturation result
                if (div_counter == 15 && mx != 0 && df != 0) begin
                    s_out <= mult_result[31:16];
                end else begin
                    s_out <= 0;
                end

                // Handle hue result with modulo 360
                if (mx != mn) begin
                    if (mx_is_r) begin
                        // (60 * ((g-m)/df) + 360) % 360
                        // mult_result = 60 * ((g-m)/df)
                        // Add 360 in Q16.16
                        mult_result <= mult_result + THREE_SIXTY_FIXED;
                    end else if (mx_is_g) begin
                        // (60 * ((b-m)/df) + 120) % 360
                        mult_result <= mult_result + ONE_TWENTY_FIXED;
                    end else begin
                        // (60 * ((r-m)/df) + 240) % 360
                        mult_result <= mult_result + TWO_FOURTY_FIXED;
                    end
                end
            end

            DONE: begin
                // Final modulo 360 for hue
                if (mx != mn) begin
                    if (mult_result >= THREE_SIXTY_FIXED) begin
                        h_out <= mult_result - THREE_SIXTY_FIXED;
                    end else begin
                        h_out <= mult_result[31:16];
                    end
                end else begin
                    h_out <= 0;
                end
                done <= 1;
            end
        endcase
    end
end

endmodule

module min_k_records (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input arrays: 4 records, each has a name and a score
    // Names are encoded as 8-bit ASCII values (single character for simplicity)
    // Scores are 8-bit unsigned integers
    input wire [7:0] name_0,
    input wire [7:0] name_1,
    input wire [7:0] name_2,
    input wire [7:0] name_3,
    input wire [7:0] score_0,
    input wire [7:0] score_1,
    input wire [7:0] score_2,
    input wire [7:0] score_3,
    input wire [1:0] k,  // K value: 1, 2, or 3 (since max 4 records)

    // Output: Top K records in score-sorted order
    // Outputs K pairs of (name, score)
    output reg [7:0] out_name_0,
    output reg [7:0] out_score_0,
    output reg [7:0] out_name_1,
    output reg [7:0] out_score_1,
    output reg [7:0] out_name_2,
    output reg [7:0] out_score_2,

    output reg done
);

    parameter NUM_RECORDS = 4;
    parameter MAX_K = 3;

    // Internal registers for sorting (4 elements)
    reg [7:0] sort_name [0:3];
    reg [7:0] sort_score [0:3];

    // State machine
    reg [2:0] state;
    reg [2:0] sort_counter;  // For bubble sort passes
    reg [1:0] pair_counter;   // For comparing adjacent pairs

    // State definitions
    localparam IDLE = 3'b000;
    localparam LOAD = 3'b001;
    localparam SORT_PASS = 3'b010;
    localparam SORT_COMPARE = 3'b011;
    localparam OUTPUT = 3'b100;
    localparam DONE_STATE = 3'b101;

    // Temporary swap registers
    reg [7:0] temp_name;
    reg [7:0] temp_score;
    reg swap_needed;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset
            state <= IDLE;
            done <= 0;
            for (i = 0; i < NUM_RECORDS; i = i + 1) begin
                sort_name[i] <= 8'h00;
                sort_score[i] <= 8'h00;
            end
            out_name_0 <= 8'h00;
            out_score_0 <= 8'h00;
            out_name_1 <= 8'h00;
            out_score_1 <= 8'h00;
            out_name_2 <= 8'h00;
            out_score_2 <= 8'h00;
            sort_counter <= 3'b0;
            pair_counter <= 2'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= LOAD;
                    end
                end

                LOAD: begin
                    // Load input data into internal sorting registers
                    sort_name[0] <= name_0;
                    sort_score[0] <= score_0;
                    sort_name[1] <= name_1;
                    sort_score[1] <= score_1;
                    sort_name[2] <= name_2;
                    sort_score[2] <= score_2;
                    sort_name[3] <= name_3;
                    sort_score[3] <= score_3;
                    sort_counter <= 3'd3;  // N-1 passes for bubble sort
                    pair_counter <= 2'b0;
                    state <= SORT_PASS;
                end

                SORT_PASS: begin
                    if (sort_counter > 0) begin
                        pair_counter <= 2'b0;
                        state <= SORT_COMPARE;
                    end else begin
                        // Sorting complete, proceed to output
                        state <= OUTPUT;
                    end
                end

                SORT_COMPARE: begin
                    // Compare adjacent pairs
                    if (pair_counter < 3) begin
                        // Compare sort_score[pair_counter] and sort_score[pair_counter+1]
                        if (sort_score[pair_counter] > sort_score[pair_counter + 1]) begin
                            // Swap needed
                            temp_name <= sort_name[pair_counter];
                            temp_score <= sort_score[pair_counter];
                            sort_name[pair_counter] <= sort_name[pair_counter + 1];
                            sort_score[pair_counter] <= sort_score[pair_counter + 1];
                            sort_name[pair_counter + 1] <= temp_name;
                            sort_score[pair_counter + 1] <= temp_score;
                        end
                        pair_counter <= pair_counter + 1;
                        state <= SORT_COMPARE;
                    end else begin
                        // Finished this pass
                        sort_counter <= sort_counter - 1;
                        state <= SORT_PASS;
                    end
                end

                OUTPUT: begin
                    // Output first K records (sorted ascending by score)
                    // K is 1-indexed in input, convert to 0-indexed count
                    out_name_0 <= sort_name[0];
                    out_score_0 <= sort_score[0];

                    // Only output remaining if K >= 2
                    if (k >= 2'd2) begin
                        out_name_1 <= sort_name[1];
                        out_score_1 <= sort_score[1];
                    end else begin
                        out_name_1 <= 8'h00;
                        out_score_1 <= 8'h00;
                    end

                    // Only output third if K >= 3
                    if (k >= 2'd3) begin
                        out_name_2 <= sort_name[2];
                        out_score_2 <= sort_score[2];
                    end else begin
                        out_name_2 <= 8'h00;
                        out_score_2 <= 8'h00;
                    end

                    state <= DONE_STATE;
                end

                DONE_STATE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module extract_index_list (
    // Inputs
    input wire clk,           // Clock signal
    input wire rst_n,         // Active-low reset
    input wire start,         // Start pulse (assert for 1 cycle)

    // Input arrays - 8 elements each, 8 bits wide
    input wire [7:0] l1_0, l1_1, l1_2, l1_3, l1_4, l1_5, l1_6, l1_7,
    input wire [7:0] l2_0, l2_1, l2_2, l2_3, l2_4, l2_5, l2_6, l2_7,
    input wire [7:0] l3_0, l3_1, l3_2, l3_3, l3_4, l3_5, l3_6, l3_7,

    // Outputs
    output reg [7:0] result_0, result_1, result_2, result_3, result_4, result_5, result_6, result_7,
    output reg [3:0] result_count,  // Number of common elements found
    output reg done                 // Asserted high when computation complete
);

    // Internal state machine
    reg [2:0] state;
    reg [3:0] idx;

    // State definitions
    localparam IDLE = 3'd0;
    localparam COMPARE = 3'd1;
    localparam OUTPUT = 3'd2;
    localparam FINISHED = 3'd3;

    // Temporary storage during comparison
    reg [7:0] temp_result [0:7];
    reg [3:0] temp_count;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset all signals
            state <= IDLE;
            done <= 1'b0;
            result_count <= 4'd0;
            result_0 <= 8'd0; result_1 <= 8'd0; result_2 <= 8'd0; result_3 <= 8'd0;
            result_4 <= 8'd0; result_5 <= 8'd0; result_6 <= 8'd0; result_7 <= 8'd0;
            idx <= 4'd0;
            temp_count <= 4'd0;
            for (i = 0; i < 8; i = i + 1) begin
                temp_result[i] <= 8'd0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPARE;
                        idx <= 4'd0;
                        temp_count <= 4'd0;
                    end
                end

                COMPARE: begin
                    // Compare current index across all three lists
                    case (idx)
                        4'd0: begin
                            if ((l1_0 == l2_0) && (l2_0 == l3_0)) begin
                                temp_result[temp_count] <= l1_0;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd1: begin
                            if ((l1_1 == l2_1) && (l2_1 == l3_1)) begin
                                temp_result[temp_count] <= l1_1;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd2: begin
                            if ((l1_2 == l2_2) && (l2_2 == l3_2)) begin
                                temp_result[temp_count] <= l1_2;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd3: begin
                            if ((l1_3 == l2_3) && (l2_3 == l3_3)) begin
                                temp_result[temp_count] <= l1_3;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd4: begin
                            if ((l1_4 == l2_4) && (l2_4 == l3_4)) begin
                                temp_result[temp_count] <= l1_4;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd5: begin
                            if ((l1_5 == l2_5) && (l2_5 == l3_5)) begin
                                temp_result[temp_count] <= l1_5;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd6: begin
                            if ((l1_6 == l2_6) && (l2_6 == l3_6)) begin
                                temp_result[temp_count] <= l1_6;
                                temp_count <= temp_count + 1'b1;
                            end
                        end
                        4'd7: begin
                            if ((l1_7 == l2_7) && (l2_7 == l3_7)) begin
                                temp_result[temp_count] <= l1_7;
                                temp_count <= temp_count + 1'b1;
                            end
                            state <= OUTPUT;
                            idx <= 4'd0;
                            result_count <= temp_count + 1'b1; // Final count
                            return;
                        end
                    endcase
                    idx <= idx + 1'b1;
                end

                OUTPUT: begin
                    // Transfer temp results to output ports
                    result_0 <= temp_result[0];
                    result_1 <= temp_result[1];
                    result_2 <= temp_result[2];
                    result_3 <= temp_result[3];
                    result_4 <= temp_result[4];
                    result_5 <= temp_result[5];
                    result_6 <= temp_result[6];
                    result_7 <= temp_result[7];
                    done <= 1'b1;
                    state <= FINISHED;
                end

                FINISHED: begin
                    done <= 1'b0;
                    if (!start) begin
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module three_equal_counter (
    input wire [7:0] x,    // First number (signed)
    input wire [7:0] y,    // Second number (signed)
    input wire [7:0] z,    // Third number (signed)
    output reg [2:0] result // 0, 2, or 3
);

    // Combinational logic to count equal numbers
    // Returns:
    // - 0 if all three are different
    // - 2 if exactly two are equal
    // - 3 if all three are equal

    wire eq_xy;  // x == y
    wire eq_xz;  // x == z
    wire eq_yz;  // y == z

    assign eq_xy = (x == y);
    assign eq_xz = (x == z);
    assign eq_yz = (y == z);

    always @(*) begin
        // Count based on equalities
        // If all three equal: eq_xy, eq_xz, eq_yz are all 1
        // If two equal: exactly one of them is 0, two are 1
        // If all different: all three are 0

        if (eq_xy && eq_xz && eq_yz) begin
            result = 3'd3;
        end else if (eq_xy || eq_xz || eq_yz) begin
            result = 3'd2;
        end else begin
            result = 3'd0;
        end
    end

endmodule

module pack_consecutive_duplicates (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr [0:15],  // 16-element input array, 8-bit elements
    input wire [4:0] input_len,    // Number of valid elements (1-16)
    output reg [7:0] out_arr [0:15],  // Flattened output array
    output reg [4:0] out_len,      // Number of output groups
    output reg done,
    output reg error               // Error: run too long or too many groups
);

    // Internal state machine
    typedef enum logic [2:0] {
        IDLE,
        READ_INPUT,
        PROCESS_RUN,
        WRITE_OUTPUT,
        FINISH
    } state_t;

    state_t current_state, next_state;

    // Run tracking registers
    reg [7:0] current_value;
    reg [3:0] run_length;      // Max run length = 8
    reg [4:0] input_index;     // Current input position
    reg [4:0] output_index;    // Current output position (group count)
    reg [3:0] group_index;     // Index within current group

    // Output buffer for current group being formed
    reg [7:0] group_buffer [0:7];

    // State transition and output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            done <= 0;
            error <= 0;
            input_index <= 0;
            output_index <= 0;
            run_length <= 0;
            out_len <= 0;
        end else begin
            case (current_state)
                IDLE: begin
                    done <= 0;
                    error <= 0;
                    input_index <= 0;
                    output_index <= 0;
                    run_length <= 0;
                    out_len <= 0;
                    if (start && input_len > 0 && input_len <= 16) begin
                        current_state <= READ_INPUT;
                    end else if (start) begin
                        // Invalid input length
                        current_state <= FINISH;
                        error <= 1;
                    end
                end

                READ_INPUT: begin
                    if (input_index == 0) begin
                        // First element
                        current_value <= arr[0];
                        run_length <= 1;
                        group_buffer[0] <= arr[0];
                        input_index <= 1;
                    end else if (input_index < input_len) begin
                        // Compare with previous
                        if (arr[input_index] == current_value && run_length < 8) begin
                            // Continue current run
                            run_length <= run_length + 1;
                            group_buffer[run_length] <= arr[input_index];
                            input_index <= input_index + 1;
                        end else if (arr[input_index] != current_value) begin
                            // New run detected, process current one
                            current_state <= WRITE_OUTPUT;
                        end else begin
                            // Run too long
                            current_state <= FINISH;
                            error <= 1;
                        end
                    end else begin
                        // End of input, process last run
                        current_state <= WRITE_OUTPUT;
                    end
                end

                WRITE_OUTPUT: begin
                    // Write current group to output array
                    if (output_index < 16 && output_index < input_len) begin
                        // Store group length first, then elements
                        // Actually, we need to flatten: store all elements sequentially
                        // and keep track of group boundaries
                        // Let's use a different approach: output_index points to next free slot
                        // We write run_length, then elements

                        // Check if we have space for this group
                        if (output_index + run_length + 1 > 16) begin
                            error <= 1;
                            current_state <= FINISH;
                        end else begin
                            // We need to store: [run_length, values...]
                            // But the problem asks for list of lists in Python
                            // For hardware, let's output concatenated: out_arr contains all elements
                            // and out_len contains number of groups
                            // We also need to track where each group starts...
                            // Simplified: output flattened with delimiter

                            // Better approach: Let's output as: [len1, data1..., len2, data2..., ...]
                            // No, let's stick to the original intent: just output the runs
                            // in sequence, and the testbench will repackage them

                            // Actually, the cleanest hardware approach:
                            // Store the result as: group 0's elements, then group 1's, etc.
                            // And output_index = total elements written
                            // out_len = number of groups
                            // We need another array for group start positions (too complex)

                            // COMPROMISE: Output format will be:
                            // out_arr[0..7] = group 0
                            // out_arr[8..15] = group 1, etc. (fixed width groups)
                            // No, variable width. Let's use a single output array
                            // and testbench handles the grouping based on run lengths

                            // FINAL DECISION: Store sequentially, with run length prefix
                            // Each group: [length, elements...]
                            // This makes it easy for testbench to reconstruct

                            out_arr[output_index] <= run_length;
                            output_index <= output_index + 1;

                            for (integer i = 0; i < 8; i++) begin
                                if (i < run_length) begin
                                    out_arr[output_index + 1 + i] <= group_buffer[i];
                                end
                            end

                            output_index <= output_index + 1 + run_length;
                            out_len <= out_len + 1;  // Increment group count

                            // Move to next state
                            if (input_index < input_len) begin
                                current_state <= READ_INPUT;
                                // Setup for next run
                                current_value <= arr[input_index];
                                run_length <= 1;
                                group_buffer[0] <= arr[input_index];
                                input_index <= input_index + 1;
                            end else begin
                                current_state <= FINISH;
                            end
                        end
                    end else begin
                        error <= 1;
                        current_state <= FINISH;
                    end
                end

                FINISH: begin
                    done <= 1;
                    if (start) begin
                        current_state <= IDLE;
                    end
                end

                default: current_state <= IDLE;
            endcase
        end
    end
endmodule

