module toggle_middle_bits (
    input      [7:0] n,    // 8-bit input number
    output     [7:0] result // 8-bit output with middle bits toggled
);

// Helper to create mask of all 1s from LSB up to highest set bit
// Original logic:
// m |= m >> 1
// m |= m >> 2
// m |= m >> 4
// m |= m >> 8
// m |= m >> 16
// set = (m >> 1) ^ 1

wire [7:0] step1;
assign step1 = n | (n >> 1);

wire [7:0] step2;
assign step2 = step1 | (step1 >> 2);

wire [7:0] step3;
assign step3 = step2 | (step2 >> 4);

// No need for >> 8 and >> 16 for 8-bit input

wire [7:0] set;
assign set = (step3 >> 1) ^ 8'h01;

// Special case: if input is 1, output is 1
// Otherwise: result = n ^ set
wire [7:0] mask;
assign mask = (n == 8'h01) ? 8'h00 : set;

assign result = n ^ mask;

endmodule

module is_product_even(
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [3:0] len,          // Number of valid elements (1-8)
    output result             // 1 = product is even, 0 = product is odd
);

    // Product is even if ANY number is even (has LSB=0)
    // Product is odd only if ALL numbers are odd

    wire [7:0] even_flags;

    // Check each number's LSB (0 = even, 1 = odd)
    assign even_flags[0] = (len >= 1) ? ~arr_0[0] : 1'b0;
    assign even_flags[1] = (len >= 2) ? ~arr_1[0] : 1'b0;
    assign even_flags[2] = (len >= 3) ? ~arr_2[0] : 1'b0;
    assign even_flags[3] = (len >= 4) ? ~arr_3[0] : 1'b0;
    assign even_flags[4] = (len >= 5) ? ~arr_4[0] : 1'b0;
    assign even_flags[5] = (len >= 6) ? ~arr_5[0] : 1'b0;
    assign even_flags[6] = (len >= 7) ? ~arr_6[0] : 1'b0;
    assign even_flags[7] = (len >= 8) ? ~arr_7[0] : 1'b0;

    // Result is 1 if any even_flag is 1
    assign result = |even_flags;

