module cumulative_sum (
    input wire clk,
    input wire rst_n,
    input wire start,

    // Input: 3 tuples, each up to 3 elements
    // tuple_0: 3 elements, tuple_1: 3 elements, tuple_2: 3 elements
    input wire [7:0] tuple_0_0, tuple_0_1, tuple_0_2,
    input wire [7:0] tuple_1_0, tuple_1_1, tuple_1_2,
    input wire [7:0] tuple_2_0, tuple_2_1, tuple_2_2,

    // Valid element counts per tuple (1-3)
    input wire [1:0] len_0, len_1, len_2,

    output reg [15:0] result,
    output reg done
);

    // State machine
    reg [2:0] state;
    reg [1:0] tuple_idx;
    reg [1:0] elem_idx;
    reg [15:0] accumulator;

    // State definitions
    localparam IDLE = 3'b000;
    localparam SUM_TUPLE0 = 3'b001;
    localparam SUM_TUPLE1 = 3'b010;
    localparam SUM_TUPLE2 = 3'b011;
    localparam DONE = 3'b100;

    // Access current element based on tuple and element index
    wire [7:0] current_element;
    assign current_element = (
        (tuple_idx == 2'd0) ? (
            (elem_idx == 2'd0) ? tuple_0_0 :
            (elem_idx == 2'd1) ? tuple_0_1 :
            tuple_0_2
        ) :
        (tuple_idx == 2'd1) ? (
            (elem_idx == 2'd0) ? tuple_1_0 :
            (elem_idx == 2'd1) ? tuple_1_1 :
            tuple_1_2
        ) :
        (
            (elem_idx == 2'd0) ? tuple_2_0 :
            (elem_idx == 2'd1) ? tuple_2_1 :
            tuple_2_2
        )
    );

    // Get valid length for current tuple
    wire [1:0] current_len;
    assign current_len = (
        (tuple_idx == 2'd0) ? len_0 :
        (tuple_idx == 2'd1) ? len_1 :
        len_2
    );

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 16'd0;
            done <= 1'b0;
            accumulator <= 16'd0;
            tuple_idx <= 2'd0;
            elem_idx <= 2'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= SUM_TUPLE0;
                        accumulator <= 16'd0;
                        tuple_idx <= 2'd0;
                        elem_idx <= 2'd0;
                    end
                end

                SUM_TUPLE0, SUM_TUPLE1, SUM_TUPLE2: begin
                    if (elem_idx < current_len) begin
                        // Add current element to accumulator
                        accumulator <= accumulator + current_element;
                        elem_idx <= elem_idx + 1'b1;
                    end else begin
                        // Move to next tuple or finish
                        elem_idx <= 2'd0;
                        tuple_idx <= tuple_idx + 1'b1;

                        if (state == SUM_TUPLE2) begin
                            result <= accumulator;
                            state <= DONE;
                        end else if (state == SUM_TUPLE1) begin
                            state <= SUM_TUPLE2;
                        end else begin
                            state <= SUM_TUPLE1;
                        end
                    end
                end

                DONE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module is_Sub_Array(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] A_0, A_1, A_2, A_3,  // Main array (max 4 elements)
    input wire [7:0] B_0, B_1, B_2, B_3,  // Subarray (max 4 elements)
    input wire [2:0] len_A,               // Valid length of A (1-4)
    input wire [2:0] len_B,               // Valid length of B (1-4)
    output reg result,
    output reg done
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam SEARCH = 3'b001;
    localparam CHECK_MATCH = 3'b010;
    localparam BACKTRACK = 3'b011;
    localparam FINISHED = 3'b100;

    // Internal registers
    reg [2:0] state;
    reg [2:0] i;  // Index for A
    reg [2:0] j;  // Index for B
    reg [2:0] start_idx;  // Starting position in A for current match attempt

    // Memory for arrays (using registers)
    reg [7:0] arr_A [0:3];
    reg [7:0] arr_B [0:3];
    reg [2:0] valid_len_A;
    reg [2:0] valid_len_B;

    // Next state logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 0;
            done <= 0;
            i <= 0;
            j <= 0;
            start_idx <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Load arrays
                        arr_A[0] <= A_0;
                        arr_A[1] <= A_1;
                        arr_A[2] <= A_2;
                        arr_A[3] <= A_3;
                        arr_B[0] <= B_0;
                        arr_B[1] <= B_1;
                        arr_B[2] <= B_2;
                        arr_B[3] <= B_3;
                        valid_len_A <= len_A;
                        valid_len_B <= len_B;

                        if (len_B == 0 || len_B > len_A) begin
                            result <= 0;
                            state <= FINISHED;
                        end else begin
                            i <= 0;
                            j <= 0;
                            start_idx <= 0;
                            state <= SEARCH;
                        end
                    end
                end

                SEARCH: begin
                    // Check if we need to start a new comparison
                    if (j >= valid_len_B) begin
                        // Match found
                        result <= 1;
                        state <= FINISHED;
                    end else if (i >= valid_len_A) begin
                        // Reached end of A without full match
                        result <= 0;
                        state <= FINISHED;
                    end else begin
                        // Compare elements
                        state <= CHECK_MATCH;
                    end
                end

                CHECK_MATCH: begin
                    if (arr_A[i] == arr_B[j]) begin
                        i <= i + 1;
                        j <= j + 1;
                        state <= SEARCH;
                    end else begin
                        // Mismatch - backtrack
                        if (start_idx + 1 >= valid_len_A) begin
                            // No more positions to try
                            result <= 0;
                            state <= FINISHED;
                        end else begin
                            start_idx <= start_idx + 1;
                            i <= start_idx + 1;
                            j <= 0;
                            state <= SEARCH;
                        end
                    end
                end

                FINISHED: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module max_sublist_length (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] data_in,        // Current element being processed
    input wire valid_in,             // Indicates current element is valid
    input wire end_of_sublist,       // Assert to mark end of current sublist
    input wire end_of_input,         // Assert to mark end of all input
    output reg [7:0] max_length,     // Result: maximum sublist length
    output reg done                  // Computation complete
);

    // Parameters for array dimensions
    parameter MAX_SUBLISTS = 8;
    parameter MAX_SUBLEN = 8;

    // State machine states
    parameter IDLE = 3'b000;
    parameter PROCESS = 3'b001;
    parameter UPDATE_MAX = 3'b010;
    parameter COMPLETE = 3'b011;

    // Internal registers
    reg [2:0] state, next_state;
    reg [7:0] current_length;      // Length of current sublist
    reg [7:0] max_len_reg;         // Maximum length found so far
    reg [2:0] sublist_count;       // Number of sublists processed
    reg [2:0] element_count;       // Elements in current sublist

    // State transition logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (start)
                    next_state = PROCESS;
                else
                    next_state = IDLE;
            end

            PROCESS: begin
                if (valid_in && !end_of_sublist && !end_of_input)
                    next_state = PROCESS;  // Still counting elements
                else if (end_of_sublist || end_of_input)
                    next_state = UPDATE_MAX;  // Sublist ended, update max
                else
                    next_state = PROCESS;
            end

            UPDATE_MAX: begin
                if (end_of_input || sublist_count >= MAX_SUBLISTS)
                    next_state = COMPLETE;
                else
                    next_state = PROCESS;
            end

            COMPLETE: begin
                next_state = COMPLETE;  // Stay done
            end

            default: next_state = IDLE;
        endcase
    end

    // Output and datapath logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_length <= 8'd0;
            max_len_reg <= 8'd0;
            sublist_count <= 3'd0;
            element_count <= 3'd0;
            done <= 1'b0;
            max_length <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    current_length <= 8'd0;
                    max_len_reg <= 8'd0;
                    sublist_count <= 3'd0;
                    element_count <= 3'd0;
                    done <= 1'b0;
                end

                PROCESS: begin
                    if (valid_in && !end_of_sublist) begin
                        // Counting elements in current sublist
                        if (element_count < MAX_SUBLEN - 1) begin
                            element_count <= element_count + 1'b1;
                        end
                    end

                    if (end_of_sublist) begin
                        // Current sublist ended
                        current_length <= element_count + 1'b1;
                        element_count <= 3'd0;
                        sublist_count <= sublist_count + 1'b1;
                    end else if (end_of_input) begin
                        // Final element
                        current_length <= element_count + 1'b1;
                    end
                end

                UPDATE_MAX: begin
                    // Update maximum length
                    if (current_length > max_len_reg) begin
                        max_len_reg <= current_length;
                    end
                    current_length <= 8'd0;
                end

                COMPLETE: begin
                    max_length <= max_len_reg;
                    done <= 1'b1;
                end
            endcase
        end
    end

endmodule

