module armstrong_check (
    input clk,
    input rst_n,
    input start,
    input [7:0] number,  // Input number (0-255, checking 3-digit max)
    output reg result,     // 1=Armstrong, 0=Not Armstrong
    output reg done        // Asserted when computation complete
);

// States for FSM
localparam IDLE = 2'b00;
localparam COUNT_DIGITS = 2'b01;
localparam CALCULATE_SUM = 2'b10;
localparam COMPARE = 2'b11;

reg [1:0] state, next_state;
reg [7:0] temp_num;
reg [7:0] sum;
reg [2:0] digit_count;  // Max 3 digits for 8-bit numbers
reg [2:0] digit;
reg [7:0] power_result;
reg [2:0] power_counter;
reg calculating_power;

// State register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        result <= 0;
        done <= 0;
    end else begin
        state <= next_state;
    end
end

// Next state logic
always @(*) begin
    case (state)
        IDLE: begin
            if (start)
                next_state = COUNT_DIGITS;
            else
                next_state = IDLE;
        end
        COUNT_DIGITS: begin
            if (temp_num == 0)
                next_state = CALCULATE_SUM;
            else
                next_state = COUNT_DIGITS;
        end
        CALCULATE_SUM: begin
            if (temp_num == 0)
                next_state = COMPARE;
            else if (calculating_power && power_counter >= digit_count)
                next_state = CALCULATE_SUM;
            else
                next_state = CALCULATE_SUM;
        end
        COMPARE: begin
            next_state = IDLE;
        end
        default: next_state = IDLE;
    endcase
end

// Output logic and datapath
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        temp_num <= 0;
        sum <= 0;
        digit_count <= 0;
        digit <= 0;
        power_result <= 1;
        power_counter <= 0;
        calculating_power <= 0;
        result <= 0;
        done <= 0;
    end else begin
        done <= 0;  // Default: done low

        case (state)
            IDLE: begin
                if (start) begin
                    temp_num <= number;
                    sum <= 0;
                    digit_count <= 0;
                    digit <= 0;
                    power_result <= 1;
                    power_counter <= 0;
                    calculating_power <= 0;
                end
            end

            COUNT_DIGITS: begin
                if (temp_num > 0) begin
                    temp_num <= temp_num / 10;  // Integer division
                    digit_count <= digit_count + 1;
                end
            end

            CALCULATE_SUM: begin
                if (temp_num > 0 && !calculating_power) begin
                    // Extract next digit
                    digit <= temp_num % 10;
                    temp_num <= temp_num / 10;
                    calculating_power <= 1;
                    power_result <= 1;
                    power_counter <= 0;
                end else if (calculating_power) begin
                    // Calculate digit ^ digit_count
                    if (power_counter < digit_count) begin
                        power_result <= power_result * digit;
                        power_counter <= power_counter + 1;
                    end else begin
                        // Power calculation complete, add to sum
                        sum <= sum + power_result;
                        calculating_power <= 0;
                        power_counter <= 0;
                    end
                end
            end

            COMPARE: begin
                // Check if original number equals sum
                if (number == sum)
                    result <= 1;
                else
                    result <= 0;
                done <= 1;
            end
        endcase
    end
end

endmodule

module big_diff(
    // Individual 8-bit input ports for array elements
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,

    // Number of valid elements (1-8)
    input [3:0] len,

    // 16-bit result output
    output reg [15:0] result
);

    // Internal storage for input array
    reg [7:0] arr [0:7];

    // Max and min tracking variables
    reg [7:0] max_val;
    reg [7:0] min_val;

    integer i;

    always @(*) begin
        // Load inputs into internal array
        arr[0] = arr_0;
        arr[1] = arr_1;
        arr[2] = arr_2;
        arr[3] = arr_3;
        arr[4] = arr_4;
        arr[5] = arr_5;
        arr[6] = arr_6;
        arr[7] = arr_7;

        // Handle edge case: len = 0
        if (len == 0) begin
            max_val = 8'h00;
            min_val = 8'h00;
        end else begin
            // Initialize max and min with first element
            max_val = arr[0];
            min_val = arr[0];

            // Iterate through remaining valid elements
            for (i = 1; i < 8 && i < len; i = i + 1) begin
                if (arr[i] > max_val)
                    max_val = arr[i];
                if (arr[i] < min_val)
                    min_val = arr[i];
            end
        end

        // Compute difference (max - min)
        result = max_val - min_val;
    end

