module char_splitter(
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] char_in,  // Single character input per cycle
    input wire [3:0] str_len,   // Length of string (1-16 characters)
    output reg [7:0] out_chars [0:15],  // Output array of characters
    output reg done,
    output reg valid
);

// Module splits a string into individual characters
// Operation: On start, reads characters sequentially over 16 cycles
// and stores them in output array. Valid entries marked by 'valid' bit.

// Internal state
reg [3:0] count;
reg processing;

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset: clear all outputs and state
        done <= 1'b0;
        valid <= 1'b0;
        count <= 4'd0;
        processing <= 1'b0;
        for (i = 0; i < 16; i = i + 1) begin
            out_chars[i] <= 8'h00;
        end
    end else begin
        if (start && !processing) begin
            // Start new computation
            count <= 4'd0;
            processing <= 1'b1;
            done <= 1'b0;
            valid <= 1'b0;
        end else if (processing) begin
            // Store current character
            if (count < str_len && count < 16) begin
                out_chars[count] <= char_in;
            end

            // Increment counter
            count <= count + 1;

            // Check completion
            if (count >= str_len - 1 || count >= 15) begin
                processing <= 1'b0;
                done <= 1'b1;
                valid <= 1'b1;
            end
        end else begin
            done <= 1'b0;
        end
    end
end

endmodule

module find_diff_first_even_odd (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [2:0] len,  // Number of valid elements (1-8)
    output reg [15:0] result,
    output reg done
);

    // Internal state definitions
    reg [2:0] index;           // Current array index being processed
    reg [7:0] first_even;      // Store first even number found
    reg [7:0] first_odd;       // Store first odd number found
    reg even_found;            // Flag: first even found
    reg odd_found;             // Flag: first odd found
    reg processing;            // Processing state flag

    // Input selection based on index
    wire [7:0] current_val;
    assign current_val = (index == 3'd0) ? arr_0 :
                        (index == 3'd1) ? arr_1 :
                        (index == 3'd2) ? arr_2 :
                        (index == 3'd3) ? arr_3 :
                        (index == 3'd4) ? arr_4 :
                        (index == 3'd5) ? arr_5 :
                        (index == 3'd6) ? arr_6 :
                        arr_7;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            done <= 1'b0;
            result <= 16'd0;
            index <= 3'd0;
            first_even <= 8'd0;
            first_odd <= 8'd0;
            even_found <= 1'b0;
            odd_found <= 1'b0;
            processing <= 1'b0;
        end else begin
            if (start && !processing) begin
                // Start new computation
                processing <= 1'b1;
                done <= 1'b0;
                index <= 3'd0;
                first_even <= 8'd0;
                first_odd <= 8'd0;
                even_found <= 1'b0;
                odd_found <= 1'b0;
            end else if (processing) begin
                if (index < len) begin
                    // Process current element
                    if (!even_found && (current_val[0] == 1'b0)) begin
                        first_even <= current_val;
                        even_found <= 1'b1;
                    end
                    if (!odd_found && (current_val[0] == 1'b1)) begin
                        first_odd <= current_val;
                        odd_found <= 1'b1;
                    end
                    index <= index + 1'b1;
                end else begin
                    // All elements processed, compute result
                    if (even_found && odd_found) begin
                        // Calculate difference (even - odd)
                        result <= {8'd0, first_even} - {8'd0, first_odd};
                    end else if (even_found && !odd_found) begin
                        // No odd found, use -1 as per spec
                        result <= {8'd0, first_even} - 16'hFFFF;  // -1 in 16-bit
                    end else if (!even_found && odd_found) begin
                        // No even found, use -1 as per spec
                        result <= 16'hFFFF - {8'd0, first_odd};  // -1 in 16-bit
                    end else begin
                        // Neither found (shouldn't happen with len>0)
                        result <= 16'd0;
                    end
                    done <= 1'b1;
                    processing <= 1'b0;
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

endmodule

// Problem: Interleave 3 lists of the same length into a single flat list.
// Hardware Adaptation: Read 3 fixed-size arrays (max 8 elements) and output interleaved values.

module interleave_3_arrays (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [3:0] len,           // Number of valid elements (1-8)
    input wire [7:0] arr1 [0:7],    // Input array 1
    input wire [7:0] arr2 [0:7],    // Input array 2
    input wire [7:0] arr3 [0:7],    // Input array 3
    output reg [7:0] result,        // Interleaved output value
    output reg valid,               // High when result is valid
    output reg done                 // High for 1 cycle when finished
);

    reg [3:0] index;                // Current input element index (0 to len-1)
    reg [1:0] state;                // State: 0=Idle, 1=Output1, 2=Output2, 3=Output3
    reg [4:0] out_count;            // Total output count (max 24 for len=8)
    reg processing;                 // Flag indicating processing in progress

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            result <= 8'b0;
            valid <= 1'b0;
            done <= 1'b0;
            index <= 4'b0;
            state <= 2'b0;
            out_count <= 5'b0;
            processing <= 1'b0;
        end else begin
            // Default outputs
            valid <= 1'b0;
            done <= 1'b0;

            if (!processing) begin
                if (start) begin
                    // Start processing
                    processing <= 1'b1;
                    index <= 4'b0;
                    state <= 2'b01;     // Start with state 1 (Output1)
                    out_count <= 5'b0;
                end
            end else begin
                // Increment output count for every valid output
                if (state != 2'b00) begin
                    out_count <= out_count + 1'b1;
                end

                case (state)
                    2'b01: begin
                        // Output arr1[index]
                        result <= arr1[index];
                        valid <= 1'b1;
                        state <= 2'b10;     // Next: Output2
                    end
                    2'b10: begin
                        // Output arr2[index]
                        result <= arr2[index];
                        valid <= 1'b1;
                        state <= 2'b11;     // Next: Output3
                    end
                    2'b11: begin
                        // Output arr3[index]
                        result <= arr3[index];
                        valid <= 1'b1;

                        // Check if this was the last element
                        if (index == len - 1) begin
                            // Check if we just finished the very last output
                            if (out_count == (len * 3) - 1) begin
                                done <= 1'b1;
                                processing <= 1'b0;
                                state <= 2'b00;
                            end else begin
                                // Wait one cycle before done (issue done next cycle)
                                state <= 2'b00; // Idle but keep processing flag high
                            end
                        end else begin
                            index <= index + 1'b1;
                            state <= 2'b01; // Next: Output1 for next index
                        end
                    end
                    default: begin // 2'b00 - Special idle/done state
                        // This state handles the delay cycle after final element
                        if (processing) begin
                            done <= 1'b1;
                            processing <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

endmodule

module max_sub_array_sum (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire signed [7:0] arr_0,
    input wire signed [7:0] arr_1,
    input wire signed [7:0] arr_2,
    input wire signed [7:0] arr_3,
    input wire signed [7:0] arr_4,
    input wire signed [7:0] arr_5,
    input wire signed [7:0] arr_6,
    input wire signed [7:0] arr_7,
    input wire [3:0] len,
    output reg signed [15:0] result,
    output reg done
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam COMPUTE = 2'b01;
    localparam FINISH = 2'b10;

    // Internal registers
    reg [1:0] state;
    reg [3:0] index;
    reg signed [15:0] max_ending_here;
    reg signed [15:0] max_so_far;
    reg signed [7:0] current_val;

    // Combinational logic for array access
    always @(*) begin
        case(index)
            4'd0: current_val = arr_0;
            4'd1: current_val = arr_1;
            4'd2: current_val = arr_2;
            4'd3: current_val = arr_3;
            4'd4: current_val = arr_4;
            4'd5: current_val = arr_5;
            4'd6: current_val = arr_6;
            4'd7: current_val = arr_7;
            default: current_val = 8'sd0;
        endcase
    end

    // Sequential logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            state <= IDLE;
            result <= 16'sd0;
            done <= 1'b0;
            index <= 4'd0;
            max_ending_here <= 16'sd0;
            max_so_far <= 16'sd0;
        end else begin
            case(state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        state <= COMPUTE;
                        index <= 4'd0;
                        max_ending_here <= 16'sd0;
                        max_so_far <= 16'sd0;
                    end
                end

                COMPUTE: begin
                    if (index < len) begin
                        // Add current element
                        max_ending_here <= max_ending_here + {8'd0, current_val};

                        // Check if negative (reset to 0)
                        if (max_ending_here + {8'd0, current_val} < 16'sd0) begin
                            max_ending_here <= 16'sd0;
                        end

                        // Update max_so_far if needed
                        if (max_ending_here + {8'd0, current_val} > max_so_far && 
                            max_ending_here + {8'd0, current_val} > 16'sd0) begin
                            max_so_far <= max_ending_here + {8'd0, current_val};
                        end

                        index <= index + 1'b1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin
                    result <= max_so_far;
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module tuple_size_calculator (
    input wire clk,              // Clock signal
    input wire rst_n,            // Active-low synchronous reset
    input wire start,            // Start pulse (1 cycle)
    input wire [7:0] data_i,     // Input data byte
    input wire [2:0] len_i,      // Number of elements (0-7, representing 1-8)
    input wire data_valid,       // Data valid signal for loading
    output reg [15:0] size_o,    // Total size in bytes
    output reg done              // Computation complete signal
);

    // Fixed overhead: 40 bytes (simulates Python object header)
    // Per-element storage: 1 byte each (simulates data payload)
    // Total size = 40 + number_of_elements

    reg [2:0] state;
    reg [2:0] count;
    reg [7:0] data_buffer [0:7]; // 8-element buffer
    reg [2:0] element_count;     // Number of valid elements

    // State definitions
    localparam IDLE = 3'd0;
    localparam LOAD = 3'd1;
    localparam CALCULATE = 3'd2;
    localparam FINISH = 3'd3;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            size_o <= 0;
            count <= 0;
            element_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= LOAD;
                        count <= 0;
                        element_count <= 0;
                    end
                end

                LOAD: begin
                    if (data_valid && count < 3'd7) begin
                        data_buffer[count] <= data_i;
                        count <= count + 1;
                        element_count <= len_i;
                    end else if (count >= len_i) begin
                        state <= CALCULATE;
                    end

                    if (len_i == 0) begin
                        state <= CALCULATE;
                    end
                end

                CALCULATE: begin
                    // Size = 40 (header) + number_of_elements
                    size_o <= 40 + element_count;
                    state <= FINISH;
                end

                FINISH: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module min_swaps (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] str1,
    input wire [7:0] str2,
    output reg [3:0] result,
    output reg done,
    output reg possible
);

    // Internal state
    reg [2:0] state;
    reg [2:0] counter;
    reg [7:0] xor_result;
    reg [3:0] mismatch_count;

    // State definitions
    localparam IDLE = 3'b000;
    localparam CALCULATE_XOR = 3'b001;
    localparam COUNT_MISMATCHES = 3'b010;
    localparam CHECK_PARITY = 3'b011;
    localparam CALCULATE_RESULT = 3'b100;
    localparam DONE_STATE = 3'b101;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            possible <= 0;
            mismatch_count <= 0;
            counter <= 0;
            xor_result <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        state <= CALCULATE_XOR;
                        xor_result <= str1 ^ str2;
                        counter <= 0;
                        mismatch_count <= 0;
                    end
                end

                CALCULATE_XOR: begin
                    state <= COUNT_MISMATCHES;
                end

                COUNT_MISMATCHES: begin
                    if (counter < 4) begin
                        // Check 2 bits per cycle
                        if (counter < 2) begin
                            mismatch_count <= mismatch_count + xor_result[2*counter] + xor_result[2*counter+1];
                        end
                        counter <= counter + 1;
                    end else begin
                        state <= CHECK_PARITY;
                        counter <= 0;
                    end
                end

                CHECK_PARITY: begin
                    state <= CALCULATE_RESULT;
                end

                CALCULATE_RESULT: begin
                    if (mismatch_count[0] == 0) begin
                        // Even number of mismatches
                        result <= mismatch_count >> 1;
                        possible <= 1;
                    end else begin
                        // Odd number of mismatches
                        result <= 0;
                        possible <= 0;
                    end
                    state <= DONE_STATE;
                end

                DONE_STATE: begin
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

module unique_product (
    input wire clk,
    input wire rst_n,
    input wire start,
    input wire [7:0] arr_0,
    input wire [7:0] arr_1,
    input wire [7:0] arr_2,
    input wire [7:0] arr_3,
    input wire [7:0] arr_4,
    input wire [7:0] arr_5,
    input wire [7:0] arr_6,
    input wire [7:0] arr_7,
    input wire [3:0] len,
    output reg [31:0] result,
    output reg done
);

    reg [2:0] state;
    reg [2:0] i;
    reg [2:0] j;
    reg [7:0] unique_arr[7:0];
    reg [2:0] unique_count;
    reg [31:0] product;
    reg found;

    localparam IDLE = 3'b000;
    localparam CHECK = 3'b001;
    localparam VERIFY = 3'b010;
    localparam ADD = 3'b011;
    localparam CALC = 3'b100;
    localparam DONE = 3'b101;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            result <= 32'b0;
            done <= 1'b0;
            i <= 3'b0;
            j <= 3'b0;
            unique_count <= 3'b0;
            product <= 32'b1;
            found <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        i <= 3'b0;
                        unique_count <= 3'b0;
                        product <= 32'b1;
                        state <= CHECK;
                    end
                end

                CHECK: begin
                    if (i < len) begin
                        if (unique_count == 0) begin
                            state <= ADD;
                        end else begin
                            j <= 3'b0;
                            found <= 1'b0;
                            state <= VERIFY;
                        end
                    end else begin
                        state <= CALC;
                        j <= 3'b0;
                    end
                end

                VERIFY: begin
                    if (j < unique_count) begin
                        case (i)
                            3'd0: begin
                                if (unique_arr[j] == arr_0) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd1: begin
                                if (unique_arr[j] == arr_1) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd2: begin
                                if (unique_arr[j] == arr_2) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd3: begin
                                if (unique_arr[j] == arr_3) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd4: begin
                                if (unique_arr[j] == arr_4) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd5: begin
                                if (unique_arr[j] == arr_5) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd6: begin
                                if (unique_arr[j] == arr_6) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                            3'd7: begin
                                if (unique_arr[j] == arr_7) begin
                                    found <= 1'b1;
                                    state <= 3'b110;
                                end else if (j == unique_count - 1) begin
                                    state <= ADD;
                                end else begin
                                    j <= j + 1;
                                end
                            end
                        endcase
                    end else begin
                        state <= ADD;
                    end
                end

                3'b110: begin
                    i <= i + 1;
                    state <= CHECK;
                end

                ADD: begin
                    case (i)
                        3'd0: unique_arr[unique_count] <= arr_0;
                        3'd1: unique_arr[unique_count] <= arr_1;
                        3'd2: unique_arr[unique_count] <= arr_2;
                        3'd3: unique_arr[unique_count] <= arr_3;
                        3'd4: unique_arr[unique_count] <= arr_4;
                        3'd5: unique_arr[unique_count] <= arr_5;
                        3'd6: unique_arr[unique_count] <= arr_6;
                        3'd7: unique_arr[unique_count] <= arr_7;
                    endcase
                    unique_count <= unique_count + 1;
                    i <= i + 1;
                    state <= CHECK;
                end

                CALC: begin
                    if (j < unique_count) begin
                        product <= product * unique_arr[j];
                        j <= j + 1;
                    end else begin
                        result <= product;
                        state <= DONE;
                    end
                end

                DONE: begin
                    done <= 1'b1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

// Module: Union of Two Sorted Arrays with Duplicate Removal
// Function: Computes union of two 4-element arrays, outputs sorted 8-element result
// Implementation: 3-stage pipeline
//   Stage 1: Merge (12 elements from 2 arrays + padding)
//   Stage 2: Bubble sort (8 cycles)
//   Stage 3: Duplicate removal (7 cycles)
// Total latency: ~16 cycles after start

module union_arrays (
    input wire clk,           // Clock signal
    input wire rst_n,         // Active-low synchronous reset
    input wire start,         // Start pulse (assert for 1 cycle)

    // Input array A (4 elements, 8-bit each)
    input wire [7:0] arr_a_0,
    input wire [7:0] arr_a_1,
    input wire [7:0] arr_a_2,
    input wire [7:0] arr_a_3,

    // Input array B (4 elements, 8-bit each)
    input wire [7:0] arr_b_0,
    input wire [7:0] arr_b_1,
    input wire [7:0] arr_b_2,
    input wire [7:0] arr_b_3,

    // Output: Result array (8 elements, 8-bit each)
    output reg [7:0] result_0,
    output reg [7:0] result_1,
    output reg [7:0] result_2,
    output reg [7:0] result_3,
    output reg [7:0] result_4,
    output reg [7:0] result_5,
    output reg [7:0] result_6,
    output reg [7:0] result_7,

    output reg done            // Asserted high when result is valid
);

    // Parameters
    parameter STAGE_IDLE = 3'd0;
    parameter STAGE_MERGE = 3'd1;
    parameter STAGE_SORT = 3'd2;
    parameter STAGE_REMOVE_DUP = 3'd3;
    parameter STAGE_COMPLETE = 3'd4;

    // Internal state
    reg [2:0] stage;
    reg [3:0] counter;
    reg [7:0] merged [0:11];  // 12-element merged array (10 values + 2 padding)
    reg [7:0] sorted [0:7];   // 8-element sorted array
    reg [7:0] final_result [0:7];  // Final result without duplicates

    // Temporary registers for sorting
    reg [7:0] temp;
    reg [7:0] temp2;
    reg [7:0] temp3;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            // Reset state
            stage <= STAGE_IDLE;
            counter <= 4'd0;
            done <= 1'b0;
            result_0 <= 8'd0;
            result_1 <= 8'd0;
            result_2 <= 8'd0;
            result_3 <= 8'd0;
            result_4 <= 8'd0;
            result_5 <= 8'd0;
            result_6 <= 8'd0;
            result_7 <= 8'd0;
            // Initialize internal arrays
            for (i = 0; i < 12; i = i + 1) merged[i] <= 8'd255;
            for (i = 0; i < 8; i = i + 1) begin
                sorted[i] <= 8'd255;
                final_result[i] <= 8'd255;
            end
        end else begin
            case (stage)
                STAGE_IDLE: begin
                    if (start) begin
                        // Stage 1: Merge input arrays
                        // Copy array A (4 elements)
                        merged[0] <= arr_a_0;
                        merged[1] <= arr_a_1;
                        merged[2] <= arr_a_2;
                        merged[3] <= arr_a_3;
                        // Copy array B (4 elements)
                        merged[4] <= arr_b_0;
                        merged[5] <= arr_b_1;
                        merged[6] <= arr_b_2;
                        merged[7] <= arr_b_3;
                        // Pad with max values (255) for sorting
                        merged[8] <= 8'd255;
                        merged[9] <= 8'd255;
                        merged[10] <= 8'd255;
                        merged[11] <= 8'd255;

                        // Initialize sorted array
                        for (i = 0; i < 8; i = i + 1)
                            sorted[i] <= 8'd255;

                        // Copy first 8 values from merged to sorted for sorting
                        sorted[0] <= arr_a_0;
                        sorted[1] <= arr_a_1;
                        sorted[2] <= arr_a_2;
                        sorted[3] <= arr_a_3;
                        sorted[4] <= arr_b_0;
                        sorted[5] <= arr_b_1;
                        sorted[6] <= arr_b_2;
                        sorted[7] <= arr_b_3;

                        counter <= 4'd0;
                        stage <= STAGE_SORT;
                        done <= 1'b0;
                    end
                end

                STAGE_SORT: begin
                    // Odd-even transposition sort (8 cycles)
                    // Each cycle performs one pass
                    if (counter < 4'd8) begin
                        // Odd phase (for odd counters)
                        if (counter[0] == 1'b1) begin
                            for (i = 0; i < 7; i = i + 2) begin
                                if (sorted[i] > sorted[i+1]) begin
                                    temp <= sorted[i];
                                    sorted[i] <= sorted[i+1];
                                    sorted[i+1] <= temp;
                                end
                            end
                        end 
                        // Even phase (for even counters)
                        else begin
                            for (i = 1; i < 7; i = i + 2) begin
                                if (sorted[i] > sorted[i+1]) begin
                                    temp <= sorted[i];
                                    sorted[i] <= sorted[i+1];
                                    sorted[i+1] <= temp;
                                end
                            end
                        end
                        counter <= counter + 1'b1;
                    end else begin
                        // Sorting complete, move to duplicate removal
                        // Reset counter and initialize final_result
                        counter <= 4'd0;
                        for (i = 0; i < 8; i = i + 1)
                            final_result[i] <= 8'd255;
                        stage <= STAGE_REMOVE_DUP;
                    end
                end

                STAGE_REMOVE_DUP: begin
                    // Remove duplicates from sorted array
                    // Simple linear pass with index tracking
                    if (counter < 4'd8) begin
                        // First element always unique
                        if (counter == 4'd0) begin
                            final_result[0] <= sorted[0];
                            counter <= 4'd1;
                        end else begin
                            // Compare with previous non-255 value
                            temp2 <= final_result[counter - 1];
                            if (sorted[counter] != final_result[counter - 1] && sorted[counter] != 8'd255) begin
                                // Find first empty slot in final_result
                                temp3 <= sorted[counter];
                                // Shift existing values if needed (simplified)
                                final_result[counter] <= sorted[counter];
                            end else if (sorted[counter] == final_result[counter - 1]) begin
                                // Skip duplicate, shift remaining
                                final_result[counter] <= 8'd255;
                            end
                            counter <= counter + 1'b1;
                        end
                    end else begin
                        // Compact the array (remove 255 gaps)
                        // Simple bubble-based compaction
                        for (i = 0; i < 7; i = i + 1) begin
                            if (final_result[i] == 8'd255 && final_result[i+1] != 8'd255) begin
                                final_result[i] <= final_result[i+1];
                                final_result[i+1] <= 8'd255;
                            end
                        end
                        // Final assignment to outputs
                        result_0 <= final_result[0];
                        result_1 <= final_result[1];
                        result_2 <= final_result[2];
                        result_3 <= final_result[3];
                        result_4 <= final_result[4];
                        result_5 <= final_result[5];
                        result_6 <= final_result[6];
                        result_7 <= final_result[7];
                        stage <= STAGE_COMPLETE;
                        done <= 1'b1;
                    end
                end

                STAGE_COMPLETE: begin
                    // Wait for start to go low
                    if (!start) begin
                        done <= 1'b0;
                        stage <= STAGE_IDLE;
                    end
                end

                default: begin
                    stage <= STAGE_IDLE;
                    done <= 1'b0;
                end
            endcase
        end
    end

endmodule

module is_sorted_check (
    input clk,
    input rst_n,
    input start,
    input [7:0] arr_0,
    input [7:0] arr_1,
    input [7:0] arr_2,
    input [7:0] arr_3,
    input [7:0] arr_4,
    input [7:0] arr_5,
    input [7:0] arr_6,
    input [7:0] arr_7,
    input [3:0] len,          // Number of valid elements (1-8)
    output reg result,        // 1 if sorted, 0 if not
    output reg done           // Pulse high when computation complete
);

    // State machine states
    reg [2:0] state;
    reg [3:0] idx;
    reg sorted_reg;

    localparam IDLE = 3'b000;
    localparam CHECK = 3'b001;
    localparam DONE = 3'b010;

    // Array to store inputs (for sequential access)
    reg [7:0] arr_reg [0:7];
    reg [3:0] len_reg;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            done <= 0;
            result <= 0;
            idx <= 0;
            sorted_reg <= 1;
            len_reg <= 0;
            // Clear array
            for (i = 0; i < 8; i = i + 1) begin
                arr_reg[i] <= 8'b0;
            end
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start && len > 1) begin
                        // Capture inputs
                        arr_reg[0] <= arr_0;
                        arr_reg[1] <= arr_1;
                        arr_reg[2] <= arr_2;
                        arr_reg[3] <= arr_3;
                        arr_reg[4] <= arr_4;
                        arr_reg[5] <= arr_5;
                        arr_reg[6] <= arr_6;
                        arr_reg[7] <= arr_7;
                        len_reg <= len;
                        idx <= 1;  // Start from second element
                        sorted_reg <= 1;
                        state <= CHECK;
                    end else if (start && len <= 1) begin
                        // Single element or empty is trivially sorted
                        result <= 1;
                        done <= 1;
                        state <= DONE;
                    end
                end

                CHECK: begin
                    // Compare arr_reg[idx-1] with arr_reg[idx]
                    if (arr_reg[idx-1] > arr_reg[idx]) begin
                        sorted_reg <= 0;
                        // Early termination - continue to process remaining for timing consistency
                    end

                    if (idx == len_reg - 1) begin
                        // Last comparison done
                        result <= sorted_reg;
                        done <= 1;
                        state <= DONE;
                    end else begin
                        idx <= idx + 1;
                    end
                end

                DONE: begin
                    done <= 0;  // Pulse done for one cycle
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule
